// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.374 (Ivan, 16.05.2026): SENTRY ERROR TRACKING
// ═══════════════════════════════════════════════════════════════════════════
//   Hvata sve neuhvaćene greške + uncaughtException + unhandledRejection +
//   svaku grešku u Express route handlerima. UptimeRobot pokriva "je li server
//   živ" (vanjski health check), a Sentry pokriva "je li unutar servera nešto
//   pucnulo" (TypeError, failed query, itd.).
//   
//   KRITIČNO: Sentry.init MORA biti POZVAN PRIJE BILO KOJEG drugog require-a
//   (osim dotenv). Inače auto-instrumentation neće raditi.
//   
//   Konfiguracija:
//   - SENTRY_DSN env var (postaviti u Railway) — bez DSN-a, Sentry je no-op
//   - tracesSampleRate 0.05: 5% requestova ide u performance tracing
//     (Free tier: 100k errors/mjesec + 10k transactions/mjesec — više nego dovoljno)
//   - environment: production / development (auto-detect kroz NODE_ENV)
//   - release: čitamo iz CACHE_VERSION-a (jednom kada CI/CD push-a build)
let _Sentry = null;
if (process.env.SENTRY_DSN) {
  try {
    _Sentry = require('@sentry/node');
    _Sentry.init({
      dsn: process.env.SENTRY_DSN,
      environment: process.env.NODE_ENV || 'production',
      release: 'v135.7.502.18',
      tracesSampleRate: 0.05,  // 5% requestova
      // Ne šaljemo PII (ime, prezime radnika, OIB) — ostane samo error tip i stack
      sendDefaultPii: false,
      // beforeSend: filter koji štiti od slanja senzitivnih podataka
      beforeSend(event, hint) {
        // Ukloni request body iz svih eventova (može sadržavati PII)
        if (event.request && event.request.data) {
          event.request.data = '[REDACTED]';
        }
        // Ukloni Authorization header ako je nekako uspio doći do tu
        if (event.request && event.request.headers) {
          delete event.request.headers.authorization;
          delete event.request.headers.cookie;
        }
        return event;
      },
      // Ignoriraj uobičajene "benign" greške (česti spam u logu)
      ignoreErrors: [
        // Network errors koji ne znače stvarno pucanje
        'ECONNRESET',
        'ETIMEDOUT',
        'EPIPE',
        // Klijent abortao request (ne naša greška)
        'AbortError',
        'Request aborted',
        // Stari browser bug (Safari)
        'ResizeObserver loop limit exceeded'
      ]
    });
    console.log(`[Sentry] inicijaliziran — env: ${process.env.NODE_ENV || 'production'}, sample rate: 5%`);
  } catch(e) {
    console.warn(`[Sentry] init fail (paket nije instaliran ili kriv DSN): ${e.message}`);
    _Sentry = null;
  }
} else {
  console.log('[Sentry] DSN nije postavljen — error tracking je OFF (postavi SENTRY_DSN env var u Railway)');
}

// Helper koji sigurno hvata grešku (no-op ako Sentry nije inicijaliziran)
function _sentryCapture(err, context) {
  if (!_Sentry) return;
  try {
    if (context) {
      _Sentry.withScope(scope => {
        scope.setContext('zbuka_context', context);
        _Sentry.captureException(err);
      });
    } else {
      _Sentry.captureException(err);
    }
  } catch(_) { /* ne želimo da Sentry sam pucne */ }
}

