// ── PUSH NOTIFICATIONS ────────────────────────────────────────────────────
// Native push — koristi samo Node.js ugrađene module
async function nativeSendPush(subJson, payload) {
  const crypto = require('crypto');
  const https = require('https');
  const { URL } = require('url');

  const sub = typeof subJson === 'string' ? JSON.parse(subJson) : subJson;
  const endpoint = sub.endpoint;
  const parsedUrl = new URL(endpoint);
  const audience = `${parsedUrl.protocol}//${parsedUrl.host}`;

  const vapidPrivKeyB64 = process.env.VAPID_PRIVATE_KEY;
  const vapidPubKeyB64 = process.env.VAPID_PUBLIC_KEY;
  const subject = process.env.VAPID_SUBJECT || 'mailto:admin@zbuka.hr';

  // Konvertira base64url VAPID private key (32 bytes raw) u JWK pa u KeyObject
  const privRaw = Buffer.from(vapidPrivKeyB64.replace(/-/g,'+').replace(/_/g,'/'), 'base64');
  const pubRaw  = Buffer.from(vapidPubKeyB64.replace(/-/g,'+').replace(/_/g,'/'), 'base64');

  // Javni ključ mora biti uncompressed (04 prefix + 64 bytes)
  const pubUncompressed = pubRaw.length === 65 ? pubRaw : Buffer.concat([Buffer.from([0x04]), pubRaw]);

  const privKeyObj = crypto.createPrivateKey({
    key: {
      kty: 'EC',
      crv: 'P-256',
      d: privRaw.toString('base64url'),
      x: pubUncompressed.slice(1, 33).toString('base64url'),
      y: pubUncompressed.slice(33, 65).toString('base64url'),
    },
    format: 'jwk'
  });

  // VAPID JWT
  const headerB64 = Buffer.from(JSON.stringify({typ:'JWT',alg:'ES256'})).toString('base64url');
  const now = Math.floor(Date.now()/1000);
  const claimsB64 = Buffer.from(JSON.stringify({ aud: audience, exp: now + 43200, sub: subject })).toString('base64url');
  const sigInput = `${headerB64}.${claimsB64}`;
  const sig = crypto.sign(null, Buffer.from(sigInput), { key: privKeyObj, dsaEncoding: 'ieee-p1363' });
  const jwt = `${sigInput}.${sig.toString('base64url')}`;

  const authHeader = `vapid t=${jwt},k=${vapidPubKeyB64}`;
  const payloadBuf = Buffer.from(JSON.stringify(payload));

  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: parsedUrl.hostname,
      port: 443,
      path: parsedUrl.pathname + (parsedUrl.search || ''),
      method: 'POST',
      headers: {
        'Authorization': authHeader,
        'Content-Type': 'application/json',
        'Content-Length': payloadBuf.length,
        'TTL': '86400',
        // ⭐ v971 (Ivan: „notifikacija dođe za sat vremena“): BEZ OZNAKE HITNOSTI Android skuplja
        //   obavijesti u batch i isporuči ih kad se uređaj sam probudi — zna biti i sat kasnije.
        //   Urgency: high traži trenutnu isporuku i budi uređaj. Topic: ista tema pregazi prethodnu
        //   neisporučenu poruku, pa se ne gomilaju tri obavijesti o istoj procjeni.
        'Urgency': 'high',
        'Topic': 'zbuka'
      }
    }, res => {
      let body = '';
      res.on('data', d => body += d);
      res.on('end', () => {
        if (res.statusCode === 201 || res.statusCode === 200 || res.statusCode === 202) {
          resolve(res.statusCode);
        } else {
          reject(Object.assign(new Error(`Push failed: ${body}`), { statusCode: res.statusCode }));
        }
      });
    });
    req.on('error', reject);
    req.write(payloadBuf);
    req.end();
  });
}

// Pošalji push notifikaciju svim uređajima (osim pošiljatelja)
async function sendPush(senderUserId, title, body, url, kategorija) {
  const vapidOk = !!(process.env.VAPID_PUBLIC_KEY && process.env.VAPID_PRIVATE_KEY);
  if (!webpush && !vapidOk) return;
  try {
    // ⭐ v135.7.32 (#6): Dodatno filtriraj NULL radnik_id (legacy subscription bez user-a)
    //    OPREZNO: senderUserId = 0 znači sistemski push (svi dobivaju, uključujući legacy NULL)
    //    senderUserId > 0 znači user akcija → isključi sebe + isključi NULL
    const isSystemPush = senderUserId === 0;
    // ⭐ v446 (Ivan): per-tab filter. kategorija zadana → šalji SAMO korisnicima koji NISU isključili
    //   tu kategoriju (notif_prefs->>kategorija != 'false'). NULL prefs ili kategorija nezadana →
    //   default šalji (backward-compat). Autor je već isključen kroz radnik_id != $1.
    let sql, params;
    if (kategorija) {
      const katCond = `COALESCE((r.notif_prefs ->> $${isSystemPush ? 1 : 2})::boolean, true) = true`;
      sql = isSystemPush
        ? `SELECT ps.* FROM push_subscriptions ps JOIN radnici r ON r.id = ps.radnik_id WHERE ${katCond}`
        : `SELECT ps.* FROM push_subscriptions ps JOIN radnici r ON r.id = ps.radnik_id WHERE ps.radnik_id IS NOT NULL AND ps.radnik_id != $1 AND ${katCond}`;
      params = isSystemPush ? [kategorija] : [senderUserId, kategorija];
    } else {
      sql = isSystemPush
        ? `SELECT * FROM push_subscriptions`
        : `SELECT * FROM push_subscriptions WHERE radnik_id IS NOT NULL AND radnik_id != $1`;
      params = isSystemPush ? [] : [senderUserId];
    }
    const subs = await pool.query(sql, params);
    
    console.log(`[sendPush] sender=${senderUserId} → šaljem ${subs.rows.length} subscription-a (filter NULL radnik_id excluded)`);
    
    const payload = { title, body, url: url || '/', ts: Date.now() };   // ⚠ v1075-rev: fn nema tip param (eslint) — broadcast = 'zb-opce'   // ⭐ v1054: `ts` = vrijeme slanja, da `[push-prijem]` mjeri server→uredjaj
    for (const sub of subs.rows) {
      try {
        // ⭐ v135.7.215: Defensive JSON.parse — corrupted DB row ne smije srušiti push loop
        let subData;
        try {
          subData = JSON.parse(sub.subscription);
        } catch (parseErr) {
          console.warn(`[sendPush] korumpiran JSON za subscription ${sub.id}, brišem`);
          await pool.query('DELETE FROM push_subscriptions WHERE id=$1', [sub.id]).catch(() => {});
          continue;
        }
        if (webpush) {
          await webpush.sendNotification(subData, JSON.stringify(payload), _pushOpcije(subData && subData.endpoint, payload && payload.tip));   // ⭐ v989: bez opcija = urgency normal = Doze batch
        } else {
          await nativeSendPush(sub.subscription, payload);
        }
      } catch(e) {
        if (e.statusCode === 410 || e.statusCode === 404) {
          await pool.query('DELETE FROM push_subscriptions WHERE id=$1', [sub.id]).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
        } else {
          console.error('Push send error:', e.message, 'status:', e.statusCode);
        }
      }
    }
  } catch(e) { console.error('sendPush error:', e.message); }
}

