    for (const c of cj) { const k = _k(c.naziv, c.dobavljac); if (!cjMap.has(k)) cjMap.set(k, []); cjMap.get(k).push(c); }
    const dupli = [...cjMap.entries()].filter(([, v]) => v.length > 1).map(([k, v]) => ({ kljuc: k, ids: v.map(x => x.id) }));
    const bezJed = cj.filter(c => !String(c.jedinica || '').trim()).map(c => ({ id: c.id, naziv: c.naziv, dobavljac: c.dobavljac }));
    const bezCijene = cj.filter(c => !(parseFloat(c.cijena) > 0)).map(c => ({ id: c.id, naziv: c.naziv, dobavljac: c.dobavljac }));
    const mats = (await pool.query("SELECT m.id, m.datum, m.naziv, m.dobavljac, m.jedinica, m.kolicina, m.cjenik_id, g.naziv AS gradiliste FROM materijal m LEFT JOIN gradilista g ON g.id=m.gradiliste_id ORDER BY m.datum DESC LIMIT 20000")).rows;
    const bezCjenika = [], krivaJed = [];
