    try { const c = await pool.query('SELECT COUNT(*) c FROM materijal_embed WHERE embedding IS NOT NULL'); t('semantika materijal', parseInt(c.rows[0].c) > 0, c.rows[0].c + ' dostava'); } catch (e) { t('semantika materijal', false, 'tablica nedostaje - init-db'); }
