// ⭐ v135.7.106 (Ivan): FFMPEG.WASM proxy — same-origin serviranje s memory cache-om
//   Razlog: Chrome ne dopušta Worker iz cross-origin URL-a. UMD verzija ffmpeg.js interno
//   kreira Worker iz `814.ffmpeg.js` (cross-origin URL ako se učita s unpkg/jsdelivr).
//   Rješenje: proxy-iramo sve ffmpeg fileove kroz naš server → same-origin → Chrome dopušta.
//   
//   Cache: prvi zahtjev fetcha s CDN-a, posli zahtjevi se serviraju iz memory cache-a (30 dana).
//   Browser cache (Cache-Control immutable, 30 dana) — klijenti ne traže ponovo.
//   Memory utjecaj: ~32 MB peak (ffmpeg-core.wasm ~31MB + ostali ~1MB ukupno).
//
// FUTURE-PROOF-2030: [FFMPEG-PROXY] Proxy s in-memory cache za ffmpeg.wasm
//   PROVJERI: pinjajne verzije: ffmpeg=0.12.10, core=0.12.6, util=0.12.1.
//             Provjeri novije verzije na https://www.npmjs.com/package/@ffmpeg/ffmpeg.
//             Sigurno: drži se single-threaded buildova (bez SharedArrayBuffer).
//   FIX: ako CDN-ovi (unpkg + jsdelivr) padnu trajno, download fileove i hostaj iz repo-a:
//        wget -P /public/ffmpeg/ https://unpkg.com/@ffmpeg/[email protected]/dist/umd/ffmpeg-core.wasm
//        + ostali fileovi.
//   LAST_VERIFIED: 2026-05-03
const _ffmpegFileCache = new Map();  // filename → { body, contentType, time }
const FFMPEG_CACHE_TTL = 30 * 24 * 60 * 60 * 1000;  // 30 dana

const FFMPEG_PROXY_VERSIONS = {
  ffmpeg: '0.12.10',
  core: '0.12.6',
  util: '0.12.1'
};

// Mapira request filename na CDN URL-ove (s fallback)
function _resolveFFmpegCdnUrls(fname) {
  if (fname === 'util.js' || fname === 'util/index.js') {
    // @ffmpeg/util UMD (postavlja window.FFmpegUtil)
    return [
      `https://unpkg.com/@ffmpeg/util@${FFMPEG_PROXY_VERSIONS.util}/dist/umd/index.js`,
      `https://cdn.jsdelivr.net/npm/@ffmpeg/util@${FFMPEG_PROXY_VERSIONS.util}/dist/umd/index.js`,
    ];
  }
  if (fname.startsWith('ffmpeg-core')) {
    // ⭐ v135.7.107.1 (Ivan): ESM verzija za core (ne UMD)!
    //   Razlog: ff.load() interno radi `import('blob:...')` (ESM dynamic import).
    //   UMD core daje "Failed to fetch dynamically imported module" jer UMD nije ESM modul.
    //   ESM core (dist/esm/) je pravi ES Module → Worker import() radi.
    return [
      `https://unpkg.com/@ffmpeg/core@${FFMPEG_PROXY_VERSIONS.core}/dist/esm/${fname}`,
      `https://cdn.jsdelivr.net/npm/@ffmpeg/core@${FFMPEG_PROXY_VERSIONS.core}/dist/esm/${fname}`,
    ];
  }
  // Sve ostalo: @ffmpeg/ffmpeg UMD (ffmpeg.js, 814.ffmpeg.js — UMD je OK za script tag load)
  return [
    `https://unpkg.com/@ffmpeg/ffmpeg@${FFMPEG_PROXY_VERSIONS.ffmpeg}/dist/umd/${fname}`,
    `https://cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@${FFMPEG_PROXY_VERSIONS.ffmpeg}/dist/umd/${fname}`,
  ];
}

app.get('/ffmpeg/:filename', async (req, res) => {
  const fname = req.params.filename;
  // Whitelist sigurnosna provjera (allow .js, .wasm, .map fileove bez specijalnih znakova)
  if (!/^[a-zA-Z0-9._-]+\.(js|wasm|map)$/.test(fname)) {
    return res.status(400).json({ error: 'Nedozvoljeno ime filea' });
  }
  
  // ⭐ v135.7.107: __diag endpoint za dijagnostiku
  if (fname === '__diag.js') {
    const diagInfo = {
      proxy: 'OK',
      cached_files: Array.from(_ffmpegFileCache.keys()),
      cache_size_kb: Array.from(_ffmpegFileCache.values()).reduce((s, c) => s + (c.body?.length || 0), 0) / 1024 | 0,
      versions: FFMPEG_PROXY_VERSIONS,
      // ⭐ v135.7.107b: pokazi što vraća za core (head bytes)
      core_sample: (() => {
        const c = _ffmpegFileCache.get('ffmpeg-core.js');
        if (!c) return 'not_cached';
        const head = c.body.slice(0, 80).toString('utf-8').replace(/\n/g, ' ');
        return head;
      })(),
      core_size_kb: (() => {
        const c = _ffmpegFileCache.get('ffmpeg-core.js');
        return c ? (c.body.length / 1024) | 0 : 0;
      })(),
      time: new Date().toISOString()
    };
    res.set('Content-Type', 'application/json');
    return res.json(diagInfo);
  }
  
  // ⭐ v135.7.107b: Cache key uključuje verziju ffmpeg-core (sprečava stale UMD u cache-u
  //   ako se promijeni source path — npr. UMD → ESM).
  const cacheKey = `${fname}@${FFMPEG_PROXY_VERSIONS.core}_${FFMPEG_PROXY_VERSIONS.ffmpeg}`;
  
  // Memory cache hit?
  const cached = _ffmpegFileCache.get(cacheKey);
  if (cached && Date.now() - cached.time < FFMPEG_CACHE_TTL) {
    res.set('Content-Type', cached.contentType);
    res.set('Cache-Control', 'public, max-age=2592000, immutable'); // 30 dana browser cache
    res.set('Cross-Origin-Resource-Policy', 'same-origin');
    res.set('X-FFmpeg-Cache', 'HIT');
    return res.send(cached.body);
  }
  
  // Cache miss — fetch s CDN s fallback
  const cdnUrls = _resolveFFmpegCdnUrls(fname);
  
  for (const cdnUrl of cdnUrls) {
    try {
      const upstream = await fetch(cdnUrl, { 
        // Timeout 25s (Railway timeout je 30s pa moramo brzo)
        signal: AbortSignal.timeout(25000) 
      });
      if (!upstream.ok) {
        console.warn(`[ffmpeg-proxy] ${cdnUrl} → HTTP ${upstream.status}`);
        continue;
      }
      
      const buf = await upstream.arrayBuffer();
      const body = Buffer.from(buf);
      
      // ⭐ v135.7.107: Validacija response sadržaja
      if (body.length < 100) {
        console.warn(`[ffmpeg-proxy] ${cdnUrl} response premalen (${body.length}B), skip`);
        continue;
      }
      
      if (fname.endsWith('.wasm')) {
        // WASM magic bytes: 0x00 0x61 0x73 0x6d (\0asm)
        if (body[0] !== 0x00 || body[1] !== 0x61 || body[2] !== 0x73 || body[3] !== 0x6D) {
          console.warn(`[ffmpeg-proxy] ${cdnUrl} nije valjan WASM (bad magic bytes), skip`);
          continue;
        }
      } else if (fname.endsWith('.js')) {
        // JS ne smije početi s '<' (HTML error page)
        const firstChar = body[0];
        if (firstChar === 0x3C) { // '<'
          console.warn(`[ffmpeg-proxy] ${cdnUrl} izgleda kao HTML, ne JS, skip`);
          continue;
        }
      }
      
      const contentType = fname.endsWith('.wasm') ? 'application/wasm' : 
                          fname.endsWith('.js') ? 'text/javascript; charset=utf-8' : 
                          'application/octet-stream';
      
      // Cache u memoriji — koristi cacheKey s verzijom
      _ffmpegFileCache.set(cacheKey, { body, contentType, time: Date.now() });
      console.log(`[ffmpeg-proxy] cached ${cacheKey} (${(body.length/1024).toFixed(1)} KB) from ${cdnUrl.split('/')[2]}`);
      
      res.set('Content-Type', contentType);
      res.set('Cache-Control', 'public, max-age=2592000, immutable'); // 30 dana browser cache
      res.set('Cross-Origin-Resource-Policy', 'same-origin');
      res.set('X-FFmpeg-Cache', 'MISS');
      res.set('X-FFmpeg-Source', cdnUrl.split('/')[2]);
      return res.send(body);
    } catch(e) {
      console.warn(`[ffmpeg-proxy] ${cdnUrl} fail:`, e.message);
    }
  }
  
  // Svi CDN-ovi pali
  console.error(`[ffmpeg-proxy] svi CDN-ovi pali za ${fname}`);
  res.status(502).json({ error: `FFmpeg file '${fname}' nije dostupan ni s jednog CDN-a (probao: ${cdnUrls.length}). Pokušaj kasnije ili provjeri Railway egress.` });
});

