// ⭐ v135.7.57 (Ivan #5): EXCEL STREAMING + KOMPRESIJA helper
//    PRIJE: writeBuffer() → Buffer.from(buf) (kopija) → res.send() (još jedna kopija u TCP)
//    SAD:   ako klijent prihvaća gzip + Excel > 100 KB, kompresira (10-20% originalne veličine)
//           inače šalje direktno (manje overhead-a za male Excel-e)
//    REZULTAT: 5-10x manje bandwidth-a za velike Excele (knjiga, plaće)
const _zlib = require('zlib');
function sendExcelResponse(req, res, buffer, fname) {
  // RFC 5987 ASCII fallback + UTF-8
  const fnameAscii = (typeof safeAsciiFilename === 'function')
    ? safeAsciiFilename(fname)
    : fname.replace(/[^\x00-\x7F]/g, '_');
  const buf = Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer);
  
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', `attachment; filename="${fnameAscii}"; filename*=UTF-8''${encodeURIComponent(fname)}`);
  
  // Gzip samo ako klijent prihvaća + buffer > 100KB (manje od toga overhead nije isplativ)
  const acceptEncoding = (req?.headers?.['accept-encoding'] || '').toLowerCase();
  const supportsGzip = acceptEncoding.includes('gzip');
  const veliki = buf.length > 100 * 1024;
  
  if (supportsGzip && veliki) {
    _zlib.gzip(buf, { level: 6 }, (err, gz) => {
      if (err) {
        console.warn('[Excel gzip] fail, fallback na raw:', err.message);
        res.send(buf);
      } else {
        res.setHeader('Content-Encoding', 'gzip');
        res.setHeader('Content-Length', gz.length);
        const ratio = ((1 - gz.length / buf.length) * 100).toFixed(0);
        if (ratio > 50) console.log(`[Excel gzip] ${fname}: ${(buf.length/1024).toFixed(0)}KB → ${(gz.length/1024).toFixed(0)}KB (${ratio}% saved)`);
        res.send(gz);
      }
    });
  } else {
    res.send(buf);
  }
}

