// ── MIDDLEWARE ────────────────────────────────────────────────────────────────

// ═══ NAV[BE]: AUTH MIDDLEWARE (auth/direktor/staff/admin)  ⚠️ TENANT HOOK za SaaS ═══
// FUTURE-PROOF-2030: [AUTH-MW] Authentication middleware (auth, direktor, staff, admin)
//   PROVJERI: role-based access — Memsur (je_admin=true) ne smije pristupati 'direktor' rutama
//   FIX: ako role hierarchy promijeniš (npr. dodaš 'voditelj'), update SVAKU middleware funkciju
//   POTENTIAL ISSUE: token iz query stringa (?_t=...) je security trade-off za <img> tagove
//                    — XSS koji ukrade URL = ukrade token. Razmotri short-lived signed URLs umjesto.
//   LAST_VERIFIED: 2026-05-01
// ⭐ v135.7.502.20.211 (Ivan, 08.06.2026): read-only korisnik smije SAMO: AI chat (+ push pretplatu). Sve ostale
//   mutacije (POST/PUT/DELETE/PATCH) blokirane uz jasnu poruku. Direktor je uvijek iznimka.
function _readOnlyAllowed(path) {
  return /^\/api\/asistent\/chat/.test(path) || /^\/api\/push\//.test(path);
}
// ⭐ v135.7.502.20.219 (Ivan, 08.06.2026): MEDIA TOKEN (P0-3 / S-1 iz audita).
//   Prije: pun 7-dnevni JWT je tekao kroz ?_t=/?token= (za <img src>, <video>, otvaranje u tabu) → završavao u
//   server-logovima/povijesti/proxyju → curenje = pun pristup računu. Sada kroz URL teče SAMO kratkoživući
//   (24h), READ-ONLY, GET-only HMAC media token (potpisan JWT_SECRET-om, domain-separation 'media:'). Čak i ako
//   procuri: ne može mutirati ni pristupiti ne-media API-ju, i istječe za 24h. Klijent ga dobiva preko
//   X-Media-Token response headera (svježi na svaki autenticirani poziv) i /api/media-token. JWT u URL-u VIŠE
//   NE PROLAZI (verify kao media token padne → 401).
const MEDIA_TTL_MS = 24 * 60 * 60 * 1000;
function _signMediaToken(userId) {
  const exp = Date.now() + MEDIA_TTL_MS;
  const payload = `${userId}.${exp}`;
  const sig = crypto.createHmac('sha256', JWT_SECRET).update('media:' + payload).digest('base64url');
  return `${payload}.${sig}`;
}
function _verifyMediaToken(mt) {
  if (!mt || typeof mt !== 'string') return null;
  const parts = mt.split('.');
  if (parts.length !== 3) return null;
  const [uid, exp, sig] = parts;
  const expected = crypto.createHmac('sha256', JWT_SECRET).update('media:' + uid + '.' + exp).digest('base64url');
  let ok = false;
  try { ok = crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected)); } catch (_) { return null; }
  if (!ok) return null;
  if (!(parseInt(exp, 10) > Date.now())) return null;       // istekao
  const id = parseInt(uid, 10);
  return Number.isFinite(id) ? id : null;
}
async function _userFromMediaToken(mt) {
  const id = _verifyMediaToken(mt);
  if (!id) return null;
  try {
    const r = await pool.query('SELECT id, ime, prezime, je_admin, role, aktivan FROM radnici WHERE id=$1', [id]);
    if (!r.rows.length || r.rows[0].aktivan === false) return null;
    return r.rows[0];
  } catch (_) { return null; }
}

// ⭐ v135.7.502.20.434 (Ivan): NADZOR share-link token — stateless HMAC (domain-separation 'nadzor:'), 90 dana.
//   Enkodira gradiliste_id + raspon datuma. Javni link za nadzorne inženjere (online premium pregled dnevnika
//   umjesto slanja 100MB PDF-a). READ-ONLY, samo dnevnik tog gradilišta/razdoblja. Bez DB tablice (stateless).
const NADZOR_TTL_MS = 90 * 24 * 60 * 60 * 1000;
function _signNadzorToken(gradilisteId, od, doo) {
  const exp = Date.now() + NADZOR_TTL_MS;
  const payload = `${gradilisteId}|${od || ''}|${doo || ''}|${exp}`;
  const sig = crypto.createHmac('sha256', JWT_SECRET).update('nadzor:' + payload).digest('base64url');
  return `${Buffer.from(payload).toString('base64url')}.${sig}`;
}
function _verifyNadzorToken(tok) {
  if (!tok || typeof tok !== 'string' || tok.length > 400) return null;
  const i = tok.lastIndexOf('.');
  if (i <= 0) return null;
  let payload;
  try { payload = Buffer.from(tok.slice(0, i), 'base64url').toString('utf8'); } catch (_) { return null; }
  const sig = tok.slice(i + 1);
  const expected = crypto.createHmac('sha256', JWT_SECRET).update('nadzor:' + payload).digest('base64url');
  try { if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return null; } catch (_) { return null; }
  const parts = payload.split('|');
  if (parts.length !== 4) return null;
  const [gid, od, doo, exp] = parts;
  if (!(parseInt(exp, 10) > Date.now())) return null;
  const gradilisteId = parseInt(gid, 10);
  if (!Number.isFinite(gradilisteId)) return null;
  return { gradilisteId, od: od || null, doo: doo || null, exp: parseInt(exp, 10) };
}

// ⭐ v457 (Ivan): JAVNI live link za RADNI NALOG (slike + opis), premium pregled za nadzor.
//   Token namespace 'nalog:' (odvojen od 'nadzor:'). Payload = nalogId|exp. Backstop expiry 1 god;
//   PRIMARNI rok valjanosti = nalog.rijesen=false (provjerava se u /rn/:token ruti). Kad netko stisne
//   "Riješi" → stranica pokaže lijepu "Završeno ✓" verziju (link i dalje radi, ali kao arhiva).
const NALOG_TTL_MS = 365 * 24 * 60 * 60 * 1000;
function _signNalogToken(nalogId) {
  const exp = Date.now() + NALOG_TTL_MS;
  const payload = `${nalogId}|${exp}`;
  const sig = crypto.createHmac('sha256', JWT_SECRET).update('nalog:' + payload).digest('base64url');
  return `${Buffer.from(payload).toString('base64url')}.${sig}`;
}
function _verifyNalogToken(tok) {
  if (!tok || typeof tok !== 'string' || tok.length > 400) return null;
  const i = tok.lastIndexOf('.');
  if (i <= 0) return null;
  let payload;
  try { payload = Buffer.from(tok.slice(0, i), 'base64url').toString('utf8'); } catch (_) { return null; }
  const sig = tok.slice(i + 1);
  const expected = crypto.createHmac('sha256', JWT_SECRET).update('nalog:' + payload).digest('base64url');
  try { if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return null; } catch (_) { return null; }
  const parts = payload.split('|');
  if (parts.length !== 2) return null;
  const [nid, exp] = parts;
  if (!(parseInt(exp, 10) > Date.now())) return null;
  const nalogId = parseInt(nid, 10);
  if (!Number.isFinite(nalogId)) return null;
  return { nalogId, exp: parseInt(exp, 10) };
}

const auth = (req, res, next) => {
  const hdr = req.headers['authorization']?.split(' ')[1] || null;
  if (hdr) {
    jwt.verify(hdr, JWT_SECRET, async (err, user) => {
      if (err) {
        // ⭐ v444 (Ivan): istekli/nevažeći token = AUTENTIKACIJSKA greška → 401 (ne 403).
        //   api() helper radi refresh SAMO na 401; 403 NE odjavljuje. Prije: nakon 7d istekao
        //   access token → auth vraća 403 → refresh se ne okida → korisnik zaglavi "Nemate dozvolu".
        //   Sad: 401 → api() proba refresh (valjan RT → tihi novi token; istekao RT → čista odjava).
        //   NE dira permission-403 iz _gateByPath (Memsur na direktor-rutama i dalje 403, bez odjave).
        return res.status(401).json({ error: err.name === 'TokenExpiredError' ? 'Token istekao' : 'Nevažeći token' });
      }
      req.user = user;
      try { res.setHeader('X-Media-Token', _signMediaToken(user.id)); } catch (_) {}  // svježi media token klijentu
      // ⭐ READ-ONLY guard: "samo pregled" korisnik ne smije mutirati (osim AI chata). Fail-open na grešci (dostupnost).
      const mut = (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE' || req.method === 'PATCH');
      if (mut && user.role !== 'direktor' && !_readOnlyAllowed(req.path)) {
        try {
          const info = await _loadOvlasti(user.id);
          if (info && info.samoPregled) {
            return res.status(403).json({ error: 'READONLY', poruka: 'Tvoj račun je samo za pregled — nemaš dozvolu od administratora za unos.' });
          }
        } catch (e) { console.warn('[readonly guard]', e && e.message); }
      }
      return next();
    });
    return;
  }
  // Bez Authorization headera: dozvoli SAMO media token u query stringu i SAMO za GET (slike/stream/download/export/preview).
  if (req.method === 'GET') {
    const mt = req.query.mt || req.query._t || req.query.token || null;
    if (mt) {
      _userFromMediaToken(mt).then((u) => {
        if (!u) return res.status(403).json({ error: 'Nevažeći token' });
        req.user = u;
        return next();   // GET media → read-only guard nije primjenjiv (nema mutacije)
      }).catch(() => res.status(403).json({ error: 'Nevažeći token' }));
      return;
    }
  }
  return res.status(401).json({ error: 'Nije prijavljen' });
};

// GET /api/media-token — klijent dohvati svježi media token (header-auth). Koristi se za <img>/<video>/download URL-ove.
app.get('/api/media-token', auth, (req, res) => {
  res.json({ mt: _signMediaToken(req.user.id), ttl_ms: MEDIA_TTL_MS });
});


// ⭐ v135.7.502.20.184 (Ivan, 07.06.2026): GRANULARNE OVLASTI — Faza 1 (backend gating).
//   admin/direktor sada dijele permission-aware logiku _gateByPath:
//     1) direktor = SUPER-ADMIN → zaobilazi sve;
//     2) inače: putanja → modul (_modulZaPath) → hasPerm (ovlasti iz baze, cache 30s);
//     3) bez poklapanja modula = SAMO-DIREKTOR (deny) → nepoznate/sistemske rute ostaju direktorske.
//   Posljedica: Memsur ostaje IDENTIČAN (financije ostaju 403; operativni admin-tabovi koje već ima
//   ostaju dostupni; sistemske/config/maintenance rute ostaju samo-direktor). Nijedna ruta nije dirana —
//   mijenja se samo značenje ova dva middlewarea + mapa putanja niže.
// ⭐ v723 (Ivan): granularni gate za pojedine rute — direktor ILI eksplicitna ovlast (zamjena za binarni 'direktor')
const permGate = (key) => async (req, res, next) => {
  if (!req.user) return res.status(401).json({ error: 'Nije prijavljen' });
  if (req.user.role === 'direktor') return next();
  try {
    const { role, ovlasti } = await _loadOvlasti(req.user.id);
    if (hasPerm(role, ovlasti, key)) return next();
  } catch (e) { return res.status(500).json({ error: 'Greška provjere ovlasti' }); }
  return res.status(403).json({ error: 'Nemaš ovlast za ovu radnju' });
};
async function _gateByPath(req, res, next) {
  if (!req.user) return res.status(401).json({ error: 'Nije prijavljen' });
  if (req.user.role === 'direktor') return next();           // super-admin
  const modul = _modulZaPath(req.path);
  if (modul) {
    try {
      const { role, ovlasti } = await _loadOvlasti(req.user.id);
      if (hasPerm(role, ovlasti, modul)) return next();
    } catch (e) { return res.status(500).json({ error: 'Greška provjere ovlasti' }); }
  }
  return res.status(403).json({ error: 'NEMATE PRISTUP' });
}
const admin = _gateByPath;
const direktor = _gateByPath;

const staff = (req, res, next) => {
  if (!req.user) return res.status(401).json({ error: 'Nije prijavljen' });
  next();
};

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.502.20.183 (Ivan, 07.06.2026): GRANULARNE OVLASTI — TEMELJ (Faza 0).
//   Registar modula + helperi (hasPerm / _loadOvlasti / requirePerm) + default za poslovođu.
//   ⚠️ U OVOJ FAZI helperi NISU primijenjeni ni na jednu rutu → NULA promjene ponašanja.
