// Cleanup QNAP — briše samo naše fajlove (_id{N}.jpg) čiji ID nije u bazi
app.get('/api/debug/qnap-cleanup', async (req, res) => {
  if (!checkAndAuditInitSecret(req, res, '/api/debug/qnap-cleanup')) return;
  if (!process.env.QNAP_WEBDAV_URL) return res.status(400).json({ error: 'QNAP nije konfiguriran' });
  try {
    const base    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/, '');
    const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
    const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
    const hdrs    = { Authorization: `Basic ${auth64}` };

    // Dohvati sve dnevnik ID-eve koji postoje u bazi
    const dbIds = await pool.query(`SELECT id FROM dnevnik`);
    const aktivniIds = new Set(dbIds.rows.map(r => String(r.id)));

    // Dohvati sva gradilišta
    const grads = await pool.query(`SELECT naziv FROM gradilista`);
    const results = { pregledano: 0, obrisano: 0, preskoceno: 0, detalji: [] };

    for (const grad of grads.rows) {
      const gradNaziv = grad.naziv.replace(/[/\\:*?"<>|]/g,'_').trim();
      const propResp = await fetch(`${baseUrl}${base}/Dnevnik/${gradNaziv}/`, {
        method: 'PROPFIND',
        headers: { ...hdrs, Depth: '1', 'Content-Type': 'application/xml' },
        body: '<?xml version="1.0"?><propfind xmlns="DAV:"><prop><displayname/></prop></propfind>'
      }).catch(() => null);
      if (!propResp || (!propResp.ok && propResp.status !== 207)) continue;

      const xml = await propResp.text();
      const files = [...xml.matchAll(/href[^>]*>([^<]*\.(?:jpg|webp))/gi)] // ⭐ v135.7.502.20.64: + webp
        .map(m => m[1].split('/').pop()).filter(Boolean);

      for (const fname of files) {
        results.pregledano++;
        // Samo fajlovi s _id{broj} uzorkom — naš format
        const idMatch = fname.match(/_id(\d+)\.(?:jpg|webp)$/i); // ⭐ v135.7.502.20.64: + webp
        if (!idMatch) { results.preskoceno++; continue; } // nije naš format — ne diraj

        const fileId = idMatch[1];
        if (aktivniIds.has(fileId)) {
          results.preskoceno++; // ID postoji u bazi — ostavi
        } else {
          // ID ne postoji — sigurno možemo brisati
          const del = await fetch(`${baseUrl}${base}/Dnevnik/${gradNaziv}/${fname}`, {
            method: 'DELETE', headers: hdrs
          }).catch(() => ({ status: 0 }));
          results.obrisano++;
          results.detalji.push(`${gradNaziv}/${fname} → ${del.status}`);
        }
      }
    }

    res.json(results);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

