// Spremi subscription
app.post('/api/push/subscribe', auth, async (req, res) => {
  const { subscription } = req.body;
  if (!subscription) return res.status(400).json({ error: 'Nedostaje subscription' });
  // ⭐ v135.7.215: Validacija push subscription strukture (sprečava korumpirane unose u DB)
  let subObj;
  try {
    subObj = typeof subscription === 'string' ? JSON.parse(subscription) : subscription;
    if (!subObj.endpoint || typeof subObj.endpoint !== 'string') {
      return res.status(400).json({ error: 'Subscription nedostaje endpoint polje' });
    }
    if (!subObj.keys || !subObj.keys.p256dh || !subObj.keys.auth) {
      return res.status(400).json({ error: 'Subscription nedostaje keys polja' });
    }
  } catch (e) {
    return res.status(400).json({ error: 'Subscription nije validan JSON' });
  }
  try {
    const sub = typeof subscription === 'string' ? subscription : JSON.stringify(subscription);
    await pool.query(
      `INSERT INTO push_subscriptions(radnik_id, subscription)
       VALUES($1, $2)
       ON CONFLICT(radnik_id, subscription) DO UPDATE SET created_at=NOW()`,
      [req.user.id, sub]
    );
    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

