    const VALID = ['mat', 'dnv', 'nalozi', 'zad', 'skel', 'rez', 'smece', 'izmjera', 'urd', 'gorivo', 'skladiste', 'fasada'];
    const incoming = (req.body && typeof req.body.prefs === 'object' && req.body.prefs) ? req.body.prefs : {};
