// ── RESET PIN (one-time, zaštićen INIT_SECRET) ───────────────────────────────
// ⭐ v421 HIGH FIX (H2): konvertirano s GET na POST jer URL query stringovi (?pin=X)
//   se logiraju u Railway HTTP access logu, u browser history, u QNAP web proxy logu
//   i u Cloudflare logu. PIN je u plaintextu. POST body se NE logira u access log
//   (samo URL i HTTP method).
//   COMPAT: GET endpoint zadržan kao deprecated wrapper koji vraća 410 Gone s
//   uputama. Nakon 2 tjedna može se ukloniti (vidi audit log).
app.post('/api/reset-pin', async (req, res) => {
  if (!checkAndAuditInitSecret(req, res, '/api/reset-pin')) return;
  const { ime, prezime, pin } = req.body;
  if (!ime || !prezime || !pin) return res.status(400).json({ error: 'Nedostaje ime, prezime ili pin' });
  try {
    const PIN_PEPPER_VAL = process.env.PIN_PEPPER || '';
    const hash = await bcrypt.hash(String(pin) + PIN_PEPPER_VAL, BCRYPT_ROUNDS);
    const r = await pool.query(
      'UPDATE radnici SET pin=$1 WHERE ime=$2 AND prezime=$3 AND aktivan=true RETURNING id,ime,prezime,role',
      [hash, ime, prezime]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Radnik nije pronađen' });
    // Audit log za sigurnosni event (PIN reset je high-impact operation)
    // ⭐ v135.7.502.20.63 (Ivan, 01.06.2026): BUG FIX — audit INSERT je koristio stupce
    //   event_type/radnik_id/metadata kojih NEMA u tablici audit_log (prava shema:
    //   action/target_type/target_id/details/severity). PostgreSQL je svaki put bacao
    //   "column does not exist", a try/catch ga je tiho progutao → reset PIN-a se NIKAD
    //   nije zapisivao u audit. FIX: usklađeni stupci s pravom shemom + severity='warning'.
    //   (Ruta nema JWT auth — štiti je INIT_SECRET — pa user_id ostaje NULL; tko je u IP/UA.)
    try {
      await pool.query(
        `INSERT INTO audit_log(action, target_type, target_id, details, ip, user_agent, severity)
         VALUES ('pin_reset_admin', 'radnici', $1, $2, $3, $4, 'warning')`,
        [r.rows[0].id, JSON.stringify({ via: 'POST /api/reset-pin', radnik: `${r.rows[0].ime} ${r.rows[0].prezime}` }), req.ip, req.get('User-Agent') || '']
      );
    } catch (e) { console.warn('[audit] pin_reset_admin log fail:', e.message); /* audit nije critical-path */ }
    res.json({ ok: true, radnik: r.rows[0] });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

