// ── LOGIN ─────────────────────────────────────────────────────────────────────

// ── RATE LIMITER — PostgreSQL persistent brute force zaštita ─────────────────
// ⭐ v501.13 (Ivan, audit-driven): ESCALATING LOCKOUT
//   PRIJE: 5 fail-ova → uvijek 15 min lock. Napadač ima 480 pokušaja/dan = 0.05% PIN guess godišnje.
//   SAD: prvih 5 fail-ova → 15 min, sljedećih 5 → 1h, sljedećih 5 → 24h, sve preko → 7 dana.
//        Total_failures counter prati sve pokušaje s istog IP-a — nikad se ne resetira.
//        Posljedica: napadač s 50+ pokušaja gubi pristup tjedan dana. Ozbiljno demotivira.
const RATE_MAX    = 5;               // max neuspjelih pokušaja prije lock
const RATE_WINDOWS = [
  { threshold: 5,   duration_ms: 15 * 60 * 1000,    label: '15 min' },     // prvi lock
  { threshold: 10,  duration_ms: 60 * 60 * 1000,    label: '1 sat' },      // drugi lock (escalation)
  { threshold: 15,  duration_ms: 24 * 60 * 60 * 1000, label: '24 sata' }, // treći lock (jaka penalizacija)
  { threshold: 25,  duration_ms: 7 * 24 * 60 * 60 * 1000, label: '7 dana' }, // četvrti lock (totalni ban)
];

function getRateKey(req) {
  return req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.ip || 'unknown';
}

async function isRateLimited(ip) {
  try {
    const r = await pool.query(
      `SELECT count, locked_until FROM login_attempts WHERE ip=$1`, [ip]
    );
    if (!r.rows.length) return false;
    const rec = r.rows[0];
    if (rec.locked_until && new Date(rec.locked_until) > new Date()) return true;
    if (rec.locked_until && new Date(rec.locked_until) <= new Date()) {
      // ⭐ v501.13: NE briši DELETE — samo resetiraj locked_until na NULL
      //   Tako total_failures counter ostaje za escalating lockout!
      //   Bez ovoga, napadač uvijek dobi novih 5 pokušaja sa svake escalation razine.
      await pool.query('UPDATE login_attempts SET locked_until=NULL, count=0 WHERE ip=$1', [ip]);
      return false;
    }
    return false;
  } catch { return false; }
}

async function getMinutesLeft(ip) {
  try {
    const r = await pool.query('SELECT locked_until FROM login_attempts WHERE ip=$1', [ip]);
    if (!r.rows.length || !r.rows[0].locked_until) return 15;
    return Math.max(1, Math.ceil((new Date(r.rows[0].locked_until) - new Date()) / 60000));
  } catch { return 15; }
}

async function recordFailure(ip) {
  try {
    // ⭐ v501.13: koristi total_failures za escalating lockout
    const r = await pool.query(`
      INSERT INTO login_attempts (ip, count, total_failures, last_attempt, locked_until)
      VALUES ($1, 1, 1, NOW(), NULL)
      ON CONFLICT (ip) DO UPDATE
        SET count        = login_attempts.count + 1,
            total_failures = COALESCE(login_attempts.total_failures, 0) + 1,
            last_attempt = NOW(),
            locked_until = CASE
              WHEN login_attempts.count + 1 >= $2
              THEN NOW() + (
                -- escalating duration based on total_failures
                CASE
                  WHEN COALESCE(login_attempts.total_failures, 0) + 1 >= 25 THEN INTERVAL '7 days'
                  WHEN COALESCE(login_attempts.total_failures, 0) + 1 >= 15 THEN INTERVAL '24 hours'
                  WHEN COALESCE(login_attempts.total_failures, 0) + 1 >= 10 THEN INTERVAL '1 hour'
                  ELSE INTERVAL '15 minutes'
                END
              )
              ELSE NULL
            END
      RETURNING count, total_failures, locked_until
    `, [ip, RATE_MAX]);
    
    // ⭐ v135.7.401: Push notif direktoru pri 3+ failed login-a s istog IP-a.
    //   Razlog: u v397 sam dokumentirao "push direktoru kod 3+ fail-ova" ali to 
    //   nije bilo implementirano. Sada se događa svaki put kad count dostigne 3 i 5.
    //   Throttle: koristi anti-spam preko in-memory _failedLoginPushState (ne db) 
    //   da ne spamuje direktora ako napadač pokušava 100 puta zaredom.
    const count = r.rows[0]?.count || 0;
    const total = r.rows[0]?.total_failures || 0;
    const locked = r.rows[0]?.locked_until;
    
    if (count === 3 || count === RATE_MAX) {
      // Anti-spam: max 1 push po IP-u u 10 min
      const pushKey = 'failed_login_' + ip;
      const lastPush = _failedLoginPushState.get(pushKey) || 0;
      if (Date.now() - lastPush < 10 * 60 * 1000) return;
      _failedLoginPushState.set(pushKey, Date.now());
      
      try {
        const dir = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1");
        if (dir.rows.length && typeof sendPushToUser === 'function') {
          // ⭐ v501.13: Push poruka sad uključuje escalation info
          let lockLabel = '15 min';
          if (total >= 25) lockLabel = '7 dana';
          else if (total >= 15) lockLabel = '24 sata';
          else if (total >= 10) lockLabel = '1 sat';
          
          const title = count === RATE_MAX 
            ? `🔴 IP zaključan na ${lockLabel} (${total} ukupnih neuspjeha)`
            : '⚠ 3 neuspjela login pokušaja';
          const body = count === RATE_MAX
            ? `IP ${ip} je zaključan na ${lockLabel}. Ukupno ${total} neuspjeha. ${total >= 10 ? '⚠ NETKO AKTIVNO POKUŠAVA UĆI.' : ''}`
            : `IP ${ip} je probao 3× pogrešan PIN. Ako nisi to ti — pripremi se za potencijalni napad.`;
          await sendPushToUser(dir.rows[0].id, title, body, '/#s-backup');
          console.warn(`[SIGURNOST] Push direktoru: ${title} (IP=${ip}, count=${count}, total=${total})`);
        }
        
        // Audit log
        if (typeof auditLog === 'function') {
          await auditLog({ headers: {}, ip }, {
            action: count === RATE_MAX ? 'login_lockout' : 'login_failure_burst',
            target_type: 'auth',
            details: { ip, count, locked_until: locked },
            severity: count === RATE_MAX ? 'critical' : 'warning'
          }).catch(() => {});
        }
      } catch (eP) { 
        console.warn('[failed-login push] fail:', eP.message); 
      }
    }
  } catch { /* ne blokiraj login ako tablica ne postoji još */ }
}

// In-memory throttle za failed-login push notifikacije (anti-spam direktoru)
const _failedLoginPushState = new Map();
setInterval(() => {
  const cutoff = Date.now() - 30 * 60 * 1000;
  for (const [k, v] of _failedLoginPushState.entries()) {
    if (v < cutoff) _failedLoginPushState.delete(k);
  }
}, 5 * 60 * 1000);

async function clearAttempts(ip) {
  try { await pool.query('DELETE FROM login_attempts WHERE ip=$1', [ip]); } catch {}
}

// ── OPĆI API RATE LIMITER (in-memory) ────────────────────────────────────────
// Štiti sve /api/ rute od prekomjernog korištenja — 300 zahtjeva/min po IP-u
// FUTURE-PROOF-2030: [LIMITS] Rate limit konstante
//   PROVJERI: ako se broj korisnika poveća (5+ radnika), 300/min/IP može biti premalo
//             jer NAT (mobilni operater) može više korisnika dijeliti isti IP
//   FIX: povećaj API_RATE_LIMIT na 600-1000, ili migriraj na user_id-based limit
//   ALTERNATIVA: 'express-rate-limit' npm paket (zrelije, distributed-friendly)
//   LAST_VERIFIED: 2026-05-01
const _apiReqMap = new Map();
const API_RATE_LIMIT  = 300;  // max zahtjeva
const API_RATE_WINDOW = 60000; // u 60 sekundi
app.use('/api', (req, res, next) => {
  // Preskoči za inicijalizacijske rute
  if (req.path === '/login' || req.path.startsWith('/init-db')) return next();
  const ip = req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.ip || 'unknown';
  const now = Date.now();
  const rec = _apiReqMap.get(ip) || { count: 0, start: now };
  if (now - rec.start > API_RATE_WINDOW) {
    rec.count = 1; rec.start = now;
  } else {
    rec.count++;
    if (rec.count > API_RATE_LIMIT) {
      _apiReqMap.set(ip, rec);
      return res.status(429).json({ error: 'Previše zahtjeva. Pokušaj za trenutak.' });
    }
  }
  _apiReqMap.set(ip, rec);
  // Čišćenje starih unosa svakih 5 minuta
  if (_apiReqMap.size > 1000) {
    for (const [k, v] of _apiReqMap) {
      if (now - v.start > API_RATE_WINDOW * 2) _apiReqMap.delete(k);
    }
  }
  next();
});

// ⭐ v135.7.218 (BUG FIX #1 iz audita): Proaktivni cleanup _apiReqMap svakih 5 minuta
//   PRIJE: cleanup samo kad mapa pređe 1000 unosa (na liniji 2317).
//          Pri natural traffic-u za 2 korisnika, mapa rijetko dosegne 1000 unosa pa
//          stari unosi mogu sjediti u memoriji satima/danima → blagi memory leak.
//   SAD: setInterval 5 min, briše sve unose starije od 2 minute (2× window-a).
//        Aktivni korisnici uvijek imaju svježi rec, briše se samo "mrtvo" stanje.
//   FUTURE-PROOF-2030: [RATE-LIMIT] [MEMORY] In-memory rate limiter (per-IP)
//     PROVJERI:
//       1. Ako broj korisnika prijeđe 100, razmotriti per-user (radnik_id) umjesto per-IP
//       2. Ako se aplikacija scale-a horizontalno (multi-instance), treba Redis-based limiter
//     LAST_VERIFIED: 2026-05-08
setInterval(() => {
  const now = Date.now();
  const cutoff = API_RATE_WINDOW * 2; // 2 minute
  let removed = 0;
  for (const [k, v] of _apiReqMap) {
    if (now - v.start > cutoff) {
      _apiReqMap.delete(k);
      removed++;
    }
  }
  if (removed > 0) {
    console.log(`[rate-limit cleanup] obrisano ${removed} starih unosa, mapa: ${_apiReqMap.size}`);
  }
}, 5 * 60 * 1000); // svakih 5 minuta

// ⭐ v135.7.125 (BUG FIX AI-03): Centralizirani Claude API caller s retry
//   Razlog: prije je svaki endpoint imao vlastiti error handling (8 mjesta).
//   Ako Anthropic 5xx vrati, user dobije generic 500 bez fallback opcije.
//   Sad: jedan helper za sve, s 1× retry za network/5xx i jasan error format.
//   
//   Vraća:
//     { ok: true, data: <Claude response JSON> }
//     { ok: false, errorType: 'rate_limit' | 'auth' | 'overloaded' | 'invalid_input' | 'network' | 'unknown', 
//       status, message, retryAfter (sek za rate_limit) }
async function _callClaudeAPI(payload, options = {}) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return { ok: false, errorType: 'auth', status: 0, message: 'ANTHROPIC_API_KEY nije postavljen' };
  }
  const fetch_ = (typeof fetch === 'function') ? fetch : require('node-fetch');
  const maxRetries = options.maxRetries ?? 1;
  // ⭐ v135.7.216: Timeout 120s (Anthropic vision može trajati 60-90s, daje buffer)
  const timeoutMs = options.timeoutMs ?? 120000;
  
  let lastError = null;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const resp = await fetch_('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(timeoutMs)
      });
      
      if (resp.ok) {
        const data = await resp.json();
        return { ok: true, data };
      }
      
      // Errors with content
      const errText = await resp.text().catch(() => '');
      const status = resp.status;
      
      // Klasificiraj
      if (status === 429) {
        const retryAfter = parseInt(resp.headers.get('retry-after')) || 30;
        return { ok: false, errorType: 'rate_limit', status, message: 'AI rate limit', retryAfter };
      }
      if (status === 401 || status === 403) {
        return { ok: false, errorType: 'auth', status, message: 'AI autentifikacija neuspješna' };
      }
      if (status >= 500) {
        // Anthropic 5xx → retry
        lastError = { ok: false, errorType: 'overloaded', status, message: 'AI server preopterečen' };
        console.warn(`[claude API] attempt ${attempt+1} failed status=${status}: ${errText.slice(0, 200)}`);
        if (attempt < maxRetries) {
          await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));  // 2s, 4s
          continue;
        }
        return lastError;
      }
      // 4xx — invalid input, no retry
      return { ok: false, errorType: 'invalid_input', status, message: 'AI je odbio zahtjev (možda preveliki input?)' };
    } catch(e) {
      // Network error
      lastError = { ok: false, errorType: 'network', status: 0, message: e.message };
      console.warn(`[claude API] attempt ${attempt+1} network error: ${e.message}`);
      // ⭐ v135.7.217: Ne retry-aj timeout (već 120s — drugi poziv samo bi udvostručio cost)
      const isTimeout = e.name === 'AbortError' || e.message?.includes('timeout') || e.message?.includes('aborted');
      if (attempt < maxRetries && !isTimeout) {
        await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
        continue;
      }
      return lastError;
    }
  }
  return lastError || { ok: false, errorType: 'unknown', status: 0, message: 'Nepoznata greška' };
}

// ⭐ v135.7.502.20.157 (Ivan, 06.06.2026): STREAMING poziv Anthropic API-ja (SSE).
//   onTextDelta(delta) se zove za svaki komad teksta (relaj klijentu uživo).
//   Vraća { ok, blocks, stop_reason, usage } — blocks su isti format kao non-stream (text + tool_use s input).
async function _callClaudeStream(payload, onTextDelta, options = {}) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { ok: false, errorType: 'auth' };
  const fetch_ = (typeof fetch === 'function') ? fetch : require('node-fetch');
  const timeoutMs = options.timeoutMs ?? 120000;
  // ⭐ v758 (Ivan, OI recept): vanjski AbortController za PREKID s klijenta. Timeout ručno (bez
  //   AbortSignal.any — Node kompatibilnost), timer unref-an. options.onCtrl predaje ctrl registru.
  const _ctrl = new AbortController();
  const _tmr = setTimeout(() => { try { _ctrl.abort(); } catch (_) {} }, timeoutMs);
  if (_tmr.unref) _tmr.unref();
  if (options.signal) {
    if (options.signal.aborted) { try { _ctrl.abort(); } catch (_) {} }
    else { try { options.signal.addEventListener('abort', () => { try { _ctrl.abort(); } catch (_) {} }, { once: true }); } catch (_) {} }
  }
  if (options.onCtrl) { try { options.onCtrl(_ctrl); } catch (_) {} }
  const _jePrekid = () => !!(options.signal && options.signal.aborted);
  let resp;
  try {
    resp = await fetch_('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json', 'accept': 'text/event-stream' },
      body: JSON.stringify({ ...payload, stream: true }),
      signal: _ctrl.signal
    });
  } catch (e) { return { ok: false, errorType: _jePrekid() ? 'prekid' : 'network', message: e.message }; }
  if (!resp.ok) {
    const status = resp.status;
    // ⭐ v1037 (Ivan: „želim Sonnet 5, zašto ga ne uzima?"): PORUKA `invalid_input` JE MOJA, NE API-jeva.
    //   Ovaj kod je SVAKI 4xx pretvarao u „invalid_input" i bacao tijelo odgovora. Zato je Ivan osam
    //   puta vidio istu beskorisnu rečenicu, a pravi razlog — koji API uredno napiše — nikad nije
    //   došao do njega. Tri sasvim različita uzroka izgledala su identično:
    //     · model_not_found → ključ nema pristup tom modelu (traži se u konzoli)
    //     · invalid_request_error → npr. `thinking.budget_tokens` veći ili blizak `max_tokens`
    //     · nepoznat naziv modela → stvarno kriv string
    //   Nijedan se ne rješava isto, a ja sam ih sve zvao istim imenom. Sada se čita tijelo greške i
    //   prenosi doslovno; klasifikacija ostaje za logiku, poruka za čovjeka.
    let _tijelo = '';
    try { _tijelo = (await resp.text() || '').slice(0, 400); } catch (_) {}
    let _por = '';
    try { const j = JSON.parse(_tijelo); _por = (j && j.error && (j.error.message || j.error.type)) || ''; } catch (_) { _por = _tijelo; }
    if (status === 429) return { ok: false, errorType: 'rate_limit', status, message: _por };
    if (status === 401 || status === 403) return { ok: false, errorType: 'auth', status, message: _por };
    return { ok: false, errorType: status >= 500 ? 'overloaded' : 'invalid_input', status, message: _por || ('HTTP ' + status) };
  }
  if (!resp.body || typeof resp.body.getReader !== 'function') return { ok: false, errorType: 'network', message: 'nema stream tijela' };
  const reader = resp.body.getReader();
  const decoder = new TextDecoder();
  let buf = '';
  const blocks = [];
  const partial = {};
  let stop_reason = null, usageInput = null, usageOutput = 0, cacheRead = 0, cacheCreate = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith('data:')) continue;
        const dataStr = line.slice(5).trim();
        if (!dataStr || dataStr === '[DONE]') continue;
        let ev; try { ev = JSON.parse(dataStr); } catch (_) { continue; }
        const t = ev.type;
        if (t === 'content_block_start') {
          const cb = ev.content_block || {};
          if (cb.type === 'text') partial[ev.index] = { type: 'text', text: cb.text || '' };
          else if (cb.type === 'tool_use') { partial[ev.index] = { type: 'tool_use', id: cb.id, name: cb.name, json: '' }; if (options.onToolStart) { try { options.onToolStart(cb.name); } catch (_) {} } }
          else if (cb.type === 'thinking') partial[ev.index] = { type: 'thinking', thinking: cb.thinking || '', signature: cb.signature || '' };
          else if (cb.type === 'redacted_thinking') partial[ev.index] = { type: 'redacted_thinking', data: cb.data || '' };
        } else if (t === 'content_block_delta') {
          const d = ev.delta || {};
          const p = partial[ev.index];
          if (d.type === 'text_delta') { if (p) p.text += d.text; if (onTextDelta && d.text) { try { onTextDelta(d.text); } catch (_) {} } }
          else if (d.type === 'input_json_delta') { if (p) p.json += (d.partial_json || ''); }
          else if (d.type === 'thinking_delta') { if (p) p.thinking = (p.thinking || '') + (d.thinking || ''); }
          else if (d.type === 'signature_delta') { if (p && d.signature) p.signature = d.signature; }
        } else if (t === 'content_block_stop') {
          const p = partial[ev.index];
          if (p) {
            if (p.type === 'text') blocks.push({ type: 'text', text: p.text });
            else if (p.type === 'tool_use') { let inp = {}; try { inp = p.json ? JSON.parse(p.json) : {}; } catch (_) {} blocks.push({ type: 'tool_use', id: p.id, name: p.name, input: inp }); }
            else if (p.type === 'thinking') blocks.push({ type: 'thinking', thinking: p.thinking || '', signature: p.signature || '' });
            else if (p.type === 'redacted_thinking') blocks.push({ type: 'redacted_thinking', data: p.data || '' });
            delete partial[ev.index];
          }
        } else if (t === 'message_start') {
          const u = ev.message && ev.message.usage;
          if (u) { usageInput = u.input_tokens || 0; cacheRead = u.cache_read_input_tokens || 0; cacheCreate = u.cache_creation_input_tokens || 0; }
        } else if (t === 'message_delta') {
          if (ev.delta && ev.delta.stop_reason) stop_reason = ev.delta.stop_reason;
          if (ev.usage && typeof ev.usage.output_tokens === 'number') usageOutput = ev.usage.output_tokens;
        } else if (t === 'error') {
          return { ok: false, errorType: 'api_error', message: ev.error && ev.error.message };
        }
      }
    }
  } catch (e) { return { ok: false, errorType: _jePrekid() ? 'prekid' : 'network', message: e.message }; }   // ⭐ v758: prekid NIJE mrežna greška
  const usage = { input_tokens: usageInput || 0, output_tokens: usageOutput || 0, cache_read_input_tokens: cacheRead, cache_creation_input_tokens: cacheCreate };
  return { ok: true, blocks, stop_reason, usage };
}

// ⭐ v135.7.125 (AI-03): Helper za Express response sa standardiziranim format
//   Frontend može parsati `errorType` i pokazati primjereni UI.
function _sendAiError(res, aiResult) {
  const userMsg = (() => {
    switch (aiResult.errorType) {
      case 'rate_limit': return `AI rate limit dosegnut. Pokušaj za ${aiResult.retryAfter || 30}s.`;
      case 'auth': return 'AI ključ nije važeći — javite administratoru.';
      case 'overloaded': return 'AI je trenutno preopterečen. Pokušaj za 1-2 min.';
      case 'invalid_input': return 'AI je odbio zahtjev (možda slika prevelika ili nečitljiva).';
      case 'network': return 'Network greška pri komunikaciji s AI-om. Provjeri internet.';
      default: return aiResult.message || 'AI greška.';
    }
  })();
  
  const status = aiResult.errorType === 'rate_limit' ? 429
    : (aiResult.errorType === 'auth' ? 503
      : (aiResult.errorType === 'invalid_input' ? 400 : 503));
  
  res.status(status).json({
    error: userMsg,
    error_type: aiResult.errorType,
    fallback_available: true,  // frontend zna da može pokazati "manual mode" gumb
    retry_after_sec: aiResult.retryAfter || null,
  });
}

// ── AI ENDPOINT RATE LIMITER (per user + globalan) ──────────────────────────
// Per-user: 20 poziva/min/korisnik (sprječava bug-loop ili spam)
// Globalan: 50 poziva/min ukupno (sprječava prijeći Anthropic globalni limit)
//   ⭐ AUDIT #34: dodano globalno rate ograničenje (Anthropic limit je na API ključu, ne na korisnika)
// ⭐ v135.7.398 (SaaS sigurnost): DAILY QUOTA — max 150 AI poziva/dan po useru.
//    PROBLEM: rate limit per minute nije dovoljan ako napadač ima ukradeni JWT token. 
//    150 poziva × 60 min × 24h = teoretskih 216 000 poziva/dan ako brute force pravopisni.
//    Pri Anthropic cijeni $0.015/poziv = $3 240/dan na tvojoj kartici.
//    
//    FIX: daily quota counter per user, persistent u DB (ai_daily_usage tablica).
//    Reset svaki dan u ponoć Europe/Zagreb. Direktor može pratiti potrošnju kroz endpoint.
//    Pri 80% potrošnje (120/150) → push notif Ivanu "AI quota se troši".
//    Pri 100% (150/150) → tvrdi lockout do ponoći + email Ivanu.
const _aiReqMap = new Map();
const AI_RATE_LIMIT = 20;  // max AI poziva po korisniku po minuti
const AI_RATE_WINDOW = 60000;  // u 60s
const GLOBAL_AI_LIMIT = 50;  // ⭐ #34: max poziva globalno/min
const AI_DAILY_QUOTA = parseInt(process.env.AI_DAILY_QUOTA || '150', 10);  // po useru/dan
const AI_DAILY_WARNING_PCT = 0.8;  // push notif pri 80% potrošnje
let _globalAiCount = 0;
let _globalAiStart = Date.now();

// In-memory cache daily counter-a (avoids DB hit svaki AI call):
//   _aiDailyMap = Map<userId, { count: N, date: 'YYYY-MM-DD', warnedAt: 0|timestamp }>
// Sinkronizira se s DB pri start-u dana i pri reach 80%.
const _aiDailyMap = new Map();

function _todayKey() {
  // YYYY-MM-DD u Europe/Zagreb timezone
  const d = new Date();
  const opts = { timeZone: 'Europe/Zagreb', year: 'numeric', month: '2-digit', day: '2-digit' };
  const parts = new Intl.DateTimeFormat('en-CA', opts).format(d);
  return parts;
}

async function _aiDailyCheck(userId) {
  // Vraća { ok: bool, used: N, quota: N, remaining: N }
  if (!userId || userId === 'anon') return { ok: true, used: 0, quota: AI_DAILY_QUOTA, remaining: AI_DAILY_QUOTA };
  
  const today = _todayKey();
  let rec = _aiDailyMap.get(userId);
  
  // Reset ako je dan promijenjen
  if (!rec || rec.date !== today) {
    // Pokušaj učitati iz DB (ako server restartao)
    try {
      const dbRow = await pool.query(
        'SELECT count FROM ai_daily_usage WHERE user_id=$1 AND date=$2',
        [userId, today]
      );
      rec = { count: dbRow.rows[0]?.count || 0, date: today, warnedAt: 0 };
    } catch(e) {
      // Tablica možda još ne postoji — fallback in-memory only
      rec = { count: 0, date: today, warnedAt: 0 };
    }
    _aiDailyMap.set(userId, rec);
  }
  
  return { 
    ok: rec.count < AI_DAILY_QUOTA, 
    used: rec.count, 
    quota: AI_DAILY_QUOTA, 
    remaining: Math.max(0, AI_DAILY_QUOTA - rec.count)
  };
}

async function _aiDailyIncrement(userId) {
  if (!userId || userId === 'anon') return;
  const today = _todayKey();
  let rec = _aiDailyMap.get(userId);
  if (!rec || rec.date !== today) {
    rec = { count: 0, date: today, warnedAt: 0 };
  }
  rec.count++;
  _aiDailyMap.set(userId, rec);
  
  // Async DB update (ne blokira request)
  pool.query(
    `INSERT INTO ai_daily_usage(user_id, date, count) VALUES($1, $2, 1)
     ON CONFLICT (user_id, date) DO UPDATE SET count = ai_daily_usage.count + 1`,
    [userId, today]
  ).catch(e => {
    if (!e.message.includes('does not exist')) {
      console.warn('[ai-daily] DB update fail:', e.message);
    }
  });
  
  // Provjera 80% warning threshold-a (push samo jednom po danu)
  const pct = rec.count / AI_DAILY_QUOTA;
  if (pct >= AI_DAILY_WARNING_PCT && !rec.warnedAt) {
    rec.warnedAt = Date.now();
    try {
      const u = await pool.query('SELECT ime, prezime, role FROM radnici WHERE id=$1', [userId]);
      const userName = u.rows[0] ? `${u.rows[0].ime} ${u.rows[0].prezime}` : `User#${userId}`;
      console.warn(`[ai-daily WARNING] ${userName} dosegao ${Math.round(pct*100)}% AI quota (${rec.count}/${AI_DAILY_QUOTA})`);
      
      // Push notif direktoru
      const dir = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1");
      if (dir.rows.length && typeof sendPushToUser === 'function' && dir.rows[0].id !== userId) {
        await sendPushToUser(
          dir.rows[0].id,
          '⚠ AI quota warning',
          `${userName} dosegao ${Math.round(pct*100)}% AI quote (${rec.count}/${AI_DAILY_QUOTA}). Provjeri postoji li neuobičajen pattern.`,
          '/#s-stat-rad'
        );
      }
    } catch(eP) { console.warn('[ai-daily warning push] fail:', eP.message); }
  }
}

function aiRateLimit(req, res, next) {
  const userId = req.user?.id || 'anon';
  const now = Date.now();
  
  // ── Daily quota check (PRVO — najvažnija zaštita) ─────────────────────
  // Async wrapper jer _aiDailyCheck radi DB poziv pri prvom pozivu dana
  _aiDailyCheck(userId).then(daily => {
    if (!daily.ok) {
      console.warn(`[ai-daily LOCKOUT] user=${userId} dosegao daily quota ${daily.used}/${daily.quota}`);
      return res.status(429).json({ 
        error: `Daily AI quota dosegnuta (${daily.used}/${daily.quota}). Reset u ponoć.`,
        error_type: 'daily_quota_exceeded',
        remaining: 0,
        reset_at: 'midnight'
      });
    }
    
    // ── Globalni rate limit (#34) ──────────────────────────────────────
    if (now - _globalAiStart > AI_RATE_WINDOW) {
      _globalAiCount = 1; _globalAiStart = now;
    } else {
      _globalAiCount++;
      if (_globalAiCount > GLOBAL_AI_LIMIT) {
        const sekLeft = Math.ceil((AI_RATE_WINDOW - (now - _globalAiStart)) / 1000);
        return res.status(429).json({ error: `Globalni AI limit dosegnut (${GLOBAL_AI_LIMIT}/min). Pokušaj za ${sekLeft}s.` });
      }
    }
    
    // ── Per-user rate limit (per-minute) ───────────────────────────────
    const rec = _aiReqMap.get(userId) || { count: 0, start: now };
    if (now - rec.start > AI_RATE_WINDOW) {
      rec.count = 1; rec.start = now;
    } else {
      rec.count++;
      if (rec.count > AI_RATE_LIMIT) {
        _aiReqMap.set(userId, rec);
        const sekLeft = Math.ceil((AI_RATE_WINDOW - (now - rec.start)) / 1000);
        return res.status(429).json({ error: `AI rate limit: max ${AI_RATE_LIMIT} poziva/min. Pokušaj za ${sekLeft}s.` });
      }
    }
    _aiReqMap.set(userId, rec);
    // Cleanup starih unosa
    if (_aiReqMap.size > 100) {
      for (const [k, v] of _aiReqMap) {
        if (now - v.start > AI_RATE_WINDOW * 2) _aiReqMap.delete(k);
      }
    }
    
    // ⭐ v135.7.398: increment daily counter AFTER all checks pass
    _aiDailyIncrement(userId).catch(e => console.warn('[ai-daily increment]', e.message));
    
    next();
  }).catch(eDaily => {
    // Ako daily check fail-a (DB down), allow request (fail-open) ali loggiraj
    console.warn('[ai-daily check fail-open]', eDaily.message);
    next();
  });
}

// ⭐ v135.7.125 (BUG FIX AI-01): Periodic memory cleanup za _aiReqMap
//   Razlog: prije cleanup samo ako map.size > 100 (rijetko triggered).
//   Ako 99 user-a istovremeno radi, map raste i čuva se zauvijek.
//   Sad: setInterval svakih 5 min — proaktivan cleanup starih unosa.
setInterval(() => {
  const now = Date.now();
  let cleaned = 0;
  for (const [k, v] of _aiReqMap) {
    if (now - v.start > AI_RATE_WINDOW * 2) {
      _aiReqMap.delete(k);
      cleaned++;
    }
  }
  if (cleaned > 0) console.log(`[ai cleanup] removed ${cleaned} expired entries (${_aiReqMap.size} remaining)`);
}, 5 * 60 * 1000);  // 5 min

