async function _posaljiAktivacijuMail(email, link, ime, pozivatelj, tip) {
  const isReset = tip === 'reset';
  const subject = isReset ? 'Resetiranje PIN-a — ŽBUKA Gradilište' : 'Aktivirajte svoj račun — ŽBUKA Gradilište';
  const text = (ime ? ('Pozdrav ' + ime + ',\n\n') : 'Pozdrav,\n\n')
    + (isReset ? 'Za vaš račun zaprimili smo zahtjev za resetiranje PIN-a. Stari PIN vrijedi dok ne postavite novi. ' : (pozivatelj ? (pozivatelj + ' vas je dodao u ŽBUKA Gradilište. ') : 'Dodani ste u ŽBUKA Gradilište. '))
    + 'Postavite PIN putem ove poveznice (vrijedi 72 sata):\n' + link + '\n\nAko niste očekivali ovaj email, slobodno ga zanemarite.\n\n— ŽBUKA ČAKARIĆ d.o.o.';
  const html = _emailAktivacijaHTML({ ime, pozivatelj, link, tip });
  const from = process.env.MAIL_FROM || ('ŽBUKA Gradilište <' + (process.env.SMTP_USER || 'noreply@zbuka.hr') + '>');
  // ⭐ v135.7.502.20.205 (Ivan, 07.06.2026): HTTPS slanje preko Resend (port 443 — host/Railway ga ne blokiraju
  //   kao SMTP 465/587). Ako je RESEND_API_KEY postavljen, šalji preko Resenda; inače padni na SMTP (nodemailer).
  if (process.env.RESEND_API_KEY) return await _posaljiMailResend({ from, to: email, subject, text, html });
  const m = _mailer();
  if (!m) return { sent: false, reason: 'mailer-unavailable' };
  await m.sendMail({ from, to: email, subject, text, html });
  return { sent: true };
}

// ⭐ v135.7.502.20.205 (Ivan, 07.06.2026): slanje e-pošte preko Resend HTTPS API-ja (https://api.resend.com/emails).
//   Zaobilazi SMTP firewall shared-hostinga (sve ide preko 443). VAŽNO: 'from' mora biti s domene verificirane u
//   Resendu (zbuka.hr) ILI 'onboarding@resend.dev' za prvi test na vlastiti email. Baca grešku na neuspjeh —
//   pozivatelj je hvata i prikazuje u email_error (modal).
async function _posaljiMailResend({ from, to, subject, text, html }) {
  const ctrl = new AbortController();
  const tmr = setTimeout(() => ctrl.abort(), 12000);
  try {
    const resp = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + process.env.RESEND_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ from, to: [to], subject, text, html }),
      signal: ctrl.signal
    });
    let data = {}; try { data = await resp.json(); } catch (_) {}
    if (!resp.ok) {
      const msg = (data && (data.message || data.name)) || ('HTTP ' + resp.status);
      console.warn('[mail/resend] nije poslano:', msg);
      throw new Error('Resend: ' + msg);
    }
    console.log('[mail/resend] poslano ->', to, '(id ' + (data && data.id) + ')');
    return { sent: true, id: data && data.id };
  } catch (e) {
    if (e && e.name === 'AbortError') throw new Error('Resend: timeout (12s)');
    throw e;
  } finally { clearTimeout(tmr); }
}

app.post('/api/korisnici', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const { ime, prezime, email, ovlasti } = req.body || {};
    if (!ime || !prezime || !String(ime).trim() || !String(prezime).trim())
      return res.status(400).json({ error: 'Ime i prezime su obavezni.' });
    if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(email).trim()))
      return res.status(400).json({ error: 'Neispravan email.' });
    const clean = _cleanOvlasti(ovlasti);
    // Neuporabljiv PIN dok korisnik ne postavi svoj preko linka (pin je NOT NULL u shemi).
    const dummyPin = await bcrypt.hash(crypto.randomBytes(32).toString('hex'), BCRYPT_ROUNDS);
    const ins = await pool.query(
      `INSERT INTO radnici (ime, prezime, email, pin, role, je_admin, aktivan, pin_set, ovlasti)
       VALUES ($1,$2,$3,$4,'poslovodja',false,false,false,$5::jsonb)
       RETURNING id, ime, prezime, email, aktivan, ovlasti`,
      [String(ime).trim(), String(prezime).trim(), email ? String(email).trim() : null, dummyPin, JSON.stringify(clean)]
    );
    const radnik = ins.rows[0];
    const token = _pozToken();
    await pool.query(
      "INSERT INTO korisnik_pozivnice (radnik_id, token_hash, tip, expires_at) VALUES ($1,$2,'invite',$3)",
      [radnik.id, _pozHash(token), new Date(Date.now() + 72 * 3600 * 1000)]
    );
    auditLog(req, { action: 'korisnik_kreiran', target_type: 'korisnik', details: { radnik_id: radnik.id, ime: radnik.ime, prezime: radnik.prezime }, severity: 'info' }).catch(() => {});
    const invite_link = _pozLinkBase() + '/?pozivnica=' + token;
    // ⭐ v135.7.502.20.198 (Ivan, 07.06.2026): ako je zadan email, pošalji pozivnicu (link i dalje vraćamo kao
    //   fallback; greška maila NE ruši kreiranje korisnika).
    let email_sent = false, email_error = null;
    if (radnik.email) {
      try {
        const inv = (await pool.query('SELECT ime, prezime FROM radnici WHERE id=$1', [req.user.id])).rows[0];
        const pozivatelj = inv ? ((inv.ime || '') + ' ' + (inv.prezime || '')).trim() : '';
        const _mr = await _posaljiAktivacijuMail(radnik.email, invite_link, radnik.ime, pozivatelj, 'invite');
        email_sent = !!(_mr && _mr.sent);  // ⭐ v200: NE oslanjaj se na "nema iznimke" — koristi stvarni rezultat
        if (!email_sent) email_error = 'Email servis trenutno nije dostupan (provjeri SMTP postavke).';
      } catch (e) { email_error = e.message; console.error('[mail invite]', e); }
    }
    res.json({ radnik, invite_link, email_sent, email_error, email: radnik.email || null });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Ažuriraj ovlasti poslovođe.
app.put('/api/korisnici/:id/ovlasti', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    const { ovlasti, samo_pregled } = req.body || {};
    if (!ovlasti || typeof ovlasti !== 'object') return res.status(400).json({ error: 'Nedostaju ovlasti.' });
    const t = await pool.query('SELECT role FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Ovlasti se mijenjaju samo poslovođama.' });
    const clean = _cleanOvlasti(ovlasti);
    // ⭐ v135.7.502.20.211 (Ivan, 08.06.2026): uz ovlasti spremi i "samo_pregled" (ako je poslan).
    if (typeof samo_pregled === 'boolean') {
      await pool.query('UPDATE radnici SET ovlasti=$1::jsonb, samo_pregled=$2 WHERE id=$3', [JSON.stringify(clean), samo_pregled, id]);
    } else {
      await pool.query('UPDATE radnici SET ovlasti=$1::jsonb WHERE id=$2', [JSON.stringify(clean), id]);
    }
    try { hotCacheInvalidate('ovlasti:' + id); } catch (_) {}
    auditLog(req, { action: 'korisnik_ovlasti_promjena', target_type: 'korisnik', details: { radnik_id: id, samo_pregled: samo_pregled === true }, severity: 'info' }).catch(() => {});
    res.json({ ok: true, ovlasti: clean, samo_pregled: samo_pregled === true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Generiraj novi link za postavljanje PIN-a (reset). Stari PIN ostaje dok korisnik ne postavi novi.
app.post('/api/korisnici/:id/pin-reset', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    const t = await pool.query('SELECT role, email, ime FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Reset je samo za poslovođe.' });
    // ⭐ v135.7.502.20.201 (Ivan, 07.06.2026): poništi stare nepotrošene reset-tokene (vrijedi samo zadnji link).
    await pool.query("UPDATE korisnik_pozivnice SET used_at=NOW() WHERE radnik_id=$1 AND tip='reset' AND used_at IS NULL", [id]);
    const token = _pozToken();
    await pool.query(
      "INSERT INTO korisnik_pozivnice (radnik_id, token_hash, tip, expires_at) VALUES ($1,$2,'reset',$3)",
      [id, _pozHash(token), new Date(Date.now() + 72 * 3600 * 1000)]
    );
    auditLog(req, { action: 'korisnik_pin_reset', target_type: 'korisnik', details: { radnik_id: id }, severity: 'info' }).catch(() => {});
    const invite_link = _pozLinkBase() + '/?pozivnica=' + token;
    // ⭐ v135.7.502.20.198 (Ivan, 07.06.2026): pošalji reset-link na email ako korisnik ima email (link i dalje fallback).
    let email_sent = false, email_error = null;
    if (t.rows[0].email) {
      try { const _mr = await _posaljiAktivacijuMail(t.rows[0].email, invite_link, t.rows[0].ime, '', 'reset'); email_sent = !!(_mr && _mr.sent); if (!email_sent) email_error = 'Email servis trenutno nije dostupan (provjeri SMTP postavke).'; }
      catch (e) { email_error = e.message; console.error('[mail reset]', e); }
    }
    res.json({ invite_link, email_sent, email_error, email: t.rows[0].email || null });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v135.7.502.20.201 (Ivan, 07.06.2026): "Pošalji ponovno pozivnicu" — jednoklik re-slanje INVITE maila korisniku
//   koji ima email a još nije aktivirao račun. Poništava stare nepotrošene invite-tokene, šalje svjež.
app.post('/api/korisnici/:id/posalji-pozivnicu', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    const t = await pool.query('SELECT role, email, ime, COALESCE(obrisan,false) AS obrisan FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Pozivnica je samo za poslovođe.' });
    if (t.rows[0].obrisan) return res.status(400).json({ error: 'Korisnik je obrisan.' });
    if (!t.rows[0].email) return res.status(400).json({ error: 'Korisnik nema email — koristi "Pošalji link".' });
    await pool.query("UPDATE korisnik_pozivnice SET used_at=NOW() WHERE radnik_id=$1 AND tip='invite' AND used_at IS NULL", [id]);
    const token = _pozToken();
    await pool.query("INSERT INTO korisnik_pozivnice (radnik_id, token_hash, tip, expires_at) VALUES ($1,$2,'invite',$3)", [id, _pozHash(token), new Date(Date.now() + 72 * 3600 * 1000)]);
    auditLog(req, { action: 'korisnik_pozivnica_ponovo', target_type: 'korisnik', details: { radnik_id: id }, severity: 'info' }).catch(() => {});
    const invite_link = _pozLinkBase() + '/?pozivnica=' + token;
    const inv = (await pool.query('SELECT ime, prezime FROM radnici WHERE id=$1', [req.user.id])).rows[0];
    const pozivatelj = inv ? ((inv.ime || '') + ' ' + (inv.prezime || '')).trim() : '';
    let email_sent = false, email_error = null;
    try {
      const _mr = await _posaljiAktivacijuMail(t.rows[0].email, invite_link, t.rows[0].ime, pozivatelj, 'invite');
      email_sent = !!(_mr && _mr.sent);
      if (!email_sent) email_error = 'Email servis trenutno nije dostupan (provjeri SMTP postavke).';
    } catch (e) { email_error = e.message; console.error('[mail invite-resend]', e); }
    res.json({ invite_link, email_sent, email_error, email: t.rows[0].email });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Deaktiviraj / reaktiviraj poslovođu (ne sebe, ne direktora).
app.put('/api/korisnici/:id/aktivan', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    if (id === req.user.id) return res.status(400).json({ error: 'Ne možeš mijenjati vlastiti status.' });
    const aktivan = !!(req.body && req.body.aktivan);
    const t = await pool.query('SELECT role, COALESCE(pin_set,true) AS pin_set FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Status se mijenja samo poslovođama.' });
    // ⭐ v135.7.502.20.195 (Ivan, 07.06.2026): ne aktiviraj korisnika koji nije postavio PIN (ne bi se mogao
    //   prijaviti, a pojavio bi se u loginu) — direktor mu prvo pošalje link za postavljanje PIN-a.
    if (aktivan && !t.rows[0].pin_set) return res.status(400).json({ error: 'Korisnik prvo mora postaviti PIN (pošalji mu link).' });
    await pool.query('UPDATE radnici SET aktivan=$1 WHERE id=$2', [aktivan, id]);
    try { hotCacheInvalidate('ovlasti:' + id); } catch (_) {}
    auditLog(req, { action: aktivan ? 'korisnik_reaktiviran' : 'korisnik_deaktiviran', target_type: 'korisnik', details: { radnik_id: id }, severity: 'warning' }).catch(() => {});
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Soft-delete poslovođe (mora prvo biti deaktiviran; ne sebe, ne direktora).
app.delete('/api/korisnici/:id', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    if (id === req.user.id) return res.status(400).json({ error: 'Ne možeš obrisati sebe.' });
    const t = await pool.query('SELECT role, aktivan FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Briše se samo poslovođa.' });
    if (t.rows[0].aktivan) return res.status(400).json({ error: 'Prvo deaktiviraj korisnika, pa obriši.' });
    await pool.query('UPDATE radnici SET obrisan=true WHERE id=$1', [id]);
    auditLog(req, { action: 'korisnik_obrisan', target_type: 'korisnik', details: { radnik_id: id }, severity: 'critical' }).catch(() => {});
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v135.7.502.20.189 (Ivan, 07.06.2026): Vrati soft-obrisanog poslovođu (obrisan=false; ostaje deaktiviran).
//   Soft-delete je reverzibilan — podaci nikad nisu fizički brisani. Status nakon vraćanja: Deaktiviran
//   (ili „Čeka PIN" ako nikad nije postavio PIN) → direktor ga onda po želji Reaktivira.
app.put('/api/korisnici/:id/vrati', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const id = parseInt(req.params.id, 10);
    const t = await pool.query('SELECT role FROM radnici WHERE id=$1', [id]);
    if (!t.rows.length) return res.status(404).json({ error: 'Korisnik ne postoji.' });
    if (t.rows[0].role !== 'poslovodja') return res.status(400).json({ error: 'Vraća se samo poslovođa.' });
    await pool.query('UPDATE radnici SET obrisan=false WHERE id=$1', [id]);
    auditLog(req, { action: 'korisnik_vracen', target_type: 'korisnik', details: { radnik_id: id }, severity: 'warning' }).catch(() => {});
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v135.7.502.20.196 (Ivan, 07.06.2026): TRAJNO (hard) brisanje korisnika + svih njegovih podataka.
//   Dvostupanjski i nepovratan: korisnik mora PRVO biti soft-obrisan (obrisan=true). Guard odbija brisanje
//   ako korisnik ima POSLOVNE zapise (sati/materijal/plaće/nalozi…) — to bi pokvarilo povijest i izvještaje
//   (i RESTRICT FK bi ionako blokirao). Briše samo pomoćne (usage/auth) zapise + radnika. CASCADE tablice
//   (push_subscriptions, refresh_tokens, radnici_dokumenti) i SET NULL (vozila/gorivo/…) idu automatski.
//   Sve u transakciji — na bilo kakvu grešku ROLLBACK (ništa se ne obriše napola).
app.delete('/api/korisnici/:id/trajno', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  const id = parseInt(req.params.id, 10);
  if (id === req.user.id) return res.status(400).json({ error: 'Ne možeš obrisati sebe.' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const t = await client.query('SELECT role, COALESCE(obrisan,false) AS obrisan, ime, prezime FROM radnici WHERE id=$1 FOR UPDATE', [id]);
    if (!t.rows.length) { await client.query('ROLLBACK'); return res.status(404).json({ error: 'Korisnik ne postoji.' }); }
    if (t.rows[0].role !== 'poslovodja') { await client.query('ROLLBACK'); return res.status(400).json({ error: 'Trajno se briše samo poslovođa.' }); }
    if (!t.rows[0].obrisan) { await client.query('ROLLBACK'); return res.status(400).json({ error: 'Korisnik mora PRVO biti obrisan (soft), pa tek onda trajno.' }); }

    // Guard: poslovni zapisi → trajno brisanje bi pokvarilo povijest. (Štiti prave radnike od greške.)
    const c = await client.query(`
      SELECT
        (SELECT COUNT(*) FROM sihterica        WHERE radnik_id=$1) AS sati,
        (SELECT COUNT(*) FROM materijal         WHERE radnik_id=$1) AS materijal,
        (SELECT COUNT(*) FROM skela             WHERE radnik_id=$1) AS skela,
        (SELECT COUNT(*) FROM dnevnik           WHERE radnik_id=$1) AS dnevnik,
        (SELECT COUNT(*) FROM zaduznica         WHERE radnik_id=$1) AS zaduznice,
        (SELECT COUNT(*) FROM rezijski_sati     WHERE radnik_id=$1) AS rezijski,
        (SELECT COUNT(*) FROM izmjera           WHERE radnik_id=$1) AS izmjera,
        (SELECT COUNT(*) FROM uredaji_dodjela   WHERE radnik_id=$1) AS uredaji,
        (SELECT COUNT(*) FROM place_parametri   WHERE radnik_id=$1) AS place,
        (SELECT COUNT(*) FROM place_akontacije  WHERE radnik_id=$1) AS akontacije,
        (SELECT COUNT(*) FROM krediti           WHERE radnik_id=$1) AS krediti,
        (SELECT COUNT(*) FROM nalozi            WHERE kreirao_id=$1) AS nalozi
    `, [id]);
    const r = c.rows[0] || {};
    const total = Object.values(r).reduce((s, v) => s + (parseInt(v) || 0), 0);
    if (total > 0) {
      await client.query('ROLLBACK');
      const breakdown = Object.entries(r).filter(([, v]) => parseInt(v) > 0).map(([k, v]) => `${k}: ${v}`).join(', ');
      return res.status(409).json({ error: `Korisnik ima ${total} poslovnih zapisa (${breakdown}) — trajno brisanje bi pokvarilo povijest. Ostaje soft-obrisan (skriven, ne može se prijaviti).` });
    }

    // Čisti pomoćne (usage/auth) zapise koje korisnik ima — ostalo (CASCADE/SET NULL) ide automatski.
    await client.query('DELETE FROM korisnik_pozivnice WHERE radnik_id=$1', [id]);
    await client.query('DELETE FROM ai_potrosnja        WHERE korisnik_id=$1', [id]);
    await client.query('DELETE FROM ai_daily_usage      WHERE user_id=$1', [id]);
    await client.query('DELETE FROM asistent_dopisi     WHERE korisnik_id=$1', [id]);
    await client.query('DELETE FROM asistent_memorija   WHERE korisnik_id=$1', [id]);
    await client.query('DELETE FROM radnici WHERE id=$1', [id]);
    await client.query('COMMIT');
    try { hotCacheInvalidate('ovlasti:' + id); } catch (_) {}
    auditLog(req, { action: 'korisnik_trajno_obrisan', target_type: 'korisnik', details: { radnik_id: id, ime: t.rows[0].ime, prezime: t.rows[0].prezime }, severity: 'critical' }).catch(() => {});
    res.json({ ok: true });
  } catch (e) {
    try { await client.query('ROLLBACK'); } catch (_) {}
    res.status(500).json({ error: 'Trajno brisanje nije uspjelo (ništa nije obrisano): ' + (e.message || '') });
  } finally {
    client.release();
  }
});

// ── JAVNE rute (bez auth) — postavljanje PIN-a preko pozivnice (stranica dolazi u Fazi 3b) ──
app.get('/api/pozivnica/:token', async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT p.tip, p.used_at, p.expires_at, r.ime, r.prezime, COALESCE(r.obrisan,false) AS obrisan
       FROM korisnik_pozivnice p JOIN radnici r ON r.id=p.radnik_id
       WHERE p.token_hash=$1 ORDER BY p.id DESC LIMIT 1`,
      [_pozHash(req.params.token)]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Pozivnica nije valjana.' });
    const p = r.rows[0];
    if (p.used_at) return res.status(410).json({ error: 'Pozivnica je već iskorištena.' });
    if (new Date(p.expires_at) < new Date()) return res.status(410).json({ error: 'Pozivnica je istekla.' });
    // ⭐ v135.7.502.20.206 (Ivan, 07.06.2026): konzistentno s POST — ne prikazuj PIN-ekran za obrisanog korisnika.
    if (p.obrisan) return res.status(410).json({ error: 'Korisnik više ne postoji.' });
    res.json({ ime: p.ime, prezime: p.prezime, tip: p.tip });
  } catch (e) { res.status(500).json({ error: 'Greška.' }); }
});

app.post('/api/pozivnica/:token', async (req, res) => {
  try {
    const pin = req.body && req.body.pin;
    if (!pin || !/^\d{8}$/.test(String(pin))) return res.status(400).json({ error: 'PIN mora imati točno 8 znamenki.' }); // ⭐ v188: sustav koristi 8-znamenkasti PIN (PIN_LENGTH=8)
    const r = await pool.query(
      'SELECT id, radnik_id, used_at, expires_at FROM korisnik_pozivnice WHERE token_hash=$1 ORDER BY id DESC LIMIT 1',
      [_pozHash(req.params.token)]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Pozivnica nije valjana.' });
    const p = r.rows[0];
    if (p.used_at) return res.status(410).json({ error: 'Pozivnica je već iskorištena.' });
    if (new Date(p.expires_at) < new Date()) return res.status(410).json({ error: 'Pozivnica je istekla.' });
    // ⭐ v135.7.502.20.191 (Ivan, 07.06.2026): ne aktiviraj obrisanog korisnika starim linkom (sprječava "uskrsnuće").
    const rr = await pool.query('SELECT COALESCE(obrisan,false) AS obrisan FROM radnici WHERE id=$1', [p.radnik_id]);
    if (!rr.rows.length || rr.rows[0].obrisan) return res.status(410).json({ error: 'Korisnik više ne postoji.' });
    const hash = await bcrypt.hash(String(pin) + (process.env.PIN_PEPPER || ''), BCRYPT_ROUNDS);
    await pool.query('UPDATE radnici SET pin=$1, aktivan=true, pin_set=true WHERE id=$2', [hash, p.radnik_id]);
    await pool.query('UPDATE korisnik_pozivnice SET used_at=NOW() WHERE id=$1', [p.id]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: 'Greška.' }); }
});

