app.get('/api/radnici', auth, async (req, res) => {
  try {
    // ⭐ v421 KRITIČNI FIX (C3, GDPR data minimization): prije je svaki auth korisnik
    //   (uključujući poslovođa Memsur) dobivao OIB, datum_rodjenja, mjesto_rodjenja
    //   svih radnika. To je GDPR breach (least-privilege) + ZOR breach (HR podaci
    //   samo onima koji ih trebaju). HR Dosije modal pokreće samo direktor pa je
    //   ovo bio overkill koji je curio PII.
    //   FIX: vraćaj puni HR set samo ako je req.user.role === 'direktor', inače
    //   bazni podaci (id, ime, prezime, role, je_admin) — što je sve što Memsur
    //   treba (npr. za odabir radnika u sihterici).
    const isDirektor = req.user.role === 'direktor';
    // ⭐ v502.20.30: micro-cache per-role (direktor dobiva PII, ostali ne — različit cache)
    const cacheKey = `radnici:${isDirektor ? 'dir' : 'staff'}`;
    const cached = hotCacheGet(cacheKey);
    if (cached) return res.json(cached);

    const cols = isDirektor
      ? `id, ime, prezime, role, je_admin, dozvola_vrijedi_do, dozvola_napomena, bez_ciscenja_stana,
         lijecnicki_vrijedi_do, lijecnicki_napomena, COALESCE(lijecnicki_notif_isk,false) AS lijecnicki_notif_isk,
         putovnica_vrijedi_do, putovnica_napomena, COALESCE(putovnica_notif_isk,false) AS putovnica_notif_isk,
         oib, datum_rodjenja, mjesto_rodjenja, drzava_rodjenja, datum_hzmo_prijave, vel_odijelo, vel_cipele`
      : `id, ime, prezime, role, je_admin, dozvola_vrijedi_do, dozvola_napomena, bez_ciscenja_stana,
         lijecnicki_vrijedi_do, lijecnicki_napomena, COALESCE(lijecnicki_notif_isk,false) AS lijecnicki_notif_isk,
         putovnica_vrijedi_do, putovnica_napomena, COALESCE(putovnica_notif_isk,false) AS putovnica_notif_isk`;
    // ⭐ v502.20.39 (Ivan, 29.05.2026): DEPLOYMENT-SAFE FALLBACK.
    //   Ako Faza-10 kolone (lijecnicki_*/putovnica_*) još ne postoje (init-db nije pokrenut nakon
    //   deploya), puni SELECT bi pao i SRUŠIO cijeli radnici endpoint → pada i tjedni prikaz
    //   šihterice, radnici tab itd. Zato: probaj puni SELECT, na grešku kolone vrati osnovni
    //   set bez novih kolona (frontend te kolone tretira kao prazne). Self-heal nakon init-db.
    let r;
    try {
      r = await pool.query(`SELECT ${cols} FROM radnici WHERE aktivan=true ORDER BY je_admin DESC, ime`);
    } catch (colErr) {
      console.warn('[radnici] Faza-10 kolone nedostaju — fallback bez njih. Pokreni /api/init-db! :', colErr.message);
      const colsBasic = isDirektor
        ? `id, ime, prezime, role, je_admin, dozvola_vrijedi_do, dozvola_napomena, bez_ciscenja_stana,
           oib, datum_rodjenja, mjesto_rodjenja, drzava_rodjenja, datum_hzmo_prijave, vel_odijelo, vel_cipele`
        : `id, ime, prezime, role, je_admin, dozvola_vrijedi_do, dozvola_napomena, bez_ciscenja_stana`;
      r = await pool.query(`SELECT ${colsBasic} FROM radnici WHERE aktivan=true ORDER BY je_admin DESC, ime`);
    }
    hotCacheSet(cacheKey, r.rows);
    res.json(r.rows);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

