app.post('/api/radnici', auth, permGate('radnici_uredi'), async (req, res) => {
  const { ime, prezime, pin } = req.body;
  if (!ime || !prezime || !pin) return res.status(400).json({ error: 'Nedostaju podaci' });
  try {
    // ⭐ v135.7.496 (Ivan, 19.05.2026): CRITICAL SIGURNOSNI FIX — dodajemo PIN_PEPPER pri kreiranju.
    //   Prije: bcrypt.hash bez peppera. Posljedica: ako je PIN_PEPPER env var postavljen u Railway
    //   (a jest u produkciji), login flow (L3529) poziva compare s pin+pepper protiv hash-bez-peppera
    //   → mismatch → noviradnik se NIKAD nije mogao logirati. Bug otkriven u auditu v135.7.495.
    //   Konzistentno s init-db (L2101), reset-pin (L2729) i lazy upgrade (L3569).
    const PIN_PEPPER_VAL = process.env.PIN_PEPPER || '';
    const h = await bcrypt.hash(String(pin) + PIN_PEPPER_VAL, BCRYPT_ROUNDS);
    const r = await pool.query(
      'INSERT INTO radnici(ime,prezime,pin,role,je_admin) VALUES($1,$2,$3,$4,$5) RETURNING id,ime,prezime,role,je_admin',
      [ime, prezime, h, 'radnik', false]
    );
    res.json(r.rows[0]);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/radnici/:id', auth, permGate('radnici_uredi'), async (req, res) => {
  // ⭐ v135.7.373 (Ivan, 16.05.2026): prošireno HR poljima
  //   Nova polja: oib, datum_rodjenja, mjesto_rodjenja, drzava_rodjenja, datum_hzmo_prijave
  //   Sva opcionalna — null vrijednost znači "korisnik nije unio", app i dalje radi.
  const { ime, prezime, pin, bez_ciscenja_stana,
          oib, datum_rodjenja, mjesto_rodjenja, drzava_rodjenja, datum_hzmo_prijave, vel_odijelo, vel_cipele } = req.body;
  if (!ime || !prezime) return res.status(400).json({ error: 'Nedostaje ime/prezime' });
  
  // Validacija OIB-a (samo ako je unesen — 11 znamenki)
  if (oib !== undefined && oib !== null && oib !== '') {
    const oibStr = String(oib).trim();
    if (!/^\d{11}$/.test(oibStr)) {
      return res.status(400).json({ error: 'OIB mora imati točno 11 znamenki' });
    }
  }
  
  try {
    const sets = ['ime=$1', 'prezime=$2'];
    const vals = [ime, prezime];
    let idx = 3;
    
    if (pin) {
      // ⭐ v135.7.496 (Ivan, 19.05.2026): CRITICAL SIGURNOSNI FIX — PIN_PEPPER pri update-u PIN-a.
      //   Isti bug kao u POST /api/radnici gore — bez peppera login bi pukao.
      //   Posljedica: direktor mijenja PIN radniku → radnik se više ne može logirati.
      const PIN_PEPPER_VAL = process.env.PIN_PEPPER || '';
      const hashed = await bcrypt.hash(String(pin) + PIN_PEPPER_VAL, BCRYPT_ROUNDS);
      sets.push(`pin=$${idx++}`);
      vals.push(hashed);
    }
    
    if (typeof bez_ciscenja_stana === 'boolean') {
      sets.push(`bez_ciscenja_stana=$${idx++}`);
      vals.push(bez_ciscenja_stana);
    }
    
    // ⭐ v373: nova HR polja (sva opcionalna)
    if (oib !== undefined) {
      sets.push(`oib=$${idx++}`);
      vals.push(oib && String(oib).trim() ? String(oib).trim() : null);
    }
    if (datum_rodjenja !== undefined) {
      sets.push(`datum_rodjenja=$${idx++}`);
      vals.push(datum_rodjenja || null);
    }
    if (mjesto_rodjenja !== undefined) {
      sets.push(`mjesto_rodjenja=$${idx++}`);
      vals.push(mjesto_rodjenja && String(mjesto_rodjenja).trim() ? String(mjesto_rodjenja).trim() : null);
    }
    if (drzava_rodjenja !== undefined) {
      sets.push(`drzava_rodjenja=$${idx++}`);
      vals.push(drzava_rodjenja && String(drzava_rodjenja).trim() ? String(drzava_rodjenja).trim() : null);
    }
    if (datum_hzmo_prijave !== undefined) {
      sets.push(`datum_hzmo_prijave=$${idx++}`);
      vals.push(datum_hzmo_prijave || null);
    }
    // ⭐ v1271: velicine odjece/obuce (slobodan tekst — „XL“, „54“, „43“)
    if (vel_odijelo !== undefined) {
      sets.push(`vel_odijelo=$${idx++}`);
      vals.push(vel_odijelo && String(vel_odijelo).trim() ? String(vel_odijelo).trim().slice(0, 20) : null);
    }
    if (vel_cipele !== undefined) {
      sets.push(`vel_cipele=$${idx++}`);
      vals.push(vel_cipele && String(vel_cipele).trim() ? String(vel_cipele).trim().slice(0, 20) : null);
    }
    
    vals.push(req.params.id);
    const r = await pool.query(
      `UPDATE radnici SET ${sets.join(', ')} WHERE id=$${idx} RETURNING *`,
      vals
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Radnik ne postoji' });
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/radnici/:id/aktivan', auth, permGate('radnici_uredi'), async (req, res) => {
  try {
    const check = await pool.query("SELECT role FROM radnici WHERE id=$1", [req.params.id]);
    if (check.rows.length && ['direktor','poslovodja'].includes(check.rows[0].role)) {
      return res.status(403).json({ error: 'Ne možeš obrisati direktora ili poslovođu!' });
    }
    // Deaktivacija: zabilježi datum; Reaktivacija: obriši datum
    // ⭐ v135.7.373 (Ivan): istovremeno sinkroniziraj radnici_dokumenti.arhiviran
    //   Ako se radnik deaktivira (arhivira), svi njegovi dokumenti dobivaju arhiviran=true.
    //   Ako se reaktivira, sve nazad na arhiviran=false. Tako ne gubimo dokumente.
    if (req.body.aktivan === false) {
      await pool.query(
        'UPDATE radnici SET aktivan=false, datum_deaktivacije=(now() AT TIME ZONE $$Europe/Zagreb$$)::date WHERE id=$1', 
        [req.params.id]
      );
      await pool.query(
        'UPDATE radnici_dokumenti SET arhiviran=true WHERE radnik_id=$1',
        [req.params.id]
      ).catch(e => console.warn('[radnici/aktivan/false dok sync]', e.message));
    } else {
      await pool.query(
        'UPDATE radnici SET aktivan=true, datum_deaktivacije=NULL WHERE id=$1', 
        [req.params.id]
      );
      await pool.query(
        'UPDATE radnici_dokumenti SET arhiviran=false WHERE radnik_id=$1',
        [req.params.id]
      ).catch(e => console.warn('[radnici/aktivan/true dok sync]', e.message));
    }
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.373 (Ivan, 16.05.2026): HR DOKUMENTACIJA RADNIKA
// ═══════════════════════════════════════════════════════════════════════════

// Helper: napravi safe folder name za QNAP path (Windows i Linux kompatibilan)
//   "Ivan Čakarić" → "Ivan_Cakaric" (bez dijakritika, bez spaceova, bez specijalnih)
function _hrSafeFolderName(ime, prezime) {
  const raw = `${ime} ${prezime}`.normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')   // makni dijakritike (č → c, š → s)
    .replace(/[^a-zA-Z0-9_-]/g, '_')   // sve nedopušteno → underscore
    .replace(/_+/g, '_')                // multiple underscore → single
    .replace(/^_|_$/g, '');             // trim
  return raw || `radnik_${Date.now()}`;
}

// Helper: timestamp za file name (YYYYMMDD-HHMMSS)
function _hrTimestamp() {
  const d = new Date();
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

