function _loadPDFAssets() {
  if (PDF_ASSETS._loaded) return PDF_ASSETS;
  
  // ─── FONTOVI ───
  // Pokušaj 1: IBM Plex Serif (premium izbor)
  const ibmReg = _pathPDF.join(__dirname, 'IBMPlexSerif-Regular.ttf');
  const ibmBold = _pathPDF.join(__dirname, 'IBMPlexSerif-Bold.ttf');
  const ibmItal = _pathPDF.join(__dirname, 'IBMPlexSerif-Italic.ttf');
  const ibmBItal = _pathPDF.join(__dirname, 'IBMPlexSerif-BoldItalic.ttf');
  
  if (_fsPDF.existsSync(ibmReg) && _fsPDF.existsSync(ibmBold)) {
    PDF_ASSETS.fonts.reg = ibmReg;
    PDF_ASSETS.fonts.bold = ibmBold;
    PDF_ASSETS.fonts.italic = _fsPDF.existsSync(ibmItal) ? ibmItal : ibmReg;
    PDF_ASSETS.fonts.bitalic = _fsPDF.existsSync(ibmBItal) ? ibmBItal : ibmBold;
    PDF_ASSETS.fonts.family = 'IBMPlexSerif';
    console.log('[PDF_ASSETS] IBM Plex Serif fontovi učitani (premium)');
  } else {
    // Pokušaj 2: DejaVuSans fallback (i dalje hrvatski znakovi)
    const djReg = _pathPDF.join(__dirname, 'DejaVuSans.ttf');
    const djBold = _pathPDF.join(__dirname, 'DejaVuSans-Bold.ttf');
    if (_fsPDF.existsSync(djReg) && _fsPDF.existsSync(djBold)) {
      PDF_ASSETS.fonts.reg = djReg;
      PDF_ASSETS.fonts.bold = djBold;
      const djItal = _pathPDF.join(__dirname, 'DejaVuSans-Italic.ttf');
      const djBItal = _pathPDF.join(__dirname, 'DejaVuSans-BoldItalic.ttf');
      PDF_ASSETS.fonts.italic = _fsPDF.existsSync(djItal) ? djItal : djReg;
      PDF_ASSETS.fonts.bitalic = _fsPDF.existsSync(djBItal) ? djBItal : djBold;
      PDF_ASSETS.fonts.family = 'DejaVuSans';
      console.log('[PDF_ASSETS] DejaVuSans fontovi učitani (fallback)');
    } else {
      console.warn('[PDF_ASSETS] Nema custom fontova — fallback Helvetica (hrvatski znakovi neće raditi)');
    }
  }
  
  // ─── LOGO ───
  // logo_light.png = za bordeaux/dark podloge (bijela tipografija)
  // logo_dark.png = za bijelu/cream podlogu (crna tipografija)
  const logoLight = _pathPDF.join(__dirname, 'logo_light.png');
  const logoDark = _pathPDF.join(__dirname, 'logo_dark.png');
  if (_fsPDF.existsSync(logoLight)) {
    PDF_ASSETS.logos.light = logoLight;
    console.log('[PDF_ASSETS] logo_light.png učitan');
  }
  if (_fsPDF.existsSync(logoDark)) {
    PDF_ASSETS.logos.dark = logoDark;
    console.log('[PDF_ASSETS] logo_dark.png učitan');
  }
  // Fallback: stari zbuka_logo.png ako noviji nisu dostupni
  if (!PDF_ASSETS.logos.light && !PDF_ASSETS.logos.dark) {
    const legacy = _pathPDF.join(__dirname, 'zbuka_logo.png');
    if (_fsPDF.existsSync(legacy)) {
      PDF_ASSETS.logos.light = legacy;
      PDF_ASSETS.logos.dark = legacy;
      console.log('[PDF_ASSETS] fallback zbuka_logo.png');
    }
  }
  
  // ⭐ v501.47 (Ivan): SMARTER pecat + potpis search
  //   Problem: Linux je case-sensitive. Ako je fajl u repo-u npr. "zbuka_cakaric_pecat.png"
  //   (mala slova) → kod tražio "Zbuka_Cakaric_Pecat.png" → ne nalazi → fallback placeholder krug.
  //   Rješenje: 3-step search:
  //     1) Tačan path (najbrži)
  //     2) Alternativni nazivi (pecat.png, zbuka_pecat.png, itd)
  //     3) Case-insensitive directory scan (sigurnosna mreža)
  
  const findAssetCaseInsensitive = (kandidati) => {
    // Step 1: tačan path
    for (const c of kandidati) {
      const p = _pathPDF.join(__dirname, c);
      if (_fsPDF.existsSync(p)) return { path: p, found: c };
    }
    // Step 2: case-insensitive scan __dirname
    try {
      const files = _fsPDF.readdirSync(__dirname);
      const lowerKandidati = kandidati.map(k => k.toLowerCase());
      for (const f of files) {
        if (lowerKandidati.includes(f.toLowerCase())) {
          return { path: _pathPDF.join(__dirname, f), found: f, caseInsensitive: true };
        }
      }
    } catch (e) { /* ignore */ }
    return null;
  };
  
  // POTPIS: glavni naziv + alternativni varijacije
  const potpisFound = findAssetCaseInsensitive([
    'potpis_Ivan.png', 'potpis_ivan.png', 'potpis.png',
    'Potpis.png', 'potpis_ivan_cakaric.png', 'ivan_potpis.png'
  ]);
  if (potpisFound) {
    PDF_ASSETS.potpis = potpisFound.path;
    console.log(`[PDF_ASSETS v501.47] potpis učitan: ${potpisFound.found}${potpisFound.caseInsensitive ? ' (case-insensitive match)' : ''}`);
  } else {
    console.warn(`[PDF_ASSETS v501.47] ❌ POTPIS nije nađen u ${__dirname}. Tražio: potpis_Ivan.png + alternative.`);
  }
  
  // PEČAT: glavni naziv + alternativni varijacije
  const pecatFound = findAssetCaseInsensitive([
    'Zbuka_Cakaric_Pecat.png', 'zbuka_cakaric_pecat.png',
    'pecat.png', 'Pecat.png', 'zbuka_pecat.png', 'Zbuka_Pecat.png',
    'cakaric_pecat.png', 'firma_pecat.png',
    'Zbuka-Cakaric-Pecat.png', 'zbuka-cakaric-pecat.png',
    'ZBUKA_CAKARIC_PECAT.png'
  ]);
  if (pecatFound) {
    PDF_ASSETS.pecat = pecatFound.path;
    console.log(`[PDF_ASSETS v501.47] pečat učitan: ${pecatFound.found}${pecatFound.caseInsensitive ? ' (case-insensitive match)' : ''}`);
  } else {
    // DEBUG: list .png fajlova u __dirname da vidimo što ima
    try {
      const allFiles = _fsPDF.readdirSync(__dirname);
      const pngs = allFiles.filter(f => /\.(png|jpg|jpeg)$/i.test(f));
      console.warn(`[PDF_ASSETS v501.47] ❌ PEČAT nije nađen u ${__dirname}.`);
      console.warn(`[PDF_ASSETS v501.47]   PNG/JPG fajlovi u root direktoriju: ${pngs.length ? pngs.join(', ') : '(nema)'}`);
      console.warn(`[PDF_ASSETS v501.47]   Tražio sam: Zbuka_Cakaric_Pecat.png, pecat.png, zbuka_pecat.png i sve case varijante.`);
    } catch (e) { console.warn('[PDF_ASSETS v501.47] readdir fail:', e.message); }
  }
  
  PDF_ASSETS._loaded = true;
  return PDF_ASSETS;
}

// Helper: registriraj fontove na PDFKit doc-u i vrati { FREG, FBOLD, FITAL, FBITAL }
function registerPDFFonts(doc) {
  _loadPDFAssets();
  let FREG = 'Helvetica', FBOLD = 'Helvetica-Bold', FITAL = 'Helvetica-Oblique', FBITAL = 'Helvetica-BoldOblique';
  
  if (PDF_ASSETS.fonts.reg && PDF_ASSETS.fonts.bold) {
    try {
      doc.registerFont('Reg', PDF_ASSETS.fonts.reg);
      doc.registerFont('Bold', PDF_ASSETS.fonts.bold);
      doc.registerFont('Italic', PDF_ASSETS.fonts.italic);
      doc.registerFont('BItalic', PDF_ASSETS.fonts.bitalic);
      FREG = 'Reg'; FBOLD = 'Bold'; FITAL = 'Italic'; FBITAL = 'BItalic';
    } catch (e) {
      console.warn('[registerPDFFonts] font register fail, fallback Helvetica:', e.message);
    }
  }
  
  return { FREG, FBOLD, FITAL, FBITAL, family: PDF_ASSETS.fonts.family };
}

