app.delete('/api/sihterica/:id', auth, staff, async (req, res) => {
  try {
    // ⭐ v501.79 (Ivan, 23.05.2026): GUARD protiv non-numeric ID
    //   Ako neki specifičan delete route (npr. orphan-zapisi) nije registriran prije,
    //   ovaj :id route bi match-ao i parseInt('orphan-zapisi') = NaN → SQL crash.
    //   Defense in depth: explicit validacija da je ID broj.
    const idNum = parseInt(req.params.id, 10);
    if (!Number.isFinite(idNum) || idNum < 1) {
      return res.status(400).json({ error: `Neispravan ID: ${req.params.id}` });
    }
    
    // ⭐ v135.7.26: Prvo dohvati radnik+datum PRIJE delete-a
    const oldR = await pool.query('SELECT radnik_id, datum FROM sihterica WHERE id=$1', [idNum]);
    const old = oldR.rows[0];
    
    const r = await pool.query('DELETE FROM sihterica WHERE id=$1 RETURNING id', [idNum]);
    if (!r.rows.length) return res.status(404).json({ error: 'Nije pronađeno' });
    res.json({ ok: true, deleted: r.rows[0].id });
    
    // ⭐ v135.7.26 BUG FIX: Auto-recalc pretplate sljedećeg mjeseca u pozadini
    if (old) {
      const datumD = new Date(old.datum);
      setImmediate(async () => {
        try {
          await _recalcPretplataKaskadno(old.radnik_id, datumD.getFullYear(), datumD.getMonth() + 1); // ⭐ v238: kaskadno
        } catch(eRecalc) {
          console.warn('[sihterica DELETE] kaskadni recalc fail:', eRecalc.message);
        }
      });
    }
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.121 (BUG FIX SIH-02): Helper za striktno parsanje sati
//   Sprječava: "5h" → 5 (silent strip), "5,5" → 5 (HR locale zarez ignored)
//   Pravilo: input mora biti broj ili string koji točno match-a /^\d+([.,]\d+)?$/.
//   Vraća: parseFloat ili null (ako invalid).
function _parseSatiStrict(input) {
  if (typeof input === 'number') {
    return isFinite(input) ? input : null;
  }
  if (typeof input !== 'string') return null;
  const trimmed = input.trim();
  if (!trimmed) return null;
  // Striktan regex: samo cifre + opcionalno . ili , decimal
  if (!/^\d+([.,]\d+)?$/.test(trimmed)) return null;
  const normalized = trimmed.replace(',', '.'); // HR zarez → točka
  const num = parseFloat(normalized);
  return isFinite(num) ? num : null;
}

app.put('/api/sihterica/:id', auth, staff, async (req, res) => {
  // ⭐ v135.7.121 (BUG FIX SIH-01): pod_naziv može biti EXPLICITLY null (clear)
  //   Razdvajanje:
  //     - undefined: ne mijenjaj
  //     - null ili '': postavi NULL u DB (clear)
  //     - non-empty string: postavi (trimmed, slice 200)
  // ⭐ v135.7.121 (BUG FIX SIH-02): _parseSatiStrict spriječava silent fail za "5h", "5,5"
  const { sati_redovni, gradiliste_id, bolovanje, datum } = req.body;
  const podNazivPresent = Object.prototype.hasOwnProperty.call(req.body, 'pod_naziv');
  let podNazivValue = null;
  if (podNazivPresent) {
    const raw = req.body.pod_naziv;
    if (raw == null) {
      podNazivValue = null;
    } else {
      const trimmed = String(raw).trim().slice(0, 200);
      podNazivValue = trimmed || null;
    }
  }
  
  // Validacija sati (strikt)
  let satiNum = null;
  if (sati_redovni != null) {
    satiNum = _parseSatiStrict(sati_redovni);
    if (satiNum === null) {
      return res.status(400).json({ error: 'Sati moraju biti broj (npr. "8" ili "7.5"). Ne smije sadržavati slova.' });
    }
    if (satiNum < 0 || satiNum > 24) {
      return res.status(400).json({ error: 'Sati moraju biti između 0 i 24' });
    }
  }
  
  // Validacija datuma (ako poslan)
  if (datum !== undefined && datum !== null) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(datum))) {
      return res.status(400).json({ error: 'Datum mora biti u formatu YYYY-MM-DD' });
    }
  }
  
  try {
    const sets = ['updated_at=NOW()'];
    const p = [];
    if (sati_redovni != null) { p.push(satiNum); sets.push(`sati_redovni=$${p.length}`); }
    if (gradiliste_id)        { p.push(gradiliste_id); sets.push(`gradiliste_id=$${p.length}`); }
    if (datum !== undefined && datum !== null) { p.push(datum); sets.push(`datum=$${p.length}`); }
    if (bolovanje !== undefined) {
      const bolBool = bolovanje === true || bolovanje === 'true';
      p.push(bolBool); sets.push(`bolovanje=$${p.length}`);
    }
    if (podNazivPresent) {
      p.push(podNazivValue); sets.push(`pod_naziv=$${p.length}`);
    }
    
    if (sets.length === 1) {
      // Ništa za ažurirati osim updated_at — vrati postojeći
      const r0 = await pool.query('SELECT * FROM sihterica WHERE id=$1', [req.params.id]);
      if (!r0.rows.length) return res.status(404).json({ error: 'Nije pronađeno' });
      return res.json(r0.rows[0]);
    }
    
    p.push(req.params.id);
    let r;
    try {
      r = await pool.query(
        `UPDATE sihterica SET ${sets.join(',')} WHERE id=$${p.length} RETURNING *`, p
      );
    } catch (primaryErr) {
      // Fallback: stara baza bez bolovanje/pod_naziv kolone — makni te SET-ove
      const filtered = sets.filter(s => !s.includes('bolovanje') && !s.includes('pod_naziv'));
      if (filtered.length === sets.length) throw primaryErr;
      const newP = [];
      let pIdx = 1;
      const newSets = ['updated_at=NOW()'];
      if (sati_redovni != null) { newP.push(satiNum); newSets.push(`sati_redovni=$${++pIdx - 1 + 0}`); }
      // Jednostavnije: ponovo build
      const fb = ['updated_at=NOW()'];
      const fbP = [];
      if (sati_redovni != null) { fbP.push(satiNum); fb.push(`sati_redovni=$${fbP.length}`); }
      if (gradiliste_id)        { fbP.push(gradiliste_id); fb.push(`gradiliste_id=$${fbP.length}`); }
      if (datum !== undefined && datum !== null) { fbP.push(datum); fb.push(`datum=$${fbP.length}`); }
      fbP.push(req.params.id);
      r = await pool.query(
        `UPDATE sihterica SET ${fb.join(',')} WHERE id=$${fbP.length} RETURNING *`, fbP
      );
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Nije pronađeno' });
    res.json(r.rows[0]);
    
    // ⭐ v135.7.26 BUG FIX: Auto-recalc pretplate sljedećeg mjeseca u pozadini
    const updated = r.rows[0];
    if (updated && updated.datum) {
      const datumD = new Date(updated.datum);
      setImmediate(async () => {
        try {
          await _recalcPretplataKaskadno(updated.radnik_id, datumD.getFullYear(), datumD.getMonth() + 1); // ⭐ v238: kaskadno
        } catch(eRecalc) {
          console.warn('[sihterica PUT] kaskadni recalc fail:', eRecalc.message);
        }
      });
    }
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Export šihterica filtrirano po gradilištu
app.get('/api/export/sihterica-grad', auth, staff, async (req, res) => {
  const { gradiliste_id, od, do: doo } = req.query;
  try {
    // FUTURE-PROOF-2030: [EXCELJS] ExcelJS lib — koristi se EKSTENZIVNO za Excel exporte
    //   PROVJERI: github.com/exceljs/exceljs (security advisories, breaking changes)
    //   FIX: ako velikI breaking change, alternativa je 'xlsx-populate' ili 'node-xlsx'.
    //        Migracija je big lift jer ima ~10 helper funkcija koje koriste ExcelJS API.
    //   POTENTIAL ISSUE: ExcelJS nije aktivno održavan zadnjih godina (provjeri commits)
    //   LAST_VERIFIED: 2026-05-01
    const ExcelJS = require('exceljs');
    const wb = new ExcelJS.Workbook();
    const C = { RED:'FFCC0000', BLUE:'FF1F4E79', WHITE:'FFFFFFFF', GREY:'FFD9D9D9', LIGHT:'FFF2F2F2' };
    const fill = h => ({type:'pattern',pattern:'solid',fgColor:{argb:h}});
    const font = (sz=10,bold=false,col='FF000000') => ({name:'Arial',size:sz,bold,color:{argb:col}});
    const aln  = (h='center') => ({horizontal:h,vertical:'middle'});
    const brd  = {top:{style:'thin',color:{argb:'FFAAAAAA'}},bottom:{style:'thin',color:{argb:'FFAAAAAA'}},
                  left:{style:'thin',color:{argb:'FFAAAAAA'}},right:{style:'thin',color:{argb:'FFAAAAAA'}}};

    // Dohvati gradilišta
    let gradQ;
    if (gradiliste_id) {
      gradQ = await pool.query('SELECT id,naziv FROM gradilista WHERE id=$1', [gradiliste_id]);
    } else {
      gradQ = await pool.query('SELECT id,naziv FROM gradilista ORDER BY naziv');
    }

    for (const grad of gradQ.rows) {
      const sih = await pool.query(`
        SELECT s.datum, r.ime||' '||r.prezime AS radnik, s.sati_redovni, s.bolovanje,
               g.naziv AS gradiliste
        FROM sihterica s
        JOIN radnici r ON r.id=s.radnik_id
        JOIN gradilista g ON g.id=s.gradiliste_id
        WHERE s.gradiliste_id=$1
          ${od  ? 'AND s.datum >= $2' : ''}
          ${doo ? 'AND s.datum <= $' + (od?3:2) : ''}
        ORDER BY s.datum DESC, r.prezime, r.ime
      `, [grad.id, ...(od?[od]:[]), ...(doo?[doo]:[])]);

      if (!sih.rows.length) continue;
      const ws = wb.addWorksheet(safeSheetName(grad.naziv));
      ws.pageSetup = {paperSize:9,orientation:'landscape',fitToPage:true,fitToWidth:1};
      ws.columns = [{width:14},{width:24},{width:10},{width:10}];

      ws.mergeCells('A1:D1');
      const tc = ws.getCell('A1');
      tc.value = 'Šihterica — ' + grad.naziv + (od ? '  (' + od + ' – ' + (doo||'danas') + ')' : '');
      tc.fill=fill(C.RED); tc.font=font(12,true,'FFFFFFFF'); tc.alignment=aln('left');
      ws.getRow(1).height = 22;

      ['Datum','Radnik','Sati','Bolovanje'].forEach((h,i) => {
        const c = ws.getCell(2,i+1);
        c.value=h; c.fill=fill(C.BLUE); c.font=font(10,true,'FFFFFFFF');
        c.alignment=aln(); c.border=brd;
      });
      ws.getRow(2).height = 16;

      let ukSati = 0;
      sih.rows.forEach((e,i) => {
        const r = i+3;
        const bg = i%2===0 ? C.WHITE : C.LIGHT;
        const sati = parseFloat(e.sati_redovni)||0;
        ukSati += sati;
        [fmtDate(new Date(e.datum)), e.radnik, e.bolovanje ? 0 : sati, e.bolovanje ? 'BOL.' : '']
          .forEach((v,ci) => {
            const c = ws.getCell(r,ci+1);
            c.value=v; c.fill=fill(bg); c.font=font(10,false,'FF000000');
            c.alignment=ci===1?aln('left'):aln(); c.border=brd;
          });
        ws.getRow(r).height = 15;
      });

      const sumR = sih.rows.length+3;
      ws.mergeCells(sumR,1,sumR,4);
      const sc = ws.getCell(sumR,1);
      sc.value = 'Ukupno: ' + sih.rows.length + ' dana  |  ' + ukSati.toFixed(1) + ' sati';
      sc.fill=fill(C.GREY); sc.font=font(10,true); sc.alignment=aln('left');
      ws.getRow(sumR).height=16;
    }

    let buf;
    try {
      // ⭐ FIX BUG: ako nema niti jednog gradilišta sa zapisima, workbook ostaje
      //    bez sheet-ova → ExcelJS generira korumpirani ~5KB file koji se ne može otvoriti.
      if (wb.worksheets.length === 0) {
        const ws = wb.addWorksheet('Nema zapisa');
        ws.getCell('A1').value = 'Nema zapisa za odabrani period';
        ws.getCell('A1').font = { name: 'Arial', size: 12, bold: true };
        ws.getCell('A2').value = `Period: ${od || 'sve'} → ${doo || 'sve'}`;
        ws.getCell('A2').font = { name: 'Arial', size: 10, italic: true };
        ws.getColumn('A').width = 50;
        console.warn(`[export sihterica-grad] 0 zapisa za period ${od}–${doo} — generiran prazan workbook s fallback sheet-om`);
      }
      buf = await wb.xlsx.writeBuffer();
    } catch(wbErr) {
      console.error('[export sihterica-grad] writeBuffer fail:', wbErr.message, wbErr.stack);
      return res.status(500).json({ error: 'Greška pri generiranju Excela: ' + wbErr.message });
    }
    if (!buf || buf.byteLength < 100) {
      console.error('[export sihterica-grad] empty buffer (', gradQ.rows.length, 'gradilišta, vjerojatno bez šihterice)');
      return res.status(404).json({ error: 'Nema podataka šihterice za odabrana gradilišta' });
    }
    
    const fname = 'Sihterica' + (gradiliste_id ? '-grad' : '-sva') + '-' + _ymd(new Date()) + '.xlsx';
    setImmediate(() => {
      qnapUploadExcel(Buffer.from(buf), 'Sihterica/Sihterica-po-gradilistima.xlsx')
        .catch(qErr => console.warn('[export sihterica-grad] QNAP fail:', qErr.message));
    });
    // ⭐ v135.7.57: Streaming + gzip kompresija
    sendExcelResponse(req, res, buf, fname);
  } catch(e) {
    console.error('[export sihterica-grad] FATAL:', e.message, e.stack);
    if (!res.headersSent) res.status(500).json({ error: 'Server greška: ' + e.message });
  }
});

