app.post('/api/skela/elementi', auth, staff, async (req, res) => {
  const { gradiliste_id, naziv, kolicina, tip } = req.body;
  // tip = 'izlaz' (povećaj) | 'povrat' (smanji)
  if (!gradiliste_id || !naziv || !kolicina)
    return res.status(400).json({ error: 'Nedostaju podaci' });
  // AUDIT FIX 1.4.3: parseInt + raspon validacija
  const kolNum = parseInt(kolicina);
  if (isNaN(kolNum) || kolNum < 0 || kolNum > 100000) {
    return res.status(400).json({ error: 'Količina mora biti 0-100000' });
  }
  if (!['izlaz', 'povrat'].includes(tip)) {
    return res.status(400).json({ error: 'Tip mora biti "izlaz" ili "povrat"' });
  }
  try {
    const delta = tip === 'povrat' ? -kolNum : kolNum;
    const r = await pool.query(`
      INSERT INTO skela_elementi(gradiliste_id, naziv, kolicina, updated_by, updated_at)
      VALUES($1, $2, GREATEST(0, $3::int), $4, NOW())
      ON CONFLICT(gradiliste_id, naziv) DO UPDATE
        SET kolicina = GREATEST(0, skela_elementi.kolicina + $3::int),
            updated_by = $4,
            updated_at = NOW()
      RETURNING *
    `, [gradiliste_id, String(naziv).trim().slice(0, 100), delta, req.user.id]);
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

