app.post('/api/postavke/doprinosi', auth, direktor, async (req, res) => {
  try {
    const model = (req.body.model === 'postotak') ? 'postotak' : 'flat';
    const bruto_dod = Math.max(0, parseFloat(req.body.bruto_dod) || 5.50);
    let postotak = parseFloat(req.body.postotak);
    if (!Number.isFinite(postotak) || postotak <= 0) postotak = 16.5;
    postotak = Math.min(100, postotak);
    const ups = (k, v) => pool.query(
      `INSERT INTO postavke(kljuc, vrijednost, updated_at) VALUES($1,$2,NOW())
       ON CONFLICT(kljuc) DO UPDATE SET vrijednost=$2, updated_at=NOW()`, [k, String(v)]);
    await ups('doprinosi_model', model);
    await ups('bruto_dodatak', bruto_dod);
    await ups('doprinosi_postotak', postotak);
    res.json({ ok: true, model, bruto_dod, postotak });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

