// Statistika radnika
app.get('/api/radnici/:id/statistika', auth, async (req, res) => {
  // ⭐ v720 (Ivan): granularno umjesto direktor-only. Ovlast 'radnici' = smije sate/dane;
  //   ovlast 'radnici_zarade' (ili direktor) = i € (bruto, bonusi, akontacije, kredit, satnica).
  const rid = req.params.id;
  const god = req.query.godina || new Date().getFullYear();
  let vidiZarade = false;
  try {
    if (req.user.role === 'direktor') vidiZarade = true;
    else {
      const { role, ovlasti } = await _loadOvlasti(req.user.id);
      if (!hasPerm(role, ovlasti, 'radnici')) return res.status(403).json({ error: 'Nemaš ovlast za radnike' });
      vidiZarade = hasPerm(role, ovlasti, 'radnici_zarade');
    }
  } catch (e) { return res.status(500).json({ error: 'Greška provjere ovlasti' }); }
  try {
    const [sih, place, akont, kredit, placeCalc] = await Promise.all([
      pool.query(`
        SELECT EXTRACT(MONTH FROM datum)::int AS mj,
               SUM(CASE WHEN bolovanje OR COALESCE(godisnji,false) OR COALESCE(ne_radi,false) THEN 0 ELSE sati_redovni END) AS sati,
               COUNT(*) FILTER (WHERE bolovanje) AS dani_bol,
               COUNT(*) FILTER (WHERE COALESCE(godisnji,false)) AS dani_god
        FROM sihterica WHERE radnik_id=$1 AND EXTRACT(YEAR FROM datum)=$2
        GROUP BY mj ORDER BY mj`, [rid, god]),
      pool.query(`
        SELECT godina, mjesec, satnica, bonus, placa_racun, terenska, ciscenje, pretplata, naknada_bolovanje,
               COALESCE(isplata_prosli_mj,0) AS isplata_prosli_mj
        FROM place_parametri WHERE radnik_id=$1 AND godina=$2
        ORDER BY mjesec`, [rid, god]),
      pool.query(`
        SELECT SUM(iznos) AS uk FROM place_akontacije
        WHERE radnik_id=$1 AND godina=$2`, [rid, god]),
      pool.query(`
        SELECT k.ukupno, COALESCE(SUM(o.iznos),0) AS otplaceno
        FROM krediti k LEFT JOIN krediti_otplate o ON o.kredit_id=k.id
        WHERE k.radnik_id=$1 AND k.aktivan=true GROUP BY k.id LIMIT 1`, [rid]),
      // Ukupna bruto — sati po mj × satnica + bonus + bolovanje
      pool.query(`
        SELECT
          EXTRACT(MONTH FROM s.datum)::int AS mj,
          COALESCE(SUM(CASE WHEN s.bolovanje THEN 0 ELSE s.sati_redovni END),0) AS sati,
          COALESCE(MAX(p.satnica), 8) AS satnica,
          COALESCE(MAX(p.bonus), 0) AS bonus,
          COALESCE(MAX(p.naknada_bolovanje), 0) AS bolovanje,
          COALESCE(MAX(p.godisnji), 0) AS godisnji
        FROM sihterica s
        LEFT JOIN place_parametri p
          ON p.radnik_id=s.radnik_id
          AND p.godina=EXTRACT(YEAR FROM s.datum)::int
          AND p.mjesec=EXTRACT(MONTH FROM s.datum)::int
        WHERE s.radnik_id=$1 AND EXTRACT(YEAR FROM s.datum)=$2
        GROUP BY EXTRACT(MONTH FROM s.datum)::int
        ORDER BY mj`, [rid, god])
    ]);
    const ukSati = sih.rows.reduce((s,r) => s + parseFloat(r.sati||0), 0);
    const ukBol  = sih.rows.reduce((s,r) => s + parseInt(r.dani_bol||0), 0);

    // Ukupni bruto = zbroj po svim mjesecima gdje ima sati
    let ukBruto = 0, ukBonus = 0, ukBolovanje = 0;
    let ukGodisnji = 0;
    placeCalc.rows.forEach(r => {
      const sati      = parseFloat(r.sati||0);
      const satnica   = parseFloat(r.satnica||8);
      const bonus     = parseFloat(r.bonus||0);
      const bol       = parseFloat(r.bolovanje||0);
      const god_iznos = parseFloat(r.godisnji||0);
      ukBruto    += sati * satnica + bonus + bol + god_iznos;
      ukBonus    += bonus;
      ukBolovanje += bol;
      ukGodisnji  += god_iznos;
    });
    // Fallback ako nema place_parametri uopće
    if (ukBruto === 0 && ukSati > 0) ukBruto = ukSati * 8;
    const out = {
      sati_po_mj: sih.rows,
      ukupno_sati: ukSati,
      dani_bolovanje: ukBol,
      dani_godisnji: (sih.rows || []).reduce((a9, r9) => a9 + (parseInt(r9.dani_god) || 0), 0),   // ⭐ v883 (Ivan)
      place: place.rows,
      ukupno_akontacije: parseFloat(akont.rows[0]?.uk||0),
      // AUDIT FIX 4.1.5: ukloni dvostruki ukupno_godisnji ključ - koristi placeCalc verziju (točniji izvor)
      ukupno_godisnji: placeCalc.rows.reduce((s,r) => s + parseFloat(r.godisnji||0), 0),
      kredit: kredit.rows[0] || null,
      ukupno_bruto: ukBruto,
      ukupno_bonus: ukBonus,
      ukupno_bolovanje: ukBolovanje,
    };
    if (!vidiZarade) {  // ⭐ v720: bez ovlasti radnici_zarade → samo sati/dani, € polja se BRIŠU (klijent ih sam ne prikaže)
      out.place = []; out.kredit = null;
      out.ukupno_akontacije = 0; out.ukupno_godisnji = 0; out.ukupno_bruto = 0; out.ukupno_bonus = 0; out.ukupno_bolovanje = 0;
    }
    res.json(out);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── NALOZI ───────────────────────────────────────────────────────────────────

app.get('/api/nalozi', auth, staff, async (req, res) => {
  try {
    const { rijesen, gradiliste_id } = req.query;
    let q = `
      SELECT n.*, r.ime||' '||r.prezime AS kreirao_ime,
             rr.ime||' '||rr.prezime AS rijesen_ime,
             g.naziv AS naziv_gradilista,
             COALESCE(json_agg(f.id ORDER BY f.id) FILTER (WHERE f.id IS NOT NULL), '[]') AS foto_ids
      FROM nalozi n
      LEFT JOIN radnici r ON r.id=n.kreirao_id
      LEFT JOIN radnici rr ON rr.id=n.rijesen_id
      LEFT JOIN gradilista g ON g.id=n.gradiliste_id
      LEFT JOIN nalozi_foto f ON f.nalog_id=n.id
      WHERE 1=1`;
    const p = [];
    if (rijesen !== undefined) { p.push(rijesen==='1'); q += ` AND n.rijesen=$${p.length}`; }
    if (gradiliste_id) { p.push(gradiliste_id); q += ` AND n.gradiliste_id=$${p.length}`; }
    q += ' GROUP BY n.id, r.ime, r.prezime, rr.ime, rr.prezime, g.naziv ORDER BY n.rijesen ASC, n.created_at DESC';
    const rows = await pool.query(q, p);
    res.json(rows.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/nalozi', auth, staff, async (req, res) => {
  const { gradiliste_id, komentar, fotos, lat, lng, maps_url } = req.body;
  // AUDIT FIX 2.2.1: limit komentar (5KB) i broj fotki (max 10 po nalogu)
  const komentarSafe = komentar ? String(komentar).slice(0, 5000) : '';
  const fotosSafe = Array.isArray(fotos) ? fotos.slice(0, 10) : [];
  // ⭐ v456 (Ivan): Google Maps lokacija — validiraj lat/lng (parseFloat + raspon, inače NULL)
  const _pf = (v, max) => { const n = parseFloat(v); return (Number.isFinite(n) && Math.abs(n) <= max) ? n : null; };
  const latNum = _pf(lat, 90);
  const lngNum = _pf(lng, 180);
  // ⭐ v459 (Ivan): sirovi Maps link — samo http(s), max 600 znakova, inače NULL
  // ⭐ v460 (Ivan): + ograniči na Google Maps domene (ne bilo koji URL) — sigurnosno otvrdnjavanje
  const _mu = (typeof maps_url === 'string') ? maps_url.trim() : '';
  const mapsUrlSafe = (/^https?:\/\//i.test(_mu) && /(google\.[a-z.]+\/maps|maps\.app\.goo\.gl|goo\.gl\/maps|maps\.google\.)/i.test(_mu))
    ? _mu.slice(0, 600) : null;
  try {
    const n = await pool.query(
      `INSERT INTO nalozi(gradiliste_id,kreirao_id,komentar,lat,lng,maps_url) VALUES($1,$2,$3,$4,$5,$6) RETURNING *`,
      [gradiliste_id||null, req.user.id, komentarSafe, latNum, lngNum, mapsUrlSafe]
    );
    const nalogId = n.rows[0].id;
    // Spremi fotke + ⭐ v482: paralelni QNAP upload + auto-strip base64
    //   PROBLEM koji rješavamo: nalozi_foto je BILA JEDINA foto-tablica bez QNAP fallback-a.
    //   Sve druge (materijal, dnevnik, smece, uredaji, izmjera) imaju qnap_path + b2_path
    //   i auto-strip cron na 730d. Bez ovoga, nalozi_foto.foto_base64 raste zauvijek u DB-u
    //   (60 MB/god → ~1 GB nakon 15 god). FIX: paralelno upload na QNAP, čim uspije →
    //   UPDATE nalozi_foto.qnap_path + foto_base64=NULL. Lazy load fallback u GET endpointu
    //   ispod (L8248+) već znade QNAP fetch ako foto_base64 NULL.
    //   GRACEFUL: ako QNAP fail (network/auth/disk), foto_base64 ostaje u DB-u (legacy mode),
    //   sve i dalje radi. Sljedeći nalog će opet pokušati upload.
    const insertedFotos = [];  // [{id, base64}] za async QNAP upload
    if (fotosSafe.length) {
      for (const f of fotosSafe) {
        const fr = await pool.query(
          'INSERT INTO nalozi_foto(nalog_id,foto_base64) VALUES($1,$2) RETURNING id',
          [nalogId, f]
        );
        insertedFotos.push({ id: fr.rows[0].id, base64: f });
      }
    }
    res.json(n.rows[0]);
    // ⭐ v482: fire-and-forget QNAP upload za sve foto-e (paralelno s response-om — ne blokira UI)
    if (insertedFotos.length && process.env.QNAP_WEBDAV_URL) {
      setImmediate(async () => {
        try {
          // Dohvati gradilište naziv za safe folder path
          const gR = gradiliste_id
            ? await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id]).catch(() => ({ rows: [] }))
            : { rows: [] };
          const gradNaziv = (gR.rows[0]?.naziv || 'bez-gradilista').replace(/[/\\:*?"<>|]/g, '_').trim();
          for (const foto of insertedFotos) {
            try {
              // Decode base64 → Buffer (skini data:image/...;base64, prefix)
              const m = foto.base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
              const cleanB64 = m ? m[1] : foto.base64;
              const buf = Buffer.from(cleanB64, 'base64');
              const ts = Date.now();
              const qnapPath = `Nalozi/${gradNaziv}/${nalogId}/foto_${foto.id}_${ts}.jpg`;
              
              // ⭐ v502.20.10 (Ivan, 27.05.2026): paralelni QNAP + B2 upload
              //   PRIJE: samo qnapUploadImage (radio B2 fire-and-forget, ali path se gubio)
              //   SAD: Promise.allSettled — uhvati i B2 path → upiši u DB
              //   Kad QNAP down, B2 fallback radi (reverseSync popuni QNAP kasnije)
              const [qnapRes, b2Res] = await Promise.allSettled([
                qnapUploadImage(buf, qnapPath),
                b2Enabled() ? b2Upload(buf, qnapPath, 'image/jpeg') : Promise.resolve(null)
              ]);
              const qnapOk = qnapRes.status === 'fulfilled' ? qnapRes.value : null;
              const b2Ok   = b2Res.status === 'fulfilled' ? b2Res.value : null;
              
              if (qnapOk || b2Ok) {
                // Strip base64 + populiraj qnap_path i b2_path (oba ako uspjeli)
                await pool.query(
                  'UPDATE nalozi_foto SET qnap_path=$1, b2_path=$2, foto_base64=NULL WHERE id=$3',
                  [qnapOk || null, b2Ok, foto.id]
                ).catch(e => console.warn(`[nalozi DB UPDATE] foto ${foto.id}:`, e.message));
                console.log(`[nalozi upload] foto ${foto.id}: QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Ok?'OK':'FAIL'}`);
              }
            } catch (eFoto) {
              console.warn(`[nalozi upload] foto ${foto.id}:`, eFoto.message);
            }
          }
        } catch (eOuter) {
          console.warn('[nalozi QNAP upload outer]', eOuter.message);
        }
      });
    }
    // ⭐ v316 (Ivan): Push bidirekcionalno — sendPush(req.user.id, ...) filtrira kreatora 
    //   pa drugi user dobije push:
    //     • Memsur kreira → Ivan dobije push
    //     • Ivan kreira → Memsur dobije push
    const gR3 = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id||null]).catch(()=>({rows:[]}));
    const gN3 = gR3.rows[0]?.naziv || 'gradilištu';
    const komTxt = komentarSafe ? ` — ${komentarSafe.slice(0,60)}` : '';
    sendPush(req.user.id, '📋 Novi radni nalog', `${req.user.ime} ${req.user.prezime} · ${gN3}${komTxt}`, '/?tab=nalozi', 'nalozi');
  } catch(e) { res.status(500).json({ error: e.message }); }
});

