app.delete('/api/nalozi/:id', auth, staff, async (req, res) => {
  try {
    // ⭐ v639 (Ivan, audit F10): pokupi foto storage putanje PRIJE brisanja. nalozi_foto ima
    //   ON DELETE CASCADE pa se DB redovi obrišu sami — ALI to NE briše QNAP/B2 FAJLOVE (POST ih
    //   uploada + strip-a base64). PRIJE: DELETE naloga je ostavljao sve fotke orphan na storageu
    //   zauvijek (za razliku od materijal/dnevnik/smece/uredaji DELETE-ova koji čiste storage).
    //   Brisanje naloga je česta akcija → aktivno curenje kroz godine. SAD: fetch putanje → DELETE
    //   (CASCADE očisti DB redove) → background QNAP+B2 cleanup (ne blokira response).
    let fotoRows = [];
    try {
      const fr = await pool.query('SELECT qnap_path, b2_path FROM nalozi_foto WHERE nalog_id=$1', [req.params.id]);
      fotoRows = fr.rows || [];
    } catch (e) { /* stara shema bez qnap_path/b2_path — nema storage fajlova za čistiti */ }

    await pool.query('DELETE FROM nalozi WHERE id=$1', [req.params.id]);
    res.json({ ok: true });

    const qnapPaths = fotoRows.map(f => f.qnap_path).filter(Boolean);
    const b2Paths   = fotoRows.map(f => f.b2_path).filter(Boolean);
    if (qnapPaths.length && process.env.QNAP_WEBDAV_URL && typeof qnapDeleteFile === 'function') {
      setImmediate(async () => {
        for (const p of qnapPaths) {
          try { await qnapDeleteFile(p); } catch (e) { console.warn('[nalozi DELETE QNAP]', p, e.message); }
        }
      });
    }
    if (b2Paths.length && b2Enabled() && typeof b2Delete === 'function') {
      setImmediate(async () => {
        for (const p of b2Paths) {
          try { await b2Delete(p); } catch (e) { console.warn('[nalozi DELETE B2]', p, e.message); }
        }
      });
    }
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v461 (Ivan): naknadna izmjena naloga — opis (komentar) + lokacija (lat/lng/maps_url).
//   Iste validacije kao POST. Ne dira fotke ni status (rijesen). Auth+staff (nema novca u nalogu).
app.put('/api/nalozi/:id', auth, staff, async (req, res) => {
  try {
    const { komentar, lat, lng, maps_url } = req.body;
    const komentarSafe = (komentar != null) ? String(komentar).slice(0, 5000) : '';
    const _pf = (v, max) => { const n = parseFloat(v); return (Number.isFinite(n) && Math.abs(n) <= max) ? n : null; };
    const latNum = _pf(lat, 90);
    const lngNum = _pf(lng, 180);
    const _mu = (typeof maps_url === 'string') ? maps_url.trim() : '';
    const mapsUrlSafe = (/^https?:\/\//i.test(_mu) && /(google\.[a-z.]+\/maps|maps\.app\.goo\.gl|goo\.gl\/maps|maps\.google\.)/i.test(_mu))
      ? _mu.slice(0, 600) : null;
    const r = await pool.query(
      `UPDATE nalozi SET komentar=$1, lat=$2, lng=$3, maps_url=$4 WHERE id=$5 RETURNING *`,
      [komentarSafe, latNum, lngNum, mapsUrlSafe, req.params.id]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Nalog nije pronađen' });
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/nalozi/:id/foto/:fid', auth, async (req, res) => {
  try {
    // ⭐ v482 (Ivan, 19.05.2026): QNAP fallback (slično kao /materijal/:id/foto L6760+)
    // ⭐ v502.20.10 (Ivan, 27.05.2026): + B2 fallback (čita b2_path uz qnap_path)
    //   Sad nalozi foto radi i kad QNAP down (preko fetchImageWithFallback s circuit breaker)
    const r = await pool.query(
      'SELECT foto_base64, qnap_path, b2_path FROM nalozi_foto WHERE id=$1 AND nalog_id=$2',
      [req.params.fid, req.params.id]
    );
    if (!r.rows.length) return res.status(404).json({error:'Nema slike'});
    const row = r.rows[0];
    // 1. Cache iz baze (legacy + nedavno kreirani prije upload-a)
    if (row.foto_base64) return res.json({ foto_base64: row.foto_base64 });
    // 2. QNAP→B2 fallback preko unified fetchImageWithFallback (circuit breaker uračunan)
    if (row.qnap_path || row.b2_path) {
      try {
        const buf = await fetchImageWithFallback(row.qnap_path, row.b2_path);
        if (buf) {
          const isPng = (row.qnap_path || row.b2_path || '').toLowerCase().endsWith('.png');
          return res.json({ foto_base64: `data:${isPng ? 'image/png' : 'image/jpeg'};base64,` + buf.toString('base64') });
        }
      } catch (e) {
        console.warn(`[nalozi foto fallback] ${req.params.fid}:`, e.message);
      }
    }
    return res.status(404).json({error:'Nema slike'});
  } catch(e) { res.status(500).json({ error: e.message }); }
});

