// ⭐ v460 (Ivan): PROFESIONALNI PDF IZVOZ RADNOG NALOGA ──────────────────────────
//   Isti brand kao live pregled (bordeaux/cream/gold). pdfkit + DejaVu (HR znakovi),
//   logo, status, opis, lokacija (klikabilan Maps link), fotodokumentacija (grid),
//   footer s brojem stranice. Koristi se iz kartice naloga (gumb "📄 PDF").

async function _nalogFotoBuffer(fid) {
  try {
    const r = await pool.query('SELECT foto_base64, qnap_path, b2_path FROM nalozi_foto WHERE id=$1', [fid]);
    if (!r.rows.length) return null;
    const row = r.rows[0];
    let buf = null;
    if (row.foto_base64) {
      const m = /^data:[^;]+;base64,(.*)$/s.exec(row.foto_base64);
      buf = Buffer.from(m ? m[1] : row.foto_base64, 'base64');
    } else if (row.qnap_path || row.b2_path) {
      buf = await fetchImageWithFallback(row.qnap_path, row.b2_path || null).catch(() => null);
    }
    if (!buf || !buf.length) return null;
    try { buf = await _toPdfSafeImage(buf); } catch (_) {}
    return buf;
  } catch (_) { return null; }
}

async function _nalogPdfBuffer(n, fotos) {
  const PDFDocument = require('pdfkit');
  const path2 = require('path');
  const FREG_P = path2.join(__dirname, 'DejaVuSans.ttf');
  const FBOLD_P = path2.join(__dirname, 'DejaVuSans-Bold.ttf');
  const hasFonts = _fs.existsSync(FREG_P) && _fs.existsSync(FBOLD_P);

  const MJ = ['siječnja','veljače','ožujka','travnja','svibnja','lipnja','srpnja','kolovoza','rujna','listopada','studenoga','prosinca'];
  const fmt = (d) => { const dt = new Date(d); return isNaN(dt) ? '—' : `${dt.getDate()}. ${MJ[dt.getMonth()]} ${dt.getFullYear()}.`; };
  const fmtT = (d) => { const dt = new Date(d); if (isNaN(dt)) return '—'; const hh=String(dt.getHours()).padStart(2,'0'); const mm=String(dt.getMinutes()).padStart(2,'0'); return `${dt.getDate()}. ${MJ[dt.getMonth()]} ${dt.getFullYear()}. u ${hh}:${mm}`; };

  // Brand paleta
  const BORD='#7a1a1a', BORDD='#4a0e0e', CREAM='#faf5ea', CREAM2='#f3ead4', GOLD='#a8842c', GOLDL='#c9a96b', INK='#241d1b', INK2='#5e544d', INK3='#8a7d72', LINE='#e2d6bd', GRN='#1f7a44';

  const rijesen = !!n.rijesen;
  const naslov = (n.naziv_gradilista && String(n.naziv_gradilista).trim()) ? String(n.naziv_gradilista).trim() : 'Radni nalog';
  const adresa = (n.adresa_gradilista && String(n.adresa_gradilista).trim()) ? String(n.adresa_gradilista).trim() : '';
  const kreirao = (n.kreirao_ime && String(n.kreirao_ime).trim()) ? String(n.kreirao_ime).trim() : '—';
  const hasCoord = (n.lat != null && n.lng != null);
  const hasMapsUrl = !!(n.maps_url && String(n.maps_url).trim());
  const mapsLink = hasMapsUrl ? String(n.maps_url).trim() : (hasCoord ? `https://www.google.com/maps?q=${n.lat},${n.lng}` : '');

  // Pre-fetch fotki (paralelno, batch)
  const photoBufs = [];
  if (fotos && fotos.length) {
    const ids = fotos.slice(0, 12);
    const B = 6;
    for (let i=0;i<ids.length;i+=B) {
      const chunk = ids.slice(i, i+B);
      const bufs = await Promise.all(chunk.map(id => _nalogFotoBuffer(id)));
      for (const b of bufs) if (b) photoBufs.push(b);
    }
  }

  const doc = new PDFDocument({ size:'A4', margin:0, bufferPages:true, info:{ Title:`Radni nalog br. ${n.id}`, Author:'ŽBUKA Čakarić d.o.o.' } });
  const chunks = [];
  doc.on('data', c => chunks.push(c));
  const done = new Promise(res => doc.on('end', () => res(Buffer.concat(chunks))));

  const W = doc.page.width, H = doc.page.height;    // A4: 595.28 x 841.89
  const M = 46, CW = W - M*2;
  const BOTTOM = H - 56;
  const F  = () => hasFonts ? doc.font(FREG_P)  : doc.font('Helvetica');
  const FB = () => hasFonts ? doc.font(FBOLD_P) : doc.font('Helvetica-Bold');

  const ensure = (need) => { if (doc.y + need > BOTTOM) { doc.addPage({ size:'A4', margin:0 }); doc.y = 54; } };
  const sectionHead = (kick, title) => {
    ensure(64);
    const y = doc.y;
    FB().fontSize(8.5).fillColor(BORD).text(kick.toUpperCase(), M, y, { characterSpacing:2.4 });
    FB().fontSize(19).fillColor(INK).text(title, M, doc.y + 2, { width: CW });
    const ry = doc.y + 6;
    doc.rect(M, ry, 46, 2).fillColor(BORD).fill();
    doc.circle(M+54, ry+1, 2.2).fillColor(GOLD).fill();
    doc.y = ry + 16;
  };

  // ── HEADER BAND (cream) ──
  doc.rect(0, 0, W, 104).fillColor(CREAM).fill();
  doc.rect(0, 104, W, 3).fillColor(BORD).fill();
  // logo (ako postoji)
  let logoBottom = 36;
  try {
    if (typeof ZBUKA_LOGO_DARK_B64 === 'string' && ZBUKA_LOGO_DARK_B64.length > 50) {
      const lb = Buffer.from(ZBUKA_LOGO_DARK_B64, 'base64');
      doc.image(lb, M, 30, { height: 30 });
      logoBottom = 64;
    } else { throw new Error('no logo'); }
  } catch (_) {
    FB().fontSize(22).fillColor(BORD).text('ŽBUKA', M, 32);
    F().fontSize(8).fillColor(INK3).text('ČAKARIĆ d.o.o.', M, 60, { characterSpacing:2 });
    logoBottom = 74;
  }
  // desni gornji blok
  F().fontSize(8.5).fillColor(BORD).text('RADNI NALOG', W-M-220, 34, { width:220, align:'right', characterSpacing:3 });
  FB().fontSize(26).fillColor(INK).text(`№ ${n.id}`, W-M-220, 48, { width:220, align:'right' });

  // ── NASLOVNI BLOK ──
  doc.y = 132;
  FB().fontSize(7.5).fillColor(BORD).text(`RADNI NALOG · ${fmt(n.created_at)}`, M, doc.y, { characterSpacing:2 });
  FB().fontSize(28).fillColor(INK).text(naslov, M, doc.y + 4, { width: CW - 130 });
  let afterTitleY = doc.y;
  if (adresa) { F().fontSize(11).fillColor(INK2).text(adresa, M, doc.y + 3, { width: CW - 130 }); afterTitleY = doc.y; }
  F().fontSize(10.5).fillColor(INK3).text(`Kreirao: ${kreirao}`, M, doc.y + 3, { width: CW - 130 });
  afterTitleY = doc.y;

  // status pill (gore desno, poravnat s naslovom)
  {
    const label = rijesen ? 'ZAVRŠENO' : 'OTVOREN';
    FB().fontSize(10);
    const tw = doc.widthOfString(label);
    const pw = tw + 26, ph = 24, px = W - M - pw, py = 138;
    if (rijesen) { doc.roundedRect(px, py, pw, ph, 12).fillColor(GOLD).fill(); doc.fillColor('#3a2a06'); }
    else { doc.roundedRect(px, py, pw, ph, 12).fillColor(BORD).fill(); doc.fillColor('#fdeee9'); }
    FB().fontSize(10).text(label, px, py + 7, { width: pw, align:'center', characterSpacing:1.5 });
  }

  doc.y = afterTitleY + 18;

  // ── META TRAKA (bordeaux, 4 stupca) ──
  {
    const ty = doc.y, th = 60, cols = 4, cwid = CW / cols;
    doc.rect(M, ty, CW, th).fillColor(BORDD).fill();
    const cells = [
      ['STATUS', rijesen ? 'Završeno' : 'Otvoren'],
      ['KREIRAN', fmt(n.created_at).replace(/\.$/,'')],
      ['FOTOGRAFIJA', String((fotos && fotos.length) || 0)],
      ['LOKACIJA', (hasCoord || hasMapsUrl) ? 'Da' : '—'],
    ];
    for (let i=0;i<cols;i++) {
      const cx = M + i*cwid + 14;
      if (i>0) { doc.rect(M + i*cwid, ty+12, 1, th-24).fillColor('#ffffff').fillOpacity(0.2).fill(); doc.fillOpacity(1); }
      F().fontSize(8).fillColor(GOLDL).text(cells[i][0], cx, ty + 14, { width: cwid-20, characterSpacing:1.2 });
      FB().fontSize(15).fillColor(CREAM).text(cells[i][1], cx, ty + 30, { width: cwid-20, lineBreak:false });
    }
    doc.y = ty + th + 26;
  }

  // ── ZAVRŠENO BANNER ──
  if (rijesen) {
    ensure(58);
    const by = doc.y, bh = 50;
    doc.roundedRect(M, by, CW, bh, 10).fillColor('#f4ecd6').fill();
    doc.roundedRect(M, by, CW, bh, 10).lineWidth(1).strokeColor(GOLDL).stroke();
    doc.circle(M+30, by+25, 15).fillColor(GOLD).fill();
    FB().fontSize(16).fillColor('#fff').text('✓', M+24, by+16);
    FB().fontSize(13).fillColor(BORDD).text('Radni nalog je završen', M+58, by+12);
    F().fontSize(10).fillColor(INK2).text(`Riješio: ${(n.rijesen_ime||'—')}${n.datum_rjesenja ? '  ·  '+fmtT(n.datum_rjesenja) : ''}`, M+58, by+30, { width: CW-72 });
    doc.y = by + bh + 24;
  }

  // ── OPIS RADOVA ──
  sectionHead('Opis radova', 'Što je potrebno');
  if (n.komentar && String(n.komentar).trim()) {
    F().fontSize(12).fillColor(INK).text(String(n.komentar).trim(), M, doc.y, { width: CW, lineGap: 3 });
  } else {
    F().fontSize(12).fillColor(INK3).text('Bez dodatnog opisa za ovaj nalog.', M, doc.y, { width: CW });
  }
  doc.y += 24;

  // ── LOKACIJA ──
  if (hasCoord || hasMapsUrl) {
    sectionHead('Lokacija', 'Gdje se izvodi');
    const ly = doc.y;
    doc.roundedRect(M, ly, CW, hasCoord ? 70 : 54, 10).fillColor('#fbf6ec').fill();
    doc.roundedRect(M, ly, CW, hasCoord ? 70 : 54, 10).lineWidth(1).strokeColor(LINE).stroke();
    let iy = ly + 14;
    if (hasCoord) {
      F().fontSize(8.5).fillColor(INK3).text('KOORDINATE', M+16, iy, { characterSpacing:1.5 });
      FB().fontSize(13).fillColor(BORD).text(`${Number(n.lat).toFixed(5)}, ${Number(n.lng).toFixed(5)}`, M+16, iy+11);
      iy += 34;
    }
    F().fontSize(11).fillColor(BORD).text('Otvori u Google Maps  ›', M+16, iy, { link: mapsLink, underline: true });
    doc.y = ly + (hasCoord ? 70 : 54) + 24;
  }

  // ── FOTODOKUMENTACIJA ──
  if (photoBufs.length) {
    sectionHead('Fotodokumentacija', `Slike s terena · ${photoBufs.length}`);
    if (photoBufs.length === 1) {
      ensure(300);
      const boxH = 330;
      try { doc.image(photoBufs[0], M, doc.y, { fit:[CW, boxH], align:'center', valign:'center' }); } catch(_) {}
      doc.y += boxH + 14;
    } else {
      const gap = 12, colW = (CW - gap) / 2, cellH = colW * 0.72;
      for (let i=0;i<photoBufs.length;i+=2) {
        ensure(cellH + 12);
        const rowY = doc.y;
        for (let k=0;k<2 && (i+k)<photoBufs.length;k++) {
          const x = M + k*(colW+gap);
          doc.roundedRect(x, rowY, colW, cellH, 8).fillColor('#efe6d2').fill();
          try { doc.image(photoBufs[i+k], x, rowY, { fit:[colW, cellH], align:'center', valign:'center' }); } catch(_) {}
        }
        doc.y = rowY + cellH + gap;
      }
    }
  }

  // ── FOOTER na svaku stranicu ──
  const range = doc.bufferedPageRange();
  for (let i=0;i<range.count;i++) {
    doc.switchToPage(range.start + i);
    const fy = H - 44;
    doc.rect(M, fy, CW, 0.8).fillColor(LINE).fill();
    F().fontSize(8).fillColor(INK3).text('ŽBUKA Čakarić d.o.o. · Ilica 506, 10000 Zagreb · OIB: 46540647857 · app.zbuka.hr', M, fy + 7, { width: CW - 60 });
    F().fontSize(8).fillColor(INK3).text(`${i+1} / ${range.count}`, W - M - 60, fy + 7, { width: 60, align:'right' });
  }

  doc.end();
  return done;
}

app.get('/api/nalozi/:id/pdf', auth, staff, async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT n.id, n.komentar, n.rijesen, n.datum_rjesenja, n.created_at, n.lat, n.lng, n.maps_url,
              r.ime||' '||r.prezime AS kreirao_ime,
              rr.ime||' '||rr.prezime AS rijesen_ime,
              g.naziv AS naziv_gradilista, g.adresa AS adresa_gradilista,
              COALESCE(json_agg(f.id ORDER BY f.id) FILTER (WHERE f.id IS NOT NULL), '[]') AS foto_ids
       FROM nalozi n
       LEFT JOIN radnici r ON r.id=n.kreirao_id
       LEFT JOIN radnici rr ON rr.id=n.rijesen_id
       LEFT JOIN gradilista g ON g.id=n.gradiliste_id
       LEFT JOIN nalozi_foto f ON f.nalog_id=n.id
       WHERE n.id=$1
       GROUP BY n.id, r.ime, r.prezime, rr.ime, rr.prezime, g.naziv, g.adresa`,
      [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ error: 'Nalog nije pronađen' });
    const n = r.rows[0];
    const fotos = Array.isArray(n.foto_ids) ? n.foto_ids.filter(x => x != null) : [];
    const buf = await _nalogPdfBuffer(n, fotos);
    const safeNaziv = String(n.naziv_gradilista || 'nalog').replace(/[^a-zA-Z0-9]/g, '_').slice(0, 40) || 'nalog';
    const datum = _ymd(new Date(n.created_at || Date.now()));
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="Nalog-${n.id}-${safeNaziv}-${datum}.pdf"`);
    res.setHeader('Cache-Control', 'no-store');
    res.send(buf);
  } catch (e) {
    console.error('[nalog pdf]', e.message);
    res.status(500).json({ error: e.message });
  }
});

