// Transakcija (zaprimanje / povrat / potrošnja)
app.post('/api/skladiste/transakcije', auth, staff, async (req, res) => {
  const { artikl_id, tip, kolicina, gradiliste_id, napomena, datum } = req.body;
  if (!artikl_id || !tip || !kolicina) return res.status(400).json({ error: 'Nedostaju podaci' });
  if (!['zaprimanje','povrat','potrosnja','otpis'].includes(tip)) return res.status(400).json({ error: 'Nevaljan tip' });
  // AUDIT FIX: atomic transakcija s FOR UPDATE lock - sprječava phantom read race condition
  // (bez ovoga, dva paralelna potrošnje mogu probiti stanje i napraviti negativno stanje)
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Lock artikl row za vrijeme provjere stanja (drugi paralelni uplosi čekaju)
    await client.query('SELECT id FROM skladiste_artikli WHERE id=$1 FOR UPDATE', [artikl_id]);
    
    if (tip === 'potrosnja' || tip === 'otpis') {
      const stanje = await client.query(`
        SELECT COALESCE(SUM(CASE WHEN tip IN ('zaprimanje','povrat') THEN kolicina WHEN tip IN ('potrosnja','otpis') THEN -kolicina ELSE 0 END),0) AS st
        FROM skladiste_transakcije WHERE artikl_id=$1`, [artikl_id]);
      if (parseFloat(stanje.rows[0].st) < parseFloat(kolicina)) {
        await client.query('ROLLBACK');
        return res.status(400).json({ error: `Nedovoljno na stanju (${parseFloat(stanje.rows[0].st)})` });
      }
    }
    const r = await client.query(
      `INSERT INTO skladiste_transakcije(artikl_id,radnik_id,gradiliste_id,tip,kolicina,napomena,datum)
       VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,
      [artikl_id, req.user.id, gradiliste_id||null, tip, parseFloat(kolicina),
       napomena||'', datum || danasZagreb()]
    );
    await client.query('COMMIT');
    // ⭐ v447 (Ivan): push ostalima — skladišna transakcija, kategorija 'skladiste'
    pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id||0])
      .then(gN => sendPush(req.user.id, '🏬 Skladište', `${req.user.ime} ${req.user.prezime}${gN.rows[0]?.naziv?' · '+gN.rows[0].naziv:''} · ${tip} ${kolicina}`, '/?tab=skladiste', 'skladiste')).catch(()=>{});
    res.json(r.rows[0]);
  } catch(e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

