// Povijest transakcija
app.get('/api/skladiste/povijest', auth, staff, async (req, res) => {
  const { artikl_id } = req.query;
  try {
    let q = `
      SELECT t.*, a.naziv AS artikl_naziv, a.jedinica,
             r.ime||' '||r.prezime AS radnik_ime,
             g.naziv AS grad_naziv
      FROM skladiste_transakcije t
      JOIN skladiste_artikli a ON a.id=t.artikl_id
      LEFT JOIN radnici r ON r.id=t.radnik_id
      LEFT JOIN gradilista g ON g.id=t.gradiliste_id
      WHERE 1=1`;
    const p = [];
    if (artikl_id) { p.push(artikl_id); q += ` AND t.artikl_id=$${p.length}`; }
    // ⭐ v641 (Ivan, audit F15): LIMIT 500 → 10000. Isti "nestajanje" kao gorivo (v139) i šihterica: stare
    //   transakcije su ispadale iz POVIJESNOG PRIKAZA nakon 500 unosa (podaci UVIJEK u bazi — saldo /stanje
    //   računa iz SVIH transakcija; samo lista je bila odsječena). 10000 = višegodišnja sigurnosna granica.
    //   Ako ikad pređe 10k → server-side paginacija (offset) kao materijal/dnevnik.
    q += ' ORDER BY t.datum DESC, t.created_at DESC LIMIT 10000';
    const r = await pool.query(q, p);
    res.json(r.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

