// ⭐ v135.7.202: B2 fallback čitanje
app.get('/api/smece/:id/foto', auth, async (req, res) => {
  try {
    const wantThumb = req.query.thumb === '1';  // ⭐ v502.20.30
    let r;
    try {
      r = await pool.query('SELECT foto_base64, qnap_path, b2_path, thumb_base64 FROM smece WHERE id=$1', [req.params.id]);
    } catch(colErr) {
      try { r = await pool.query('SELECT foto_base64, qnap_path, b2_path FROM smece WHERE id=$1', [req.params.id]); }
      catch(e2) { r = await pool.query('SELECT foto_base64, qnap_path FROM smece WHERE id=$1', [req.params.id]); }
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Nema zapisa' });
    const row = r.rows[0];

    if (wantThumb && row.thumb_base64) return res.json({ foto_base64: row.thumb_base64, from_thumb: true });

    if (row.foto_base64) {
      if (wantThumb) {
        const thumb = await _generirajThumbServer(row.foto_base64).catch(() => null);
        if (thumb) {
          pool.query('UPDATE smece SET thumb_base64=$1 WHERE id=$2', [thumb, req.params.id]).catch(()=>{});
          return res.json({ foto_base64: thumb, from_thumb: true });
        }
      }
      return res.json({ foto_base64: row.foto_base64 });
    }
    
    const buf = await fetchImageWithFallback(row.qnap_path, row.b2_path);
    if (buf) {
      if (wantThumb) {
        const thumb = await _generirajThumbServer(buf).catch(() => null);
        if (thumb) {
          pool.query('UPDATE smece SET thumb_base64=$1 WHERE id=$2', [thumb, req.params.id]).catch(()=>{});
          return res.json({ foto_base64: thumb, from_thumb: true });
        }
      }
      const b64 = 'data:image/jpeg;base64,' + buf.toString('base64');
      return res.json({ foto_base64: b64 });
    }
    return res.status(404).json({ error: 'Nema slike' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/smece', auth, staff, async (req, res) => {
  const { gradiliste_id, datum, m3, iznos, napomena, foto_base64 } = req.body;
  if (!gradiliste_id || !m3) return res.status(400).json({ error: 'Nedostaju podaci' });
  // AUDIT FIX 2.4.1: validacija m3 i iznos (negativni / preveliki)
  const m3N = parseFloat(m3);
  if (isNaN(m3N) || m3N <= 0 || m3N > 1000) {
    return res.status(400).json({ error: 'm³ mora biti 0-1000' });
  }
  const iznosN = parseFloat(iznos) || 0;
  if (iznosN < 0 || iznosN > 100000) {
    return res.status(400).json({ error: 'Iznos mora biti 0-100000€' });
  }
  try {
    let qnapPath = null;
    let b2Path = null;
    // ⭐ v135.7.210: Upload radi i ako je samo B2 dostupan (bez QNAP-a)
    if (foto_base64 && (process.env.QNAP_WEBDAV_URL || b2Enabled())) {
      try {
        const now  = new Date();
        const pad  = n => String(n).padStart(2,'0');
        const ts   = `${pad(now.getDate())}_${pad(now.getMonth()+1)}_${now.getFullYear()}_${pad(now.getHours())}-${pad(now.getMinutes())}-${pad(now.getSeconds())}`;
        const fname = `${ts}_smece.${imgExtFromB64(foto_base64)}`; // ⭐ v...65: webp/jpg po stvarnom formatu
        const targetPath = `Smece/${fname}`;
        const imgData = foto_base64.replace(/^data:image\/\w+;base64,/,'');
        const imgBuffer = Buffer.from(imgData,'base64');
        
        // QNAP setup (samo ako QNAP enabled)
        let qnapPromise = Promise.resolve(null);
        if (process.env.QNAP_WEBDAV_URL) {
          const qnapBase    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
          const qnapBaseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
          const auth64      = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
          const hdrs        = { Authorization: `Basic ${auth64}` };
          await fetch(`${qnapBaseUrl}${qnapBase}/Smece/`, { method:'MKCOL', headers:hdrs, signal: AbortSignal.timeout(3000) }).catch(() => {});
          qnapPromise = fetch(`${qnapBaseUrl}${qnapBase}/Smece/${fname}`, {
            method:'PUT', headers:{...hdrs,'Content-Type': extToContentType(fname)},
            body: imgBuffer,
            signal: AbortSignal.timeout(8000)
          });
        }
        
        // ⭐ v135.7.204: Paralelni upload QNAP + B2
        const [qnapResult, b2Res] = await Promise.allSettled([
          qnapPromise,
          b2Enabled() ? b2Upload(imgBuffer, targetPath, 'image/jpeg') : Promise.resolve(null)
        ]).then(rs => [
          rs[0].status === 'fulfilled' ? rs[0].value : null,
          rs[1].status === 'fulfilled' ? rs[1].value : null
        ]);
        
        const qnapOk = qnapResult && (qnapResult.ok || qnapResult.status === 201 || qnapResult.status === 204);
        if (qnapOk) qnapPath = targetPath;
        if (b2Res) b2Path = b2Res;
        if (!qnapOk && !b2Path) {
          console.error('QNAP+B2 smece OBA fail-ala:', qnapResult?.status);
        }
        console.log(`[smece upload] QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
      } catch(e) { console.error('Smece upload:', e.message); }
    }
    const r = await pool.query(
      `INSERT INTO smece(gradiliste_id,radnik_id,datum,m3,iznos,napomena,foto_base64,qnap_path,b2_path,created_at)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,NOW()) RETURNING id,datum,m3,iznos,napomena`,
      [gradiliste_id, req.user.id, datum || danasZagreb(),
       m3N, iznosN, napomena||'',
       (qnapPath || b2Path) ? null : (foto_base64 || null), qnapPath, b2Path]
    ).catch(async e => {
      // Fallback ako b2_path kolona još ne postoji (migracija nije izvršena)
      console.warn('[smece] fallback bez b2_path:', e.message);
      return pool.query(
        `INSERT INTO smece(gradiliste_id,radnik_id,datum,m3,iznos,napomena,foto_base64,qnap_path,created_at)
         VALUES($1,$2,$3,$4,$5,$6,$7,$8,NOW()) RETURNING id,datum,m3,iznos,napomena`,
        [gradiliste_id, req.user.id, datum || danasZagreb(),
         m3N, iznosN, napomena||'',
         qnapPath ? null : (foto_base64 || null), qnapPath]
      );
    });
    // ⭐ v446 (Ivan): push ostalima — autor isključen u sendPush, kategorija 'smece'
    pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id])
      .then(gN => sendPush(req.user.id, '🗑️ Novi odvoz smeća', `${req.user.ime} ${req.user.prezime} · ${gN.rows[0]?.naziv||''} · ${m3N} m³`, '/?tab=smece', 'smece')).catch(()=>{});
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/smece/:id', auth, staff, async (req, res) => {
  try {
    // AUDIT FIX: dohvati qnap_path prije brisanja za cleanup
    // ⭐ v135.7.206: dodano b2_path za parallel cleanup
    let r;
    try {
      r = await pool.query('SELECT qnap_path, b2_path FROM smece WHERE id=$1', [req.params.id]);
    } catch(colErr) {
      r = await pool.query('SELECT qnap_path FROM smece WHERE id=$1', [req.params.id]);
    }
    const qnapPath = r.rows[0]?.qnap_path;
    const b2Path = r.rows[0]?.b2_path;
    
    await pool.query('DELETE FROM smece WHERE id=$1', [req.params.id]);
    
    // QNAP + B2 cleanup u background-u
    if (qnapPath && process.env.QNAP_WEBDAV_URL) {
      setImmediate(async () => {
        try {
          if (typeof qnapDeleteFile === 'function') {
            await qnapDeleteFile(qnapPath);
          }
        } catch(e) { console.warn('[smeće QNAP delete]', e.message); }
      });
    }
    // ⭐ v135.7.206: paralelno B2 brisanje
    if (b2Path && b2Enabled()) {
      setImmediate(async () => {
        try {
          const ok = await b2Delete(b2Path);
          console.log(`[B2 DELETE] smece ${b2Path}: ${ok ? 'OK' : 'FAIL'}`);
        } catch(e) { console.warn('[B2 DELETE] smece:', e.message); }
      });
    }
    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

