app.put('/api/vozila/:id', auth, admin, async (req, res) => {
  const { naziv, registracija, aktivan, registracija_istek, registracija_napomena, registracija_notif_isk, registracija_godisnje } = req.body;
  try {
    const r = await pool.query(
      `UPDATE vozila SET
         naziv=COALESCE($1,naziv),
         registracija=COALESCE($2,registracija),
         aktivan=COALESCE($3,aktivan),
         registracija_istek = CASE WHEN $4::text IS NOT NULL THEN NULLIF($4,'')::date ELSE registracija_istek END,
         registracija_napomena = CASE WHEN $5::text IS NOT NULL THEN $5 ELSE registracija_napomena END,
         -- ⭐ v514: novi datum (≠ stari) → auto re-enable notifikacija + reset tjednog throttle-a → ponovna notif za novu registraciju
         registracija_notif_isk = CASE
           WHEN $4::text IS NOT NULL AND (NULLIF($4,'')::date IS DISTINCT FROM registracija_istek) THEN false
           WHEN $6::boolean IS NOT NULL THEN $6
           ELSE registracija_notif_isk END,
         registracija_notif_zadnji = CASE
           WHEN $4::text IS NOT NULL AND (NULLIF($4,'')::date IS DISTINCT FROM registracija_istek) THEN NULL
           ELSE registracija_notif_zadnji END,
         -- ⭐ v515: godišnje ponavljanje (zadrži postojeće ako nije poslano)
         registracija_godisnje = CASE WHEN $8::boolean IS NOT NULL THEN $8 ELSE registracija_godisnje END
       WHERE id=$7 RETURNING *`,
      // AUDIT FIX 3.1.6: slice na string poljima
      [naziv != null ? String(naziv).trim().slice(0, 100) : null,
       registracija != null ? String(registracija).trim().slice(0, 30) : null,
       aktivan != null ? aktivan : null,
       registracija_istek != null ? String(registracija_istek).slice(0, 10) : null,
       registracija_napomena != null ? String(registracija_napomena).trim().slice(0, 200) : null,
       registracija_notif_isk != null ? !!registracija_notif_isk : null,
       req.params.id,
       registracija_godisnje != null ? !!registracija_godisnje : null]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Nije pronađeno' });
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

