// Gorivo — stanje računa
app.get('/api/gorivo/stanje', auth, staff, async (req, res) => {
  try {
    // ⭐ v502.20.47 (Ivan, 29.05.2026): stanje se RAČUNA iz unosa (single source of truth).
    //   PRIJE: čitao denormaliziran gorivo_racun.stanje — zaseban broj koji se ručno ažurira pri
    //   svakom INSERT/PUT/DELETE. Ako bilo koja operacija promaši (dupli klik, ručni SQL, prekinuta
    //   konekcija), broj TRAJNO odluta od stvarnog zbroja unosa i nitko ne primijeti raskorak.
    //   SAD: stanje = Σ uplata − Σ troškova, izračunato iz gorivo_unosi. Uvijek točno, nemoguće
    //   da "krivo zbraja". gorivo_racun se i dalje održava (za kompatibilnost), ali NIJE izvor istine.
    const r = await pool.query(`
      SELECT COALESCE(SUM(CASE WHEN tip='uplata' THEN iznos ELSE -iznos END), 0) AS stanje
      FROM gorivo_unosi
    `);
    const stanje = parseFloat(r.rows[0]?.stanje || 0);
    // Self-heal: ako denormaliziran broj odstupa, uskladi ga (da i stari kod vidi točno).
    // ⭐ v135.7.502.20.129 (Ivan, 04.06.2026): bivši .catch(()=>{}) tiho je gutao grešku —
    //   ako uskladba ikad padne (npr. nema gorivo_racun reda), "self-heal" je bio prazno
    //   obećanje bez traga. Izvor istine ostaje SUM iznad (ovo je samo kompat-polje), pa
    //   greška NIJE critical-path — ali sad ostavlja trag u logu da se divergencija primijeti.
    pool.query(`UPDATE gorivo_racun SET stanje=$1, updated_at=NOW()`, [stanje])
      .catch(e => console.warn('[gorivo self-heal] denormaliziran stanje sync fail:', e.message));
    res.json({ stanje });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Gorivo — lista unosa
app.get('/api/gorivo', auth, staff, async (req, res) => {
  try {
    // ⭐ v135.7.502.20.139 (Ivan, 04.06.2026): LIMIT 200 → 10000. UZROK "nestajanja" unosa nakon
    //   mjesec dana: stari su ispadali iz prikaza čim se nakupilo >200 unosa (podaci su UVIJEK bili
    //   u bazi — INSERT je atomski/commitan, nema bulk-delete ni retention). Sad se vraćaju svi
    //   (10000 = višegodišnja sigurnosna granica). Ako ikad pređe 10k → server-side paginacija/search.
    const r = await pool.query(`
      SELECT g.*, v.naziv AS vozilo_naziv, v.registracija,
             r.ime||' '||r.prezime AS radnik_ime
      FROM gorivo_unosi g
      LEFT JOIN vozila v ON v.id = g.vozilo_id
      LEFT JOIN radnici r ON r.id = g.radnik_id
      ORDER BY g.datum DESC, g.created_at DESC
      LIMIT 10000
    `);
    res.json(r.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Gorivo — novi unos (trošak ili uplata)
app.post('/api/gorivo', auth, staff, async (req, res) => {
  const { vozilo_id, datum, iznos, napomena, tip } = req.body;
  if (!iznos) return res.status(400).json({ error: 'Nedostaje iznos' });
  // ⭐ AUDIT v176: Iznos mora biti pozitivan i razumno velik (max 50,000€ za doplatu)
  const iznosNum = parseFloat(iznos);
  if (!Number.isFinite(iznosNum) || iznosNum <= 0 || iznosNum > 50000) {
    return res.status(400).json({ error: 'Iznos mora biti 0-50,000 €' });
  }
  const tipV = tip === 'uplata' ? 'uplata' : 'trosak';
  // AUDIT FIX: atomic transakcija (INSERT + stanje update) za konzistentnost
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const r = await client.query(
      `INSERT INTO gorivo_unosi(vozilo_id,radnik_id,datum,iznos,napomena,tip,created_at)
       VALUES($1,$2,$3,$4,$5,$6,NOW()) RETURNING *`,
      [tipV === 'uplata' ? null : (vozilo_id || null), req.user.id, datum || danasZagreb(),   // ⭐ v624: uplata NIKAD s vozilom (server guard, obrana u dubinu uz klijentski fix)
       iznosNum, String(napomena||'').slice(0, 500), tipV]
    );
    const delta = tipV === 'uplata' ? iznosNum : -iznosNum;
    const updRes = await client.query(
      `UPDATE gorivo_racun SET stanje = stanje + $1, updated_at=NOW() RETURNING stanje`,
      [delta]
    );
    await client.query('COMMIT');
    
    const novoStanje = parseFloat(updRes.rows[0]?.stanje || 0);
    // ⭐ v447 (Ivan): push ostalima — novi unos goriva, kategorija 'gorivo'
    pool.query('SELECT naziv FROM vozila WHERE id=$1', [vozilo_id||0])
      .then(vN => sendPush(req.user.id, '⛽ Novi unos goriva', `${req.user.ime} ${req.user.prezime} · ${vN.rows[0]?.naziv||'vozilo'} · ${iznos}€`, '/?tab=gorivo', 'gorivo')).catch(()=>{});
    res.json({ ...r.rows[0], novo_stanje: novoStanje });
    
    // Push notifikacija (izvan transakcije - ne kritično za atomicity)
    if (tipV === 'trosak' && novoStanje < 300) {
      try {
        const allSubs = await pool.query('SELECT * FROM push_subscriptions');
        const payload = JSON.stringify({ title: '⛽ Stanje goriva nisko!', body: `Trenutno stanje: ${hrBroj(novoStanje,2)} € — potrebno doplatiti!`, url: '/' });
        for (const sub of allSubs.rows) {
          try {
            if (webpush) await webpush.sendNotification(JSON.parse(sub.subscription), payload, _pushOpcije(JSON.parse(sub.subscription).endpoint, payload && payload.tip));   // ⭐ v989
          } catch(e) {
            if (e.statusCode === 410 || e.statusCode === 404) await pool.query('DELETE FROM push_subscriptions WHERE id=$1', [sub.id]).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
          }
        }
      } catch(_) {}
    }
  } catch(e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

// ⭐ v502.20.17 (Ivan, 27.05.2026): PUT /api/gorivo/:id — edit postojećeg unosa
//   Atomska transakcija: vrati stanje "kao prije unosa" → primijeni novi iznos/tip.
//   Use case: krivi iznos, krivi vozilo, dodavanje napomene naknadno.
//   Auth: staff (kao POST). DELETE ostaje admin.
app.put('/api/gorivo/:id', auth, staff, async (req, res) => {
  const unosId = parseInt(req.params.id);
  if (!unosId) return res.status(400).json({ error: 'Neispravan ID' });
  
  const { vozilo_id, datum, iznos, napomena, tip } = req.body;
  
  // Validacija (kao POST)
  if (iznos != null) {
    const iznosNum = parseFloat(iznos);
    if (!Number.isFinite(iznosNum) || iznosNum <= 0 || iznosNum > 50000) {
      return res.status(400).json({ error: 'Iznos mora biti 0-50,000 €' });
    }
  }
  const tipV = tip ? (tip === 'uplata' ? 'uplata' : 'trosak') : null;
  
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    
    // 1. Dohvati postojeći zapis
    const oldR = await client.query('SELECT iznos, tip FROM gorivo_unosi WHERE id=$1', [unosId]);
    if (!oldR.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Unos ne postoji' });
    }
    const oldRow = oldR.rows[0];
    
    // 2. Partial UPDATE
    // ⭐ v624 (Ivan): ako je KONAČNI tip zapisa 'uplata' (novi ili zatečeni), vozilo se PRISILNO briše —
    //   uplata je samo redak stanja računa; troškovi vozila su gorivo (tip='trosak') + servisi.
    const _finalTip = tipV || oldRow.tip;
    const sets = [];
    const p = [];
    if (_finalTip === 'uplata')       { p.push(null); sets.push(`vozilo_id=$${p.length}`); }
    else if (vozilo_id !== undefined) { p.push(vozilo_id ? parseInt(vozilo_id) : null); sets.push(`vozilo_id=$${p.length}`); }
    if (datum != null)           { p.push(String(datum).slice(0, 10)); sets.push(`datum=$${p.length}`); }
    if (iznos != null)           { p.push(parseFloat(iznos)); sets.push(`iznos=$${p.length}`); }
    if (napomena != null)        { p.push(String(napomena).slice(0, 500)); sets.push(`napomena=$${p.length}`); }
    if (tipV)                    { p.push(tipV); sets.push(`tip=$${p.length}`); }
    
    if (!sets.length) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'Nema podataka za update' });
    }
    
    p.push(unosId);
    const upR = await client.query(
      `UPDATE gorivo_unosi SET ${sets.join(',')} WHERE id=$${p.length} RETURNING *`, p
    );
    const newRow = upR.rows[0];
    
    // 3. Recalculate stanje ako se iznos ili tip mijenjao
    let novoStanje = null;
    if (iznos != null || tipV) {
      // Inverzna stara transakcija (vrati stanje kao prije unosa)
      const oldIznos = parseFloat(oldRow.iznos);
      const oldDelta = oldRow.tip === 'uplata' ? oldIznos : -oldIznos;  // bilo dodano
      
      // Novi delta
      const newIznos = parseFloat(newRow.iznos);
      const newDelta = newRow.tip === 'uplata' ? newIznos : -newIznos;
      
      // Korekcija stanja: oduzmi stari, dodaj novi
      const correction = -oldDelta + newDelta;
      const updRes = await client.query(
        `UPDATE gorivo_racun SET stanje = stanje + $1, updated_at=NOW() RETURNING stanje`,
        [correction]
      );
      novoStanje = parseFloat(updRes.rows[0]?.stanje || 0);
    }
    
    await client.query('COMMIT');
    res.json({ ...newRow, novo_stanje: novoStanje });
  } catch(e) {
    await client.query('ROLLBACK').catch(()=>{});
    console.error('[PUT /api/gorivo/:id]', e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

app.delete('/api/gorivo/:id', auth, admin, async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const r = await client.query('SELECT iznos, tip FROM gorivo_unosi WHERE id=$1', [req.params.id]);
    if (!r.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Nije pronađeno' });
    }
    const { iznos, tip } = r.rows[0];
    const delta = tip === 'uplata' ? -parseFloat(iznos) : parseFloat(iznos);
    await client.query('DELETE FROM gorivo_unosi WHERE id=$1', [req.params.id]);
    await client.query('UPDATE gorivo_racun SET stanje = stanje + $1, updated_at=NOW()', [delta]);
    await client.query('COMMIT');
    res.json({ ok: true });
  } catch(e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

