app.get('/api/uredaji', auth, staff, async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT u.id, u.naziv, u.marka, u.oznaka, u.opis, u.godina_proizvodnje,
             u.brojilo_tip, u.brojilo_stanje, u.brojilo_otpis,
             u.otpisan, u.datum_otpisa, u.created_at,
             u.qnap_path,
             CASE WHEN u.foto_base64 IS NOT NULL OR u.qnap_path IS NOT NULL THEN true ELSE false END AS ima_foto,
             d.id AS dodjela_id,
             d.radnik_id AS dodjela_radnik_id,
             d.vanjski, d.vanjski_napomena,
             d.datum_dodjele,
             ra.ime || ' ' || ra.prezime AS kod_radnika,
             d.gradiliste_id AS dodjela_gradiliste_id,
             gg.naziv AS kod_gradilista
      FROM uredaji u
      LEFT JOIN uredaji_dodjela d ON d.uredaj_id = u.id AND d.datum_povrata IS NULL
      LEFT JOIN radnici ra ON ra.id = d.radnik_id
      LEFT JOIN gradilista gg ON gg.id = d.gradiliste_id
      ORDER BY u.otpisan ASC, u.naziv ASC
    `);
    res.json(r.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// GET — foto uređaja
// ⭐ v135.7.202: B2 fallback čitanje
app.get('/api/uredaji/:id/foto', auth, async (req, res) => {
  try {
    const wantThumb = req.query.thumb === '1';  // ⭐ v502.20.30
    let r;
    try {
      r = await pool.query('SELECT foto_base64, qnap_path, b2_path, thumb_base64 FROM uredaji WHERE id=$1', [req.params.id]);
    } catch(colErr) {
      try { r = await pool.query('SELECT foto_base64, qnap_path, b2_path FROM uredaji WHERE id=$1', [req.params.id]); }
      catch(e2) { r = await pool.query('SELECT foto_base64, qnap_path FROM uredaji WHERE id=$1', [req.params.id]); }
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Nema uređaja' });
    const row = r.rows[0];

    if (wantThumb && row.thumb_base64) return res.json({ foto_base64: row.thumb_base64, from_thumb: true });

    if (row.foto_base64) {
      if (wantThumb) {
        const thumb = await _generirajThumbServer(row.foto_base64).catch(() => null);
        if (thumb) {
          pool.query('UPDATE uredaji SET thumb_base64=$1 WHERE id=$2', [thumb, req.params.id]).catch(()=>{});
          return res.json({ foto_base64: thumb, from_thumb: true });
        }
      }
      return res.json({ foto_base64: row.foto_base64 });
    }
    
    const buf = await fetchImageWithFallback(row.qnap_path, row.b2_path);
    if (buf) {
      if (wantThumb) {
        const thumb = await _generirajThumbServer(buf).catch(() => null);
        if (thumb) {
          pool.query('UPDATE uredaji SET thumb_base64=$1 WHERE id=$2', [thumb, req.params.id]).catch(()=>{});
          return res.json({ foto_base64: thumb, from_thumb: true });
        }
      }
      const b64 = 'data:image/jpeg;base64,' + buf.toString('base64');
      return res.json({ foto_base64: b64 });
    }
    return res.status(404).json({ error: 'Nema slike' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST — novi uređaj
app.post('/api/uredaji', auth, staff, async (req, res) => {
  const { naziv, marka, oznaka, opis, godina_proizvodnje, foto_base64 } = req.body;
  if (!naziv) return res.status(400).json({ error: 'Nedostaje naziv' });
  // AUDIT FIX 2.1.4: slice + godina validacija
  const godNum = godina_proizvodnje ? parseInt(godina_proizvodnje) : null;
  if (godNum != null && (isNaN(godNum) || godNum < 1900 || godNum > 2100)) {
    return res.status(400).json({ error: 'Godina mora biti 1900-2100' });
  }
  try {
    const r = await pool.query(
      `INSERT INTO uredaji(naziv,marka,oznaka,opis,godina_proizvodnje)
       VALUES($1,$2,$3,$4,$5) RETURNING *`,
      [String(naziv).trim().slice(0, 100),
       String(marka||'').slice(0, 100),
       String(oznaka||'').slice(0, 100),
       String(opis||'').slice(0, 2000),
       godNum]
    );
    const uredajId = r.rows[0].id;
    // ⭐ v135.7.210: Upload radi i ako je samo B2 dostupan (bez QNAP-a)
    if (foto_base64 && (process.env.QNAP_WEBDAV_URL || b2Enabled())) {
      try {
        const nazivSafe = naziv.replace(/[/\\:*?"<>|]/g,'_').trim().slice(0,40);
        const pad = n => String(n).padStart(2,'0');
        const now = new Date();
        const fname = `${pad(now.getDate())}_${pad(now.getMonth()+1)}_${now.getFullYear()}_id${uredajId}_${nazivSafe}.${imgExtFromB64(foto_base64)}`; // ⭐ v...65
        const qnapPath = `Uredaji/${fname}`;
        const imgData = foto_base64.replace(/^data:image\/\w+;base64,/,'');
        const imgBuffer = Buffer.from(imgData,'base64');
        
        // QNAP setup (samo ako QNAP enabled)
        let qnapPromise = Promise.resolve(null);
        if (process.env.QNAP_WEBDAV_URL) {
          const base    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
          const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
          const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
          const hdrs    = { Authorization:`Basic ${auth64}` };
          await fetch(`${baseUrl}${base}/Uredaji/`, {method:'MKCOL',headers:hdrs,signal:AbortSignal.timeout(3000)}).catch(() => {});
          qnapPromise = fetch(`${baseUrl}${base}/${qnapPath}`, {
            method:'PUT', headers:{...hdrs,'Content-Type': extToContentType(qnapPath)},
            body: imgBuffer,
            signal: AbortSignal.timeout(8000)
          });
        }
        
        // ⭐ v135.7.204: Paralelni upload QNAP + B2
        const [qnapResult, b2Path] = await Promise.allSettled([
          qnapPromise,
          b2Enabled() ? b2Upload(imgBuffer, qnapPath, 'image/jpeg') : Promise.resolve(null)
        ]).then(rs => [
          rs[0].status === 'fulfilled' ? rs[0].value : null,
          rs[1].status === 'fulfilled' ? rs[1].value : null
        ]);
        
        const qnapOk = qnapResult && (qnapResult.ok || qnapResult.status===201 || qnapResult.status===204);
        if (qnapOk || b2Path) {
          await pool.query(
            'UPDATE uredaji SET qnap_path=$1, b2_path=$2, foto_base64=NULL WHERE id=$3', 
            [qnapOk ? qnapPath : null, b2Path, uredajId]
          ).catch(async e => {
            console.warn('[uredaji] fallback bez b2_path:', e.message);
            return pool.query('UPDATE uredaji SET qnap_path=$1, foto_base64=NULL WHERE id=$2', [qnapPath, uredajId]);
          });
          if (qnapOk) r.rows[0].qnap_path = qnapPath;
          if (b2Path) r.rows[0].b2_path = b2Path;
          console.log(`[uredaj upload] id=${uredajId} QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
        }
      } catch(e) { console.error('Uredaj upload:', e.message); }
    }
    // ⭐ v447 (Ivan): push ostalima — novi uređaj, kategorija 'urd'
    sendPush(req.user.id, '🔧 Novi uređaj', `${req.user.ime} ${req.user.prezime} · ${naziv||''}${marka?' '+marka:''}`, '/?tab=urd', 'urd');
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// PUT — uredi uređaj (s opcionom foto izmjenom)
app.put('/api/uredaji/:id', auth, staff, async (req, res) => {
  const { naziv, marka, oznaka, opis, godina_proizvodnje, foto_base64 } = req.body;
  try {
    const r = await pool.query(
      `UPDATE uredaji SET naziv=$1,marka=$2,oznaka=$3,opis=$4,godina_proizvodnje=$5 WHERE id=$6 RETURNING *`,
      [naziv, marka||'', oznaka||'', opis||'', godina_proizvodnje||null, req.params.id]
    );
    const row = r.rows[0];
    // Ako je nova slika — upload na QNAP + B2, obrisi staru s OBA storage-a
    // ⭐ v135.7.210: radi i ako je samo B2 dostupan (bez QNAP-a)
    if (foto_base64 && (process.env.QNAP_WEBDAV_URL || b2Enabled())) {
      try {
        // dohvati i b2_path da obrišemo i staru B2 kopiju
        let old;
        try {
          old = await pool.query('SELECT qnap_path, b2_path FROM uredaji WHERE id=$1', [req.params.id]);
        } catch(colErr) {
          old = await pool.query('SELECT qnap_path FROM uredaji WHERE id=$1', [req.params.id]);
        }
        const nazivSafe = naziv.replace(/[/\\:*?"<>|]/g,'_').trim().slice(0,40);
        const pad = n => String(n).padStart(2,'0');
        const now = new Date();
        const safeId = parseInt(req.params.id) || 0;
        const fname = `${pad(now.getDate())}_${pad(now.getMonth()+1)}_${now.getFullYear()}_id${safeId}_${nazivSafe}.${imgExtFromB64(foto_base64)}`; // ⭐ v...65
        const qnapPath = `Uredaji/${fname}`;
        const imgData = foto_base64.replace(/^data:image\/\w+;base64,/,'');
        const imgBuffer = Buffer.from(imgData,'base64');
        
        // QNAP setup (samo ako QNAP enabled)
        let qnapPromise = Promise.resolve(null);
        let baseUrl = '', base = '', hdrs = null;
        if (process.env.QNAP_WEBDAV_URL) {
          base    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
          baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
          const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
          hdrs    = { Authorization:`Basic ${auth64}` };
          await fetch(`${baseUrl}${base}/Uredaji/`, {method:'MKCOL',headers:hdrs,signal:AbortSignal.timeout(3000)}).catch(() => {});
          qnapPromise = fetch(`${baseUrl}${base}/${qnapPath}`, {
            method:'PUT', headers:{...hdrs,'Content-Type': extToContentType(qnapPath)},
            body: imgBuffer,
            signal: AbortSignal.timeout(8000)
          });
        }
        
        // ⭐ v135.7.204: Paralelni upload QNAP + B2
        const [qnapResult, b2Path] = await Promise.allSettled([
          qnapPromise,
          b2Enabled() ? b2Upload(imgBuffer, qnapPath, 'image/jpeg') : Promise.resolve(null)
        ]).then(rs => [
          rs[0].status === 'fulfilled' ? rs[0].value : null,
          rs[1].status === 'fulfilled' ? rs[1].value : null
        ]);
        
        const qnapOk = qnapResult && (qnapResult.ok || qnapResult.status===201 || qnapResult.status===204);
        if (qnapOk || b2Path) {
          // Obrisi staru sliku s OBA storage-a
          if (old.rows[0]?.qnap_path && old.rows[0].qnap_path !== qnapPath && hdrs) {
            fetch(`${baseUrl}${base}/${old.rows[0].qnap_path}`, {method:'DELETE',headers:hdrs,signal:AbortSignal.timeout(5000)}).catch(() => {});
          }
          if (old.rows[0]?.b2_path && old.rows[0].b2_path !== qnapPath && b2Enabled()) {
            b2Delete(old.rows[0].b2_path).catch(e => console.warn('[B2 stari delete]', e.message));
          }
          await pool.query(
            'UPDATE uredaji SET qnap_path=$1, b2_path=$2, foto_base64=NULL WHERE id=$3', 
            [qnapOk ? qnapPath : null, b2Path, req.params.id]
          ).catch(async e => {
            console.warn('[uredaji PUT] fallback bez b2_path:', e.message);
            return pool.query('UPDATE uredaji SET qnap_path=$1, foto_base64=NULL WHERE id=$2', [qnapPath, req.params.id]);
          });
          if (qnapOk) row.qnap_path = qnapPath;
          if (b2Path) row.b2_path = b2Path;
          console.log(`[uredaj update] id=${req.params.id} QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
        }
      } catch(e) { console.error('Uredaj update foto:', e.message); }
    }
    res.json(row);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

