// ⭐ v502.20.36 (FAZA 9): GET /api/radnici/:id/otvorena-zaduzenja
//   Sve što radnik DRŽI/DUGUJE vratiti: ne-razdužene zadužnice (stavke) + uređaji bez povrata.
//   Koristi se pri deaktivaciji radnika (prompt) i u tabu Zadužnica.
app.get('/api/radnici/:id/otvorena-zaduzenja', auth, staff, async (req, res) => {
  try {
    const rid = req.params.id;
    const zad = await pool.query(`
      SELECT z.id, z.datum, z.tip, z.stavke, g.naziv AS gradiliste
      FROM zaduznica z
      LEFT JOIN gradilista g ON g.id = z.gradiliste_id
      WHERE z.radnik_id=$1 AND z.razduzen=false
      ORDER BY z.datum DESC
    `, [rid]);
    const urd = await pool.query(`
      SELECT d.id, d.datum_dodjele, u.naziv, u.marka, u.oznaka
      FROM uredaji_dodjela d
      JOIN uredaji u ON u.id = d.uredaj_id
      WHERE d.radnik_id=$1 AND d.datum_povrata IS NULL
      ORDER BY d.datum_dodjele DESC
    `, [rid]);
    // Broj stavki preko svih ne-razduženih zadužnica (za sažetak u promptu)
    let brojStavki = 0;
    for (const z of zad.rows) { try { brojStavki += (Array.isArray(z.stavke) ? z.stavke.length : 0); } catch(_){} }
    res.json({
      zaduznice: zad.rows,
      uredaji: urd.rows,
      ima_otvorenih: (zad.rows.length > 0 || urd.rows.length > 0),
      broj_zaduznica: zad.rows.length,
      broj_stavki: brojStavki,
      broj_uredaja: urd.rows.length
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── REŽIJSKI SATI ────────────────────────────────────────────────────────────

app.post('/api/rezijski', auth, staff, async (req, res) => {
  const { datum, gradiliste_id, broj_radnika, sati, napomena, narucitelj, potpis_base64 } = req.body;
  if (!gradiliste_id) return res.status(400).json({ error: 'Nedostaje gradiliste_id' });
  // AUDIT FIX 2.3.1: validacije
  const brNum = parseInt(broj_radnika) || 0;
  const satiNum = parseFloat(sati) || 0;
  if (brNum < 0 || brNum > 200) {
    return res.status(400).json({ error: 'Broj radnika 0-200' });
  }
  if (satiNum < 0 || satiNum > 24) {
    return res.status(400).json({ error: 'Sati 0-24' });
  }
  // potpis_base64 limit (1MB - normalan SVG/PNG signature je ispod 100KB)
  if (potpis_base64 && potpis_base64.length > 1024 * 1024) {
    return res.status(413).json({ error: 'Potpis prevelik (max 1MB)' });
  }
  try {
    const r = await pool.query(
      `INSERT INTO rezijski_sati(datum,gradiliste_id,radnik_id,broj_radnika,sati,napomena,narucitelj,potpis_base64,potpis_datum)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
      [datum || danasZagreb(),
       gradiliste_id, req.user.id,
       brNum, satiNum,
       String(napomena||'').slice(0, 5000),
       String(narucitelj||'').slice(0, 200),
       potpis_base64 || null,
       potpis_base64 ? new Date() : null]
    );
    // ⭐ v446 (Ivan): push ostalima — autor isključen u sendPush, kategorija 'rez'
    pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id])
      .then(gN => sendPush(req.user.id, '⏱️ Novi režijski sati', `${req.user.ime} ${req.user.prezime} · ${gN.rows[0]?.naziv||''} · ${brNum} rad. ${satiNum}h`, '/?tab=rez', 'rez')).catch(()=>{});
    res.json(r.rows[0]);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

