app.get('/api/rezijski', auth, staff, async (req, res) => {
  const { od, do: doo, gradiliste_id } = req.query;
  try {
    let q = `
      SELECT r.*, ra.ime, ra.prezime, g.naziv AS naziv_gradilista
      FROM rezijski_sati r
      JOIN radnici ra ON ra.id = r.radnik_id
      JOIN gradilista g ON g.id = r.gradiliste_id
      WHERE 1=1`;
    const p = [];
    if (od)            { p.push(od);           q += ` AND r.datum >= $${p.length}`; }
    if (doo)           { p.push(doo);          q += ` AND r.datum <= $${p.length}`; }
    if (gradiliste_id) { p.push(gradiliste_id); q += ` AND r.gradiliste_id = $${p.length}`; }
    q += ' ORDER BY r.datum DESC, r.created_at DESC';
    const rows = await pool.query(q, p);
    res.json(rows.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

