    const _premChip = (x, y, txt, filled) => {
      const w = doc.font(filled ? FBOLD : FREG).fontSize(9).widthOfString(txt) + 18;
      if (filled) { doc.roundedRect(x, y, w, 19, 9.5).fillColor(COL.BORDEAUX).fill(); doc.fillColor(COL.WHITE); }
      else { doc.roundedRect(x, y, w, 19, 9.5).fillColor(COL.CREAM2).fill(); doc.roundedRect(x, y, w, 19, 9.5).strokeColor(COL.LINE2).lineWidth(0.8).stroke(); doc.fillColor(COL.INK2); }
      doc.font(filled ? FBOLD : FREG).fontSize(9).text(txt, x + 9, y + 5);
      return w;
    };
    
    // ═══════════════════════════════════════════════════════════════
    // STRANICA 1: NASLOVNA (cream pozadina v501.28)
