      if (i > 0) doc.moveTo(x - 14, _ly + 14).lineTo(x - 14, _ly + 62).strokeColor(COL.LINE2).lineWidth(0.6).stroke();
      doc.fillColor(COL.INK3).font(FREG).fontSize(7).text(_ledLbl[i], x, _ly + 16, { characterSpacing: 1.5 });
      if (i === 0) doc.fillColor(COL.INK).font(FBOLD).fontSize(10.5).text(_ledVal[i], x, _ly + 35, { width: 162, lineGap: 0 });
      else doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(30).text(_ledVal[i], x, _ly + 28);
