        // suptilna zebra
        if (_tlZebra % 2 === 1) doc.fillColor(COL.CREAM3).rect(TL_X, timelineY, TL_W, rowH).fill();
        
        const yT = timelineY + 6;
        doc.fillColor(isWeekend ? COL.BORDEAUX : COL.INK).font(FBOLD).fontSize(9.5).text(datStr, cDat, yT, { lineBreak: false });
        doc.fillColor(isWeekend ? COL.BORDEAUX : COL.INK3).font(FREG).fontSize(9).text(dan, cDan, yT + 0.5, { lineBreak: false });
        doc.fillColor(COL.INK).font(FBOLD).fontSize(10).text(String(d.sviRadnici || '—'), cRad, yT, { lineBreak: false });
