// Dohvati izmjere za gradilište
app.get('/api/izmjera', auth, staff, async (req, res) => {
  const { gradiliste_id } = req.query;
  // gradiliste_id opcionalan — bez njega vraća sve izmjere (Ukupno prikaz)
  try {
    const p = [];
    let where = '';
    if (gradiliste_id) { p.push(gradiliste_id); where = 'WHERE i.gradiliste_id=$1'; }
    const r = await pool.query(
      `SELECT i.id, i.naziv, i.tip, i.qnap_path, i.ima_foto, i.gradiliste_id,
              g.naziv AS naziv_gradilista,
              CASE WHEN i.foto_base64 IS NOT NULL THEN true ELSE false END AS has_cache,
              i.created_at
       FROM izmjera i
       LEFT JOIN gradilista g ON g.id = i.gradiliste_id
       ${where}
       ORDER BY i.created_at DESC`,
      p
    );
    res.json(r.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Upload više izmjera odjednom — batch (slike + PDF)
app.post('/api/izmjera/batch', auth, staff, async (req, res) => {
  const { gradiliste_id, stavke } = req.body;
  // stavke = [{ naziv, tip, file_base64 }, ...]
  // ⭐ v135.7.215: Validacija gradiliste_id (mora biti pozitivan int)
  const gradId = parseInt(gradiliste_id);
  if (!gradId || gradId <= 0) return res.status(400).json({ error: 'Nedostaje ili neispravan gradiliste_id' });
  if (!Array.isArray(stavke) || !stavke.length)
                                return res.status(400).json({ error: 'Nedostaje stavke[]' });
  // ⭐ v135.7.215: Limit broj stavki (sprečava memory exhaustion)
  if (stavke.length > 30) {
    return res.status(400).json({ error: 'Maksimalno 30 stavki po batch-u' });
  }

  // ⭐ AUDIT #4: Atomic batch + per-stavka result tracking
  //   PRIJE: ako 5. PDF fail-a QNAP, prvih 4 su upisani s qnap_path=NULL, server vraća ok:true
  //          → korisnik misli da je sve uspjelo, ali zapravo nije
  //   SAD: track failed/success per stavka, vrati allOk + lista failed-ih za retry
  //          → ako QNAP padne za pojedinu stavku, korisnik dobiva jasnu listu
  //          → frontend može pokazati retry gumb za failed stavke

  try {
    // Pripremi QNAP jednom za cijeli batch
    let gradNaziv = null, qnapBase = null, qnapBaseUrl = null, qnapHdrs = null;
    if (process.env.QNAP_WEBDAV_URL) {
      const gradR = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id]);
      gradNaziv    = (gradR.rows[0]?.naziv||'gradiliste').replace(/[/\\:*?"<>|]/g,'_').trim();
      qnapBase     = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
      qnapBaseUrl  = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
      const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
      qnapHdrs     = { Authorization: `Basic ${auth64}` };
      // Kreiraj foldere jednom
      // ⭐ v502.20.28 (Ivan, 27.05.2026): MKCOL dobiva 5s timeout (prije bez → 60s vis ako QNAP spor)
      for (const f of [`${qnapBase}/Izmjera`, `${qnapBase}/Izmjera/${gradNaziv}`]) {
        await fetch(`${qnapBaseUrl}${f}/`, { method:'MKCOL', headers:qnapHdrs, signal: AbortSignal.timeout(5000) }).catch(e => console.warn('[izmjera MKCOL]', e?.message || String(e)));
      }
    }

    const pad = n => String(n).padStart(2,'0');
    // ⭐ v502.20.29 (Ivan, 28.05.2026): PARALELNI upload svih stavki (prije: sekvencijalni for)
    //   PROBLEM: za N stavki, svaki upload je await-an redom → N × 8s = sporo.
    //   Izmjera batch ima per-stavka result tracking (frontend treba točan success/fail za 
    //   retry), pa NE možemo u potpuni background kao dnevnik. ALI možemo sve stavke 
    //   uploadati ISTOVREMENO (Promise.all) → ukupno vrijeme ~8s umjesto N×8s.
    //   Svaka stavka i dalje vraća svoj success/fail u results[].
    const uploadStavka = async (i) => {
      const { naziv, tip, file_base64 } = stavke[i];
      if (!file_base64) {
        return { index: i, success: false, error: 'Nedostaje file_base64' };
      }
      const fileTip   = tip || 'slika';
      const fileNaziv = (naziv || 'izmjera').slice(0, 60);

      let qnapPath = null;
      let b2Path = null;
      let qnapError = null;
      if (qnapBaseUrl || b2Enabled()) {
        try {
          const now  = new Date();
          const ts   = `${pad(now.getDate())}_${pad(now.getMonth()+1)}_${now.getFullYear()}_${pad(now.getHours())}-${pad(now.getMinutes())}-${pad(now.getSeconds())}_${pad(i)}`;
          const safeName    = fileNaziv.replace(/[/\\:*?"<>|]/g,'_').slice(0,40);
          const ext         = fileTip === 'pdf' ? 'pdf' : 'jpg';
          const fname       = `${ts}_${safeName}.${ext}`;
          const targetPath  = `Izmjera/${gradNaziv || 'gradiliste'}/${fname}`;
          const rawData     = file_base64.replace(/^data:[^;]+;base64,/, '');
          const fileBuffer  = Buffer.from(rawData, 'base64');
          const contentType = fileTip === 'pdf' ? 'application/pdf' : 'image/jpeg';
          
          let qnapPromise = Promise.resolve(null);
          if (qnapBaseUrl) {
            qnapPromise = fetch(`${qnapBaseUrl}${qnapBase}/Izmjera/${gradNaziv}/${fname}`, {
              method: 'PUT',
              headers: { ...qnapHdrs, 'Content-Type': contentType },
              body: fileBuffer,
              signal: AbortSignal.timeout(8000)
            });
          }
          
          const [qnapResult, b2Res] = await Promise.allSettled([
            qnapPromise,
            b2Enabled() ? b2Upload(fileBuffer, targetPath, contentType) : Promise.resolve(null)
          ]).then(rs => [
            rs[0].status === 'fulfilled' ? rs[0].value : null,
            rs[1].status === 'fulfilled' ? rs[1].value : null
          ]);
          
          const qnapOk = qnapResult && (qnapResult.ok || qnapResult.status === 201 || qnapResult.status === 204);
          if (qnapOk) qnapPath = targetPath;
          if (b2Res) b2Path = b2Res;
          if (!qnapOk && qnapBaseUrl) {
            qnapError = `QNAP upload status ${qnapResult?.status || 'fail'}`;
          }
          console.log(`[izmjera batch] idx=${i} QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
        } catch(e) { 
          console.error('Izmjera batch upload:', e.message); 
          qnapError = `Exception: ${e.message}`;
        }
      }

      // ⭐ v683 (C1, Ivan): ako OBA storage-a (QNAP+B2) padnu, NE gubi foto — spremi malu sličicu u DB
      //   kao zajamčeni fallback + flag da puni upload treba retry. Foto se više nikad ne gubi.
      let storageFailed = false;
      let cacheB64;
      if ((qnapBaseUrl || b2Enabled()) && !qnapPath && !b2Path) {
        storageFailed = true;
        cacheB64 = await _generirajThumbServer(file_base64).catch(() => file_base64);
      } else {
        // Bez konfiguriranog storage-a: original je jedini izvor (spremi ga cijelog)
        cacheB64 = (!qnapPath && !b2Path) ? file_base64 : null;
      }
      try {
        let r;
        try {
          r = await pool.query(
            `INSERT INTO izmjera(gradiliste_id, radnik_id, naziv, tip, qnap_path, b2_path, foto_base64, ima_foto)
             VALUES($1,$2,$3,$4,$5,$6,$7,true) RETURNING id`,
            [gradiliste_id, req.user.id, fileNaziv, fileTip, qnapPath, b2Path, cacheB64]
          );
        } catch(colErr) {
          console.warn('[izmjera batch] fallback bez b2_path:', colErr.message);
          r = await pool.query(
            `INSERT INTO izmjera(gradiliste_id, radnik_id, naziv, tip, qnap_path, foto_base64, ima_foto)
             VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id`,
            [gradiliste_id, req.user.id, fileNaziv, fileTip, qnapPath, cacheB64]
          );
        }
        return { 
          index: i, success: true, id: r.rows[0].id, 
          naziv: fileNaziv, tip: fileTip, qnap_path: qnapPath,
          storage_failed: storageFailed 
        };
      } catch(dbErr) {
        console.error('[izmjera/batch] DB INSERT fail:', dbErr.message);
        if (qnapPath && qnapBaseUrl) {
          fetch(`${qnapBaseUrl}${qnapBase}/${qnapPath}`, { 
            method: 'DELETE', headers: qnapHdrs 
          }).catch(() => {});
        }
        return { 
          index: i, success: false, naziv: fileNaziv,
          error: 'DB insert failed: ' + dbErr.message 
        };
      }
    };

    // ⭐ v502.20.31 (Ivan, 28.05.2026): CONCURRENCY LIMIT umjesto svih odjednom
    //   BUG (bug hunt): Promise.all(stavke.map) pokretao SVIH do 30 PUT-ova na QNAP 
    //   istovremeno → kućni NAS (WebDAV) može odbiti veze ili timeout-ati pod 30 
    //   paralelnih konekcija. FIX: batch po 5 (isti pristup kao storage scan).
    //   Per-stavka result tracking ostaje, samo se izvršava u kontroliranim grupama.
    const IZMJERA_CONCURRENCY = 5;
    const results = [];
    for (let i = 0; i < stavke.length; i += IZMJERA_CONCURRENCY) {
      const batchIdx = [];
      for (let j = i; j < Math.min(i + IZMJERA_CONCURRENCY, stavke.length); j++) batchIdx.push(j);
      const batchResults = await Promise.all(batchIdx.map(idx => uploadStavka(idx)));
      results.push(...batchResults);
    }

    const successful = results.filter(r => r.success);
    const failed = results.filter(r => !r.success);
    const allOk = failed.length === 0;
    
    // Vrati detaljni report
    res.json({ 
      ok: allOk, 
      count: successful.length,
      failed_count: failed.length,
      ids: successful,  // legacy compat: stari format
      results,           // novi: per-stavka detalji
      failed             // za retry ako frontend zna baratati
    });
  } catch(e) { 
    console.error('[izmjera/batch] global error:', e.message);
    res.status(500).json({ error: e.message }); 
  }
});

// Upload izmjere (slika ili PDF)
app.post('/api/izmjera', auth, staff, async (req, res) => {
  const { gradiliste_id, naziv, tip, file_base64 } = req.body;
  if (!gradiliste_id) return res.status(400).json({ error: 'Nedostaje gradiliste_id' });
  if (!file_base64)   return res.status(400).json({ error: 'Nedostaje file_base64' });
  const fileTip = tip || 'slika'; // 'slika' | 'pdf'
  const fileNaziv = naziv || 'izmjera';

  try {
    // ⭐ v135.7.209: Dual-write QNAP + B2
    // ⭐ v135.7.210: Radi i ako je samo B2 dostupan (bez QNAP-a)
    let qnapPath = null;
    let b2Path = null;
    if (process.env.QNAP_WEBDAV_URL || b2Enabled()) {
      const gradR = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id]);
      const gradNaziv = (gradR.rows[0]?.naziv||'gradiliste').replace(/[/\\:*?"<>|]/g,'_').trim();

      // Ime fajla s timestampom
      const now  = new Date();
      const pad  = n => String(n).padStart(2,'0');
      const ts   = `${pad(now.getDate())}_${pad(now.getMonth()+1)}_${now.getFullYear()}_${pad(now.getHours())}-${pad(now.getMinutes())}-${pad(now.getSeconds())}`;
      const safeName = fileNaziv.replace(/[/\\:*?"<>|]/g,'_').slice(0,40);
      const ext  = fileTip === 'pdf' ? 'pdf' : 'jpg';
      const fname = `${ts}_${safeName}.${ext}`;
      const targetPath = `Izmjera/${gradNaziv}/${fname}`;

      // Strip data URI prefix
      const rawData = file_base64.replace(/^data:[^;]+;base64,/, '');
      const fileBuffer = Buffer.from(rawData, 'base64');
      const contentType = fileTip === 'pdf' ? 'application/pdf' : 'image/jpeg';
      
      // QNAP setup (samo ako QNAP enabled)
      let qnapPromise = Promise.resolve(null);
      if (process.env.QNAP_WEBDAV_URL) {
        const qnapBase    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
        const qnapBaseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
        const auth64      = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
        const hdrs        = { Authorization: `Basic ${auth64}` };

        // Kreiraj foldere s 3s timeout
        for (const f of [`${qnapBase}/Izmjera`, `${qnapBase}/Izmjera/${gradNaziv}`]) {
          await fetch(`${qnapBaseUrl}${f}/`, { method:'MKCOL', headers:hdrs, signal: AbortSignal.timeout(3000) }).catch(() => {});
        }
        
        qnapPromise = fetch(`${qnapBaseUrl}${qnapBase}/Izmjera/${gradNaziv}/${fname}`, {
          method: 'PUT',
          headers: { ...hdrs, 'Content-Type': contentType },
          body: fileBuffer,
          signal: AbortSignal.timeout(8000)
        });
      }

      // ⭐ v135.7.209: Paralelni QNAP + B2 upload
      const [qnapResult, b2Res] = await Promise.allSettled([
        qnapPromise,
        b2Enabled() ? b2Upload(fileBuffer, targetPath, contentType) : Promise.resolve(null)
      ]).then(rs => [
        rs[0].status === 'fulfilled' ? rs[0].value : null,
        rs[1].status === 'fulfilled' ? rs[1].value : null
      ]);
      
      const qnapOk = qnapResult && (qnapResult.ok || qnapResult.status === 201 || qnapResult.status === 204);
      if (qnapOk) qnapPath = targetPath;
      if (b2Res) b2Path = b2Res;
      console.log(`[izmjera upload] QNAP=${qnapOk?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
    }

    // Upiši u bazu — bez QNAP: spremi i slike i PDF u bazu (jedini storage)
    // S QNAP/B2: ne cachei PDF (prevelik), slike se cacheiraju pri prvom dohvatu
    const cacheB64 = (!qnapPath && !b2Path) ? file_base64 : null;
    let r;
    try {
      r = await pool.query(
        `INSERT INTO izmjera(gradiliste_id, radnik_id, naziv, tip, qnap_path, b2_path, foto_base64, ima_foto)
         VALUES($1,$2,$3,$4,$5,$6,$7,true) RETURNING id`,
        [gradiliste_id, req.user.id, fileNaziv, fileTip, qnapPath, b2Path, cacheB64]
      );
    } catch(colErr) {
      // Fallback ako b2_path kolona ne postoji
      console.warn('[izmjera] fallback bez b2_path:', colErr.message);
      r = await pool.query(
        `INSERT INTO izmjera(gradiliste_id, radnik_id, naziv, tip, qnap_path, foto_base64, ima_foto)
         VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id`,
        [gradiliste_id, req.user.id, fileNaziv, fileTip, qnapPath, cacheB64]
      );
    }
    // ⭐ v447 (Ivan): push ostalima — nova izmjera, kategorija 'izmjera'
    pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id])
      .then(gN => sendPush(req.user.id, '📐 Nova izmjera', `${req.user.ime} ${req.user.prezime} · ${gN.rows[0]?.naziv||''} · ${naziv||'izmjera'}`, '/?tab=izmjera', 'izmjera')).catch(()=>{});
    res.json({ ok: true, id: r.rows[0].id, qnap_path: qnapPath, b2_path: b2Path });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Dohvati jedan fajl iz izmjere (slika ili PDF kao base64)
// ⭐ v135.7.202: B2 fallback čitanje
app.get('/api/izmjera/:id/foto', auth, async (req, res) => {
  try {
    let r;
    try {
      r = await pool.query(
        'SELECT foto_base64, qnap_path, b2_path, tip FROM izmjera WHERE id=$1', [req.params.id]
      );
    } catch(colErr) {
      r = await pool.query(
        'SELECT foto_base64, qnap_path, tip FROM izmjera WHERE id=$1', [req.params.id]
      );
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Nema izmjere' });
    const row = r.rows[0];

    if (row.foto_base64) return res.json({ foto_base64: row.foto_base64, tip: row.tip });

    const buf = await fetchImageWithFallback(row.qnap_path, row.b2_path);
    if (buf) {
      const mime = row.tip === 'pdf' ? 'application/pdf' : 'image/jpeg';
      const b64 = `data:${mime};base64,` + buf.toString('base64');
      return res.json({ foto_base64: b64, tip: row.tip });
    }
    return res.status(404).json({ error: 'Nema fajla' });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

