app.post('/api/ponude/:id/slike', auth, staff, async (req, res) => {
  try {
    const p = await pool.query('SELECT id FROM ponude WHERE id=$1', [req.params.id]);
    if (!p.rows.length) return res.status(404).json({ error: 'Ponuda nije pronađena.' });
    const slike = Array.isArray(req.body && req.body.slike) ? req.body.slike : [];
    if (!slike.length) return res.status(400).json({ error: 'Nema slika.' });
    let uneseno = 0;
    for (const sl of slike.slice(0, 30)) {
      const data = String((sl && sl.file_base64) || '');
      if (!data || data.length < 50) continue;
      // ⭐ v674: kompresija u WebP (resize max 1600px, q80) — puno manja baza; auto-rotacija po EXIF-u
      let store;
      try {
        const _sharp = require('sharp');
        const web = await _sharp(Buffer.from(data, 'base64')).rotate().resize({ width: 1600, height: 1600, fit: 'inside', withoutEnlargement: true }).webp({ quality: 80 }).toBuffer();
        store = 'data:image/webp;base64,' + web.toString('base64');
      } catch (_) { store = data.startsWith('data:') ? data : ('data:image/jpeg;base64,' + data); }
      await pool.query('INSERT INTO ponude_slike(ponuda_id, naziv, foto_base64) VALUES($1,$2,$3)', [req.params.id, String((sl && sl.naziv) || '').slice(0, 200), store]);
      uneseno++;
    }
    res.json({ ok: true, uneseno });
  } catch (e) { console.error('[ponude slike]', e && e.message); res.status(500).json({ error: 'Greška pri spremanju slika.' }); }
});
