app.delete('/api/izmjera/:id', auth, staff, async (req, res) => {
  try {
    // ⭐ v135.7.209: dodano b2_path
    let r;
    try {
      r = await pool.query('SELECT qnap_path, b2_path FROM izmjera WHERE id=$1', [req.params.id]);
    } catch(colErr) {
      r = await pool.query('SELECT qnap_path FROM izmjera WHERE id=$1', [req.params.id]);
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Nema izmjere' });
    const { qnap_path, b2_path } = r.rows[0];

    await pool.query('DELETE FROM izmjera WHERE id=$1', [req.params.id]);

    // Briši s QNAP-a
    if (qnap_path && process.env.QNAP_WEBDAV_URL) {
      const base    = (process.env.QNAP_BASE_PATH||'/APLIKACIJA').replace(/\/$/,'');
      const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/,'');
      const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
      fetch(`${baseUrl}${base}/${qnap_path}`, {
        method:'DELETE', headers:{ Authorization:`Basic ${auth64}` }
      }).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    }
    // ⭐ v135.7.209: paralelno B2 brisanje
    if (b2_path && b2Enabled()) {
      setImmediate(async () => {
        try {
          const ok = await b2Delete(b2_path);
          console.log(`[B2 DELETE] izmjera ${b2_path}: ${ok ? 'OK' : 'FAIL'}`);
        } catch(e) { console.warn('[B2 DELETE] izmjera:', e.message); }
      });
    }
    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/dnevnik', auth, staff, async (req, res) => {
  const { od, do: doo, gradiliste_id } = req.query;
  const pod_naziv = req.query.pod_naziv || null;
  const limit  = parseInt(req.query.limit)  || null;
  const offset = parseInt(req.query.offset) || 0;
  try {
    let q = `
      SELECT d.id, d.datum, d.gradiliste_id, d.broj_radnika, d.komentar,
             d.ima_foto,
             d.qnap_path, d.pod_naziv, COALESCE(d.tip,'foto') AS tip,
             CASE WHEN d.foto_base64 IS NOT NULL OR d.qnap_path IS NOT NULL THEN true ELSE false END AS has_foto_base64,
             d.created_at,
             COALESCE(d.vrijeme, '') AS vrijeme,
             d.temperatura,
             r.ime, r.prezime, g.naziv AS naziv_gradilista
      FROM dnevnik d
      JOIN radnici r ON d.radnik_id = r.id
      JOIN gradilista g ON d.gradiliste_id = g.id
      WHERE 1=1`;
    const p = [];
    if (od)            { p.push(od);           q += ` AND d.datum >= $${p.length}`; }
    if (doo)           { p.push(doo);          q += ` AND d.datum <= $${p.length}`; }
    if (gradiliste_id) { p.push(gradiliste_id); q += ` AND d.gradiliste_id = $${p.length}`; }
    if (pod_naziv) {
      if (pod_naziv === '__NULL__') {
        q += ` AND d.pod_naziv IS NULL`;
      } else {
        p.push(pod_naziv); q += ` AND d.pod_naziv = $${p.length}`;
      }
    }
    q += ' ORDER BY d.datum DESC, d.id ASC';
    if (limit)  { p.push(limit);  q += ` LIMIT $${p.length}`; }
    if (offset) { p.push(offset); q += ` OFFSET $${p.length}`; }
    const r = await pool.query(q, p);
    res.json(r.rows);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v135.7.122 (FEATURE DNV-4): Pretraga komentara across all months
//   GET /api/dnevnik/search?q=...&limit=50
//   - ILIKE search po komentaru (case-insensitive)
//   - Min 3 znaka query
//   - Vraća do 50 rezultata sortiranih po datum DESC
//   - Optimization: postavi index ako nedostaje (one-time)
app.get('/api/dnevnik/search', auth, staff, async (req, res) => {
  const q = String(req.query.q || '').trim();
  const limit = Math.min(parseInt(req.query.limit) || 50, 200);
  
  if (q.length < 3) {
    return res.status(400).json({ error: 'Query mora biti najmanje 3 znaka' });
  }
  // Striktna validacija — sprječava SQL bezobrazluk u LIKE pattern-u
  if (q.length > 100) {
    return res.status(400).json({ error: 'Query previše dugačak (max 100 znakova)' });
  }
  
  try {
    // Best-effort: stvori index ako nedostaje (idempotent CREATE INDEX IF NOT EXISTS)
    pool.query(`CREATE INDEX IF NOT EXISTS idx_dnevnik_komentar_lower 
                ON dnevnik (LOWER(komentar)) WHERE komentar IS NOT NULL`).catch(() => {});
    
    // Escape % i _ wildcards iz user query-a (treba točan match na pattern)
    const escaped = q.replace(/[\\%_]/g, '\\$&');
    const pattern = `%${escaped}%`;
    
    const r = await pool.query(`
      SELECT d.id, d.datum, d.gradiliste_id, d.broj_radnika, d.komentar,
             d.ima_foto, d.qnap_path, d.pod_naziv,
             CASE WHEN d.foto_base64 IS NOT NULL OR d.qnap_path IS NOT NULL THEN true ELSE false END AS has_foto_base64,
             d.created_at,
             COALESCE(d.vrijeme, '') AS vrijeme,
             d.temperatura,
             r.ime, r.prezime, g.naziv AS naziv_gradilista
      FROM dnevnik d
      JOIN radnici r ON d.radnik_id = r.id
      JOIN gradilista g ON d.gradiliste_id = g.id
      WHERE d.komentar ILIKE $1 ESCAPE '\\'
      ORDER BY d.datum DESC, d.id DESC
      LIMIT $2
    `, [pattern, limit]);
    
    res.json({ q, count: r.rows.length, results: r.rows });
  } catch (e) {
    console.error('[dnevnik search]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.129 (FEATURE DNV-03): Time-lapse Image List
//   GET /api/dnevnik/timelapse-images?gradiliste_id=X&od=YYYY-MM-DD&do=YYYY-MM-DD&perday=2
//   perday: 1 = prva slika dana, 2 = prva + zadnja, 0 = sve slike
//   ⭐ v135.7.130: Limit 1500 dana
//   ⭐ v135.7.134: perday opcija — user može odabrati 1, 2 ili sve slike po danu
app.get('/api/dnevnik/timelapse-images', auth, staff, async (req, res) => {
  const gid = parseInt(req.query.gradiliste_id);
  const od = req.query.od;
  const doo = req.query.do;
  const perday = parseInt(req.query.perday);  // 0 = sve, 1 = prva, 2 = first+last (default)
  const perdayMode = (perday === 0 || perday === 1 || perday === 2) ? perday : 2;
  
  if (!gid) return res.status(400).json({ error: 'gradiliste_id obavezan' });
  if (!od || !doo) return res.status(400).json({ error: 'Datumski raspon (od + do) obavezan' });
  if (!/^\d{4}-\d{2}-\d{2}$/.test(od) || !/^\d{4}-\d{2}-\d{2}$/.test(doo)) {
    return res.status(400).json({ error: 'Datumi moraju biti YYYY-MM-DD format' });
  }
  
  // ⭐ v135.7.130: Sanity check max 1500 dana (~4 godine) — dovoljno za cijeli vijek bilo kojeg gradilišta
  const dOd = new Date(od + 'T00:00:00Z');
  const dDo = new Date(doo + 'T00:00:00Z');
  const dani = Math.round((dDo - dOd) / 86400000);
  if (dani > 1500) return res.status(400).json({ error: 'Max raspon 1500 dana (~4 god)' });
  if (dani < 1) return res.status(400).json({ error: 'Datumski raspon nevažeći (do < od)' });
  
  try {
    // ⭐ v135.7.134: perday logika
    //   0 = sve slike (najduži video)
    //   1 = samo prva slika dana
    //   2 = prva + zadnja u danu (default)
    // ⭐ v135.7.136: Skipnemo video unose (tip='video') — time-lapse je samo za slike
    //   Plus: defensive za stare zapise bez 'tip' kolone (COALESCE 'slika')
    let queryStr;
    if (perdayMode === 0) {
      // Sve slike
      queryStr = `
        SELECT 
          id AS dnevnik_id, datum, qnap_path, ima_foto,
          COALESCE(vrijeme, '') AS vrijeme, broj_radnika,
          (SELECT COUNT(*) FROM dnevnik d2 WHERE d2.datum = dnevnik.datum 
           AND d2.gradiliste_id = dnevnik.gradiliste_id AND d2.ima_foto AND COALESCE(d2.tip, 'slika') = 'slika') AS broj_fota_taj_dan
        FROM dnevnik
        WHERE gradiliste_id = $1 
          AND datum BETWEEN $2 AND $3
          AND ima_foto = true
          AND COALESCE(tip, 'slika') = 'slika'
        ORDER BY datum ASC, id ASC
      `;
    } else if (perdayMode === 1) {
      // Samo prva slika svakog dana
      queryStr = `
        SELECT DISTINCT ON (datum) 
               id AS dnevnik_id, datum, qnap_path, ima_foto, 
               COALESCE(vrijeme, '') AS vrijeme, broj_radnika,
               (SELECT COUNT(*) FROM dnevnik d2 WHERE d2.datum = dnevnik.datum 
                AND d2.gradiliste_id = dnevnik.gradiliste_id AND d2.ima_foto AND COALESCE(d2.tip, 'slika') = 'slika') AS broj_fota_taj_dan
        FROM dnevnik
        WHERE gradiliste_id = $1 
          AND datum BETWEEN $2 AND $3
          AND ima_foto = true
          AND COALESCE(tip, 'slika') = 'slika'
        ORDER BY datum ASC, id ASC
      `;
    } else {
      // perdayMode === 2 — prva + zadnja
      queryStr = `
        WITH ranked AS (
          SELECT 
            id AS dnevnik_id, datum, qnap_path, ima_foto,
            COALESCE(vrijeme, '') AS vrijeme, broj_radnika,
            ROW_NUMBER() OVER (PARTITION BY datum ORDER BY id ASC) AS rn_first,
            ROW_NUMBER() OVER (PARTITION BY datum ORDER BY id DESC) AS rn_last,
            COUNT(*) OVER (PARTITION BY datum) AS broj_fota_taj_dan
          FROM dnevnik
          WHERE gradiliste_id = $1 
            AND datum BETWEEN $2 AND $3
            AND ima_foto = true
            AND COALESCE(tip, 'slika') = 'slika'
        )
        SELECT dnevnik_id, datum, qnap_path, ima_foto, vrijeme, broj_radnika, broj_fota_taj_dan
        FROM ranked
        WHERE rn_first = 1 OR (rn_last = 1 AND broj_fota_taj_dan > 1)
        ORDER BY datum ASC, dnevnik_id ASC
      `;
    }
    const r = await pool.query(queryStr, [gid, od, doo]);
    
    // Provjeri ima li slike — ako ne, friendly error
    if (!r.rows.length) {
      return res.status(404).json({ 
        error: 'Nema slika u Dnevniku za zadani raspon', 
        gradiliste_id: gid, od, doo, dana_pretrazeno: dani 
      });
    }
    
    res.json({ 
      gradiliste_id: gid, 
      od, do: doo, 
      dana_pretrazeno: dani,
      slika_count: r.rows.length,
      images: r.rows 
    });
  } catch(e) {
    console.error('[timelapse-images]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.130 (FEATURE DNV-03 nadogradnja): "Cijeli vijek" range
//   GET /api/dnevnik/timelapse-range?gradiliste_id=X&perday=2
//   Vraća: { first_date, last_date, ukupno_dana, slika_count }
//   ⭐ v135.7.134: slika_count ovisi o perday opciji (0/1/2)
app.get('/api/dnevnik/timelapse-range', auth, staff, async (req, res) => {
  const gid = parseInt(req.query.gradiliste_id);
  if (!gid) return res.status(400).json({ error: 'gradiliste_id obavezan' });
  const perday = parseInt(req.query.perday);
  const perdayMode = (perday === 0 || perday === 1 || perday === 2) ? perday : 2;
  
  try {
    // ⭐ v135.7.134: slika_count ovisi o perday opciji
    //   perday=0 → ukupan broj svih slika
    //   perday=1 → broj distinct datuma sa slikom (1 po danu)
    //   perday=2 → LEAST(daily_count, 2) — sumira do 2 po danu
    let countExpr;
    if (perdayMode === 0) {
      countExpr = 'SUM(daily_count)';
    } else if (perdayMode === 1) {
      countExpr = 'COUNT(*)';  // count distinct datums
    } else {
      countExpr = 'SUM(LEAST(daily_count, 2))';
    }
    
    const r = await pool.query(`
      SELECT 
        MIN(datum) AS first_date,
        MAX(datum) AS last_date,
        ${countExpr} AS slika_count
      FROM (
        SELECT datum, COUNT(*) AS daily_count
        FROM dnevnik
        WHERE gradiliste_id = $1 
          AND ima_foto = true 
          AND COALESCE(tip, 'slika') = 'slika'
        GROUP BY datum
      ) AS dnevni_count
    `, [gid]);
    
    const row = r.rows[0];
    if (!row.first_date) {
      return res.status(404).json({ 
        error: 'Nema slika u Dnevniku za ovo gradilište', 
        gradiliste_id: gid 
      });
    }
    
    // Format dates as YYYY-MM-DD strings (Postgres vraća Date objekte)
    const fmtDate = (d) => {
      if (!d) return null;
      if (typeof d === 'string') return d.slice(0, 10);
      const yyyy = d.getFullYear();
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      const dd = String(d.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    };
    
    const first = fmtDate(row.first_date);
    const last = fmtDate(row.last_date);
    const dOd = new Date(first + 'T00:00:00Z');
    const dDo = new Date(last + 'T00:00:00Z');
    const ukupno_dana = Math.round((dDo - dOd) / 86400000) + 1;
    
    res.json({
      gradiliste_id: gid,
      first_date: first,
      last_date: last,
      ukupno_dana,
      slika_count: parseInt(row.slika_count)
    });
  } catch(e) {
    console.error('[timelapse-range]', e.message);
    res.status(500).json({ error: e.message });
  }
});

