// ── EXCEL EXPORT ──────────────────────────────────────────────────────────────

// ── HELPER: sanitiziraj naziv za QNAP folder/filename (ASCII-safe) ─────────
// Pretvori "Hercegovačka 56" → "Hercegovacka_56" (bez dijakritika + bez razmaka)
function sanitizeFolderName(naziv) {
  if (!naziv) return 'Bez_naziva';
  // Hrvatske dijakritike → ASCII
  const map = { 'č':'c','ć':'c','š':'s','đ':'d','ž':'z',
                'Č':'C','Ć':'C','Š':'S','Đ':'D','Ž':'Z',
                'ä':'a','ö':'o','ü':'u','ß':'ss' };
  let s = String(naziv).split('').map(ch => map[ch] || ch).join('');
  // Decompose remaining accents (NFD) i ukloni accent marks
  try { s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); } catch(_e) {}
  // Zamijeni razmake i specijalne znakove podvlakom
  s = s.replace(/[\\/<>:"|?*]/g, '_').replace(/\s+/g, '_').replace(/_+/g, '_');
  // Ukloni leading/trailing underscores i dot
  s = s.replace(/^[_.]+|[_.]+$/g, '');
  // Limit dužine
  return s.slice(0, 60) || 'Bez_naziva';
}

// ── HELPER: QNAP folder path za fasada gradilište ──────────────────────────
// Vraca "Fasade-AI/{slug_naziva}" - jedinstveni folder po gradilištu (bez ID prefix-a po Ivan-ovoj specifikaciji)
function fasadaQnapFolder(nazivGradilista) {
  return `Fasade-AI/${sanitizeFolderName(nazivGradilista)}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v465 (Ivan, 18.05.2026): STABLE PATH HELPER — "BRUTALNO SIGURNA" VEZA
// ═══════════════════════════════════════════════════════════════════════════
//   Generira stabilne (TS-FREE) putove za slike i anotirane.
//   Konvencija:
//     Multi:  Fasade-AI/<naziv>/proc<ID>/Procelje-<oznakaSafe>/{slika|anotirana}.jpg
//     Single: Fasade-AI/<naziv>/proc<ID>/{slika|anotirana}.jpg
//   
//   Zašto STABLE umjesto TS:
//   - Save = overwrite postojeće (atomic na razini WebDAV-a)
//   - Nema "create new + delete old" race condition-a → veza se NE PUCA
//   - DB referencija postavljena jednom, vrijedi zauvijek
//   - Idempotentno: ako save fail-a u sredini, sljedeći save isti put → overwrite
//   - B2 dual-write i dalje radi (backup)
//   
//   Args:
//     gradNaziv: ime gradilišta (kako u DB)
//     procjenaId: ID procjene (mora biti unaprijed poznat — vidi pre-fetch sekvence)
//     kind: 'slika' | 'anotirana'
//     proceljeOznaka: string oznake pročelja za multi, null za single/top-level
function fasadaStablePath(gradNaziv, procjenaId, kind, proceljeOznaka) {
  const procFolder = `${fasadaQnapFolder(gradNaziv)}/proc${procjenaId}`;
  if (proceljeOznaka) {
    const oznakaSafe = String(proceljeOznaka).replace(/[/\\:*?"<>|]/g, '_').slice(0, 40);
    return `${procFolder}/Procelje-${oznakaSafe}/${kind}.jpg`;
  }
  return `${procFolder}/${kind}.jpg`;
}

// Detekcija da li je path stable (v465+) ili legacy (TS-based)
function fasadaJeStablePath(p) {
  if (!p) return false;
  // Stable: završava na /slika.jpg ili /anotirana.jpg, plus sadrži /proc<broj>/
  return /\/proc\d+\//.test(p) && /\/(slika|anotirana)\.jpg$/.test(p);
}

// ════════════════════════════════════════════════════════════════════════════
// ═══ NAV[BE]: BACKBLAZE B2 FAILOVER + DUAL-WRITE (foto redundancija) ═══
// ⭐ v135.7.202 BACKBLAZE B2 LIVE FAILOVER
// ════════════════════════════════════════════════════════════════════════════
// Strategija: dual-write + read-with-fallback
//   - Pri uploadu: paralelno na QNAP I B2 (oba moraju uspjeti, ili bar jedan)
//   - Pri čitanju: prvo QNAP (5s timeout) → ako fail, automatski B2
//   - DB sprema OBA path-a: qnap_path (postojeći) i b2_path (novi nullable)
//
// Env varijable (postavit ćemo na Railway):
//   B2_KEY_ID         = Application Key ID iz Backblaze console
//   B2_APP_KEY        = Application Key Secret
//   B2_BUCKET_NAME    = ime buckete (npr. "zbuka-prod")
//   B2_ENABLED        = "true" ako želimo aktivirati (default false dok ne postavimo)
//
// Auth flow B2:
//   1. POST b2_authorize_account (Basic Auth) → vraća authToken + apiUrl + downloadUrl
//   2. POST b2_get_upload_url → vraća uploadUrl + uploadToken
//   3. POST <uploadUrl> s file → vraća fileId + fileName
//   4. GET <downloadUrl>/file/<bucket>/<path> za download
//
// Auth token vrijedi 24h — keširamo ga u memoriji.

let _b2AuthCache = null;  // { authToken, apiUrl, downloadUrl, accountId, bucketId, expires }

// ⭐ v135.7.210: Mutex za paralelne auth pokušaje (race condition fix)
//   PRIJE: 10 paralelnih upload-a → 10 pokušaja b2_authorize_account u sekundi → rate limited
//   SAD: ako je auth već u tijeku, čekaj njega umjesto novog poziva
let _b2AuthInFlight = null;

// Provjeri je li B2 omogućen (env var + config)
// ⭐ v135.7.203: Tolerantnija provjera env vars + log zašto nije aktivan (jednom na startu)
let _b2EnabledLogged = false;
function b2Enabled() {
  const enabled = String(process.env.B2_ENABLED || '').trim().toLowerCase();
  const isOn = ['true', '1', 'yes', 'on'].includes(enabled);
  const hasKeyId = !!(process.env.B2_KEY_ID && process.env.B2_KEY_ID.trim());
  const hasAppKey = !!(process.env.B2_APP_KEY && process.env.B2_APP_KEY.trim());
  const hasBucket = !!(process.env.B2_BUCKET_NAME && process.env.B2_BUCKET_NAME.trim());
  
  const result = isOn && hasKeyId && hasAppKey && hasBucket;
  
  // Log jednom pri startu/prvom pozivu — pomoć pri dijagnostici
  if (!_b2EnabledLogged) {
    _b2EnabledLogged = true;
    if (result) {
      console.log('[B2] ✓ Enabled — bucket:', process.env.B2_BUCKET_NAME);
    } else {
      console.log('[B2] ✗ DISABLED — uzroci:',
        !isOn ? `B2_ENABLED='${enabled}' (treba 'true')` : null,
        !hasKeyId ? 'B2_KEY_ID missing' : null,
        !hasAppKey ? 'B2_APP_KEY missing' : null,
        !hasBucket ? 'B2_BUCKET_NAME missing' : null
      );
    }
  }
  return result;
}

// Invalidate cache (pozvati pri 401 response)
function _b2InvalidateAuth() {
  _b2AuthCache = null;
  _b2AuthInFlight = null;
}

// Autoriziraj se na B2 (cached 22h — kraće od 24h zbog clock drift safe)
// ⭐ v135.7.210: Mutex spriječi paralelne auth pozive (race condition fix)
async function b2Authorize() {
  if (!b2Enabled()) return null;
  
  // Cache provjera — token vrijedi 24h, mi cache-iramo 22h za safe margin
  if (_b2AuthCache && _b2AuthCache.expires > Date.now()) {
    return _b2AuthCache;
  }
  
  // Ako auth već radi (paralelni poziv), čekaj njega
  if (_b2AuthInFlight) {
    return _b2AuthInFlight;
  }
  
  // Kreiraj promise za auth + spremi u in-flight da paralelni pozivi čekaju
  _b2AuthInFlight = (async () => {
    try {
      const auth64 = Buffer.from(`${process.env.B2_KEY_ID}:${process.env.B2_APP_KEY}`).toString('base64');
      const r = await fetch('https://api.backblazeb2.com/b2api/v3/b2_authorize_account', {
        method: 'GET',
        headers: { Authorization: `Basic ${auth64}` },
        signal: AbortSignal.timeout(10000)
      });
      if (!r.ok) {
        console.error('[B2 auth] HTTP', r.status, await r.text().catch(() => ''));
        return null;
      }
      const data = await r.json();
      
      // Pronađi bucketId za naš bucket
      const bucketName = process.env.B2_BUCKET_NAME;
      const bucketsUrl = `${data.apiInfo.storageApi.apiUrl}/b2api/v3/b2_list_buckets`;
      const bRes = await fetch(bucketsUrl, {
        method: 'POST',
        headers: { 
          Authorization: data.authorizationToken, 
          'Content-Type': 'application/json' 
        },
        body: JSON.stringify({ accountId: data.accountId, bucketName }),
        signal: AbortSignal.timeout(10000)
      });
      if (!bRes.ok) {
        console.error('[B2 list buckets] HTTP', bRes.status);
        return null;
      }
      const bData = await bRes.json();
      const bucket = (bData.buckets || []).find(b => b.bucketName === bucketName);
      if (!bucket) {
        console.error(`[B2] Bucket "${bucketName}" nije pronađen`);
        return null;
      }
      
      _b2AuthCache = {
        authToken: data.authorizationToken,
        apiUrl: data.apiInfo.storageApi.apiUrl,
        downloadUrl: data.apiInfo.storageApi.downloadUrl,
        accountId: data.accountId,
        bucketId: bucket.bucketId,
        bucketName,
        expires: Date.now() + 22 * 60 * 60 * 1000  // 22h (token traje 24h, safe margin)
      };
      console.log('[B2 auth] OK, bucket:', bucketName);
      return _b2AuthCache;
    } catch (e) {
      console.error('[B2 auth]', e.message);
      return null;
    } finally {
      _b2AuthInFlight = null;  // free mutex
    }
  })();
  
  return _b2AuthInFlight;
}

// Upload na B2 — vraća remotePath na success, null na fail
// ⭐ v135.7.210: Retry s fresh auth pri 401 (token expired before cache TTL)
async function b2Upload(buffer, remotePath, contentType = 'application/octet-stream') {
  return _b2UploadAttempt(buffer, remotePath, contentType, 0);
}

async function _b2UploadAttempt(buffer, remotePath, contentType, retryCount) {
  const auth = await b2Authorize();
  if (!auth) {
    console.error('[B2 upload] auth fail za', remotePath);
    return null;
  }
  
  try {
    // Step 1: get upload URL
    const urlRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_get_upload_url`, {
      method: 'POST',
      headers: { 
        Authorization: auth.authToken, 
        'Content-Type': 'application/json' 
      },
      body: JSON.stringify({ bucketId: auth.bucketId }),
      signal: AbortSignal.timeout(10000)
    });
    
    // ⭐ v135.7.210: Retry pri 401 (token expired) — invalidate cache i pokušaj jednom još
    if (urlRes.status === 401 && retryCount < 1) {
      console.warn('[B2 upload] 401 na get_upload_url — invalidate cache + retry');
      _b2InvalidateAuth();
      return _b2UploadAttempt(buffer, remotePath, contentType, retryCount + 1);
    }
    
    if (!urlRes.ok) {
      const errBody = await urlRes.text().catch(() => '');
      console.error('[B2 upload] get_upload_url HTTP', urlRes.status, errBody.slice(0, 200));
      return null;
    }
    const urlData = await urlRes.json();
    
    // Step 2: upload file
    const sha1 = require('crypto').createHash('sha1').update(buffer).digest('hex');
    const cleanPath = remotePath.replace(/^\//, '');
    const uploadRes = await fetch(urlData.uploadUrl, {
      method: 'POST',
      headers: {
        Authorization: urlData.authorizationToken,
        'Content-Type': contentType,
        'Content-Length': buffer.length.toString(),
        'X-Bz-File-Name': encodeURIComponent(cleanPath),
        'X-Bz-Content-Sha1': sha1,
      },
      body: buffer,
      signal: AbortSignal.timeout(60000)
    });
    
    // ⭐ v135.7.210: 401 na upload — retry s fresh auth
    if (uploadRes.status === 401 && retryCount < 1) {
      console.warn('[B2 upload] 401 na upload — invalidate cache + retry');
      _b2InvalidateAuth();
      return _b2UploadAttempt(buffer, remotePath, contentType, retryCount + 1);
    }
    
    // Pojačana provjera response-a
    const respText = await uploadRes.text();
    let respJson = null;
    try { respJson = JSON.parse(respText); } catch(e) {}
    
    if (!uploadRes.ok) {
      console.error(`[B2 upload] PUT FAIL ${cleanPath}: HTTP ${uploadRes.status}, body:`, respText.slice(0, 300));
      return null;
    }
    
    // Provjeri da response sadrži fileId (potvrda da je B2 spremio)
    if (!respJson || !respJson.fileId) {
      console.error(`[B2 upload] response nema fileId za ${cleanPath}: status=${uploadRes.status}, body:`, respText.slice(0, 300));
      return null;
    }
    
    console.log(`[B2 upload] OK ${cleanPath} (${buffer.length} B), fileId=${respJson.fileId.slice(0, 16)}...`);
    return cleanPath;
  } catch (e) {
    console.error('[B2 upload] EXCEPTION za', remotePath, ':', e.message);
    return null;
  }
}

// Fetch buffer s B2 — vraća Buffer ili null
// ⭐ v135.7.210: Retry pri 401 + parametar za timeout
async function b2FetchBuffer(remotePath, timeoutMs = 15000) {
  return _b2FetchAttempt(remotePath, timeoutMs, 0);
}

async function _b2FetchAttempt(remotePath, timeoutMs, retryCount) {
  if (!remotePath) return null;
  const auth = await b2Authorize();
  if (!auth) return null;
  
  try {
    const cleanPath = remotePath.replace(/^\//, '');
    const fileUrl = `${auth.downloadUrl}/file/${auth.bucketName}/${cleanPath.split('/').map(encodeURIComponent).join('/')}`;
    const r = await fetch(fileUrl, {
      headers: { Authorization: auth.authToken },
      signal: AbortSignal.timeout(timeoutMs)
    });
    
    // 401 → invalidate + retry
    if (r.status === 401 && retryCount < 1) {
      console.warn(`[B2 fetch] 401 za ${cleanPath} — retry s fresh auth`);
      _b2InvalidateAuth();
      return _b2FetchAttempt(remotePath, timeoutMs, retryCount + 1);
    }
    
    if (!r.ok) {
      // 404 je normalno — file ne postoji, ne loguj alarm
      if (r.status !== 404) {
        console.warn(`[B2 fetch] ${cleanPath}: HTTP ${r.status}`);
      }
      return null;
    }
    const ab = await r.arrayBuffer();
    return Buffer.from(ab);
  } catch (e) {
    console.warn('[B2 fetch]', e.message);
    return null;
  }
}

// Brisanje s B2 — briše SVE verzije fajla (file versioning u B2 default-no je on)
// ⭐ v135.7.210: Mijenjano s startFileName → b2_list_file_versions s prefix-om za točan match
//   Prije: koristio startFileName s maxFileCount=1 koji vraća sljedeći alphabetical → moglo
//   pogrešno match-ati. Plus: brisalo samo NAJNOVIJU verziju, starije ostale na cloudu zauvijek.
//   Sad: list_file_versions s prefix=cleanPath, briše SVE verzije s točno tim imenom.
async function b2Delete(remotePath) {
  if (!remotePath) return false;
  const auth = await b2Authorize();
  if (!auth) return false;
  
  try {
    const cleanPath = remotePath.replace(/^\//, '');
    
    // List sve verzije s točno tim imenom (max 100, što je više nego dovoljno za isti path)
    const listRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_versions`, {
      method: 'POST',
      headers: { 
        Authorization: auth.authToken, 
        'Content-Type': 'application/json' 
      },
      body: JSON.stringify({ 
        bucketId: auth.bucketId, 
        startFileName: cleanPath,
        prefix: cleanPath,  // Točan match
        maxFileCount: 100 
      }),
      signal: AbortSignal.timeout(10000)
    });
    
    if (listRes.status === 401) {
      _b2InvalidateAuth();
      return false;  // Caller će opet pokušati ako treba
    }
    if (!listRes.ok) {
      console.warn(`[B2 delete] list_versions HTTP ${listRes.status}`);
      return false;
    }
    
    const listData = await listRes.json();
    // Filter: točno match na fileName (prefix može vratiti i sufix matchove)
    const versions = (listData.files || []).filter(f => f.fileName === cleanPath);
    
    if (versions.length === 0) {
      // Fajl već ne postoji — to nije greška
      return true;
    }
    
    // Briši sve verzije
    let deletedCount = 0;
    for (const file of versions) {
      try {
        const delRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_delete_file_version`, {
          method: 'POST',
          headers: { 
            Authorization: auth.authToken, 
            'Content-Type': 'application/json' 
          },
          body: JSON.stringify({ fileId: file.fileId, fileName: cleanPath }),
          signal: AbortSignal.timeout(10000)
        });
        if (delRes.ok) deletedCount++;
      } catch(e) {
        console.warn('[B2 delete] verzija fail:', e.message);
      }
    }
    
    if (deletedCount > 0 && deletedCount === versions.length) {
      return true;
    }
    if (deletedCount > 0) {
      console.warn(`[B2 delete] ${cleanPath}: obrisano ${deletedCount}/${versions.length} verzija`);
      return true;  // Bar nešto obrisano
    }
    return false;
  } catch (e) {
    console.warn('[B2 delete]', e.message);
    return false;
  }
}

// ⭐ v135.7.255: b2DeleteByPrefix — briše SVE fajlove čije ime počinje s prefix-om
//   (folder ekvivalent — B2 nema native rekurzivni delete, pa moramo iterirati).
//   Koristi se za:
//     - Brisanje nacrt foldera (PDF + N rasteriziranih PNG stranica)
//     - Brisanje cijelog Procelje-{i}-{oznaka} foldera ako su B2 paths spremljeni
//     - Brisanje cijelog gradilište foldera kad se obriše zadnja procjena
//   
//   Pagination: B2 vraća max 10 000 po listanju, ali za sigurnost koristim
//   maxFileCount=1000 + nextFileName loop (do 10 iteracija = 10K fajlova).
//   
//   Vraća: { ok: bool, deleted: int, errors: int }
async function b2DeleteByPrefix(prefix) {
  if (!prefix || typeof prefix !== 'string') return { ok: false, deleted: 0, errors: 0 };
  const auth = await b2Authorize();
  if (!auth) return { ok: false, deleted: 0, errors: 0 };
  
  // Anti-misuse: ne dozvoljavamo prazan / root prefix (slučajan poziv bi obrisao SVE)
  const cleanPrefix = prefix.replace(/^\//, '');
  if (!cleanPrefix || cleanPrefix.length < 5) {
    console.warn(`[B2 deleteByPrefix] odbijen prekratak prefix: "${cleanPrefix}"`);
    return { ok: false, deleted: 0, errors: 1 };
  }
  
  let deleted = 0, errors = 0;
  let nextFileName = null;
  const maxIterations = 10;  // Hard limit: 10 × 1000 = 10K fajlova max
  
  try {
    for (let iter = 0; iter < maxIterations; iter++) {
      const listBody = {
        bucketId: auth.bucketId,
        prefix: cleanPrefix,
        maxFileCount: 1000
      };
      if (nextFileName) listBody.startFileName = nextFileName;
      
      const listRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
        method: 'POST',
        headers: { 
          Authorization: auth.authToken, 
          'Content-Type': 'application/json' 
        },
        body: JSON.stringify(listBody),
        signal: AbortSignal.timeout(15000)
      });
      
      if (listRes.status === 401) {
        _b2InvalidateAuth();
        console.warn(`[B2 deleteByPrefix] auth expired za "${cleanPrefix}"`);
        return { ok: false, deleted, errors: errors + 1 };
      }
      if (!listRes.ok) {
        console.warn(`[B2 deleteByPrefix] list HTTP ${listRes.status} za "${cleanPrefix}"`);
        return { ok: false, deleted, errors: errors + 1 };
      }
      
      const listData = await listRes.json();
      const files = (listData.files || []).filter(f => f.fileName.startsWith(cleanPrefix));
      
      if (files.length === 0) break;
      
      // Briši paralelno (chunk po 10 da ne pretrpamo API)
      for (let i = 0; i < files.length; i += 10) {
        const chunk = files.slice(i, i + 10);
        await Promise.all(chunk.map(async (file) => {
          try {
            // Briši SVE verzije kroz b2Delete (uključuje historic versions)
            const ok = await b2Delete(file.fileName);
            if (ok) deleted++;
            else errors++;
          } catch (e) {
            errors++;
            console.warn(`[B2 deleteByPrefix] fail ${file.fileName}:`, e.message);
          }
        }));
      }
      
      // Pagination — ako ima više
      nextFileName = listData.nextFileName;
      if (!nextFileName) break;
    }
    
    console.log(`[B2 deleteByPrefix] "${cleanPrefix}": ${deleted} obrisano, ${errors} grešaka`);
    return { ok: errors === 0, deleted, errors };
  } catch (e) {
    console.error(`[B2 deleteByPrefix] "${cleanPrefix}":`, e.message);
    return { ok: false, deleted, errors: errors + 1 };
  }
}

// ════════════════════════════════════════════════════════════════════════════
// DUAL-WRITE WRAPPERS
//   Glavne funkcije za upload — paralelno na QNAP i B2.
//   Vraća objekt s oba path-a (može biti null ako jedan fail-a).
//   Ako oba fail-aju → throw (poziv mora handle-ati).
// ════════════════════════════════════════════════════════════════════════════

// Dual upload za slike (i ostale fajlove sličnog tipa).
// Vraća { qnap_path, b2_path } — barem jedan ne-null ili null oba (greška).
async function dualUploadImage(buffer, remotePath) {
  const [qnapPath, b2Path] = await Promise.allSettled([
    qnapUploadImage(buffer, remotePath),
    b2Enabled() ? b2Upload(buffer, remotePath, 'image/jpeg') : Promise.resolve(null)
  ]).then(results => results.map(r => r.status === 'fulfilled' ? r.value : null));
  
  if (!qnapPath && !b2Path) {
    console.error('[dual upload] OBA storage-a fail-ala za', remotePath);
    return { qnap_path: null, b2_path: null };
  }
  if (b2Enabled() && !b2Path) {
    console.warn('[dual upload] B2 fail za', remotePath, '— samo QNAP');
  }
  if (!qnapPath) {
    console.warn('[dual upload] QNAP fail za', remotePath, '— samo B2');
  }
  return { qnap_path: qnapPath, b2_path: b2Path };
}

// Dual upload za file (PDF, Excel, ZIP backup, ...) s explicit content type
async function dualUploadFile(buffer, remotePath, contentType = 'application/octet-stream') {
  const [qnapPath, b2Path] = await Promise.allSettled([
    qnapUploadFile(buffer, remotePath, contentType),
    b2Enabled() ? b2Upload(buffer, remotePath, contentType) : Promise.resolve(null)
  ]).then(results => results.map(r => r.status === 'fulfilled' ? r.value : null));
  
  if (!qnapPath && !b2Path) {
    console.error('[dual upload file] OBA fail-ala za', remotePath);
    return { qnap_path: null, b2_path: null };
  }
  return { qnap_path: qnapPath, b2_path: b2Path };
}

// ════════════════════════════════════════════════════════════════════════════
// ════════════════════════════════════════════════════════════════════════════
// READ-WITH-FALLBACK
//   ⭐ v135.7.213: QNAP je GLAVNI storage. B2 je SAMO fallback za 1% scenarij.
//   
//   Logika: 
//   1. Prvo pokušaj QNAP (15s timeout — dovoljno čak i za sporije konekcije)
//   2. Ako QNAP uspije → vraćamo, B2 se NE poziva (štedimo bandwidth)
//   3. Ako QNAP fail (timeout/non-OK/error) → fallback na B2
//   
//   PRIJE (v202-v212): paralelni race QNAP+B2, B2 hvatao previše zahtjeva
//   SAD: sequential — B2 se aktivira samo pri stvarnoj propasti QNAP-a
//   
//   Vraća Buffer ili null. Loguje koji storage je servirao.
// ════════════════════════════════════════════════════════════════════════════
async function fetchImageWithFallback(qnapPath, b2Path) {
  // ⭐ v135.7.220: QNAP CIRCUIT BREAKER — auto-skip ako je QNAP DOWN
  //   PROBLEM: ako QNAP ne radi (požar, network outage), svaki fetch čeka 15s
  //            timeout pa onda ide na B2 fallback → ekstremno spor UX (10 slika = 150s).
  //   RJEŠENJE: prati uzastopne fail-ove. Ako 5+ fail-ova u zadnjih 60s, uđi u
  //            "QNAP_DOWN" mode → preskoči QNAP, idi direktno na B2.
  //            Auto-resetira se kad QNAP opet odgovori (test svakih 30s).
  // ⭐ v502.20.8 (Ivan, 27.05.2026): QNAP timeout 15s → 5s
  // ⭐ v502.20.18 (Ivan, 27.05.2026): KRITIČAN BUG FIX — Reference portfolio export
  //   PROBLEM: stare slike (uploadane prije v502.20.9) imaju qnap_path ali nemaju 
  //   b2_path (B2 kolona dodana kasnije). Kad QNAP down + circuit OPEN, ove slike 
  //   pokušavaju QNAP fetch koji odmah pukne ali sporo (5s timeout svaki put × N slika).
  //   Korisnik vidi "Nema slika za izabrana gradilišta".
  //   FIX: kad je circuit OPEN i nema b2_path, vrati null ODMAH (brzi fail).
  //   Forward sync će popuniti b2_path kad QNAP opet bude online, pa će fallback raditi.
  const circuitOpen = _qnapCircuitOpen();
  
  // ⭐ v502.20.21 (Ivan, 27.05.2026): KRITIČAN FIX — circuit OPEN ne smije BLOCK-irati 
  //   QNAP retry. Prošli v502.20.19 fix je radio "return null" kad circuit open i B2 fail,
  //   što znači NIKAD nije ponovo testirao QNAP. Ivan kaže "QNAP je dostupan" — circuit 
  //   je samo stari state. Sada: dajemo QNAP-u priliku s kratkim 2s timeout-om.
  // ⭐ v502.20.22 (Ivan, 27.05.2026): retry timeout 2s → 5s, jer 2s je preagresivno za 
  //   spori WebDAV preko 5G mreže (mobile QNAP test može trebati 3-4s).
  if (circuitOpen && b2Path) {
    // Prvo brzi B2 pokušaj (postoji b2_path)
    const b2Buf = await b2FetchBuffer(b2Path, 5000);
    if (b2Buf) return b2Buf;
    // B2 fail — daj QNAP-u priliku s razumnim timeout-om (možda se vratio online)
    if (qnapPath) {
      console.log('[fetchImage] circuit OPEN, B2 fail, last-resort QNAP retry');
      const qBuf = await _qnapFastFetch(qnapPath, 5000);  // ⭐ v502.20.22: 2s → 5s
      _qnapCircuitRecord(!!qBuf);  // ako uspije, circuit se zatvori
      if (qBuf) return qBuf;
    }
    return null;
  }
  
  // ⭐ v502.20.21: ako je circuit OPEN i NEMA b2_path — daj QNAP retry s razumnim timeout-om
  // ⭐ v502.20.22: 2s → 5s (vidi gore razlog)
  if (circuitOpen && qnapPath && !b2Path) {
    const qBuf = await _qnapFastFetch(qnapPath, 5000);  // ⭐ v502.20.22: 2s → 5s
    _qnapCircuitRecord(!!qBuf);
    return qBuf;  // null ako fail, buf ako QNAP opet radi
  }
  
  // Slučaj 1: samo QNAP path (stari unosi prije B2)
  if (qnapPath && !b2Path) {
    const buf = await _qnapFastFetch(qnapPath, 5000);
    _qnapCircuitRecord(!!buf);
    return buf;
  }
  
  // Slučaj 2: samo B2 path (rijetko — npr. ako je QNAP path obrisan)
  if (!qnapPath && b2Path) {
    return await b2FetchBuffer(b2Path, 5000);
  }
  
  // Slučaj 3: nema path-a
  if (!qnapPath && !b2Path) {
    return null;
  }
  
  // Slučaj 4: oba path-a — QNAP GLAVNI, B2 fallback
  // ⭐ v502.20.8: 5s timeout (bilo 15s)
  const qnapBuf = await _qnapFastFetch(qnapPath, 5000);
  _qnapCircuitRecord(!!qnapBuf);
  if (qnapBuf) {
    return qnapBuf;  // QNAP radi → ne zovemo B2 uopće
  }
  
  // QNAP fail — sad fallback na B2 (rijetko, samo pri stvarnoj propasti)
  console.warn(`[fetchImage] QNAP fail za ${qnapPath} → B2 fallback`);
  const b2Buf = await b2FetchBuffer(b2Path, 5000);
  if (b2Buf) {
    console.log(`[fetchImage] servirano s B2 (QNAP nedostupan): ${b2Path}`);
    return b2Buf;
  }
  
  console.error(`[fetchImage] OBA fail-ala: QNAP=${qnapPath} B2=${b2Path}`);
  return null;
}

// ⭐ v135.7.220: QNAP circuit breaker state
//   Prati uzastopne fail-ove. Otvara circuit kad >= 5 fail-ova u zadnjih 60s.
//   Zatvara automatski nakon 30s (re-test) ili pri prvom uspjehu.
const _qnapCircuit = {
  failures: [],     // timestamp-ovi recent fail-ova
  openedAt: 0,      // kad je circuit otvoren
  // ⭐ v502.20.8 (Ivan, 27.05.2026): threshold 5 → 3, brže ulazi u DOWN mode
  //   Worst case prije: 5 × 15s = 75s. Sad: 3 × 5s = 15s.
  threshold: 3,     // fail count za otvaranje (bilo 5)
  windowMs: 60000,  // 60s prozor za brojanje
  // ⭐ v502.20.21 (Ivan, 27.05.2026): cooldown 30s → 10s
  //   Razlog: ako QNAP se vrati online unutar 30s, circuit ostane otvoren predugo.
  //   Korisnik vidi "Nema slika" iako QNAP radi. 10s je dovoljno za brzu detekciju 
  //   recovery-a (auto-test svakih 10s).
  cooldownMs: 10000 // 10s prije re-testa (bilo 30s)
};

function _qnapCircuitOpen() {
  if (!_qnapCircuit.openedAt) return false;
  // Auto-reset nakon cooldown
  if (Date.now() - _qnapCircuit.openedAt > _qnapCircuit.cooldownMs) {
    console.log('[qnap-circuit] cooldown gotov, re-testiram QNAP');
    _qnapCircuit.openedAt = 0;
    _qnapCircuit.failures = [];
    return false;
  }
  return true;
}

function _qnapCircuitRecord(success) {
  const now = Date.now();
  if (success) {
    // Uspjeh → zatvori circuit i obriši fail count
    if (_qnapCircuit.openedAt) {
      const downSeconds = Math.round((now - _qnapCircuit.openedAt) / 1000);
      const downMinutes = Math.round(downSeconds / 60);
      console.log(`[qnap-circuit] QNAP opet radi (bio DOWN ${downSeconds}s), zatvaram circuit`);
      
      // ⭐ v135.7.228: Notify direktora kad QNAP opet proradi (samo ako je bilo >2 min DOWN)
      //   Razlog: kratki blip-ovi (<2 min) su normalni, ne treba uznemiravati Ivana.
      //   Veći outage je vrijedan obavještavanja.
      if (downSeconds > 120) {
        _qnapNotifyRecovery(downMinutes);
      }
    }
    _qnapCircuit.openedAt = 0;
    _qnapCircuit.failures = [];
    return;
  }
  // Fail → dodaj timestamp, otvori circuit ako prelazi threshold
  _qnapCircuit.failures.push(now);
  // Cleanup stari (izvan prozora)
  _qnapCircuit.failures = _qnapCircuit.failures.filter(t => now - t < _qnapCircuit.windowMs);
  if (_qnapCircuit.failures.length >= _qnapCircuit.threshold && !_qnapCircuit.openedAt) {
    _qnapCircuit.openedAt = now;
    console.warn(`[qnap-circuit] OTVOREN! ${_qnapCircuit.failures.length} fail-ova u ${_qnapCircuit.windowMs/1000}s. Slijedećih ${_qnapCircuit.cooldownMs/1000}s preskačem QNAP, idem direktno B2.`);
    
    // ⭐ v135.7.228: Push notifikacija direktoru kad QNAP padne
    //   Razlog: prije se to vidjelo samo u Railway logovima, Ivan ne bi primjetio.
    //   Sada: instant push s informacijom da je QNAP DOWN, B2 fallback aktivan.
    //   Throttle: max 1 push svakih 30 min (da ne spam-a ako QNAP flap-a)
    // ⭐ v259 (Ivan): push TEK ako je circuit i dalje otvoren nakon 60s — myqnapcloud relay
    //   štucaji (3 faila/60s uz LAN-zdrav QNAP) su Ivanu slali lažne 'QNAP pao' alarme.
    setTimeout(() => { try { if (_qnapCircuit.openedAt) _qnapNotifyDown(); } catch (_) {} }, 60000);
  }
}

// ⭐ v502.20.27 (Ivan, 27.05.2026): QNAP storage scan - egzaktna veličina cijelog /APLIKACIJA foldera
//   PROBLEM: Godišnji izvještaj koristi DB estimate koji ne uključuje backup foldere, 
//   sistemske file-ove, _.DS_Store, thumb cache, itd. Ivan kaže direktno mjeri 1.27 GB 
//   iz Windows Explorer-a a aplikacija prikaže 598 MB.
//   RJEŠENJE: Rekurzivno PROPFIND scan svih foldera u /APLIKACIJA preko WebDAV-a.
//   Vraća: total bytes, per-folder breakdown, file count.
//   Performance: scan ~800 fajlova × ~50 ms = ~40 sekundi. Cache rezultat 1h u memoriji.
let _qnapStorageCache = null;  // { ts, result }
const QNAP_STORAGE_CACHE_TTL = 60 * 60 * 1000;  // 1h

async function _qnapPropfindFolder(folderPath, depth = '1') {
  if (!process.env.QNAP_WEBDAV_URL) return null;
  const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
  const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
  
  // Osiguraj da folderPath završava sa /
  const folder = folderPath.endsWith('/') ? folderPath : folderPath + '/';
  
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 30000);  // 30s timeout per folder
    
    const resp = await fetch(`${baseUrl}${folder}`, {
      method: 'PROPFIND',
      headers: {
        Authorization: `Basic ${auth64}`,
        Depth: depth,
        'Content-Type': 'application/xml'
      },
      body: '<?xml version="1.0"?><propfind xmlns="DAV:"><prop><getcontentlength/><resourcetype/><displayname/></prop></propfind>',
      signal: ctrl.signal
    });
    clearTimeout(t);
    
    if (!resp.ok && resp.status !== 207) {
      console.warn(`[qnap-scan] PROPFIND ${folder} → ${resp.status}`);
      return null;
    }
    
    const xml = await resp.text();
    
    // Parse XML: izvuci sve <response> blokove
    // <D:response>
    //   <D:href>/APLIKACIJA/Dnevnik/Pregrada/foto.jpg</D:href>
    //   <D:propstat><D:prop><D:getcontentlength>123456</D:getcontentlength>
    //   <D:resourcetype/> ili <D:resourcetype><D:collection/></D:resourcetype>
    //   </D:prop></D:propstat>
    // </D:response>
    const entries = [];
    const responseBlocks = xml.match(/<[a-zA-Z]*:?response[\s\S]*?<\/[a-zA-Z]*:?response>/gi) || [];
    
    for (const block of responseBlocks) {
      // href
      const hrefMatch = block.match(/<[a-zA-Z]*:?href[^>]*>([^<]*)<\/[a-zA-Z]*:?href>/i);
      if (!hrefMatch) continue;
      const href = decodeURIComponent(hrefMatch[1]);
      
      // resourcetype (folder ili file?)
      const isCollection = /<[a-zA-Z]*:?collection\s*\/>/i.test(block) || 
                          /<[a-zA-Z]*:?resourcetype[^>]*>[\s\S]*?<[a-zA-Z]*:?collection/i.test(block);
      
      // contentlength (samo za file-ove)
      const sizeMatch = block.match(/<[a-zA-Z]*:?getcontentlength[^>]*>(\d+)<\/[a-zA-Z]*:?getcontentlength>/i);
      const size = sizeMatch ? parseInt(sizeMatch[1]) : 0;
      
      entries.push({
        href,
        isFolder: isCollection,
        sizeBytes: size
      });
    }
    
    return entries;
  } catch(e) {
    console.warn(`[qnap-scan] PROPFIND ${folder} error:`, e.message);
    return null;
  }
}

/**
 * Rekurzivno skenira folder na QNAP-u i vraća ukupnu veličinu + per-folder breakdown.
 * @param {string} rootPath - Početni folder (npr "/APLIKACIJA")
 * @param {number} maxDepth - Maksimalna dubina rekurzije (default 6)
 * @returns {Promise<{totalBytes, totalFiles, byFolder: [{folder, sizeBytes, fileCount}], scanDurationMs}>}
 */
async function qnapStorageScan(rootPath, maxDepth = 6) {
  const t0 = Date.now();
  const startPath = rootPath.replace(/\/$/, '');
  
  const result = {
    totalBytes: 0,
    totalFiles: 0,
    byFolder: [],
    scanDurationMs: 0,
    errors: []
  };
  
  const folderStats = {};  // path → { bytes, count }
  
  // ⭐ v502.20.30 (Ivan, 28.05.2026): PARALELNI BFS — obrađuj foldere u batch-evima
  //   PROBLEM: prije je BFS bio sekvencijalan (jedan PROPFIND po iteraciji while petlje).
  //   Za ~60 foldera × ~500ms PROPFIND = ~30-60s scan.
  //   FIX: level-by-level BFS s concurrency limitom (5 PROPFIND-ova istovremeno).
  //   Folderi na istoj razini se skeniraju paralelno → ~10-15s umjesto 30-60s.
  const CONCURRENCY = 5;
  
  // Helper: obradi jedan folder, vrati listu subfoldera za sljedeću razinu
  const scanFolder = async (currentPath, depth) => {
    if (depth > maxDepth) {
      result.errors.push(`Max depth reached: ${currentPath}`);
      return [];
    }
    const entries = await _qnapPropfindFolder(currentPath, '1');
    if (!entries) {
      result.errors.push(`PROPFIND fail: ${currentPath}`);
      return [];
    }
    const subfolders = [];
    for (const entry of entries) {
      const normalizedHref = entry.href.replace(/\/$/, '');
      // Preskoči self-reference
      if (normalizedHref === currentPath) continue;
      if (entry.isFolder) {
        subfolders.push({ path: normalizedHref, depth: depth + 1 });
      } else {
        result.totalBytes += entry.sizeBytes;
        result.totalFiles++;
        if (!folderStats[currentPath]) {
          folderStats[currentPath] = { bytes: 0, count: 0 };
        }
        folderStats[currentPath].bytes += entry.sizeBytes;
        folderStats[currentPath].count++;
      }
    }
    return subfolders;
  };
  
  // Level-by-level BFS s concurrency limitom
  let currentLevel = [{ path: startPath, depth: 0 }];
  while (currentLevel.length > 0) {
    const nextLevel = [];
    // Obradi trenutnu razinu u batch-evima od CONCURRENCY
    for (let i = 0; i < currentLevel.length; i += CONCURRENCY) {
      const batch = currentLevel.slice(i, i + CONCURRENCY);
      const batchResults = await Promise.all(
        batch.map(({ path, depth }) => scanFolder(path, depth))
      );
      for (const subs of batchResults) nextLevel.push(...subs);
    }
    currentLevel = nextLevel;
  }
  
  // Pretvori folderStats u sortirani array
  // Grupiraj po top-level folderima (npr /APLIKACIJA/Dnevnik agregira sve subfoldere)
  const topLevelStats = {};
  for (const [folderPath, stats] of Object.entries(folderStats)) {
    // Izvuci top-level naziv (prvi segment nakon /APLIKACIJA/)
    const relative = folderPath.replace(startPath + '/', '');
    const topLevel = relative.split('/')[0] || '(root)';
    
    if (!topLevelStats[topLevel]) {
      topLevelStats[topLevel] = { bytes: 0, count: 0, subfolders: 0 };
    }
    topLevelStats[topLevel].bytes += stats.bytes;
    topLevelStats[topLevel].count += stats.count;
    topLevelStats[topLevel].subfolders++;
  }
  
  result.byFolder = Object.entries(topLevelStats)
    .map(([folder, s]) => ({
      folder,
      sizeBytes: s.bytes,
      sizeMb: s.bytes / 1024 / 1024,
      fileCount: s.count,
      subfolderCount: s.subfolders
    }))
    .sort((a, b) => b.sizeBytes - a.sizeBytes);
  
  result.scanDurationMs = Date.now() - t0;
  result.totalMb = result.totalBytes / 1024 / 1024;
  result.totalGb = result.totalBytes / 1024 / 1024 / 1024;
  
  return result;
}


// ⭐ v135.7.502.20.253 (Ivan, 11.06.2026): Sentry ReferenceError — _qnapDownPushSentAt korišten bez
//   deklaracije (rušio je _qnapFetchSlikaAsDataUrl → GET procelje-slika 500). Throttle init na 0.
let _qnapDownPushSentAt = 0;

async function _qnapNotifyDown() {
  const now = Date.now();
  if (now - _qnapDownPushSentAt < 30 * 60 * 1000) {
    return;  // Već poslano u zadnjih 30 min
  }
  _qnapDownPushSentAt = now;
  
  try {
    // Pronađi direktora
    const dirR = await pool.query(
      "SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1"
    );
    if (!dirR.rows.length) return;
    
    const dirId = dirR.rows[0].id;
    if (typeof sendPushToUser !== 'function') return;
    
    await sendPushToUser(
      dirId,
      '⚠ QNAP nedostupan',
      `Circuit breaker otvoren. Aplikacija prebačena na B2 fallback. Provjeri QNAP.`,
      '/?tab=menu'
    ).catch(e => console.warn('[qnap-circuit notify down]', e.message));
    
    console.log(`[qnap-circuit] push direktoru poslan: QNAP DOWN`);
  } catch(e) {
    console.warn('[qnap-circuit notify down] error:', e.message);
  }
}

async function _qnapNotifyRecovery(downMinutes) {
  try {
    const dirR = await pool.query(
      "SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1"
    );
    if (!dirR.rows.length) return;
    
    const dirId = dirR.rows[0].id;
    if (typeof sendPushToUser !== 'function') return;
    
    // Brojanje pending B2→QNAP sinka
    let pendingTotal = 0;
    try {
      const stats = await pool.query(`
        SELECT 
          (SELECT COUNT(*) FROM materijal WHERE b2_path IS NOT NULL AND qnap_path IS NULL) +
          (SELECT COUNT(*) FROM dnevnik WHERE b2_path IS NOT NULL AND qnap_path IS NULL) +
          (SELECT COUNT(*) FROM uredaji WHERE b2_path IS NOT NULL AND qnap_path IS NULL) +
          (SELECT COUNT(*) FROM izmjera WHERE b2_path IS NOT NULL AND qnap_path IS NULL) +
          (SELECT COUNT(*) FROM smece WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS total
      `);
      pendingTotal = parseInt(stats.rows[0]?.total || 0);
    } catch(_) {}
    
    const pendingMsg = pendingTotal > 0 
      ? ` ${pendingTotal} slika čeka B2→QNAP sync (cron auto pokreće).`
      : '';
    
    await sendPushToUser(
      dirId,
      '✅ QNAP opet radi',
      `QNAP bio DOWN ~${downMinutes} min. Sustav nastavio normalno.${pendingMsg}`,
      '/?tab=menu'
    ).catch(e => console.warn('[qnap-circuit notify recovery]', e.message));
    
    console.log(`[qnap-circuit] push direktoru poslan: QNAP RECOVERED (down ${downMinutes}min)`);
    
    // ⭐ v135.7.228: Auto-pokreni B2→QNAP sync jer je QNAP nazad
    if (pendingTotal > 0 && global._b2ReverseSyncBatch) {
      console.log('[qnap-circuit] auto-pokrećem B2→QNAP sync (pending: ' + pendingTotal + ')');
      global._b2ReverseSyncBatch().catch(e => console.warn('[auto sync]', e.message));
    }
  } catch(e) {
    console.warn('[qnap-circuit notify recovery] error:', e.message);
  }
}

// Brzi QNAP fetch s timeoutom — interno za fetchImageWithFallback
async function _qnapFastFetch(qnapPath, timeoutMs) {
  if (!qnapPath || !process.env.QNAP_WEBDAV_URL) return null;
  try {
    const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
    const base = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
    const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
    const cleanPath = qnapPath.replace(/^\//, '');
    const encodedPath = cleanPath.split('/').filter(Boolean).map(encodeURIComponent).join('/');
    const fullUrl = `${baseUrl}${base}/${encodedPath}`;
    const r = await fetch(fullUrl, { 
      headers: { Authorization: `Basic ${auth64}` },
      signal: AbortSignal.timeout(timeoutMs)
    });
    if (r.ok) {
      const ab = await r.arrayBuffer();
      return Buffer.from(ab);
    }
    return null;
  } catch(e) {
    return null;  // log se radi vani u fetchImageWithFallback
  }
}

