// ── ANALITIKA — trošak radnika po mjesecu ────────────────────────────────────
// ⭐ v135.7.161: Sati-only analitika za poslovođu (Memsur)
//   Razlog: Memsur može vidjeti aktivne radnike + sati po mjesecu, ali ne i 
//   financijske podatke (satnica, bonus, plaća, trošak). Ovo je za KPI dashboard
//   widget bez 4. KPI-a "Trošak rada".

// ⭐ v135.7.194: Sati po gradilištu UKUPNO (bez datum filtera)
//   Razlog: na Analitika tabu "Sati po gradilištu" je ranije računao iz 30-dnevnog
//   /sihterica fetch-a što je pokazivalo samo zadnji mjesec, a Ivan očekuje cijela
//   povijest (Samobor 5517h itd.). Ovaj endpoint vraća agregirane sume po gradilištu
//   bez učitavanja svih ~50000 redaka u browser.
//   
//   Performance: SUM agregacija na PG strani je < 50ms i za 100k redaka. 
//   Uključuje samo bolovanje=false (kao i sati-summary) za točan broj radnih sati.
app.get('/api/analitika/sati-grad-ukupno', auth, staff, async (req, res) => {
  try {
    // ⭐ v501.16 (Ivan, 21.05.2026): SAMO AKTIVNA gradilišta — sažeti pregled za Analitika tab.
    //   Arhivirana gradilišta su gotova; njihovi sati su u Arhiva tabu.
    const result = await pool.query(`
      SELECT
        s.gradiliste_id                    AS gradiliste_id,
        g.naziv                            AS naziv,
        SUM(s.sati_redovni)                AS sati
      FROM sihterica s
      JOIN gradilista g ON g.id = s.gradiliste_id
      WHERE COALESCE(s.bolovanje, false) = false
        AND g.aktivan = true
      GROUP BY s.gradiliste_id, g.naziv
      ORDER BY sati DESC NULLS LAST
    `);
    res.json(result.rows.map(r => ({
      gradiliste_id: r.gradiliste_id,
      naziv: r.naziv || '—',
      sati: parseFloat(r.sati || 0)
    })));
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/analitika/sati-summary', auth, staff, async (req, res) => {
  try {
    const godina = validateGodina(req.query.godina);
    const result = await pool.query(`
      SELECT
        EXTRACT(YEAR  FROM s.datum)::int AS god,
        EXTRACT(MONTH FROM s.datum)::int AS mj,
        r.id                             AS radnik_id,
        r.ime || ' ' || r.prezime        AS radnik,
        SUM(s.sati_redovni)              AS sati
      FROM sihterica s
      JOIN radnici r ON r.id = s.radnik_id AND r.role != 'direktor'
      WHERE EXTRACT(YEAR FROM s.datum)::int = $1
        AND COALESCE(s.bolovanje, false) = false
      GROUP BY god, mj, r.id, r.ime, r.prezime
      ORDER BY god, mj, r.ime
    `, [godina]);
    
    // Group po god+mj
    const byMj = {};
    result.rows.forEach(row => {
      const key = `${row.god}_${row.mj}`;
      if (!byMj[key]) byMj[key] = { godina: row.god, mjesec: row.mj, radnici: [] };
      byMj[key].radnici.push({
        radnik_id: row.radnik_id,
        radnik: row.radnik,
        sati: parseFloat(row.sati || 0)
      });
    });
    // DESC sort (najnoviji prvi) + max 12 mj
    const arr = Object.values(byMj)
      .sort((a, b) => (b.godina*100+b.mjesec) - (a.godina*100+a.mjesec))
      .slice(0, 12);
    res.json(arr);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/analitika/trosak', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.99: validacija godine
    let godina = parseInt(req.query.godina);
    if (!Number.isFinite(godina) || godina < 2020 || godina > 2100) {
      godina = new Date().getFullYear();
    }
    // ⭐ v501.62 (Ivan): koristi calcMjesecniTrosakRada (single source) za netto + doprinosi
    //   NETTO = ono što firma stvarno isplaćuje (gotovina + račun + bonus + naknada + terenska + godišnji)
    //   DOPRINOSI = sati × bruto_dod (5.50 €/h)
    //   BRUTTO = NETTO + DOPRINOSI = ukupni trošak firme
    const { redovi, bruto_dod } = await calcMjesecniTrosakRada({ godina });

    const byMjesec = {};
    for (const r of redovi) {
      const key = r.god + '-' + String(r.mj).padStart(2,'0');
      if (!byMjesec[key]) byMjesec[key] = { 
        godina: r.god, mjesec: r.mj, 
        radnici: [], 
        ukupno: 0,           // alias za backward compat — = brutto
        ukupno_netto: 0,     // NETTO trošak (bez doprinosa)
        ukupno_doprinosi: 0, // doprinosi (sati × bruto_dod) — ⭐ v501.95: samo radni sati
        ukupno_brutto: 0,    // NETTO + DOPRINOSI = stvarni mjesečni trošak firme
        ukupno_sati: 0,
        ukupno_bonus: 0,
        ukupno_bolovanje: 0,
        ukupno_godisnji: 0   // ⭐ v501.95: isplaćeni godišnji (odvojeno prikazano u UI)
      };

      byMjesec[key].radnici.push({
        radnik: r.radnik,
        sati: r.sati_ukupno,
        satnica: r.satnica,
        bruto: r.sati_ukupno * r.satnica + r.bonus + r.naknada_bol + r.godisnji,  // za backward compat
        bonus: r.bonus,
        naknada_bolovanje: r.naknada_bol,
        godisnji: r.godisnji,
        terenska: r.terenska,
        placa_racun: r.placa_racun,
        isplata: r.isplata_gotovina,
        // Novi field-i (v501.62)
        netto_trosak: r.netto_trosak,
        doprinosi: r.doprinosi,
        brutto_trosak: r.brutto_trosak,
        trosak: r.brutto_trosak    // alias backward compat
      });

      byMjesec[key].ukupno_sati += r.sati_ukupno;
      byMjesec[key].ukupno_netto += r.netto_trosak;
      byMjesec[key].ukupno_doprinosi += r.doprinosi;
      byMjesec[key].ukupno_brutto += r.brutto_trosak;
      byMjesec[key].ukupno_bonus += r.bonus;
      byMjesec[key].ukupno_bolovanje += r.naknada_bol;
      byMjesec[key].ukupno_godisnji += r.godisnji;  // ⭐ v501.95
      byMjesec[key].ukupno += r.brutto_trosak;  // backward compat alias
    }

    // ⭐ v501.70 (Ivan, 23.05.2026): Filtriraj prazne mjesece prije slanja klijentu.
    //   PROBLEM: UNION (sihterica + place_parametri) u calcMjesecniTrosakRada vraćao je
    //   i mjesece za koje postoji samo place_parametri zapis (npr. satnice unaprijed
    //   unesene za buduće mjesece). Tab Analitika je prikazivao Lip/Srp 2026 sa 
    //   "18 radnika · 0h" iako ti mjeseci još nisu prošli i nemaju nikakvih troškova.
    //   FIX: mjesec se prikazuje samo ako ima stvaran trošak (sati > 0, brutto > 0,
    //   ili neka isplata bonus/bolovanje). Single source helper ostaje netaknut —
    //   filtar je samo na nivou ovog endpointa za prezentaciju.
    const mjeseci = Object.values(byMjesec).filter(m =>
      m.ukupno_sati > 0 || m.ukupno_brutto > 0 || m.ukupno_bonus > 0 || m.ukupno_bolovanje > 0
    );

    res.json(mjeseci.sort((a,b) =>
      b.godina !== a.godina ? b.godina - a.godina : b.mjesec - a.mjesec
    ));
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v501.65 (Ivan): AUDIT endpoint — godišnji netto trošak po formuli iz tab Plaće
//   Vraća: ukupni netto trošak (suma bruto svakog radnika kroz 12 mjeseci)
//          + breakdown per radnik za audit ako se brojevi razlikuju
//   Use: GET /api/analitika/godisnji-audit?godina=2026
app.get('/api/analitika/godisnji-audit', auth, direktor, async (req, res) => {
  try {
    const godina = validateGodina(req.query.godina);
    const { redovi, bruto_dod } = await calcMjesecniTrosakRada({ godina });
    
    // Suma per radnik (kroz svih 12 mjeseci)
    const perRadnik = new Map();
    let ukupni_netto = 0, ukupni_doprinosi = 0, ukupni_sati = 0;
    
    for (const r of redovi) {
      if (!perRadnik.has(r.radnik_id)) {
        perRadnik.set(r.radnik_id, { 
          radnik_id: r.radnik_id, radnik: r.radnik,
          sati: 0, netto: 0, doprinosi: 0, brutto: 0,
          mjeseci: 0
        });
      }
      const pr = perRadnik.get(r.radnik_id);
      pr.sati += r.sati_ukupno;
      pr.netto += r.netto_trosak;
      pr.doprinosi += r.doprinosi;
      pr.brutto += r.brutto_trosak;
      pr.mjeseci++;
      
      ukupni_netto += r.netto_trosak;
      ukupni_doprinosi += r.doprinosi;
      ukupni_sati += r.sati_ukupno;
    }
    
    const perRadnikArr = Array.from(perRadnik.values())
      .sort((a, b) => b.netto - a.netto)
      .map(r => ({
        ...r,
        sati: Math.round(r.sati * 10) / 10,
        netto: Math.round(r.netto * 100) / 100,
        doprinosi: Math.round(r.doprinosi * 100) / 100,
        brutto: Math.round(r.brutto * 100) / 100
      }));
    
    res.json({
      godina,
      bruto_dod_used: bruto_dod,
      formula_netto: 'sati × satnica + bonus + naknada_bolovanje + isplata_prosli_mj + godisnji',
      formula_brutto: 'netto + sati × bruto_dod',
      ukupno: {
        sati: Math.round(ukupni_sati * 10) / 10,
        netto: Math.round(ukupni_netto * 100) / 100,
        doprinosi: Math.round(ukupni_doprinosi * 100) / 100,
        brutto: Math.round((ukupni_netto + ukupni_doprinosi) * 100) / 100,
        broj_radnika: perRadnik.size
      },
      per_radnik: perRadnikArr
    });
  } catch(e) {
    console.error('godisnji-audit:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.72 (Ivan, 23.05.2026): POBOLJŠANI DEBUG endpoint — per-radnik dijagnostika
//   Use: GET /api/analitika/debug-sati?godina=2026
//   v501.71 je hvatao samo orphan (gradiliste_id NULL ili obrisano). v501.72 dodaje:
//     1. Per-radnik tablica: sati iz mjesečnog helpera vs sati iz alocirajTrosak
//        → pokazuje POJEDINAČNE razlike, ne samo total
//     2. Razlozi razlike: gradilište_NULL, obrisano_gradilište, direktor_role, 
//        obrisan_radnik, samo_bolovanje (radnik je samo bolovao taj mjesec)
//     3. Top 20 problematičnih (radnik, mjesec) trojica s razlikom > 0
//   Cilj: Ivan vidi TKO i KOLIKO sati se gubi u alokaciji, čak i ako nije orphan.
app.get('/api/analitika/debug-sati', auth, direktor, async (req, res) => {
  try {
    const godina = validateGodina(req.query.godina);
    
    // ─── 1. Mjesečni total (referenca, single source) ───
    const { redovi, bruto_dod } = await calcMjesecniTrosakRada({ godina });
    let mjes_sati = 0, mjes_netto = 0, mjes_doprinosi = 0, mjes_brutto = 0;
    const mjesPerRadnikMj = new Map();  // "radnik_id_god_mj" → r
    for (const r of redovi) {
      mjes_sati += r.sati_ukupno;
      mjes_netto += r.netto_trosak;
      mjes_doprinosi += r.doprinosi;
      mjes_brutto += r.brutto_trosak;
      mjesPerRadnikMj.set(`${r.radnik_id}_${r.god}_${r.mj}`, r);
    }
    
    // ─── 2. Alocirano po gradilištu ───
    const od = `${godina}-01-01`, doD = `${godina}-12-31`;
    const { byGrad } = await alocirajTrosakPoGradilistima({ datum_od: od, datum_do: doD });
    let aloc_sati = 0, aloc_netto = 0, aloc_doprinosi = 0, aloc_brutto = 0;
    const perGrad = [];
    // Sumiraj per (radnik, god, mj) kroz sva gradilišta — da uporedimo s mjesečnim
    const alocPerRadnikMj = new Map();  // "radnik_id_god_mj" → { sati, netto, ... }
    for (const g of byGrad.values()) {
      aloc_sati += g.ukupno_sati;
      aloc_netto += g.ukupno_netto;
      aloc_doprinosi += g.ukupno_doprinosi;
      aloc_brutto += g.ukupno_brutto;
      perGrad.push({
        grad_id: g.grad_id,
        naziv: g.naziv,
        sati: Math.round(g.ukupno_sati * 10) / 10,
        netto: Math.round(g.ukupno_netto * 100) / 100,
        doprinosi: Math.round(g.ukupno_doprinosi * 100) / 100,
        brutto: Math.round(g.ukupno_brutto * 100) / 100,
        broj_radnika: Object.keys(g.radnici).length
      });
    }
    perGrad.sort((a, b) => b.sati - a.sati);
    
    // ─── 3. ⭐ NOVO v501.72: Per-radnik usporedba (mjesečni vs alocirano) ───
    //   Direktan SQL koji simulira alocirajTrosak agregaciju po radniku + mjesecu
    const alocSqlQ = await pool.query(`
      SELECT
        r.id AS radnik_id,
        r.ime || ' ' || r.prezime AS radnik,
        EXTRACT(YEAR FROM s.datum)::int AS god,
        EXTRACT(MONTH FROM s.datum)::int AS mj,
        SUM(s.sati_redovni) AS sati
      FROM sihterica s
      JOIN radnici r ON r.id = s.radnik_id
      WHERE r.role != 'direktor'
        AND COALESCE(s.bolovanje, false) = false
        AND EXTRACT(YEAR FROM s.datum)::int = $1
      GROUP BY r.id, r.ime, r.prezime, god, mj
    `, [godina]);
    
    for (const r of alocSqlQ.rows) {
      alocPerRadnikMj.set(`${r.radnik_id}_${r.god}_${r.mj}`, {
        radnik: r.radnik,
        sati: parseFloat(r.sati) || 0
      });
    }
    
    // ─── 4. Razlika per (radnik, god, mj) ───
    const problemi = [];
    for (const [key, mjes] of mjesPerRadnikMj.entries()) {
      const aloc = alocPerRadnikMj.get(key);
      const aloc_sati = aloc ? aloc.sati : 0;
      const razlika = (mjes.sati_ukupno || 0) - aloc_sati;
      if (Math.abs(razlika) > 0.05) {
        problemi.push({
          radnik_id: mjes.radnik_id,
          radnik: mjes.radnik,
          god: mjes.god,
          mj: mjes.mj,
          mjes_sati: Math.round((mjes.sati_ukupno || 0) * 10) / 10,
          aloc_sati: Math.round(aloc_sati * 10) / 10,
          razlika_sati: Math.round(razlika * 10) / 10,
          razlika_doprinosi: Math.round(razlika * bruto_dod * 100) / 100,
          satnica: mjes.satnica
        });
      }
    }
    // Postoji li radnik koji je u alocSql ali NIJE u mjesečnom?
    for (const [key, aloc] of alocPerRadnikMj.entries()) {
      if (!mjesPerRadnikMj.has(key)) {
        const [radnik_id, god, mj] = key.split('_');
        problemi.push({
          radnik_id: parseInt(radnik_id),
          radnik: aloc.radnik,
          god: parseInt(god),
          mj: parseInt(mj),
          mjes_sati: 0,
          aloc_sati: Math.round(aloc.sati * 10) / 10,
          razlika_sati: -Math.round(aloc.sati * 10) / 10,
          razlika_doprinosi: -Math.round(aloc.sati * bruto_dod * 100) / 100,
          napomena: 'U alocirajTrosak ali ne u mjesečnom (čudno — provjeri UNION filter)'
        });
      }
    }
    problemi.sort((a, b) => Math.abs(b.razlika_sati) - Math.abs(a.razlika_sati));
    
    // ─── 5. Orphan zapisi (sihterica bez validnog gradilišta) ───
    const orphanQ = await pool.query(`
      SELECT s.id, s.datum, s.gradiliste_id, s.sati_redovni, 
             s.bolovanje, r.ime || ' ' || r.prezime AS radnik, r.id AS radnik_id
      FROM sihterica s
      LEFT JOIN gradilista g ON g.id = s.gradiliste_id
      JOIN radnici r ON r.id = s.radnik_id
      WHERE g.id IS NULL
        AND NOT (COALESCE(s.bolovanje,false) OR COALESCE(s.godisnji,false) OR COALESCE(s.ne_radi,false))   -- ⭐ v903: odsutni bez gradilišta nisu problem
        AND EXTRACT(YEAR FROM s.datum)::int = $1
        AND r.role != 'direktor'
        AND COALESCE(s.bolovanje, false) = false
      ORDER BY s.datum DESC, r.prezime
      LIMIT 100
    `, [godina]);
    
    // ─── 6. ⭐ NOVO v501.72: Razlozi gdje se gube sati ───
    //   Direktan breakdown SUM(sihterica) po kategorijama:
    //   - OK: r.role != direktor, bolovanje = false, gradiliste_id postoji
    //   - DIREKTOR: r.role = direktor, bolovanje = false (preskačemo)
    //   - BOLOVANJE: bolovanje = true (preskačemo doprinose)
    //   - GRADILISTE_NULL: gradiliste_id NULL ali radnik OK
    //   - OBRISANO_GRADILISTE: gradiliste_id pokazuje na nepostojeće gradilište
    //   - OBRISAN_RADNIK: radnik.obrisan = true
    const razloziQ = await pool.query(`
      WITH sih_year AS (
        SELECT s.id, s.datum, s.radnik_id, s.gradiliste_id, s.sati_redovni, s.bolovanje
        FROM sihterica s
        WHERE EXTRACT(YEAR FROM s.datum)::int = $1
      ),
      classified AS (
        SELECT 
          s.*,
          r.role AS radnik_role,
          COALESCE(r.obrisan, false) AS radnik_obrisan,
          r.id AS radnik_id_chk,
          g.id AS gradiliste_id_chk,
          CASE 
            WHEN r.id IS NULL THEN 'NEMA_RADNIKA (orphan FK)'
            WHEN COALESCE(r.obrisan, false) = true THEN 'OBRISAN_RADNIK'
            WHEN r.role = 'direktor' THEN 'DIREKTOR (preskoceno)'
            WHEN COALESCE(s.bolovanje, false) = true THEN 'BOLOVANJE (u doprinose, ne u alokaciju)'
            WHEN s.gradiliste_id IS NULL THEN 'GRADILISTE_NULL'
            WHEN g.id IS NULL THEN 'GRADILISTE_OBRISANO'
            ELSE 'OK (ulazi u alociranje)'
          END AS razlog
        FROM sih_year s
        LEFT JOIN radnici r ON r.id = s.radnik_id
        LEFT JOIN gradilista g ON g.id = s.gradiliste_id
      )
      SELECT razlog, COUNT(*)::int AS zapisa, 
             COALESCE(SUM(sati_redovni), 0)::float AS sati,
             -- ⭐ v501.77: doprinosi uračunavaju i bolovanje (dani × 8h × bruto_dod)
             ROUND((
               COALESCE(SUM(sati_redovni), 0) * $2 +
               CASE WHEN razlog LIKE 'BOLOVANJE%' 
                    THEN COUNT(*) * 8 * $2 
                    ELSE 0 END
             )::numeric, 2)::float AS doprinosi_eur
      FROM classified
      GROUP BY razlog
      ORDER BY sati DESC
    `, [godina, bruto_dod]);
    
    res.json({
      godina,
      bruto_dod_used: bruto_dod,
      mjesecni_total: {
        sati: Math.round(mjes_sati * 10) / 10,
        netto: Math.round(mjes_netto * 100) / 100,
        doprinosi: Math.round(mjes_doprinosi * 100) / 100,
        brutto: Math.round(mjes_brutto * 100) / 100
      },
      alocirano_total: {
        sati: Math.round(aloc_sati * 10) / 10,
        netto: Math.round(aloc_netto * 100) / 100,
        doprinosi: Math.round(aloc_doprinosi * 100) / 100,
        brutto: Math.round(aloc_brutto * 100) / 100
      },
      razlika: {
        sati: Math.round((mjes_sati - aloc_sati) * 10) / 10,
        netto: Math.round((mjes_netto - aloc_netto) * 100) / 100,
        doprinosi: Math.round((mjes_doprinosi - aloc_doprinosi) * 100) / 100,
        brutto: Math.round((mjes_brutto - aloc_brutto) * 100) / 100,
        komentar: Math.abs(mjes_sati - aloc_sati) < 0.1 
          ? 'OK — brojevi se poklapaju' 
          : 'RAZLIKA — provjeri razlozi[] i problemi[] niže'
      },
      // ⭐ NOVO v501.72
      razlozi: razloziQ.rows,
      problemi_top20: problemi.slice(0, 20),
      problemi_count: problemi.length,
      orphan_zapisi: orphanQ.rows,
      orphan_count: orphanQ.rowCount,
      per_grad: perGrad
    });
  } catch(e) {
    console.error('debug-sati v501.72:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.72 (Ivan, 23.05.2026): ORPHAN ZAPISI endpoint za Šihterica banner
//   Use: GET /api/sihterica/orphan-zapisi?godina=2026
//   Vraća: { count, zapisi: [...], po_mjesecima: { '2026-05': N, ... } }
//   Cilj: Šihterica tab pokazuje banner ako postoje orphan zapisi (sihterica bez gradilišta).
//         Klikom Ivan može direktno doći do popravka u Šihterici.
app.get('/api/sihterica/orphan-zapisi', auth, direktor, async (req, res) => {
  try {
    const godina = validateGodina(req.query.godina);
    
    // Sva sihterica gdje gradiliste_id pokazuje na nepostojeće gradilište ili je NULL
    const q = await pool.query(`
      SELECT 
        s.id, 
        s.datum, 
        s.radnik_id, 
        s.gradiliste_id, 
        s.sati_redovni::float AS sati,
        s.bolovanje,
        r.ime, r.prezime,
        r.ime || ' ' || r.prezime AS radnik,
        CASE 
          WHEN s.gradiliste_id IS NULL THEN 'gradiliste_id NULL'
          ELSE 'gradilište ne postoji (id=' || s.gradiliste_id || ')'
        END AS razlog
      FROM sihterica s
      LEFT JOIN gradilista g ON g.id = s.gradiliste_id
      JOIN radnici r ON r.id = s.radnik_id
      WHERE g.id IS NULL
        AND NOT (COALESCE(s.bolovanje,false) OR COALESCE(s.godisnji,false) OR COALESCE(s.ne_radi,false))   -- ⭐ v502.20.60 · v903: bolovanje, godišnji i ne-radi su LEGITIMNI bez gradilišta, nisu orphan
        AND EXTRACT(YEAR FROM s.datum)::int = $1
        AND r.role != 'direktor'
      ORDER BY s.datum DESC, r.prezime
    `, [godina]);
    
    // Sumirano per mjesec
    const poMjesecima = {};
    let ukupnoSati = 0;
    for (const r of q.rows) {
      const d = r.datum instanceof Date ? r.datum : new Date(r.datum);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      if (!poMjesecima[key]) poMjesecima[key] = { zapisa: 0, sati: 0 };
      poMjesecima[key].zapisa++;
      poMjesecima[key].sati += parseFloat(r.sati) || 0;
      ukupnoSati += parseFloat(r.sati) || 0;
    }
    
    res.json({
      godina,
      count: q.rowCount,
      ukupno_sati: Math.round(ukupnoSati * 10) / 10,
      zapisi: q.rows.map(r => ({
        id: r.id,
        datum: r.datum instanceof Date ? _ymd(r.datum) : String(r.datum).slice(0,10),
        radnik_id: r.radnik_id,
        radnik: r.radnik,
        ime: r.ime,
        prezime: r.prezime,
        sati: parseFloat(r.sati) || 0,
        bolovanje: !!r.bolovanje,
        gradiliste_id: r.gradiliste_id,
        razlog: r.razlog
      })),
      po_mjesecima: poMjesecima
    });
  } catch(e) {
    console.error('sihterica/orphan-zapisi:', e.message);
    res.status(500).json({ error: e.message });
  }
});

