// ⭐ v135.7.502.20.403 (Ivan): COMPLIANCE CENTAR — status dokumenata SVIH aktivnih radnika
//   (dozvola / liječnički / putovnica) + dana_do + sažetak po hitnosti. DIREKTOR (HR-osjetljivo kao OIB).
app.get('/api/pregled/compliance', auth, direktor, async (req, res) => {
  try {
    const q = await pool.query(`
      SELECT id, ime, prezime, dozvola_vrijedi_do, lijecnicki_vrijedi_do, putovnica_vrijedi_do
      FROM radnici
      WHERE COALESCE(aktivan, true) = true AND COALESCE(obrisan, false) = false
      ORDER BY prezime, ime
    `);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const danaDo = (d) => { if (!d) return null; const x = new Date(d); x.setHours(0, 0, 0, 0); return Math.round((x - today) / 86400000); };
    let istekli = 0, uskoro = 0, upozorenje = 0, ok = 0, bez = 0;
    const radnici = q.rows.map(r => {
      const docs = {
        dozvola:    { datum: r.dozvola_vrijedi_do,    dana_do: danaDo(r.dozvola_vrijedi_do) },
        lijecnicki: { datum: r.lijecnicki_vrijedi_do, dana_do: danaDo(r.lijecnicki_vrijedi_do) },
        putovnica:  { datum: r.putovnica_vrijedi_do,  dana_do: danaDo(r.putovnica_vrijedi_do) }
      };
      let worst = null;
      for (const k of ['dozvola', 'lijecnicki', 'putovnica']) { const dd = docs[k].dana_do; if (dd != null && (worst == null || dd < worst)) worst = dd; }
      let status = 'bez';
      if (worst != null) { if (worst < 0) status = 'istekao'; else if (worst <= 30) status = 'uskoro'; else if (worst <= 60) status = 'upozorenje'; else status = 'ok'; }
      if (status === 'istekao') istekli++; else if (status === 'uskoro') uskoro++; else if (status === 'upozorenje') upozorenje++; else if (status === 'ok') ok++; else bez++;
      return { id: r.id, ime: r.ime, prezime: r.prezime, docs, worst, status };
    }).sort((a, b) => { const av = a.worst == null ? 999999 : a.worst, bv = b.worst == null ? 999999 : b.worst; return av - bv; });
    res.json({ radnici, summary: { istekli, uskoro, upozorenje, ok, bez, ukupno: q.rows.length } });
  } catch (e) {
    console.error('GET /pregled/compliance:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.502.20.405 (Ivan): DEEP SEARCH — globalna pretraga cijele aplikacije.
//   ⭐ v135.7.502.20.406 (Ivan): NIJE više direktor-only — POŠTUJE OVLASTI svakog korisnika (isti
//   princip kao AI asistent). Svaka kategorija se uključuje SAMO ako korisnik ima tu ovlast u tabu Korisnici:
//     • gradilišta (aktivna+arhivirana) ……… ovlast 'gradilista'
//     • radnici (aktivni+bivši/obrisani) …… ovlast 'radnici'
//     • dnevnik (opis unosa) ……………………… ovlast 'dnevnik'
//     • nalozi (komentar) ………………………… ovlast 'nalozi'
//     • dopisi (asistent_dopisi) …………………… ovlast 'asistent' (ne-direktor vidi SAMO SVOJE; direktor sve)
//     • dokumenti radnika (ugovori) ……………… ovlast 'radnici'
//   Direktor ima sve. Dijakritik-NEosjetljivo (translate-fold). Svaka grupa cap 8.
app.get('/api/search', auth, async (req, res) => {
  try {
    const raw = (req.query.q || '').toString().trim();
    const empty = { q: raw, gradilista: [], radnici: [], dnevnik: [], nalozi: [], dopisi: [], dokumenti: [], cjenik: [], uredaji: [] };
    if (raw.length < 2) return res.json(empty);
    const { role, ovlasti } = await _loadOvlasti(req.user.id);
    const isDir = role === 'direktor';
    const can = (k) => isDir || hasPerm(role, ovlasti, k);
    const fold = (col) => `translate(lower(${col}), 'čćžšđ', 'cczsd')`;
    const needle = '%' + raw.toLowerCase().replace(/č/g,'c').replace(/ć/g,'c').replace(/ž/g,'z').replace(/š/g,'s').replace(/đ/g,'d') + '%';
    const LIM = 8;
    const none = Promise.resolve({ rows: [] });
    const Q = (sql, params) => pool.query(sql, params).catch(() => ({ rows: [] }));

    const [grad, rad, dnv, nal, dop, dok, cjen, urd] = await Promise.all([
      can('gradilista') ? Q(`SELECT id, naziv, COALESCE(aktivan,true) AS aktivan FROM gradilista
                  WHERE ${fold('naziv')} LIKE $1 OR ${fold("COALESCE(adresa,'')")} LIKE $1
                  ORDER BY COALESCE(aktivan,true) DESC, naziv LIMIT ${LIM}`, [needle]) : none,
      can('radnici') ? Q(`SELECT id, ime, prezime, COALESCE(aktivan,true) AS aktivan, COALESCE(obrisan,false) AS obrisan FROM radnici
                  WHERE ${fold("ime||' '||prezime")} LIKE $1
                  ORDER BY COALESCE(aktivan,true) DESC, prezime, ime LIMIT ${LIM}`, [needle]) : none,
      can('dnevnik') ? Q(`SELECT d.id, d.datum, d.komentar, d.gradiliste_id, g.naziv AS gradiliste, COALESCE(g.aktivan,true) AS grad_aktivan FROM dnevnik d
                  LEFT JOIN gradilista g ON g.id=d.gradiliste_id
                  WHERE COALESCE(d.komentar,'') <> '' AND ${fold("d.komentar")} LIKE $1
                  ORDER BY d.datum DESC LIMIT ${LIM}`, [needle]) : none,
      can('nalozi') ? Q(`SELECT n.id, n.komentar, n.rijesen, n.created_at, g.naziv AS gradiliste FROM nalozi n
                  LEFT JOIN gradilista g ON g.id=n.gradiliste_id
                  WHERE COALESCE(n.komentar,'') <> '' AND ${fold("n.komentar")} LIKE $1
                  ORDER BY n.created_at DESC LIMIT ${LIM}`, [needle]) : none,
      can('asistent') ? Q(isDir
            ? `SELECT id, naziv, token, created_at FROM asistent_dopisi
                  WHERE ${fold("COALESCE(naziv,'')")} LIKE $1 ORDER BY created_at DESC LIMIT ${LIM}`
            : `SELECT id, naziv, token, created_at FROM asistent_dopisi
                  WHERE korisnik_id = $2 AND ${fold("COALESCE(naziv,'')")} LIKE $1 ORDER BY created_at DESC LIMIT ${LIM}`,
          isDir ? [needle] : [needle, req.user.id]) : none,
      can('radnici') ? Q(`SELECT dk.id, dk.radnik_id, dk.tip, dk.naziv, dk.napomena, (r.ime||' '||r.prezime) AS radnik
                  FROM radnici_dokumenti dk LEFT JOIN radnici r ON r.id=dk.radnik_id
                  WHERE ${fold("COALESCE(dk.naziv,'')")} LIKE $1 OR ${fold("COALESCE(dk.tip,'')")} LIKE $1 OR ${fold("COALESCE(dk.napomena,'')")} LIKE $1
                  ORDER BY dk.created_at DESC LIMIT ${LIM}`, [needle]) : none,
      // ⭐ v408: cjenik (cijene materijala) — DIREKTOR-only (osjetljive cijene; nema 'cjenik' ovlasti)
      isDir ? Q(`SELECT c.id, c.naziv, c.kategorija, c.jedinica, c.cijena_trenutna, p.naziv AS proizvodjac
                  FROM cjenik c LEFT JOIN proizvodjaci p ON p.id=c.proizvodjac_id
                  WHERE ${fold("c.naziv")} LIKE $1 OR ${fold("COALESCE(c.kategorija,'')")} LIKE $1 OR ${fold("COALESCE(p.naziv,'')")} LIKE $1
                  ORDER BY c.naziv LIMIT ${LIM}`, [needle]) : none,
      // ⭐ v408: uređaji/alati — ovlast 'uredaji'
      can('uredaji') ? Q(`SELECT id, naziv, marka, oznaka, opis, COALESCE(otpisan,false) AS otpisan FROM uredaji
                  WHERE ${fold("naziv||' '||COALESCE(marka,'')||' '||COALESCE(oznaka,'')||' '||COALESCE(opis,'')")} LIKE $1
                  ORDER BY COALESCE(otpisan,false), naziv LIMIT ${LIM}`, [needle]) : none,
    ]);
    res.json({
      q: raw,
      gradilista: grad.rows, radnici: rad.rows,
      dnevnik: dnv.rows, nalozi: nal.rows,
      dopisi: dop.rows, dokumenti: dok.rows,
      cjenik: cjen.rows, uredaji: urd.rows
    });
  } catch (e) {
    console.error('GET /search:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.502.20.388 (Ivan): DASHBOARD FINANCIJE — mjesečni rashod za desktop pregled.
//   DIREKTOR-only. Koristi iste single-source helpere kao Analitika/Plaće (alocirajTrosakPoGradilistima
//   za rad brutto, aggregateMaterijal za € materijala iz cjenika, SUM gorivo/servisi po rasponu mjeseca).
//   Vraća: firma totali (rad/materijal/gorivo/servisi/ukupno) + trošak po gradilištu (rad+materijal, direktni).
app.get('/api/pregled/financije', auth, direktor, async (req, res) => {
  try {
    const now = new Date();
    let godina = parseInt(req.query.godina);
    let mjesec = parseInt(req.query.mjesec);
    if (!Number.isFinite(godina) || godina < 2020 || godina > 2100) godina = now.getFullYear();
    if (!Number.isFinite(mjesec) || mjesec < 1 || mjesec > 12) mjesec = now.getMonth() + 1;
    const mm = String(mjesec).padStart(2, '0');
    const datum_od = `${godina}-${mm}-01`;
    const lastDay = new Date(godina, mjesec, 0).getDate();
    const datum_do = `${godina}-${mm}-${String(lastDay).padStart(2, '0')}`;

    // 1. RAD brutto po gradilištu + total
    const radMap = new Map();
    let trosak_rad = 0;
    try {
      const { byGrad } = await alocirajTrosakPoGradilistima({ datum_od, datum_do, samo_aktivna_gradilista: false });
      if (byGrad) for (const [gid, g] of byGrad.entries()) {
        if (Number(gid) < 0) continue;
        const b = g.ukupno_brutto || 0;
        radMap.set(Number(gid), b);
        trosak_rad += b;
      }
    } catch (e) { console.warn('[pregled/financije] rad fail:', e.message); }

    // 2. MATERIJAL € po gradilištu + total (iz cjenika)
    const matMap = new Map();
    let trosak_materijal = 0;
    try {
      const matAggr = await aggregateMaterijal({ od_datum: datum_od, do_datum: datum_do });
      for (const m of (matAggr.materijal_po_gradilistima || [])) {
        const eur = parseFloat(m.ukupno_eur) || 0;
        trosak_materijal += eur;
        if (m.id != null) matMap.set(Number(m.id), eur);
      }
    } catch (e) { console.warn('[pregled/financije] materijal fail:', e.message); }

    // 3. GORIVO + SERVISI (firma total, nisu per-gradilište)
    let trosak_gorivo = 0, trosak_servisi = 0;
    try {
      const gQ = await pool.query(`SELECT COALESCE(SUM(iznos),0)::float AS eur FROM gorivo_unosi WHERE datum >= $1 AND datum <= $2 AND tip = 'trosak'`, [datum_od, datum_do]);
      trosak_gorivo = parseFloat(gQ.rows[0]?.eur) || 0;
    } catch (e) {}
    try {
      const sQ = await pool.query(`SELECT COALESCE(SUM(iznos),0)::float AS eur FROM servisi WHERE datum >= $1 AND datum <= $2`, [datum_od, datum_do]);
      trosak_servisi = parseFloat(sQ.rows[0]?.eur) || 0;
    } catch (e) {}

    // 4. Nazivi gradilišta + spoji rad+materijal po gradilištu
    const gids = new Set([...radMap.keys(), ...matMap.keys()]);
    const nazivi = {};
    if (gids.size) {
      try {
        const gr = await pool.query(`SELECT id, naziv FROM gradilista WHERE id = ANY($1::int[])`, [[...gids]]);
        for (const r of gr.rows) nazivi[r.id] = r.naziv;
      } catch (e) {}
    }
    const po_gradilistu = [...gids].map(gid => {
      const rad = radMap.get(gid) || 0;
      const materijal = matMap.get(gid) || 0;
      return { gradiliste_id: gid, naziv: nazivi[gid] || ('Gradilište #' + gid), rad, materijal, ukupno: rad + materijal };
    }).filter(g => g.ukupno > 0).sort((a, b) => b.ukupno - a.ukupno);

    const ukupno = trosak_rad + trosak_materijal + trosak_gorivo + trosak_servisi;
    res.json({ godina, mjesec, trosak_rad, trosak_materijal, trosak_gorivo, trosak_servisi, ukupno, po_gradilistu });
  } catch (e) {
    console.error('GET /pregled/financije:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.502.20.389 (Ivan): DASHBOARD ISTECI — dokumenti radnika koji ističu/istekli (DIREKTOR only,
//   HR-osjetljivo kao OIB). Vraća dozvola/liječnički/putovnica koji ističu unutar prozora (default 60 dana)
//   ili su već istekli, sortirano po hitnosti (najprije istekli/najbliži).
app.get('/api/pregled/isteci', auth, direktor, async (req, res) => {
  try {
    let dana = parseInt(req.query.dana);
    if (!Number.isFinite(dana) || dana < 1 || dana > 365) dana = 60;
    const q = await pool.query(`
      SELECT id, ime, prezime, dozvola_vrijedi_do, lijecnicki_vrijedi_do, putovnica_vrijedi_do
      FROM radnici
      WHERE COALESCE(aktivan, true) = true AND COALESCE(obrisan, false) = false
        AND (dozvola_vrijedi_do IS NOT NULL OR lijecnicki_vrijedi_do IS NOT NULL OR putovnica_vrijedi_do IS NOT NULL)
    `);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const items = [];
    const addDoc = (r, tip, datum) => {
      if (!datum) return;
      const d = new Date(datum); d.setHours(0, 0, 0, 0);
      const dana_do = Math.round((d - today) / 86400000);
      items.push({ radnik_id: r.id, ime: r.ime, prezime: r.prezime, tip, datum, dana_do });
    };
    for (const r of q.rows) {
      addDoc(r, 'dozvola', r.dozvola_vrijedi_do);
      addDoc(r, 'lijecnicki', r.lijecnicki_vrijedi_do);
      addDoc(r, 'putovnica', r.putovnica_vrijedi_do);
    }
    const filtered = items.filter(i => i.dana_do <= dana).sort((a, b) => a.dana_do - b.dana_do);
    res.json(filtered);
  } catch (e) {
    console.error('GET /pregled/isteci:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v393 (Ivan): DASHBOARD — KOLIČINA MATERIJALA PO AKTIVNIM GRADILIŠTIMA (CIJELI VIJEK).
//   Top 8 unosa po gradilištu, konvertirano u osnovnu jedinicu (kg/m²/m'/kom) preko aggregateMaterijal
//   (SINGLE SOURCE — ista logika kao PDF raspis: pakiranja t→kg, pal→kg/m², bala→m², izolacija po deb_cm).
//   EPS po debljini = odvojene stavke (npr. "EPS F 18cm 3.000 m²", "EPS F 15cm 2.000 m²").
//   BEZ € / cijena u odgovoru → Memsur (poslovođa) smije količine (operativno), ne financije.
//   Gate `staff`: vraća čiste količine; nijedan eur ni raspis-string (koji sadrži €) ne ide van.
app.get('/api/pregled/materijal-gradilista', auth, staff, async (req, res) => {
  try {
    // Lifetime raspon iz tablice materijal (fallback širok)
    let od = '2015-01-01', do_ = _ymd(new Date());
    try {
      const rq = await pool.query(`SELECT MIN(datum)::date AS prvi, MAX(datum)::date AS zadnji FROM materijal`);
      const r = rq.rows[0] || {};
      if (r.prvi)   od  = (r.prvi   instanceof Date ? r.prvi.toISOString()   : String(r.prvi)).slice(0, 10);
      if (r.zadnji) do_ = (r.zadnji instanceof Date ? r.zadnji.toISOString() : String(r.zadnji)).slice(0, 10);
    } catch (_) {}
    const aggr = await aggregateMaterijal({ od_datum: od, do_datum: do_ });
    const perGrad = aggr.materijal_detalji_po_gradilistu || [];
    const jeDir = req.user?.role === 'direktor';  // ⭐ v395: € (ukupan trošak materijala) SAMO direktoru — Memsur samo količine
    const dispNaziv = (grp) => {
      let n = (grp.pod_naziv || grp.naziv || '?').toString().trim() || '?';
      if (grp.deb_cm && !/\d+\s*cm/i.test(n)) n += ` ${grp.deb_cm}cm`;  // dodaj debljinu ako već nije u nazivu
      return n;
    };
    const out = perGrad
      .filter(g => !g.arhivirano && g.gradiliste_id)   // samo AKTIVNA (ne-arhivirana), preskoči orphan
      .map(g => {
        const grupe = (g.grupe || [])
          // ⭐ v397 (Ivan): SVE grupe (bez slice) — frontend prikazuje top 8 + ostatak na klik "+N ostalih"
          .map(grp => ({
            naziv: dispNaziv(grp),
            kolicina: Math.round((parseFloat(grp.ukupno_baz_kolicina) || 0) * 10) / 10,
            jedinica: grp.baz_jedinica || '',
            nedef: !!grp.ima_nedef_jed   // ⭐ v421: true → jedinica nije definirana u cjeniku (⚠)
          }))
          .filter(x => x.kolicina > 0);                 // već sortirano po € (proxy "najveći materijal")
        return {
          gradiliste_id: g.gradiliste_id,
          naziv: g.gradiliste_naziv || ('Gradilište #' + g.gradiliste_id),
          ukupno_vrsta: grupe.length,                   // ⭐ v397: broj prikazivih vrsta (sve s kolicina>0)
          eur: jeDir ? Math.round((parseFloat(g.ukupno_eur) || 0) * 100) / 100 : undefined,  // ⭐ v395: ukupan trošak materijala gradilišta
          grupe
        };
      })
      .filter(g => g.grupe.length > 0)
      .sort((a, b) => b.ukupno_vrsta - a.ukupno_vrsta);
    res.json(out);
  } catch (e) {
    console.error('GET /pregled/materijal-gradilista:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.502.20.416 (Ivan): DIJAGNOSTIKA — zašto "materijal po gradilištu" krivo prikazuje količinu.
//   Vraća SIROVE podatke za dani naziv: (1) svaki materijal unos s njegovim cjenik_id + povezana cjenik
//   stavka (kategorija/jedinica/pakiranja), (2) SVE cjenik stavke koje matchaju naziv (s pakiranjima).
//   Iz toga vidimo: ima li unos cjenik_id, koja je kategorija (mrezica vs ostalo), ima li cjenik stavka
//   pakiranja (rola→m²) i poklapa li se naziv. Direktor only, read-only. Otvori u browseru:
//   app.zbuka.hr/api/debug/materijal-calc?naziv=P100
app.get('/api/debug/materijal-calc', auth, direktor, async (req, res) => {
  try {
    const naziv = (req.query.naziv || '').trim();
    if (!naziv) return res.status(400).json({ error: 'naziv param obavezan (npr. ?naziv=P100)' });
    const matR = await pool.query(
      `SELECT m.id, m.naziv, m.dobavljac, m.tip, m.jedinica, m.kolicina, m.cjenik_id, m.gradiliste_id,
              to_char(m.datum,'YYYY-MM-DD') AS datum,
              c.naziv AS cjen_naziv, c.dobavljac AS cjen_dobavljac, c.kategorija AS cjen_kategorija,
              c.jedinica AS cjen_jedinica, c.pakiranja AS cjen_pakiranja, c.paleta_kolicina AS cjen_paleta
         FROM materijal m
         LEFT JOIN cjenik c ON c.id = m.cjenik_id
        WHERE m.naziv ILIKE $1
        ORDER BY m.datum DESC
        LIMIT 50`,
      [`%${naziv}%`]
    );
    const cjenR = await pool.query(
      `SELECT id, naziv, dobavljac, kategorija, jedinica, pakiranja, paleta_kolicina, cijena_trenutna
         FROM cjenik
        WHERE naziv ILIKE $1
        ORDER BY naziv, dobavljac
        LIMIT 50`,
      [`%${naziv}%`]
    );
    res.json({
      naziv_filter: naziv,
      objasnjenje: 'materijal_unosi: provjeri cjenik_id (null=nije povezan), cjen_kategorija (treba mrezica), cjen_pakiranja (treba [{jed:rola,u_osnovnoj:50}]). cjenik_stavke: sve stavke s tim nazivom i njihova pakiranja.',
      broj_unosa: matR.rows.length,
      materijal_unosi: matR.rows,
      broj_cjenik_stavki: cjenR.rows.length,
      cjenik_stavke: cjenR.rows
    });
  } catch (e) {
    console.error('GET /debug/materijal-calc:', e.message);
    res.status(500).json({ error: e.message });
  }
});
