// ⭐ v399 (Ivan): NORMA SAT (Ns) — DIREKTOR only (financije).
//   Ns = ukupni radni sati gradilišta / m² ugrađene fasade (sati po m²).
//   Trošak €/m² = Ns × medijanska BRUTO satnica.
//   Medijanska bruto satnica = medijan(zadnja valjana satnica po aktivnom ne-direktor radniku) + bruto_dodatak (doprinosi/h).
//     - satnica = ugovorna €/h (place_parametri, carry-forward zadnje valjane vrijednosti)
//     - bruto_dodatak = doprinosi po satu (postavke, default 5.50) → puni trošak firme po radnom satu
//     - MEDIJAN (ne prosjek) = otporan na outliere (jedan jako visok/nizak radnik ne pomiče rezultat)
//   Sati po gradilištu = LIFETIME (cijeli vijek), ne-direktor, bez bolovanja (konzistentno s troškom rada).
app.get('/api/pregled/norma-sat', auth, direktor, async (req, res) => {
  try {
    // ⭐ v401 (Ivan): config doprinosa — norma sat poštuje model (flat €/h ili postotak na bruto).
    const _normaCfg = await getDoprinosiConfig();
    const bruto_dod = _normaCfg.bruto_dod;
    const _normaPct = _normaCfg.model === 'postotak' ? _normaCfg.postotak : 0;
    // 1. Medijan satnica — zadnja VALJANA satnica po aktivnom ne-direktor radniku
    const ppQ = await pool.query(`
      SELECT p.radnik_id, p.godina, p.mjesec, p.satnica, COALESCE(p.satnica_set, false) AS satnica_set
      FROM place_parametri p
      JOIN radnici r ON r.id = p.radnik_id
      WHERE r.role != 'direktor' AND COALESCE(r.aktivan, true) = true
      ORDER BY p.radnik_id, p.godina DESC, p.mjesec DESC
    `);
    const byRad = new Map();
    for (const row of ppQ.rows) {
      if (!byRad.has(row.radnik_id)) byRad.set(row.radnik_id, []);
      byRad.get(row.radnik_id).push(row);
    }
    const satnice = [];
    for (const [rid, rows] of byRad) {
      let s = null;
      for (const r of rows) { const v = parseFloat(r.satnica) || 0; if (satnicaVrijedna(v, r.satnica_set)) { s = v; break; } }  // zadnja valjana (rows su DESC)
      if (s == null) { const raw = parseFloat(rows[0]?.satnica) || 0; if (raw > 0) s = raw; }  // fallback: zadnja sirova >0
      if (s != null && s > 0) satnice.push(s);
    }
    const median_satnica = Math.round(_median(satnice) * 100) / 100;  // ⭐ v400: _median iz lib/place-math
    // ⭐ v401 (Ivan): bruto satnica = satnica + €/h (flat) ILI satnica × (1 + %/100) (postotni).
    const median_bruto_satnica = _normaPct > 0
      ? Math.round((median_satnica * (1 + _normaPct / 100)) * 100) / 100
      : Math.round((median_satnica + bruto_dod) * 100) / 100;
    // doprinosi po satu (za info prikaz): €/h fiksno ili satnica×%
    const dopr_po_satu = _normaPct > 0 ? Math.round((median_satnica * _normaPct / 100) * 100) / 100 : bruto_dod;
    // 2. Lifetime sati po gradilištu (ne-direktor, bez bolovanja) + spremljeni m²
    const gQ = await pool.query(`
      SELECT s.gradiliste_id,
             COALESCE(g.naziv, 'Gradilište #' || s.gradiliste_id) AS naziv,
             g.m2_fasada AS m2,
             SUM(s.sati_redovni) AS sati
      FROM sihterica s
      JOIN radnici r ON r.id = s.radnik_id
      LEFT JOIN gradilista g ON g.id = s.gradiliste_id
      WHERE r.role != 'direktor' AND COALESCE(s.bolovanje, false) = false AND s.gradiliste_id IS NOT NULL
      GROUP BY s.gradiliste_id, g.naziv, g.m2_fasada
      HAVING SUM(s.sati_redovni) > 0
      ORDER BY SUM(s.sati_redovni) DESC
    `);
    const gradilista = gQ.rows.map(r => ({
      gradiliste_id: r.gradiliste_id,
      naziv: r.naziv,
      sati: Math.round((parseFloat(r.sati) || 0) * 10) / 10,
      m2: (r.m2 != null) ? parseFloat(r.m2) : null
    }));
    res.json({ median_satnica, bruto_dodatak: bruto_dod, median_bruto_satnica, n_radnika: satnice.length, gradilista,
               doprinosi_model: _normaPct > 0 ? 'postotak' : 'flat', doprinosi_postotak: _normaPct, dopr_po_satu });
  } catch (e) {
    console.error('GET /pregled/norma-sat:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v399 (Ivan): spremi m² ugrađene fasade za gradilište (norma-sat). DIREKTOR only.
app.post('/api/pregled/norma-sat/m2', auth, direktor, async (req, res) => {
  try {
    const gid = parseInt(req.body?.gradiliste_id);
    let m2 = req.body?.m2;
    m2 = (m2 === null || m2 === undefined || m2 === '') ? null : parseFloat(m2);
    if (!Number.isFinite(gid)) return res.status(400).json({ error: 'gradiliste_id nedostaje' });
    if (m2 != null && (!Number.isFinite(m2) || m2 < 0)) return res.status(400).json({ error: 'm2 nevažeći' });
    await pool.query('UPDATE gradilista SET m2_fasada = $1 WHERE id = $2', [m2, gid]);
    res.json({ ok: true, gradiliste_id: gid, m2 });
  } catch (e) {
    console.error('POST /pregled/norma-sat/m2:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v400 (Ivan, P1 audit): DASHBOARD AGREGAT — sva operativna statistika u JEDNOM pozivu (GROUP BY na bazi).
//   Zamjenjuje vučenje sirovih šihterica redaka (365d = tisuće redaka) → mali JSON, brži dashboard.
//   Vraća: cur/prev totale (za delta), po_danu (chart), po_gradilistu, po_radniku. Koristi indekse idx_sih_*.
//   auth+staff (operativa, BEZ €) — isti pristup kao /api/sihterica.
app.get('/api/sihterica/dashboard-stats', auth, staff, async (req, res) => {
  try {
    const od = (req.query.od || '').slice(0, 10);
    const do_ = (req.query.do || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(od) || !/^\d{4}-\d{2}-\d{2}$/.test(do_)) {
      return res.status(400).json({ error: 'od/do moraju biti YYYY-MM-DD' });
    }
    // Prethodni jednako dug period: [od - (do-od), od)
    const odD = new Date(od + 'T00:00:00');
    const doD = new Date(do_ + 'T00:00:00');
    const durMs = Math.max(0, doD - odD);
    const prevOd = new Date(odD - durMs - 86400000);  // -1 dan da se ne preklapa s 'od'
    const prevDo = new Date(odD - 86400000);
    const fmt = (d) => _ymd(d);
    const prevOdS = fmt(prevOd), prevDoS = fmt(prevDo);

    const totalsSQL = `
      SELECT COALESCE(SUM(sati_redovni),0)::float AS sati,
             COUNT(DISTINCT radnik_id) AS radnika,
             COUNT(*) AS unosa,
             COUNT(DISTINCT gradiliste_id) FILTER (WHERE gradiliste_id IS NOT NULL) AS grad
      FROM sihterica WHERE datum >= $1 AND datum <= $2`;

    const [curT, prevT, poDanu, poGrad, poRadnik] = await Promise.all([
      pool.query(totalsSQL, [od, do_]),
      pool.query(totalsSQL, [prevOdS, prevDoS]),
      pool.query(`SELECT datum::text AS datum, COALESCE(SUM(sati_redovni),0)::float AS sati
                  FROM sihterica WHERE datum >= $1 AND datum <= $2 GROUP BY datum ORDER BY datum`, [od, do_]),
      pool.query(`SELECT s.gradiliste_id,
                         COALESCE(g.naziv, 'Gradilište #' || s.gradiliste_id) AS naziv,
                         COALESCE(SUM(s.sati_redovni),0)::float AS sati
                  FROM sihterica s LEFT JOIN gradilista g ON g.id = s.gradiliste_id
                  WHERE s.datum >= $1 AND s.datum <= $2 AND s.gradiliste_id IS NOT NULL
                  GROUP BY s.gradiliste_id, g.naziv ORDER BY sati DESC`, [od, do_]),
      pool.query(`SELECT s.radnik_id, r.ime, r.prezime, COALESCE(SUM(s.sati_redovni),0)::float AS sati
                  FROM sihterica s JOIN radnici r ON r.id = s.radnik_id
                  WHERE s.datum >= $1 AND s.datum <= $2
                  GROUP BY s.radnik_id, r.ime, r.prezime ORDER BY sati DESC`, [od, do_])
    ]);

    const norm = (row) => ({
      sati: Math.round((parseFloat(row.sati) || 0) * 10) / 10,
      radnika: parseInt(row.radnika) || 0,
      unosa: parseInt(row.unosa) || 0,
      grad: parseInt(row.grad) || 0
    });

    res.json({
      od, do: do_,
      cur: norm(curT.rows[0] || {}),
      prev: norm(prevT.rows[0] || {}),
      po_danu: poDanu.rows.map(r => ({ datum: (r.datum || '').slice(0, 10), sati: Math.round((parseFloat(r.sati) || 0) * 10) / 10 })),
      po_gradilistu: poGrad.rows.map(r => ({ gradiliste_id: r.gradiliste_id, naziv: r.naziv, sati: Math.round((parseFloat(r.sati) || 0) * 10) / 10 })),
      po_radniku: poRadnik.rows.map(r => ({ radnik_id: r.radnik_id, ime: r.ime, prezime: r.prezime, sati: Math.round((parseFloat(r.sati) || 0) * 10) / 10 }))
    });
  } catch (e) {
    console.error('GET /sihterica/dashboard-stats:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ── ANALITIKA — bonus i bolovanje po radniku ────────────────────────────────

app.get('/api/analitika/bonus-bolovanje', auth, direktor, async (req, res) => {
  try {
    const godina = validateGodina(req.query.godina);
    const result = await pool.query(`
      SELECT
        r.ime || ' ' || r.prezime AS radnik,
        COALESCE(SUM(p.bonus),             0) AS uk_bonus,
        COALESCE(SUM(p.naknada_bolovanje), 0) AS uk_bolovanje,
        COALESCE(SUM(p.godisnji),          0) AS uk_godisnji,   -- ⭐ v904 (Ivan): i godišnji je trošak
        COALESCE((SELECT COUNT(DISTINCT s.datum) FROM sihterica s
                   WHERE s.radnik_id = r.id AND EXTRACT(YEAR FROM s.datum)::int = $1
                     AND COALESCE(s.bolovanje,false)), 0) AS bol_dana,   -- ⭐ v904: dani iz šihterice uz iznos iz Plaća
        COALESCE((SELECT COUNT(DISTINCT s.datum) FROM sihterica s
                   WHERE s.radnik_id = r.id AND EXTRACT(YEAR FROM s.datum)::int = $1
                     AND COALESCE(s.godisnji,false)), 0) AS god_dana
      FROM radnici r
      JOIN place_parametri p ON p.radnik_id = r.id AND p.godina = $1
      WHERE r.role != 'direktor'
        AND (p.bonus > 0 OR p.naknada_bolovanje > 0 OR p.godisnji > 0
             OR EXISTS (SELECT 1 FROM sihterica s2 WHERE s2.radnik_id = r.id
                          AND EXTRACT(YEAR FROM s2.datum)::int = $1
                          AND (COALESCE(s2.bolovanje,false) OR COALESCE(s2.godisnji,false))))   -- ⭐ v909: i dani bez iznosa (⚠ oba smjera)
      GROUP BY r.id, r.ime, r.prezime
      ORDER BY uk_bonus DESC, uk_bolovanje DESC
    `, [godina]);
    res.json(result.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── ANALITIKA — trošak rada po gradilištu ─────────────────────────────────────────
app.get('/api/analitika/trosak-grad', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.68 (Ivan, 23.05.2026): CUMULATIVE CIJELA POVIJEST — identično kao brošura
    //   PRIJE (v501.62): zadnjih 12 mjeseci rolling → razlikovalo se od brošure (cijela povijest)
    //   SAD: cijela povijest gradilišta (od najranijeg do najnovijeg unosa)
    //        → Analitika i Brošura PDF moraju biti identični broj za isto gradilište
    //   Datum range: MIN/MAX iz sihterica + materijal za sva gradilišta
    const rangeQ = await pool.query(`
      SELECT
        LEAST(
          (SELECT MIN(datum)::date FROM sihterica),
          (SELECT MIN(datum)::date FROM materijal)
        ) AS prvi,
        GREATEST(
          (SELECT MAX(datum)::date FROM sihterica),
          (SELECT MAX(datum)::date FROM materijal),
          (now() AT TIME ZONE $$Europe/Zagreb$$)::date
        ) AS zadnji
    `);
    const rng = rangeQ.rows[0] || {};
    const od = rng.prvi ? (rng.prvi instanceof Date ? _ymd(rng.prvi) : String(rng.prvi).slice(0, 10)) : '2020-01-01';
    const doD = rng.zadnji ? (rng.zadnji instanceof Date ? _ymd(rng.zadnji) : String(rng.zadnji).slice(0, 10)) : _ymd(new Date());

    const { byGrad, bruto_dod } = await alocirajTrosakPoGradilistima({
      datum_od: od,
      datum_do: doD,
      samo_aktivna_gradilista: false  // ⭐ v501.62: uključi sva (Ivan dogovor)
    });

    // Pretvori Map → niz; per radnik objekt → niz s weighted average satnicom
    // ⭐ v502.19.4 (Ivan, 26.05.2026): dodan bruto_dod_used u svaki red — frontend treba znati 
    //   stvarnu DB vrijednost da pravilno skalira stepper "what-if" simulaciju.
    //   PRIJE: frontend hardkodirao BASE_DOD=5.50 → kad Ivan promijeni DB postavku na 0.10,
    //          frontend dvaput skalira (× 0.10 / 5.50 = × 0.018) → 1.635 € prikazani kao 31 €.
    const output = Array.from(byGrad.values()).map(g => ({
      grad_id: g.grad_id,
      naziv: g.naziv,
      bruto_dod_used: bruto_dod,              // ⭐ v502.19.4: DB vrijednost
      ukupno_sati: g.ukupno_sati,
      ukupno_netto: g.ukupno_netto,           // ⭐ NOVO v501.62: netto trošak (proporcionalan iz Plaće)
      ukupno_doprinosi: g.ukupno_doprinosi,   // ⭐ NOVO v501.62: doprinosi (sati × bruto_dod)
      ukupno_brutto: g.ukupno_brutto,         // ⭐ NOVO v501.62: BRUTTO = netto + doprinosi
      ukupno_bonus_alloc: g.ukupno_bonus_alloc,       // ⭐ NOVO v501.62: bonus alociran (proporcionalno)
      ukupno_bolovanje_alloc: g.ukupno_bolovanje_alloc, // ⭐ NOVO v501.62: bolovanje alocirano
      ukupno_trosak: g.ukupno_brutto,         // backward compat alias (brutto)
      radnici: Object.values(g.radnici).map(r => ({
        radnik: r.radnik,
        sati: r.sati,
        netto: r.netto,
        brutto: r.brutto,
        rad_netto: r.rad_netto,  // sati × satnica (čisti rad)
        bonus: r.bonus,
        bolovanje: r.bolovanje,
        trosak: r.brutto,         // backward compat
        satnica: r.sati > 0 ? (r.rad_netto / r.sati) : 0  // weighted avg
      }))
    }));

    // ⭐ v502.20.11 (Ivan, 27.05.2026): MATERIJAL-ONLY GRADILIŠTA u trošak listi
    //   PROBLEM (Ivan): gradilište Trešćakovec ima samo materijal (bez radnih sati) — 
    //   nije se pojavljivalo u "Trošak gradilišta" panelu Analitike, iako je vidljivo 
    //   u P&L tablici (jer calcProfitabilnost spaja sve izvore).
    //   ROOT CAUSE: byGrad Map se gradi isključivo iz sihterice. Gradilište bez sati = 
    //   ne postoji u output listi.
    //   FIX: nakon byGrad output-a, dohvati sva gradilišta koja imaju materijal ILI 
    //   kooperante ali nisu u byGrad. Za svako dodaj prazan zapis (0 sati, 0 rad) → 
    //   materijal i kooperanti će se popuniti u sljedeće 2 petlje.
    try {
      const existingIds = new Set(output.map(o => Number(o.grad_id)));
      
      // Gradilišta koja imaju materijal u period-u
      const matGidsQ = await pool.query(`
        SELECT DISTINCT gradiliste_id FROM materijal 
        WHERE datum >= $1 AND datum <= $2 AND gradiliste_id IS NOT NULL
      `, [od, doD]);
      
      // Gradilišta koja imaju kooperante u period-u
      const koopGidsQ = await pool.query(`
        SELECT DISTINCT gradiliste_id FROM kooperanti 
        WHERE datum >= $1 AND datum <= $2 AND gradiliste_id IS NOT NULL
      `, [od, doD]);
      
      const extraGids = new Set();
      for (const r of matGidsQ.rows)  if (r.gradiliste_id && !existingIds.has(Number(r.gradiliste_id))) extraGids.add(Number(r.gradiliste_id));
      for (const r of koopGidsQ.rows) if (r.gradiliste_id && !existingIds.has(Number(r.gradiliste_id))) extraGids.add(Number(r.gradiliste_id));
      
      if (extraGids.size > 0) {
        // Dohvati nazive za extra gradilišta
        const extraGidsArr = Array.from(extraGids);
        const nQ = await pool.query(`SELECT id, naziv FROM gradilista WHERE id = ANY($1)`, [extraGidsArr]);
        const nameMap = new Map();
        for (const r of nQ.rows) nameMap.set(Number(r.id), r.naziv);
        
        for (const gid of extraGidsArr) {
          output.push({
            grad_id: gid,
            naziv: nameMap.get(gid) || '(nepoznato)',
            bruto_dod_used: bruto_dod,
            ukupno_sati: 0,
            ukupno_netto: 0,
            ukupno_doprinosi: 0,
            ukupno_brutto: 0,
            ukupno_bonus_alloc: 0,
            ukupno_bolovanje_alloc: 0,
            ukupno_trosak: 0,
            radnici: []
          });
        }
        console.log(`[trosak-grad v502.20.11] + ${extraGids.size} gradilišta s materijalom/kooperantima bez sati`);
      }
    } catch (e) {
      console.warn('[trosak-grad v502.20.11] extra gradilišta fail:', e.message);
    }

    // Trošak materijala per gradilište (12-mj period) — iz aggregateMaterijal
    try {
      for (const grad of output) {
        try {
          const matAggr = await aggregateMaterijal({ 
            od_datum: od, 
            do_datum: doD, 
            gradiliste_id: grad.grad_id 
          });
          grad.trosak_materijal = parseFloat(matAggr.ukupno_eur) || 0;
          grad.materijal_unosa = matAggr.ukupno_unosa || 0;
        } catch (e) {
          grad.trosak_materijal = 0;
          grad.materijal_unosa = 0;
        }
      }
      console.log(`[trosak-grad v501.62] alociran trošak (netto + brutto) za ${output.length} gradilišta, bruto_dod=${bruto_dod}`);
    } catch (e) {
      console.warn('[trosak-grad v501.62] materijal aggregation fail:', e.message);
      for (const grad of output) {
        if (grad.trosak_materijal === undefined) {
          grad.trosak_materijal = 0;
          grad.materijal_unosa = 0;
        }
      }
    }
    
    // ⭐ v502.20 (Ivan, 26.05.2026): Trošak kooperanata per gradilište (cijela povijest)
    try {
      const kQ = await pool.query(`
        SELECT gradiliste_id AS grad_id, 
               COALESCE(SUM(iznos), 0)::float AS eur, 
               COUNT(*)::int AS unosa
        FROM kooperanti
        WHERE datum >= $1 AND datum <= $2 AND gradiliste_id IS NOT NULL
        GROUP BY gradiliste_id
      `, [od, doD]);
      const kMap = new Map();
      for (const r of kQ.rows) kMap.set(Number(r.grad_id), r);
      for (const grad of output) {
        const k = kMap.get(Number(grad.grad_id));
        grad.trosak_kooperanti = k ? parseFloat(k.eur) : 0;
        grad.kooperanti_unosa = k ? k.unosa : 0;
      }
    } catch (e) {
      console.warn('[trosak-grad v502.20] kooperanti aggregation fail:', e.message);
      for (const grad of output) {
        if (grad.trosak_kooperanti === undefined) {
          grad.trosak_kooperanti = 0;
          grad.kooperanti_unosa = 0;
        }
      }
    }

    // ⭐ v502.20.11 (Ivan, 27.05.2026): sort po UKUPNOM trošku (brutto + materijal + kooperanti)
    //   PRIJE: sortirano samo po ukupno_brutto → materijal-only gradilišta (brutto=0) padala na dno
    //   SAD: ukupni trošak — Trešćakovec (1.060 € materijal, 0 rad) sortira pravilno
    res.json(output.sort((a, b) => {
      const tA = (a.ukupno_brutto || 0) + (a.trosak_materijal || 0) + (a.trosak_kooperanti || 0);
      const tB = (b.ukupno_brutto || 0) + (b.trosak_materijal || 0) + (b.trosak_kooperanti || 0);
      return tB - tA;
    }));
  } catch(e) { 
    console.error('trosak-grad v501.62:', e.message);
    res.status(500).json({ error: e.message }); 
  }
});

// ⭐ v501.15 (Ivan, 21.05.2026): TREND 12 MJESECI — rad i materijal po mjesecima
//   Vraća array od 12 mjeseci s rad_eur + materijal_eur za svaki mjesec.
//   Format: [{ god, mj, label: "Sij 2026", rad_eur, mat_eur }, ...] (chronological)
//   Use: SVG line chart na Analitika tabu. Vidiš sezonalitet, anomalije, trend up/down.
//   Single source of truth: aggregateMaterijal za materijal, place_parametri za satnice.
app.get('/api/analitika/trend-12m', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.71 (Ivan, 23.05.2026): TREND KALENDARSKE GODINE (Sij-Pro) — ne rolling 12mj
    //   PROBLEM (v501.62 → v501.70): koristio datum_od/datum_do (rolling 12mj). 
    //   To je davalo različit (god,mj,radnik) tuple set od mjesečnog endpointa  
    //   (koji koristi godina filter). Plus timezone bug u Date(year, month, 0).toISOString()
    //   gubio je 31.05 → trend total ≠ mjesečni total (razlika 1.436h × 5.50 = 7.898 €).
    //   
    //   FIX: prelazim na godina filter (default = trenutna). Trend uvijek prikazuje 
    //   Sij-Pro odabrane godine. Mjeseci u budućnosti će biti 0 (npr. Lip-Pro 2026 
    //   danas 23.05.2026 = 0 €). Total trenda = Total mjesečnog endpointa.
    //   Query param ?godina=2025 za prethodnu godinu.
    // ⭐ v501.99 (Ivan, 24.05.2026) BUG FIX: validacija range godine
    //   PRIJE: parseInt('-100') || 2026 = -100 (truthy negative, fallback ne radi)
    //   SAD: clamp na valid range 2020-2100
    let godina = parseInt(req.query.godina);
    if (!Number.isFinite(godina) || godina < 2020 || godina > 2100) {
      godina = new Date().getFullYear();
    }
    
    const meseci = [];
    for (let mj = 1; mj <= 12; mj++) {
      meseci.push({
        god: godina,
        mj,
        label: ['Sij','Velj','Ožu','Tra','Svi','Lip','Srp','Kol','Ruj','Lis','Stu','Pro'][mj - 1] + ' ' + String(godina).slice(2)
      });
    }
    
    // ⭐ v501.71: single source — calcMjesecniTrosakRada s godina filter
    //   Garantira da total trenda === total /api/analitika/trosak (Po mjesecima)
    const { redovi, bruto_dod } = await calcMjesecniTrosakRada({ godina });
    
    // Sumiraj per mjesec (god × mj)
    const radNettoMap = new Map();
    const doprinosiMap = new Map();
    // ⭐ v501.95 (Ivan, 24.05.2026): bonus + bolovanje + godišnji su odvojene stavke 
    //   (NE više dio doprinosa)
    const bonusMap = new Map();      // sirovi bonus iznos isplaćen
    const bolovanjeMap = new Map();  // sirova naknada bolovanje isplaćena
    const godisnjiMap = new Map();   // sirova godišnji isplata
    const satiMap = new Map();        // ⭐ v501.95: ukupno sati po mjesecu (za frontend stepper recalc)
    for (const m of meseci) {
      radNettoMap.set(`${m.god}_${m.mj}`, 0);
      doprinosiMap.set(`${m.god}_${m.mj}`, 0);
      bonusMap.set(`${m.god}_${m.mj}`, 0);
      bolovanjeMap.set(`${m.god}_${m.mj}`, 0);
      godisnjiMap.set(`${m.god}_${m.mj}`, 0);
      satiMap.set(`${m.god}_${m.mj}`, 0);
    }
    for (const r of redovi) {
      const key = `${r.god}_${r.mj}`;
      if (!radNettoMap.has(key)) continue;
      radNettoMap.set(key, radNettoMap.get(key) + r.netto_trosak);
      doprinosiMap.set(key, doprinosiMap.get(key) + r.doprinosi);
      bonusMap.set(key, bonusMap.get(key) + (r.bonus || 0));
      bolovanjeMap.set(key, bolovanjeMap.get(key) + (r.naknada_bol || 0));
      godisnjiMap.set(key, godisnjiMap.get(key) + (r.godisnji || 0));
      satiMap.set(key, satiMap.get(key) + (r.sati_ukupno || 0));
    }
    
    // ─── MATERIJAL: aggregateMaterijal za cijelu godinu (Sij-Pro) ───
    const od = `${godina}-01-01`;
    const zadLast = `${godina}-12-31`;
    const matMap = new Map();
    for (const m of meseci) matMap.set(`${m.god}_${m.mj}`, 0);
    
    try {
      const matAggr = await aggregateMaterijal({ od_datum: od, do_datum: zadLast });
      for (const x of (matAggr.materijal_po_god_mj || [])) {
        const key = `${x.god}_${x.mj}`;
        if (matMap.has(key)) {
          matMap.set(key, parseFloat(x.eur) || 0);
        }
      }
    } catch(e) {
      console.warn('[trend-12m v501.71] aggregateMaterijal fail, all months = 0:', e.message);
    }
    
    // ⭐ v501.75 (Ivan, 23.05.2026): GORIVO, SERVISI, SMEĆE — dodano u trend
    //   Razlog: Ivan želi sveobuhvatan prikaz svih troškova firme u trend grafu, 
    //   ne samo rad+materijal. Ukupno sad uključuje sve 5 kategorija.
    const gorivoMap = new Map();
    const servisiMap = new Map();
    const smeceMap = new Map();
    for (const m of meseci) {
      gorivoMap.set(`${m.god}_${m.mj}`, 0);
      servisiMap.set(`${m.god}_${m.mj}`, 0);
      smeceMap.set(`${m.god}_${m.mj}`, 0);
    }
    
    try {
      // Gorivo: samo trosak tipa (tip='trosak'), ne uplate
      const gQ = await pool.query(`
        SELECT EXTRACT(YEAR FROM datum)::int AS god, EXTRACT(MONTH FROM datum)::int AS mj, 
               COALESCE(SUM(iznos), 0)::float AS eur
        FROM gorivo_unosi
        WHERE datum >= $1 AND datum <= $2 AND tip = 'trosak'
        GROUP BY god, mj
      `, [od, zadLast]);
      for (const r of gQ.rows) {
        const key = `${r.god}_${r.mj}`;
        if (gorivoMap.has(key)) gorivoMap.set(key, r.eur);
      }
    } catch(e) { console.warn('[trend-12m v501.75] gorivo aggr fail:', e.message); }
    
    try {
      const sQ = await pool.query(`
        SELECT EXTRACT(YEAR FROM datum)::int AS god, EXTRACT(MONTH FROM datum)::int AS mj, 
               COALESCE(SUM(iznos), 0)::float AS eur
        FROM servisi
        WHERE datum >= $1 AND datum <= $2
        GROUP BY god, mj
      `, [od, zadLast]);
      for (const r of sQ.rows) {
        const key = `${r.god}_${r.mj}`;
        if (servisiMap.has(key)) servisiMap.set(key, r.eur);
      }
    } catch(e) { console.warn('[trend-12m v501.75] servisi aggr fail:', e.message); }
    
    try {
      const smQ = await pool.query(`
        SELECT EXTRACT(YEAR FROM datum)::int AS god, EXTRACT(MONTH FROM datum)::int AS mj, 
               COALESCE(SUM(iznos), 0)::float AS eur
        FROM smece
        WHERE datum >= $1 AND datum <= $2
        GROUP BY god, mj
      `, [od, zadLast]);
      for (const r of smQ.rows) {
        const key = `${r.god}_${r.mj}`;
        if (smeceMap.has(key)) smeceMap.set(key, r.eur);
      }
    } catch(e) { console.warn('[trend-12m v501.75] smece aggr fail:', e.message); }
    
    // ⭐ v502.20 (Ivan, 26.05.2026): KOOPERANTI per mjesec (kao gorivo/servisi/smeće)
    const kooperantiMap = new Map();
    for (const m of meseci) kooperantiMap.set(`${m.god}_${m.mj}`, 0);
    try {
      const kQ = await pool.query(`
        SELECT EXTRACT(YEAR FROM datum)::int AS god, EXTRACT(MONTH FROM datum)::int AS mj,
               COALESCE(SUM(iznos), 0)::float AS eur
        FROM kooperanti
        WHERE datum >= $1 AND datum <= $2
        GROUP BY god, mj
      `, [od, zadLast]);
      for (const r of kQ.rows) {
        const key = `${r.god}_${r.mj}`;
        if (kooperantiMap.has(key)) kooperantiMap.set(key, r.eur);
      }
    } catch(e) { console.warn('[trend-12m v502.20] kooperanti aggr fail:', e.message); }
    
    // Sastavi finalni response — razdvojeno netto + doprinosi + brutto + materijal + gorivo + servisi + smeće + kooperanti + ukupno
    // ⭐ v502.19.4 (Ivan, 26.05.2026): bruto_dod_used u svaki red — frontend BASE_DOD treba biti pravilan
    const output = meseci.map(m => {
      const key = `${m.god}_${m.mj}`;
      const rad_netto = radNettoMap.get(key) || 0;
      const doprinosi_eur = doprinosiMap.get(key) || 0;
      const rad_brutto = rad_netto + doprinosi_eur;
      const mat_eur = matMap.get(key) || 0;
      const gorivo_eur = gorivoMap.get(key) || 0;
      const servisi_eur = servisiMap.get(key) || 0;
      const smece_eur = smeceMap.get(key) || 0;
      const kooperanti_eur = kooperantiMap.get(key) || 0;  // ⭐ v502.20
      // ⭐ v501.95 (Ivan, 24.05.2026): bonus + bolovanje + godišnji kao odvojene stavke
      //   (NE više razloženje doprinosa)
      const bonus_iznos = bonusMap.get(key) || 0;
      const bolovanje_iznos = bolovanjeMap.get(key) || 0;
      const godisnji_iznos = godisnjiMap.get(key) || 0;
      const sati = satiMap.get(key) || 0;
      return {
        god: m.god,
        mj: m.mj,
        label: m.label,
        bruto_dod_used: bruto_dod,           // ⭐ v502.19.4: DB vrijednost
        rad_netto: Math.round(rad_netto),
        doprinosi_eur: Math.round(doprinosi_eur),
        rad_brutto: Math.round(rad_brutto),
        rad_eur: Math.round(rad_brutto),     // backward compat alias
        mat_eur: Math.round(mat_eur),
        gorivo_eur: Math.round(gorivo_eur),
        servisi_eur: Math.round(servisi_eur),
        smece_eur: Math.round(smece_eur),
        kooperanti_eur: Math.round(kooperanti_eur),  // ⭐ v502.20
        // ⭐ NOVO v501.95: odvojene stavke (bonus + bolovanje + godišnji)
        bonus_iznos: Math.round(bonus_iznos),
        bolovanje_iznos: Math.round(bolovanje_iznos),
        godisnji_iznos: Math.round(godisnji_iznos),
        // ⭐ NOVO v501.95: sati po mjesecu — za frontend stepper recalc
        sati: Math.round(sati),
        // UKUPNO sad uključuje SVE 6 kategorija (rad brutto + materijal + gorivo + servisi + smeće + kooperanti)
        ukupno_eur: Math.round(rad_brutto + mat_eur + gorivo_eur + servisi_eur + smece_eur + kooperanti_eur)
      };
    });
    
    console.log(`[trend-12m v501.95] godina=${godina}, bruto_dod=${bruto_dod}, ukupno redaka=${redovi.length}`);
    res.json(output);
  } catch(e) {
    console.error('trend-12m v501.71:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.15 (Ivan, 21.05.2026): RADNICI OVAJ MJESEC — top 5 + bottom 5
//   Vraća sve radnike sa satima ovaj mjesec + flag "aktivan" (radio bilo kad zadnjih 30 dana).
//   Klijent sortira po satima desc i pokaže top + bottom 5.
//   Use: brzi monitoring "tko ne radi", "tko je odsutan", "tko nosi firmu".
app.get('/api/analitika/radnici-mjesec', auth, direktor, async (req, res) => {
  try {
    const now = new Date();
    const godina = req.query.godina ? parseInt(req.query.godina) : now.getFullYear();
    const mjesec = req.query.mjesec ? parseInt(req.query.mjesec) : (now.getMonth() + 1);
    
    // Početak i kraj mjeseca
    const od = `${godina}-${String(mjesec).padStart(2,'0')}-01`;
    const lastDay = new Date(godina, mjesec, 0);
    const doD = `${lastDay.getFullYear()}-${String(lastDay.getMonth()+1).padStart(2,'0')}-${String(lastDay.getDate()).padStart(2,'0')}`;
    
    // Sati per radnik ovaj mjesec
    const satiQ = await pool.query(`
      SELECT r.id, r.ime, r.prezime,
             COALESCE(SUM(CASE WHEN COALESCE(s.bolovanje, false) = false THEN s.sati_redovni ELSE 0 END), 0)::float AS sati,
             COALESCE(SUM(CASE WHEN COALESCE(s.bolovanje, false) = true THEN s.sati_redovni ELSE 0 END), 0)::float AS bolovanje_sati,
             COUNT(DISTINCT s.datum)::int AS broj_dana
      FROM radnici r
      LEFT JOIN sihterica s 
        ON s.radnik_id = r.id 
        AND s.datum >= $1 
        AND s.datum <= $2
      WHERE r.aktivan = true AND r.role != 'direktor'
      GROUP BY r.id, r.ime, r.prezime
      ORDER BY sati DESC
    `, [od, doD]);
    
    // Provjera "aktivnost ikad" (zadnjih 90 dana ima bilo koji unos)
    const aktivnostQ = await pool.query(`
      SELECT s.radnik_id, MAX(s.datum) AS zadnji_dan
      FROM sihterica s
      WHERE s.datum >= NOW() - INTERVAL '90 days'
      GROUP BY s.radnik_id
    `);
    const aktivnostMap = new Map();
    for (const a of aktivnostQ.rows) {
      aktivnostMap.set(a.radnik_id, a.zadnji_dan);
    }
    
    // Sastavi response
    const radnici = satiQ.rows.map(r => {
      const zadnji = aktivnostMap.get(r.id);
      return {
        id: r.id,
        ime: r.ime + ' ' + r.prezime,
        sati: parseFloat(r.sati) || 0,
        bolovanje_sati: parseFloat(r.bolovanje_sati) || 0,
        broj_dana: parseInt(r.broj_dana) || 0,
        zadnji_dan: zadnji ? _ymd(new Date(zadnji)) : null,
      };
    });
    
    // Stats za context
    const ukupno_sati = radnici.reduce((s, r) => s + r.sati, 0);
    const radnika_radilo = radnici.filter(r => r.sati > 0).length;
    
    res.json({
      godina,
      mjesec,
      ukupno_sati,
      radnika_radilo,
      radnici, // sortirano desc by sati
    });
  } catch(e) {
    console.error('radnici-mjesec:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v501.21 (Ivan, 21.05.2026): CJENIK MATERIJALA — Sesija 1 API
//   Direktor-only edit cjenik + povijest cijena.
//   Single source of truth za sve materijal trošak izračune (v501.22+ integration).
// ═══════════════════════════════════════════════════════════════════════════

// ─── 1. PROIZVOĐAČI ─────────────────────────────────────────────────────────
// Svi (Memsur i direktor) mogu vidjeti popis za dropdown u materijal unosu.
// Samo direktor može dodati/editirati/brisati.
app.get('/api/proizvodjaci', auth, async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT id, naziv, aktivan FROM proizvodjaci WHERE aktivan = true ORDER BY naziv ASC`
    );
    res.json(r.rows);
  } catch (e) {
    console.error('GET /proizvodjaci:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/proizvodjaci', auth, direktor, async (req, res) => {
  try {
    const naziv = (req.body.naziv || '').trim();
    if (!naziv) return res.status(400).json({ error: 'Naziv je obavezan' });
    const r = await pool.query(
      `INSERT INTO proizvodjaci (naziv) VALUES ($1)
       ON CONFLICT (naziv) DO UPDATE SET aktivan = true
       RETURNING id, naziv, aktivan`,
      [naziv]
    );
    res.json(r.rows[0]);
  } catch (e) {
    console.error('POST /proizvodjaci:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.put('/api/proizvodjaci/:id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    const naziv = (req.body.naziv || '').trim();
    if (!naziv) return res.status(400).json({ error: 'Naziv je obavezan' });
    const r = await pool.query(
      `UPDATE proizvodjaci SET naziv = $1 WHERE id = $2 RETURNING id, naziv, aktivan`,
      [naziv, id]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Proizvođač ne postoji' });
    res.json(r.rows[0]);
  } catch (e) {
    console.error('PUT /proizvodjaci:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.delete('/api/proizvodjaci/:id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    // Provjeri ima li cjenik unosa s ovim proizvođačem
    const linked = await pool.query(`SELECT COUNT(*)::int AS cnt FROM cjenik WHERE proizvodjac_id = $1`, [id]);
    if (linked.rows[0].cnt > 0) {
      // Soft delete (postoje cjenik unosi)
      await pool.query(`UPDATE proizvodjaci SET aktivan = false WHERE id = $1`, [id]);
      return res.json({ ok: true, soft_delete: true, message: `Soft delete — ${linked.rows[0].cnt} proizvoda referenciraju ovog proizvođača` });
    }
    await pool.query(`DELETE FROM proizvodjaci WHERE id = $1`, [id]);
    res.json({ ok: true, soft_delete: false });
  } catch (e) {
    console.error('DELETE /proizvodjaci:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ─── 2. CJENIK — glavna lista proizvoda + cijena ────────────────────────────
// GET dostupan svima (Memsur autocomplete naziva pri unosu).
// POST/PUT/DELETE samo direktor.
app.get('/api/cjenik', auth, async (req, res) => {
  try {
    const includeInactive = req.query.svi === '1';
    
    // ⭐ v501.30 (Ivan production bug): DEFENSIVE GET
    //   Ako Ivan nije pokrenuo init-db nakon deploy-a v501.27+, kolone pod_naziv/dobavljac 
    //   neće postojati u produkciji → SELECT pada s "column c.pod_naziv does not exist".
    //   Rješenje: provjeri existence kolona u information_schema PRIJE select-a.
    //   Ako ne postoje, dodaj ih lazy (idempotent ALTER TABLE).
    
    // Lazy schema check (cached u memoriji da ne provjerava svaki put)
    if (!global._cjenikSchemaChecked) {
      try {
        const colsQ = await pool.query(`
          SELECT column_name FROM information_schema.columns 
          WHERE table_name = 'cjenik' AND column_name IN ('pod_naziv', 'dobavljac')
        `);
        const hasPod = colsQ.rows.some(r => r.column_name === 'pod_naziv');
        const hasDob = colsQ.rows.some(r => r.column_name === 'dobavljac');
        if (!hasPod || !hasDob) {
          console.warn(`[v501.30 LAZY SCHEMA] cjenik missing cols (pod_naziv=${hasPod}, dobavljac=${hasDob}) — applying ALTER`);
          await pool.query(`
            ALTER TABLE cjenik ADD COLUMN IF NOT EXISTS dobavljac TEXT DEFAULT NULL;
            ALTER TABLE cjenik ADD COLUMN IF NOT EXISTS pod_naziv TEXT DEFAULT NULL;
            CREATE INDEX IF NOT EXISTS idx_cjenik_dobavljac ON cjenik(dobavljac);
            CREATE INDEX IF NOT EXISTS idx_cjenik_pod_naziv ON cjenik(pod_naziv);
          `);
          console.log('[v501.30 LAZY SCHEMA] cjenik ALTER završen ✓');
        }
        global._cjenikSchemaChecked = true;
      } catch (schErr) {
        console.warn('[v501.30 LAZY SCHEMA] check fail:', schErr.message);
      }
    }
    
    const sql = `
      SELECT c.id, c.naziv, c.pod_naziv, c.dobavljac, c.kategorija, c.jedinica, 
             c.paleta_kolicina, c.cijena_trenutna, c.vazi_od, c.aktivan,
             c.pakiranja,
             COALESCE(c.treba_pregled, false) AS treba_pregled,
             c.proizvodjac_id, p.naziv AS proizvodjac,
             c.created_at, c.updated_at
      FROM cjenik c
      LEFT JOIN proizvodjaci p ON p.id = c.proizvodjac_id
      ORDER BY 
        c.dobavljac ASC NULLS LAST, 
        c.naziv ASC,
        c.pod_naziv ASC NULLS FIRST
    `;
    // ⭐ v502.20.30: micro-cache (30s) — cjenik se rijetko mijenja, čita na svakom unosu materijala
    const cacheKey = `cjenik:${includeInactive ? 'svi' : 'aktivni'}`;
    const cached = hotCacheGet(cacheKey);
    if (cached) return res.json(cached);

    const r = await pool.query(sql);
    hotCacheSet(cacheKey, r.rows);
    res.json(r.rows);
  } catch (e) {
    console.error('GET /cjenik:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/cjenik', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.27: dodano dobavljac + pod_naziv + eps_grafitni kategorija
    const { proizvodjac_id, dobavljac, pod_naziv, naziv, kategorija, jedinica, paleta_kolicina, cijena_trenutna, vazi_od } = req.body;
    
    if (!naziv || !String(naziv).trim()) return res.status(400).json({ error: 'Naziv proizvoda je obavezan' });
    if (!kategorija) return res.status(400).json({ error: 'Kategorija je obavezna' });
    
    // ⭐ v501.59 (Ivan QA): koristi GLOBAL CJEN_MASTER kao single source of truth
    // ⭐ v135.7.502.20.107 (Ivan): + prihvati DINAMIČKE izol kategorije (Multipor='multipor' i sl.) koje
    //   nisu u CJEN_MASTER ali jesu u IZOL_KATEGORIJE (volumenski tipovi). Inače se izolacija ne može
    //   spremiti u cjenik.
    if (!(await kategorijaDozvoljena(kategorija))) {
      return res.status(400).json({ error: `Nevažeća kategorija: ${kategorija}. Dozvoljene: ${Object.keys(CJEN_MASTER).join(', ')} (ili izolacijska kategorija)` });
    }
    
    const cijena = parseFloat(cijena_trenutna) || 0;
    // ⭐ v502.19 (Ivan, 26.05.2026): paleta default iz PAL_PER_KAT (single source of truth)
    //   PRIJE: hardcoded 1200 → mozaik/grund/super_primer/boja stavke kreirane s krivih 1200 kg.
    //   SAD: ako frontend ne pošalje paleta_kolicina, koristi PAL_PER_KAT[kategorija].
    const palKol = parseFloat(paleta_kolicina) || PAL_PER_KAT[kategorija] || 1200;
    
    // ⭐ v501.59 (Ivan QA): validacija negativnih vrijednosti
    if (cijena < 0) return res.status(400).json({ error: 'Cijena ne može biti negativna' });
    if (palKol <= 0) return res.status(400).json({ error: 'Paleta količina mora biti veća od 0' });
    
    const datum = vazi_od || danasZagreb();
    const nazivClean = String(naziv).trim();
    const podClean = (pod_naziv || '').trim().slice(0, 100) || null;
    const dobClean = (dobavljac || '').trim().slice(0, 100) || null;
    
    // Provjeri duplikat (naziv + pod_naziv + dobavljac)
    const dup = await pool.query(
      `SELECT id FROM cjenik 
       WHERE LOWER(naziv) = LOWER($1)
         AND COALESCE(LOWER(pod_naziv), '') = COALESCE(LOWER($2), '')
         AND COALESCE(LOWER(dobavljac), '') = COALESCE(LOWER($3), '')`,
      [nazivClean, podClean, dobClean]
    );
    if (dup.rows.length > 0) {
      return res.status(409).json({ error: 'Proizvod s istim nazivom + pod_naziv + dobavljač već postoji u cjeniku' });
    }
    
    // ⭐ v135.7.502.20.80 (Ivan): pakiranja JSON (uredive konverzije) — validiraj prije spremanja
    let pakiranjaJson = null;
    if (req.body.pakiranja && Array.isArray(req.body.pakiranja)) {
      const valid = req.body.pakiranja
        .map(x => {
          // ⭐ v135.7.502.20.83: čuvaj izolacijski oblik (deb_cm + m2) + obični (jed + u_osnovnoj)
          const o = { jed: String(x.jed||'').toLowerCase().trim(), u_osnovnoj: parseFloat(x.u_osnovnoj)||0 };
          if (x.deb_cm != null && parseFloat(x.deb_cm) > 0) o.deb_cm = parseFloat(x.deb_cm);
          if (x.m2 != null && parseFloat(x.m2) > 0) o.m2 = parseFloat(x.m2);
          if (x.m2_pal != null && parseFloat(x.m2_pal) > 0) o.m2_pal = parseFloat(x.m2_pal);  // ⭐ v85: m²/paleta
          return o;
        })
        .filter(x => x.jed && x.u_osnovnoj > 0);
      pakiranjaJson = valid.length ? JSON.stringify(valid) : null;
    }

    const ins = await pool.query(
      `INSERT INTO cjenik (naziv, pod_naziv, dobavljac, kategorija, jedinica, paleta_kolicina, cijena_trenutna, vazi_od, pakiranja)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING *`,
      [nazivClean, podClean, dobClean, kategorija, jedinica || 'kg', palKol, cijena, datum, pakiranjaJson]
    );
    const cjenikRow = ins.rows[0];
    
    await pool.query(
      `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, napomena, created_by_id)
       VALUES ($1, $2, $3, $4, $5)`,
      [cjenikRow.id, cijena, datum, 'Inicijalni unos', req.user?.id || null]
    );
    
    res.json(cjenikRow);
  } catch (e) {
    console.error('POST /cjenik:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.put('/api/cjenik/:id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    // ⭐ v501.55 (Ivan): aktivan parameter uklonjen — više se ne koristi (sve stavke su aktivne)
    const { proizvodjac_id, dobavljac, pod_naziv, naziv, kategorija, jedinica, paleta_kolicina, treba_pregled } = req.body;
    
    // ⭐ v501.59 (Ivan QA): validacija kategorije (prije: PUT je dopuštao bilo koji string → dirty data)
    // ⭐ v135.7.502.20.107 (Ivan): + dinamičke izol kategorije (Multipor) dozvoljene.
    if (kategorija !== undefined && kategorija !== null && !(await kategorijaDozvoljena(kategorija))) {
      return res.status(400).json({ error: `Nevažeća kategorija: ${kategorija}. Dozvoljene: ${Object.keys(CJEN_MASTER).join(', ')} (ili izolacijska kategorija)` });
    }
    
    // ⭐ v501.59 (Ivan QA): partial update logika
    //   PRIJE bug: ako frontend ne pošalje dobavljac/pod_naziv u request → PUT je postavljao na NULL (obrisao podatak).
    //   SAD: undefined → ne diraj postojeću vrijednost; null/prazan string → eksplicitno postavi NULL.
    const updateDobavljac = dobavljac !== undefined;
    const updatePodNaziv = pod_naziv !== undefined;
    const dobavljacVal = updateDobavljac ? ((dobavljac || '').trim().slice(0, 100) || null) : null;
    const podNazivVal = updatePodNaziv ? ((pod_naziv || '').trim().slice(0, 100) || null) : null;

    // ⭐ v135.7.502.20.80 (Ivan): pakiranja partial update. undefined → ne diraj; array → validiraj+spremi;
    //   null/prazan → postavi NULL (vrati na zadane konverzije).
    const updatePak = req.body.pakiranja !== undefined;
    let pakiranjaVal = null;
    if (updatePak && Array.isArray(req.body.pakiranja)) {
      const valid = req.body.pakiranja
        .map(x => {
          // ⭐ v135.7.502.20.83: čuvaj izolacijski oblik (deb_cm + m2) + obični (jed + u_osnovnoj)
          const o = { jed: String(x.jed||'').toLowerCase().trim(), u_osnovnoj: parseFloat(x.u_osnovnoj)||0 };
          if (x.deb_cm != null && parseFloat(x.deb_cm) > 0) o.deb_cm = parseFloat(x.deb_cm);
          if (x.m2 != null && parseFloat(x.m2) > 0) o.m2 = parseFloat(x.m2);
          if (x.m2_pal != null && parseFloat(x.m2_pal) > 0) o.m2_pal = parseFloat(x.m2_pal);  // ⭐ v85: m²/paleta
          return o;
        })
        .filter(x => x.jed && x.u_osnovnoj > 0);
      pakiranjaVal = valid.length ? JSON.stringify(valid) : null;
    }

    const r = await pool.query(
      `UPDATE cjenik
       SET proizvodjac_id = COALESCE($1, proizvodjac_id),
           dobavljac      = CASE WHEN $2::boolean THEN $3 ELSE dobavljac END,
           pod_naziv      = CASE WHEN $4::boolean THEN $5 ELSE pod_naziv END,
           naziv          = COALESCE($6, naziv),
           kategorija     = COALESCE($7, kategorija),
           jedinica       = COALESCE($8, jedinica),
           paleta_kolicina= COALESCE($9, paleta_kolicina),
           treba_pregled  = COALESCE($11::boolean, treba_pregled),
           pakiranja      = CASE WHEN $12::boolean THEN $13::jsonb ELSE pakiranja END,
           updated_at     = NOW()
       WHERE id = $10
       RETURNING *`,
      [proizvodjac_id ?? null,
       updateDobavljac, dobavljacVal,
       updatePodNaziv, podNazivVal,
       naziv ?? null, kategorija ?? null, jedinica ?? null,
       paleta_kolicina ?? null, id,
       (treba_pregled === undefined || treba_pregled === null) ? null : !!treba_pregled,
       updatePak, pakiranjaVal]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Proizvod ne postoji' });
    // ⭐ v135.7.502.20.111 (Ivan, 03.06.2026): #4 FIX — propagiraj novi naziv u materijal.naziv (GLAVNI
    //   prikaz u listi/exportima), NE u pod_naziv. PRIJE (v107 bug): pisalo u pod_naziv → glavni naziv
    //   ostajao star (npr "CEMENT SPECIAL NEXE" iako je cjenik "CEMENT SPECIAL"). Sad: naziv se osvježi
    //   svugdje (lista, PDF, analitika koriste m.naziv). BONUS: čisti pod_naziv ako je jednak nazivu
    //   (v107 ga je duplikatno punio → prikazivao suvišan badge).
    try {
      const noviNaziv = r.rows[0].naziv;
      if (noviNaziv && String(noviNaziv).trim()) {
        const nn = String(noviNaziv).trim();
        const upd = await pool.query(
          `UPDATE materijal SET naziv = $1 WHERE cjenik_id = $2 AND COALESCE(naziv,'') <> $1`,
          [nn, id]
        );
        // očisti pod_naziv ako je jednak nazivu (duplikat iz v107) — da se ne prikazuje suvišan badge
        await pool.query(
          `UPDATE materijal SET pod_naziv = NULL WHERE cjenik_id = $2 AND COALESCE(pod_naziv,'') = $1`,
          [nn, id]
        );
        if (upd.rowCount) console.log(`[v111 cjenik→mat] naziv "${nn}" propagiran na ${upd.rowCount} unosa (cjenik_id=${id})`);
      }
    } catch (e) { console.warn('[v111 cjenik→mat propagacija]', e.message); }
    res.json(r.rows[0]);
  } catch (e) {
    if (e.code === '23505') return res.status(409).json({ error: 'Proizvod s istim nazivom već postoji za tog dobavljača' });
    console.error('PUT /cjenik:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.50 (Ivan): DIAGNOSTIC endpoint za debug retroaktivne cijene
//   Daje kompletnu sliku jedne cjenik stavke + svih materijal unosa koji su vezani na njena
//   + svih cjenik_povijest redova + svih "slično imenovanih" duplikat stavki u cjeniku
//   (koje možda postoje kao auto-popula greška i pokupile su stare unose).
//   
//   URL: GET /api/cjenik/:id/audit
app.get('/api/cjenik/:id/audit', auth, direktor, async (req, res) => {
  try {
    const cjenikId = parseInt(req.params.id);
    
    // 1) Trenutni stanje cjenik stavke
    const cR = await pool.query(`
      SELECT id, naziv, pod_naziv, dobavljac, kategorija, jedinica, paleta_kolicina,
             cijena_trenutna, vazi_od, aktivan,
             COALESCE(treba_pregled, false) AS treba_pregled,
             created_at, updated_at
      FROM cjenik WHERE id = $1
    `, [cjenikId]);
    if (!cR.rows.length) return res.status(404).json({ error: 'Cjenik stavka ne postoji' });
    const c = cR.rows[0];
    
    // 2) Sva cjenik_povijest za tu stavku
    const povR = await pool.query(`
      SELECT id, cijena, vazi_od, vazi_do, napomena, created_at
      FROM cjenik_povijest WHERE cjenik_id = $1
      ORDER BY vazi_od ASC
    `, [cjenikId]);
    
    // 3) Svi materijal unosi vezani na ovu cjenik stavku
    const matR = await pool.query(`
      SELECT m.id, m.datum, m.naziv, m.pod_naziv, m.dobavljac, m.kolicina, m.jedinica,
             m.gradiliste_id, g.naziv AS gradiliste_naziv
      FROM materijal m
      LEFT JOIN gradilista g ON g.id = m.gradiliste_id
      WHERE m.cjenik_id = $1
      ORDER BY m.datum DESC
    `, [cjenikId]);
    
    // 4) DUPLIKATI — druge cjenik stavke sa SLIČNIM nazivom/dobavljačem
    //    (Možda postoji "SockelFlex" + "sockelflex" + "SOCKELFLEX" kao tri zapisa)
    const dupR = await pool.query(`
      SELECT id, naziv, pod_naziv, dobavljac, kategorija, cijena_trenutna, aktivan,
             COALESCE(treba_pregled, false) AS treba_pregled,
             (SELECT COUNT(*) FROM materijal WHERE cjenik_id = c.id)::int AS broj_materijal_unosa
      FROM cjenik c
      WHERE id != $1
        AND LOWER(TRIM(naziv)) = LOWER(TRIM($2))
      ORDER BY broj_materijal_unosa DESC, id ASC
    `, [cjenikId, c.naziv]);
    
    // 5) "Orphan" unosi — materijal s istim nazivom + dobavljačem ali cjenik_id NULL ili drugi
    const orphR = await pool.query(`
      SELECT cjenik_id, COUNT(*)::int AS broj_unosa,
             (SELECT cijena_trenutna FROM cjenik WHERE id = m.cjenik_id) AS cijena_te_stavke
      FROM materijal m
      WHERE LOWER(TRIM(naziv)) = LOWER(TRIM($1))
        AND COALESCE(LOWER(TRIM(dobavljac)), '') = COALESCE(LOWER(TRIM($2::text)), '')
      GROUP BY cjenik_id
      ORDER BY broj_unosa DESC
    `, [c.naziv, c.dobavljac || '']);
    
    // 6) Sample: pretvori cijenu za prvih nekoliko materijal unosa (test lookup)
    const lookupTest = matR.rows.slice(0, 5).map(m => {
      const datumStr = (typeof m.datum === 'string' ? m.datum : m.datum.toISOString()).slice(0, 10);
      let cijenaIzPovijesti = null;
      for (const p of povR.rows) {
        const odStr = (typeof p.vazi_od === 'string' ? p.vazi_od : p.vazi_od.toISOString()).slice(0, 10);
        const doStr = p.vazi_do ? (typeof p.vazi_do === 'string' ? p.vazi_do : p.vazi_do.toISOString()).slice(0, 10) : '9999-12-31';
        if (datumStr >= odStr && datumStr <= doStr) {
          cijenaIzPovijesti = parseFloat(p.cijena);
          break;
        }
      }
      return {
        materijal_id: m.id,
        datum: datumStr,
        kolicina: parseFloat(m.kolicina),
        jedinica: m.jedinica,
        cijena_iz_povijesti: cijenaIzPovijesti,
        ocekivana_cijena: parseFloat(c.cijena_trenutna)
      };
    });
    
    res.json({
      cjenik_stavka: c,
      cjenik_povijest: povR.rows.map(p => ({
        ...p,
        cijena: parseFloat(p.cijena),
        vazi_od_str: (typeof p.vazi_od === 'string' ? p.vazi_od : p.vazi_od.toISOString()).slice(0,10),
        vazi_do_str: p.vazi_do ? (typeof p.vazi_do === 'string' ? p.vazi_do : p.vazi_do.toISOString()).slice(0,10) : 'NULL (forever)'
      })),
      ukupno_povijest_redova: povR.rows.length,
      materijal_unosi: matR.rows.length,
      materijal_unosi_sample: matR.rows.slice(0, 10),
      moguci_duplikati_u_cjeniku: dupR.rows,
      svi_unosi_po_cjenik_id: orphR.rows,
      lookup_test_sample: lookupTest,
      dijagnoza: (() => {
        const issues = [];
        if (dupR.rows.length) {
          issues.push(`⚠ Postoji ${dupR.rows.length} DUPLIKATI cjenik stavki s istim nazivom — možda materijal unosi pokazuju na njih, ne na ovu stavku #${cjenikId}.`);
          for (const d of dupR.rows) {
            if (d.broj_materijal_unosa > 0) {
              issues.push(`  → Duplikat #${d.id} (cijena: ${d.cijena_trenutna} €) ima ${d.broj_materijal_unosa} materijal unosa.`);
            }
          }
        }
        if (orphR.rows.length > 1) {
          issues.push(`⚠ Materijal unosi s nazivom "${c.naziv}" raspoređeni su preko ${orphR.rows.length} različitih cjenik_id-eva → neki koriste pogrešnu cijenu.`);
        }
        if (povR.rows.length > 1) {
          issues.push(`ℹ Cjenik povijest ima ${povR.rows.length} redova — povijesna logika u igri.`);
        }
        if (!povR.rows.length) {
          issues.push(`⚠ cjenik_povijest je PRAZAN — lookup fallback-a na cjenik.cijena_trenutna.`);
        }
        if (issues.length === 0) {
          issues.push('✓ Stavka izgleda OK — cijena treba pravilno raditi za sve unose.');
        }
        return issues;
      })()
    });
  } catch (e) {
    console.error('GET /cjenik/:id/audit:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.50 (Ivan): GLOBALNO konsolidiraj duplikate cjenik stavki
//   Pronalazi sve grupe (naziv + dobavljac) gdje postoji više cjenik stavki.
//   Za svaku grupu:
//     - "kanonska" stavka = ona s najvećom cijenom (presumed: Ivan ručno editirao)
//                            ILI s najviše materijal unosa
//                            ILI najnovija (created_at DESC)
//     - sve ostale duplikate: migriraj materijal unose na kanonsku + deaktiviraj
//   POST body: { dry_run: true } = ne mijenja, samo vraća što bi promijenilo
app.post('/api/cjenik/konsolidiraj-duplikate', auth, direktor, async (req, res) => {
  try {
    const dryRun = !!req.body.dry_run;
    
    // Nađi sve grupe duplikata (≥ 2 stavke s istim naziv + dobavljac)
    const dupQ = await pool.query(`
      SELECT 
        LOWER(TRIM(naziv)) AS k_naziv, 
        LOWER(TRIM(COALESCE(dobavljac, ''))) AS k_dobavljac,
        array_agg(id ORDER BY 
          (SELECT COUNT(*) FROM materijal WHERE cjenik_id = c.id) DESC,
          (CASE WHEN COALESCE(treba_pregled, false) THEN 0 ELSE 1 END) DESC,
          cijena_trenutna DESC,
          updated_at DESC NULLS LAST,
          id DESC
        ) AS ids,
        COUNT(*)::int AS broj_stavki,
        MAX(naziv) AS prikazni_naziv,
        MAX(dobavljac) AS prikazni_dobavljac
      FROM cjenik c
      GROUP BY LOWER(TRIM(naziv)), LOWER(TRIM(COALESCE(dobavljac, '')))
      HAVING COUNT(*) > 1
    `);
    
    const akcije = [];
    let ukupnoMigrirano = 0;
    let ukupnoDeaktivirano = 0;
    
    for (const g of dupQ.rows) {
      const ids = g.ids;
      const kanonId = ids[0];  // najjača (najviše unosa / nije treba_pregled / najviša cijena)
      const duplikati = ids.slice(1);
      
      // Detalji za log
      const detR = await pool.query(`
        SELECT id, cijena_trenutna, COALESCE(treba_pregled, false) AS treba_pregled,
               (SELECT COUNT(*) FROM materijal WHERE cjenik_id = c.id)::int AS unosa
        FROM cjenik c WHERE id = ANY($1::int[])
        ORDER BY array_position($1::int[], id)
      `, [ids]);
      
      const akcija = {
        naziv: g.prikazni_naziv,
        dobavljac: g.prikazni_dobavljac,
        kanonska_stavka: detR.rows[0],
        duplikati: detR.rows.slice(1),
        unosa_za_migraciju: 0,
        plan: ''
      };
      
      if (!dryRun) {
        // Migriraj materijal unose s duplikata na kanonsku
        const migR = await pool.query(
          `UPDATE materijal SET cjenik_id = $1 WHERE cjenik_id = ANY($2::int[])`,
          [kanonId, duplikati]
        );
        akcija.unosa_za_migraciju = migR.rowCount;
        ukupnoMigrirano += migR.rowCount;
        
        // ⭐ v501.53 (Ivan): HARD DELETE duplikata (umjesto soft aktivan=false)
        await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = ANY($1::int[])`, [duplikati]);
        await pool.query(`DELETE FROM cjenik WHERE id = ANY($1::int[])`, [duplikati]);
        ukupnoDeaktivirano += duplikati.length;
        
        akcija.plan = `✓ ${migR.rowCount} unosa premješteno na #${kanonId}, ${duplikati.length} duplikata OBRISANO`;
      } else {
        const totalUnosa = detR.rows.slice(1).reduce((s, d) => s + d.unosa, 0);
        akcija.unosa_za_migraciju = totalUnosa;
        akcija.plan = `[dry_run] Bi premjestio ${totalUnosa} unosa na #${kanonId} + deaktivirao ${duplikati.length} duplikata`;
      }
      
      akcije.push(akcija);
    }
    
    res.json({
      ok: true,
      dry_run: dryRun,
      grupa_duplikata: dupQ.rows.length,
      ukupno_migrirano_unosa: ukupnoMigrirano,
      ukupno_deaktivirano_duplikata: ukupnoDeaktivirano,
      akcije,
      napomena: dryRun 
        ? '🔍 DRY RUN — ništa nije promijenjeno. Pošalji bez dry_run da izvršiš.' 
        : `✅ Konsolidirano ${dupQ.rows.length} grupa duplikata. ${ukupnoMigrirano} materijal unosa premješteno. ${ukupnoDeaktivirano} duplikata deaktivirano.`
    });
  } catch (e) {
    console.error('POST /cjenik/konsolidiraj-duplikate:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.delete('/api/cjenik/:id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    // ⭐ v135.7.502.20.117 (Ivan): dohvati kategoriju PRIJE brisanja (za povezano brisanje custom izol tipa)
    const cur = await pool.query(`SELECT kategorija FROM cjenik WHERE id = $1`, [id]);
    const katDel = cur.rows.length ? String(cur.rows[0].kategorija || '').toLowerCase().trim() : '';
    // ⭐ v501.53 (Ivan): HARD DELETE uvijek
    //   - Materijal unosi vezani na ovu stavku → cjenik_id = NULL (pojave se u Neklasificirano)
    //   - Obriši cjenik_povijest + cjenik red trajno
    //   Više nema soft delete / aktivan=false logike — Ivan radi s čistom listom.
    const used = await pool.query(`SELECT COUNT(*)::int AS cnt FROM materijal WHERE cjenik_id = $1`, [id]);
    const otvorenih = used.rows[0].cnt;
    
    if (otvorenih > 0) {
      await pool.query(`UPDATE materijal SET cjenik_id = NULL WHERE cjenik_id = $1`, [id]);
    }
    await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [id]);
    await pool.query(`DELETE FROM cjenik WHERE id = $1`, [id]);

    // ⭐ v135.7.502.20.117 (Ivan): POVEZANO BRISANJE — ako je obrisana CUSTOM izolacija (Multipor i sl.) i
    //   više nema cjenik stavki te kategorije → soft-delete i njen TIP, da NESTANE i button pri unosu.
    //   Ivan zahtjev: brisanje izolacije u cjeniku = brisanje svuda. Sistemske izol (eps/mw/xps) NE diramo.
    let tipObrisan = null;
    try {
      if (katDel && jeIzolKat(katDel) && !['eps','eps_grafitni','mw','xps'].includes(katDel)) {
        const ostatak = await pool.query(`SELECT 1 FROM cjenik WHERE LOWER(TRIM(kategorija)) = $1 LIMIT 1`, [katDel]);
        if (ostatak.rows.length === 0) {
          const tipR = await pool.query(
            `UPDATE materijal_tipovi SET aktivan = false
             WHERE obracun_volumen = true AND je_sistemski = false AND LOWER(TRIM(kategorija)) = $1 AND aktivan = true
             RETURNING naziv`, [katDel]
          );
          if (tipR.rows.length) {
            tipObrisan = tipR.rows[0].naziv;
            await pool.query(`UPDATE materijal SET cjenik_id = NULL WHERE LOWER(TRIM(COALESCE(naziv,''))) = LOWER(TRIM($1))`, [tipObrisan]);
            await osvjeziIzolKategorije();
            console.log(`[cjenik DELETE] custom izol "${tipObrisan}" (${katDel}) → tip soft-deleted (povezano brisanje)`);
          }
        }
      }
    } catch (te) { console.warn('[cjenik DELETE] povezano tip brisanje fail:', te.message); }
    
    res.json({ 
      ok: true, 
      hard_delete: true, 
      odvojeno_unosa: otvorenih,
      tip_obrisan: tipObrisan,
      message: tipObrisan
        ? `Izolacija "${tipObrisan}" obrisana iz cjenika I iz unosa (tip uklonjen).`
        : (otvorenih > 0 
          ? `Stavka obrisana. ${otvorenih} materijal unosa odvojeno (sada u Neklasificirano).`
          : 'Stavka trajno obrisana.')
    });
  } catch (e) {
    console.error('DELETE /cjenik:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ─── 3. POVIJEST CIJENA ─────────────────────────────────────────────────────
//   Direktor mijenja cijenu → automatski "zatvori" prethodni red (vazi_do = vazi_od - 1) 
//   + kreira novi (vazi_do = NULL). Cjenik.cijena_trenutna se updatira.
app.get('/api/cjenik/:id/povijest', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    const r = await pool.query(
      `SELECT id, cijena, vazi_od, vazi_do, napomena, created_at, created_by_id
       FROM cjenik_povijest 
       WHERE cjenik_id = $1 
       ORDER BY vazi_od DESC`,
      [id]
    );
    res.json(r.rows);
  } catch (e) {
    console.error('GET /cjenik/povijest:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/cjenik/:id/povijest', auth, direktor, async (req, res) => {
  try {
    const cjenikId = parseInt(req.params.id);
    const cijena = parseFloat(req.body.cijena);
    const vazi_od = req.body.vazi_od || danasZagreb();
    const napomena = (req.body.napomena || '').trim();
    
    if (!isFinite(cijena) || cijena < 0) return res.status(400).json({ error: 'Nevažeća cijena' });
    if (!vazi_od) return res.status(400).json({ error: 'Datum važenja je obavezan' });
    
    // Provjeri da cjenik postoji + dohvati treba_pregled
    const c = await pool.query(`SELECT *, COALESCE(treba_pregled, false) AS treba_pregled FROM cjenik WHERE id = $1`, [cjenikId]);
    if (!c.rows.length) return res.status(404).json({ error: 'Cjenik proizvod ne postoji' });
    
    // ⭐ v501.53 (Ivan): SUSTAV SAM odlučuje hoće li biti retroaktivno ili povijesno
    //   - treba_pregled = true (auto-kreirana s default cijenom) → RETROAKTIVNO
    //     • Brišem default cijenu iz povijesti, nova vrijedi od početka vremena
    //     • Ivan prvi put unosi pravu cijenu — ne želi da default kontaminira stare unose
    //   - treba_pregled = false (Ivan već potvrdio cijenu) → POVIJESNO
    //     • Stara cijena vrijedi do (novi datum - 1)
    //     • Nova cijena vrijedi od novog datuma
    //     • Stari unosi po staroj cijeni, novi po novoj
    const retroaktivno = !!c.rows[0].treba_pregled;
    
    // ⭐ v135.7.502.20.130 (Ivan, 04.06.2026): TRANSAKCIJA na dediciranom client-u (ne na poolu).
    //   PRIJE: pool.query('BEGIN') + pool.query(...) → svaki poziv MOŽE dobiti drugu konekciju iz
    //   poola → BEGIN/INSERT/COMMIT na različitim konekcijama = atomičnost je iluzija (stanje tx
    //   može iscuriti u druge requestove). Cijene su financijski izvor (cjenik_povijest→izracunajEur),
    //   pa transakcija MORA biti stvarno atomična. SAD: dedicirani client + finally{release()}.
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      if (retroaktivno) {
        // ── RETROAKTIVNO MOD ──
        //   Prvo: konsolidiraj eventualne duplikate (slučaj da je auto-popula stvorila više stavki)
        const c0 = c.rows[0];
        const dupR = await client.query(`
          SELECT id FROM cjenik
          WHERE id != $1
            AND LOWER(TRIM(naziv)) = LOWER(TRIM($2))
            AND COALESCE(LOWER(TRIM(dobavljac)), '') = COALESCE(LOWER(TRIM($3::text)), '')
        `, [cjenikId, c0.naziv, c0.dobavljac || '']);
        
        let migrirano = 0;
        if (dupR.rows.length > 0) {
          const dupIds = dupR.rows.map(d => d.id);
          const migR = await client.query(
            `UPDATE materijal SET cjenik_id = $1 WHERE cjenik_id = ANY($2::int[])`,
            [cjenikId, dupIds]
          );
          migrirano = migR.rowCount;
          await client.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = ANY($1::int[])`, [dupIds]);
          await client.query(`DELETE FROM cjenik WHERE id = ANY($1::int[])`, [dupIds]);
        }
        
        // Obriši cijelu povijest + ubaci novi s forever-past vazi_od
        await client.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [cjenikId]);
        const novi = await client.query(
          `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, vazi_do, napomena, created_by_id)
           VALUES ($1, $2, '1900-01-01', NULL, $3, $4)
           RETURNING *`,
          [cjenikId, cijena, napomena || `Prvi unos prave cijene${migrirano > 0 ? ` (+ konsolidirano ${dupR.rows.length} duplikata, ${migrirano} unosa)` : ''}`, req.user?.id || null]
        );
        
        // Označi da je Ivan potvrdio
        await client.query(
          `UPDATE cjenik SET cijena_trenutna = $1, vazi_od = $2, treba_pregled = false, updated_at = NOW() 
           WHERE id = $3`,
          [cijena, vazi_od, cjenikId]
        );
        
        await client.query('COMMIT');
        console.log(`[cjenik/povijest v501.53] AUTO-retroaktivno #${cjenikId}: cijena ${cijena}${migrirano > 0 ? `, konsolidirano ${dupR.rows.length} duplikata (${migrirano} unosa)` : ''}`);
        return res.json({ 
          ...novi.rows[0], 
          mode: 'retroaktivno',
          konsolidirano_duplikata: dupR.rows.length,
          migrirano_unosa: migrirano
        });
      }
      
      // ── POVIJESNI MOD (default kad treba_pregled = false) ──
      
      // Obriši redove s istim datumom (izbjeg duplikate)
      await client.query(
        `DELETE FROM cjenik_povijest WHERE cjenik_id = $1 AND vazi_od = $2::date`,
        [cjenikId, vazi_od]
      );
      
      // Zatvori postojeće redove koji preklapaju s novim datumom
      await client.query(
        `UPDATE cjenik_povijest 
         SET vazi_do = ($1::date - INTERVAL '1 day')::date
         WHERE cjenik_id = $2 
           AND vazi_od < $1::date
           AND (vazi_do IS NULL OR vazi_do >= $1::date)`,
        [vazi_od, cjenikId]
      );
      
      // Ako postoji red s vazi_od > novi_od, ograniči novi vazi_do
      const kasniji = await client.query(
        `SELECT MIN(vazi_od) AS prvi_kasniji FROM cjenik_povijest 
         WHERE cjenik_id = $1 AND vazi_od > $2::date`,
        [cjenikId, vazi_od]
      );
      let novi_vazi_do = null;
      if (kasniji.rows[0]?.prvi_kasniji) {
        const k = kasniji.rows[0].prvi_kasniji;
        const kDate = new Date(k);
        kDate.setDate(kDate.getDate() - 1);
        novi_vazi_do = _ymd(kDate);
      }
      
      // Ubaci novi red
      const novi = await client.query(
        `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, vazi_do, napomena, created_by_id)
         VALUES ($1, $2, $3, $4, $5, $6)
         RETURNING *`,
        [cjenikId, cijena, vazi_od, novi_vazi_do, napomena, req.user?.id || null]
      );
      
      // Update cjenik.cijena_trenutna na najnoviju
      const najnoviji = await client.query(
        `SELECT cijena, vazi_od FROM cjenik_povijest 
         WHERE cjenik_id = $1 
         ORDER BY vazi_od DESC, created_at DESC, id DESC LIMIT 1`,
        [cjenikId]
      );
      if (najnoviji.rows.length) {
        await client.query(
          `UPDATE cjenik SET cijena_trenutna = $1, vazi_od = $2, updated_at = NOW() WHERE id = $3`,
          [najnoviji.rows[0].cijena, najnoviji.rows[0].vazi_od, cjenikId]
        );
      }
      
      await client.query('COMMIT');
      
      // ⭐ v501.59 (Ivan QA): Resync povijesti — garantira da nema rupa i zatvorenih krajeva
      await _resyncCjenikPovijest(cjenikId);
      
      console.log(`[cjenik/povijest v501.53] POVIJESNO #${cjenikId}: cijena ${cijena} od ${vazi_od}`);
      res.json({ ...novi.rows[0], mode: 'povijesno' });
    } catch (txErr) {
      await client.query('ROLLBACK').catch(()=>{});
      throw txErr;
    } finally {
      client.release();
    }
  } catch (e) {
    console.error('POST /cjenik/povijest:', e.message);
    res.status(500).json({ error: e.message });
  }
});
// PUT — izmjena postojećeg reda u povijesti (retroaktivna promjena cijene/datuma)
app.put('/api/cjenik/povijest/:povijest_id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.povijest_id);
    const { cijena, vazi_od, vazi_do, napomena } = req.body;
    
    // ⭐ v501.59 (Ivan QA): vazi_do može biti:
    //   - undefined (frontend nije poslao) → NE diraj postojeću vrijednost
    //   - null (eksplicitno nuluj) → set NULL (otvori red)
    //   - string datum → set tu vrijednost
    const updateVaziDo = vazi_do !== undefined;
    
    const r = await pool.query(
      `UPDATE cjenik_povijest
       SET cijena    = COALESCE($1, cijena),
           vazi_od   = COALESCE($2, vazi_od),
           vazi_do   = CASE WHEN $3::boolean THEN $4::date ELSE vazi_do END,
           napomena  = COALESCE($5, napomena)
       WHERE id = $6
       RETURNING *`,
      [cijena ?? null, vazi_od ?? null, updateVaziDo, vazi_do ?? null, napomena ?? null, id]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Red povijesti ne postoji' });
    
    // ⭐ v501.59 (Ivan QA): KOMPLETAN RESYNC povijesti — drži konzistentnost
    //   1. Sortiraj sve redove po datumu
    //   2. Postavi vazi_do = (sljedeći.vazi_od - 1) za svaki osim posljednjeg
    //   3. Posljednji red ima vazi_do = NULL (otvoreni)
    //   4. Update cjenik.cijena_trenutna na zadnji red
    const cjenikId = r.rows[0].cjenik_id;
    await _resyncCjenikPovijest(cjenikId);
    
    res.json(r.rows[0]);
  } catch (e) {
    console.error('PUT /cjenik/povijest:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.delete('/api/cjenik/povijest/:povijest_id', auth, direktor, async (req, res) => {
  try {
    const id = parseInt(req.params.povijest_id);
    
    // Dohvati cjenik_id prije brisanja za resync
    const exists = await pool.query(`SELECT cjenik_id FROM cjenik_povijest WHERE id = $1`, [id]);
    if (!exists.rows.length) return res.status(404).json({ error: 'Red povijesti ne postoji' });
    const cjenikId = exists.rows[0].cjenik_id;
    
    // ⭐ v501.59 (Ivan QA): provjeri da nije zadnji red (cjenik bez cijene = corrupt)
    const cnt = await pool.query(`SELECT COUNT(*)::int AS n FROM cjenik_povijest WHERE cjenik_id = $1`, [cjenikId]);
    if (cnt.rows[0].n <= 1) {
      return res.status(400).json({ 
        error: 'Ne možeš obrisati jedini povijesni red. Cjenik stavka mora imati barem jednu cijenu. Obriši cijelu stavku ili dodaj novu cijenu prvo.' 
      });
    }
    
    await pool.query(`DELETE FROM cjenik_povijest WHERE id = $1`, [id]);
    
    // Kompletan resync (postavi vazi_do prethodnog reda ako je obrisan zadnji)
    await _resyncCjenikPovijest(cjenikId);
    
    res.json({ ok: true });
  } catch (e) {
    console.error('DELETE /cjenik/povijest:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.59 (Ivan QA): Helper za KOMPLETAN resync povijesti jedne cjenik stavke
//   Resortira sve redove po vazi_od, postavi vazi_do = (sljedeći.vazi_od - 1) osim za zadnji.
//   Zadnji red ima vazi_do = NULL (otvoreni). Update cjenik.cijena_trenutna na zadnji red.
//   Garantira: nikad nema "rupa" u povijesti, nikad nema 2 paralelna otvorena reda, 
//   cjenik.cijena_trenutna uvijek match-a zadnji povijesni red.
async function _resyncCjenikPovijest(cjenikId) {
  try {
    const rows = await pool.query(
      `SELECT id, cijena, vazi_od FROM cjenik_povijest 
       WHERE cjenik_id = $1 ORDER BY vazi_od ASC, id ASC`,
      [cjenikId]
    );
    if (rows.rows.length === 0) return;
    
    for (let i = 0; i < rows.rows.length; i++) {
      const r = rows.rows[i];
      const next = rows.rows[i + 1];
      if (next) {
        // Zatvori s sljedeći datum - 1
        await pool.query(
          `UPDATE cjenik_povijest SET vazi_do = ($1::date - INTERVAL '1 day')::date WHERE id = $2`,
          [next.vazi_od, r.id]
        );
      } else {
        // Posljednji red — otvoreni
        await pool.query(`UPDATE cjenik_povijest SET vazi_do = NULL WHERE id = $1`, [r.id]);
      }
    }
    
    // Update cjenik.cijena_trenutna na ZADNJI red
    const zadnji = rows.rows[rows.rows.length - 1];
    await pool.query(
      `UPDATE cjenik SET cijena_trenutna = $1, vazi_od = $2, updated_at = NOW() WHERE id = $3`,
      [zadnji.cijena, zadnji.vazi_od, cjenikId]
    );
  } catch (e) {
    console.warn(`[_resyncCjenikPovijest #${cjenikId}] fail:`, e.message);
  }
}

// ─── 4. NEKLASIFICIRANI MATERIJALI ──────────────────────────────────────────
// Vraća listu materijal unosa koji nemaju cjenik_id (nije moguće izračunati trošak).
// Direktor klikne, vidi popis, dodaje u cjenik → automatski se re-klasificiraju.
app.get('/api/cjenik/neklasificirani', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.45 (Ivan): Vraćamo 2 kategorije:
    //   A) materijal unose bez cjenik_id (legacy)
    //   B) cjenik stavke s treba_pregled=true (auto-kreirane s default cijenom)
    
    // A) Materijal unosi bez cjenik_id
    const aQ = await pool.query(`
      SELECT m.naziv, m.pod_naziv, m.dobavljac,
             COUNT(*)::int AS broj_unosa,
             MAX(m.datum) AS zadnji_unos,
             MIN(m.datum) AS prvi_unos,
             NULL::int AS cjenik_id,
             NULL::numeric AS cijena_trenutna,
             NULL::text AS jedinica,
             NULL::text AS kategorija
      FROM materijal m
      WHERE m.cjenik_id IS NULL
      GROUP BY m.naziv, m.pod_naziv, m.dobavljac
    `);
    
    // B) Cjenik stavke s treba_pregled=true
    const bQ = await pool.query(`
      SELECT c.naziv, NULL::text AS pod_naziv, c.dobavljac,
             COALESCE((
               SELECT COUNT(*)::int FROM materijal WHERE cjenik_id = c.id
             ), 0) AS broj_unosa,
             (SELECT MAX(datum) FROM materijal WHERE cjenik_id = c.id) AS zadnji_unos,
             (SELECT MIN(datum) FROM materijal WHERE cjenik_id = c.id) AS prvi_unos,
             c.id AS cjenik_id,
             c.cijena_trenutna,
             c.jedinica,
             c.kategorija
      FROM cjenik c
      WHERE COALESCE(c.treba_pregled, false) = true
    `);
    
    // Merge: sve A unose + B stavke
    const merged = [...aQ.rows, ...bQ.rows].sort((x, y) => 
      (y.broj_unosa || 0) - (x.broj_unosa || 0)
    );
    
    res.json(merged.slice(0, 200));
  } catch (e) {
    console.error('GET /cjenik/neklasificirani:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.44 (Ivan): Spoji neklasificirane materijal unose s postojećom cjenik stavkom
//   Body: { cjenik_id, naziv, dobavljac, pod_naziv (optional) }
//   Linka sve materijal unose koji match-aju (naziv + dobavljac + pod_naziv) i cjenik_id IS NULL.
app.post('/api/cjenik/spoji-neklas', auth, direktor, async (req, res) => {
  try {
    const { cjenik_id, naziv, dobavljac, pod_naziv } = req.body;
    const cjenikId = parseInt(cjenik_id);
    if (!cjenikId) return res.status(400).json({ error: 'cjenik_id je obavezan' });
    if (!naziv) return res.status(400).json({ error: 'naziv je obavezan' });
    
    // Provjeri da cjenik stavka postoji
    const c = await pool.query(`SELECT id FROM cjenik WHERE id = $1`, [cjenikId]);
    if (!c.rows.length) return res.status(404).json({ error: 'Cjenik stavka ne postoji ili je deaktivirana' });
    
    // Build WHERE clause — uvijek match po naziv. Dobavljac i pod_naziv match-aju i NULL slučaj.
    const params = [cjenikId, naziv];
    let where = `cjenik_id IS NULL AND LOWER(TRIM(naziv)) = LOWER(TRIM($2))`;
    
    if (dobavljac && dobavljac.trim()) {
      params.push(dobavljac.trim());
      where += ` AND LOWER(TRIM(COALESCE(dobavljac,''))) = LOWER(TRIM($${params.length}))`;
    } else {
      where += ` AND (dobavljac IS NULL OR TRIM(dobavljac) = '')`;
    }
    
    if (pod_naziv && pod_naziv.trim()) {
      params.push(pod_naziv.trim());
      where += ` AND LOWER(TRIM(COALESCE(pod_naziv,''))) = LOWER(TRIM($${params.length}))`;
    } else {
      where += ` AND (pod_naziv IS NULL OR TRIM(pod_naziv) = '')`;
    }
    
    const upR = await pool.query(`UPDATE materijal SET cjenik_id = $1 WHERE ${where}`, params);
    
    console.log(`[v501.44 spoji-neklas] ${upR.rowCount} materijal unosa linkano na cjenik #${cjenikId} (naziv=${naziv}, dobavljac=${dobavljac}, pod_naziv=${pod_naziv})`);
    res.json({ ok: true, linkano: upR.rowCount });
  } catch (e) {
    console.error('POST /cjenik/spoji-neklas:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ─── 5. POMOĆNI: cijena koja je važila na specifični datum ────────────────
//   Koristi se za prikaz povijesnih cijena u analizama (v501.22 integration).
//   Vraća cijenu koja je važila datuma X za cjenik_id Y.
app.get('/api/cjenik/:id/cijena-na-datum', auth, async (req, res) => {
  try {
    const cjenikId = parseInt(req.params.id);
    const datum = req.query.datum;
    if (!datum) return res.status(400).json({ error: 'Datum je obavezan' });
    
    const r = await pool.query(
      `SELECT cijena, vazi_od, vazi_do
       FROM cjenik_povijest
       WHERE cjenik_id = $1
         AND vazi_od <= $2::date
         AND (vazi_do IS NULL OR vazi_do >= $2::date)
       ORDER BY vazi_od DESC
       LIMIT 1`,
      [cjenikId, datum]
    );
    
    if (!r.rows.length) {
      // Fallback na trenutnu cijenu iz cjenika
      const c = await pool.query(`SELECT cijena_trenutna AS cijena FROM cjenik WHERE id = $1`, [cjenikId]);
      if (c.rows.length) return res.json({ cijena: c.rows[0].cijena, izvor: 'trenutna_fallback' });
      return res.status(404).json({ error: 'Nema cijene za taj datum' });
    }
    
    res.json({ cijena: r.rows[0].cijena, vazi_od: r.rows[0].vazi_od, vazi_do: r.rows[0].vazi_do, izvor: 'povijest' });
  } catch (e) {
    console.error('GET /cjenik/cijena-na-datum:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.23 (Ivan, 21.05.2026): MIGRACIJA POSTOJEĆIH MATERIJAL UNOSA → cjenik_id
//   Endpoint čita SVE materijal unose bez cjenik_id, klasificira preko regex-a 
//   i pokušava match-ati s DB cjenikom (po proizvođaču + nazivu).
//   Ako match → postavi cjenik_id.
//   Direktor only. Idempotent (može se pokrenuti više puta).
app.post('/api/cjenik/migracija', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.29: Učitaj DB cjenik s dobavljačima (od v501.27 schema)
    //   COALESCE za backwards compat s legacy proizvodjac_id zapisima
    const cjQ = await pool.query(`
      SELECT c.id, c.naziv, c.pod_naziv, c.kategorija, 
             COALESCE(c.dobavljac, p.naziv) AS dobavljac_eff
      FROM cjenik c
      LEFT JOIN proizvodjaci p ON p.id = c.proizvodjac_id
      WHERE COALESCE(c.aktivan, true) = true
    `);
    
    // Indeksiraj cjenik za brzi lookup
    const byKatGeneric = new Map();   // kategorija → generički proizvod (bez dobavljača)
    const byProizvNaziv = [];          // [{ cjenikId, dobavljac (lc), cjenikNaziv (lc), kategorija }, ...]
    
    for (const c of cjQ.rows) {
      if (!c.dobavljac_eff) {
        // Generički — fallback po kategoriji
        if (!byKatGeneric.has(c.kategorija)) byKatGeneric.set(c.kategorija, c.id);
      } else {
        byProizvNaziv.push({
          cjenikId: c.id,
          cjenikNaziv: (c.naziv || '').toLowerCase(),
          proizvNaziv: (c.dobavljac_eff || '').toLowerCase(),
          kategorija: c.kategorija
        });
      }
    }
    
    // ⭐ v501.59 (Ivan): koristi GLOBAL klasificirajMaterijal (single source of truth)
    const klasificiraj = klasificirajMaterijal;
    
    // Match unos s DB cjenik
    // ⭐ v501.25 (Ivan): popravljena logika — najprecizniji match, ne prvi.
    //   Prije: prvi pogodak je pobjeđivao → mogao je biti slabiji od kasnijeg.
    //   Sad: scoring sustav, najveći score wins.
    const matchCjenik = (naziv, dobavljac) => {
      const n = (naziv || '').toLowerCase().trim();
      const d = (dobavljac || '').toLowerCase().trim();
      
      if (!n) return null;
      
      // Sakupimo SVE kandidate s score-om, vratimo najveći
      const kandidati = [];  // [{ id, score }]
      
      for (const c of byProizvNaziv) {
        let score = 0;
        
        // Točan substring match na naziv proizvoda (Roefix 866 ⊆ "Roefix 866 paleta")
        if (n.includes(c.cjenikNaziv)) {
          score += 100 + c.cjenikNaziv.length;  // duži match = bolji
        }
        
        // Match na proizvođača (ako se dobavljač podudara)
        if (d && c.proizvNaziv === d) {
          score += 50;
        }
        
        // Match na ključne riječi (npr. "866" u nazivu)
        const cijeli_naziv_rijeci = c.cjenikNaziv.split(/\s+/);
        for (const rijec of cijeli_naziv_rijeci) {
          if (rijec.length >= 3 && n.includes(rijec)) {
            score += 5 + rijec.length;
          }
        }
        
        if (score > 0) {
          kandidati.push({ id: c.cjenikId, score, kategorija: c.kategorija });
        }
      }
      
      if (kandidati.length > 0) {
        // Sortiraj po score desc, vrati najveći
        kandidati.sort((a, b) => b.score - a.score);
        return kandidati[0].id;
      }
      
      // Fallback: kategorija → generički proizvod
      const kat = klasificiraj(naziv);
      if (byKatGeneric.has(kat)) {
        return byKatGeneric.get(kat);
      }
      
      return null;
    };
    
    // Dohvati sve unose bez cjenik_id
    const matQ = await pool.query(`
      SELECT id, naziv, dobavljac FROM materijal WHERE cjenik_id IS NULL
    `);
    
    let updated = 0;
    let notFound = 0;
    
    // Batch update u transakciji
    // ⭐ v135.7.502.20.130 (Ivan, 04.06.2026): transakcija na dediciranom client-u (ne pool) —
    //   pool.query('BEGIN')+pool.query(...) ne garantira istu konekciju → atomičnost je iluzija.
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      for (const m of matQ.rows) {
        const cjenikId = matchCjenik(m.naziv, m.dobavljac);
        if (cjenikId) {
          await client.query(`UPDATE materijal SET cjenik_id = $1 WHERE id = $2`, [cjenikId, m.id]);
          updated++;
        } else {
          notFound++;
        }
      }
      await client.query('COMMIT');
    } catch (txErr) {
      await client.query('ROLLBACK').catch(()=>{});
      throw txErr;
    } finally {
      client.release();
    }
    
    console.log(`[v501.23 migracija] ${updated} unosa povezano s cjenikom, ${notFound} neklasificirano`);
    res.json({ ok: true, total: matQ.rows.length, updated, neklasificirano: notFound });
  } catch (e) {
    console.error('[v501.23 migracija]:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.27 (Ivan): BULK AUTO-POPULATE CJENIK iz svih postojećih materijal unosa
//   Prolazi sve materijal unose, za svaki uniqe (naziv + pod_naziv + dobavljac) trio:
//   - Ako postoji u cjeniku → linka materijal.cjenik_id
//   - Ako ne postoji → kreira stavku s cijena 0 + povezuje
//   Idempotent — možeš pokrenuti više puta sigurno.
app.post('/api/cjenik/auto-popula-from-materijal', auth, direktor, async (req, res) => {
  try {
    // ⭐ v501.59 (Ivan): koristi top-level klasificirajMaterijal (single source of truth)
    //   Stari mini-klasifikator nije pokrivao: roefix_866, super_primer, pur_pjena, mozaik, 
    //   silikat/silikon, kalibrirane podlozne (vapnen/spritz/š?pric) — sve to padalo u "ostalo".
    const klasificiraj = klasificirajMaterijal;
    
    // Dohvati sve unique trios (naziv + pod_naziv + dobavljac) iz materijal tablice
    const unique = await pool.query(`
      SELECT DISTINCT 
        TRIM(naziv) AS naziv,
        NULLIF(TRIM(COALESCE(pod_naziv, '')), '') AS pod_naziv,
        NULLIF(TRIM(COALESCE(dobavljac, '')), '') AS dobavljac,
        jedinica
      FROM materijal
      WHERE naziv IS NOT NULL AND TRIM(naziv) != ''
    `);
    
    let kreiran = 0, postojaoVec = 0, linked = 0;
    
    // ⭐ v135.7.502.20.130 (Ivan, 04.06.2026): transakcija na dediciranom client-u (ne pool) —
    //   pool.query('BEGIN')+pool.query(...) ne garantira istu konekciju → atomičnost je iluzija.
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      for (const u of unique.rows) {
        // ⭐ v501.52 (Ivan): Provjeri postoji li AKTIVNA stavka (ne match-a deaktivirane duplikate)
        const existing = await client.query(
          `SELECT id FROM cjenik 
           WHERE LOWER(naziv) = LOWER($1)
             AND COALESCE(LOWER(pod_naziv), '') = COALESCE(LOWER($2), '')
             AND COALESCE(LOWER(dobavljac), '') = COALESCE(LOWER($3), '')`,
          [u.naziv, u.pod_naziv, u.dobavljac]
        );
        
        let cjenikId;
        if (existing.rows.length > 0) {
          cjenikId = existing.rows[0].id;
          postojaoVec++;
        } else {
          const kat = klasificiraj(u.naziv);
          // ⭐ v501.35/59 (Ivan): jedinica per KATEGORIJA — sad iz GLOBAL JED_PER_KAT (single source)
          const defJed = JED_PER_KAT[kat] || 'kg';
          const defPal = PAL_PER_KAT[kat] || 1200;
          
          const insC = await client.query(
            `INSERT INTO cjenik (naziv, pod_naziv, dobavljac, kategorija, jedinica, paleta_kolicina, cijena_trenutna, vazi_od)
             VALUES ($1, $2, $3, $4, $5, $6, 0, (now() AT TIME ZONE $$Europe/Zagreb$$)::date)
             RETURNING id`,
            [u.naziv, u.pod_naziv, u.dobavljac, kat, defJed, defPal]
          );
          cjenikId = insC.rows[0].id;
          await client.query(
            `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, napomena)
             VALUES ($1, 0, (now() AT TIME ZONE $$Europe/Zagreb$$)::date, 'Auto-popula iz materijal unosa')`,
            [cjenikId]
          );
          kreiran++;
        }
        
        // Linkaj sve materijal unose s tim triom
        const upd = await client.query(
          `UPDATE materijal SET cjenik_id = $1
           WHERE LOWER(TRIM(naziv)) = LOWER($2)
             AND COALESCE(LOWER(TRIM(COALESCE(pod_naziv, ''))), '') = COALESCE(LOWER($3), '')
             AND COALESCE(LOWER(TRIM(COALESCE(dobavljac, ''))), '') = COALESCE(LOWER($4), '')
             AND (cjenik_id IS NULL OR cjenik_id != $1)`,
          [cjenikId, u.naziv, u.pod_naziv, u.dobavljac]
        );
        linked += upd.rowCount;
      }
      await client.query('COMMIT');
    } catch (txErr) {
      await client.query('ROLLBACK').catch(()=>{});
      throw txErr;
    } finally {
      client.release();
    }
    
    console.log(`[v501.27 auto-popula] ${kreiran} novih, ${postojaoVec} postojalo, ${linked} unosa linkano`);
    res.json({ 
      ok: true, 
      unique_triplets: unique.rows.length,
      kreiran, 
      postojao_vec: postojaoVec,
      linked
    });
  } catch (e) {
    console.error('[v501.27 auto-popula]:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.30 (Ivan): POPUNI CIJENE — smart suggester za stavke s cijenom 0
//   Strategija (po prioritetu):
//   1. Ako postoji druga cjenik stavka istog dobavljača + iste kategorije s cijenom > 0
//      → uzmi PROSJEK njegovih cijena (lokalna kalibracija)
//   2. Inače default po kategoriji (Hr market 2026, ovo su moje educated guesses)
//   3. Ivan može OVERWRITE bilo koju stavku ručno kasnije
//   
//   IDEMPOTENT: Ne dira stavke s cijena > 0 (samo nule).
//   POVIJEST: svaka promjena dobi red u cjenik_povijest s napomenom "Auto-popuni cijena (default/iz dobavljača X)".
//   v501.32: PLUS osigurava da postoje 4 GENERIC IZOLACIJSKE stavke (EPS, EPS Grafitni, MW, XPS)
//             koje pokrivaju cijelu kategoriju neovisno o dobavljaču.
// ⭐ v501.45 (Ivan): MODULE-LEVEL default cijene per kategorija (Hr market 2026)
//   Koristi se i u auto-populi pri POST /api/materijal (Memsur unosi novi materijal)
//   i u /api/cjenik/popuni-cijene (orphan endpoint, ostavljen za sigurnost)
//   Ako Ivan misli da nije OK — overwrite ručno u Cjenik UI-u
// ⭐ v501.59 QA (Ivan): KOMPLETNO — sve kategorije iz CJEN_MASTER imaju default cijenu
//   Razlog: prije su 3 kategorije nedostajale (roefix_866, mozaik, pur_pjena) → auto-popula
//   je za njih davala 0 € (jer fallback `|| 0`). Ivan je morao ručno ispravljati svaki put.
// ⭐ v135.7.502.20.96 (Ivan, 03.06.2026): SINGLE SOURCE praškastih kategorija. PRIJE: 5 kopija liste,
//   2 su imale renoplus/podlozna/zbuka_generalno a 3 nisu → nekonzistentan kom→25kg obračun (glavni
//   vs raspis). SAD: jedna globalna lista, sve funkcije je koriste. 'kom'=vreća 25kg za ove kategorije.
const PRASKASTE_KATEGORIJE = ['zbuka','zbuka_generalno','ljepilo','cement','zavrsna_zbuka','fina_zbuka','podlozna_zbuka','mozaik','glet','estrih','renoplus'];

// ⭐ v135.7.502.20.106 (Ivan): DINAMIČKE izolacijske kategorije. PRIJE: hardkod ['eps','eps_grafitni',
//   'xps','mw'] na 6 mjesta → nova izolacija (Multipor) sa svojom kategorijom NIJE prepoznata kao
//   volumenska → nema debljine/m³. SAD: set se puni iz tipova s obracun_volumen=true (single source).
//   Sinkroni includes ostaje (lista je modul-global), osvježava se pri startupu i promjeni tipova.
//   Sigurnosne 4 su uvijek unutra (deployment-safe ako baza prazna).
let IZOL_KATEGORIJE = new Set(['eps','eps_grafitni','xps','mw']);
async function osvjeziIzolKategorije() {
  try {
    const r = await pool.query(`SELECT DISTINCT kategorija FROM materijal_tipovi WHERE obracun_volumen = true AND kategorija IS NOT NULL AND TRIM(kategorija) <> ''`);
    const set = new Set(['eps','eps_grafitni','xps','mw']);  // sigurnosna mreža
    for (const row of r.rows) set.add(String(row.kategorija).toLowerCase().trim());
    IZOL_KATEGORIJE = set;
    console.log(`[v106 IZOL] izolacijske kategorije: ${[...set].join(', ')}`);
  } catch (e) { console.warn('[v106 IZOL] osvježavanje fail:', e.message); }
}
const jeIzolKat = (kat) => IZOL_KATEGORIJE.has(String(kat || '').toLowerCase().trim());

// ⭐ v135.7.502.20.114 (Ivan, 03.06.2026): SAMO-ISCJELJUJUĆA provjera kategorije za cjenik.
//   PROBLEM: spremanje izolacije Multipor (kategorija='multipor') vraćalo "Nevažeća kategorija: multipor"
//   jer in-memory IZOL_KATEGORIJE set nije sadržavao 'multipor' (osvježava se pri init/CRUD tipova — ako
//   korisnik nije pokrenuo init nakon kreiranja tipa, set ima samo 4 defaulta). Posljedica: tablica
//   debljina (bale) se NIKAD ne spremi → "nema podataka za bale" iako ih korisnik vidi u dialogu.
//   FIX: ako kategorija nije odmah prepoznata → OSVJEŽI set iz baze (pokupi nove volumenske tipove) pa
//   provjeri ponovno; ako i dalje ne → provjeri DB direktno (kategorija BILO KOJEG tipa). Samo-iscjeljuje.
async function kategorijaDozvoljena(kategorija) {
  const k = String(kategorija || '').toLowerCase().trim();
  if (!k) return false;
  if (CJEN_MASTER[kategorija] || jeIzolKat(k)) return true;
  try {
    await osvjeziIzolKategorije();          // pokupi novokreirane volumenske tipove (Multipor...)
    if (jeIzolKat(k)) return true;
    const tk = await pool.query(            // ili bilo koja kategorija postojećeg tipa (custom ne-volumenski)
      `SELECT 1 FROM materijal_tipovi WHERE LOWER(TRIM(kategorija)) = $1 LIMIT 1`, [k]
    );
    return tk.rows.length > 0;
  } catch (_) { return false; }
}

