  // Ljepila + grundovi
  'ljepilo':           0.44,   // EPS-Kleber / StarContact / 186M Easy
  'grund':             1.90,   // grund pred boju/žbuku
  'super_primer':      4.50,   // super primer
  // Mrežice + kutnici + sitno
  'mrezica':           0.82,   // €/m² standardna 160g
  'kutnik':            3.50,   // €/kom APU/okapnice
  'tiple':             0.38,   // €/kom 9×130
