// ⭐ Cjenik popuni-cijene endpoint (legacy, ostavljen za sigurnost — UI ga više ne poziva)
app.post('/api/cjenik/popuni-cijene', auth, direktor, async (req, res) => {
  try {
    const DEFAULT_CIJENE = KATEGORIJA_DEFAULT_CIJENE;
    
    // ⭐ v501.32: KORAK 0 — osiguraj 4 GENERIC IZOLACIJSKE stavke
    //   Princip: za EPS/EPS Grafitni/MW/XPS nema potrebe za posebnim nazivima/dobavljačima
    //   jer cijena se u suštini ne razlikuje — sve EPS = ~40 €/m³.
    //   Stavke se kreiraju s dobavljac=NULL, pod_naziv=NULL kao "kategorija-level" cijena.
    //   Naziv = "EPS (generalno)", "MW (generalno)" itd.
    const GENERIC_IZOLACIJE = [
      { naziv: 'EPS (generalno)',          kat: 'eps',          cijena: 40 },
      { naziv: 'EPS Grafitni (generalno)', kat: 'eps_grafitni', cijena: 60 },
      { naziv: 'XPS (generalno)',          kat: 'xps',          cijena: 100 }
    ];
    
    let kreiraneGeneric = 0;
    for (const g of GENERIC_IZOLACIJE) {
      // ⭐ v135.7.502.20.73 (Ivan, 02.06.2026): provjera po KATEGORIJI, ne nazivu.
      //   PRIJE: provjeravalo se po nazivu ("EPS (generalno)") → ako je već postojao "EPS" (drugi
      //   naziv, ista kat 'eps'), svejedno se kreirao "EPS (generalno)" → DUPLIKAT. SAD: ako kategorija
      //   već ima BILO KOJU generic stavku (bez dobavljača/pod_naziva), ne kreiraj novu.
      const exQ = await pool.query(
        `SELECT id FROM cjenik 
         WHERE kategorija = $1
           AND COALESCE(dobavljac, '') = ''
           AND COALESCE(pod_naziv, '') = ''`,
        [g.kat]
      );
      if (exQ.rows.length === 0) {
        const insQ = await pool.query(
          `INSERT INTO cjenik (naziv, pod_naziv, dobavljac, kategorija, jedinica, paleta_kolicina, cijena_trenutna, vazi_od)
           VALUES ($1, NULL, NULL, $2, 'm³', 1, $3, (now() AT TIME ZONE $$Europe/Zagreb$$)::date)
           RETURNING id`,
          [g.naziv, g.kat, g.cijena]
        );
        const cjenikId = insQ.rows[0].id;
        await pool.query(
          `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, napomena, created_by_id)
           VALUES ($1, $2, (now() AT TIME ZONE $$Europe/Zagreb$$)::date, $3, $4)`,
          [cjenikId, g.cijena, `Generic kategorija cijena (Hr market 2026)`, req.user?.id || null]
        );
        kreiraneGeneric++;
      }
    }
    
    // ⭐ v501.35: KORAK 0.5 — popravi jedinice za SVE postojeće stavke (ne samo izolacije)
    //   Bug: stare stavke su naslijedile jedinicu iz materijal unosa ("kom" = vreće)
    //   ali cjenik treba baznu jedinicu (Ljepilo/Žbuka/Boja = kg, Mrežica = m², itd.)
    // ⭐ v502.19 (Ivan, 26.05.2026): paleta_kolicina po stvarnim pakiranjima
    //   - mozaik / grund / super_primer / boja → paleta = 600 kg (kante 20-25kg × 24-30 kanti)
    //   - žbuke ostale (zavrsna, fina, podlozna, roefix866, renoplus, zbuka_gen) → 1200 kg default
    //     (Ivan može ručno u cjeniku staviti 800 za baumit završne)
    //   - ljepilo → 1200 kg
    let jedFixed = 0;
    const jedFix = await pool.query(`
      UPDATE cjenik SET 
        jedinica = CASE
          WHEN kategorija IN ('eps','eps_grafitni','mw','xps') THEN 'm³'
          WHEN kategorija = 'mrezica' THEN 'm²'
          WHEN kategorija IN ('kutnik','tiple','pur_pjena') THEN 'kom'
          ELSE 'kg'
        END,
        paleta_kolicina = CASE
          WHEN kategorija IN ('eps','eps_grafitni','mw','xps') THEN 1
          WHEN kategorija = 'mrezica' THEN 1800
          WHEN kategorija = 'kutnik' THEN 1500
          WHEN kategorija = 'tiple' THEN 5000
          WHEN kategorija = 'pur_pjena' THEN 600
          WHEN kategorija IN ('mozaik','grund','super_primer','boja') THEN 600
          ELSE 1200
        END,
        updated_at = NOW()
      WHERE jedinica IS DISTINCT FROM (
        CASE
          WHEN kategorija IN ('eps','eps_grafitni','mw','xps') THEN 'm³'
          WHEN kategorija = 'mrezica' THEN 'm²'
          WHEN kategorija IN ('kutnik','tiple','pur_pjena') THEN 'kom'
          ELSE 'kg'
        END
      )
    `);
    jedFixed = jedFix.rowCount;
    
    // ⭐ v502.19 (Ivan, 26.05.2026): MIGRACIJA paleta_kolicina za mozaik/grund/super_primer/boja → 600 kg
    //   Ako su postojeće stavke imale 1200 (stari default), prebaci ih na 600 kg.
    //   Ivan može i dalje ručno staviti drugu vrijednost ako želi.
    let paletaFixed600 = 0;
    try {
      const palFix = await pool.query(`
        UPDATE cjenik SET paleta_kolicina = 600, updated_at = NOW()
        WHERE kategorija IN ('mozaik','grund','super_primer','boja')
          AND (paleta_kolicina = 1200 OR paleta_kolicina IS NULL)
      `);
      paletaFixed600 = palFix.rowCount;
      if (paletaFixed600 > 0) console.log(`[v502.19] paleta_kolicina 1200→600 kg za mozaik/grund/super_primer/boja: ${paletaFixed600} stavki`);
    } catch (e) {
      console.warn('[v502.19] paleta_kolicina 600 fix fail:', e.message);
    }
    
    // ⭐ v501.37 (Ivan): KONSOLIDIRAJ IZOLACIJE
    //   Sve postojeće izolacijske cjenik stavke s dobavljačem (npr. "Fragmat EPS", "Ravago EPS-F",
    //   "Caparol MW", "Knauf MW") → DEAKTIVIRAJ ih + relink materijal unose na 4 GENERIC stavke.
    //   Razlog: Ivan ne želi različite cijene per dobavljač za izolacije, samo 4 generic cijene.
    let izolacijeKonsolidirano = 0;
    let izolacijeMaterijalRelink = 0;
    try {
      // ⭐ v135.7.502.20.110 (Ivan, 03.06.2026): MW IZBAČEN iz konsolidacije.
      //   MW (kamena vuna) ide SAMO po dobavljaču (Rockwool/Knauf/+custom) — NEMA MW GENERIC.
      //   Razlog: cijena MW se bitno razlikuje po proizvođaču (gustoća). PRIJE: 'mw' je bio ovdje pa bi
      //   konsolidacija OBRISALA MW Rockwool/Knauf i spojila u MW GENERIC na svakom init-u (gubitak!).
      //   EPS/EPS Grafitni/XPS ostaju GENERIC (jedna cijena po m³).
      // Mapiraj kategoriju → generic cjenik_id
      const genericIzolMap = new Map();
      const genQ = await pool.query(`
        SELECT id, kategorija FROM cjenik 
        WHERE aktivan = true 
          AND kategorija IN ('eps','eps_grafitni','xps')
          AND COALESCE(dobavljac, '') = ''
          AND COALESCE(pod_naziv, '') = ''
      `);
      for (const r of genQ.rows) {
        if (!genericIzolMap.has(r.kategorija)) {
          genericIzolMap.set(r.kategorija, r.id);
        }
      }
      
      // Za svaku ne-generic izolacijsku stavku → relink materijal unose na GENERIC + deaktiviraj
      const neGenericQ = await pool.query(`
        SELECT id, kategorija, naziv, dobavljac FROM cjenik 
        WHERE aktivan = true 
          AND kategorija IN ('eps','eps_grafitni','xps')
          AND (COALESCE(dobavljac, '') != '' OR COALESCE(pod_naziv, '') != '')
      `);
      
      for (const r of neGenericQ.rows) {
        const genId = genericIzolMap.get(r.kategorija);
        if (!genId) continue;  // nema generic za tu kat — preskoči
        
        // Relink materijal unose
        const relinkR = await pool.query(
          `UPDATE materijal SET cjenik_id = $1 WHERE cjenik_id = $2`,
          [genId, r.id]
        );
        izolacijeMaterijalRelink += relinkR.rowCount;
        
        // ⭐ v501.55 (Ivan): HARD DELETE umjesto soft (aktivan više ne koristimo)
        await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [r.id]);
        await pool.query(`DELETE FROM cjenik WHERE id = $1`, [r.id]);
        izolacijeKonsolidirano++;
      }
      
      if (izolacijeKonsolidirano > 0) {
        console.log(`[v501.37 konsolidacija] ${izolacijeKonsolidirano} izolacijskih stavki spojene u 4 GENERIC + ${izolacijeMaterijalRelink} materijal unosa relinkano`);
      }

      // ⭐ v135.7.502.20.110 (Ivan, 03.06.2026): UKLONI MW GENERIC stavku.
      //   MW ide samo po dobavljaču. Stari model je auto-kreirao "MW (generalno)" (bez dobavljača) —
      //   to sad smeta. Briši ga, ALI SAMO ako postoji bar jedan MW po dobavljaču (Rockwool/Knauf/...),
      //   da korisnik ne ostane bez ijednog MW. Idempotentno (ako ga nema, ništa).
      //   SIGURNO: materijal.cjenik_id FK je ON DELETE SET NULL → vezani unosi se NE gube (samo
      //   izgube vezu na cjenik, mogu se ponovno povezati na Rockwool/Knauf). cjenik_povijest CASCADE.
      try {
        const mwDob = await pool.query(
          `SELECT COUNT(*)::int AS n FROM cjenik
           WHERE kategorija = 'mw' AND (COALESCE(dobavljac,'') != '' OR COALESCE(pod_naziv,'') != '')`
        );
        if ((mwDob.rows[0]?.n || 0) > 0) {
          const mwGen = await pool.query(
            `DELETE FROM cjenik
             WHERE kategorija = 'mw' AND COALESCE(dobavljac,'') = '' AND COALESCE(pod_naziv,'') = ''
             RETURNING id`
          );
          if (mwGen.rows.length) console.log(`[v110] MW GENERIC uklonjen (${mwGen.rows.length}) — MW samo po dobavljaču`);
        }
      } catch (e) { console.warn('[v110] MW GENERIC uklanjanje fail:', e.message); }

      // ⭐ v135.7.502.20.73 (Ivan, 02.06.2026): KONSOLIDACIJA GENERIC DUPLIKATA.
      //   Problem: postojalo je VIŠE generic stavki iste kategorije (npr. "EPS", "EPS (generalno)",
      //   "Fragmat EPS" — sve kat='eps', bez dobavljača) jer su 3 različita seeda kroz verzije
      //   kreirala stavke s RAZLIČITIM nazivom ali istom kategorijom → ON CONFLICT (naziv) ih nije
      //   spajao. Stara konsolidacija (gore) hvata samo stavke S dobavljačem, ne generic duplikate.
      //   FIX: za svaku izolacijsku kategoriju zadrži JEDNU generic (najnoviju po vazi_od, pa id),
      //   relinkaj SVE materijal unose s ostalih na zadržanu, obriši ostale. Rezultat: točno 4 stavke.
      //   OPREZ (pravni podaci): unosi se NIKAD ne gube — prvo relink, pa tek onda delete duplikata.
      let genericDuplikataObrisano = 0, genericRelink = 0;
      try {
        for (const kat of ['eps', 'eps_grafitni', 'xps']) {
          // ⭐ v135.7.502.20.81: SVE generic ove kategorije bez dobavljača (bez obzira pod_naziv/naziv)
          const dups = await pool.query(`
            SELECT id, naziv, vazi_od FROM cjenik
            WHERE aktivan = true AND kategorija = $1
              AND COALESCE(dobavljac, '') = ''
            ORDER BY vazi_od DESC NULLS LAST, id DESC
          `, [kat]);
          if (dups.rows.length <= 1) continue;  // 0 ili 1 → nema duplikata
          // zadrži čišći naziv (bez "(generalno)") ako postoji, inače najnoviju
          let keepRow = dups.rows.find(r => !/\(generalno\)/i.test(r.naziv || '')) || dups.rows[0];
          const keepId = keepRow.id;
          const removeIds = dups.rows.filter(r => r.id !== keepId).map(r => r.id);
          // Relink SVI materijal unosi s duplikata → zadržana stavka (prije brisanja!)
          const rl = await pool.query(
            `UPDATE materijal SET cjenik_id = $1 WHERE cjenik_id = ANY($2::int[])`,
            [keepId, removeIds]
          );
          genericRelink += rl.rowCount;
          // Obriši duplikate (povijest pa stavka)
          await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = ANY($1::int[])`, [removeIds]);
          const del = await pool.query(`DELETE FROM cjenik WHERE id = ANY($1::int[])`, [removeIds]);
          genericDuplikataObrisano += del.rowCount;
          console.log(`[v73 generic-konsolidacija] ${kat}: zadržan #${keepId}, obrisano ${del.rowCount} duplikata, ${rl.rowCount} unosa relinkano`);
        }
        if (genericDuplikataObrisano > 0) {
          console.log(`[v73 generic-konsolidacija] UKUPNO: ${genericDuplikataObrisano} generic duplikata spojeno, ${genericRelink} unosa relinkano`);
        }
        izolacijeKonsolidirano += genericDuplikataObrisano;
        izolacijeMaterijalRelink += genericRelink;
      } catch (eGen) {
        console.warn('[v73 generic-konsolidacija] fail:', eGen.message);
      }
    } catch (e) {
      console.warn('[v501.37 konsolidacija] fail:', e.message);
    }
    
    // Dohvati sve stavke s cijenom 0 (ili NULL)
    const nulteQ = await pool.query(`
      SELECT id, naziv, pod_naziv, dobavljac, kategorija, cijena_trenutna
      FROM cjenik 
      WHERE aktivan = true AND (cijena_trenutna IS NULL OR cijena_trenutna = 0)
    `);
    
    if (!nulteQ.rows.length && jedFixed === 0 && kreiraneGeneric === 0 && izolacijeKonsolidirano === 0) {
      return res.json({ ok: true, total: 0, popunjeno: 0, generic_izolacije_kreirano: 0, jedinice_popravljene: 0, izolacije_konsolidirano: 0, message: 'Nema stavki za promjenu — sve već OK.' });
    }
    if (!nulteQ.rows.length) {
      return res.json({ 
        ok: true, total: 0, popunjeno: 0, 
        generic_izolacije_kreirano: kreiraneGeneric, 
        jedinice_popravljene: jedFixed, 
        izolacije_konsolidirano: izolacijeKonsolidirano,
        izolacije_materijal_relink: izolacijeMaterijalRelink,
        message: `${kreiraneGeneric} generic + ${jedFixed} jedinica + ${izolacijeKonsolidirano} izolacija spojeno (${izolacijeMaterijalRelink} unosa relinkano).`
      });
    }
    
    // Dohvati sve stavke s cijena > 0 za prosjek (grupirano po dobavljac + kategorija)
    const popunjeneQ = await pool.query(`
      SELECT dobavljac, kategorija, AVG(cijena_trenutna) AS avg_cijena
      FROM cjenik
      WHERE aktivan = true AND cijena_trenutna > 0
      GROUP BY dobavljac, kategorija
    `);
    const prosjekMap = new Map();  // "dobavljac|kategorija" → avg
    for (const r of popunjeneQ.rows) {
      const key = `${(r.dobavljac || '').toLowerCase()}|${r.kategorija}`;
      prosjekMap.set(key, parseFloat(r.avg_cijena));
    }
    
    let popunjeno = 0;
    const detalji = [];
    
    // ⭐ v135.7.502.20.130 (Ivan, 04.06.2026): transakcija na dediciranom client-u (ne pool) —
    //   pool.query('BEGIN')+pool.query(...) ne garantira istu konekciju → atomičnost je iluzija.
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      for (const s of nulteQ.rows) {
        let novaCijena;
        let strategija;
        
        // 1. Prosjek za isti dobavljač + kategorija
        const key = `${(s.dobavljac || '').toLowerCase()}|${s.kategorija}`;
        if (prosjekMap.has(key)) {
          novaCijena = Math.round(prosjekMap.get(key) * 100) / 100;
          strategija = `Prosjek iz ${s.dobavljac} / ${s.kategorija}`;
        } 
        // 2. Default po kategoriji
        else if (DEFAULT_CIJENE[s.kategorija] !== undefined) {
          novaCijena = DEFAULT_CIJENE[s.kategorija];
          strategija = `Default cijena za kategoriju "${s.kategorija}" (Hr market 2026)`;
        } 
        // 3. Fallback
        else {
          novaCijena = 1.0;
          strategija = 'Fallback 1 EUR (nepoznata kategorija)';
        }
        
        // Update cjenik + insert povijest
        await client.query(
          `UPDATE cjenik SET cijena_trenutna = $1, vazi_od = (now() AT TIME ZONE $$Europe/Zagreb$$)::date, updated_at = NOW() WHERE id = $2`,
          [novaCijena, s.id]
        );
        await client.query(
          `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, napomena, created_by_id)
           VALUES ($1, $2, (now() AT TIME ZONE $$Europe/Zagreb$$)::date, $3, $4)`,
          [s.id, novaCijena, `Auto-popuni: ${strategija}`, req.user?.id || null]
        );
        
        popunjeno++;
        detalji.push({
          id: s.id,
          naziv: s.naziv + (s.pod_naziv ? ` [${s.pod_naziv}]` : ''),
          dobavljac: s.dobavljac || '—',
          kategorija: s.kategorija,
          novaCijena,
          strategija
        });
      }
      await client.query('COMMIT');
    } catch (txErr) {
      await client.query('ROLLBACK').catch(()=>{});
      throw txErr;
    } finally {
      client.release();
    }
    
    console.log(`[v501.37 popuni-cijene] ${kreiraneGeneric} generic + ${jedFixed} jed + ${izolacijeKonsolidirano} izol konsol (${izolacijeMaterijalRelink} mat relink) + ${popunjeno}/${nulteQ.rows.length} cijena popunjeno`);
    res.json({ 
      ok: true, 
      generic_izolacije_kreirano: kreiraneGeneric,
      jedinice_popravljene: jedFixed,
      izolacije_konsolidirano: izolacijeKonsolidirano,
      izolacije_materijal_relink: izolacijeMaterijalRelink,
      total: nulteQ.rows.length,
      popunjeno,
      detalji
    });
  } catch (e) {
    console.error('[v501.30 popuni-cijene]:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.30 (Ivan): SELF-TEST cijena povijest
//   Ivan može pokrenuti u produkciji za jednu cjenik stavku — TEST kreira
//   3 mock povijest reda za 3 godine, kreira mock materijal unose na različite datume,
//   pokrene aggregateMaterijal i pokaže izračune.
//   
//   IDEMPOTENT: koristi PRIVREMENU cjenik stavku "TEST_CIJENA_POVIJEST_<timestamp>",
//   briše nakon testa. NE DIRA realne podatke.
app.get('/api/cjenik/self-test-cijena-povijest', auth, direktor, async (req, res) => {
  const TEST_TS = Date.now();
  const TEST_NAZIV = `TEST_CIJENA_POVIJEST_${TEST_TS}`;
  let cjenikId = null;
  
  try {
    const log = [];
    log.push(`═══ SELF-TEST CIJENA POVIJEST kroz 3 godine ═══`);
    log.push(`Test stavka: "${TEST_NAZIV}" — bit će obrisana nakon testa`);
    log.push('');
    
    // 1. Kreiraj test cjenik stavku
    const insC = await pool.query(
      `INSERT INTO cjenik (naziv, dobavljac, kategorija, jedinica, paleta_kolicina, cijena_trenutna, vazi_od)
       VALUES ($1, 'TEST', 'ostalo', 'kg', 1, 0.20, '2024-01-01')
       RETURNING id`,
      [TEST_NAZIV]
    );
    cjenikId = insC.rows[0].id;
    log.push(`✓ Kreirana test cjenik stavka id=${cjenikId}`);
    
    // 2. Dodaj 3 povijest reda (simulacija 3 promjene cijene)
    const povijestRedovi = [
      { vazi_od: '2024-01-01', vazi_do: '2024-06-30', cijena: 0.20, napomena: 'TEST P1: Inicijalno' },
      { vazi_od: '2024-07-01', vazi_do: '2025-03-31', cijena: 0.25, napomena: 'TEST P2: Inflacija ljeto 2024' },
      { vazi_od: '2025-04-01', vazi_do: null,         cijena: 0.30, napomena: 'TEST P3: Q2 2025 poskupljenje' }
    ];
    
    // Najprije obrisi default povijest red koji INSERT auto-kreira ne radi (samo INSERT cjenik bez povijesti)
    await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [cjenikId]);
    
    for (const p of povijestRedovi) {
      await pool.query(
        `INSERT INTO cjenik_povijest (cjenik_id, cijena, vazi_od, vazi_do, napomena)
         VALUES ($1, $2, $3, $4, $5)`,
        [cjenikId, p.cijena, p.vazi_od, p.vazi_do, p.napomena]
      );
    }
    log.push(`✓ Dodano ${povijestRedovi.length} povijest redova:`);
    for (const p of povijestRedovi) {
      log.push(`    ${p.vazi_od} → ${p.vazi_do || 'sada'}: ${p.cijena.toFixed(2)} EUR/kg (${p.napomena})`);
    }
    log.push('');
    
    // Update cijena_trenutna na zadnju (0.30)
    await pool.query(`UPDATE cjenik SET cijena_trenutna = 0.30 WHERE id = $1`, [cjenikId]);
    
    // 3. Učitaj povijest kao map (kopija cijenaPoDatumu logike)
    const povijestQ = await pool.query(
      `SELECT cijena, vazi_od, vazi_do FROM cjenik_povijest WHERE cjenik_id = $1 ORDER BY vazi_od DESC`,
      [cjenikId]
    );
    const povijest = povijestQ.rows;
    
    const cijenaPoDatumu = (datum) => {
      const datumStr = typeof datum === 'string' ? datum.slice(0, 10) : _ymd(datum);
      for (const p of povijest) {
        const vaziOdStr = typeof p.vazi_od === 'string' ? p.vazi_od.slice(0,10) : _ymd(p.vazi_od);
        const vaziDoStr = p.vazi_do 
          ? (typeof p.vazi_do === 'string' ? p.vazi_do.slice(0,10) : _ymd(p.vazi_do))
          : '9999-12-31';
        if (datumStr >= vaziOdStr && datumStr <= vaziDoStr) return parseFloat(p.cijena);
      }
      return 0.30;
    };
    
    // 4. Simuliraj 8 materijal unosa kroz 3 godine (500 kg svaki)
    const testDatumi = [
      '2024-01-15', '2024-05-15', '2024-09-15', 
      '2025-01-15', '2025-05-15', '2025-09-15',
      '2026-01-15', '2026-05-15'
    ];
    
    log.push(`Mock materijal unosi (500 kg svaki, cijena_po_datumu_unosa):`);
    log.push(`────────────────────────────────────────────────────────`);
    log.push(`DATUM         KOLIČINA  CIJENA/kg  TROŠAK     PERIOD`);
    log.push(`────────────────────────────────────────────────────────`);
    
    let total2024 = 0, total2025 = 0, total2026 = 0;
    let kol2024 = 0, kol2025 = 0, kol2026 = 0;
    
    for (const dat of testDatumi) {
      const cijena = cijenaPoDatumu(dat);
      const trosak = 500 * cijena;
      const god = dat.slice(0, 4);
      let period;
      if (dat < '2024-07-01') period = 'P1 (0.20)';
      else if (dat < '2025-04-01') period = 'P2 (0.25)';
      else period = 'P3 (0.30)';
      
      log.push(`${dat}   500 kg    ${cijena.toFixed(2)} EUR   ${String(trosak.toFixed(2)).padStart(8)} EUR   ${period}`);
      
      if (god === '2024') { total2024 += trosak; kol2024 += 500; }
      else if (god === '2025') { total2025 += trosak; kol2025 += 500; }
      else if (god === '2026') { total2026 += trosak; kol2026 += 500; }
    }
    
    log.push(`────────────────────────────────────────────────────────`);
    log.push('');
    log.push(`SUMA PO GODINAMA:`);
    log.push(`  2024: ${kol2024} kg → ${total2024.toFixed(2)} EUR  (prosjek ${(total2024/kol2024).toFixed(4)} EUR/kg)`);
    log.push(`  2025: ${kol2025} kg → ${total2025.toFixed(2)} EUR  (prosjek ${(total2025/kol2025).toFixed(4)} EUR/kg)`);
    log.push(`  2026: ${kol2026} kg → ${total2026.toFixed(2)} EUR  (prosjek ${(total2026/kol2026).toFixed(4)} EUR/kg)`);
    log.push('');
    
    // 5. Provjera očekivanih vrijednosti
    const exp2024 = 500 * 0.20 + 500 * 0.20 + 500 * 0.25;  // 225
    const exp2025 = 500 * 0.25 + 500 * 0.30 + 500 * 0.30;  // 425
    const exp2026 = 500 * 0.30 + 500 * 0.30;                // 300
    
    const test1 = Math.abs(total2024 - exp2024) < 0.01;
    const test2 = Math.abs(total2025 - exp2025) < 0.01;
    const test3 = Math.abs(total2026 - exp2026) < 0.01;
    
    log.push(`PROVJERA (očekivane vrijednosti):`);
    log.push(`  2024: ${exp2024} EUR  → ${test1 ? '✅' : '❌'}`);
    log.push(`  2025: ${exp2025} EUR  → ${test2 ? '✅' : '❌'}`);
    log.push(`  2026: ${exp2026} EUR  → ${test3 ? '✅' : '❌'}`);
    log.push('');
    
    if (test1 && test2 && test3) {
      log.push(`✅ SVI TESTOVI PROŠLI`);
      log.push(`Logika cijenaPoDatumu radi TOČNO:`);
      log.push(`  - aggregateMaterijal (Analitika tab, Excel exporti) ← OK`);
      log.push(`  - Cjenik PDF SAŽETAK (aggregateMaterijal) ← OK`);
      log.push(`  - cijenaPoDatumuG (Godišnji PDF) ← OK`);
      log.push(`  - Materijal unos s datumom 2024 uzme P1 cijenu`);
      log.push(`  - Materijal unos s datumom 2025 (jan-mar) uzme P2 cijenu`);
      log.push(`  - Materijal unos s datumom 2025 (apr+) i 2026 uzme P3 cijenu`);
    } else {
      log.push(`❌ TESTOVI NISU PROŠLI — molim kontaktiraj support`);
    }
    
    // 6. Cleanup (briši test podatke)
    await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [cjenikId]);
    await pool.query(`DELETE FROM cjenik WHERE id = $1`, [cjenikId]);
    log.push('');
    log.push(`✓ Test podaci obrisani (cjenik id=${cjenikId} + 3 povijest reda)`);
    
    res.json({
      ok: test1 && test2 && test3,
      log: log.join('\n'),
      results: {
        '2024': { kg: kol2024, eur: total2024, expected: exp2024, ok: test1 },
        '2025': { kg: kol2025, eur: total2025, expected: exp2025, ok: test2 },
        '2026': { kg: kol2026, eur: total2026, expected: exp2026, ok: test3 }
      }
    });
  } catch (e) {
    // Cleanup ako test fail-uje
    if (cjenikId) {
      try {
        await pool.query(`DELETE FROM cjenik_povijest WHERE cjenik_id = $1`, [cjenikId]);
        await pool.query(`DELETE FROM cjenik WHERE id = $1`, [cjenikId]);
      } catch (_) {}
    }
    console.error('[v501.30 self-test cijena]:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v501.23: Materijal endpoint dobi validaciju obaveznih polja (dobavljač + naziv)
//   Ovaj middleware ide PRIJE POST /api/materijal (postojeći) i validira input.
//   NIJE breaking — samo poboljšane greške. Postojeći endpoint i dalje radi normalno.
//   Provjera je SOFT — ne odbija ako Memsur "ipak" pošalje bez dobavljača (legacy unosi).
//   Ali klijent prompt će forsirati pravo ponašanje.

// ⭐ v501.23 (Ivan, 21.05.2026): PDF EXPORT CJENIKA — prezentacijski format
//   Direktor klikne "📄 Export PDF" u cjeniku → multi-page PDF:
//   STRANICA 1: Naslov + Summary (broj proizvoda, prosjek cijena po kategoriji)
//   STRANICA 2+: Po proizvođaču, tablica proizvoda (naziv, jedinica, cijena, paleta)
//   STRANICA N+: Po proizvod (samo aktivni s 2+ unosa) - mini analitika:
//                 graf cijena kroz vrijeme + potrošnja per mjesec + ukupni godišnji trošak
app.get('/api/cjenik/export-pdf', auth, direktor, async (req, res) => {
  try {
    const PDFDocument = require('pdfkit');
    const godina = validateGodina(req.query.godina);
    
    // ⭐ v501.28: dobavljac + pod_naziv (od v501.27 model)
    //   Backwards compat: i dalje JOIN proizvodjaci za stare zapise koji imaju proizvodjac_id
    const cjenikQ = await pool.query(`
      SELECT c.id, c.naziv, c.pod_naziv, c.dobavljac, c.kategorija, c.jedinica, c.paleta_kolicina,
             c.cijena_trenutna, c.vazi_od, c.aktivan,
             COALESCE(c.dobavljac, p.naziv) AS dobavljac_eff
      FROM cjenik c
      LEFT JOIN proizvodjaci p ON p.id = c.proizvodjac_id
      ORDER BY COALESCE(c.dobavljac, p.naziv) ASC NULLS LAST, c.naziv ASC, c.pod_naziv ASC NULLS FIRST
    `);
    const cjenikData = cjenikQ.rows;
    
    // Dohvati potrošnju per cjenik_id za danu godinu
    const potrosnjaQ = await pool.query(`
      SELECT cjenik_id, 
             EXTRACT(MONTH FROM datum)::int AS mjesec,
             COUNT(*)::int AS broj_unosa,
             COALESCE(SUM(kolicina::float), 0) AS uk_kolicina,
             COALESCE(SUM(CASE WHEN jedinica = 'paleta' OR jedinica = 'pal' THEN kolicina::float * 1200 ELSE kolicina::float END), 0) AS uk_kg_priblizno  -- PAK_FAKTORI.PALETA_KG=1200 (raw SQL, približna kg statistika)
      FROM materijal
      WHERE cjenik_id IS NOT NULL AND EXTRACT(YEAR FROM datum) = $1
      GROUP BY cjenik_id, mjesec
      ORDER BY cjenik_id, mjesec
    `, [godina]);
    
    // Indeksiraj potrošnju per cjenik_id → { mjesec: { broj, kolicina } }
    const potrosnjaMap = new Map();
    for (const p of potrosnjaQ.rows) {
      if (!potrosnjaMap.has(p.cjenik_id)) potrosnjaMap.set(p.cjenik_id, {});
      potrosnjaMap.get(p.cjenik_id)[p.mjesec] = {
        broj: parseInt(p.broj_unosa) || 0,
        kolicina: parseFloat(p.uk_kolicina) || 0
      };
    }
    
    // Dohvati povijest cijena per cjenik_id
    const povijestQ = await pool.query(`
      SELECT cjenik_id, cijena, vazi_od, vazi_do
      FROM cjenik_povijest
      ORDER BY cjenik_id, vazi_od ASC
    `);
    const povijestMap = new Map();
    for (const p of povijestQ.rows) {
      if (!povijestMap.has(p.cjenik_id)) povijestMap.set(p.cjenik_id, []);
      povijestMap.get(p.cjenik_id).push({
        cijena: parseFloat(p.cijena) || 0,
        vazi_od: p.vazi_od,
        vazi_do: p.vazi_do
      });
    }
    
    // ⭐ v135.7.502.20.122 (Ivan, FAZA 6): perCjenikStats UKLONJEN — imao je vlastitu (divergentnu)
    //   normalizaciju paleta→kg koja je davala ~2.6× prenapuhan trošak (325k umjesto 124k). UDIO TROŠKA
    //   sad koristi aggregateMaterijal (jedini izvor istine, isti kao materijal PDF). Manje koda, nema
    //   divergencije. Cjenik export i dalje koristi povijestMap za graf cijena po kategoriji (nije dirano).
    
    // ─── INICIJALIZIRAJ PDF ───
    // ⭐ v501.30: margin: 0 (manual positioning, prevent auto-pagination koje kreira prazne stranice)
    const doc = new PDFDocument({ size: 'A4', margin: 0, info: {
      Title: `ŽBUKA Cjenik materijala — ${godina}`,
      Author: 'ŽBUKA Čakarić d.o.o.',
      Subject: 'Cjenik materijala'
    }});
    
    // ⭐ v501.26: registriraj fontove + dohvati logo
    const { FREG, FBOLD, FITAL, FBITAL } = registerPDFFonts(doc);
    const LOGO_LIGHT = getPDFLogo('dark');
    const LOGO_DARK = getPDFLogo('light');
    
    const chunks = [];
    doc.on('data', c => chunks.push(c));
    
    // ⭐ v502.17 (Ivan, 26.05.2026): dodan reject u Promise — vidi razlog na donePromise materijal PDF.
    const pdfDone = new Promise((resolve, reject) => {
      doc.on('end', resolve);
      doc.on('error', reject);
    });
    
    // BORDEAUX BRAND PALETA
    const COL = {
      BORDEAUX: '#7a1a1a',
      BORDEAUX_DARK: '#5a0e0e',
      BORDEAUX_LIGHT_BG: '#f5d5d5',
      RED: '#dc2626',
      BLUE: '#3b82f6',
      GREEN: '#16a34a',
      GREY: '#6b7280',
      LIGHT: '#f3f4f6',
      DARK: '#1f2937',
      WHITE: '#ffffff'
    };
    
    const MJES_KRATKO = ['Sij','Velj','Ožu','Tra','Svi','Lip','Srp','Kol','Ruj','Lis','Stu','Pro'];
    const A4W = 595, A4H = 842, MX = 40;  // margine
    const eur = (n) => (Math.round((parseFloat(n)||0) * 100) / 100).toLocaleString('hr-HR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmtKratko = (d) => { if (!d) return ''; const x = new Date(d); return `${x.getDate()}.${x.getMonth()+1}.${String(x.getFullYear()).slice(2)}.`; };

    // Čitljiv naziv kategorije (kod → ime). Tip naziv ako postoji, inače master.
    let tipKatNaziv = {};
    try {
      const tr = await pool.query(`SELECT naziv, kategorija FROM materijal_tipovi WHERE kategorija IS NOT NULL`);
      for (const t of tr.rows) { if (t.kategorija && !tipKatNaziv[t.kategorija]) tipKatNaziv[t.kategorija] = t.naziv; }
    } catch (_) {}
    const katIme = (kod) => tipKatNaziv[kod] || (CJEN_MASTER[kod] && CJEN_MASTER[kod].naziv) || (kod || 'Ostalo');

    // Helper: header svake stranice (cream banner s logom)
    const drawHeader = (subtitle) => {
      const _logoDark = getPDFLogo('light');
      doc.rect(0, 0, A4W, 62).fillColor('#f5ecd9').fill();
      doc.rect(0, 60, A4W, 2.5).fillColor(COL.BORDEAUX).fill();
      if (_logoDark) { try { doc.image(_logoDark, MX, 12, { width: 80, height: 38 }); } catch (_) {} }
      else { doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(15).text('ŽBUKA Čakarić d.o.o.', MX, 20); }
      doc.fillColor(COL.GREY).font(FREG).fontSize(9).text(subtitle || `Cjenik materijala · ${godina}`, 0, 24, { width: A4W - MX, align: 'right' });
      doc.fillColor('#9ca3af').font(FREG).fontSize(7.5).text('Ilica 506, Zagreb · OIB: 46540647857', 0, 38, { width: A4W - MX, align: 'right' });
      doc.y = 80;
    };
    const drawFooter = (pageNum) => {
      doc.fillColor('#9ca3af').font(FREG).fontSize(7.5)
         .text(`ŽBUKA Čakarić d.o.o. · Cjenik ${godina} · str. ${pageNum} · generirano ${fmtKratko(new Date())}`,
               MX, A4H - 28, { width: A4W - 2*MX, align: 'center' });
    };

    // Helper: AREA CHART kretanja cijene (premium). points=[{cijena,vazi_od}], sortirano ASC.
    // ⭐ v135.7.502.20.115 (Ivan, 03.06.2026): redizajn — area fill s vertikalnim gradijentom (boja→prozirno)
    //   umjesto gole linije; zaobljena pozadina; istaknuta zadnja cijena; prva cijena maknuta (preklapala
    //   se s datumom). Pregledniji i ljepši ("vrhunski premium").
    const drawSparkline = (x, y, w, h, points, boja) => {
      if (!points || points.length < 2) return false;
      const cijene = points.map(p => p.cijena);
      const min = Math.min(...cijene), max = Math.max(...cijene);
      const range = (max - min) || (min * 0.1) || 1;
      const padL = 6, padR = 46, padT = 16, padB = 15;
      const innerW = w - padL - padR, innerH = h - padT - padB;
      const px = (i) => x + padL + (innerW * i / (points.length - 1));
      const py = (c) => y + padT + innerH - (innerH * (c - min) / range);
      const baseY = py(min);
      const col = boja || COL.BORDEAUX;
      doc.save();
      // zaobljena pozadina + suptilni okvir
      doc.roundedRect(x, y, w, h, 5).fillColor('#fdfbf6').fill();
      doc.roundedRect(x, y, w, h, 5).lineWidth(0.6).strokeColor('#ece3d0').stroke();
      // suptilna baseline (min razina)
      doc.lineWidth(0.4).strokeColor('#efe7d6').dash(1.5, { space: 2.5 });
      doc.moveTo(x + padL, py(min)).lineTo(x + padL + innerW, py(min)).stroke();
      doc.undash();
      // AREA FILL s vertikalnim gradijentom (boja → gotovo prozirno)
      doc.moveTo(px(0), baseY);
      points.forEach((p, i) => doc.lineTo(px(i), py(p.cijena)));
      doc.lineTo(px(points.length - 1), baseY);
      doc.closePath();
      const grad = doc.linearGradient(x, y + padT, x, baseY);
      grad.stop(0, col, 0.30).stop(1, col, 0.02);
      doc.fillColor(grad).fill();
      // LINIJA (glatka, zaobljeni spojevi)
      doc.lineWidth(2).strokeColor(col).lineJoin('round').lineCap('round');
      points.forEach((p, i) => { const X = px(i), Y = py(p.cijena); if (i === 0) doc.moveTo(X, Y); else doc.lineTo(X, Y); });
      doc.stroke();
      // prva (bijela s obrubom) + zadnja (puna, veća) točka
      doc.circle(px(0), py(cijene[0]), 2.1).fillColor('#fff').fill();
      doc.circle(px(0), py(cijene[0]), 2.1).lineWidth(1).strokeColor(col).stroke();
      doc.circle(px(points.length-1), py(cijene[cijene.length-1]), 2.8).fillColor(col).fill();
      doc.circle(px(points.length-1), py(cijene[cijene.length-1]), 2.8).lineWidth(1.4).strokeColor('#fff').stroke();
      // zadnja cijena (istaknuta, desno)
      doc.fillColor(col).font(FBOLD).fontSize(10.5).text(eur(cijene[cijene.length-1]) + ' \u20ac', x + w - padR, py(cijene[cijene.length-1]) - 6, { width: padR - 2, align: 'right' });
      // datumi prve/zadnje (dolje, sitno)
      doc.font(FREG).fontSize(6).fillColor('#c4baa3');
      doc.text(fmtKratko(points[0].vazi_od), x + padL, y + h - 10, { width: 54, align: 'left' });
      doc.text(fmtKratko(points[points.length-1].vazi_od), x + w - padR - 56, y + h - 10, { width: padR + 54, align: 'right' });
      doc.restore();
      return true;
    };

    let pageNum = 1;

    // ══════════ COVER (premium cream) ══════════
    doc.rect(0, 0, A4W, A4H).fillColor('#f5ecd9').fill();
    doc.fillColor(COL.BORDEAUX).polygon([0, 0], [190, 0], [0, 190]).fill();
    doc.fillColor('#e0d4b6').polygon([A4W, A4H], [A4W-190, A4H], [A4W, A4H-190]).fill();
    if (LOGO_DARK) { try { doc.image(LOGO_DARK, (A4W - 250) / 2, 150, { width: 250, height: 116 }); } catch (_) {} }
    doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(33).text('CJENIK MATERIJALA', 0, 318, { width: A4W, align: 'center', characterSpacing: 1 });
    doc.fillColor(COL.DARK).font(FREG).fontSize(15).text('Pregled cijena i kretanja \u00b7 ' + godina, 0, 364, { width: A4W, align: 'center' });
    doc.rect((A4W-120)/2, 398, 120, 2).fillColor(COL.BORDEAUX).fill();
    doc.fillColor(COL.GREY).font(FREG).fontSize(10).text('Interni dokument za pra\u0107enje cijena materijala\ni pregovore s dobavlja\u010dima', 0, 418, { width: A4W, align: 'center', lineGap: 3 });
    doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(13).text('\u017dBUKA \u010cakari\u0107 d.o.o.', 0, 700, { width: A4W, align: 'center' });
    doc.fillColor(COL.GREY).font(FREG).fontSize(9).text('Ilica 506, Zagreb \u00b7 OIB: 46540647857', 0, 720, { width: A4W, align: 'center' });
    doc.fillColor('#9ca3af').font(FREG).fontSize(8).text('Generirano ' + fmtKratko(new Date()), 0, 736, { width: A4W, align: 'center' });

    // ══════════ PRIPREMA PODATAKA ══════════
    const aktivni = cjenikData.filter(c => c.naziv && String(c.naziv).trim());
    const katGrupe = new Map();
    for (const c of aktivni) {
      const kat = (c.kategorija || 'ostalo').toLowerCase().trim();
      if (!katGrupe.has(kat)) katGrupe.set(kat, []);
      const pov = (povijestMap.get(c.id) || []).slice().sort((a,b) => new Date(a.vazi_od) - new Date(b.vazi_od));
      const cijenaSad = parseFloat(c.cijena_trenutna) || (pov.length ? pov[pov.length-1].cijena : 0);
      const cijenaPrva = pov.length ? pov[0].cijena : cijenaSad;
      const promjenaPct = (cijenaPrva > 0) ? ((cijenaSad - cijenaPrva) / cijenaPrva * 100) : 0;
      katGrupe.get(kat).push({
        naziv: c.naziv, dobavljac: c.dobavljac_eff || c.dobavljac || '\u2014',
        jedinica: c.jedinica || 'kg', paleta: c.paleta_kolicina,
        cijenaSad, cijenaPrva, promjenaPct, pov, brojPromjena: pov.length
      });
    }
    const izolKatSet = IZOL_KATEGORIJE;
    const katKljucevi = [...katGrupe.keys()].sort((a, b) => {
      const ai = izolKatSet.has(a) ? 0 : 1, bi = izolKatSet.has(b) ? 0 : 1;
      if (ai !== bi) return ai - bi;
      return katIme(a).localeCompare(katIme(b), 'hr');
    });
    for (const k of katKljucevi) {
      katGrupe.get(k).sort((a, b) => (a.dobavljac||'').localeCompare(b.dobavljac||'', 'hr') || (a.naziv||'').localeCompare(b.naziv||'', 'hr'));
    }

    // ══════════ SAŽETAK ══════════
    // ⭐ v135.7.502.20.122 (Ivan, FAZA 6): KRITIČAN FIX — trošak iz aggregateMaterijal (ISTI izvor istine
    //   kao materijal PDF). PRIJE: perCjenikStats imao VLASTITU normalizaciju koja je divergirala ~2.6× →
    //   prikazivao 325.747 € umjesto stvarnih 124.149 €. SAD: ukupno + udjeli kategorija se garantirano
    //   poklapaju s materijal exportom. Bonus: broj nabava po kategoriji za prikaz.
    const trosakPoKat = new Map();      // kljuc → eur
    const katNabave = new Map();        // kljuc → broj_unosa (nabava)
    let trosakUkupno = 0;
    let trosakBrojUnosa = 0;
    let trosakDobavljaca = 0;
    try {
      const _ag = await aggregateMaterijal({ od_datum: `${godina}-01-01`, do_datum: `${godina}-12-31` });
      trosakUkupno = _ag.ukupno_eur || 0;
      trosakBrojUnosa = _ag.ukupno_unosa || 0;
      trosakDobavljaca = _ag.ukupno_dobavljaca || 0;
      for (const kat of (_ag.materijal_kategorije || [])) {
        const key = (kat.kljuc || '').toLowerCase().trim();
        if (!key) continue;
        trosakPoKat.set(key, (trosakPoKat.get(key) || 0) + (kat.eur || 0));
        katNabave.set(key, (katNabave.get(key) || 0) + (kat.broj_unosa || 0));
      }
    } catch (e) {
      console.warn('[cjenik PDF v122] aggregateMaterijal trošak fail:', e.message);
    }
    const imaTrosak = trosakUkupno > 0;
    const sumMaxShare = imaTrosak ? Math.max(...[...trosakPoKat.values()].map(v => v / trosakUkupno), 0.0001) : 1;

    doc.addPage(); pageNum++;
    drawHeader('Sa\u017eetak po kategorijama');
    doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(20).text('Pregled cjenika', MX, doc.y);
    doc.moveDown(0.3);
    doc.fillColor(COL.GREY).font(FREG).fontSize(9.5).text(
      imaTrosak
        ? ('Ukupno ' + aktivni.length + ' proizvoda u ' + katKljucevi.length + ' kategorija. Trošak materijala ' + godina + '.: ' + eur(trosakUkupno) + ' \u20ac kroz ' + trosakBrojUnosa + ' ' + (trosakBrojUnosa === 1 ? 'nabavu' : (trosakBrojUnosa < 5 ? 'nabave' : 'nabava')) + (trosakDobavljaca ? (' od ' + trosakDobavljaca + ' ' + (trosakDobavljaca === 1 ? 'dobavljača' : 'dobavljača')) : '') + '. UDIO TROŠKA = udio kategorije u ukupnom trošku.')
        : ('Ukupno ' + aktivni.length + ' proizvoda u ' + katKljucevi.length + ' kategorija. Strelica pokazuje prosje\u010dnu promjenu cijene. (Nema unosa materijala u ' + godina + '. za udio tro\u0161ka.)'),
      MX, doc.y, { width: A4W - 2*MX, lineGap: 2 });
    doc.moveDown(1);
    doc.rect(MX, doc.y, A4W - 2*MX, 24).fillColor(COL.BORDEAUX).fill();
    let sumHy = doc.y + 7.5;
    doc.fillColor('#fff').font(FBOLD).fontSize(8.5);
    doc.text('KATEGORIJA', MX+12, sumHy);
    doc.text('PROIZ.', MX+180, sumHy, { width: 42, align: 'center' });
    doc.text('UDIO TRO\u0160KA', MX+228, sumHy, { width: 112, align: 'left' });
    doc.text('RASPON CIJENA', MX+345, sumHy, { width: 92, align: 'center' });
    doc.text('PROMJ.', A4W-MX-76, sumHy, { width: 76, align: 'right' });
    doc.y += 24;
    let sumRi = 0;
    for (const k of katKljucevi) {
      const arr = katGrupe.get(k);
      const jeIzolK = izolKatSet.has(k);
      const cijene = arr.map(p => p.cijenaSad).filter(c => c > 0);
      const minC = cijene.length ? Math.min(...cijene) : 0, maxC = cijene.length ? Math.max(...cijene) : 0;
      const promj = arr.filter(p => p.brojPromjena >= 2);
      const avgProm = promj.length ? (promj.reduce((s,p) => s + p.promjenaPct, 0) / promj.length) : 0;
      const jed = arr[0] ? arr[0].jedinica : '';
      const catEur = trosakPoKat.get(k) || 0;
      const share = imaTrosak ? (catEur / trosakUkupno) : 0;
      if (doc.y > A4H - 60) { drawFooter(pageNum); doc.addPage(); pageNum++; drawHeader('Sa\u017eetak po kategorijama'); doc.y = 80; }
      const ry = doc.y;
      if (sumRi % 2 === 0) { doc.rect(MX, ry, A4W - 2*MX, 31).fillColor('#faf6ee').fill(); }
      // accent točka + ime + (broj nabava ispod)
      const nabave = katNabave.get(k) || 0;
      doc.circle(MX+16, ry+11, 3).fillColor(jeIzolK ? COL.BORDEAUX : '#cbb994').fill();
      doc.fillColor(COL.DARK).font(FBOLD).fontSize(10).text(katIme(k), MX+26, ry+5, { width: 148, ellipsis: true });
      if (nabave > 0) {
        doc.fillColor('#a89a7d').font(FREG).fontSize(7).text(nabave + ' ' + (nabave === 1 ? 'nabava' : (nabave < 5 ? 'nabave' : 'nabava')), MX+26, ry+17, { width: 148 });
      }
      // PROIZ. (broj)
      doc.fillColor(COL.GREY).font(FREG).fontSize(9.5).text(String(arr.length), MX+180, ry+8.5, { width: 42, align: 'center' });
      // UDIO TROŠKA: bar + % (gore) + apsolutni € (ispod)
      const barX = MX+228, barMaxW = 72;
      doc.roundedRect(barX, ry+7, barMaxW, 7, 3.5).fillColor('#ece3d0').fill();
      if (imaTrosak && share > 0) {
        const barW = Math.max(4, barMaxW * share / sumMaxShare);
        doc.roundedRect(barX, ry+7, barW, 7, 3.5).fillColor(jeIzolK ? COL.BORDEAUX : '#cbb994').fill();
        const pct = share * 100;
        doc.fillColor(COL.DARK).font(FBOLD).fontSize(9).text(pct.toFixed(pct >= 9.95 ? 0 : 1) + '%', MX+302, ry+5.5, { width: 38, align: 'left' });
        doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(8.5).text(eur(catEur) + ' \u20ac', barX, ry+17, { width: 110 });
      } else {
        doc.fillColor('#b8ad97').font(FREG).fontSize(8.5).text('\u2014', MX+302, ry+8.5, { width: 38, align: 'left' });
      }
      // RASPON CIJENA
      doc.fillColor(COL.DARK).font(FREG).fontSize(8).text(cijene.length ? (eur(minC) + '\u2013' + eur(maxC) + ' \u20ac/' + jed) : '\u2014', MX+345, ry+9, { width: 92, align: 'center' });
      // PROMJENA
      const promBoja = avgProm > 0.5 ? COL.RED : (avgProm < -0.5 ? COL.GREEN : COL.GREY);
      const promStr = promj.length ? ((avgProm > 0 ? '\u25b2 +' : (avgProm < 0 ? '\u25bc ' : '\u2013 ')) + avgProm.toFixed(1) + '%') : '\u2014';
      doc.fillColor(promBoja).font(FBOLD).fontSize(9).text(promStr, A4W-MX-76, ry+8.5, { width: 76, align: 'right' });
      doc.y = ry + 31;
      sumRi++;
    }
    drawFooter(pageNum);

    // ══════════ PO KATEGORIJAMA ══════════
    // ⭐ v135.7.502.20.111 (Ivan): kategorije TEKU jedna za drugom (nova stranica SAMO kad nema mjesta).
    //   PRIJE: doc.addPage() po svakoj kategoriji → kategorija s 1 proizvodom = cijela prazna stranica.
    //   Sad: popunjeno, manje stranica. Veća kartica (82px) + veći/čitljiviji graf.
    doc.addPage(); pageNum++;
    drawHeader('Cjenik po kategorijama');
    for (const k of katKljucevi) {
      const arr = katGrupe.get(k);
      const jeIzol = izolKatSet.has(k);
      // nova stranica ako nema mjesta za header kategorije + bar 1 karticu (~120px); inače razmak
      if (doc.y > A4H - 132) { drawFooter(pageNum); doc.addPage(); pageNum++; drawHeader('Cjenik po kategorijama'); }
      else if (doc.y > 88) { doc.y += 14; }
      // header kategorije — ⭐ v135.7.502.20.115 (Ivan): zaobljen + accent linija dolje
      const hy = doc.y;
      doc.roundedRect(MX, hy, A4W - 2*MX, 30, 6).fillColor(jeIzol ? COL.BORDEAUX : '#2d2d2b').fill();
      doc.rect(MX+6, hy+27, A4W - 2*MX - 12, 1.5).fillColor(jeIzol ? '#d9b3b3' : '#cbb994').fill();
      doc.fillColor('#fff').font(FBOLD).fontSize(14).text((jeIzol ? '\u25c6  ' : '') + katIme(k), MX+14, hy+8);
      doc.fillColor(jeIzol ? '#e8d5d5' : '#cfcfcd').font(FREG).fontSize(8.5).text(arr.length + ' ' + (arr.length===1?'proizvod':'proizvoda'), A4W - MX - 130, hy+10.5, { width: 117, align: 'right' });
      doc.y = hy + 40;
      for (const p of arr) {
        const cardH = 84;
        if (doc.y > A4H - cardH - 30) { drawFooter(pageNum); doc.addPage(); pageNum++; drawHeader('Cjenik po kategorijama  \u00b7  ' + katIme(k) + ' (nast.)'); doc.y = 80; }
        const cy = doc.y;
        const cardW = A4W - 2*MX;
        // ⭐ v135.7.502.20.115 (Ivan): premium kartica — suptilna sjena + zaobljeni rubovi + pill dobavljač
        //   + blok cijene s tintom. Pregledniji, ljepši, vrhunski.
        doc.roundedRect(MX+2, cy+2.5, cardW, cardH, 7).fillColor('#eae2d2').fill();       // sjena
        doc.roundedRect(MX, cy, cardW, cardH, 7).fillColor('#ffffff').fill();             // bijela ploha
        doc.roundedRect(MX, cy, cardW, cardH, 7).lineWidth(0.7).strokeColor('#ece5d6').stroke();
        doc.save();                                                                        // lijevi accent (clip uz zaobljenje)
        doc.roundedRect(MX, cy, cardW, cardH, 7).clip();
        doc.rect(MX, cy, 5, cardH).fillColor(jeIzol ? COL.BORDEAUX : '#cbb994').fill();
        doc.restore();
        // naziv proizvoda
        doc.fillColor(COL.DARK).font(FBOLD).fontSize(13.5).text(p.naziv, MX+18, cy+13, { width: 215, ellipsis: true });
        // dobavljač — pill badge
        const dobTxt = p.dobavljac || '\u2014';
        doc.font(FREG).fontSize(8.5);
        const dobW = Math.min(doc.widthOfString(dobTxt) + 16, 200);
        doc.roundedRect(MX+18, cy+35, dobW, 15, 7).fillColor('#f6f0e4').fill();
        doc.fillColor('#7a6a45').font(FBOLD).fontSize(8.5).text(dobTxt, MX+24, cy+38.5, { width: dobW-12, ellipsis: true });
        // paleta
        doc.fillColor('#a9a08c').font(FREG).fontSize(8).text(p.paleta ? ('paleta: ' + parseFloat(p.paleta).toFixed(0) + ' ' + p.jedinica) : 'bez palete', MX+18, cy+56, { width: 210 });
        // CIJENA blok (svijetla tinta)
        const priceX = MX+244, priceW = 92;
        doc.roundedRect(priceX, cy+12, priceW, cardH-24, 6).fillColor(jeIzol ? '#fbf3f3' : '#faf6ee').fill();
        doc.fillColor(COL.BORDEAUX).font(FBOLD).fontSize(20).text(eur(p.cijenaSad), priceX, cy+24, { width: priceW-8, align: 'right' });
        doc.fillColor(COL.GREY).font(FREG).fontSize(8.5).text('\u20ac / ' + p.jedinica, priceX, cy+50, { width: priceW-8, align: 'right' });
        // GRAF (desni dio)
        const grafX = priceX + priceW + 10, grafW = A4W - MX - grafX - 10, grafY = cy + 9, grafH = cardH - 18;
        const promBoja = p.promjenaPct > 0.5 ? COL.RED : (p.promjenaPct < -0.5 ? COL.GREEN : COL.GREY);
        if (p.brojPromjena >= 2) {
          drawSparkline(grafX, grafY, grafW, grafH, p.pov, promBoja);
          // % promjene badge (gore lijevo na grafu)
          const promStr = (p.promjenaPct > 0 ? '\u25b2 +' : (p.promjenaPct < 0 ? '\u25bc ' : '\u2013 ')) + Math.abs(p.promjenaPct).toFixed(1) + '%';
          doc.roundedRect(grafX + 5, grafY + 4, 50, 13, 6).fillColor(promBoja).fill();
          doc.fillColor('#fff').font(FBOLD).fontSize(7.5).text(promStr, grafX + 5, grafY + 6.5, { width: 50, align: 'center' });
        } else {
          doc.roundedRect(grafX, grafY, grafW, grafH, 5).fillColor('#fcfaf5').fill();
          doc.roundedRect(grafX, grafY, grafW, grafH, 5).lineWidth(0.6).strokeColor('#e0d6c2').stroke();
          doc.fillColor('#c4baa3').font(FITAL).fontSize(8).text('nema povijesti cijena', grafX, grafY + grafH/2 - 4, { width: grafW, align: 'center' });
        }
        doc.y = cy + cardH + 9;
      }
    }
    drawFooter(pageNum);

    // ─── ZAVRŠETAK ───
    doc.end();
    await pdfDone;
    
    const buf = Buffer.concat(chunks);
    res.set('Content-Type', 'application/pdf');
    res.set('Content-Disposition', `inline; filename="ZBUKA-Cjenik-${godina}.pdf"`);
    res.send(buf);
  } catch (e) {
    console.error('[cjenik export-pdf]:', e.message, e.stack);
    res.status(500).json({ error: e.message });
  }
});

// ── EXPORT ŠIHTERICA — po radniku, po mjesecu, A4 print ready ───────────────
app.get('/api/export/sihterica', auth, admin, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');
    const MJES = ['Siječanj','Veljača','Ožujak','Travanj','Svibanj','Lipanj',
                  'Srpanj','Kolovoz','Rujan','Listopad','Studeni','Prosinac'];
    const DANI_HRV = ['Ned','Pon','Uto','Sri','Čet','Pet','Sub'];

    const radnikIdFilter = req.query.radnik_id ? parseInt(req.query.radnik_id) : null;
    let odFilter  = req.query.od  || null;
    let doFilter  = req.query.do  || null;
    
    // ⭐ v135.7.222: Godišnja šihterica
    //   Use case: Ivan klikne "Godišnja šihterica" gumb → ?godina=2026
    //   Postavlja od/do na cijelu godinu, mijenja filename u Sihterica-2026.xlsx (statično).
    //   Razlog statičnog imena: izbjegava akumulaciju 30+ datumskih fajlova u QNAP folderu.
    const godinaFilter = req.query.godina ? parseInt(req.query.godina) : null;
    if (godinaFilter && godinaFilter >= 2020 && godinaFilter <= 2099) {
      odFilter = `${godinaFilter}-01-01`;
      doFilter = `${godinaFilter}-12-31`;
      console.log(`[export sihterica/godisnja] godina=${godinaFilter}, od=${odFilter}, do=${doFilter}`);
    }

    // Svi zapisi — s opcionim filterima
    let sih;
    try {
      sih = await pool.query(`
        SELECT s.datum, s.sati_redovni,
               COALESCE(s.bolovanje, false) AS bolovanje,
               COALESCE(s.godisnji, false) AS godisnji, COALESCE(s.ne_radi, false) AS ne_radi,
               r.id AS radnik_id, r.ime||' '||r.prezime AS radnik,
               g.naziv AS grad,
               s.pod_naziv
        FROM sihterica s
        JOIN radnici r ON s.radnik_id = r.id
        LEFT JOIN gradilista g ON s.gradiliste_id = g.id   -- ⭐ v903: odsutni (B/G/N) nemaju gradilište — ne smiju ispasti iz exporta
        WHERE ($1::int IS NULL OR s.radnik_id = $1)
          AND ($2::date IS NULL OR s.datum >= $2)
          AND ($3::date IS NULL OR s.datum <= $3)
        ORDER BY r.prezime, r.ime, s.datum
      `, [radnikIdFilter, odFilter, doFilter]);
    } catch {
      sih = await pool.query(`
        SELECT s.datum, s.sati_redovni,
               false AS bolovanje, false AS godisnji, false AS ne_radi,
               r.id AS radnik_id, r.ime||' '||r.prezime AS radnik,
               g.naziv AS grad,
               s.pod_naziv
        FROM sihterica s
        JOIN radnici r ON s.radnik_id = r.id
        LEFT JOIN gradilista g ON s.gradiliste_id = g.id   -- ⭐ v903: odsutni (B/G/N) nemaju gradilište — ne smiju ispasti iz exporta
        WHERE ($1::int IS NULL OR s.radnik_id = $1)
          AND ($2::date IS NULL OR s.datum >= $2)
          AND ($3::date IS NULL OR s.datum <= $3)
        ORDER BY r.prezime, r.ime, s.datum
      `, [radnikIdFilter, odFilter, doFilter]);
    }

    // Grupiraj po radniku
    const byRad = {};
    sih.rows.forEach(row => {
      const key = row.radnik;
      if (!byRad[key]) byRad[key] = { ime: row.radnik, zapisi: [] };
      byRad[key].zapisi.push(row);
    });

    const wb = new ExcelJS.Workbook();
    const C = {
      RED: 'FFCC0000', BLUE: 'FF1F4E79', WHITE: 'FFFFFFFF',
      LIGHT: 'FFF5F5F5', GREY: 'FFD9D9D9', GREEN: 'FFE2EFDA',
      YELLOW: 'FFFFFF00', BOL: 'FFFFF3CD', BOL_TXT: 'FF856404'
    };
    const fill  = h => ({ type: 'pattern', pattern: 'solid', fgColor: { argb: h } });
    const font  = (sz=10, bold=false, col='FF000000') => ({ name: 'Arial', size: sz, bold, color: { argb: col } });
    const aln   = (h='center') => ({ horizontal: h, vertical: 'middle' });
    const brd   = { top:{style:'thin',color:{argb:'FFBBBBBB'}}, bottom:{style:'thin',color:{argb:'FFBBBBBB'}},
                    left:{style:'thin',color:{argb:'FFBBBBBB'}}, right:{style:'thin',color:{argb:'FFBBBBBB'}} };

    for (const [ime, rad] of Object.entries(byRad)) {
      const ws = wb.addWorksheet(safeSheetName(ime, 'Radnik'));
      ws.columns = [
        { width: 5 }, { width: 14 }, { width: 8 }, { width: 32 }, { width: 10 }, { width: 20 }
      ];

      // Grupiraj zapise po godini-mjesecu
      const byMjesec = {};
      rad.zapisi.forEach(z => {
        const d = new Date(z.datum);
        const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
        if (!byMjesec[key]) byMjesec[key] = [];
        byMjesec[key].push(z);
      });

      let currentRow = 1;
      // Page setup jednom za cijeli sheet
      ws.pageSetup = {
        paperSize: 9,           // A4
        orientation: 'portrait',
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,         // neograničeno u visinu
        margins: { left:0.5, right:0.5, top:0.7, bottom:0.7, header:0.3, footer:0.3 }
      };

      const mjKeys = Object.keys(byMjesec).sort();
      for (let mjIdx = 0; mjIdx < mjKeys.length; mjIdx++) {
        const mjKey = mjKeys[mjIdx];
        const zapisi = byMjesec[mjKey];
        const [god, mj] = mjKey.split('-').map(Number);
        const mjes_ime = MJES[mj - 1];
        const num_days = new Date(god, mj, 0).getDate();

        // NASLOV BLOKA
        ws.mergeCells(currentRow, 1, currentRow, 6);
        const titleCell = ws.getCell(currentRow, 1);
        titleCell.value  = `${ime}  —  ${mjes_ime} ${god}`;
        titleCell.fill   = fill(C.RED);
        titleCell.font   = font(12, true, C.WHITE);
        titleCell.alignment = aln('left');
        ws.getRow(currentRow).height = 24;
        currentRow++;

        // ZAGLAVLJE
        const hdrs = ['Rb', 'Datum', 'Dan', 'Gradilište', 'Sati', 'Napomena'];
        hdrs.forEach((h, i) => {
          const c = ws.getCell(currentRow, i + 1);
          c.value = h; c.fill = fill(C.BLUE);
          c.font = font(10, true, C.WHITE);
          c.alignment = aln(); c.border = brd;
        });
        ws.getRow(currentRow).height = 18;
        currentRow++;

        // Mapiranje dana — zbroji duplikate po danu
        // Pod "Vanjsko" s različitim podnazivima se prikazuju kao "Vanjsko / Sesvete"
        const daniMap = {};
        zapisi.forEach(z => {
          const d = new Date(z.datum);
          const day = d.getDate();
          // Spoji grad + pod_naziv u jedinstveni prikaz
          const gradLabel = z.pod_naziv ? `${z.grad} / ${z.pod_naziv}` : z.grad;
          if (!daniMap[day]) {
            daniMap[day] = { ...z, sati_redovni: parseFloat(z.sati_redovni||0), gradovi: [gradLabel], duplikat: false };
          } else {
            daniMap[day].sati_redovni += parseFloat(z.sati_redovni||0);
            daniMap[day].gradovi.push(gradLabel);
            // DUPLIKAT se detektira samo ako je SAME grad + pod_naziv (stvarni duplikat)
            // Različiti poslovi (Vanjsko/Sesvete + Vanjsko/Vrbik) ili različita gradilišta nisu duplikat
            daniMap[day].duplikat = daniMap[day].gradovi.length !== new Set(daniMap[day].gradovi).size;
          }
        });

        let ukupno = 0;
        for (let d = 1; d <= num_days; d++) {
          const dt = new Date(god, mj - 1, d);
          const vikend = dt.getDay() === 0 || dt.getDay() === 6;
          const z = daniMap[d];
          const sati = z ? z.sati_redovni : 0;
          const bol  = z?.bolovanje;
          const god9 = z?.godisnji, ner9 = z?.ne_radi;   // ⭐ v883
          ukupno += sati;
          // Više različitih poslova/gradilišta isti dan = normalan scenarij (split day), nije duplikat
          const viseGradilista = z && z.gradovi && z.gradovi.length > 1;
          const bg = z?.duplikat ? 'FFFFC7CE' : bol ? C.BOL : god9 ? 'FFDBEAFE' : ner9 ? 'FFE5E7EB' : vikend ? C.LIGHT : C.WHITE;
          let napomena = '';
          if (z?.duplikat) napomena = '⚠ DUPLIKAT: ' + z.gradovi.join(' + ');
          else if (bol) napomena = 'Bolovanje';
          else if (god9) napomena = 'Godišnji odmor';
          else if (ner9) napomena = 'Ne radi';
          else if (viseGradilista) napomena = z.gradovi.length + ' posla';
          
          // Ako je više gradilišta bez duplikata, prikaži sva jedno ispod drugog u ćeliji
          const gradDisplay = z 
            ? (viseGradilista ? z.gradovi.join('\n') : (z.gradovi ? z.gradovi[0] : z.grad))
            : '';
          
          const vals = [
            d,
            `${String(d).padStart(2,'0')}.${String(mj).padStart(2,'0')}.${god}`,
            DANI_HRV[dt.getDay()],
            gradDisplay,
            sati || '',
            napomena
          ];
          const fontCol = z?.duplikat ? 'FF9C0006' : bol ? C.BOL_TXT : (vikend ? 'FF888888' : 'FF000000');
          vals.forEach((v, i) => {
            const c = ws.getCell(currentRow, i + 1);
            c.value = v;
            c.fill  = fill(bg);
            c.font  = font(10, z?.duplikat ? true : false, fontCol);
            // Gradilište i Napomena (ako više gradilišta) - lijevo poravnanje + wrap
            if (i === 3 || (i === 5 && viseGradilista)) {
              c.alignment = { horizontal: 'left', vertical: 'middle', wrapText: true };
            } else {
              c.alignment = i === 3 ? aln('left') : aln();
            }
            c.border = brd;
            if (i === 4 && sati) c.numFmt = '0.0';
          });
          // Povećaj visinu reda ako ima više gradilišta
          ws.getRow(currentRow).height = viseGradilista ? Math.max(15, z.gradovi.length * 14) : 15;
          currentRow++;
        }

        // UKUPNO RED
        ws.mergeCells(currentRow, 1, currentRow, 4);
        const uc = ws.getCell(currentRow, 1);
        uc.value = `Ukupno — ${mjes_ime} ${god}`;
        uc.fill = fill(C.GREY); uc.font = font(10, true); uc.alignment = aln('left'); uc.border = brd;
        const sc = ws.getCell(currentRow, 5);
        sc.value = ukupno; sc.fill = fill(C.GREY); sc.font = font(11, true);
        sc.alignment = aln(); sc.border = brd; sc.numFmt = '0.0 "h"';
        ws.getRow(currentRow).height = 20;
        currentRow++;

        // RASPODJELA PO GRADILIŠTU/PODNAZIVU
        // Sumiraj sate po "grad / pod_naziv"
        const raspodjela = {};
        zapisi.forEach(z => {
          if (z.bolovanje || z.godisnji || z.ne_radi) return;
          const k = z.pod_naziv ? `${z.grad} / ${z.pod_naziv}` : z.grad;
          raspodjela[k] = (raspodjela[k] || 0) + parseFloat(z.sati_redovni || 0);
        });
        const raspList = Object.entries(raspodjela).sort((a,b) => b[1] - a[1]);
        
        if (raspList.length > 0) {
          // Header podsažetka
          ws.mergeCells(currentRow, 1, currentRow, 6);
          const rc = ws.getCell(currentRow, 1);
          rc.value = `Raspodjela sati (${raspList.length} ${raspList.length === 1 ? 'gradilište' : 'gradilišta/posla'})`;
          rc.fill = fill('FFEEF6FF'); rc.font = font(9, true, 'FF1F4E79'); 
          rc.alignment = aln('left'); rc.border = brd;
          ws.getRow(currentRow).height = 16;
          currentRow++;
          
          // Retci raspodjele
          raspList.forEach(([naziv, sati]) => {
            ws.mergeCells(currentRow, 1, currentRow, 4);
            const nc = ws.getCell(currentRow, 1);
            nc.value = '  ' + naziv;
            nc.fill = fill('FFF8FBFF'); nc.font = font(9, false);
            nc.alignment = aln('left'); nc.border = brd;
            const sc2 = ws.getCell(currentRow, 5);
            sc2.value = sati; sc2.fill = fill('FFF8FBFF'); sc2.font = font(9);
            sc2.alignment = aln(); sc2.border = brd; sc2.numFmt = '0.0 "h"';
            const pc = ws.getCell(currentRow, 6);
            pc.value = ukupno > 0 ? (sati / ukupno) : 0;
            pc.fill = fill('FFF8FBFF'); pc.font = font(9, false, 'FF666666');
            pc.alignment = aln(); pc.border = brd; pc.numFmt = '0%';
            ws.getRow(currentRow).height = 15;
            currentRow++;
          });
        }

        // Page break NAKON ukupno reda (ispred novog naslova), osim za zadnji mjesec
        if (mjIdx < mjKeys.length - 1) {
          ws.getRow(currentRow - 1).addPageBreak();
        }

      }  // kraj for byMjesec

      if (Object.keys(byMjesec).length === 0) {
        ws.getCell(1, 1).value = 'Nema zapisa';
      }
    }

    // Generiraj buffer
    let buffer;
    try {
      // ⭐ FIX BUG: ako nema niti jednog radnika sa zapisima u tom periodu,
      //    workbook bi ostao bez sheet-ova → ExcelJS generira korumpirani ~5KB file
      //    koji niti Excel niti Google Sheets ne mogu otvoriti.
      //    Rješenje: dodaj fallback sheet "Nema zapisa".
      if (wb.worksheets.length === 0) {
        const ws = wb.addWorksheet('Nema zapisa');
        ws.getCell('A1').value = 'Nema zapisa za odabrani period';
        ws.getCell('A1').font = { name: 'Arial', size: 12, bold: true };
        ws.getCell('A2').value = `Period: ${odFilter || 'sve'} → ${doFilter || 'sve'}`;
        ws.getCell('A2').font = { name: 'Arial', size: 10, italic: true };
        ws.getColumn('A').width = 50;
        console.warn(`[export sihterica] 0 zapisa za period ${odFilter}–${doFilter} — generiran prazan workbook s fallback sheet-om`);
      }
      buffer = await wb.xlsx.writeBuffer();
    } catch(wbErr) {
      console.error('[export sihterica] writeBuffer fail:', wbErr.message, wbErr.stack);
      return res.status(500).json({ error: 'Greška pri generiranju Excela: ' + wbErr.message });
    }
    
    // Provjera da je buffer validni (ne empty)
    if (!buffer || buffer.byteLength < 100) {
      console.error('[export sihterica] empty/invalid buffer:', buffer?.byteLength);
      return res.status(500).json({ error: 'Generirani Excel je prazan ili oštećen' });
    }
    
    // ⭐ v135.7.222: Godišnja šihterica koristi statičko ime (uvijek prepiše isti fajl)
    //   Inače: Sihterica-2026-05-09.xlsx (akumulira se po danima)
    //   Godišnja: Sihterica-2026.xlsx (uvijek prepiše)
    const fname  = godinaFilter
      ? `Sihterica-${godinaFilter}.xlsx`
      : `Sihterica-${_ymd(new Date())}.xlsx`;
    const fnameAscii = fname.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'-');

    res.set({
      'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition': `attachment; filename="${fnameAscii}"; filename*=UTF-8''${encodeURIComponent(fname)}`,
      'Content-Length': buffer.byteLength
    });
    res.send(Buffer.from(buffer));

    // QNAP upload async (best effort, ne blokira response)
    setImmediate(() => {
      qnapUploadExcel(Buffer.from(buffer), `Sihterica/${fname}`)
        .catch(qErr => console.warn('[export sihterica] QNAP upload fail:', qErr.message));
    });

  } catch (e) {
    console.error('[export sihterica] FATAL:', e.message, e.stack);
    if (!res.headersSent) {
      res.status(500).json({ error: 'Server greška: ' + e.message });
    }
  }
});

// ── STARI EXPORT (ostaje za kompatibilnost, ali šalje na novi endpoint) ───────
app.get('/api/export', auth, admin, async (req, res) => {
  res.redirect('/api/export/sihterica');
});



