// ⭐ v135.7.30: Bolovanja za odabrani mjesec — pregled svih radnika s naknadom za bolovanje
app.get('/api/place/bolovanja-sve', auth, direktor, async (req, res) => {
  const { godina, mjesec } = req.query;
  if (!godina || !mjesec) return res.status(400).json({ error: 'Nedostaju godina i mjesec' });
  try {
    const r = await pool.query(`
      SELECT p.radnik_id, p.naknada_bolovanje AS iznos, p.napomena, p.godina, p.mjesec,
             r.ime || ' ' || r.prezime AS radnik_ime,
             (SELECT COUNT(*) FROM sihterica s 
              WHERE s.radnik_id = p.radnik_id 
                AND COALESCE(s.bolovanje, false) = true
                AND EXTRACT(YEAR FROM s.datum)::int = p.godina
                AND EXTRACT(MONTH FROM s.datum)::int = p.mjesec) AS dani_bolovanja
      FROM place_parametri p
      JOIN radnici r ON r.id = p.radnik_id
      WHERE p.godina=$1 AND p.mjesec=$2
        AND COALESCE(p.naknada_bolovanje, 0) > 0
      ORDER BY r.prezime, r.ime
    `, [godina, mjesec]);
    res.json(r.rows);
  } catch(e) { res.status(500).json({ error: e.message }); }
});

