// ⭐ AUDIT #41: PUT endpoint za edit napomene akontacije inline
//    PRIJE: jedini način promjene = delete + re-add (gubi se ID, podaci, datum)
//    SAD: PUT mijenja iznos i/ili napomenu na postojećoj akontaciji
app.put('/api/place/akontacije/:id', auth, direktor, async (req, res) => {
  const { iznos, napomena } = req.body;
  const id = parseInt(req.params.id);
  if (!id) return res.status(400).json({ error: 'Nedostaje ID' });
  
  try {
    // Validacija iznosa ako je poslan
    let iznosNum = null;
    if (iznos !== undefined && iznos !== null) {
      iznosNum = parseFloat(iznos);
      if (isNaN(iznosNum) || iznosNum <= 0 || iznosNum > 100000) {
        return res.status(400).json({ error: 'Iznos mora biti 0-100,000 €' });
      }
    }
    
    // Napomena: trim + max 500 chars + null ako prazno
    let napomenaNorm = null;
    if (napomena !== undefined) {
      napomenaNorm = napomena ? String(napomena).trim().slice(0, 500) : null;
      if (napomenaNorm === '') napomenaNorm = null;
    }
    
    // Dohvati radnik+god+mj PRIJE update-a (za recalc)
    const oldR = await pool.query('SELECT radnik_id, godina, mjesec FROM place_akontacije WHERE id=$1', [id]);
    if (!oldR.rows.length) return res.status(404).json({ error: 'Akontacija ne postoji' });
    const old = oldR.rows[0];
    
    // Conditional UPDATE — samo polja koja su poslana
    const updates = [];
    const params = [];
    let pIdx = 1;
    if (iznosNum !== null) {
      updates.push(`iznos = $${pIdx++}`);
      params.push(iznosNum);
    }
    if (napomena !== undefined) {
      updates.push(`napomena = $${pIdx++}`);
      params.push(napomenaNorm);
    }
    if (!updates.length) return res.status(400).json({ error: 'Nema polja za izmjenu (iznos ili napomena)' });
    
    params.push(id);
    const r = await pool.query(
      `UPDATE place_akontacije SET ${updates.join(', ')} WHERE id = $${pIdx} RETURNING *`,
      params
    );
    res.json(r.rows[0]);
    
    // Auto-recalc pretplate ako je iznos promijenjen
    if (iznosNum !== null) {
      setImmediate(async () => {
        try {
          await _recalcPretplataKaskadno(old.radnik_id, old.godina, old.mjesec); // ⭐ v238: kaskadno
        } catch(eRecalc) {
          console.warn('[place/akontacije PUT] kaskadni recalc fail:', eRecalc.message);
        }
      });
    }
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Kredit — dodaj novi
// ⭐ v135.7.124 (BUG FIX PLA-04): krediti audit logger (best-effort, ne ruši glavnu operaciju)
async function logKreditAudit(client, kreditId, akcija, prijasnji, novi, user) {
  try {
    const izvrsioIme = user ? `${user.ime || ''} ${user.prezime || ''}`.trim() : null;
    await (client || pool).query(
      `INSERT INTO krediti_audit (kredit_id, akcija, prijasnji_podaci, novi_podaci, izvrsio_id, izvrsio_ime)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [kreditId, akcija, prijasnji ? JSON.stringify(prijasnji) : null, novi ? JSON.stringify(novi) : null, user?.id || null, izvrsioIme]
    );
  } catch(e) {
    console.warn('[krediti audit log fail]', e.message);
  }
}

app.post('/api/krediti', auth, direktor, async (req, res) => {
  const { radnik_id, ukupno, datum_pocetka, napomena } = req.body;
  if (!radnik_id || !ukupno) return res.status(400).json({ error: 'Nedostaju podaci' });
  // AUDIT FIX 4.1.9: validacije ukupno (mora biti pozitivan, max 500k)
  const ukNum = parseFloat(ukupno);
  if (isNaN(ukNum) || ukNum <= 0 || ukNum > 500000) {
    return res.status(400).json({ error: 'Ukupni iznos kredita mora biti 0-500000 €' });
  }
  // AUDIT FIX: atomic transakcija (deaktivacija starog + novi)
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Snimi prijašnji aktivni kredit ako postoji (za audit)
    const prevQ = await client.query("SELECT * FROM krediti WHERE radnik_id=$1 AND aktivan=true LIMIT 1", [radnik_id]);
    const prevKredit = prevQ.rows[0] || null;
    
    await client.query("UPDATE krediti SET aktivan=false WHERE radnik_id=$1 AND aktivan=true", [radnik_id]);
    const r = await client.query(`
      INSERT INTO krediti (radnik_id, ukupno, datum_pocetka, napomena)
      VALUES ($1,$2,$3,$4) RETURNING *
    `, [radnik_id, ukNum, datum_pocetka || danasZagreb(), String(napomena||'').slice(0, 500)]);
    
    // ⭐ v135.7.124: Audit log
    if (prevKredit) {
      await logKreditAudit(client, prevKredit.id, 'close_for_new', prevKredit, null, req.user);
    }
    await logKreditAudit(client, r.rows[0].id, 'create', null, r.rows[0], req.user);
    
    await client.query('COMMIT');
    res.json(r.rows[0]);
  } catch (e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

// Kredit — deaktiviraj (otplaćen)
app.put('/api/krediti/:id/zatvori', auth, direktor, async (req, res) => {
  try {
    // ⭐ v135.7.124 (PLA-04): Snimi prije + log
    const prev = await pool.query("SELECT * FROM krediti WHERE id=$1", [req.params.id]);
    if (!prev.rows.length) return res.status(404).json({ error: 'Kredit ne postoji' });
    await pool.query("UPDATE krediti SET aktivan=false WHERE id=$1", [req.params.id]);
    await logKreditAudit(null, parseInt(req.params.id), 'close', prev.rows[0], { ...prev.rows[0], aktivan: false }, req.user);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ⭐ v135.7.153: Reaktiviraj zatvoreni kredit
//   Razlog: korisnik može pogriješno kliknuti "otplaćen" — sad može vratiti
//   bez ručnog ponovnog unosa.
//   Logika: ako radnik već ima drugi aktivni kredit, vrati 409 (treba prvo
//   zatvoriti taj). Inače: aktivan=true.
app.put('/api/krediti/:id/reaktiviraj', auth, direktor, async (req, res) => {
  try {
    const prev = await pool.query("SELECT * FROM krediti WHERE id=$1", [req.params.id]);
    if (!prev.rows.length) return res.status(404).json({ error: 'Kredit ne postoji' });
    if (prev.rows[0].aktivan) return res.status(400).json({ error: 'Kredit je već aktivan' });
    
    // Provjeri ima li radnik drugi aktivni kredit (jedan po radniku)
    const drugiAktivni = await pool.query(
      "SELECT id FROM krediti WHERE radnik_id=$1 AND aktivan=true AND id != $2 LIMIT 1",
      [prev.rows[0].radnik_id, req.params.id]
    );
    if (drugiAktivni.rows.length) {
      return res.status(409).json({ 
        error: 'Radnik već ima drugi aktivni kredit. Prvo ga zatvori.' 
      });
    }
    
    await pool.query("UPDATE krediti SET aktivan=true WHERE id=$1", [req.params.id]);
    await logKreditAudit(null, parseInt(req.params.id), 'reopen', prev.rows[0], { ...prev.rows[0], aktivan: true }, req.user);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});


// DELETE kredit
app.delete('/api/krediti/:id', auth, direktor, async (req, res) => {
  // AUDIT FIX: atomic transakcija (otplate + kredit)
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // ⭐ v135.7.124 (PLA-04): Snimi prije brisanja + log
    const prev = await client.query("SELECT * FROM krediti WHERE id=$1", [req.params.id]);
    const prevOtplate = await client.query("SELECT * FROM krediti_otplate WHERE kredit_id=$1", [req.params.id]);
    
    await client.query('DELETE FROM krediti_otplate WHERE kredit_id=$1', [req.params.id]);
    await client.query('DELETE FROM krediti WHERE id=$1', [req.params.id]);
    
    if (prev.rows[0]) {
      await logKreditAudit(client, parseInt(req.params.id), 'delete', 
        { kredit: prev.rows[0], otplate_count: prevOtplate.rows.length, otplate_total: prevOtplate.rows.reduce((s,o) => s + parseFloat(o.iznos||0), 0) }, 
        null, req.user);
    }
    
    await client.query('COMMIT');
    res.json({ ok: true });
  } catch(e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

