// Rata kredita — spremi/ažuriraj za ovaj mjesec
app.post('/api/krediti/rata', auth, direktor, async (req, res) => {
  const { kredit_id, radnik_id, godina, mjesec, iznos } = req.body;
  if (!kredit_id || !iznos) return res.status(400).json({ error: 'Nedostaju podaci' });
  
  // ⭐ AUDIT #14: Validacija da rata ne prelazi preostali kredit
  //    PRIJE: mogla se upisati rata 1000€ za kredit od 500€ → kredit u nelogičnom stanju
  //    SAD: server provjerava SUM(otplate) ≤ ukupno (uvijek, čak i pri UPDATE-u postojeće rate)
  const noviIznos = parseFloat(iznos);
  if (isNaN(noviIznos) || noviIznos <= 0) {
    return res.status(400).json({ error: 'Iznos mora biti veći od 0' });
  }
  if (noviIznos > 100000) {
    return res.status(400).json({ error: 'Iznos rate prevelik (max 100,000 €)' });
  }
  
  try {
    // ⭐ v434 (Ivan final audit, kritičan fix): wrap u transakciji s FOR UPDATE row lock-om.
    //   Race condition prije: read otplaceno_bez_trenutne pa onda INSERT — drugi paralelan
    //   request može unijeti rate između, što rezultira sa otplata > kredit. Sad: BEGIN +
    //   SELECT FOR UPDATE locks kredit row dok ne COMMIT.
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      
      // Lock kredit row tijekom cijele transakcije
      const kreditR = await client.query('SELECT ukupno FROM krediti WHERE id=$1 FOR UPDATE', [kredit_id]);
      if (!kreditR.rows.length) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Kredit ne postoji' });
      }
      const ukupno = parseFloat(kreditR.rows[0].ukupno);
      
      // Suma svih otplata OSIM trenutne (ako mijenjamo postojeću ratu, ne brojimo je dvaput)
      const otplateR = await client.query(`
        SELECT COALESCE(SUM(iznos), 0) AS uk
        FROM krediti_otplate
        WHERE kredit_id=$1 AND NOT (godina=$2 AND mjesec=$3)
      `, [kredit_id, godina, mjesec]);
      const otplaceno_bez_trenutne = parseFloat(otplateR.rows[0].uk);
      
      const preostalo = ukupno - otplaceno_bez_trenutne;
      if (noviIznos > preostalo + 0.01) {
        await client.query('ROLLBACK');
        return res.status(400).json({ 
          error: `Rata ${noviIznos.toFixed(2)}€ je veća od preostalog kredita ${preostalo.toFixed(2)}€ (ukupno ${ukupno.toFixed(2)}€ − otplaćeno ${otplaceno_bez_trenutne.toFixed(2)}€)` 
        });
      }
      
      const r = await client.query(`
        INSERT INTO krediti_otplate (kredit_id, radnik_id, godina, mjesec, iznos)
        VALUES ($1,$2,$3,$4,$5)
        ON CONFLICT (kredit_id, godina, mjesec) DO UPDATE SET iznos = EXCLUDED.iznos
        RETURNING *
      `, [kredit_id, radnik_id, godina, mjesec, noviIznos]);
      
      await client.query('COMMIT');
      res.json(r.rows[0]);
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Export Excel isplatnih lista — formatirano s ExcelJS (identično v4 demu)
// ⭐ AUDIT #45: GET /api/place/godisnji-izvjestaj?godina=X[&radnik_id=Y]
//    Generira Excel s mjesečnim pregledom plaća za cijelu godinu (jedan radnik ili svi)
//    Stupci: Mjesec | Sati | Bruto | Akontacije | Pretplata | Isplata | Napomena
//    Reds: 12 mjeseca + ukupno red
app.get('/api/place/godisnji-izvjestaj', auth, direktor, async (req, res) => {
  const godina = parseInt(req.query.godina);
  const radnik_id = req.query.radnik_id ? parseInt(req.query.radnik_id) : null;
  if (!godina || godina < 2020 || godina > 2050) {
    return res.status(400).json({ error: 'Nevažeća godina (2020-2050)' });
  }
  
  try {
    const ExcelJS = require('exceljs');
    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Čakarić d.o.o.';
    wb.created = new Date();
    
    const C = { 
      RED: 'FFCC0000', BLUE: 'FF1F4E79', GREEN: 'FFE2EFDA', 
      YELLOW: 'FFFFFFF0', GREY: 'FFD9D9D9', WHITE: 'FFFFFFFF', 
      LIGHT: 'FFF2F2F2', ORANGE: 'FFED7D31' 
    };
    const fill = h => ({ type: 'pattern', pattern: 'solid', fgColor: { argb: h } });
    const font = (sz=10, bold=false, c='FF000000') => ({ name: 'Arial', size: sz, bold, color: { argb: c } });
    const aln = (h='center') => ({ horizontal: h, vertical: 'middle' });
    const brd = { top:{style:'thin',color:{argb:'FFAAAAAA'}}, bottom:{style:'thin',color:{argb:'FFAAAAAA'}},
                  left:{style:'thin',color:{argb:'FFAAAAAA'}}, right:{style:'thin',color:{argb:'FFAAAAAA'}} };
    const MJES = ['Siječanj','Veljača','Ožujak','Travanj','Svibanj','Lipanj',
                  'Srpanj','Kolovoz','Rujan','Listopad','Studeni','Prosinac'];
    
    // Dohvati radnike (jedan ili svi)
    // ⭐ v135.7.159: Uključi bez_ciscenja_stana flag
    // ⭐ v135.7.174: Uključi i deaktivirane radnike koji su radili u toj godini
    //   (deaktivacija = u istoj ili kasnijoj godini). Bez ovoga, ako radnik 
    //   radi 6 mjeseci pa se deaktivira, godišnji izvještaj ga ne pokazuje 
    //   uopće — što gubi važan zapis o izvršenom radu.
    const radniciR = await pool.query(
      radnik_id 
        ? `SELECT id, ime, prezime, aktivan, datum_deaktivacije, COALESCE(bez_ciscenja_stana,false) AS bez_ciscenja_stana 
           FROM radnici WHERE id=$1
             AND (
               aktivan = true
               OR (aktivan = false AND datum_deaktivacije IS NOT NULL 
                   AND EXTRACT(YEAR FROM datum_deaktivacije) >= $2::int)
             )`
        : `SELECT id, ime, prezime, aktivan, datum_deaktivacije, COALESCE(bez_ciscenja_stana,false) AS bez_ciscenja_stana 
           FROM radnici 
           WHERE (role IS NULL OR role != 'direktor')
             AND (
               aktivan = true
               OR (aktivan = false AND datum_deaktivacije IS NOT NULL 
                   AND EXTRACT(YEAR FROM datum_deaktivacije) >= $1::int)
             )
           ORDER BY aktivan DESC, prezime, ime`,
      radnik_id ? [radnik_id, godina] : [godina]
    );
    
    if (!radniciR.rows.length) {
      return res.status(404).json({ error: 'Nema radnika' });
    }
    
    // ⭐ AUDIT FIX (Ivan): ako su odabrani SVI radnici, dodaj prvi list "UKUPNO" sa zbrojima po mjesecima
    // Ovo je sumarni pregled koji pokazuje koliko firma godišnje troši na plaće
    let sumarniMjeseci = null;
    if (!radnik_id) {
      // Inicijaliziraj agregaciju
      sumarniMjeseci = Array.from({length: 12}, () => ({
        sati: 0, bruto: 0, akontacije: 0, pretplata: 0, isplata: 0, broj_radnika: 0
      }));
    }
    
    // Skupljanje agregata se događa kroz radnik petlju ispod (popuni sumarniMjeseci)
    
    for (const rad of radniciR.rows) {
      const sheetName = `${rad.prezime} ${rad.ime}`.replace(/[\\/?*[\]:]/g, '_').slice(0, 30);
      const ws = wb.addWorksheet(sheetName, {
        pageSetup: { paperSize: 9, orientation: 'portrait', fitToPage: true, fitToWidth: 1, fitToHeight: 0,
                    margins: { left: 0.4, right: 0.4, top: 0.4, bottom: 0.4, header: 0.2, footer: 0.2 } }
      });
      ws.columns = [
        { width: 14 }, { width: 9 }, { width: 13 }, { width: 13 }, 
        { width: 13 }, { width: 13 }, { width: 35 }
      ];
      
      // HEADER
      let r = 1;
      ws.mergeCells(r, 1, r, 7);
      const hc = ws.getCell(r, 1);
      hc.value = `GODIŠNJI IZVJEŠTAJ PLAĆA — ${rad.ime} ${rad.prezime} (${godina})`;
      hc.fill = fill(C.RED); hc.font = font(14, true, 'FFFFFFFF'); hc.alignment = aln('center');
      ws.getRow(r).height = 26;
      r += 2;
      
      // ZAGLAVLJE TABLICE
      ['Mjesec', 'Sati', 'Bruto', 'Akontacije', 'Pretplata', 'Isplata', 'Napomena'].forEach((h, i) => {
        const c = ws.getCell(r, i+1);
        c.value = h; c.fill = fill(C.BLUE); c.font = font(11, true, 'FFFFFFFF');
        c.alignment = aln(); c.border = brd;
      });
      ws.getRow(r).height = 18;
      r++;
      
      // Mjeseci
      let uk_sati = 0, uk_bruto = 0, uk_akont = 0, uk_pretpl = 0, uk_isplata = 0;
      for (let mj = 1; mj <= 12; mj++) {
        // Sati za mjesec
        const sihR = await pool.query(`
          SELECT COALESCE(SUM(CASE WHEN COALESCE(bolovanje,false) THEN 0 ELSE sati_redovni END), 0) AS sati
          FROM sihterica
          WHERE radnik_id=$1 AND EXTRACT(YEAR FROM datum)::int=$2 AND EXTRACT(MONTH FROM datum)::int=$3
        `, [rad.id, godina, mj]);
        const sati = parseFloat(sihR.rows[0]?.sati || 0);
        
        // Parametri
        const paramR = await pool.query(`
          SELECT * FROM place_parametri WHERE radnik_id=$1 AND godina=$2 AND mjesec=$3
        `, [rad.id, godina, mj]);
        const p = paramR.rows[0] || {};
        
        // Akontacije
        const akR = await pool.query(`
          SELECT COALESCE(SUM(iznos),0) AS uk FROM place_akontacije
          WHERE radnik_id=$1 AND godina=$2 AND mjesec=$3
        `, [rad.id, godina, mj]);
        const akontacije = parseFloat(akR.rows[0]?.uk || 0);
        
        // Kredit rata
        let kreditRata = 0;
        try {
          const krR = await pool.query(`
            SELECT COALESCE(SUM(ko.iznos),0) AS rata FROM krediti_otplate ko
            JOIN krediti k ON k.id = ko.kredit_id
            WHERE k.radnik_id=$1 AND ko.godina=$2 AND ko.mjesec=$3
          `, [rad.id, godina, mj]);
          kreditRata = parseFloat(krR.rows[0]?.rata || 0);
        } catch(_) {}
        
        // Single source of truth
        // ⭐ v135.7.159: bez_ciscenja_stana flag iz radnika
        const payout = calculatePayout({
          sati, satnica: p.satnica, bonus: p.bonus,
          naknada_bolovanje: p.naknada_bolovanje, isplata_prosli_mj: p.isplata_prosli_mj,
          godisnji: p.godisnji, placa_racun: p.placa_racun, terenska: p.terenska,
          ciscenje: p.ciscenje, pretplata: p.pretplata, akontacije, kredit_rata: kreditRata,
          bez_ciscenja_stana: rad.bez_ciscenja_stana
        });
        
        const napomena = (p.napomena || '').slice(0, 200);
        const fillC = (mj % 2 === 0) ? C.WHITE : C.LIGHT;
        
        ws.getCell(r, 1).value = MJES[mj-1];
        ws.getCell(r, 2).value = sati;
        ws.getCell(r, 3).value = payout.bruto;
        ws.getCell(r, 4).value = akontacije;
        ws.getCell(r, 5).value = parseFloat(p.pretplata || 0);
        ws.getCell(r, 6).value = payout.isplata;
        ws.getCell(r, 7).value = napomena;
        
        for (let col = 1; col <= 7; col++) {
          const c = ws.getCell(r, col);
          c.fill = fill(fillC); c.font = font(10); c.border = brd;
          c.alignment = aln(col === 1 ? 'left' : (col === 7 ? 'left' : 'center'));
          if (col >= 2 && col <= 6) c.numFmt = (col === 2 ? '0.0' : '#,##0.00 €');
          if (col === 6) {
            c.font = font(10, true, payout.isplata < 0 ? 'FFCC0000' : 'FF1E7145');
          }
        }
        
        uk_sati += sati;
        uk_bruto += payout.bruto;
        uk_akont += akontacije;
        uk_pretpl += parseFloat(p.pretplata || 0);
        uk_isplata += payout.isplata;
        
        // ⭐ AUDIT FIX: Agregiraj u sumarni list (samo ako su odabrani svi radnici)
        if (sumarniMjeseci) {
          sumarniMjeseci[mj-1].sati += sati;
          sumarniMjeseci[mj-1].bruto += payout.bruto;
          sumarniMjeseci[mj-1].akontacije += akontacije;
          sumarniMjeseci[mj-1].pretplata += parseFloat(p.pretplata || 0);
          sumarniMjeseci[mj-1].isplata += payout.isplata;
          if (payout.bruto > 0) sumarniMjeseci[mj-1].broj_radnika++;
        }
        
        r++;
      }
      
      // UKUPNO red
      ws.getCell(r, 1).value = 'UKUPNO';
      ws.getCell(r, 2).value = uk_sati;
      ws.getCell(r, 3).value = parseFloat(uk_bruto.toFixed(2));
      ws.getCell(r, 4).value = parseFloat(uk_akont.toFixed(2));
      ws.getCell(r, 5).value = parseFloat(uk_pretpl.toFixed(2));
      ws.getCell(r, 6).value = parseFloat(uk_isplata.toFixed(2));
      ws.getCell(r, 7).value = '';
      for (let col = 1; col <= 7; col++) {
        const c = ws.getCell(r, col);
        c.fill = fill(C.GREEN); c.font = font(11, true); c.border = brd;
        c.alignment = aln(col === 1 ? 'left' : 'center');
        if (col >= 2 && col <= 6) c.numFmt = (col === 2 ? '0.0' : '#,##0.00 €');
      }
    }
    
    // ⭐ AUDIT FIX: Kreiraj sumarni list "UKUPNO" sa svim mjesecima (samo ako su odabrani svi radnici)
    if (sumarniMjeseci) {
      const wsSum = wb.addWorksheet('UKUPNO', {
        pageSetup: { paperSize: 9, orientation: 'portrait', fitToPage: true, fitToWidth: 1, fitToHeight: 0,
                    margins: { left: 0.4, right: 0.4, top: 0.4, bottom: 0.4, header: 0.2, footer: 0.2 } }
      });
      wsSum.columns = [
        { width: 14 }, { width: 9 }, { width: 13 }, { width: 13 }, 
        { width: 13 }, { width: 13 }, { width: 11 }
      ];
      
      // HEADER
      let r = 1;
      wsSum.mergeCells(r, 1, r, 7);
      const hc = wsSum.getCell(r, 1);
      hc.value = `UKUPNO PLAĆE PO MJESECIMA — SVI RADNICI (${godina})`;
      hc.fill = fill(C.RED); hc.font = font(14, true, 'FFFFFFFF'); hc.alignment = aln('center');
      wsSum.getRow(r).height = 26;
      r += 2;
      
      // ZAGLAVLJE TABLICE
      ['Mjesec', 'Sati', 'Bruto', 'Akontacije', 'Pretplata', 'Isplata', 'Aktivno radn.'].forEach((h, i) => {
        const c = wsSum.getCell(r, i+1);
        c.value = h; c.fill = fill(C.BLUE); c.font = font(11, true, 'FFFFFFFF');
        c.alignment = aln(); c.border = brd;
      });
      wsSum.getRow(r).height = 18;
      r++;
      
      // 12 mjeseci
      let g_sati = 0, g_bruto = 0, g_akont = 0, g_pretpl = 0, g_isplata = 0;
      for (let mj = 1; mj <= 12; mj++) {
        const sm = sumarniMjeseci[mj-1];
        const fillC = (mj % 2 === 0) ? C.WHITE : C.LIGHT;
        
        wsSum.getCell(r, 1).value = MJES[mj-1];
        wsSum.getCell(r, 2).value = sm.sati;
        wsSum.getCell(r, 3).value = parseFloat(sm.bruto.toFixed(2));
        wsSum.getCell(r, 4).value = parseFloat(sm.akontacije.toFixed(2));
        wsSum.getCell(r, 5).value = parseFloat(sm.pretplata.toFixed(2));
        wsSum.getCell(r, 6).value = parseFloat(sm.isplata.toFixed(2));
        wsSum.getCell(r, 7).value = sm.broj_radnika;
        
        for (let col = 1; col <= 7; col++) {
          const c = wsSum.getCell(r, col);
          c.fill = fill(fillC); c.font = font(10); c.border = brd;
          c.alignment = aln(col === 1 ? 'left' : 'center');
          if (col >= 2 && col <= 6) c.numFmt = (col === 2 ? '0.0' : '#,##0.00 €');
          if (col === 6) {
            c.font = font(10, true, sm.isplata < 0 ? 'FFCC0000' : 'FF1E7145');
          }
        }
        
        g_sati += sm.sati;
        g_bruto += sm.bruto;
        g_akont += sm.akontacije;
        g_pretpl += sm.pretplata;
        g_isplata += sm.isplata;
        r++;
      }
      
      // GODIŠNJI UKUPNO red
      wsSum.getCell(r, 1).value = 'UKUPNO ' + godina;
      wsSum.getCell(r, 2).value = g_sati;
      wsSum.getCell(r, 3).value = parseFloat(g_bruto.toFixed(2));
      wsSum.getCell(r, 4).value = parseFloat(g_akont.toFixed(2));
      wsSum.getCell(r, 5).value = parseFloat(g_pretpl.toFixed(2));
      wsSum.getCell(r, 6).value = parseFloat(g_isplata.toFixed(2));
      wsSum.getCell(r, 7).value = '';
      for (let col = 1; col <= 7; col++) {
        const c = wsSum.getCell(r, col);
        c.fill = fill(C.GREEN); c.font = font(12, true); c.border = brd;
        c.alignment = aln(col === 1 ? 'left' : 'center');
        if (col >= 2 && col <= 6) c.numFmt = (col === 2 ? '0.0' : '#,##0.00 €');
      }
      wsSum.getRow(r).height = 22;
      r += 2;
      
      // Mali komentar
      wsSum.mergeCells(r, 1, r, 7);
      const cmt = wsSum.getCell(r, 1);
      cmt.value = `Detaljni izvještaji po radniku — vidjeti ostale tabove ispod ↓`;
      cmt.font = font(10, false, 'FF666666'); cmt.alignment = aln('center');
      
      // ⭐ Premjesti sumarni list na PRVO mjesto (defaultno se dodaje na kraj)
      // ExcelJS workbook ima order pristup
      try {
        // Ukloni i ponovo dodaj na poziciju 0
        const sumIdx = wb.worksheets.findIndex(w => w.name === 'UKUPNO');
        if (sumIdx > 0) {
          const sumSheet = wb.worksheets[sumIdx];
          wb.worksheets.splice(sumIdx, 1);
          wb.worksheets.unshift(sumSheet);
        }
      } catch(e) {
        console.warn('[godisnji UKUPNO sheet order]', e.message);
        // Nije kritično ako ne uspije reorder, sheet je svejedno dodan
      }
    }
    
    const fname = radnik_id 
      ? `Godisnji_${radniciR.rows[0].prezime}_${radniciR.rows[0].ime}_${godina}.xlsx`
      : `Godisnji_Svi_radnici_${godina}.xlsx`;
    const safeFname = safeAsciiFilename(fname);
    
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    // ⭐ v501.96: Cache-Control no-store osigurava svježe podatke
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Content-Disposition', `attachment; filename="${safeFname}"; filename*=UTF-8''${encodeURIComponent(fname)}`);
    
    const buf = await wb.xlsx.writeBuffer();
    res.send(Buffer.from(buf));
  } catch(e) {
    console.error('[godisnji-izvjestaj]', e);
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/place/export', auth, direktor, async (req, res) => {
  const { godina, mjesec } = req.query;
  if (!godina || !mjesec) return res.status(400).json({ error: 'Nedostaje godina/mjesec' });
  // ⭐ v643 (Ivan, feature): opcionalni radnik_id → export SAMO tog radnika za taj mjesec.
  //   Kad je zadan, generira se jedan sheet + ime datoteke po radniku. Bez njega = ponašanje kao prije
  //   (svi radnici). Ista logika/format/obračun (calculatePayout, satnica carry) → 1:1 konzistentno s ekranom.
  const radnik_id = req.query.radnik_id ? parseInt(req.query.radnik_id) : null;
  if (req.query.radnik_id && (!radnik_id || radnik_id < 1)) return res.status(400).json({ error: 'Neispravan radnik_id' });
  try {
    // ⭐ AUDIT #2: Excel verify protiv frontend kalkulacije
    //    PRIJE: Excel generator koristi vlastite formule (npr. fallback `<=` u getSatnica),
    //          frontend full-check koristi `<` → mogu pokazivati DRUGE vrijednosti.
    //          Računovođa dobiva nekonzistentne podatke.
    //    SAD: prije generiranja Excela, pozovi `_recalcPretplataMjesec` za sve aktivne radnike
    //          → pretplate sljedećeg mjeseca su sinkronizirane sa stvarnim isplatama
    //    Time je Excel uvijek konzistentan s onim što UI prikazuje.
    try {
      // ⭐ v135.7.174: Uključi i deaktivirane radnike koji su radili u ovom 
      //   mjesecu (deaktivacija je bila u istom ili kasnijem mjesecu).
      //   Inače Excel ima njihove podatke ali pretplata nije recalculirana.
      const radniciR = await pool.query(`
        SELECT id FROM radnici 
        WHERE (role IS NULL OR role != 'direktor')
          AND ($3::int IS NULL OR id = $3::int)
          AND (
            aktivan = true
            OR (
              aktivan = false
              AND datum_deaktivacije IS NOT NULL
              AND (
                EXTRACT(YEAR FROM datum_deaktivacije) > $1::int
                OR (
                  EXTRACT(YEAR FROM datum_deaktivacije) = $1::int
                  AND EXTRACT(MONTH FROM datum_deaktivacije) >= $2::int
                )
              )
            )
          )
      `, [parseInt(godina), parseInt(mjesec), radnik_id]);
      for (const rad of radniciR.rows) {
        try {
          await _recalcPretplataMjesec(rad.id, parseInt(godina), parseInt(mjesec));
        } catch(e) {
          console.warn(`[place/export pre-recalc] radnik ${rad.id}:`, e.message);
        }
      }
      console.log(`[place/export] pre-recalc završen za ${radniciR.rows.length} radnika (${godina}/${mjesec})`);
    } catch(e) {
      console.warn('[place/export pre-recalc skipped]:', e.message);
      // Ne ruši export ako pre-recalc fail-a — bolje stari Excel nego ništa
    }
    
    const ExcelJS = require('exceljs');
    const MJES = ['Siječanj','Veljača','Ožujak','Travanj','Svibanj','Lipanj',
                  'Srpanj','Kolovoz','Rujan','Listopad','Studeni','Prosinac'];
    const mjes_ime = MJES[parseInt(mjesec)-1];
    const num_days = new Date(godina, mjesec, 0).getDate();
    const dani_hrv = ['Ned','Pon','Uto','Sri','Čet','Pet','Sub'];

    // Boje
    const C = {
      RED:    'FFCC0000', BLUE:   'FF1F4E79', GREEN:  'FFE2EFDA',
      YELLOW: 'FFFFFFF0', GREY:   'FFD9D9D9', WHITE:  'FFFFFFFF',
      LIGHT:  'FFF2F2F2', PURPLE: 'FF7030A0', ORANGE: 'FFED7D31',
    };

    const fill = hex => ({ type: 'pattern', pattern: 'solid', fgColor: { argb: hex } });
    const font = (sz=10, bold=false, color='FF000000') => ({ name: 'Arial', size: sz, bold, color: { argb: color } });
    const aln = (h='center') => ({ horizontal: h, vertical: 'middle' });
    const brd = { top:{style:'thin',color:{argb:'FFAAAAAA'}}, bottom:{style:'thin',color:{argb:'FFAAAAAA'}},
                  left:{style:'thin',color:{argb:'FFAAAAAA'}}, right:{style:'thin',color:{argb:'FFAAAAAA'}} };
    const brdT = { top:{style:'medium',color:{argb:'FF444444'}}, bottom:{style:'medium',color:{argb:'FF444444'}},
                   left:{style:'medium',color:{argb:'FF444444'}}, right:{style:'medium',color:{argb:'FF444444'}} };

    const wb = new ExcelJS.Workbook();

    const radnici = await pool.query(`
      SELECT r.id, r.ime, r.prezime, COALESCE(r.bez_ciscenja_stana, false) AS bez_ciscenja_stana,
             -- ⭐ v135.7.502.20.72: satnica poštuje satnica_set (isto kao GET /api/place carry).
             --   Ako lokalna satnica NIJE ručno postavljena (satnica_set=false / nema zapisa) →
             --   uzmi zadnju RUČNO postavljenu (ili bilo koju ≠ naslijeđeni default) iz prošlosti.
             --   Time je PDF izvoz konzistentan s ekranom (inače bi izvoz pokazao 8.00 a UI 6.90).
             COALESCE(
               CASE WHEN COALESCE(p.satnica_set, false) = true THEN p.satnica ELSE NULL END,
               (SELECT pp.satnica FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                AND pp.satnica IS NOT NULL
                AND (COALESCE(pp.satnica_set, false) = true OR pp.satnica <> 8.00)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1),
               p.satnica, 8) AS satnica,
             COALESCE(p.bonus,
               (SELECT bonus FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS bonus,
             COALESCE(p.placa_racun,
               (SELECT placa_racun FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS placa_racun,
             COALESCE(p.terenska,
               (SELECT terenska FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS terenska,
             COALESCE(p.ciscenje,
               (SELECT ciscenje FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 15) AS ciscenje,
             COALESCE(p.pretplata, 0) AS pretplata,
             COALESCE(p.naknada_bolovanje,
               (SELECT naknada_bolovanje FROM place_parametri pp WHERE pp.radnik_id=r.id
                AND (pp.godina*12+pp.mjesec) <= ($1::int*12+$2::int)
                ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS naknada_bolovanje,
             COALESCE(p.godisnji, 0) AS godisnji,   -- ⭐ v839 (Ivan): kolona je FALILA → rad.godisnji undefined → red se nikad nije prikazao
             COALESCE(p.isplata_prosli_mj, 0) AS isplata_prosli_mj,
             COALESCE(p.napomena, '') AS napomena
      FROM radnici r
      LEFT JOIN place_parametri p ON p.radnik_id=r.id AND p.godina=$1 AND p.mjesec=$2
      WHERE r.role != 'direktor'
        AND ($3::int IS NULL OR r.id = $3::int)
        AND (
          -- Aktivni radnik → uvijek uključen
          r.aktivan = true
          OR (
            -- ⭐ v135.7.174: Deaktivirani radnik → uključen ako je deaktiviran 
            --   u OVOM ili KASNIJEM mjesecu od onoga koji se exporta.
            --   Razlog: ako je radnik deaktiviran 15.04, treba se pojaviti u 
            --   travanjskoj platnoj listi (radio prvi pola mjeseca), ali NE 
            --   i u svibanjskoj. Ista logika kao /api/place GET.
            r.aktivan = false
            AND r.datum_deaktivacije IS NOT NULL
            AND (
              EXTRACT(YEAR FROM r.datum_deaktivacije) > $1::int
              OR (
                EXTRACT(YEAR FROM r.datum_deaktivacije) = $1::int
                AND EXTRACT(MONTH FROM r.datum_deaktivacije) >= $2::int
              )
            )
          )
        )
      ORDER BY r.aktivan DESC, r.prezime, r.ime
    `, [godina, mjesec, radnik_id]);

    // ⭐ v643: tražen konkretan radnik a nema ga (ne postoji / direktor / nije radio taj mj) → 404 umjesto praznog Excela
    if (radnik_id && !radnici.rows.length) return res.status(404).json({ error: 'Radnik nema podataka za taj mjesec' });

    // ⭐ v326 (Ivan, O4): BATCH pre-fetch — 3 query-ja umjesto N×3. Dokazivo ekvivalentno (kao GET /api/place).
    const _radIds2 = radnici.rows.map(r => r.id);
    const _satiMap2 = {}, _akontMap2 = {}, _kredMap2 = {};
    if (_radIds2.length) {
      const _satiAll2 = await pool.query(`
        SELECT s.radnik_id, EXTRACT(DAY FROM s.datum)::int AS dan,
               SUM(s.sati_redovni) AS sati,
               STRING_AGG(DISTINCT g.naziv, ', ') AS gradilista,
               BOOL_OR(COALESCE(s.bolovanje, false)) AS ima_bolovanje,
               BOOL_OR(COALESCE(s.godisnji, false)) AS ima_godisnji,   -- ⭐ v904
               BOOL_OR(COALESCE(s.ne_radi, false)) AS ima_ne_radi
        FROM sihterica s
        LEFT JOIN gradilista g ON g.id=s.gradiliste_id
        WHERE s.radnik_id=ANY($1) AND EXTRACT(YEAR FROM s.datum)=$2 AND EXTRACT(MONTH FROM s.datum)=$3
        GROUP BY s.radnik_id, dan ORDER BY s.radnik_id, dan
      `, [_radIds2, godina, mjesec]);
      for (const row of _satiAll2.rows) { (_satiMap2[row.radnik_id] = _satiMap2[row.radnik_id] || []).push(row); }

      const _akontAll2 = await pool.query(`
        SELECT radnik_id, id, iznos, napomena FROM place_akontacije
        WHERE radnik_id=ANY($1) AND godina=$2 AND mjesec=$3 ORDER BY radnik_id, created_at
      `, [_radIds2, godina, mjesec]);
      for (const row of _akontAll2.rows) { (_akontMap2[row.radnik_id] = _akontMap2[row.radnik_id] || []).push(row); }

      const _kredAll2 = await pool.query(`
        SELECT DISTINCT ON (k.radnik_id) k.radnik_id, k.id, k.ukupno, k.aktivan,
               COALESCE((SELECT SUM(o2.iznos) FROM krediti_otplate o2
                         WHERE o2.kredit_id = k.id
                           AND (o2.godina < $2 OR (o2.godina = $2 AND o2.mjesec < $3))), 0) AS otplaceno,
               (SELECT iznos FROM krediti_otplate WHERE kredit_id=k.id AND godina=$2 AND mjesec=$3 LIMIT 1) AS rata
        FROM krediti k
        WHERE k.radnik_id=ANY($1)
          AND (k.aktivan = true OR (k.aktivan = false
               AND ($2::int * 100 + $3::int) <= COALESCE((SELECT MAX(godina*100 + mjesec) FROM krediti_otplate WHERE kredit_id = k.id), 0)))
        ORDER BY k.radnik_id, k.aktivan DESC, k.datum_pocetka DESC
      `, [_radIds2, godina, mjesec]);
      for (const row of _kredAll2.rows) { _kredMap2[row.radnik_id] = row; }
    }

    for (const rad of radnici.rows) {
      const sati_q = { rows: _satiMap2[rad.id] || [] };  // ⭐ v326: batch mapa
      const dani_map = {};
      // ⭐ v502.1 (Ivan, 24.05.2026): Bolovanje dan → ne prikazuj gradilište, samo "bolovanje"
      sati_q.rows.forEach(r => { 
        dani_map[r.dan] = { 
          sati: parseFloat(r.sati), 
          gradiliste: r.ima_bolovanje ? 'bolovanje' : (r.ima_godisnji ? 'godišnji odmor' : (r.ima_ne_radi ? 'ne radi' : (r.gradilista || '')))   // ⭐ v904
        }; 
      });

      const akont_q = { rows: _akontMap2[rad.id] || [] };  // ⭐ v326: batch mapa

      const kred_q = { rows: _kredMap2[rad.id] ? [_kredMap2[rad.id]] : [] };  // ⭐ v326: batch mapa (DISTINCT ON)
      const kred = kred_q.rows[0] || null;

      const ws = wb.addWorksheet(`${rad.prezime} ${rad.ime}`.slice(0,31));
      ws.pageSetup = { paperSize: 9, orientation: 'portrait', fitToPage: true, fitToWidth: 1, fitToHeight: 1 };
      ws.pageSetup.margins = { left:0.3, right:0.3, top:0.4, bottom:0.4, header:0.2, footer:0.2 };
      ws.columns = [
        {width:5},{width:14},{width:8},{width:22},{width:10},{width:22},{width:14}
      ];

      let r = 1;

      // Helper: merge A:G, stil
      const mergeRow = (row, val, bgArgb, fontSz=10, fontBold=false, fontColor='FFFFFFFF', height=20) => {
        ws.mergeCells(row,1,row,7);
        const c = ws.getCell(row,1);
        c.value = val; c.fill = fill(bgArgb);
        c.font = font(fontSz, fontBold, fontColor);
        c.alignment = aln('left'); c.border = brd;
        ws.getRow(row).height = height;
      };

      // Helper: label A:F + value G
      const lblVal = (row, label, value, bgArgb=C.WHITE, boldLabel=false, boldVal=false,
                      accentArgb=null, fmtStr='#,##0.00 €', height=15) => {
        ws.mergeCells(row,1,row,6);
        const lc = ws.getCell(row,1);
        lc.value = label;
        lc.fill = fill(accentArgb || bgArgb);
        lc.font = font(10, boldLabel, accentArgb ? 'FFFFFFFF' : 'FF000000');
        lc.alignment = aln('left'); lc.border = accentArgb ? brdT : brd;
        const vc = ws.getCell(row,7);
        vc.value = (typeof value === 'string' && value.startsWith('=')) ? { formula: value.slice(1) } : value;
        vc.fill = fill(accentArgb || (boldVal && bgArgb===C.WHITE ? C.GREEN : bgArgb));
        vc.font = font(accentArgb ? 12 : 10, boldVal || boldLabel,
                       accentArgb ? 'FFFFFFFF' : (bgArgb===C.YELLOW ? 'FF0000CC' : 'FF000000'));
        vc.alignment = aln('center');
        vc.border = accentArgb ? brdT : brd;
        vc.numFmt = fmtStr;
        ws.getRow(row).height = height;
      };

      const sepRow = (row, argb=C.GREY) => {
        ws.mergeCells(row,1,row,7);
        ws.getCell(row,1).fill = fill(argb);
        ws.getRow(row).height = 5;
      };

      // NASLOV
      mergeRow(r, `${rad.ime} ${rad.prezime}  —  ${mjes_ime} ${godina}`, C.RED, 11, true, 'FFFFFFFF', 20); r++;

      // Baneri
      if (kred && parseFloat(kred.ukupno) > 0) {
        const prevMj  = MJES[(parseInt(mjesec)-2+12)%12];
        const ukupno_k    = parseFloat(kred.ukupno);
        const otplaceno_k = parseFloat(kred.otplaceno);
        const ostalo_k    = Math.max(0, ukupno_k - otplaceno_k);
        const rata_k      = kred.rata ? parseFloat(kred.rata) : 0;
        const ostalo_nakon_k = Math.max(0, ostalo_k - rata_k);
        // Svjetlo ljubičasta pozadina (#E8D5F5) s tamno ljubičastim tekstom (#4B0082)
        const PURPLE_LIGHT = 'FFE8D5F5';
        const PURPLE_DARK_TXT = 'FF4B0082';
        const PURPLE_BOLD = 'FFD4B0F0';
        const kredRow = (row, label, value, bold=false) => {
          ws.mergeCells(row,1,row,6);
          const lc = ws.getCell(row,1);
          lc.value = label;
          lc.fill = fill(bold ? PURPLE_BOLD : PURPLE_LIGHT);
          lc.font = font(10, bold, PURPLE_DARK_TXT);
          lc.alignment = aln('left'); lc.border = brd;
          const vc = ws.getCell(row,7);
          vc.value = value;
          vc.fill = fill(bold ? PURPLE_BOLD : PURPLE_LIGHT);
          vc.font = font(bold ? 11 : 10, bold, PURPLE_DARK_TXT);
          vc.alignment = aln('center'); vc.border = brd;
          vc.numFmt = '#,##0.00 €';
          ws.getRow(row).height = 15;
        };
        kredRow(r, 'Kredit — ukupno iznos',             ukupno_k,        true);  r++;
        kredRow(r, `Otplaćeno do ${prevMj} ${godina}`,  otplaceno_k,     false); r++;
        kredRow(r, `Rata ${mjes_ime} ${godina}`,         rata_k,          false); r++;
        kredRow(r, 'Ostatak kredita nakon ove rate',     ostalo_nakon_k,  true);  r++;
      }
      if (parseFloat(rad.pretplata) > 0) {
        const prevMj = MJES[(parseInt(mjesec)-2+12)%12];
        mergeRow(r, `↩  PRETPLATA iz ${prevMj}: ${hrBroj(rad.pretplata,2)} €  — oduzima se od ove isplate`, C.ORANGE, 9, true, 'FFFFFFFF', 16); r++;
      }

      // ZAGLAVLJE tablice
      const hdrLabels = ['Rb','Datum','Dan','Gradilište','Sati','',''];
      hdrLabels.forEach((h,i) => {
        const c = ws.getCell(r, i+1);
        c.value = h; c.fill = fill(C.BLUE);
        c.font = font(10,true,'FFFFFFFF');
        c.alignment = aln(); c.border = brd;
      });
      ws.getRow(r).height = 15; r++;

      // DANI
      let ukupno_sati = 0;
      const sati_start = r;
      for (let d=1; d<=num_days; d++) {
        const dt = new Date(parseInt(godina), parseInt(mjesec)-1, d);
        const dan = dani_hrv[dt.getDay()];
        const vikend = dt.getDay()===0 || dt.getDay()===6;
        const bg = vikend ? C.LIGHT : C.WHITE;
        const p = dani_map[d] || {};
        const sati = parseFloat(p.sati || 0);
        ukupno_sati += sati;
        const fclr = vikend ? 'FF888888' : 'FF000000';
        const row = ws.getRow(r);
        // fix datum
        const datumStr = `${String(d).padStart(2,'0')}.${String(parseInt(mjesec)).padStart(2,'0')}.${godina}`;
        // ⭐ v907 (Ivan): dan odsutnosti obojan — bolovanje žućkasto, godišnji plavkasto, ne-radi crvenkasto
        const _o7 = p.gradiliste === 'bolovanje' ? ['FFFFF3CD', 'FF856404'] : p.gradiliste === 'godišnji odmor' ? ['FFDBEAFE', 'FF1E40AF'] : p.gradiliste === 'ne radi' ? ['FFFEE2E2', 'FF991B1B'] : null;
        const cellVals = [d, datumStr, dan, p.gradiliste||'', sati||0,'',''];
        cellVals.forEach((v,i2) => {
          const c = ws.getCell(r, i2+1);
          c.value = v; c.fill = fill(_o7 ? _o7[0] : bg);
          c.font = font(10, (vikend && i2===2) || (_o7 && i2===3), _o7 ? _o7[1] : fclr);
          c.alignment = i2===3 ? aln('left') : aln();
          c.border = brd;
          if (i2===4) c.numFmt = '0.0';
        });
        row.height = 13; r++;
      }
      const sati_end = r-1;

      // SEPARATOR
      sepRow(r); r++;

      // UKUPNO SATI
      ws.mergeCells(r,1,r,6);
      const uc = ws.getCell(r,1);
      uc.value = `UKUPNO SATI  —  ${mjes_ime} ${godina}`;
      uc.fill = fill(C.GREY); uc.font = font(10,true); uc.alignment = aln('left'); uc.border = brd;
      const sc2 = ws.getCell(r,7);
      sc2.value = { formula: `SUM(E${sati_start}:E${sati_end})` };
      sc2.fill = fill(C.GREY); sc2.font = font(11,true); sc2.alignment = aln(); sc2.border = brd;
      sc2.numFmt = '0.0 "h"';
      ws.getRow(r).height = 16;
      const sati_sum_row = r; r++;

      // SATNICA
      lblVal(r, 'Satnica  (€/h)', parseFloat(rad.satnica), C.YELLOW, false, true); const satnica_row=r; r++;
      // ⭐ v841 (Ivan): međuzbroj RADA — vidi se što samo sati donose prije dodataka (npr. 155×8,20=1.271)
      lblVal(r, 'Sati × satnica', { formula: `G${sati_sum_row}*G${satnica_row}` }, C.WHITE, false, true, null, '#,##0.00 €'); const rad_sum_row=r; r++;
      // BONUS / PENAL — dinamičan label i boja prema predznaku
      // ⭐ v135.7.41 (Ivan): jasno označi penal u isplatnoj listi (ne samo broj)
      const bonusVal = parseFloat(rad.bonus || 0);
      let bonusLabel = 'Bonus';
      let bonusFill = C.YELLOW;
      if (bonusVal < 0) {
        bonusLabel = '⚠️ PENAL / Kazna';
        bonusFill = 'FFFEE2E2';  // svijetlo crvena
      } else if (bonusVal > 0) {
        bonusLabel = '🎁 Bonus (nagrada)';
        bonusFill = 'FFE2EFDA';  // svijetlo zelena
      }
      // ⭐ v135.7.101 (Ivan): "Bonus [napomena]" pattern — ako postoji napomena uz bonus, doda je u label
      //    Reuse postojeće `napomena` kolone (nije nova DB kolona — minimalna invazija).
      const bonusNapStr = String(rad.napomena || '').trim();
      if (bonusVal !== 0 && bonusNapStr) {
        bonusLabel = `${bonusLabel} — ${bonusNapStr.slice(0, 80)}`;
      }
      lblVal(r, bonusLabel, bonusVal, bonusFill, false, true); const bonus_row=r; r++;
      // BRUTO
      // Bolovanje red
      lblVal(r, 'Bolovanje', parseFloat(rad.naknada_bolovanje||0), C.YELLOW); const bol_row=r; r++;
      // ⭐ v838 (Ivan, screenshot): GODIŠNJI ODMOR je bio u canvasu i u calculatePayout, ali NE u
      //   redovima/formuli Excela — ISPLATA ćelija je računala bez njega (−300 € razlike).
      const god_val = parseFloat(rad.godisnji || 0);
      let god_row = null;
      if (god_val > 0) {
        lblVal(r, 'Godišnji odmor', god_val, 'FFE2EFDA', false, true); god_row = r; r++;
      }
      const ispl_prosli = parseFloat(rad.isplata_prosli_mj||0);
      let ispl_prosli_row = null;
      if (ispl_prosli > 0) {
        lblVal(r, 'Isplata prošlog mj.', ispl_prosli, C.YELLOW, false, true); ispl_prosli_row=r; r++;
      }
      const _fDij = [`G${rad_sum_row}`, `G${bonus_row}`, `G${bol_row}`];   // ⭐ v838 · v841: bruto se referira na red „Sati × satnica“
      if (god_row) _fDij.push(`G${god_row}`);
      if (ispl_prosli_row) _fDij.push(`G${ispl_prosli_row}`);
      const bruto_formula = _fDij.join('+');
      // ⭐ v135.7.41 (Ivan): Bruto formula napomena - jasna i s penal/bonus napomenom
      const brutoOpis = (bonusVal < 0
        ? 'Bruto plaća  =  (sati × satnica) − PENAL + bolovanje'
        : bonusVal > 0
        ? 'Bruto plaća  =  (sati × satnica) + bonus + bolovanje'
        : 'Bruto plaća  =  (sati × satnica) + bolovanje')
        + (god_row ? ' + godišnji' : '')
        + (ispl_prosli_row ? ' + isplata prošlog mj.' : '');   // ⭐ v838
      lblVal(r, brutoOpis,
        { formula: bruto_formula },
        C.WHITE, true, true, null, '#,##0.00 €');
      const bruto_row=r; r++;

      sepRow(r); r++;

      // ODBITCI
      const odbitak_rows = [];
      lblVal(r, 'Plaća na račun', parseFloat(rad.placa_racun), C.YELLOW); odbitak_rows.push(r); r++;
      lblVal(r, 'Terenska', parseFloat(rad.terenska), C.YELLOW); odbitak_rows.push(r); r++;

      for (let i=0; i<akont_q.rows.length; i++) {
        const a = akont_q.rows[i];
        const lbl = akont_q.rows.length>1 ? `Akontacija ${i+1}${a.napomena?' — '+a.napomena:''}` : `Akontacija${a.napomena?' — '+a.napomena:''}`;
        lblVal(r, lbl, parseFloat(a.iznos), C.YELLOW); odbitak_rows.push(r); r++;
      }

      if (kred && kred.rata) {
        const ostalo_prije = parseFloat(kred.ukupno) - parseFloat(kred.otplaceno);
        const ostalo_nakon = ostalo_prije - parseFloat(kred.rata);
        lblVal(r, `Kredit — rata  (ostatak: ${hrBroj(ostalo_nakon,2)} €)`, parseFloat(kred.rata), C.YELLOW);
        odbitak_rows.push(r); r++;
      }

      if (parseFloat(rad.pretplata) > 0) {
        const prevMj = MJES[(parseInt(mjesec)-2+12)%12];
        // Orange accent za pretplatu
        ws.mergeCells(r,1,r,6);
        const lc2 = ws.getCell(r,1); lc2.value = `Pretplata iz ${prevMj}`;
        lc2.fill=fill(C.ORANGE); lc2.font=font(10,false,'FFFFFFFF'); lc2.alignment=aln('left'); lc2.border=brdT;
        const vc2 = ws.getCell(r,7); vc2.value=parseFloat(rad.pretplata);
        vc2.fill=fill(C.ORANGE); vc2.font=font(10,true,'FFFFFFFF'); vc2.alignment=aln(); vc2.border=brdT;
        vc2.numFmt='#,##0.00 €'; ws.getRow(r).height=18;
        odbitak_rows.push(r); r++;
      }

      // ⭐ v1263 REVIZIJA MATEMATIKE (Ivan: „Excel treba odgovarati canvasu“): red se pisao
      //   BEZUVJETNO, a canvas/calculatePayout nuliraju ciscenje za sati=0 ili bez_ciscenja_stana
      //   (v157/158) — pa je Excelova ISPLATA (formula bruto−SUM(redova)) odbijala ciscenje i
      //   Memsuru i radniku bez ijednog sata, dok je BOJA celije (calculatePayout) bila po pravom
      //   iznosu. Red sada ide u tablicu samo kad se ciscenje stvarno naplacuje.
      if (ukupno_sati > 0 && !rad.bez_ciscenja_stana && parseFloat(rad.ciscenje) > 0) {
        lblVal(r, 'Čišćenje stana', parseFloat(rad.ciscenje), C.YELLOW); odbitak_rows.push(r); r++;
      }

      sepRow(r); r++;

      // ISPLATA — izračunaj za boju
      const odFormula = odbitak_rows.map(x=>`G${x}`).join('+');
      const akont_sum_ex = akont_q.rows.reduce((s,a)=>s+parseFloat(a.iznos||0),0);
      const kredit_rata_ex = kred?.rata ? parseFloat(kred.rata) : 0;
      // ⭐ AUDIT #1: koristi centraliziranu calculatePayout (single source of truth)
      // ⭐ v135.7.159: bez_ciscenja_stana flag iz radnika
      const payoutEx = calculatePayout({
        sati: ukupno_sati, satnica: rad.satnica,
        bonus: rad.bonus, naknada_bolovanje: rad.naknada_bolovanje,
        isplata_prosli_mj: rad.isplata_prosli_mj, godisnji: rad.godisnji,
        placa_racun: rad.placa_racun, terenska: rad.terenska, ciscenje: rad.ciscenje,
        pretplata: rad.pretplata, akontacije: akont_sum_ex, kredit_rata: kredit_rata_ex,
        bez_ciscenja_stana: rad.bez_ciscenja_stana
      });
      const bruto_ex = payoutEx.bruto;
      const odbitci_ex = payoutEx.odbitci;
      const isplata_ex = payoutEx.isplata;
      const isplata_color = isplata_ex >= 0 ? 'FF1E7145' : 'FFCC0000';
      // Piši ISPLATA red s dinamičnom bojom
      ws.mergeCells(r,1,r,6);
      const islc = ws.getCell(r,1);
      islc.value = 'ISPLATA'; islc.fill = fill(isplata_color);
      islc.font = font(12, true, 'FFFFFFFF'); islc.alignment = aln('left'); islc.border = brdT;
      const isvc = ws.getCell(r,7);
      isvc.value = { formula: `G${bruto_row}-(${odFormula})` };
      isvc.fill = fill(isplata_color); isvc.font = font(13, true, 'FFFFFFFF');
      isvc.alignment = aln('center'); isvc.border = brdT; isvc.numFmt = '#,##0.00 €';
      ws.getRow(r).height = 22; r++;

    }

    const placeBuf = await wb.xlsx.writeBuffer();
    // ⭐ v643: kad je export za jednog radnika, ime datoteke nosi njegovo ime (npr. Placa-Arsim_Jakupi-Srpanj-2026.xlsx)
    const placeFname = (radnik_id && radnici.rows.length)
      ? `Placa-${_hrSafeFolderName(radnici.rows[0].ime, radnici.rows[0].prezime)}-${mjes_ime}-${godina}.xlsx`
      : `Place-${mjes_ime}-${godina}.xlsx`;
    // ⭐ v135.7.57: Streaming + gzip kompresija
    sendExcelResponse(req, res, placeBuf, placeFname);
    setImmediate(() => qnapUploadExcel(Buffer.from(placeBuf), `Plaća/${placeFname}`));
  } catch (e) {
    console.error('export place:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ── PLAĆE EXPORT — raspon više mjeseci ────────────────────────────────────────
// Jedan sheet po radniku, svi mjeseci jedan ispod drugog, page break između.
app.get('/api/place/export-range', auth, direktor, async (req, res) => {
  let { od_godina, od_mjesec, do_godina, do_mjesec } = req.query;
  
  // ⭐ v135.7.224: Godišnja plaća — ?godina=2026 automatski postavi raspon siječanj-prosinac
  //   Use case: Ivan klikne "Godišnja plaća" → svi 12 mjeseci, svi radnici, multi-sheet.
  //   Filename: Place-{godina}.xlsx (statički, prepisuje se na QNAP+B2).
  const godinaFilter = req.query.godina ? parseInt(req.query.godina) : null;
  if (godinaFilter && godinaFilter >= 2020 && godinaFilter <= 2099) {
    od_godina = godinaFilter;
    od_mjesec = 1;
    do_godina = godinaFilter;
    do_mjesec = 12;
    console.log(`[export place/godisnji] godina=${godinaFilter}`);
  }
  
  if (!od_godina || !od_mjesec || !do_godina || !do_mjesec)
    return res.status(400).json({ error: 'Nedostaju parametri' });

  const odG = parseInt(od_godina), odM = parseInt(od_mjesec);
  const doG = parseInt(do_godina), doM = parseInt(do_mjesec);
  if (odG * 100 + odM > doG * 100 + doM)
    return res.status(400).json({ error: 'Od mora biti prije Do' });
  const ukMjeseci = (doG - odG) * 12 + (doM - odM) + 1;
  if (ukMjeseci > 24)
    return res.status(400).json({ error: 'Maksimalni raspon je 24 mjeseca' });

  try {
    const ExcelJS = require('exceljs');
    const MJES = ['Siječanj','Veljača','Ožujak','Travanj','Svibanj','Lipanj',
                  'Srpanj','Kolovoz','Rujan','Listopad','Studeni','Prosinac'];
    const dani_hrv = ['Ned','Pon','Uto','Sri','Čet','Pet','Sub'];
    const C = {
      RED:'FFCC0000', BLUE:'FF1F4E79', GREEN:'FFE2EFDA',
      YELLOW:'FFFFFFF0', GREY:'FFD9D9D9', WHITE:'FFFFFFFF',
      LIGHT:'FFF2F2F2', ORANGE:'FFED7D31',
    };
    const fill = hex => ({ type:'pattern', pattern:'solid', fgColor:{ argb:hex } });
    const font = (sz=10,bold=false,color='FF000000') => ({ name:'Arial', size:sz, bold, color:{ argb:color } });
    const aln  = (h='center') => ({ horizontal:h, vertical:'middle' });
    const brd  = { top:{style:'thin',color:{argb:'FFAAAAAA'}},bottom:{style:'thin',color:{argb:'FFAAAAAA'}},
                   left:{style:'thin',color:{argb:'FFAAAAAA'}},right:{style:'thin',color:{argb:'FFAAAAAA'}} };
    const brdT = { top:{style:'medium',color:{argb:'FF444444'}},bottom:{style:'medium',color:{argb:'FF444444'}},
                   left:{style:'medium',color:{argb:'FF444444'}},right:{style:'medium',color:{argb:'FF444444'}} };

    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Gradilište';

    // Generiraj popis mjeseci
    const mjeseci = [];
    let gm = odG, mm = odM;
    while (gm * 100 + mm <= doG * 100 + doM) {
      mjeseci.push({ g: gm, m: mm });
      mm++; if (mm > 12) { mm = 1; gm++; }
    }

    // Dohvati sve relevantne radnike (unija svih mjeseci)
    const radniciQ = await pool.query(`
      SELECT DISTINCT r.id, r.ime, r.prezime, COALESCE(r.bez_ciscenja_stana, false) AS bez_ciscenja_stana
      FROM radnici r
      WHERE r.role != 'direktor'
        AND (r.aktivan = true
          OR (r.aktivan = false AND r.datum_deaktivacije IS NOT NULL
            AND r.datum_deaktivacije >= make_date($1::int, $2::int, 1)))
      ORDER BY r.prezime, r.ime
    `, [odG, odM]);

    // JEDAN SHEET PO RADNIKU
    for (const rad of radniciQ.rows) {
      const ws = wb.addWorksheet(`${rad.prezime} ${rad.ime}`.slice(0,31));
      ws.pageSetup = {
        paperSize: 9, orientation: 'portrait',
        fitToPage: true, fitToWidth: 1, fitToHeight: 0,
      };
      ws.pageSetup.margins = { left:0.3, right:0.3, top:0.4, bottom:0.4, header:0.2, footer:0.2 };
      ws.columns = [ {width:5},{width:14},{width:8},{width:22},{width:10},{width:22},{width:14} ];

      let r = 1;
      // ⭐ v135.7.225: Trackam broj generiranih mjeseci za godišnji export
      //   Na kraju, ako je 0, brišem sheet (radnik nije imao aktivnosti niti u jednom mjesecu).
      let _mjeseciGen = 0;

      const mergeRow = (row, val, bgArgb, fontSz=10, fontBold=false, fontColor='FFFFFFFF', height=20) => {
        ws.mergeCells(row,1,row,7);
        const c = ws.getCell(row,1);
        c.value = val; c.fill = fill(bgArgb);
        c.font = font(fontSz, fontBold, fontColor);
        c.alignment = aln('left'); c.border = brd;
        ws.getRow(row).height = height;
      };

      const lblVal = (row, label, value, bgArgb=C.WHITE, boldLabel=false, boldVal=false,
                      accentArgb=null, fmtStr='#,##0.00 €', height=15) => {
        ws.mergeCells(row,1,row,6);
        const lc = ws.getCell(row,1);
        lc.value = label;
        lc.fill = fill(accentArgb || bgArgb);
        lc.font = font(10, boldLabel, accentArgb ? 'FFFFFFFF' : 'FF000000');
        lc.alignment = aln('left'); lc.border = accentArgb ? brdT : brd;
        const vc = ws.getCell(row,7);
        vc.value = (typeof value === 'string' && value.startsWith('=')) ? { formula: value.slice(1) } : value;
        vc.fill = fill(accentArgb || (boldVal && bgArgb===C.WHITE ? C.GREEN : bgArgb));
        vc.font = font(accentArgb ? 12 : 10, boldVal || boldLabel,
                       accentArgb ? 'FFFFFFFF' : (bgArgb===C.YELLOW ? 'FF0000CC' : 'FF000000'));
        vc.alignment = aln('center'); vc.border = accentArgb ? brdT : brd;
        vc.numFmt = fmtStr; ws.getRow(row).height = height;
      };

      const sepRow = (row, argb=C.GREY) => {
        ws.mergeCells(row,1,row,7);
        ws.getCell(row,1).fill = fill(argb);
        ws.getRow(row).height = 5;
      };

      // SVAKI MJESEC U ISTOM SHEETU
      for (let mjIdx = 0; mjIdx < mjeseci.length; mjIdx++) {
        const { g: godina, m: mjesec } = mjeseci[mjIdx];
        const mjes_ime = MJES[mjesec - 1];
        const num_days = new Date(godina, mjesec, 0).getDate();

        // ⭐ v1263 REVIZIJA MATEMATIKE (Z1 nalaz): range je povlacio ZADNJI CIJELI RED <= mjeseca —
        //   pa je mjesec bez svojih parametara nasljedjivao i PRETPLATU, GODISNJI i ISPLATU PROSLOG
        //   MJESECA iz nekog starijeg mjeseca (strogo mjesecne stavke!), a satnica je ignorirala
        //   satnica_set. Sada ISTA semantika kao mjesecni export i GET /api/place: carry SAMO za
        //   satnicu (satnica_set logika), bonus, placu, terensku, ciscenje i bolovanje; pretplata/
        //   godisnji/isplata_prosli iskljucivo iz reda TOG mjeseca. Red se uvijek vrati (LEFT JOIN);
        //   ima_ikad zamjenjuje staro "nema nijednog reda" preskakanje.
        const paramQ = await pool.query(`
          SELECT
                 COALESCE(
                   CASE WHEN COALESCE(p.satnica_set, false) = true THEN p.satnica ELSE NULL END,
                   (SELECT pp.satnica FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    AND pp.satnica IS NOT NULL
                    AND (COALESCE(pp.satnica_set, false) = true OR pp.satnica <> 8.00)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1),
                   p.satnica, 8) AS satnica,
                 COALESCE(p.bonus,
                   (SELECT bonus FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS bonus,
                 COALESCE(p.placa_racun,
                   (SELECT placa_racun FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS placa_racun,
                 COALESCE(p.terenska,
                   (SELECT terenska FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS terenska,
                 COALESCE(p.ciscenje,
                   (SELECT ciscenje FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 15) AS ciscenje,
                 COALESCE(p.pretplata, 0) AS pretplata,
                 COALESCE(p.naknada_bolovanje,
                   (SELECT naknada_bolovanje FROM place_parametri pp WHERE pp.radnik_id=$1
                    AND (pp.godina*12+pp.mjesec) <= ($2::int*12+$3::int)
                    ORDER BY pp.godina DESC, pp.mjesec DESC LIMIT 1), 0) AS naknada_bolovanje,
                 COALESCE(p.godisnji, 0) AS godisnji,
                 COALESCE(p.isplata_prosli_mj, 0) AS isplata_prosli_mj,
                 COALESCE(p.napomena, '') AS napomena,
                 (p.radnik_id IS NOT NULL) AS ima_red,
                 EXISTS(SELECT 1 FROM place_parametri pp WHERE pp.radnik_id=$1) AS ima_ikad
          FROM (SELECT 1) x
          LEFT JOIN place_parametri p ON p.radnik_id=$1 AND p.godina=$2 AND p.mjesec=$3
        `, [rad.id, godina, mjesec]);

        // Ako nema NIJEDNOG parametra za ovog radnika, preskoči taj mjesec
        // (radnik možda nije bio zaposlen tada)
        const p = paramQ.rows[0];
        // Provjeri je li radnik imao ikakvih sati u tom mjesecu
        const checkSati = await pool.query(`
          SELECT COUNT(*) AS cnt FROM sihterica
          WHERE radnik_id=$1 AND EXTRACT(YEAR FROM datum)=$2 AND EXTRACT(MONTH FROM datum)=$3
        `, [rad.id, godina, mjesec]);
        const imaSati = parseInt(checkSati.rows[0]?.cnt || 0) > 0;
        // Preskoči ako nema ni sati ni parametara (ikad) — ⭐ v1263: red sad uvijek postoji (LEFT JOIN)
        if (!p.ima_ikad && !imaSati) continue;
        
        // ⭐ v135.7.225: Godišnji export — preskoči mjesece BEZ realne aktivnosti
        //   Use case: radnik radi veljača-svibanj 2026 → ne stvaraj prazne A4
        //   listove za lipanj-prosinac (gdje ima parametre u sustavu ali nema sati).
        //   
        //   Kriterij "ima aktivnosti": bilo što od navedenog
        //     - sati u sihterici za taj mjesec
        //     - naknada bolovanja > 0
        //     - godišnji odmor > 0
        //     - isplata prošli mjesec > 0
        //     - postoji parametar bonus ili plaća-na-račun > 0
        //     - postoji akontacija za taj mjesec
        //   
        //   Primjenjuje se SAMO za godišnji export (?godina=YYYY), ne i za custom range,
        //   jer kod range-a možda korisnik želi i prazne listove (npr. za reviziju).
        if (godinaFilter && p.ima_ikad && !imaSati) {   // ⭐ v1263: isto znacenje kao staro `p` (postoji ikakav red)
          const naknadaBol  = parseFloat(p?.naknada_bolovanje || 0);
          const godisnjiAnl = parseFloat(p?.godisnji || 0);
          const isplProsli  = parseFloat(p?.isplata_prosli_mj || 0);
          const bonusAnl    = parseFloat(p?.bonus || 0);
          const placaRacun  = parseFloat(p?.placa_racun || 0);
          
          // Provjeri akontacije za taj mjesec (ako ih ima, mjesec se prikazuje)
          const akontCheck = await pool.query(`
            SELECT COUNT(*) AS cnt FROM place_akontacije
            WHERE radnik_id=$1 AND godina=$2 AND mjesec=$3
          `, [rad.id, godina, mjesec]);
          const imaAkont = parseInt(akontCheck.rows[0]?.cnt || 0) > 0;
          
          // Ako NIJEDNO od navedenog → preskoči mjesec
          const imaIkakvuAktivnost = naknadaBol > 0 || godisnjiAnl > 0 || isplProsli > 0
                                     || bonusAnl > 0 || placaRacun > 0 || imaAkont;
          
          if (!imaIkakvuAktivnost) {
            console.log(`[place godisnji] preskačem ${rad.ime} ${rad.prezime} ${mjes_ime} ${godina} (nema aktivnosti)`);
            continue;
          }
        }

        const satnica     = parseFloat(p?.satnica || 8);
        const bonus       = parseFloat(p?.bonus || 0);
        const placa_racun = parseFloat(p?.placa_racun || 0);
        const terenska    = parseFloat(p?.terenska || 0);
        // ⭐ v1263 PLA-01 REGRESIJA u range exportu: `|| 15` je pretvarao EKSPLICITNU nulu u 15
        //   (v135.7.124 lekcija — NULL=default, 0=iskljuceno). Sada NULL-aware kao calculatePayout.
        const ciscenje    = (p?.ciscenje === null || p?.ciscenje === undefined || p?.ciscenje === '')
                              ? 15 : (parseFloat(p.ciscenje) || 0);
        const pretplata   = parseFloat(p?.pretplata || 0);
        const naknada_bol = parseFloat(p?.naknada_bolovanje || 0);
        const ispl_prosli = parseFloat(p?.isplata_prosli_mj || 0);
        // ⭐ AUDIT #1: godisnji prije nije bio u scope-u → bug u export-range
        const godisnji_anl = parseFloat(p?.godisnji || 0);

        const sati_q = await pool.query(`
          SELECT EXTRACT(DAY FROM s.datum)::int AS dan,
                 SUM(s.sati_redovni) AS sati,
                 STRING_AGG(DISTINCT g.naziv, ', ') AS gradilista,
                 BOOL_OR(COALESCE(s.bolovanje, false)) AS ima_bolovanje,
                 BOOL_OR(COALESCE(s.godisnji, false)) AS ima_godisnji,   -- ⭐ v904
                 BOOL_OR(COALESCE(s.ne_radi, false)) AS ima_ne_radi
          FROM sihterica s 
          LEFT JOIN gradilista g ON g.id=s.gradiliste_id
          WHERE s.radnik_id=$1 AND EXTRACT(YEAR FROM s.datum)=$2 AND EXTRACT(MONTH FROM s.datum)=$3
          GROUP BY dan ORDER BY dan
        `, [rad.id, godina, mjesec]);
        const dani_map = {};
        // ⭐ v502.1: bolovanje → ne prikazuj gradilište
        sati_q.rows.forEach(row => { 
          dani_map[row.dan] = { 
            sati: parseFloat(row.sati), 
            gradiliste: row.ima_bolovanje ? 'bolovanje' : (row.ima_godisnji ? 'godišnji odmor' : (row.ima_ne_radi ? 'ne radi' : (row.gradilista || '')))   // ⭐ v904
          }; 
        });

        const akont_q = await pool.query(`
          SELECT id, iznos, napomena FROM place_akontacije
          WHERE radnik_id=$1 AND godina=$2 AND mjesec=$3 ORDER BY created_at
        `, [rad.id, godina, mjesec]);

        const kred_q = await pool.query(`
          SELECT k.id, k.ukupno, k.aktivan,
                 COALESCE((SELECT SUM(o2.iznos) FROM krediti_otplate o2
                   WHERE o2.kredit_id=k.id
                     AND (o2.godina < $2 OR (o2.godina=$2 AND o2.mjesec < $3))
                 ), 0) AS otplaceno,
                 (SELECT iznos FROM krediti_otplate WHERE kredit_id=k.id AND godina=$2 AND mjesec=$3 LIMIT 1) AS rata
          FROM krediti k 
          WHERE k.radnik_id=$1 
            AND (
              k.aktivan = true
              OR (
                -- ⭐ v135.7.153: Otplaćen kredit, prikaži samo do zadnje rate (uključno)
                k.aktivan = false
                AND ($2::int * 100 + $3::int) <= COALESCE(
                  (SELECT MAX(godina*100 + mjesec) FROM krediti_otplate WHERE kredit_id = k.id),
                  0
                )
              )
            )
          ORDER BY k.aktivan DESC, k.datum_pocetka DESC
          LIMIT 1
        `, [rad.id, godina, mjesec]);
        const kred = kred_q.rows[0] || null;

        // ── NASLOV MJESECA ────────────────────────────────────────────────────
        mergeRow(r, `${rad.ime} ${rad.prezime}  —  ${mjes_ime} ${godina}`, C.RED, 11, true, 'FFFFFFFF', 20); r++;

        // KREDIT BANER
        if (kred && parseFloat(kred.ukupno) > 0) {
          const prevMj = MJES[(mjesec-2+12)%12];
          const ukupno_k     = parseFloat(kred.ukupno);
          const otplaceno_k  = parseFloat(kred.otplaceno);
          const ostalo_k     = Math.max(0, ukupno_k - otplaceno_k);
          const rata_k       = kred.rata ? parseFloat(kred.rata) : 0;
          const ostalo_nakon = Math.max(0, ostalo_k - rata_k);
          const PL = 'FFE8D5F5', PD = 'FF4B0082', PB = 'FFD4B0F0';
          const kredRow = (row, label, value, bold=false) => {
            ws.mergeCells(row,1,row,6);
            const lc = ws.getCell(row,1);
            lc.value = label; lc.fill = fill(bold?PB:PL);
            lc.font = font(10,bold,PD); lc.alignment = aln('left'); lc.border = brd;
            const vc = ws.getCell(row,7);
            vc.value = value; vc.fill = fill(bold?PB:PL);
            vc.font = font(bold?11:10,bold,PD); vc.alignment = aln('center'); vc.border = brd;
            vc.numFmt = '#,##0.00 €'; ws.getRow(row).height = 15;
          };
          kredRow(r,'Kredit — ukupno iznos',            ukupno_k,    true);  r++;
          kredRow(r,`Otplaćeno do ${prevMj} ${godina}`, otplaceno_k, false); r++;
          kredRow(r,`Rata ${mjes_ime} ${godina}`,        rata_k,      false); r++;
          kredRow(r,'Ostatak kredita nakon ove rate',    ostalo_nakon,true);  r++;
        }
        if (pretplata > 0) {
          const prevMj = MJES[(mjesec-2+12)%12];
          mergeRow(r, `↩  PRETPLATA iz ${prevMj}: ${hrBroj(pretplata,2)} €  — oduzima se od ove isplate`, C.ORANGE, 9, true, 'FFFFFFFF', 16); r++;
        }

        // ZAGLAVLJE TABLICE
        ['Rb','Datum','Dan','Gradilište','Sati','',''].forEach((h,i) => {
          const c = ws.getCell(r,i+1);
          c.value = h; c.fill = fill(C.BLUE);
          c.font = font(10,true,'FFFFFFFF');
          c.alignment = aln(); c.border = brd;
        });
        ws.getRow(r).height = 15; r++;

        // DANI
        let ukupno_sati = 0;
        const sati_start = r;
        for (let d = 1; d <= num_days; d++) {
          const dt = new Date(godina, mjesec-1, d);
          const vikend = dt.getDay()===0 || dt.getDay()===6;
          const p2 = dani_map[d] || {};
          const sati = parseFloat(p2.sati || 0);
          ukupno_sati += sati;
          const datumStr = `${String(d).padStart(2,'0')}.${String(mjesec).padStart(2,'0')}.${godina}`;
          const _o7r = p2.gradiliste === 'bolovanje' ? ['FFFFF3CD', 'FF856404'] : p2.gradiliste === 'godišnji odmor' ? ['FFDBEAFE', 'FF1E40AF'] : p2.gradiliste === 'ne radi' ? ['FFFEE2E2', 'FF991B1B'] : null;   // ⭐ v907
          [d, datumStr, dani_hrv[dt.getDay()], p2.gradiliste||'', sati||0,'',''].forEach((v,i2) => {
            const c = ws.getCell(r,i2+1);
            c.value = v; c.fill = fill(_o7r ? _o7r[0] : (vikend ? C.LIGHT : C.WHITE));
            c.font = font(10, (vikend && i2===2) || (_o7r && i2===3), _o7r ? _o7r[1] : (vikend ? 'FF888888' : 'FF000000'));
            c.alignment = i2===3 ? aln('left') : aln(); c.border = brd;
            if (i2===4) c.numFmt = '0.0';
          });
          ws.getRow(r).height = 13; r++;
        }
        const sati_end = r-1;

        sepRow(r); r++;

        // UKUPNO SATI
        ws.mergeCells(r,1,r,6);
        const uc = ws.getCell(r,1);
        uc.value = `UKUPNO SATI  —  ${mjes_ime} ${godina}`;
        uc.fill = fill(C.GREY); uc.font = font(10,true); uc.alignment = aln('left'); uc.border = brd;
        const sc2 = ws.getCell(r,7);
        sc2.value = { formula: `SUM(E${sati_start}:E${sati_end})` };
        sc2.fill = fill(C.GREY); sc2.font = font(11,true); sc2.alignment = aln(); sc2.border = brd;
        sc2.numFmt = '0.0 "h"';
        ws.getRow(r).height = 16;
        const sati_sum_row = r; r++;

        // OBRAČUN
        lblVal(r,'Satnica  (€/h)', satnica, C.YELLOW, false, true); const satnica_row=r; r++;
        // ⭐ v135.7.101 (Ivan): "Bonus [napomena]" pattern — ako postoji napomena uz bonus, doda je u label
        const bonusNapR = String(p?.napomena || '').trim();
        const bonusLblR = (bonus !== 0 && bonusNapR) 
          ? `Bonus — ${bonusNapR.slice(0, 80)}`
          : 'Bonus';
        lblVal(r, bonusLblR, bonus, C.YELLOW, false, true); const bonus_row=r; r++;
        lblVal(r,'Bolovanje', naknada_bol, C.YELLOW); const bol_row=r; r++;
        // ⭐ v1263 REVIZIJA MATEMATIKE: GODISNJI je u range exportu FALIO i kao red i u bruto
        //   formuli (mjesecni export ga ima od v839/v841; calculatePayout ga racuna — pa je BOJA
        //   ISPLATE bila po jednom broju, a CELIJA po drugom, manjem za godisnji). Sada red
        //   (uvjetno, kao u mjesecnom) + clan u formuli.
        let god_row_r = null;
        if (godisnji_anl > 0) {
          lblVal(r,'Godišnji odmor', godisnji_anl, 'FFE2EFDA', false, true); god_row_r=r; r++;
        }
        let ispl_prosli_row = null;
        if (ispl_prosli > 0) {
          lblVal(r,'Isplata prošlog mj.', ispl_prosli, C.YELLOW, false, true); ispl_prosli_row=r; r++;
        }
        const _fDijR = [`G${sati_sum_row}*G${satnica_row}`, `G${bonus_row}`, `G${bol_row}`];
        if (god_row_r) _fDijR.push(`G${god_row_r}`);
        if (ispl_prosli_row) _fDijR.push(`G${ispl_prosli_row}`);
        const bruto_formula = _fDijR.join('+');
        lblVal(r,'Bruto plaća  =  (sati × satnica) + bonus + bolovanje' + (god_row_r?' + godišnji':'') + (ispl_prosli_row?' + isplata prošlog mj.':''),
          { formula: bruto_formula }, C.WHITE, true, true, null, '#,##0.00 €');
        const bruto_row=r; r++;

        sepRow(r); r++;

        const odbitak_rows = [];
        lblVal(r,'Plaća na račun', placa_racun, C.YELLOW); odbitak_rows.push(r); r++;
        lblVal(r,'Terenska', terenska, C.YELLOW); odbitak_rows.push(r); r++;

        for (let i=0; i<akont_q.rows.length; i++) {
          const a = akont_q.rows[i];
          const lbl = akont_q.rows.length>1 ? `Akontacija ${i+1}${a.napomena?' — '+a.napomena:''}` : `Akontacija${a.napomena?' — '+a.napomena:''}`;
          lblVal(r, lbl, parseFloat(a.iznos), C.YELLOW); odbitak_rows.push(r); r++;
        }

        if (kred && kred.rata) {
          const ostalo_pr = parseFloat(kred.ukupno) - parseFloat(kred.otplaceno);
          lblVal(r, `Kredit — rata  (ostatak: ${hrBroj(ostalo_pr - parseFloat(kred.rata),2)} €)`,
            parseFloat(kred.rata), C.YELLOW);
          odbitak_rows.push(r); r++;
        }

        if (pretplata > 0) {
          const prevMj = MJES[(mjesec-2+12)%12];
          ws.mergeCells(r,1,r,6);
          const lc2=ws.getCell(r,1); lc2.value=`Pretplata iz ${prevMj}`;
          lc2.fill=fill(C.ORANGE); lc2.font=font(10,false,'FFFFFFFF'); lc2.alignment=aln('left'); lc2.border=brdT;
          const vc2=ws.getCell(r,7); vc2.value=pretplata;
          vc2.fill=fill(C.ORANGE); vc2.font=font(10,true,'FFFFFFFF'); vc2.alignment=aln(); vc2.border=brdT;
          vc2.numFmt='#,##0.00 €'; ws.getRow(r).height=18;
          odbitak_rows.push(r); r++;
        }

        // ⭐ v1263: isti uvjet kao mjesecni export i calculatePayout (v157/158)
        if (ukupno_sati > 0 && !rad.bez_ciscenja_stana && ciscenje > 0) {
          lblVal(r,'Čišćenje stana', ciscenje, C.YELLOW); odbitak_rows.push(r); r++;
        }

        sepRow(r); r++;

        // ISPLATA
        const odFormula = odbitak_rows.map(x=>`G${x}`).join('+');
        const akont_sum  = akont_q.rows.reduce((s,a)=>s+parseFloat(a.iznos||0),0);
        const kredit_r   = kred?.rata ? parseFloat(kred.rata) : 0;
        // ⭐ AUDIT #1: koristi centralizirani calculatePayout (single source of truth)
        // ⭐ v135.7.159: bez_ciscenja_stana flag iz radnika (rad iz vanjske petlje)
        const payoutEr = calculatePayout({
          sati: ukupno_sati, satnica,
          bonus, naknada_bolovanje: naknada_bol,
          isplata_prosli_mj: ispl_prosli, godisnji: godisnji_anl,
          placa_racun, terenska, ciscenje,
          pretplata, akontacije: akont_sum, kredit_rata: kredit_r,
          bez_ciscenja_stana: rad.bez_ciscenja_stana
        });
        const bruto_ex = payoutEr.bruto;
        const odbitci_ex = payoutEr.odbitci;
        const isplata_color = (bruto_ex - odbitci_ex) >= 0 ? 'FF1E7145' : 'FFCC0000';

        ws.mergeCells(r,1,r,6);
        const islc=ws.getCell(r,1);
        islc.value='ISPLATA'; islc.fill=fill(isplata_color);
        islc.font=font(12,true,'FFFFFFFF'); islc.alignment=aln('left'); islc.border=brdT;
        const isvc=ws.getCell(r,7);
        isvc.value={ formula: `G${bruto_row}-(${odFormula})` };
        isvc.fill=fill(isplata_color); isvc.font=font(13,true,'FFFFFFFF');
        isvc.alignment=aln('center'); isvc.border=brdT; isvc.numFmt='#,##0.00 €';
        ws.getRow(r).height=22; r++;
        
        // ⭐ v135.7.225: Mjesec uspješno generiran — increment counter
        _mjeseciGen++;

        // PAGE BREAK nakon svakog mjeseca osim zadnjeg
        if (mjIdx < mjeseci.length - 1) {
          // Prazan separator red + page break
          ws.mergeCells(r,1,r,7);
          ws.getCell(r,1).fill = fill('FFFFFFFF');
          ws.getRow(r).height = 8;
          ws.getRow(r).addPageBreak();
          r++;
        }

      } // kraj for mjeseci
      
      // ⭐ v135.7.225: Ako godišnji export i radnik NEMA niti jedan mjesec s aktivnošću,
      //   makni cijeli njegov sheet iz workbook-a (ne kreiraj prazan list u Excelu).
      if (godinaFilter && _mjeseciGen === 0) {
        console.log(`[place godisnji] uklanjam prazan sheet za ${rad.ime} ${rad.prezime} (0 mjeseci s aktivnošću)`);
        wb.removeWorksheet(ws.id);
      }
    } // kraj for radnici
    
    // ⭐ v135.7.225: Defensive — ako svi radnici skipped (0 sheetova), dodaj info sheet
    //   ExcelJS ne dopušta workbook bez sheetova → fallback poruka.
    if (wb.worksheets.length === 0) {
      const wsInfo = wb.addWorksheet('Info');
      wsInfo.getCell('A1').value = `Niti jedan radnik nije imao aktivnosti u razdoblju ${odG}-${String(odM).padStart(2,'0')} do ${doG}-${String(doM).padStart(2,'0')}.`;
      wsInfo.getCell('A1').font = { name: 'Arial', size: 12, bold: true };
      wsInfo.getColumn('A').width = 80;
    }

    // ⭐ v135.7.224: Godišnji koristi statički Place-{godina}.xlsx, range klasičan format
    const fname = godinaFilter
      ? `Place-${godinaFilter}.xlsx`
      : `Place-${String(odG)}-${String(odM).padStart(2,'0')}_${String(doG)}-${String(doM).padStart(2,'0')}.xlsx`;
    const fnameAscii = fname.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'-');
    const buffer = await wb.xlsx.writeBuffer();
    res.set({
      'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition': `attachment; filename="${fnameAscii}"; filename*=UTF-8''${encodeURIComponent(fname)}`
    });
    res.send(buffer);
    
    // ⭐ v135.7.224: Godišnja plaća — auto-upload na QNAP+B2 (kao i mjesečna plaća)
    //   Range bez godinaFilter NE ide na QNAP (custom raspon = ad-hoc, ne treba arhiva)
    if (godinaFilter) {
      setImmediate(() => qnapUploadExcel(Buffer.from(buffer), `Plaća/${fname}`));
    }

  } catch(e) {
    console.error('place export-range:', e.message);
    res.status(500).json({ error: e.message });
  }
});


