app.get('/api/zaduznice/export', auth, staff, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');

    // Dohvati SVU povijest — uključujući obrisane radnike (LEFT JOIN)
    const q = await pool.query(`
      SELECT z.id, z.datum, z.razduzen,
             z.stavke,
             COALESCE(r.ime || ' ' || r.prezime, 'Obrisani radnik ' || COALESCE(z.radnik_id::text,'?')) AS radnik_ime,
             COALESCE(z.radnik_id, 0) AS radnik_id
      FROM zaduznica z
      LEFT JOIN radnici r ON r.id = z.radnik_id
      WHERE r.id IS NULL OR r.role != 'direktor'
      ORDER BY radnik_ime, z.datum DESC, z.id DESC
    `);

    // Grupiraj po radniku
    // Pokušaj dohvatiti updated_at (postoji samo ako je init-db pokrenut)
    let updatedAtMap = {};
    try {
      const uq = await pool.query('SELECT id, updated_at FROM zaduznica WHERE razduzen=true AND updated_at IS NOT NULL');
      uq.rows.forEach(r => { updatedAtMap[r.id] = r.updated_at; });
    } catch { /* kolona ne postoji još */ }

    const byRad = {};
    q.rows.forEach(z => {
      const key = z.radnik_id || 'nepoznat';
      if (!byRad[key]) byRad[key] = { ime: z.radnik_ime, stavke: {} };
      let stavke = [];
      if (Array.isArray(z.stavke)) { stavke = z.stavke; }
      else if (typeof z.stavke === 'string') { try { stavke = JSON.parse(z.stavke); } catch {} }
      else if (z.stavke) { stavke = z.stavke; }
      stavke.forEach(s => {
        const naziv    = typeof s === 'string' ? s : s.naziv;
        const kolicina = typeof s === 'string' ? 1 : (s.kolicina || 1);
        const napomena = typeof s === 'object' ? (s.napomena || '') : '';
        // Ključ = naziv + razduzen status — grupiraj iste alate
        const grpKey = naziv + '||' + (z.razduzen ? '1' : '0');
        if (!byRad[key].stavke[grpKey]) {
          byRad[key].stavke[grpKey] = {
            naziv, kolicina: 0, napomena,
            datum_zaduzenja: z.datum,
            datum_razduzenja: updatedAtMap[z.id] || null,
            razduzen: z.razduzen,
          };
        }
        byRad[key].stavke[grpKey].kolicina += kolicina;
        // Napomena — spoji ako različite
        if (napomena && !byRad[key].stavke[grpKey].napomena.includes(napomena)) {
          byRad[key].stavke[grpKey].napomena = [byRad[key].stavke[grpKey].napomena, napomena].filter(Boolean).join('; ');
        }
      });
    });
    // Pretvori stavke iz objekta u array
    Object.values(byRad).forEach(rad => {
      rad.stavke = Object.values(rad.stavke);
    });

    const wb = new ExcelJS.Workbook();
    const C = {
      RED:   'FFCC0000', BLUE:  'FF1F4E79', GREEN: 'FFE2EFDA',
      GREY:  'FFD9D9D9', WHITE: 'FFFFFFFF', LIGHT: 'FFF2F2F2',
      RAZD:  'FFD9EAD3', // zelenkasta za razduženo
    };
    const fill  = h => ({ type:'pattern', pattern:'solid', fgColor:{argb:h} });
    const font  = (sz=10,bold=false,col='FF000000') => ({name:'Arial',size:sz,bold,color:{argb:col}});
    const aln   = (h='center') => ({horizontal:h,vertical:'middle'});
    const brd   = {top:{style:'thin',color:{argb:'FFAAAAAA'}},bottom:{style:'thin',color:{argb:'FFAAAAAA'}},
                   left:{style:'thin',color:{argb:'FFAAAAAA'}},right:{style:'thin',color:{argb:'FFAAAAAA'}}};

    for (const [key, rad] of Object.entries(byRad)) {
      const ws = wb.addWorksheet(safeSheetName(rad.ime, 'Radnik'));
      ws.pageSetup = { paperSize:9, orientation:'portrait', fitToPage:true, fitToWidth:1 };
      ws.columns = [{width:5},{width:22},{width:8},{width:28},{width:14},{width:14},{width:16}];

      // Naslov
      ws.mergeCells('A1:G1');
      const tc = ws.getCell('A1');
      tc.value = `${rad.ime}  —  Povijest zadužnica`;
      tc.fill=fill(C.RED); tc.font=font(12,true,'FFFFFFFF'); tc.alignment=aln('left');
      ws.getRow(1).height = 24;

      // Zaglavlje
      const hdr = ['Rb','Naziv alata / opreme','Kol.','Napomena','Datum zaduženja','Datum razduženja','Status'];
      hdr.forEach((h,i) => {
        const c = ws.getCell(2, i+1);
        c.value=h; c.fill=fill(C.BLUE); c.font=font(10,true,'FFFFFFFF');
        c.alignment=aln(); c.border=brd;
      });
      ws.getRow(2).height = 18;

      // Stavke — sortiraj: aktivne gore, razdužene ispod
      const aktivne  = rad.stavke.filter(s => !s.razduzen);
      const razduzen = rad.stavke.filter(s =>  s.razduzen);
      const sorted   = [...aktivne, ...razduzen];

      sorted.forEach((s, i) => {
        const r = i + 3;
        const bg = s.razduzen ? C.RAZD : C.WHITE;
        const row = ws.getRow(r);
        const datumZad  = fmtDate(new Date(s.datum_zaduzenja));
        const datumRazd = s.razduzen && s.datum_razduzenja
          ? fmtDate(new Date(s.datum_razduzenja)) : '—';
        const vals = [i+1, s.naziv, s.kolicina || 1, s.napomena || '', datumZad, datumRazd,
                      s.razduzen ? '✓ Razduženo' : '● Kod radnika'];
        vals.forEach((v,col) => {
          const c = ws.getCell(r, col+1);
          c.value=v;
          c.fill=fill(bg);
          c.font=font(10, col===1, s.razduzen ? 'FF555555' : 'FF000000');
          c.alignment = (col===1 || col===3) ? aln('left') : aln();
          c.border=brd;
          if (col===2) { c.numFmt='0'; c.font=font(10,true, s.razduzen?'FF555555':'FF000000'); }
        });
        row.height = 16;
      });

      // Sažetak
      const totRed = sorted.length + 3;
      ws.mergeCells(totRed, 1, totRed, 7);
      const sc = ws.getCell(totRed, 1);
      const ukKol = sorted.reduce((sum,s) => sum + (s.kolicina||1), 0);
      sc.value = `Ukupno stavki: ${sorted.length}  |  Uk. komada: ${ukKol}  |  Aktivno: ${aktivne.length}  |  Razduženo: ${razduzen.length}`;
      sc.fill=fill(C.GREY); sc.font=font(10,true); sc.alignment=aln('left');
      ws.getRow(totRed).height=18;
    }

    const zadBuf = await wb.xlsx.writeBuffer();
    res.set({
      'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition':`attachment; filename="Zaduznica.xlsx"`
    });
    res.send(zadBuf);
    setImmediate(() => qnapUploadExcel(zadBuf, 'Zaduznice/Zaduznica.xlsx'));
  } catch (e) {
    console.error('export zaduznice:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Razduži djelomično — endpoint alias (zadDjelomicno funkcija)
app.put('/api/zaduznica/:id/razduzi-kolicinu', auth, staff, async (req, res) => {
  const { naziv, kolicina_razduzi } = req.body;
  if (!naziv || !kolicina_razduzi) return res.status(400).json({ error: 'Nedostaju podaci' });
  // AUDIT FIX: atomic transakcija s FOR UPDATE lock - sprječava race condition
  // (bez ovoga, dva paralelna razduženja istog naziva mogla bi mimoići se)
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const r = await client.query('SELECT stavke FROM zaduznica WHERE id=$1 FOR UPDATE', [req.params.id]);
    if (!r.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Nije pronađeno' });
    }
    let stavke = r.rows[0].stavke || [];
    if (typeof stavke === 'string') { try { stavke = JSON.parse(stavke); } catch { stavke = []; } }
    if (!Array.isArray(stavke)) stavke = [];
    stavke = stavke.map(s => typeof s === 'string' ? { naziv: s, kolicina: 1 } : { naziv: s.naziv||s, kolicina: parseInt(s.kolicina)||1 });
    const updated = stavke.map(s => {
      if (s.naziv === naziv) {
        const nova = s.kolicina - parseInt(kolicina_razduzi);
        return nova <= 0 ? null : { naziv: s.naziv, kolicina: nova };
      }
      return s;
    }).filter(Boolean);
    if (!updated.length) {
      await client.query('UPDATE zaduznica SET razduzen=true WHERE id=$1', [req.params.id]);
    } else {
      await client.query('UPDATE zaduznica SET stavke=$1::jsonb WHERE id=$2', [JSON.stringify(updated), req.params.id]);
    }
    await client.query('COMMIT');
    res.json({ ok: true, preostalo: updated });
  } catch(e) {
    await client.query('ROLLBACK').catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

