// ⭐ v135.7.374 (Ivan): DB veličina diagnostika
//   Vraća: ukupnu veličinu DB-a, veličinu po tabeli, broj redova.
//   Use case: Ivan provjeri prije migracije fotki base64 → QNAP.
//   Samo direktor (sadrži tehničke detalje o infrastrukturi).
app.get('/api/db-size', auth, direktor, async (req, res) => {
  try {
    // Ukupna veličina DB-a
    const totalR = await pool.query(`
      SELECT pg_size_pretty(pg_database_size(current_database())) AS total_size,
             pg_database_size(current_database()) AS total_bytes
    `);
    
    // Top 15 tabela po veličini (s row count i base64 indikator)
    const tablesR = await pool.query(`
      SELECT 
        relname AS tabela,
        pg_size_pretty(pg_total_relation_size(c.oid)) AS velicina,
        pg_total_relation_size(c.oid) AS bytes,
        (SELECT reltuples::bigint FROM pg_class WHERE relname = c.relname AND relkind = 'r' LIMIT 1) AS approx_rows
      FROM pg_class c
      LEFT JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relkind = 'r'
      ORDER BY pg_total_relation_size(c.oid) DESC
      LIMIT 15
    `);
    
    // Provjeri koje tablice imaju foto_base64 i koliko prostora koriste
    const fotoR = await pool.query(`
      SELECT 'materijal' AS tabela,
             COUNT(*) AS ukupno,
             COUNT(foto_base64) AS sa_base64,
             pg_size_pretty(SUM(LENGTH(foto_base64))::bigint) AS base64_velicina
      FROM materijal
      UNION ALL
      SELECT 'dnevnik', COUNT(*), COUNT(foto_base64), pg_size_pretty(SUM(LENGTH(foto_base64))::bigint) FROM dnevnik
      UNION ALL
      SELECT 'uredaji', COUNT(*), COUNT(foto_base64), pg_size_pretty(SUM(LENGTH(foto_base64))::bigint) FROM uredaji
      UNION ALL  
      SELECT 'smece', COUNT(*), COUNT(foto_base64), pg_size_pretty(SUM(LENGTH(foto_base64))::bigint) FROM smece
    `).catch(() => ({ rows: [] }));
    
    res.json({
      ok: true,
      ukupno: totalR.rows[0],
      tabele: tablesR.rows,
      foto_base64_pregled: fotoR.rows,
      preporuka: totalR.rows[0].total_bytes > 10 * 1024 * 1024 * 1024
        ? '⚠️ DB > 10 GB — preporučujem migraciju fotki base64 → QNAP'
        : totalR.rows[0].total_bytes > 5 * 1024 * 1024 * 1024
        ? '🟡 DB > 5 GB — migracija nije hitna, ali planiraj u sljedećih 3-6 mjeseca'
        : '✅ DB pod 5 GB — migracija fotki nije urgentna'
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.400: SIGURNOSNI DIJAGNOSTIČKI ENDPOINT
//   Public — ne traži auth. Vraća SAMO boolean signale (postoji li env var, 
//   matchne li hash), nikad ne vraća stvarne vrijednosti secret-a.
//   Korisno za debug "Pogrešan PIN" bez exposiranja PIN_PEPPER ili hash-eva.
//   
//   USE: GET /api/diag/pin-check?pin=17081960&ime=Ivan&prezime=Čakarić
//   Vraća: {
//     pepper_set: true/false,
//     init_secret_set: true/false,
//     user_found: true/false,
//     pin_match_with_pepper: true/false,
//     pin_match_without_pepper: true/false,
//     hash_rounds: 12,
//     deployed_version: 'v135.7.X'
//   }
//   Ovaj endpoint će biti UKLONJEN u sljedećoj verziji nakon što se debug završi.
app.get('/api/diag/pin-check', async (req, res) => {
  // ⭐ v421 KRITIČNI FIX (C1): bez INIT_SECRET-a, ovaj endpoint je bio PIN brute-force oracle.
  //   Login je 5/15min rate-limited, ali ovaj endpoint nije bio limited. Plus curi konfiguracijske
  //   informacije (PEPPER status, hash prefix, bcrypt rounds). Zahtjeva INIT_SECRET odsd.
  //   Razmotri ukloniti potpuno nakon što se debug stabilizira.
  if (!checkAndAuditInitSecret(req, res, '/api/diag/pin-check')) return;
  const { pin, ime, prezime } = req.query;
  const result = {
    deployed_version: 'v135.7.410',
    timestamp: new Date().toISOString(),
    pepper_set: !!process.env.PIN_PEPPER,
    pepper_length: (process.env.PIN_PEPPER || '').length,
    init_secret_set: !!process.env.INIT_SECRET,
    jwt_secret_set: !!process.env.JWT_SECRET,
    bcrypt_rounds: 12,
    user_lookup: null,
    pin_match_with_pepper: null,
    pin_match_without_pepper: null,
    advice: null
  };
  
  if (!pin || !ime || !prezime) {
    result.advice = 'Pošalji ?pin=...&ime=...&prezime=... za pin check';
    return res.json(result);
  }
  
  try {
    const r = await pool.query(
      'SELECT id, ime, prezime, role, aktivan, pin FROM radnici WHERE ime=$1 AND prezime=$2',
      [ime, prezime]
    );
    
    if (!r.rows.length) {
      result.user_lookup = 'NOT_FOUND';
      result.advice = `Korisnik ${ime} ${prezime} ne postoji u DB. Pokreni /api/init-db?key=<INIT_SECRET>.`;
      return res.json(result);
    }
    
    const u = r.rows[0];
    result.user_lookup = { id: u.id, role: u.role, aktivan: u.aktivan };
    
    // Test bcrypt s PEPPER-om
    const pepperVal = process.env.PIN_PEPPER || '';
    result.pin_match_with_pepper = await bcrypt.compare(String(pin) + pepperVal, u.pin);
    
    // Test bcrypt BEZ PEPPER-a
    result.pin_match_without_pepper = await bcrypt.compare(String(pin), u.pin);
    
    // Detektiraj rounds iz hash-a
    const roundsMatch = u.pin.match(/^\$2[aby]\$(\d{1,2})\$/);
    result.hash_rounds_actual = roundsMatch ? parseInt(roundsMatch[1]) : null;
    
    // Inteligentna preporuka
    if (result.pin_match_with_pepper) {
      result.advice = '✅ PIN match s PEPPER-om — login bi trebao raditi. Problem je možda u frontend-u (stari Service Worker?). Probaj hard refresh (Ctrl+Shift+R) ili inkognito mod.';
    } else if (result.pin_match_without_pepper && !result.pepper_set) {
      result.advice = '⚠ PEPPER NIJE postavljen u env vars, ali PIN match radi bez PEPPER-a. Postavi PIN_PEPPER env var na Railway i restart-aj container.';
    } else if (result.pin_match_without_pepper && result.pepper_set) {
      result.advice = '🔴 KRITIČNO: PEPPER je postavljen SAD, ali DB hash je iz vremena PRIJE PEPPER-a (ili s drugim PEPPER-om). Trebaš pokrenuti /api/init-db?key=<INIT_SECRET> da rehash-aš PIN-ove s aktualnim PEPPER-om.';
    } else if (!result.pin_match_without_pepper && !result.pin_match_with_pepper) {
      result.advice = '🔴 PIN se ne podudara ni sa ni bez PEPPER-a. Provjeri: 1) je li PIN zaista 17081960, 2) je li init-db pokrenut nakon zadnjeg deploy-a.';
    }
    
    // NE VRAĆAJ hash, samo prefix za debugging
    result.hash_prefix = u.pin.substring(0, 7) + '...';
    
    // ⭐ v135.7.401: Provjeri push subscriptions za direktora
    const pushSubs = await pool.query(
      "SELECT id, created_at FROM push_subscriptions WHERE radnik_id = $1",
      [u.id]
    ).catch(() => ({ rows: [] }));
    result.push_subscriptions_count = pushSubs.rows.length;
    result.push_subscriptions_oldest = pushSubs.rows[0]?.created_at || null;
    
  } catch (e) {
    result.error = e.message;
  }
  
  res.json(result);
});

