// ⭐ v135.7.404: Diagnostic — provjeri postoje li HR kolone u radnici tablici.
//   Ako migracije nisu prošle iz nekog razloga, ovo će reći točno koje kolone fale.
//   USE: GET /api/diag/radnici-schema
app.get('/api/diag/radnici-schema', auth, direktor, async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT column_name, data_type, is_nullable 
      FROM information_schema.columns 
      WHERE table_name = 'radnici'
      ORDER BY ordinal_position
    `);
    
    const cols = r.rows.map(row => row.column_name);
    const required = ['oib', 'datum_rodjenja', 'mjesto_rodjenja', 'drzava_rodjenja', 'datum_hzmo_prijave'];
    const missing = required.filter(c => !cols.includes(c));
    
    // Pokušaj SELECT sa svim HR poljima da vidimo da li UPDATE čak ide u DB
    let sampleData = null;
    try {
      const sample = await pool.query(`
        SELECT id, ime, prezime, oib, datum_rodjenja, mjesto_rodjenja, drzava_rodjenja, datum_hzmo_prijave
        FROM radnici WHERE aktivan=true LIMIT 5
      `);
      sampleData = sample.rows.map(row => ({
        id: row.id,
        ime: row.ime + ' ' + row.prezime,
        oib: row.oib || null,
        datum_rodjenja: row.datum_rodjenja || null,
        mjesto_rodjenja: row.mjesto_rodjenja || null,
        drzava_rodjenja: row.drzava_rodjenja || null,
        datum_hzmo_prijave: row.datum_hzmo_prijave || null,
        ima_neki_hr_podatak: !!(row.oib || row.datum_rodjenja || row.mjesto_rodjenja || row.drzava_rodjenja || row.datum_hzmo_prijave)
      }));
    } catch (eSel) {
      sampleData = { error: eSel.message };
    }
    
    res.json({
      ok: missing.length === 0,
      all_columns: cols,
      hr_columns_required: required,
      hr_columns_missing: missing,
      sample_data_5_radnici: sampleData,
      advice: missing.length > 0 
        ? `KOLONE FALE: ${missing.join(', ')}. Pokreni /api/init-db?key=<INIT_SECRET> da execute-aš ALTER TABLE.`
        : 'Sve HR kolone postoje. Ako podaci ne perziste, problem je u SELECT-u (već popravljeno u v404).'
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/health', async (req, res) => {
  const result = {
    ok: true,
    ts: new Date().toISOString(),
    // ⭐ v135.7.217: Generic version (sprečava recon na specifične exploit-e)
    version: 'production',
    components: {
      server: 'ok',
      database: 'unknown',
      qnap: 'unknown'
    },
    response_time_ms: {},
    // ⭐ v502.20.7 (Ivan, 27.05.2026): pool stats za dijagnostiku spore prijave
    //   totalCount = ukupno otvorenih connection-a
    //   idleCount = slobodne (spremne za korištenje)
    //   waitingCount = zahtjevi koji čekaju slobodnu connection (BAD ako > 0)
    //   AKO waitingCount > 0 → pool je zagušen, login će biti spor
    pool_stats: {
      total: pool.totalCount,        // koliko ukupno
      idle: pool.idleCount,          // slobodno
      waiting: pool.waitingCount,    // čeka u queue (alarmantno ako > 0)
      max: pool.options?.max || 10
    },
    // ⭐ v502.20.8 (Ivan, 27.05.2026): QNAP circuit breaker status
    //   Ako je circuit OPEN, app preskače QNAP zahtjeve → brže odgovara,
    //   ali foto upload-i ne rade dok se QNAP ne oporavi.
    qnap_circuit: {
      open: !!_qnapCircuit.openedAt,
      failures_recent: _qnapCircuit.failures.length,
      threshold: _qnapCircuit.threshold,
      opened_at: _qnapCircuit.openedAt ? new Date(_qnapCircuit.openedAt).toISOString() : null
    }
  };
  
  const startTime = Date.now();
  
  // 1. Database — SELECT 1 query s 3s timeout
  try {
    const dbStart = Date.now();
    await Promise.race([
      pool.query('SELECT 1'),
      new Promise((_, reject) => setTimeout(() => reject(new Error('DB timeout')), 3000))
    ]);
    result.components.database = 'ok';
    result.response_time_ms.database = Date.now() - dbStart;
  } catch (e) {
    result.components.database = 'fail: ' + (e.message || 'unknown');
    result.ok = false;
  }
  
  // 2. QNAP — PROPFIND na /APLIKACIJA path s 5s timeout
  //    ⭐ v135.7.201: Promijenjeno iz HEAD na root (vraćao 403 jer WebDAV root je restricted)
  //    na PROPFIND na /APLIKACIJA folder — to je standardna WebDAV operacija "list directory"
  //    koju naš server normalno koristi. Ako ova radi, QNAP je živ i autentikacija ispravna.
  if (process.env.QNAP_WEBDAV_URL) {
    try {
      const qnapStart = Date.now();
      const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
      const basePath = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
      const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
      const ctrl = new AbortController();
      const timeoutId = setTimeout(() => ctrl.abort(), 5000);
      const r = await fetch(`${baseUrl}${basePath}`, {
        method: 'PROPFIND',
        headers: { 
          Authorization: `Basic ${auth64}`,
          'Depth': '0',  // Samo metadata folder-a (ne sadržaj)
          'Content-Type': 'application/xml'
        },
        signal: ctrl.signal
      });
      clearTimeout(timeoutId);
      // WebDAV PROPFIND vraća 207 (Multi-Status) kad uspije
      // 200 = također OK
      // 401/403 = autentikacija/autorizacija problem (server radi, ali konfiguracija)
      // 404 = folder ne postoji (problem u konfiguraciji ali server radi)
      // 405 = metoda nije dozvoljena (server radi, ali ne podržava PROPFIND)
      if (r.status === 207 || r.status === 200) {
        result.components.qnap = 'ok';
        // ⭐ v502.20.21 (Ivan, 27.05.2026): auto-zatvori circuit ako je bio otvoren
        //   QNAP health check uspio → QNAP je živ → circuit ne smije biti otvoren.
        //   Ovo automatski "popravlja" recovery od QNAP outage-a bez intervencije.
        if (_qnapCircuit.openedAt) {
          console.log('[health] QNAP health OK, auto-zatvaram circuit');
          _qnapCircuitRecord(true);  // marker uspjeha = reset circuit
        }
      } else if (r.status === 401 || r.status === 403) {
        // Server odgovara, ali autorizacija krivo postavljena
        result.components.qnap = `auth_issue: HTTP ${r.status} (server radi, provjeri credentials)`;
        // NE postavljamo result.ok = false — server radi, samo konfiguracija
      } else if (r.status === 404) {
        result.components.qnap = `path_missing: HTTP 404 (folder ${basePath} ne postoji)`;
      } else if (r.status === 405) {
        // PROPFIND not supported — pokušaj HEAD kao fallback
        result.components.qnap = `ok (PROPFIND not supported, HTTP ${r.status})`;
      } else {
        result.components.qnap = `unexpected: HTTP ${r.status}`;
      }
      result.response_time_ms.qnap = Date.now() - qnapStart;
    } catch (e) {
      // Network error / timeout — QNAP ne odgovara
      result.components.qnap = 'unreachable: ' + (e.message || 'unknown');
      // QNAP fail nije fatalni — server može raditi i bez njega (slike fail-aju ali ostalo radi)
      // result.ok = false;  // ← NE postavljamo na false jer DB radi i to je glavna stvar
    }
  } else {
    result.components.qnap = 'not_configured';
  }
  
  result.response_time_ms.total = Date.now() - startTime;
  
  // HTTP 503 (Service Unavailable) ako kritična komponenta ne radi (samo DB)
  if (!result.ok) {
    return res.status(503).json(result);
  }
  res.json(result);
});

// ⭐ v501.46 (Ivan): PDF ASSETS DIAGNOSTICS
//   Direktor može provjeriti jesu li svi PDF assets (potpis, pečat, fontovi, logo) učitani.
//   Bug: ako su PNG/TTF fajlovi forgotten iz git repo ili Railway deploy, PDF generation
//   se ne ruši nego silently fallback-a na placeholder (krug umjesto pečata).
//   Endpoint vraća jasan status svakog asseta + file size.
app.get('/api/pdf-assets/status', auth, direktor, async (req, res) => {
  try {
    const path = require('path');
    const fs = require('fs');
    
    // ⭐ v501.47: ?force=1 — invalidira cache da pokušaj ponovno učitati assets
    //   (korisno ako si upload-ao fajl tijekom dok server radi i ne želiš restart)
    if (req.query.force === '1') {
      PDF_ASSETS._loaded = false;
      PDF_ASSETS.potpis = null;
      PDF_ASSETS.pecat = null;
      PDF_ASSETS.logos = { light: null, dark: null };
    }
    
    _loadPDFAssets();
    
    const assets = [
      { naziv: 'DejaVuSans.ttf',           tip: 'font_reg',  path: PDF_ASSETS.fonts.reg },
      { naziv: 'DejaVuSans-Bold.ttf',      tip: 'font_bold', path: PDF_ASSETS.fonts.bold },
      { naziv: 'logo_light.png',           tip: 'logo',      path: PDF_ASSETS.logos.light },
      { naziv: 'logo_dark.png',            tip: 'logo',      path: PDF_ASSETS.logos.dark },
      { naziv: 'potpis_Ivan.png',          tip: 'potpis',    path: PDF_ASSETS.potpis },
      { naziv: 'Zbuka_Cakaric_Pecat.png',  tip: 'pecat',     path: PDF_ASSETS.pecat }
    ];
    
    const out = assets.map(a => {
      const result = { naziv: a.naziv, tip: a.tip, ucitan: !!a.path };
      if (a.path) {
        try {
          const stat = fs.statSync(a.path);
          result.path = a.path;
          result.velicina_bytes = stat.size;
          result.modificiran = stat.mtime.toISOString();
        } catch (e) {
          result.ucitan = false;
          result.error = e.message;
        }
      } else {
        // Probaj naći datoteku u __dirname (možda je tu ali nije učitan iz nekog razloga)
        const fallbackPath = path.join(__dirname, a.naziv);
        if (fs.existsSync(fallbackPath)) {
          result.napomena = `Fajl postoji na ${fallbackPath}, ali nije učitan u PDF_ASSETS — pokušaj restart`;
        } else {
          result.napomena = `Fajl ne postoji na ${fallbackPath} — TREBA DEPLOYAT s repom`;
        }
      }
      return result;
    });
    
    // ⭐ v501.47 (Ivan): DEBUG — lista svih fajlova u __dirname (slike + fontovi)
    //   Ovo pokazuje TOČNO što Railway vidi u root direktoriju.
    //   Ako pečat nedostaje, Ivan može vidjeti koji su nazivi PNG fajlova u repo-u.
    let rootFiles = { slike: [], fontovi: [], ukupno_fajlova: 0 };
    try {
      const allFiles = fs.readdirSync(__dirname);
      rootFiles.ukupno_fajlova = allFiles.length;
      rootFiles.slike = allFiles.filter(f => /\.(png|jpg|jpeg|gif|svg)$/i.test(f));
      rootFiles.fontovi = allFiles.filter(f => /\.(ttf|otf|woff|woff2)$/i.test(f));
    } catch (e) {
      rootFiles.error = e.message;
    }
    
    const sviUcitani = out.every(a => a.ucitan);
    res.json({
      ok: sviUcitani,
      svi_ucitani: sviUcitani,
      ts: new Date().toISOString(),
      __dirname,
      root_directory_contents: rootFiles,
      assets: out,
      napomena: sviUcitani 
        ? '✅ Svi PDF assets su učitani. Pečat će biti vidljiv u PDF-u.'
        : '⚠ NEKI ASSETS NEDOSTAJU. Provjeri "root_directory_contents.slike" niže — koji su PNG fajlovi stvarno u Railway repo-u? Možda su nazivi različiti od očekivanih (case-sensitive!)'
    });
  } catch (e) {
    console.error('GET /pdf-assets/status:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.208: Pojačani diagnostic — upload, list, fetch da vidimo gdje fajlovi nestaju
// ⭐ v135.7.217: Auth + direktor only (sigurnost — ne otkrivati cloud strukturu)
app.get('/api/b2/full-test', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  if (!b2Enabled()) return res.json({ ok: false, error: 'B2 nije aktiviran' });
  
  const result = {
    ts: new Date().toISOString(),
    steps: []
  };
  
  try {
    // Step 1: Auth
    _b2AuthCache = null;
    const auth = await b2Authorize();
    if (!auth) {
      result.steps.push({ step: 'auth', ok: false });
      return res.json(result);
    }
    result.steps.push({ 
      step: 'auth', 
      ok: true, 
      bucketId: auth.bucketId,
      bucketName: auth.bucketName,
      apiUrl: auth.apiUrl
    });
    
    // Step 2: List files BEFORE upload
    const listResBefore = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ bucketId: auth.bucketId, maxFileCount: 100 })
    });
    const listDataBefore = await listResBefore.json();
    result.steps.push({ 
      step: 'list_before', 
      ok: listResBefore.ok,
      file_count: (listDataBefore.files || []).length,
      first_files: (listDataBefore.files || []).slice(0, 5).map(f => f.fileName)
    });
    
    // Step 3: Get upload URL
    const urlRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_get_upload_url`, {
      method: 'POST',
      headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ bucketId: auth.bucketId })
    });
    const urlBody = await urlRes.text();
    let urlData;
    try { urlData = JSON.parse(urlBody); } catch(e) {}
    result.steps.push({ 
      step: 'get_upload_url', 
      ok: urlRes.ok,
      status: urlRes.status,
      body_preview: urlBody.slice(0, 200),
      uploadUrl_prefix: urlData?.uploadUrl ? urlData.uploadUrl.slice(0, 60) : null
    });
    
    if (!urlRes.ok || !urlData) {
      return res.json(result);
    }
    
    // Step 4: Upload test fajla
    const testPath = `Diagnostic/full-test-${Date.now()}.txt`;
    const testBody = Buffer.from(`Full test ${new Date().toISOString()}`);
    const sha1 = require('crypto').createHash('sha1').update(testBody).digest('hex');
    
    const uploadRes = await fetch(urlData.uploadUrl, {
      method: 'POST',
      headers: {
        Authorization: urlData.authorizationToken,
        'Content-Type': 'text/plain',
        'Content-Length': testBody.length.toString(),
        'X-Bz-File-Name': encodeURIComponent(testPath),
        'X-Bz-Content-Sha1': sha1,
      },
      body: testBody
    });
    const uploadBody = await uploadRes.text();
    let uploadJson;
    try { uploadJson = JSON.parse(uploadBody); } catch(e) {}
    result.steps.push({ 
      step: 'upload', 
      ok: uploadRes.ok,
      status: uploadRes.status,
      body_preview: uploadBody.slice(0, 300),
      fileId: uploadJson?.fileId || null,
      fileName: uploadJson?.fileName || null,
      bucketId_returned: uploadJson?.bucketId || null,
      bucketId_expected: auth.bucketId,
      bucket_match: uploadJson?.bucketId === auth.bucketId
    });
    
    // Step 5: List files AFTER upload (provjera da je stigao)
    await new Promise(r => setTimeout(r, 1000));  // 1s delay za eventual consistency
    const listResAfter = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ bucketId: auth.bucketId, maxFileCount: 100 })
    });
    const listDataAfter = await listResAfter.json();
    const filesAfter = listDataAfter.files || [];
    const testFileFound = filesAfter.find(f => f.fileName === testPath);
    result.steps.push({ 
      step: 'list_after', 
      ok: listResAfter.ok,
      file_count: filesAfter.length,
      test_file_found: !!testFileFound,
      test_file_details: testFileFound ? {
        fileName: testFileFound.fileName,
        contentLength: testFileFound.contentLength,
        uploadTimestamp: new Date(testFileFound.uploadTimestamp).toISOString()
      } : null,
      all_files_in_bucket: filesAfter.map(f => f.fileName)
    });
    
    // Step 6: Fetch test fajla preko download URL-a
    const downloadUrl = `${auth.downloadUrl}/file/${auth.bucketName}/${testPath.split('/').map(encodeURIComponent).join('/')}`;
    const fetchRes = await fetch(downloadUrl, {
      headers: { Authorization: auth.authToken }
    });
    const fetchBody = fetchRes.ok ? await fetchRes.text() : await fetchRes.text();
    result.steps.push({ 
      step: 'fetch', 
      ok: fetchRes.ok,
      status: fetchRes.status,
      url: downloadUrl,
      body_preview: fetchBody.slice(0, 100),
      content_match: fetchBody === testBody.toString()
    });
    
    // Step 7: Cleanup test fajla (ne ostavljaj smeće)
    if (uploadJson?.fileId) {
      const delRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_delete_file_version`, {
        method: 'POST',
        headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
        body: JSON.stringify({ fileId: uploadJson.fileId, fileName: testPath })
      });
      result.steps.push({ 
        step: 'cleanup', 
        ok: delRes.ok 
      });
    }
    
    result.summary = result.steps.every(s => s.ok) ? '✅ Sve OK' : '⚠ Neke faze fail-ale';
    res.json(result);
  } catch(e) {
    result.error = e.message;
    res.json(result);
  }
});


//   GET /api/b2/list?prefix=Materijali/&maxFiles=20 — bez auth-a
//   Vraća popis fajlova s veličinom i datumima.
//   Pomaže kad Backblaze dashboard ne pokazuje aktualne podatke (cache).
// ⭐ v135.7.217: Auth + direktor (sprečava unauthorized list cloud-a)
// ⭐ v135.7.222: CLEANUP STARIH DATUMSKIH EXCEL FAJLOVA (Sihterica + Smece)
// ⭐ v135.7.223: Prošireno za Dnevnik (filtrirani exporti)
//   POST /api/cleanup-old-excels (samo direktor)
//   
//   Use case: Stari Sihterica/Dnevnik exporti su se akumulirali (30+ fajlova) jer
//   su filename-i sadržavali datum/filter info. Od v222/v223 koristimo statična/godišnja
//   imena. Ovaj endpoint briše stare fajlove i s QNAP-a i s B2-a.
//   
//   ŠTO BRIŠE:
//     - Sihterica/Sihterica-YYYY-MM-DD.xlsx (datumski format)
//     - Smece/Smece_YYYY-MM-DD.xlsx (datumski format) — od v222 se ne radi više
//     - Dnevnik/Dnevnik-{naziv}_*.xlsx (filtrirani exporti — datum range u imenu)
//     - Dnevnik/Dnevnik_*.xlsx (filtrirani datum exporti bez gradilišta)
//   ŠTO ZADRŽAVA:
//     - Sihterica/Sihterica-YYYY.xlsx (godišnji format — novo)
//     - Sihterica/Sihterica-po-gradilistima.xlsx (statičko ime)
//     - Smece/Smece.xlsx (statičko ime — novo)
//     - Dnevnik/Dnevnik.xlsx (statičko, sve gradilište)
//     - Dnevnik/Dnevnik-YYYY.xlsx (godišnji)
//     - Materijali/Materijali.xlsx + Materijali-YYYY.xlsx
app.post('/api/cleanup-old-excels', auth, direktor, async (req, res) => {
  const result = {
    qnap: { deleted: [], errors: [] },
    b2: { deleted: [], errors: [] },
    summary: { total_deleted: 0 }
  };
  
  // Pattern matchers
  const isOldSihterica = (name) => /^Sihterica-\d{4}-\d{2}-\d{2}\.xlsx$/.test(name);
  const isOldSmece = (name) => /^Smece_\d{4}-\d{2}-\d{2}\.xlsx$/.test(name);
  // Dnevnik filtrirani: Dnevnik-{naziv}_2026-01-01.xlsx, Dnevnik_2026-01-01_do_2026-12-31.xlsx, itd.
  // Sve što ima datum u imenu — briše se
  const isOldDnevnik = (name) => {
    if (!/^Dnevnik[\-_]/.test(name)) return false;
    if (!name.endsWith('.xlsx')) return false;
    // Zadržava: Dnevnik.xlsx, Dnevnik-2026.xlsx (samo godina, bez datuma)
    if (/^Dnevnik\.xlsx$/.test(name)) return false;
    if (/^Dnevnik-\d{4}\.xlsx$/.test(name)) return false;
    // Briše: sve s datumom YYYY-MM-DD u imenu
    return /\d{4}-\d{2}-\d{2}/.test(name);
  };
  const shouldDelete = (folder, name) => {
    if (folder === 'Sihterica' && isOldSihterica(name)) return true;
    if (folder === 'Smece' && isOldSmece(name)) return true;
    if (folder === 'Dnevnik' && isOldDnevnik(name)) return true;
    return false;
  };
  
  // === QNAP cleanup ===
  if (process.env.QNAP_WEBDAV_URL) {
    try {
      const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
      const base = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
      const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
      const hdrs = { Authorization: `Basic ${auth64}` };
      
      for (const folder of ['Sihterica', 'Smece', 'Dnevnik']) {
        try {
          // PROPFIND za listu fajlova u folderu
          const propResp = await fetch(`${baseUrl}${base}/${folder}/`, {
            method: 'PROPFIND',
            headers: { ...hdrs, Depth: '1', 'Content-Type': 'application/xml' },
            body: '<?xml version="1.0"?><propfind xmlns="DAV:"><prop><displayname/></prop></propfind>',
            signal: AbortSignal.timeout(15000)
          });
          
          if (!propResp.ok) {
            result.qnap.errors.push(`${folder}/: PROPFIND HTTP ${propResp.status}`);
            continue;
          }
          
          const xml = await propResp.text();
          const fnames = [...xml.matchAll(/<(?:d:)?displayname>([^<]+)<\//g)].map(m => m[1]);
          
          for (const fname of fnames) {
            if (!shouldDelete(folder, fname)) continue;
            try {
              const delResp = await fetch(`${baseUrl}${base}/${folder}/${encodeURIComponent(fname)}`, {
                method: 'DELETE',
                headers: hdrs,
                signal: AbortSignal.timeout(10000)
              });
              if (delResp.ok || delResp.status === 204) {
                result.qnap.deleted.push(`${folder}/${fname}`);
                console.log(`[cleanup-old-excels] QNAP DELETE OK: ${folder}/${fname}`);
              } else {
                result.qnap.errors.push(`${folder}/${fname}: HTTP ${delResp.status}`);
              }
            } catch(e) {
              result.qnap.errors.push(`${folder}/${fname}: ${e.message}`);
            }
          }
        } catch(e) {
          result.qnap.errors.push(`${folder}/: ${e.message}`);
        }
      }
    } catch(e) {
      result.qnap.errors.push(`QNAP global: ${e.message}`);
    }
  }
  
  // === B2 cleanup ===
  if (b2Enabled()) {
    try {
      const auth2 = await b2Authorize();
      if (!auth2) {
        result.b2.errors.push('B2 auth fail');
      } else {
        for (const folder of ['Sihterica', 'Smece', 'Dnevnik']) {
          try {
            // List files s prefix-om
            const listRes = await fetch(`${auth2.apiUrl}/b2api/v3/b2_list_file_names`, {
              method: 'POST',
              headers: { Authorization: auth2.authToken, 'Content-Type': 'application/json' },
              body: JSON.stringify({ bucketId: auth2.bucketId, maxFileCount: 1000, prefix: `${folder}/` }),
              signal: AbortSignal.timeout(15000)
            });
            
            if (!listRes.ok) {
              result.b2.errors.push(`${folder}/: list HTTP ${listRes.status}`);
              continue;
            }
            
            const listData = await listRes.json();
            const files = listData.files || [];
            
            for (const f of files) {
              const justName = f.fileName.split('/').pop();
              if (!shouldDelete(folder, justName)) continue;
              try {
                // B2 brisanje treba fileName + fileId
                const delRes = await fetch(`${auth2.apiUrl}/b2api/v3/b2_delete_file_version`, {
                  method: 'POST',
                  headers: { Authorization: auth2.authToken, 'Content-Type': 'application/json' },
                  body: JSON.stringify({ fileName: f.fileName, fileId: f.fileId }),
                  signal: AbortSignal.timeout(10000)
                });
                if (delRes.ok) {
                  result.b2.deleted.push(f.fileName);
                  console.log(`[cleanup-old-excels] B2 DELETE OK: ${f.fileName}`);
                } else {
                  result.b2.errors.push(`${f.fileName}: HTTP ${delRes.status}`);
                }
              } catch(e) {
                result.b2.errors.push(`${f.fileName}: ${e.message}`);
              }
            }
          } catch(e) {
            result.b2.errors.push(`${folder}/: ${e.message}`);
          }
        }
      }
    } catch(e) {
      result.b2.errors.push(`B2 global: ${e.message}`);
    }
  }
  
  result.summary.total_deleted = result.qnap.deleted.length + result.b2.deleted.length;
  result.summary.total_errors = result.qnap.errors.length + result.b2.errors.length;
  
  console.log(`[cleanup-old-excels] Završeno: ${result.summary.total_deleted} obrisano, ${result.summary.total_errors} grešaka`);
  res.json(result);
});

// ⭐ v135.7.215: Direktni B2 list — vidi koliko fajlova ima u bucketu prema folderu
//   GET /api/b2/list?prefix=Materijali/&maxFiles=20 — bez auth-a
//   Vraća popis fajlova s veličinom i datumima.
//   Pomaže kad Backblaze dashboard ne pokazuje aktualne podatke (cache).
// ⭐ v135.7.217: Auth + direktor (sprečava unauthorized list cloud-a)
app.get('/api/b2/list', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  if (!b2Enabled()) {
    return res.json({ ok: false, error: 'B2 nije aktiviran' });
  }
  try {
    const auth2 = await b2Authorize();
    if (!auth2) {
      return res.json({ ok: false, error: 'B2 auth fail' });
    }
    
    const prefix = String(req.query.prefix || '').replace(/^\//, '');
    const maxFiles = Math.min(parseInt(req.query.maxFiles) || 20, 100);
    
    // ⭐ v135.7.221: Bug fix — koristi auth2 (ne globalni auth)
    const listRes = await fetch(`${auth2.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { 
        Authorization: auth2.authToken, 
        'Content-Type': 'application/json' 
      },
      body: JSON.stringify({ 
        bucketId: auth2.bucketId, 
        maxFileCount: maxFiles,
        prefix: prefix || ''
      }),
      signal: AbortSignal.timeout(10000)
    });
    
    if (!listRes.ok) {
      return res.json({ ok: false, error: `B2 list HTTP ${listRes.status}` });
    }
    const listData = await listRes.json();
    
    const files = (listData.files || []).map(f => ({
      name: f.fileName,
      size_bytes: f.contentLength,
      size_kb: Math.round(f.contentLength / 1024 * 10) / 10,
      uploaded: new Date(f.uploadTimestamp).toISOString(),
      content_type: f.contentType
    }));
    
    // Statistika
    const totalSize = files.reduce((s, f) => s + f.size_bytes, 0);
    const byPrefix = {};
    files.forEach(f => {
      const folder = f.name.split('/').slice(0, -1).join('/') || '(root)';
      if (!byPrefix[folder]) byPrefix[folder] = { count: 0, size_bytes: 0 };
      byPrefix[folder].count++;
      byPrefix[folder].size_bytes += f.size_bytes;
    });
    
    res.json({
      ok: true,
      bucket: auth2.bucketName,
      prefix: prefix || '(all)',
      total_files: files.length,
      total_size_kb: Math.round(totalSize / 1024 * 10) / 10,
      total_size_mb: Math.round(totalSize / 1024 / 1024 * 100) / 100,
      by_folder: byPrefix,
      files: files.slice(0, 50)  // limit za response veličinu
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

// ⭐ v135.7.207: Verifikacija određenog fajla — provjeri postoji li specifični path na B2
// ⭐ v135.7.217: Auth required (sprečava unauthorized recon B2 file structure)
//   PRIJE: bilo tko mogao pogoditi path i dobiti veličinu → recon attack
//   SAD: zahtijeva login (any staff)
app.get('/api/b2/check', auth, async (req, res) => {
  if (!b2Enabled()) return res.json({ ok: false, error: 'B2 nije aktiviran' });
  
  const filePath = String(req.query.path || '').replace(/^\//, '');
  if (!filePath) return res.status(400).json({ error: 'Nedostaje ?path=' });
  // Path traversal protection
  if (filePath.includes('..') || filePath.includes('//')) {
    return res.status(400).json({ error: 'Nevažeći path' });
  }
  
  try {
    const buf = await b2FetchBuffer(filePath);
    if (buf) {
      res.json({ 
        ok: true, 
        path: filePath, 
        size_bytes: buf.length,
        size_kb: Math.round(buf.length / 1024 * 10) / 10
      });
    } else {
      res.json({ ok: false, path: filePath, error: 'Fajl ne postoji ili ne mogu ga fetchati' });
    }
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

// ⭐ v502.20.19 (Ivan, 27.05.2026): Ručni reset QNAP circuit breaker-a
//   Use case: QNAP se vratio online, ali circuit još uvijek otvoren (do 30s cooldown).
//   GET /api/qnap/reset-circuit (direktor) → odmah forsira retest.
app.get('/api/qnap/reset-circuit', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor' });
  const wasOpen = !!_qnapCircuit.openedAt;
  const failCount = _qnapCircuit.failures.length;
  _qnapCircuit.openedAt = 0;
  _qnapCircuit.failures = [];
  console.log(`[qnap-circuit] RUČNI RESET — was open=${wasOpen}, fails=${failCount}`);
  res.json({ ok: true, was_open: wasOpen, fail_count_before: failCount, reset: true });
});

// ⭐ v502.20.27 (Ivan, 27.05.2026): QNAP storage scan endpoint
//   Rekurzivno skenira /APLIKACIJA folder na QNAP-u i vraća EGZAKTNU veličinu
//   svih file-ova (uključujući backup foldere, sistemske fajlove, itd).
//   
//   Use: GET /api/qnap/storage-scan?force=1 (samo direktor)
//   - force=1 preskoči cache (default cache 1h)
//   - vraća total + breakdown po top-level folderima
//   - takes ~30-60 sekundi za prvi scan, instant iz cache-a
app.get('/api/qnap/storage-scan', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor' });
  if (!process.env.QNAP_WEBDAV_URL) return res.status(503).json({ error: 'QNAP nije konfiguriran' });
  
  const force = req.query.force === '1';
  
  // Cache check
  if (!force && _qnapStorageCache && (Date.now() - _qnapStorageCache.ts) < QNAP_STORAGE_CACHE_TTL) {
    const ageMin = Math.round((Date.now() - _qnapStorageCache.ts) / 60000);
    return res.json({
      ...(_qnapStorageCache.result),
      from_cache: true,
      cache_age_min: ageMin
    });
  }
  
  try {
    const basePath = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
    console.log(`[qnap-storage-scan] Pokrećem rekurzivni scan ${basePath}...`);
    
    const result = await qnapStorageScan(basePath);
    
    console.log(`[qnap-storage-scan] DONE ${(result.totalMb).toFixed(1)} MB, ${result.totalFiles} fajlova, ${result.scanDurationMs} ms`);
    
    // Cache rezultat
    _qnapStorageCache = { ts: Date.now(), result };
    
    res.json({
      ...result,
      from_cache: false
    });
  } catch(e) {
    console.error('[qnap-storage-scan]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v502.20.19 (Ivan, 27.05.2026): DIAGNOSTIC za reference portfolio export bug
//   ⭐ v502.20.22: razširen — testira raw QNAP fetch (bez circuit breaker-a) + B2 + thumb
//   Use: GET /api/reference/portfolio-diag?grad_id=X (samo direktor)
//   Vraća za svaku referencu: id, qnap_path, b2_path, thumb_size + 3 testa.
app.get('/api/reference/portfolio-diag', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor' });
  const gid = parseInt(req.query.grad_id);
  if (!gid) return res.status(400).json({ error: 'Nedostaje ?grad_id=' });
  
  try {
    // ⭐ v502.20.25 (Ivan, 27.05.2026): defensive SELECT za predmigracijske baze
    let r;
    try {
      r = await pool.query(`
        SELECT id, qnap_path, b2_path, 
               (thumb_base64 IS NOT NULL) AS has_thumb,
               LENGTH(thumb_base64) AS thumb_size,
               created_at
        FROM fasada_reference 
        WHERE gradiliste_id = $1 
        ORDER BY created_at DESC LIMIT 10
      `, [gid]);
    } catch(colErr) {
      console.warn('[portfolio-diag] DB kolona fallback:', colErr.message);
      r = await pool.query(`
        SELECT id, qnap_path, created_at
        FROM fasada_reference 
        WHERE gradiliste_id = $1 
        ORDER BY created_at DESC LIMIT 10
      `, [gid]);
      // Defensive: dodaj prazna polja
      r.rows.forEach(row => {
        row.b2_path = null;
        row.has_thumb = false;
        row.thumb_size = 0;
      });
    }
    
    const diag = [];
    for (const row of r.rows) {
      const item = {
        id: row.id,
        qnap_path: row.qnap_path || null,
        b2_path: row.b2_path || null,
        has_thumb: row.has_thumb,
        thumb_size_bytes: row.thumb_size || 0,
        created_at: row.created_at,
        tests: {}
      };
      
      // Test 1: B2 fetch ako b2_path postoji
      if (row.b2_path) {
        try {
          const t0 = Date.now();
          const buf = await b2FetchBuffer(row.b2_path, 5000);
          item.tests.b2_fetch = buf 
            ? `OK (${Math.round(buf.length/1024)} KB, ${Date.now()-t0}ms)` 
            : `NULL (fail nakon ${Date.now()-t0}ms)`;
        } catch(e) { item.tests.b2_fetch = `ERROR: ${e.message}`; }
      } else {
        item.tests.b2_fetch = 'SKIP (no b2_path)';
      }
      
      // Test 2: RAW QNAP fetch (bez circuit breaker-a!)
      if (row.qnap_path) {
        try {
          const t0 = Date.now();
          const buf = await _qnapFastFetch(row.qnap_path, 5000);
          item.tests.qnap_raw = buf 
            ? `OK (${Math.round(buf.length/1024)} KB, ${Date.now()-t0}ms)` 
            : `NULL (fail nakon ${Date.now()-t0}ms)`;
        } catch(e) { item.tests.qnap_raw = `ERROR: ${e.message}`; }
      } else {
        item.tests.qnap_raw = 'SKIP (no qnap_path)';
      }
      
      // Test 3: fetchImageWithFallback (pravi flow + circuit breaker)
      try {
        const t0 = Date.now();
        const buf = await fetchImageWithFallback(row.qnap_path, row.b2_path);
        item.tests.fetchImageWithFallback = buf 
          ? `OK (${Math.round(buf.length/1024)} KB, ${Date.now()-t0}ms)` 
          : `NULL (fail nakon ${Date.now()-t0}ms)`;
      } catch(e) { item.tests.fetchImageWithFallback = `ERROR: ${e.message}`; }
      
      diag.push(item);
    }
    
    res.json({
      ok: true,
      grad_id: gid,
      total_count: r.rows.length,
      qnap_circuit: {
        open: !!_qnapCircuit.openedAt,
        fail_count: _qnapCircuit.failures.length,
        opened_at: _qnapCircuit.openedAt ? new Date(_qnapCircuit.openedAt).toISOString() : null
      },
      b2_enabled: b2Enabled(),
      qnap_env: {
        webdav_url: process.env.QNAP_WEBDAV_URL ? 'SET' : 'MISSING',
        base_path: process.env.QNAP_BASE_PATH || '/APLIKACIJA',
        user: process.env.QNAP_USER ? 'SET' : 'MISSING',
        password: process.env.QNAP_PASSWORD ? 'SET' : 'MISSING'
      },
      reference_first_10: diag
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.211: Ručno pokretanje migration cron-a (samo direktor)
//   GET /api/b2/migrate-now — pokrene migration batch odmah, vraća rezultate.
//   Korisno za testiranje i kad ne želiš čekati dnevni cron.
app.get('/api/b2/migrate-now', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  if (!b2Enabled()) return res.json({ ok: false, error: 'B2 nije aktiviran' });
  
  if (!global._b2MigrateBatch) {
    return res.json({ 
      ok: false, 
      error: 'Migration cron još nije pokrenut (5 min nakon starta servera). Pokušaj za par minuta.' 
    });
  }
  
  try {
    console.log('[B2 migrate-now] direktor pokrenuo ručnu migraciju');
    const stats = await pool.query(`
      SELECT 
        (SELECT COUNT(*) FROM materijal WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS materijal_pending,
        (SELECT COUNT(*) FROM dnevnik WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS dnevnik_pending,
        (SELECT COUNT(*) FROM uredaji WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS uredaji_pending,
        (SELECT COUNT(*) FROM izmjera WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS izmjera_pending,
        (SELECT COUNT(*) FROM smece WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS smece_pending
    `).catch(() => ({ rows: [{}] }));
    
    // Pokreni migraciju u pozadini
    global._b2MigrateBatch().catch(e => console.error('[B2 migrate-now]', e.message));
    
    res.json({
      ok: true,
      message: 'Migracija pokrenuta u pozadini. Provjeri Railway logove za napredak.',
      pending_before: stats.rows[0]
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

// ⭐ v135.7.220: DISASTER RECOVERY DASHBOARD
//   GET /api/disaster-recovery — pregled stanja sigurnosti podataka
//   Use case: Ivan u bilo kojem trenutku vidi: koliko fajlova ima na B2 (siguran),
//             koliko samo na QNAP-u (potencijalan gubitak), status QNAP/B2.
//   
//   Ne provjerava velike DBskeniranje — samo 5 brzih SUM/COUNT query-ja.
app.get('/api/disaster-recovery', auth, direktor, async (req, res) => {
  try {
    const result = {
      timestamp: new Date().toISOString(),
      qnap: { url: process.env.QNAP_WEBDAV_URL ? 'configured' : 'NOT configured', circuit_open: _qnapCircuitOpen() },
      b2:   { enabled: b2Enabled(), bucket: process.env.B2_BUCKET_NAME || null }
    };
    
    // Provjera live status QNAP (1s timeout — brzo)
    if (process.env.QNAP_WEBDAV_URL) {
      try {
        const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
        const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
        const r = await fetch(`${baseUrl}/`, {
          method: 'PROPFIND',
          headers: { Authorization: `Basic ${auth64}`, Depth: '0' },
          signal: AbortSignal.timeout(3000)
        });
        result.qnap.live_status = r.ok ? 'OK' : `HTTP ${r.status}`;
      } catch(e) {
        result.qnap.live_status = `FAIL: ${e.message}`;
      }
    }
    
    // Provjera live status B2 (auth check)
    if (b2Enabled()) {
      try {
        await b2Authorize();
        result.b2.live_status = 'OK';
      } catch(e) {
        result.b2.live_status = `FAIL: ${e.message}`;
      }
    }
    
    // Stats: koliko slika ima na B2, koliko samo QNAP
    const stats = await pool.query(`
      SELECT 
        (SELECT COUNT(*) FROM materijal WHERE qnap_path IS NOT NULL) AS materijal_total,
        (SELECT COUNT(*) FROM materijal WHERE b2_path IS NOT NULL) AS materijal_na_b2,
        (SELECT COUNT(*) FROM materijal WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS materijal_samo_qnap,
        (SELECT COUNT(*) FROM dnevnik WHERE qnap_path IS NOT NULL) AS dnevnik_total,
        (SELECT COUNT(*) FROM dnevnik WHERE b2_path IS NOT NULL) AS dnevnik_na_b2,
        (SELECT COUNT(*) FROM dnevnik WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS dnevnik_samo_qnap,
        (SELECT COUNT(*) FROM uredaji WHERE qnap_path IS NOT NULL) AS uredaji_total,
        (SELECT COUNT(*) FROM uredaji WHERE b2_path IS NOT NULL) AS uredaji_na_b2,
        (SELECT COUNT(*) FROM uredaji WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS uredaji_samo_qnap,
        (SELECT COUNT(*) FROM izmjera WHERE qnap_path IS NOT NULL) AS izmjera_total,
        (SELECT COUNT(*) FROM izmjera WHERE b2_path IS NOT NULL) AS izmjera_na_b2,
        (SELECT COUNT(*) FROM izmjera WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS izmjera_samo_qnap,
        (SELECT COUNT(*) FROM smece WHERE qnap_path IS NOT NULL) AS smece_total,
        (SELECT COUNT(*) FROM smece WHERE b2_path IS NOT NULL) AS smece_na_b2,
        (SELECT COUNT(*) FROM smece WHERE qnap_path IS NOT NULL AND b2_path IS NULL) AS smece_samo_qnap
    `).catch(() => ({ rows: [{}] }));
    result.slike = stats.rows[0];
    
    // Posljednji backup
    const lastBackup = await pool.query(
      "SELECT created_at, status, filename, size_kb FROM backup_log WHERE status IN ('ok', 'ok_no_b2', 'ok_b2_only', 'ok_no_qnap') ORDER BY created_at DESC LIMIT 1"
    ).catch(() => ({ rows: [] }));
    result.last_backup = lastBackup.rows[0] || null;
    
    // Verdikt — što bi se dogodilo ako QNAP nestane sad
    const samoQnap = (parseInt(result.slike.materijal_samo_qnap) || 0) +
                     (parseInt(result.slike.dnevnik_samo_qnap) || 0) +
                     (parseInt(result.slike.uredaji_samo_qnap) || 0) +
                     (parseInt(result.slike.izmjera_samo_qnap) || 0) +
                     (parseInt(result.slike.smece_samo_qnap) || 0);
    
    if (samoQnap === 0) {
      result.verdikt = '✅ SIGURNO: sve slike su na B2. Ako QNAP nestane, aplikacija nastavi raditi normalno.';
    } else if (samoQnap < 50) {
      result.verdikt = `⚠ ${samoQnap} starih slika je SAMO na QNAP-u. Migration cron radi u pozadini, postupno migrira. Pokreni POST /api/b2/migrate-now za ručno ubrzanje.`;
    } else {
      result.verdikt = `⚠ ${samoQnap} starih slika je SAMO na QNAP-u. Preporuka: pokreni POST /api/b2/migrate-now za ručno migriranje (može potrajati).`;
    }
    
    res.json(result);
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.397: BACKUP VERIFY ENDPOINT (BUG #BAK-04)
//   PROBLEM: backup se kreira svake nedjelje u 23:00, ZIP ide na B2. Ali nikad ne 
//   provjeravamo je li ZIP zapravo korišten. Klasičan disaster recovery scenarij: 
//   firma pravi backup 5 godina, dan-D server crash, otvore backup → corrupted.
//   
//   ROOT CAUSE: trenutni backup-log označava status='ok' ako je upload na B2 vratio 200 OK. 
//   To znači "transfer je prošao" — ne "ZIP je validan, slike unutra, SQL restore-able".
//   
//   FIX: ovaj endpoint:
//     1) Skine najnoviji backup ZIP iz B2 (random sample 1 od zadnjih 10)
//     2) Provjeri SHA256 hash — uspoređuje s onim spremljenim u backup_log
//     3) Otvori ZIP — test da nije corrupted (try-catch unzip)
//     4) Izvuče prvih 3 slike — proba ih otvoriti s sharp (test integriteta)
//     5) Izvuče SQL dump — test sintakse (CREATE TABLE pattern, ne zapravo restore)
//     6) Ako sve OK → UPDATE backup_log SET verified_at = NOW(), qnap_verified = TRUE
//     7) Ako fail → console.error + push notif direktoru
//   
//   COST: 1 B2 download tjedno (~50-200 MB), 30 sek izvršenja. Negligible.
//   
//   USE: ručno za sad (POST /api/backup/verify-latest), kasnije auto-cron utorak 8:00 
//   (nakon nedjeljnog backup-a, pa imamo cijeli ponedjeljak ako fail-a).
// ⭐ v421 BACKUP VERIFY ENHANCEMENT: auto-trigger nakon svakog backup-a.
//   Pokreće isti core verify logic kao /api/backup/verify-latest, ali bez Express req/res.
//   Ako verify fail-a, push direktoru s detaljima — backup-corruption se ne smije tiho propustiti.
async function performAutoBackupVerify() {
  try {
    const recent = await pool.query(`
      SELECT id, created_at, filename, size_kb, sha256, b2_ok, qnap_uploaded, qnap_verified
      FROM backup_log
      WHERE status='ok' AND b2_ok=TRUE
      ORDER BY created_at DESC
      LIMIT 1
    `);
    if (!recent.rows.length) {
      console.warn('[auto-verify] nema backup-a za provjeru');
      return;
    }
    const target = recent.rows[0];
    if (target.qnap_verified) {
      console.log(`[auto-verify] backup #${target.id} već verificiran — preskačem`);
      return;
    }
    if (!b2Enabled()) {
      console.warn('[auto-verify] B2 nije omogućen — skip');
      return;
    }
    
    let failReason = null;
    try {
      const b2Auth = await b2Authorize();
      if (!b2Auth) throw new Error('B2 auth nije dostupan');
      // ⭐ v502.5 (Ivan, 25.05.2026): KRITIČAN BUG FIX — B2 path case-sensitivity
      //   PRIJE: `backup/${target.filename}` (malo slovo "b")
      //   POSLJEDICA: B2 paths su case-sensitive. Upload ide u "Backup/..." (L26581),
      //              ali verify download traži "backup/..." → vraća HTTP 401 (File doesn't exist
      //              odgovor je 401, ne 404, za key-eve s ograničenim prefix-om).
      //   POSLJEDICA²: push notif "🚨 BACKUP VERIFY FAIL: B2 HTTP 401" iako je ZIP zaista na B2.
      //   SAD: koristim "Backup/" (veliko B), identičan path kao upload (L26581) i lista (L28507).
      //
      // ⭐ v502.5 BUG FIX #2 (Ivan, 25.05.2026): URL encoding fix
      //   PRIJE: `encodeURIComponent(b2Path)` → "Backup/file.zip" → "Backup%2Ffile.zip"
      //   POSLJEDICA: B2 traži datoteku s nazivom "Backup/file.zip" cijelim kao filename
      //              (umjesto kao putanju), ne nalazi je → HTTP 401 (ograničeni key prefix).
      //              To se prikazuje kao "🚨 BACKUP VERIFY FAIL: Download/parse fail: B2 HTTP 401"
      //              iako ZIP postoji na B2.
      //   SAD: split('/').map(encodeURIComponent).join('/') — svaki segment se enkodira odvojeno,
      //        slash-evi ostaju kao putanja. Identičan pattern kao u b2Download (L16709).
      const b2Path = `Backup/${target.filename}`;
      const encodedPath = b2Path.split('/').map(encodeURIComponent).join('/');
      const downloadUrl = `${b2Auth.downloadUrl}/file/${process.env.B2_BUCKET_NAME}/${encodedPath}`;
      let resp = await fetch(downloadUrl, {
        headers: { Authorization: b2Auth.authToken },
        signal: AbortSignal.timeout(60000)
      });
      // Ako 401, invalidate cache i retry s fresh tokenom (token expired)
      if (resp.status === 401) {
        console.warn('[auto-verify] B2 download 401 — invalidate cache + retry');
        _b2InvalidateAuth();
        const b2Auth2 = await b2Authorize();
        if (b2Auth2) {
          resp = await fetch(downloadUrl, {
            headers: { Authorization: b2Auth2.authToken },
            signal: AbortSignal.timeout(60000)
          });
        }
      }
      if (!resp.ok) throw new Error(`B2 HTTP ${resp.status}`);
      const zipBuffer = Buffer.from(await resp.arrayBuffer());
      
      // SHA256 check
      if (target.sha256) {
        const computedHash = crypto.createHash('sha256').update(zipBuffer).digest('hex');
        if (computedHash !== target.sha256) {
          failReason = `SHA256 mismatch: očekivano ${target.sha256.substring(0, 16)}..., dobiveno ${computedHash.substring(0, 16)}...`;
        }
      }
      
      // ZIP open check
      if (!failReason) {
        const JSZip = require('jszip');
        const zip = await JSZip.loadAsync(zipBuffer);
        const fileCount = Object.keys(zip.files).length;
        if (fileCount < 5) failReason = `ZIP ima samo ${fileCount} fajlova (premalo)`;
      }
    } catch (e) {
      failReason = `Download/parse fail: ${e.message}`;
    }
    
    if (failReason) {
      console.error(`[auto-verify] BACKUP #${target.id} FAIL: ${failReason}`);
      // ⭐ v502.5 (Ivan, 25.05.2026): Smanji severity ako QNAP postoji
      //   Auto-verify download dolazi s B2. Ako QNAP backup uploaded=TRUE, onda postoji 
      //   off-site backup (QNAP NAS lokalno) i verify fail na B2 NIJE disaster:
      //     - severity 'warning' umjesto 'critical' (ne kvari godišnji izvještaj)
      //     - push notif s blažim tone-om ("⚠️ B2 verify fail" umjesto "🚨 BACKUP VERIFY FAIL")
      //   Disaster (severity='critical') je samo ako i QNAP i B2 fail-aju.
      const qnapPresent = target.qnap_uploaded === true;
      const severity = qnapPresent ? 'warning' : 'critical';
      const pushTitle = qnapPresent ? '⚠️ B2 verify fail' : '🚨 BACKUP VERIFY FAIL';
      const pushBody = qnapPresent 
        ? `Backup #${target.id}: B2 verify fail, ali ZIP postoji na QNAP-u`
        : `Backup #${target.id} (${target.filename}): ${failReason.substring(0, 100)}`;
      
      try {
        await pool.query(
          `INSERT INTO audit_log(action, target_type, target_id, details, severity)
           VALUES ('backup_auto_verify_fail', 'backup', $1, $2, $3)`,
          [target.id, JSON.stringify({ filename: target.filename, reason: failReason, qnap_present: qnapPresent }), severity]
        );
      } catch (_) {}
      // Push direktoru
      try {
        const direktori = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true");
        for (const d of direktori.rows) {
          sendPushToUser(d.id, pushTitle, pushBody, '/?tab=backup').catch(_ => {});
        }
      } catch (_) {}
    } else {
      await pool.query(
        `UPDATE backup_log SET qnap_verified=TRUE, verified_at=NOW() WHERE id=$1`,
        [target.id]
      );
      console.log(`[auto-verify] ✅ backup #${target.id} verificiran`);
    }
  } catch (e) {
    console.error('[auto-verify] unexpected fail:', e.message);
  }
}

app.post('/api/backup/verify-latest', auth, direktor, async (req, res) => {
  const startMs = Date.now();
  const stats = { tests_passed: 0, tests_failed: 0, details: [] };
  
  try {
    // 1. Nađi najnoviji backup koji JE upload-an na B2 i još nije verificiran
    // ⭐ v502.17 (Ivan, 26.05.2026): backup status enum unified — uključi sve 4 OK varijante.
    //   PRIJE: samo status='ok' → backupi gdje QNAP fail-ao a B2 uspio (ok_b2_only/ok_no_qnap) 
    //          ne bi se verificirali nikad. Bug u edge slučaju (npr. QNAP downtime 2 tjedna).
    const recent = await pool.query(`
      SELECT id, created_at, filename, size_kb, sha256, b2_ok, qnap_uploaded, qnap_verified
      FROM backup_log
      WHERE status IN ('ok','ok_no_b2','ok_b2_only','ok_no_qnap') AND (b2_ok=TRUE OR qnap_uploaded=TRUE)
      ORDER BY created_at DESC
      LIMIT 10
    `);
    
    if (!recent.rows.length) {
      return res.status(404).json({ error: 'Nema dostupnih backup-a za verifikaciju' });
    }
    
    // Random sample iz top 10 (manje koreliranih s recent failure-ima)
    const target = recent.rows[Math.floor(Math.random() * Math.min(3, recent.rows.length))];
    stats.target_backup = {
      id: target.id,
      filename: target.filename,
      created_at: target.created_at,
      size_kb: target.size_kb,
      expected_sha256: target.sha256
    };
    
    // 2. Pokušaj download s B2
    if (!b2Enabled() || !target.b2_ok) {
      stats.details.push({ test: 'b2_download', status: 'skip', razlog: 'B2 nije omogućen ili backup nije na B2' });
    } else {
      try {
        const auth = await b2Authorize();
        if (!auth) throw new Error('b2Authorize vratio null');
        
        // ⭐ v502.5 (Ivan, 25.05.2026): 3 BUG-a FIX:
        //   #1: B2 path mora biti "Backup/" (veliko B) — case-sensitive, identičan kao upload (L26581)
        //   #2: Authorization header mora biti `auth.authToken` — cache property je `authToken`,
        //       ne `authorizationToken`. Pogrešno: `auth.authorizationToken` (undefined) → HTTP 401.
        //   #3: URL encoding — encodeURIComponent na cijelom path-u pretvara "/" u "%2F", 
        //       što B2 ne razumije (smatra cijelim kao filename). Mora biti per-segment encoding.
        //       Identičan pattern kao b2Download (L16709) i upload diag (L27692).
        const b2Path = `Backup/${target.filename}`;
        const encodedPath = b2Path.split('/').map(encodeURIComponent).join('/');
        const downloadUrl = `${auth.downloadUrl}/file/${process.env.B2_BUCKET_NAME}/${encodedPath}`;
        
        let resp = await fetch(downloadUrl, {
          headers: { Authorization: auth.authToken },
          signal: AbortSignal.timeout(60000)  // 60s timeout
        });
        // Retry s fresh token ako 401 (token expired)
        if (resp.status === 401) {
          console.warn('[verify-latest] B2 download 401 — invalidate cache + retry');
          _b2InvalidateAuth();
          const auth2 = await b2Authorize();
          if (auth2) {
            resp = await fetch(downloadUrl, {
              headers: { Authorization: auth2.authToken },
              signal: AbortSignal.timeout(60000)
            });
          }
        }
        
        if (!resp.ok) throw new Error(`B2 HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
        
        const zipBuffer = Buffer.from(await resp.arrayBuffer());
        stats.zip_downloaded_kb = Math.round(zipBuffer.length / 1024);
        stats.details.push({ test: 'b2_download', status: 'ok', size_kb: stats.zip_downloaded_kb });
        stats.tests_passed++;
        
        // 3. SHA256 verifikacija
        if (target.sha256) {
          const computedHash = crypto.createHash('sha256').update(zipBuffer).digest('hex');
          if (computedHash === target.sha256) {
            stats.details.push({ test: 'sha256_match', status: 'ok' });
            stats.tests_passed++;
          } else {
            stats.details.push({ 
              test: 'sha256_match', status: 'FAIL',
              expected: target.sha256.substring(0, 16) + '...',
              computed: computedHash.substring(0, 16) + '...'
            });
            stats.tests_failed++;
          }
        } else {
          stats.details.push({ test: 'sha256_match', status: 'skip', razlog: 'Hash nije spremljen za ovaj backup' });
        }
        
        // 4. ZIP integrity test
        try {
          const JSZip = require('jszip');
          const zip = await JSZip.loadAsync(zipBuffer);
          const fileCount = Object.keys(zip.files).length;
          stats.details.push({ test: 'zip_open', status: 'ok', files: fileCount });
          stats.tests_passed++;
          
          // 5. SQL dump validity test (površan — samo CREATE TABLE pattern)
          const sqlEntry = Object.keys(zip.files).find(n => n.endsWith('.sql') || n.includes('backup'));
          if (sqlEntry) {
            const sqlContent = await zip.files[sqlEntry].async('string');
            const hasCreate = /CREATE TABLE|INSERT INTO/i.test(sqlContent);
            const hasRadnici = /radnici|gradilista|sihterica/i.test(sqlContent);
            if (hasCreate && hasRadnici) {
              stats.details.push({ test: 'sql_validity', status: 'ok', sql_size_kb: Math.round(sqlContent.length / 1024) });
              stats.tests_passed++;
            } else {
              stats.details.push({ test: 'sql_validity', status: 'FAIL', razlog: 'SQL dump ne sadrži očekivane pattern-e' });
              stats.tests_failed++;
            }
          }
          
          // 6. Random sample slika test
          const imageEntries = Object.keys(zip.files).filter(n => /\.(jpg|jpeg|png|webp)$/i.test(n)).slice(0, 3);
          let imagesOk = 0;
          for (const imgPath of imageEntries) {
            try {
              const imgBuffer = await zip.files[imgPath].async('nodebuffer');
              // Sharp metadata read = brzi integrity test
              const sharp = require('sharp');
              const meta = await sharp(imgBuffer).metadata();
              if (meta.width && meta.height) imagesOk++;
            } catch (eImg) {
              stats.details.push({ test: 'image_sample', file: imgPath, status: 'FAIL', error: eImg.message });
              stats.tests_failed++;
            }
          }
          if (imageEntries.length > 0) {
            stats.details.push({ 
              test: 'image_sample', status: imagesOk === imageEntries.length ? 'ok' : 'partial',
              tested: imageEntries.length, ok: imagesOk
            });
            if (imagesOk === imageEntries.length) stats.tests_passed++;
            else stats.tests_failed++;
          }
          
        } catch (eZip) {
          stats.details.push({ test: 'zip_open', status: 'FAIL', error: eZip.message });
          stats.tests_failed++;
        }
        
      } catch (eDl) {
        stats.details.push({ test: 'b2_download', status: 'FAIL', error: eDl.message });
        stats.tests_failed++;
      }
    }
    
    // 7. Update verified_at u DB ako sve prošlo
    const allPassed = stats.tests_failed === 0 && stats.tests_passed >= 3;
    if (allPassed) {
      await pool.query(
        `UPDATE backup_log SET qnap_verified=TRUE, verified_at=NOW() WHERE id=$1`,
        [target.id]
      );
      stats.verdikt = `✅ Backup #${target.id} verificiran — ${stats.tests_passed} testova prošlo`;
      
      // ⭐ v135.7.397: AUDIT — uspješna verifikacija je info severity
      auditLog(req, {
        action: 'backup_verify_ok',
        target_type: 'backup',
        target_id: target.id,
        details: { filename: target.filename, tests_passed: stats.tests_passed },
        severity: 'info'
      });
    } else {
      stats.verdikt = `⚠ Backup #${target.id} ima problem — ${stats.tests_failed} failed, ${stats.tests_passed} passed. Provjeri detalje.`;
      console.error('[BACKUP VERIFY] FAIL za backup #' + target.id + ':', JSON.stringify(stats.details));
      
      // ⭐ v135.7.397: AUDIT — fail-ana verifikacija je WARNING (potencijalan disaster recovery problem)
      auditLog(req, {
        action: 'backup_verify_fail',
        target_type: 'backup',
        target_id: target.id,
        details: { filename: target.filename, tests_failed: stats.tests_failed, tests_passed: stats.tests_passed, details: stats.details },
        severity: 'warning'
      });
      
      // Push notif direktoru ako fail
      try {
        const dir = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1");
        if (dir.rows.length && typeof sendPushToUser === 'function') {
          await sendPushToUser(
            dir.rows[0].id,
            '⚠ Backup verifikacija fail-ala',
            `Backup #${target.id} (${target.filename}) ne prolazi testove. Otvori app za detalje.`,
            '/#s-backup'
          );
        }
      } catch(ePush) { console.warn('[backup verify] push fail:', ePush.message); }
    }
    
    stats.duration_ms = Date.now() - startMs;
    res.json(stats);
    
  } catch(eAll) {
    console.error('[BACKUP VERIFY] kritična greška:', eAll);
    res.status(500).json({ error: eAll.message, stats });
  }
});

