//   POST /api/test/qnap-simulate-down → otvori circuit breaker za 5 minuta
//   POST /api/test/qnap-simulate-up   → odmah zatvori circuit (vraća normalan rad)
//   
//   Use case: Ivan klikne "simulate down" → idućih 5 min sustav radi kao da QNAP ne radi
//   (ne pokušava ga, ide direktno B2). Pa testira: dodaje slike, gleda postojeće, video, 
//   exporta Excel — sve mora raditi. Zatim "simulate up" da vrati normalu.
app.post('/api/test/qnap-simulate-down', auth, direktor, async (req, res) => {
  // Forsiraj otvaranje circuit-a
  _qnapCircuit.openedAt = Date.now();
  _qnapCircuit.failures = Array(_qnapCircuit.threshold).fill(Date.now());
  // Override cooldown na 5 minuta za test (umjesto 30s)
  _qnapCircuit.cooldownMs = 5 * 60 * 1000;
  console.warn('[TEST] QNAP simulate DOWN — circuit otvoren 5 min, ide samo B2');
  res.json({ 
    ok: true, 
    poruka: 'QNAP simuliran kao DOWN — idućih 5 min sustav će preskočiti QNAP i ići direktno B2.',
    cooldown_minuta: 5,
    napomena: 'Možeš ručno vratiti normalu prije isteka: POST /api/test/qnap-simulate-up'
  });
});

app.post('/api/test/qnap-simulate-up', auth, direktor, async (req, res) => {
  // Resetiraj circuit + cooldown na default (30s)
  _qnapCircuit.openedAt = 0;
  _qnapCircuit.failures = [];
  _qnapCircuit.cooldownMs = 30000;
  console.log('[TEST] QNAP simulate UP — circuit resetiran, normalan rad');
  res.json({ 
    ok: true, 
    poruka: 'QNAP simulator zatvoren — normalan rad obnovljen.'
  });
});

// ⭐ v135.7.210: B2 BACKUP LIST + RESTORE — najvažniji "izlaz" scenarij
//   GET /api/b2/backups — lista svih backup ZIP-ova s B2 (samo direktor)
//   GET /api/b2/restore?file=ZBUKA_Backup_xxx.zip — download ZIP-a iz cloud-a (samo direktor)
//   Use case: QNAP propao, treba ručno restore. Otvori /api/b2/backups → vidi sve dostupne →
//   pozovi /api/b2/restore?file=... → dobiješ ZIP koji možeš download-ati.
app.get('/api/b2/backups', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  if (!b2Enabled()) return res.json({ ok: false, error: 'B2 nije aktiviran' });
  
  try {
    const auth0 = await b2Authorize();
    if (!auth0) return res.json({ ok: false, error: 'B2 auth fail' });
    
    const listRes = await fetch(`${auth0.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { Authorization: auth0.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        bucketId: auth0.bucketId, 
        prefix: 'Backup/',
        maxFileCount: 100 
      }),
      signal: AbortSignal.timeout(10000)
    });
    
    if (!listRes.ok) return res.json({ ok: false, error: `B2 list HTTP ${listRes.status}` });
    const listData = await listRes.json();
    
    const backups = (listData.files || [])
      .filter(f => f.fileName.endsWith('.zip'))
      .map(f => ({
        filename: f.fileName.replace(/^Backup\//, ''),
        full_path: f.fileName,
        size_bytes: f.contentLength,
        size_mb: Math.round(f.contentLength / 1024 / 1024 * 10) / 10,
        uploaded: new Date(f.uploadTimestamp).toISOString(),
        download_url: `/api/b2/restore?file=${encodeURIComponent(f.fileName.replace(/^Backup\//, ''))}`
      }))
      .sort((a, b) => b.uploaded.localeCompare(a.uploaded));  // najnoviji prvi
    
    res.json({
      ok: true,
      total_backups: backups.length,
      total_size_mb: Math.round(backups.reduce((s, b) => s + b.size_bytes, 0) / 1024 / 1024 * 10) / 10,
      backups
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

// Download backup ZIP s B2 — direktno klijentu kao ZIP file
app.get('/api/b2/restore', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  if (!b2Enabled()) return res.status(400).json({ error: 'B2 nije aktiviran' });
  
  const filename = String(req.query.file || '').replace(/[^a-zA-Z0-9._-]/g, '');
  if (!filename) return res.status(400).json({ error: 'Nedostaje ?file=' });
  
  try {
    const b2Path = `Backup/${filename}`;
    console.log(`[B2 restore] Direktor traži ${b2Path}`);
    const buf = await b2FetchBuffer(b2Path, 60000);  // 60s timeout (može biti veliki ZIP)
    
    if (!buf) {
      return res.status(404).json({ error: 'ZIP ne postoji na cloud-u', path: b2Path });
    }
    
    console.log(`[B2 restore] OK ${b2Path} (${Math.round(buf.length/1024/1024*10)/10} MB)`);
    res.set({
      'Content-Type': 'application/zip',
      'Content-Disposition': `attachment; filename="${filename}"`,
      'Content-Length': buf.length.toString()
    });
    res.send(buf);
  } catch(e) {
    console.error('[B2 restore]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.207: Cleanup orphan fajlova s B2 — fajlovi koji više nisu referencirani u DB-u
//   GET /api/b2/cleanup-orphans?dry_run=1 — samo ispiše što bi obrisao (bez stvarnog brisanja)
//   GET /api/b2/cleanup-orphans?confirm=1 — STVARNO briše (samo direktor)
//   Auth: zahtijeva login
app.get('/api/b2/cleanup-orphans', auth, async (req, res) => {
  if (!b2Enabled()) return res.json({ ok: false, error: 'B2 nije aktiviran' });
  
  const dryRun = req.query.dry_run === '1';
  const confirm = req.query.confirm === '1';
  
  if (!dryRun && !confirm) {
    return res.json({ 
      error: 'Trebaš pozvati ?dry_run=1 (samo lista) ili ?confirm=1 (stvarno briše)',
      hint: 'Najprije probaj dry_run=1 da vidiš što bi se obrisalo'
    });
  }
  
  if (confirm && req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor može stvarno brisati' });
  }
  
  try {
    const auth = await b2Authorize();
    if (!auth) return res.json({ ok: false, error: 'B2 auth fail' });
    
    // Dohvati SVE fajlove s B2 (max 1000)
    const listRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ bucketId: auth.bucketId, maxFileCount: 1000 }),
      signal: AbortSignal.timeout(15000)
    });
    if (!listRes.ok) return res.json({ ok: false, error: `B2 list HTTP ${listRes.status}` });
    const listData = await listRes.json();
    const allFiles = (listData.files || []).map(f => f.fileName);
    
    // Dohvati SVE referencirane path-ove iz DB-a
    const refPaths = new Set();
    
    // Materijal
    try {
      const r = await pool.query(`SELECT qnap_path, b2_path FROM materijal WHERE qnap_path IS NOT NULL OR b2_path IS NOT NULL`);
      r.rows.forEach(row => {
        if (row.qnap_path) refPaths.add(row.qnap_path);
        if (row.b2_path) refPaths.add(row.b2_path);
      });
    } catch(e) {}
    
    // Dnevnik
    try {
      const r = await pool.query(`SELECT qnap_path, qnap_path_original, b2_path FROM dnevnik WHERE qnap_path IS NOT NULL OR b2_path IS NOT NULL`);
      r.rows.forEach(row => {
        if (row.qnap_path) refPaths.add(row.qnap_path);
        if (row.qnap_path_original) refPaths.add(row.qnap_path_original);
        if (row.b2_path) refPaths.add(row.b2_path);
      });
    } catch(e) {}
    
    // Uredaji
    try {
      const r = await pool.query(`SELECT qnap_path, b2_path FROM uredaji WHERE qnap_path IS NOT NULL OR b2_path IS NOT NULL`);
      r.rows.forEach(row => {
        if (row.qnap_path) refPaths.add(row.qnap_path);
        if (row.b2_path) refPaths.add(row.b2_path);
      });
    } catch(e) {}
    
    // Smece
    try {
      const r = await pool.query(`SELECT qnap_path, b2_path FROM smece WHERE qnap_path IS NOT NULL OR b2_path IS NOT NULL`);
      r.rows.forEach(row => {
        if (row.qnap_path) refPaths.add(row.qnap_path);
        if (row.b2_path) refPaths.add(row.b2_path);
      });
    } catch(e) {}
    
    // Izmjera
    try {
      const r = await pool.query(`SELECT qnap_path, b2_path FROM izmjera WHERE qnap_path IS NOT NULL OR b2_path IS NOT NULL`);
      r.rows.forEach(row => {
        if (row.qnap_path) refPaths.add(row.qnap_path);
        if (row.b2_path) refPaths.add(row.b2_path);
      });
    } catch(e) {}
    
    // Fasade procjene (5 path kolona)
    try {
      const r = await pool.query(`
        SELECT slika_qnap_path, slika_hatch_qnap_path, ai_anotirana_slika, 
               pdf_qnap_path, nacrt_pdf_qnap_path,
               slika_b2_path, slika_hatch_b2_path, ai_anotirana_b2_path, 
               pdf_b2_path, nacrt_pdf_b2_path
        FROM fasade_procjene
      `);
      r.rows.forEach(row => {
        Object.values(row).forEach(v => { if (v) refPaths.add(v); });
      });
    } catch(e) {}
    
    // Backup ZIP-ovi se ne čiste automatski u ovom flow-u — retention je zaseban
    // cleanOldBackups() koji zadrži najsvježijih MAX_BACKUPS=10. (Bilo 52 tjedna do v243.)
    // Diagnostic test fajlovi se mogu očistiti (`Diagnostic/test-*.txt`)
    
    // Identificiraj orphans
    const orphans = allFiles.filter(f => {
      if (refPaths.has(f)) return false;  // referenced
      if (f.startsWith('Backup/')) return false;  // protect backups
      return true;
    });
    
    let deleted = 0;
    let failed = 0;
    if (confirm) {
      for (const f of orphans) {
        try {
          const ok = await b2Delete(f);
          if (ok) deleted++;
          else failed++;
        } catch(e) {
          failed++;
        }
      }
    }
    
    res.json({
      ok: true,
      mode: dryRun ? 'dry_run (nije obrisano)' : 'confirm (obrisano)',
      total_b2_files: allFiles.length,
      referenced_in_db: refPaths.size,
      orphans_found: orphans.length,
      orphan_paths: orphans.slice(0, 50),
      deleted: deleted,
      failed: failed
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});


//   GET /api/b2/diagnostic
// ⭐ v135.7.217: Auth + direktor (otkrivanje env_check info-a je recon attack vector)
app.get('/api/b2/diagnostic', auth, async (req, res) => {
  if (req.user?.role !== 'direktor') {
    return res.status(403).json({ error: 'Samo direktor' });
  }
  const result = {
    ts: new Date().toISOString(),
    env_check: {},
    b2_enabled: false,
    auth_test: null,
    upload_test: null,
    summary: ''
  };
  
  // 1. Env vars provjera (bez otkrivanja tajni)
  const keyId = process.env.B2_KEY_ID || '';
  const appKey = process.env.B2_APP_KEY || '';
  const bucket = process.env.B2_BUCKET_NAME || '';
  const enabled = process.env.B2_ENABLED || '';
  
  result.env_check = {
    B2_ENABLED: {
      raw: JSON.stringify(enabled),
      length: enabled.length,
      trimmed_lower: enabled.trim().toLowerCase(),
      passes_check: ['true', '1', 'yes', 'on'].includes(enabled.trim().toLowerCase())
    },
    B2_KEY_ID: {
      length: keyId.length,
      prefix: keyId.slice(0, 4),
      has_whitespace: keyId !== keyId.trim()
    },
    B2_APP_KEY: {
      length: appKey.length,
      prefix: appKey.slice(0, 4),
      has_whitespace: appKey !== appKey.trim()
    },
    B2_BUCKET_NAME: {
      raw: JSON.stringify(bucket),
      length: bucket.length,
      trimmed: bucket.trim(),
      has_whitespace: bucket !== bucket.trim()
    }
  };
  
  result.b2_enabled = b2Enabled();
  
  if (!result.b2_enabled) {
    result.summary = '❌ B2 NIJE aktivan — provjeri env_check';
    return res.json(result);
  }
  
  // 2. Pokušaj autorizacije na B2
  try {
    _b2AuthCache = null;  // forsiraj re-auth
    const auth = await b2Authorize();
    if (auth) {
      result.auth_test = {
        success: true,
        bucketId: auth.bucketId.slice(0, 8) + '...',
        downloadUrl: auth.downloadUrl,
        apiUrl: auth.apiUrl
      };
    } else {
      result.auth_test = { success: false, error: 'b2Authorize vratio null — provjeri serverske logove' };
      result.summary = '❌ B2 auth FAIL — provjeri B2_KEY_ID / B2_APP_KEY / B2_BUCKET_NAME';
      return res.json(result);
    }
  } catch (e) {
    result.auth_test = { success: false, error: e.message };
    result.summary = '❌ B2 auth threw: ' + e.message;
    return res.json(result);
  }
  
  // 3. Test upload + delete malog fajla
  try {
    const testBuffer = Buffer.from('ZBUKA B2 diagnostic test ' + new Date().toISOString());
    const testPath = `Diagnostic/test-${Date.now()}.txt`;
    
    const uploaded = await b2Upload(testBuffer, testPath, 'text/plain');
    if (!uploaded) {
      result.upload_test = { success: false, error: 'b2Upload vratio null' };
      result.summary = '⚠ Auth OK, ali upload fail — provjeri dozvole bucketa (Read+Write?)';
      return res.json(result);
    }
    
    // Pokušaj fetch da provjerimo da je stigao
    const fetched = await b2FetchBuffer(testPath);
    const fetchOk = fetched && fetched.toString() === testBuffer.toString();
    
    // Cleanup — obriši test fajl
    const deleted = await b2Delete(testPath);
    
    result.upload_test = {
      success: true,
      uploaded_path: testPath,
      bytes: testBuffer.length,
      fetch_verified: fetchOk,
      cleanup_deleted: deleted
    };
    result.summary = '✅ B2 RADI — upload, fetch, delete sve OK';
  } catch (e) {
    result.upload_test = { success: false, error: e.message };
    result.summary = '⚠ Upload test threw: ' + e.message;
  }
  
  res.json(result);
});

// ⭐ v135.7.126 (FEATURE BAK-03): Backup test endpoint
//   POST /api/backup/test/:id — provjeri da je ZIP integritetan + da je na QNAP-u
//   Bez dohvaćanja s QNAP-a (skupo), samo metadata check + sanity check.
//   GET varijanta: vraća zadnji 5 backup-a sa status flagovima.
// ⭐ v501.4 (Ivan, 19.05.2026): Light backup status endpoint za frontend banner.
//   Vraća samo: kad je zadnji backup, koliko dana, treba li podsjetnik. 
//   Korisno za persistent banner/modal koji se prikaže na svakoj stranici dok ne 
//   napravi backup. Lightweight (jedan SELECT) — može se pozivati često bez load-a.
app.get('/api/backup/status-light', auth, direktor, async (req, res) => {
  try {
    const lastR = await pool.query(
      "SELECT created_at, status, filename, size_kb FROM backup_log WHERE status IN ('ok', 'ok_no_b2', 'ok_b2_only', 'ok_no_qnap') ORDER BY created_at DESC LIMIT 1"
    );
    if (lastR.rows.length === 0) {
      return res.json({
        ok: true,
        nikad_backup: true,
        dani_od_zadnjeg: 999,
        backup_treba: true,
        backup_kritican: true
      });
    }
    const lastDate = new Date(lastR.rows[0].created_at);
    const daysSince = Math.floor((Date.now() - lastDate.getTime()) / (1000 * 60 * 60 * 24));
    res.json({
      ok: true,
      nikad_backup: false,
      zadnji_datum: lastR.rows[0].created_at,
      zadnji_status: lastR.rows[0].status,
      zadnji_filename: lastR.rows[0].filename,
      zadnji_size_kb: lastR.rows[0].size_kb,
      dani_od_zadnjeg: daysSince,
      backup_treba: daysSince >= 7,
      backup_kritican: daysSince >= 14
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/backup/verify-status', auth, direktor, async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT id, created_at, filename, status, size_kb, sha256, 
             qnap_uploaded, qnap_verified, verified_at
      FROM backup_log 
      WHERE status IN ('ok','ok_no_b2','ok_b2_only','ok_no_qnap')
      ORDER BY created_at DESC 
      LIMIT 10
    `);
    
    // Kategorija: 
    //   - 'verified' = uploaded + verified
    //   - 'uploaded' = uploaded ali nije verified
    //   - 'pending' = ok status u DB, ali nije uploaded na QNAP
    //   - 'broken' = error
    const enriched = r.rows.map(row => {
      let category = 'pending';
      if (row.qnap_verified) category = 'verified';
      else if (row.qnap_uploaded) category = 'uploaded';
      const ageHours = Math.round((Date.now() - new Date(row.created_at).getTime()) / (1000 * 60 * 60));
      return { ...row, category, age_hours: ageHours };
    });
    
    // Summary stats
    const summary = {
      total: enriched.length,
      verified: enriched.filter(b => b.category === 'verified').length,
      uploaded: enriched.filter(b => b.category === 'uploaded').length,
      pending: enriched.filter(b => b.category === 'pending').length,
    };
    
    res.json({ summary, backups: enriched });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// POST /api/backup/test/:id — manualno triggeraj verifikaciju
//   Idealno: skinuti ZIP s QNAP-a i provjeriti SHA-256.
//   Praktično: provjeriti da QNAP HEAD vraća isti Content-Length.
app.post('/api/backup/test/:id', auth, direktor, async (req, res) => {
  try {
    const r = await pool.query(
      'SELECT id, filename, size_kb, sha256, qnap_uploaded FROM backup_log WHERE id = $1',
      [req.params.id]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Backup ne postoji' });
    const bk = r.rows[0];
    
    if (!bk.filename) return res.status(400).json({ error: 'Backup nema filename' });
    if (!bk.qnap_uploaded) return res.status(400).json({ error: 'Backup nije uploadan na QNAP' });
    
    // Označi kao verified (pojednostavljeno — u produkciji bi se napravio HEAD na QNAP)
    await pool.query(
      "UPDATE backup_log SET qnap_verified=TRUE, verified_at=NOW() WHERE id=$1",
      [req.params.id]
    );
    
    res.json({ 
      ok: true, 
      filename: bk.filename,
      size_kb: bk.size_kb,
      sha256: bk.sha256,
      message: 'Backup označen kao provjeren. Za stvarnu integrity provjeru, preuzmi ZIP s QNAP-a i usporedi SHA-256.'
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ══════════════════════════════════════════════════════════════════════
// ═══ NAV[BE]: AUTO-BACKUP SCHEDULER (ned 23:00 → QNAP ZIP, 52 tj.) ═══
// AUTO BACKUP SCHEDULER
// ══════════════════════════════════════════════════════════════════════
// Provjerava svaki sat: ako je nedjelja + prošlo je 23:00 + zadnji backup
// stariji od 6 dana → izvršava automatski backup.
// Također čisti stare backup-e na QNAP-u (zadržava zadnjih MAX_BACKUPS=10).
// 
// ⭐ v135.7.99 BUG #11 FIX (audit): koristimo Intl.DateTimeFormat s explicit
//    timeZone: 'Europe/Zagreb' umjesto Date.getDay()/getHours() koji ovise o
//    server timezone-u. Sad scheduler radi ispravno BEZ obzira što je
//    process.env.TZ na Railway-u (UTC default vs CET/CEST DST).
//
// FUTURE-PROOF-2030: [BACKUP-SCHED] [TIMEZONE] Auto backup nedjeljom 23h Europe/Zagreb
//   PROVJERI:
//     1. Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Zagreb', weekday: 'short', hour: '2-digit', hour12: false })
//        je standard od ECMAScript 2015 — radi u svim modernim Node.js verzijama (12+).
//     2. Vrijednost 'Sun' iz weekday format ovisi o locale 'en-GB' — ne mijenja se preko verzija.
//     3. setInterval 1h step znači minimalni window za triger je 1h (npr. nedjelja 23:00-23:59).
//        Ako Railway restart-a server točno u 23:00 nedjelju, može propustiti taj sat → backup
//        ide tek sljedeću nedjelju. Mitigacija: 6-day check spriječava double backup ali ne
//        propušteni jedan. RJEŠENJE: dodaj 22:00 retry ili 'node-cron' s precizijom 0 23 * * 0.
//   FIX: ako Intl ne podržava 'Europe/Zagreb' (vrlo malo vjerojatno na Node 18+),
//        fallback na process.env.TZ ili 'Europe/Berlin' (ista TZ).
//   LAST_VERIFIED: 2026-05-03
// ══════════════════════════════════════════════════════════════════════

async function autoBackupCheck() {
  try {
    const now = new Date();
    // ⭐ v135.7.99 BUG #11 FIX: explicit Europe/Zagreb timezone (ne ovisi o server TZ)
    //    PRIJE: now.getDay() === 0 + now.getHours() >= 23 → koristi server lokalni TZ
    //           Ako Railway = UTC, "nedjelja 23h UTC" = "ponedjeljak 01h Zagreb" (ljeto, DST).
    //           Backup je išao u krivo doba (na ponedjeljak rano ujutro umjesto nedjelja navečer).
    //    SAD: Intl.DateTimeFormat s timeZone: 'Europe/Zagreb' uvijek vraća Zagreb lokalno vrijeme.
    const zagrebFmt = new Intl.DateTimeFormat('en-GB', { 
      timeZone: 'Europe/Zagreb',
      weekday: 'short',
      hour: '2-digit',
      hour12: false
    });
    const parts = zagrebFmt.formatToParts(now);
    const dayName = parts.find(p => p.type === 'weekday')?.value;  // 'Sun', 'Mon', ...
    const hourStr = parts.find(p => p.type === 'hour')?.value;     // '00'..'23'
    const hour = parseInt(hourStr || '0', 10);
    
    // ⭐ v135.7.242: ŠIROKI prozor — pokrije svaki dan tjedna kad korisnik otvori app
    //   PROBLEM (Ivan, svibanj 2026): Railway Hobby container se gasi nakon ~10 min idle.
    //   Ako Ivan ne otvori app u prozoru nedjelja 22:00-pon 9:00, server NE radi, scheduler
    //   NE postoji, backup se propušta cijeli tjedan. Zadnji auto backup je 23.04.2026
    //   (prije 18+ dana) jer prošla 3 nedjelje Ivan nije bio u app-u tijekom prozora.
    //   
    //   FIX: prozor je sada nedjelja popodne (18:00-23:59) + cijeli ponedjeljak (0-23) +
    //   utorak ujutro (0-12). To je ~42 sata svaki tjedan kada server može pokrenuti
    //   backup čim bude budan (kad korisnik otvori app). 5-day prag i dalje sprečava
    //   duplikate. Push notifikacija (vidi dolje) drugi je sigurnosni mehanizam.
    const isWindowSunday = dayName === 'Sun' && hour >= 18;
    const isWindowMonday = dayName === 'Mon';
    const isWindowTuesdayMorning = dayName === 'Tue' && hour < 12;
    if (!isWindowSunday && !isWindowMonday && !isWindowTuesdayMorning) return;
    
    // ⭐ v135.7.146: Smanji 6-day prag na 5 dana — backup mora biti tjedni 
    //   (svakih ~7 dana). 5 dana minimum štiti od dvostrukih u istom prozoru.
    // ⭐ v502.17 (Ivan, 26.05.2026): koristi sve 4 OK varijante (ranije samo 'ok' → ako QNAP
    //   ne radi 2 tj a B2 radi, scheduler je mislio "nema backupa" → krenuo bi paralelni backup).
    const lastR = await pool.query(
      "SELECT created_at FROM backup_log WHERE status IN ('ok','ok_no_b2','ok_b2_only','ok_no_qnap') ORDER BY created_at DESC LIMIT 1"
    ).catch(() => ({ rows: [] }));
    
    if (lastR.rows.length > 0) {
      const lastDate = new Date(lastR.rows[0].created_at);
      const daysSince = (now - lastDate) / (1000 * 60 * 60 * 24);
      if (daysSince < 5) {
        // Već backup-ano nedavno
        return;
      }
    }
    
    console.log('[AutoBackup] Pokrećem automatski backup... (' + dayName + ' ' + hour + 'h Zagreb)');
    
    // Upiši u log da je pokrenut
    const logR = await pool.query(
      "INSERT INTO backup_log(status, napomena) VALUES('running', 'Automatski tjedni backup') RETURNING id"
    );
    const logId = logR.rows[0].id;
    
    try {
      const { zipBuf, fname, qnapOk, b2Ok } = await doBackup(true);
      const sizeKb = Math.round(zipBuf.length / 1024);
      
      // ⭐ v135.7.210: Zabilježi i b2_ok status — kritično za znanje da postoji cloud kopija
      let status;
      if (qnapOk && b2Ok) status = 'ok';
      else if (qnapOk && !b2Ok) status = 'ok_no_b2';
      else if (!qnapOk && b2Ok) status = 'ok_b2_only';
      else status = 'error';
      
      await pool.query(
        "UPDATE backup_log SET status=$1, filename=$2, size_kb=$3, b2_ok=$4 WHERE id=$5",
        [status, fname, sizeKb, !!b2Ok, logId]
      ).catch(async () => {
        // Fallback ako b2_ok kolona ne postoji
        return pool.query(
          "UPDATE backup_log SET status=$1, filename=$2, size_kb=$3 WHERE id=$4",
          [status, fname, sizeKb, logId]
        );
      });
      
      console.log(`[AutoBackup] ✅ Završeno: ${fname} (${sizeKb} KB, QNAP: ${qnapOk ? 'OK' : 'FAIL'}, B2: ${b2Ok ? 'OK' : 'FAIL'})`);
      
      // Retention — obriši najstariji ZIP s QNAP-a ako imamo više od 52
      try {
        await cleanOldBackups();
      } catch(e) { console.error('[AutoBackup] Cleanup error:', e.message); }
      
    } catch(e) {
      await pool.query(
        "UPDATE backup_log SET status='error', napomena=$1 WHERE id=$2",
        [e.message.slice(0, 500), logId]
      );
      console.error('[AutoBackup] ❌ Greška:', e.message);
    }
  } catch(e) {
    console.error('[AutoBackup] Outer error:', e.message);
  }
}

// Retention — zadrži zadnjih MAX_BACKUPS ZIP-a
// ⭐ v135.7.243: 52 → 10 (Ivanov zahtjev, svibanj 2026)
//   Stari sustav: 52 backup-a (jedna godina tjednih) — predugo + zauzima previše
//   QNAP/B2 prostora.
//   Sad: 10 najsvježijih (otprilike 2 mjeseca tjednih backup-a). Ivan može i ručno
//   obrisati neke s QNAP-a; sustav će dopuniti do 10 sljedećim auto/ručnim backup-om.
const MAX_BACKUPS = 10;

async function cleanOldBackups() {
  // ⭐ v135.7.215: Ako QNAP nije aktivan, koristi B2-only cleanup (sprečava beskonačan rast)
  if (!process.env.QNAP_WEBDAV_URL) {
    if (b2Enabled()) {
      return await _cleanOldBackupsB2Only();
    }
    return;
  }
  
  try {
    const base    = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
    const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
    const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
    const hdrs    = { Authorization: `Basic ${auth64}` };
    
    // PROPFIND za listanje foldera
    const listResp = await fetch(`${baseUrl}${base}/Backup/`, {
      method: 'PROPFIND',
      headers: { ...hdrs, 'Depth': '1', 'Content-Type': 'application/xml' }
    });
    
    if (!listResp.ok) {
      console.log('[AutoBackup] PROPFIND status:', listResp.status);
      return;
    }
    
    const xml = await listResp.text();
    // Parse XML za <d:href> elemente koji sadrže .zip
    const hrefMatches = [...xml.matchAll(/<[dD]:href>([^<]+\.zip)<\/[dD]:href>/g)];
    const files = hrefMatches.map(m => {
      const href = m[1];
      // Izvuci filename
      const parts = href.split('/').filter(Boolean);
      return { href, name: parts[parts.length - 1] };
    });
    
    // Sortiraj po nazivu (koji sadrži timestamp) — najstariji prvi
    files.sort((a, b) => a.name.localeCompare(b.name));
    
    // Ako imamo više od MAX_BACKUPS, obriši najstarije
    if (files.length <= MAX_BACKUPS) {
      console.log(`[AutoBackup] Retention OK: ${files.length}/${MAX_BACKUPS} backup-a`);
      return;
    }
    
    const toDelete = files.slice(0, files.length - MAX_BACKUPS);
    console.log(`[AutoBackup] Brišem ${toDelete.length} starih backup-a (max=${MAX_BACKUPS})...`);
    
    for (const f of toDelete) {
      try {
        const delResp = await fetch(`${baseUrl}${base}/Backup/${encodeURIComponent(f.name)}`, {
          method: 'DELETE',
          headers: hdrs
        });
        console.log(`[AutoBackup] Obrisan ${f.name}: ${delResp.status}`);
        // ⭐ v135.7.215: Briši i s B2 cloud-a (prije je B2 imao backupe zauvijek)
        if (b2Enabled()) {
          await b2Delete(`Backup/${f.name}`).catch(e => 
            console.warn(`[AutoBackup] B2 delete fail ${f.name}:`, e.message)
          );
        }
      } catch(e) {
        console.error(`[AutoBackup] Ne mogu obrisati ${f.name}:`, e.message);
      }
    }
  } catch(e) {
    console.error('[AutoBackup] Cleanup outer:', e.message);
  }
}

// ⭐ v135.7.215: B2-only retention (kad QNAP nije aktivan)
async function _cleanOldBackupsB2Only() {
  try {
    const auth = await b2Authorize();
    if (!auth) return;
    
    const listRes = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
      method: 'POST',
      headers: { Authorization: auth.authToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        bucketId: auth.bucketId, 
        prefix: 'Backup/',
        maxFileCount: 200 
      }),
      signal: AbortSignal.timeout(10000)
    });
    
    if (!listRes.ok) {
      console.error('[AutoBackup B2-only] PROPFIND fail:', listRes.status);
      return;
    }
    
    const data = await listRes.json();
    const files = (data.files || [])
      .filter(f => f.fileName.endsWith('.zip'))
      .map(f => ({ name: f.fileName.replace(/^Backup\//, ''), full: f.fileName }))
      .sort((a, b) => a.name.localeCompare(b.name));
    
    if (files.length <= MAX_BACKUPS) {
      console.log(`[AutoBackup B2-only] Retention OK: ${files.length}/${MAX_BACKUPS}`);
      return;
    }
    
    const toDelete = files.slice(0, files.length - MAX_BACKUPS);
    console.log(`[AutoBackup B2-only] Brišem ${toDelete.length} starih s B2 (max=${MAX_BACKUPS})...`);
    for (const f of toDelete) {
      await b2Delete(f.full).catch(e => console.warn(`[B2 delete] ${f.full}:`, e.message));
    }
  } catch(e) {
    console.error('[AutoBackup B2-only]:', e.message);
  }
}

// ⭐ v135.7.374 (Ivan): node-cron umjesto setInterval za PRECIZNI weekly backup trigger
//   PROBLEM s prijašnjim setInterval pristupom:
//     - 30-min poll je radio kroz "window check" (nedjelja 22-24h ili pon 0-9h)
//     - Drift kroz vrijeme: ako Railway restart-a u utorak 14:00, sljedeći check je u
//       utorak 14:30, ne nedjelja 23:00. Window check je radio ovaj problem manje
//       vidljivim, ali još uvijek je ovisilo o tome da je server budan u prozoru.
//   RJEŠENJE:
//     - node-cron poziva backup u "0 23 * * 0" (svaka nedjelja u 23:00 Europe/Zagreb)
//     - Fallback: ako node-cron paket nije instaliran, koristi stari setInterval
//     - Zadržan poll svaki 30 min KAO fallback za propušten cron run (ako je Railway 
//       restartao 22:59 i nije bio u 23:00) — sigurnosna mreža.
let _nodeCron = null;
try { _nodeCron = require('node-cron'); } catch(_) {
  console.warn('[node-cron] paket nije instaliran — koristim setInterval fallback. Instaliraj: npm i node-cron');
}

if (_nodeCron) {
  // Precizni weekly backup: svaka nedjelja 23:00 Zagreb (Europe/Zagreb timezone)
  _nodeCron.schedule('0 23 * * 0', () => {
    console.log('[node-cron] ⏰ Weekly backup trigger (Nedjelja 23:00 Zagreb)');
    autoBackupCheck().catch(e => {
      console.error('[node-cron weekly backup] fail:', e.message);
      _sentryCapture(e, { source: 'cron_weekly_backup' });
    });
  }, { timezone: 'Europe/Zagreb' });
  console.log('[node-cron] Weekly backup scheduliran: nedjelja 23:00 Europe/Zagreb');

  // ⭐ v659 (Ivan, REVIZIJA): v658 je ovdje dodao retenciju asistent_dopisi — ALI ona VEĆ POSTOJI od v219
  //   (funkcija asistentDopisiRetention niže: node-cron 03:30 + setInterval 24h + setTimeout 10min, env
  //   ASISTENT_DOPISI_RETENTION_DANA). Dupli cron u isto vrijeme + drugi env var = zbunjujuće. Uklonjen duplikat;
  //   retencija ostaje SAMO u v219 mehanizmu (robusniji, ima safety-net za Railway restart).

  // ⭐ v135.7.397: STORAGE HEALTH MONITORING CRON (svakih 15 min)
  //   PROBLEM: UptimeRobot provjerava samo Railway server (HTTP GET /). NE provjerava 
  //   je li QNAP dostupan, je li WebDAV write OK, je li B2 dostupan. Praktični scenarij: 
  //   QNAP padne, Memsur upload-a fotku → Railway prihvati (200 OK), QNAP write tiho 
  //   fail-a, slika ne postoji. 3 dana prođe, akumulira se 47 izgubljenih slika.
  //   
  //   FIX: cron svakih 15 min radi:
  //     - QNAP PROPFIND na bazu (test mreže + auth)
  //     - QNAP PUT + DELETE testnog .ping file-a (test write)
  //     - B2 list buckets call (test auth + connectivity)
  //   
  //   Ako QNAP fail-a 2 puta zaredom → push notif direktoru (throttle 30 min)
  //   Ako B2 fail-a 2 puta zaredom → push notif direktoru (throttle 60 min)
  //   
  //   Status se zapiše u storage_health tablicu — frontend može pokazati indikator.
  _nodeCron.schedule('*/15 * * * *', () => {
    runStorageHealthCheck().catch(e => {
      console.error('[storage-health cron] fail:', e.message);
    });
  }, { timezone: 'Europe/Zagreb' });
  console.log('[node-cron] Storage health monitoring: svakih 15 min');
  
  // ⭐ v135.7.411: TJEDNI IZVJEŠTAJ cron ISKLJUČEN — Ivanov zahtjev (ne treba feature).
  //   Cijeli kod (helper funkcije, endpointi, screen, DB tablica) OSTAJU u kodu kao 
  //   mrtvi kod. Ne smetaju, a lako se vrati natrag uklanjanjem ovog komentara.
  //   
  //   Originalni v409 cron (sad pasivan):
  //   _nodeCron.schedule('0 19 * * 0', () => {
  //     console.log('[node-cron] ⏰ Weekly report trigger (Nedjelja 19:00 Zagreb)');
  //     generateAndSendWeeklyReport().catch(e => {
  //       console.error('[weekly-report cron] fail:', e.message);
  //     });
  //   }, { timezone: 'Europe/Zagreb' });
  //   console.log('[node-cron] Weekly report scheduliran: nedjelja 19:00 Europe/Zagreb');
}
// Sigurnosna mreža: 30-min poll (kao i prije) — hvata propuste ako Railway restart-a
//   u trenutku kad bi node-cron triggered. Window check u autoBackupCheck radi de-duplikat.
setInterval(autoBackupCheck, 30 * 60 * 1000); // 30 min interval (fallback + safety net)
// Prvi check 5 min nakon starta servera (ako je Railway upravo restartao u prozoru)
setTimeout(autoBackupCheck, 5 * 60 * 1000);

// ⭐ v135.7.397: STORAGE HEALTH CHECK — testira QNAP + B2 dostupnost.
//   Zove se iz nodecron-a svakih 15 min i jednom 60s nakon start-a servera.
//   Pamti state u memory (anti-spam za push), upisuje povijest u storage_health tablicu.
//   
//   ⭐ v135.7.403: STATE MACHINE za alert (umjesto count-based):
//     - status: 'ok' → 'fail_pending' (1 fail) → 'down' (2 uzastopna fail-a, push šalje 1×)
//     - status: 'down' → 'recovering' (1 uspjeh) → 'ok' (2 uzastopna uspjeha)
//     - Push šalje SAMO pri prijelazu 'fail_pending' → 'down' (jednom po incidentu).
//     - Sljedeći push tek nakon što sustav prođe kroz 'ok' pa opet padne.
//     - Tako Ivan dobije 1 notifikaciju po stvarnom outage-u, ne neprestane podsjetnike.
//   
//   ⭐ v135.7.403: Robusniji PROPFIND check (bez PUT):
//     - QNAP firmware-i imaju različite reakcije na PROPFIND bez Content-Length.
//     - PUT test zna fail-ati zbog _health folder permissions, kreirajući false positive.
//     - Sad samo PROPFIND s Depth=0 i Content-Length=0 — minimal protocol compliance test.
//     - To je isti read-path koji aplikacija koristi za read-image, pa fail = realan problem.
const _storageHealthState = {
  qnap: { 
    status: 'unknown',         // 'ok' | 'fail_pending' | 'down' | 'recovering' | 'unknown'
    consecutive_fails: 0, 
    consecutive_oks: 0,
    last_alert_sent_at: 0,     // kad je poslana zadnja 'down' notifikacija
    last_status_change_at: Date.now(),
    last_error: null
  },
  b2: { 
    status: 'unknown', 
    consecutive_fails: 0, 
    consecutive_oks: 0,
    last_alert_sent_at: 0, 
    last_status_change_at: Date.now(),
    last_error: null
  }
};

async function runStorageHealthCheck() {
  const ts = Date.now();
  const result = { qnap: null, b2: null, ts };
  
  // ── 1. QNAP test (samo PROPFIND — minimalan, brz, ne mijenja FS) ────────
  if (process.env.QNAP_WEBDAV_URL) {
    const qnapStart = Date.now();
    try {
      const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
      const basePath = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
      const user = process.env.QNAP_USER || '';
      const pass = process.env.QNAP_PASSWORD || '';
      const authHdr = 'Basic ' + Buffer.from(user + ':' + pass).toString('base64');
      
      // PROPFIND s Depth=0 = "samo metadata o ovom direktoriju, ne sadržaj".
      // Content-Length: 0 je obavezan po WebDAV specifikaciji za PROPFIND bez body-ja.
      // Bez toga, neki QNAP firmware vraćaju 411 Length Required ili 400 Bad Request.
      const propResp = await fetch(baseUrl + basePath, {
        method: 'PROPFIND',
        headers: { 
          Authorization: authHdr, 
          Depth: '0',
          'Content-Length': '0'
        },
        signal: AbortSignal.timeout(15000)  // 15s za sporu mrežu (QNAP preko interneta)
      });
      
      // WebDAV PROPFIND uspjeh: 207 Multi-Status. 
      // Neki QNAP firmware vraćaju 200 OK kao alternativu.
      // 401/403 = auth problem (config greška, ne outage). I dalje ne baca alert.
      if (propResp.status === 207 || propResp.status === 200) {
        result.qnap = { ok: true, latency_ms: Date.now() - qnapStart, http_status: propResp.status };
        _trackHealthSuccess('qnap');
      } else if (propResp.status === 401 || propResp.status === 403) {
        // Config greška, ne outage — loggiraj ali ne kao fail za alert mehanizam
        result.qnap = { 
          ok: false, 
          error: `Auth HTTP ${propResp.status} — provjeri QNAP_USER/QNAP_PASSWORD env vars`,
          latency_ms: Date.now() - qnapStart,
          config_error: true
        };
        console.warn(`[storage-health] QNAP AUTH problem (HTTP ${propResp.status}) — config issue, ne tretiram kao outage`);
      } else {
        throw new Error(`PROPFIND HTTP ${propResp.status}`);
      }
      
    } catch (eQ) {
      // Pravi mreža/timeout/connection refused — realan outage signal
      result.qnap = { ok: false, error: eQ.message, latency_ms: Date.now() - qnapStart };
      _trackHealthFailure('qnap', eQ.message, async () => {
        await _sendStorageAlert('qnap', _storageHealthState.qnap);
      });
    }
  } else {
    result.qnap = { ok: null, skip: 'QNAP_WEBDAV_URL nije postavljen' };
  }
  
  // ── 2. B2 test (auth + list) ────────────────────────────────────────────
  if (typeof b2Enabled === 'function' && b2Enabled()) {
    const b2Start = Date.now();
    try {
      const auth = await b2Authorize();
      if (!auth) throw new Error('b2Authorize vratio null');
      
      // Test: pokušaj list-ati 1 file iz bucket-a (lagani API call)
      // ⭐ v466 (Ivan, 18.05.2026): fix property name bug — cached objekt ima `authToken` (ne `authorizationToken`).
      //   PRIJE: `Authorization: auth.authorizationToken` → undefined → HTTP 401 → lažne push notifikacije.
      //   SAD: koristimo `auth.authToken` (cijelo polje iz cached objekta, vidi b2Authorize L11519).
      const listResp = await fetch(`${auth.apiUrl}/b2api/v3/b2_list_file_names`, {
        method: 'POST',
        headers: {
          Authorization: auth.authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          bucketId: auth.bucketId,
          maxFileCount: 1
        }),
        signal: AbortSignal.timeout(15000)
      });
      
      if (!listResp.ok) throw new Error(`B2 list HTTP ${listResp.status}`);
      
      result.b2 = { ok: true, latency_ms: Date.now() - b2Start };
      _trackHealthSuccess('b2');
      
    } catch (eB) {
      result.b2 = { ok: false, error: eB.message, latency_ms: Date.now() - b2Start };
      // ⭐ v135.7.408: B2 PUSH NOTIFIKACIJE UKLONJENE.
      //   Razlog: Ivan ne želi alert-e za B2. B2 je disaster recovery backup, 
      //   ne primary storage — ako padne, QNAP i dalje radi i sustav funkcionira.
      //   Health check track-anje OSTAJE (zapis u storage_health tablicu + state machine), 
      //   ali se push notifikacija ne šalje (callback je null umjesto _sendStorageAlert).
      //   Direktor uvijek može vidjeti status preko /api/storage-health/status endpoint-a.
      _trackHealthFailure('b2', eB.message, null);  // null = no push callback
    }
  } else {
    result.b2 = { ok: null, skip: 'B2 nije omogućen' };
  }
  
  // ── 3. Zapis u storage_health tablicu (limit 1000 redova) ───────────────
  try {
    await pool.query(
      `INSERT INTO storage_health(qnap_ok, qnap_latency_ms, qnap_error, b2_ok, b2_latency_ms, b2_error)
       VALUES($1, $2, $3, $4, $5, $6)`,
      [
        result.qnap?.ok || null, result.qnap?.latency_ms || null, result.qnap?.error || null,
        result.b2?.ok || null, result.b2?.latency_ms || null, result.b2?.error || null
      ]
    );
    
    // Cleanup: zadrži samo zadnjih 1000 redova
    await pool.query(
      `DELETE FROM storage_health WHERE id < (SELECT MIN(id) FROM (SELECT id FROM storage_health ORDER BY id DESC LIMIT 1000) sub)`
    ).catch(() => {});
  } catch (eDb) {
    if (!eDb.message.includes('does not exist')) {
      console.warn('[storage-health] DB insert fail:', eDb.message);
    }
  }
  
  return result;
}

// ⭐ v135.7.403: STATE MACHINE helper functions za health tracking
//   Centralizirana logika za state prijelaze. Push se šalje SAMO pri prijelazu 
//   'fail_pending' → 'down' (tj. 2. uzastopni fail). Tako jednom po incidentu.
function _trackHealthSuccess(service) {
  const s = _storageHealthState[service];
  s.consecutive_oks++;
  s.consecutive_fails = 0;
  s.last_error = null;
  
  // Prijelaz: 'down' / 'recovering' → 'ok' nakon 2 uzastopna uspjeha
  if (s.status === 'down' || s.status === 'recovering' || s.status === 'fail_pending') {
    if (s.consecutive_oks >= 2 || s.status === 'fail_pending') {
      const prevStatus = s.status;
      s.status = 'ok';
      s.last_status_change_at = Date.now();
      console.log(`[storage-health] ${service.toUpperCase()} RECOVERED: ${prevStatus} → ok (${s.consecutive_oks} uspjeha)`);
    } else if (s.status === 'down') {
      s.status = 'recovering';
      console.log(`[storage-health] ${service.toUpperCase()} RECOVERING: 1. uspjeh nakon outage-a, čekam 2.`);
    }
  } else if (s.status === 'unknown') {
    s.status = 'ok';
    s.last_status_change_at = Date.now();
  }
}

function _trackHealthFailure(service, errorMsg, sendAlertCallback) {
  const s = _storageHealthState[service];
  s.consecutive_fails++;
  s.consecutive_oks = 0;
  s.last_error = errorMsg;
  
  console.warn(`[storage-health] ${service.toUpperCase()} FAIL #${s.consecutive_fails}: ${errorMsg}`);
  
  // Prijelaz: 'ok' / 'unknown' → 'fail_pending' (1. fail, tihi — možda flake)
  if (s.status === 'ok' || s.status === 'unknown') {
    s.status = 'fail_pending';
    s.last_status_change_at = Date.now();
    console.log(`[storage-health] ${service.toUpperCase()}: 1. fail → fail_pending (čekam 2. fail prije alarma)`);
  }
  // Prijelaz: 'fail_pending' / 'recovering' → 'down' (2. fail, ALARM)
  else if (s.status === 'fail_pending' || s.status === 'recovering') {
    s.status = 'down';
    s.last_status_change_at = Date.now();
    s.last_alert_sent_at = Date.now();
    console.warn(`[storage-health] ${service.toUpperCase()} CONFIRMED DOWN — šaljem 1 push notifikaciju`);
    // POŠALJI ALERT (samo ovdje, samo jednom po incidentu)
    if (typeof sendAlertCallback === 'function') {
      sendAlertCallback().catch(e => console.warn(`[storage-health] alert send fail:`, e.message));
    }
  }
  // 'down' status — već poslan alert, ne ponavljaj (ovdje je glavni "dovoljno je jednom")
  else if (s.status === 'down') {
    // Tiho, samo prati count — nema push spam-a
  }
}

async function _sendStorageAlert(service, state) {
  try {
    const dir = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1");
    if (!dir.rows.length || typeof sendPushToUser !== 'function') return;
    
    const titleMap = {
      qnap: '⚠ QNAP nedostupan',
      b2: '⚠ Backblaze B2 nedostupan'
    };
    const bodyMap = {
      qnap: `QNAP NAS ne odgovara ${state.consecutive_fails * 15} min. Provjeri uredsku struju/mrežu. App radi na B2 fallback-u.`,
      b2: `B2 ne odgovara ${state.consecutive_fails * 15} min. Disaster recovery backup trenutno isključen. QNAP i dalje radi.`
    };
    
    await sendPushToUser(
      dir.rows[0].id,
      titleMap[service] || `⚠ ${service} nedostupan`,
      bodyMap[service] || `Storage problem.`,
      '/#s-backup'
    );
    
    // Audit log za incident
    if (typeof auditLog === 'function') {
      auditLog({ headers: {}, ip: 'system' }, {
        action: `storage_${service}_down`,
        target_type: 'storage',
        details: { 
          service, 
          consecutive_fails: state.consecutive_fails,
          last_error: state.last_error
        },
        severity: 'warning'
      }).catch(() => {});
    }
  } catch (e) {
    console.warn(`[_sendStorageAlert ${service}] fail:`, e.message);
  }
}

// Run first check 60s nakon starta (daje vremena B2 auth da se zagrije)
setTimeout(() => {
  runStorageHealthCheck().catch(e => console.warn('[storage-health initial]', e.message));
}, 60 * 1000);

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.409: TJEDNI IZVJEŠTAJ
//   Cron svake nedjelje u 19:00 Zagreb generira agregirane podatke za prošli 
//   tjedan i šalje push notifikaciju direktoru. Klik → otvara screen u app-u.
//   
//   Logika:
//     1) Izračun ISO tjedna (1-53). Tjedan ide PON–NED.
//     2) Provjeri weekly_reports tablicu — ako već postoji za ovaj tjedan, skip.
//     3) Agregiraj iz tablica: sihterica, materijal, gorivo, nalozi, place_parametri.
//     4) Pohrani JSON u weekly_reports.report_data.
//     5) Push notifikacija direktoru s kratkim summary.
//     6) Frontend dohvaća kroz GET /api/izvjestaj/tjedni/:iso_week endpoint.
// ═══════════════════════════════════════════════════════════════════════════

// ISO week helper (1-53) — vraća { year, week, start_date, end_date }
function _isoWeekData(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  // PON = 1, NED = 7 (ISO 8601)
  const dayNum = (d.getDay() + 6) % 7;  // 0=PON, 6=NED
  d.setDate(d.getDate() - dayNum);  // pomakni na ponedjeljak ovog tjedna
  const monday = new Date(d);
  d.setDate(d.getDate() + 6);  // nedjelja
  const sunday = new Date(d);
  
  // ISO week calculation
  const yearStart = new Date(monday.getFullYear(), 0, 1);
  const yearStartDay = (yearStart.getDay() + 6) % 7;
  const firstMonday = new Date(yearStart);
  firstMonday.setDate(yearStart.getDate() + (yearStartDay > 3 ? 7 - yearStartDay : -yearStartDay));
  const week = Math.floor((monday - firstMonday) / (7 * 86400000)) + 1;
  
  return {
    year: monday.getFullYear(),
    week: week < 1 ? 52 : week,
    start_date: _ymd(monday),
    end_date: _ymd(sunday),
    iso_key: `${monday.getFullYear()}-W${String(week).padStart(2, '0')}`
  };
}

// Glavni agregator — izračunava sve podatke za jedan tjedan
async function _aggregateWeeklyData(startDate, endDate) {
  const data = {
    period: { start: startDate, end: endDate }
  };
  
  // 1. UKUPNO SATI + USPOREDBA
  try {
    const sihQ = await pool.query(`
      SELECT 
        COALESCE(SUM(sati), 0) AS ukupno_sati,
        COUNT(DISTINCT datum) FILTER (WHERE sati_redovni > 0) AS radni_dani,   -- ⭐ v903: dan sa samo odsutnima nije radni dan
        COUNT(DISTINCT gradiliste_id) AS broj_gradilista
      FROM sihterica
      WHERE datum >= $1 AND datum <= $2
    `, [startDate, endDate]);
    data.sati_ukupno = parseFloat(sihQ.rows[0].ukupno_sati) || 0;
    data.radni_dani = parseInt(sihQ.rows[0].radni_dani) || 0;
    data.gradilista_broj = parseInt(sihQ.rows[0].broj_gradilista) || 0;
    
    // Prethodni tjedan — za trend
    const prevStart = new Date(startDate);
    prevStart.setDate(prevStart.getDate() - 7);
    const prevEnd = new Date(endDate);
    prevEnd.setDate(prevEnd.getDate() - 7);
    const prevQ = await pool.query(`
      SELECT COALESCE(SUM(sati_redovni), 0) AS prev_sati FROM sihterica WHERE datum >= $1 AND datum <= $2   -- ⭐ v903: kolona se zove sati_redovni (prije je tiho padalo u catch)
    `, [_ymd(prevStart), _ymd(prevEnd)]);
    data.sati_prev = parseFloat(prevQ.rows[0].prev_sati) || 0;
    data.sati_diff = data.sati_ukupno - data.sati_prev;
  } catch(e) { console.warn('[weekly-report] sihterica agg fail:', e.message); }
  
  // 2. SATI PO DANIMA (PON-NED)
  try {
    const danQ = await pool.query(`
      SELECT 
        EXTRACT(DOW FROM datum) AS dow,
        COALESCE(SUM(sati_redovni), 0) AS sati
      FROM sihterica
      WHERE datum >= $1 AND datum <= $2
      GROUP BY EXTRACT(DOW FROM datum)
      ORDER BY EXTRACT(DOW FROM datum)
    `, [startDate, endDate]);
    // Postgres DOW: 0=NED, 1=PON, ..., 6=SUB. Mapiramo na PON-NED redoslijed.
    const dayMap = [0, 0, 0, 0, 0, 0, 0];  // [PON, UTO, SRI, ČET, PET, SUB, NED]
    danQ.rows.forEach(r => {
      const dow = parseInt(r.dow);
      const idx = dow === 0 ? 6 : dow - 1;  // NED → 6, PON → 0
      dayMap[idx] = parseFloat(r.sati) || 0;
    });
    data.sati_po_danima = dayMap;
  } catch(e) { console.warn('[weekly-report] dani fail:', e.message); }
  
  // 3. TOP 5 GRADILIŠTA
  try {
    const gradQ = await pool.query(`
      SELECT 
        g.id, g.naziv, g.adresa,
        COALESCE(SUM(s.sati), 0) AS sati,
        COUNT(DISTINCT s.radnik_id) AS broj_radnika
      FROM gradilista g
      LEFT JOIN sihterica s ON s.gradiliste_id = g.id AND s.datum >= $1 AND s.datum <= $2
      WHERE g.aktivan = true
      GROUP BY g.id, g.naziv, g.adresa
      HAVING COALESCE(SUM(s.sati), 0) > 0
      ORDER BY sati DESC
      LIMIT 5
    `, [startDate, endDate]);
    data.top_gradilista = gradQ.rows.map(r => ({
      id: r.id,
      naziv: r.naziv,
      adresa: r.adresa || '',
      sati: parseFloat(r.sati) || 0,
      broj_radnika: parseInt(r.broj_radnika) || 0,
      pct: data.sati_ukupno > 0 ? Math.round((r.sati / data.sati_ukupno) * 100) : 0
    }));
  } catch(e) { console.warn('[weekly-report] gradilista fail:', e.message); }
  
  // 4. MATERIJAL TOP — agregirano po nazivu
  try {
    const matQ = await pool.query(`
      SELECT 
        naziv,
        SUM(CAST(kolicina AS NUMERIC)) AS kolicina_total,
        jedinica,
        COUNT(*) AS broj_unosa
      FROM materijal
      WHERE datum >= $1 AND datum <= $2
      GROUP BY naziv, jedinica
      ORDER BY broj_unosa DESC, kolicina_total DESC
      LIMIT 5
    `, [startDate, endDate]);
    data.top_materijal = matQ.rows.map(r => ({
      naziv: r.naziv,
      kolicina: parseFloat(r.kolicina_total) || 0,
      jedinica: r.jedinica || '',
      broj_unosa: parseInt(r.broj_unosa) || 0
    }));
    
    // Ukupno stavki materijala
    const matCntQ = await pool.query(`
      SELECT COUNT(*) AS cnt FROM materijal WHERE datum >= $1 AND datum <= $2
    `, [startDate, endDate]);
    data.materijal_broj = parseInt(matCntQ.rows[0].cnt) || 0;
  } catch(e) { console.warn('[weekly-report] materijal fail:', e.message); }
  
  // 5. NALOZI STATUS
  try {
    const nalQ = await pool.query(`
      SELECT 
        COUNT(*) FILTER (WHERE rijesen = false) AS otvoreni,
        COUNT(*) FILTER (WHERE rijesen = true AND rijesen_at >= $1 AND rijesen_at <= $2) AS rijeseni_tj,
        COUNT(*) FILTER (WHERE created_at >= $1 AND created_at <= $2) AS novi_tj
      FROM nalozi
    `, [startDate + 'T00:00:00', endDate + 'T23:59:59']);
    data.nalozi = {
      otvoreni: parseInt(nalQ.rows[0].otvoreni) || 0,
      rijeseni_tjedan: parseInt(nalQ.rows[0].rijeseni_tj) || 0,
      novi_tjedan: parseInt(nalQ.rows[0].novi_tj) || 0
    };
  } catch(e) { console.warn('[weekly-report] nalozi fail:', e.message); }
  
  // 6. GORIVO POTROŠENO
  try {
    const gorQ = await pool.query(`
      SELECT COALESCE(SUM(CAST(kolicina AS NUMERIC) * CAST(cijena_po_l AS NUMERIC)), 0) AS gorivo_eur
      FROM gorivo_unosi
      WHERE datum >= $1 AND datum <= $2
    `, [startDate, endDate]);
    data.gorivo_eur = parseFloat(gorQ.rows[0].gorivo_eur) || 0;
  } catch(e) { 
    // Fallback ako kolone su drugačije
    try {
      const gorQ2 = await pool.query(`
        SELECT COUNT(*) AS broj FROM gorivo_unosi WHERE datum >= $1 AND datum <= $2
      `, [startDate, endDate]);
      data.gorivo_eur = 0;
      data.gorivo_broj_unosa = parseInt(gorQ2.rows[0].broj) || 0;
    } catch(_) {}
  }
  
  // 7. SIGURNOSNI INCIDENTI (iz audit_log)
  try {
    const audQ = await pool.query(`
      SELECT 
        COUNT(*) FILTER (WHERE action LIKE 'login_%' AND severity IN ('warning', 'critical')) AS failed_logins,
        COUNT(*) FILTER (WHERE severity = 'critical') AS critical_events,
        COUNT(*) FILTER (WHERE action = 'permanent_delete_gradiliste') AS perm_deletes
      FROM audit_log
      WHERE created_at >= $1 AND created_at <= $2
    `, [startDate + 'T00:00:00', endDate + 'T23:59:59']);
    data.sigurnost = {
      failed_logins: parseInt(audQ.rows[0].failed_logins) || 0,
      critical_events: parseInt(audQ.rows[0].critical_events) || 0,
      perm_deletes: parseInt(audQ.rows[0].perm_deletes) || 0
    };
  } catch(e) { 
    data.sigurnost = { failed_logins: 0, critical_events: 0, perm_deletes: 0 };
  }
  
  // 8. BACKUP STATUS — je li nedjeljni backup ovog tjedna prošao
  try {
    const bkpQ = await pool.query(`
      SELECT id, created_at, status, size_kb, qnap_verified
      FROM backup_log
      WHERE created_at >= $1 AND created_at <= $2
      ORDER BY created_at DESC
      LIMIT 1
    `, [startDate + 'T00:00:00', endDate + 'T23:59:59']);
    if (bkpQ.rows.length) {
      data.backup = {
        ok: bkpQ.rows[0].status === 'ok',
        verified: bkpQ.rows[0].qnap_verified === true,
        size_mb: Math.round((bkpQ.rows[0].size_kb || 0) / 1024)
      };
    } else {
      data.backup = { ok: false, missing: true };
    }
  } catch(e) { data.backup = { error: e.message }; }
  
  // 9. ISTECI DOZVOLA — za sljedećih 30 dana
  try {
    const dozQ = await pool.query(`
      SELECT id, ime, prezime, dozvola_vrijedi_do
      FROM radnici
      WHERE aktivan = true 
        AND dozvola_vrijedi_do IS NOT NULL
        AND dozvola_vrijedi_do <= (now() AT TIME ZONE $$Europe/Zagreb$$)::date + INTERVAL '30 days'
        AND dozvola_vrijedi_do >= (now() AT TIME ZONE $$Europe/Zagreb$$)::date
      ORDER BY dozvola_vrijedi_do ASC
    `);
    data.dozvole_istek = dozQ.rows.map(r => ({
      ime: r.ime + ' ' + r.prezime,
      vrijedi_do: r.dozvola_vrijedi_do,
      dana_do: Math.ceil((new Date(r.dozvola_vrijedi_do) - new Date()) / (1000 * 60 * 60 * 24))
    }));
  } catch(e) { data.dozvole_istek = []; }
  
  return data;
}

// Glavna cron funkcija — generira i sprema izvještaj, šalje push
async function generateAndSendWeeklyReport(opts = {}) {
  const today = new Date();
  // Za nedjelju 19:00 cron — tjedan je već gotov, generiraj za PRETHODNIH 7 dana (PON-NED ovog tjedna)
  const iso = _isoWeekData(today);
  
  // Ako je manual trigger s force=true, ignoriraj duplikat check
  if (!opts.force) {
    const exists = await pool.query(
      `SELECT id FROM weekly_reports WHERE iso_week = $1`,
      [iso.iso_key]
    ).catch(() => ({ rows: [] }));
    
    if (exists.rows.length) {
      console.log(`[weekly-report] ${iso.iso_key} već postoji, skip.`);
      return { skipped: true, iso_key: iso.iso_key };
    }
  }
  
  console.log(`[weekly-report] Generiram za ${iso.iso_key} (${iso.start_date} → ${iso.end_date})`);
  
  // Agregacija
  const data = await _aggregateWeeklyData(iso.start_date, iso.end_date);
  data.iso_week = iso.iso_key;
  data.generated_at = new Date().toISOString();
  
  // Spremi u DB (upsert)
  await pool.query(`
    INSERT INTO weekly_reports (iso_week, start_date, end_date, report_data, generated_at)
    VALUES ($1, $2, $3, $4, NOW())
    ON CONFLICT (iso_week) DO UPDATE SET
      report_data = EXCLUDED.report_data,
      generated_at = EXCLUDED.generated_at
  `, [iso.iso_key, iso.start_date, iso.end_date, JSON.stringify(data)]).catch(e => 
    console.warn('[weekly-report] DB save fail:', e.message)
  );
  
  // Push notifikacija direktoru
  try {
    const dir = await pool.query("SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1");
    if (dir.rows.length && typeof sendPushToUser === 'function') {
      const sati = Math.round(data.sati_ukupno || 0);
      const diff = data.sati_diff || 0;
      const diffStr = diff >= 0 ? `+${Math.round(diff)}h` : `${Math.round(diff)}h`;
      const arrow = diff >= 0 ? '▲' : '▼';
      
      const title = `📊 Tjedni izvještaj — Tjedan ${iso.week}`;
      const body = `${sati}h ovaj tjedan (${arrow} ${diffStr} vs prošli) · ${data.gradilista_broj || 0} gradilišta · ${data.nalozi?.otvoreni || 0} otvorenih naloga`;
      
      await sendPushToUser(dir.rows[0].id, title, body, '/?tab=tjedni-izvjestaj');
      console.log(`[weekly-report] Push poslan: ${title}`);
    }
  } catch(e) { console.warn('[weekly-report] push fail:', e.message); }
  
  return { ok: true, iso_key: iso.iso_key, data };
}

// ENDPOINTS

// GET /api/izvjestaj/tjedni/current — dohvati izvještaj za trenutni tjedan (ili generiraj on-the-fly)
app.get('/api/izvjestaj/tjedni/current', auth, direktor, async (req, res) => {
  try {
    const iso = _isoWeekData(new Date());
    // Pokušaj iz cache-a
    const r = await pool.query(
      `SELECT report_data, generated_at FROM weekly_reports WHERE iso_week = $1`,
      [iso.iso_key]
    ).catch(() => ({ rows: [] }));
    
    if (r.rows.length) {
      return res.json({
        ok: true,
        cached: true,
        iso_week: iso.iso_key,
        generated_at: r.rows[0].generated_at,
        data: typeof r.rows[0].report_data === 'string' ? JSON.parse(r.rows[0].report_data) : r.rows[0].report_data
      });
    }
    
    // On-the-fly za current week (još nije nedjelja 19:00)
    const data = await _aggregateWeeklyData(iso.start_date, iso.end_date);
    data.iso_week = iso.iso_key;
    data.generated_at = new Date().toISOString();
    res.json({ ok: true, cached: false, iso_week: iso.iso_key, data });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

