// ⭐ v135.7.403: ACK alarm — direktor klikne "razumijem, neka ne šalje opet" 
//   Resetira state.status na 'ok' (privremeno) → neće slati push dok se ne dogodi 
//   novi outage (tj. dok se ne prijeđe ponovo kroz 'ok' → 'fail_pending' → 'down').
//   Korisno ako Ivan zna da QNAP namjerno gasi (npr. servis), ne želi spam.
app.post('/api/storage-health/ack/:service', auth, direktor, async (req, res) => {
  const svc = req.params.service;
  if (!['qnap', 'b2'].includes(svc)) {
    return res.status(400).json({ error: 'Service mora biti qnap ili b2' });
  }
  const prevStatus = _storageHealthState[svc].status;
  _storageHealthState[svc].status = 'ok';  // forsiraj OK
  _storageHealthState[svc].consecutive_fails = 0;
  _storageHealthState[svc].last_status_change_at = Date.now();
  console.log(`[storage-health] ${svc.toUpperCase()} alarm ACK-an od direktora: ${prevStatus} → ok (forced)`);
  res.json({ 
    ok: true, 
    service: svc,
    previous_status: prevStatus,
    new_status: 'ok',
    message: `Alarm za ${svc} resetiran. Sljedeći push tek kad se dogodi novi outage.`
  });
});

