    const r = await fetch('https://api.anthropic.com/v1/messages', { method: 'POST', headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' }, body: JSON.stringify({ model: ASISTENT_MODEL_BRZI, max_tokens: 150, messages: [{ role: 'user', content: [{ type: 'image', source: { type: 'base64', media_type: _mime(clean), data: clean } }, { type: 'text', text: 'Ovo je fotografija uz dostavu gradevinskog materijala (otpremnica/racun/paleta). Ukratko: sto se vidi - dobavljac, materijal(i), kolicine ako su citljive. 1-2 recenice, hrvatski, bez uvoda.' }] }] }) });
    if (!r.ok) return false;
