// ⭐ v178: podijeli dugačak tekst u dijelove (~1200 znakova) po odlomcima — za granularnu pretragu baze znanja.
function _chunkText(text, maxLen) {
  maxLen = maxLen || 1200;
  const t = String(text || '').trim();
  if (t.length <= maxLen) return t ? [t] : [];
  const paras = t.split(/\n\s*\n/);
  const chunks = []; let cur = '';
  for (let p of paras) {
    p = p.trim(); if (!p) continue;
    if (cur && (cur.length + 2 + p.length) > maxLen) { chunks.push(cur); cur = ''; }
    cur = cur ? (cur + '\n\n' + p) : p;
    while (cur.length > maxLen) { chunks.push(cur.slice(0, maxLen)); cur = cur.slice(maxLen).trim(); }
  }
  if (cur.trim()) chunks.push(cur.trim());
  return chunks;
}

// ⭐ v179 (Ivan, 07.06.2026): izvuci čitljiv tekst iz HTML-a (za učitavanje zakona/propisa s poveznice u bazu znanja).
// ⭐ v755 (Ivan): entity-decode izdvojen (koriste ga stari i novi ekstraktor).
function _htmlDecodeEnt(s) {
  const named = { 'nbsp':' ','amp':'&','lt':'<','gt':'>','quot':'"','apos':"'",'#39':"'",'scaron':'š','Scaron':'Š','ccaron':'č','Ccaron':'Č','cacute':'ć','Cacute':'Ć','dstrok':'đ','Dstrok':'Đ','zcaron':'ž','Zcaron':'Ž','laquo':'«','raquo':'»','ndash':'–','mdash':'—','hellip':'…','bdquo':'„','ldquo':'“','rdquo':'”',
    'sup2':'\u00b2','sup3':'\u00b3','deg':'\u00b0','plusmn':'\u00b1','le':'\u2264','ge':'\u2265','times':'\u00d7','middot':'\u00b7','minus':'\u2212','frac12':'\u00bd','frac14':'\u00bc','euro':'\u20ac','copy':'\u00a9','reg':'\u00ae','trade':'\u2122','micro':'\u00b5','permil':'\u2030','sect':'\u00a7' };   // ⭐ v755: tehnički entiteti (m², °C, ±, ≤…) — bez ovoga "&sup2;" ostaje sirov u tablicama
  return String(s || '')
    .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => (named[n] !== undefined ? named[n] : ' '))
    .replace(/&#(\d+);/g, (_, n) => { try { return String.fromCodePoint(parseInt(n, 10)); } catch (_e) { return ' '; } })
    .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => { try { return String.fromCodePoint(parseInt(n, 16)); } catch (_e) { return ' '; } });
}
// ⭐ v755 (Ivan): STRUKTURIRANI HTML → tekst. Za bazu znanja (iz-url + docx kroz mammoth HTML):
//   • REŽE boilerplate (nav/aside/footer/header/form/svg/iframe/button/select) — meni i cookie trake
//     više NE ulaze u znanje (stari ekstraktor ih je puštao);
//   • <h1..6> → @@Hn@@ marker (razina za hijerarhijski [put] u chunkeru);
//   • <table> → Markdown PIPE tablica (stari je ćelije slijepio razmacima = smeće za zakone s tablicama);
//   • <li> → "- "; inline tagovi bez razmaka (ne kvari riječi).
function _extractStructFromHtml(html) {
  let s = String(html || '');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ')
       .replace(/<(script|style|noscript|svg|iframe|form|button|select|nav|aside|footer|header)\b[\s\S]*?<\/\1>/gi, '\n')
       .replace(/<head[\s\S]*?<\/head>/gi, '\n');
  s = s.replace(/<table[\s\S]*?<\/table>/gi, (tbl) => {
    try {
      const rows = [];
      for (const tr of (tbl.match(/<tr[\s\S]*?<\/tr>/gi) || [])) {
        const cells = (tr.match(/<t[dh][^>]*>[\s\S]*?<\/t[dh]>/gi) || [])
          .map(c => _htmlDecodeEnt(c.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim());
        if (cells.length) rows.push('| ' + cells.join(' | ') + ' |');
      }
      if (!rows.length) return '\n';
      if (rows.length >= 2) { const nc = Math.max(1, (rows[0].match(/\|/g) || []).length - 1); rows.splice(1, 0, '|' + Array(nc).fill(' --- ').join('|') + '|'); }
      return '\n' + rows.join('\n') + '\n';
    } catch (_) { return '\n'; }
  });
  s = s.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (m, lvl, txt) => '\n@@H' + lvl + '@@ ' + _htmlDecodeEnt(txt.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim() + '\n');
  s = s.replace(/<li[^>]*>/gi, '\n- ');
  s = s.replace(/<\/(p|div|li|ul|ol|tr|section|article|blockquote|figure|figcaption)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/?(b|i|strong|em|span|a|u|small|sup|sub|mark|code)\b[^>]*>/gi, '');
  s = s.replace(/<[^>]+>/g, ' ');
  s = _htmlDecodeEnt(s);
  s = s.replace(/[ \t\f\v]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return s;
}
// ⭐ v755 (Ivan): STRUKTURIRANI CHUNKING za znanje (iz-url + iz-file) — isti duh kao smart-uvoz:
//   sekcije po @@Hn@@ naslovima (fallback heuristika "Članak N." za zakone bez h-tagova), hijerarhijski
//   [Naslov › sekcija] prefiks (čitač + AI citati vode na TOČAN članak), pipe TABLICA atomarna, paragrafi
//   se režu na GRANICI REČENICE (stari _chunkText je rezao usred riječi na tvrdih maxLen znakova).
function _znanjeStrukturirajChunks(naslov, tekst, maxLen) {
  maxLen = maxLen || 1500;
  const lines = String(tekst || '').split('\n');
  const imaH = lines.some(l => /^@@H[1-6]@@ /.test(l));
  const sekcije = []; let cur = { put: [naslov], linije: [] }; const stack = [];
  const pushCur = () => { if (cur.linije.some(l => l.trim())) sekcije.push(cur); };
  for (const l of lines) {
    let razina = null, h = null;
    const mH = l.match(/^@@H([1-6])@@ (.*)$/);
    if (mH) { razina = parseInt(mH[1], 10); h = mH[2].trim(); }
    else if (!imaH && /^(Članak|Ĉlanak)\s+\d+[a-z]?\.?\s*$/i.test(l.trim())) { razina = 2; h = l.trim(); }
    if (h) {
      pushCur();
      while (stack.length && stack[stack.length - 1].razina >= razina) stack.pop();
      stack.push({ razina, naslov: h.slice(0, 120) });
      cur = { put: [naslov, ...stack.map(s2 => s2.naslov)], linije: [] };
    } else cur.linije.push(l);
  }
  pushCur();
  if (!sekcije.length) sekcije.push({ put: [naslov], linije: lines });
  const chunks = [];
  for (const s of sekcije) {
    const pre = '[' + s.put.filter(Boolean).join(' \u203a ') + ']\n';
    const ls = s.linije; const blokovi = []; let buf = [];
    const flush = () => { if (buf.length) { blokovi.push({ t: buf.join('\n'), tbl: false }); buf = []; } };
    for (let i2 = 0; i2 < ls.length; i2++) {
      if (/^\|.*\|$/.test(ls[i2].trim())) {
        flush(); let j2 = i2; const tb = [];
        while (j2 < ls.length && (/^\|.*\|$/.test(ls[j2].trim()) || !ls[j2].trim())) { if (ls[j2].trim()) tb.push(ls[j2].trim()); j2++; }
        blokovi.push({ t: tb.join('\n'), tbl: true }); i2 = j2 - 1;
      } else buf.push(ls[i2]);
    }
    flush();
    let curC = '';
    const emit = () => { const t = curC.trim(); if (t) chunks.push(pre + t); curC = ''; };
    for (const b of blokovi) {
      const bt = b.t.trim(); if (!bt) continue;
      if (b.tbl) {
        if (curC && (curC.length + bt.length) > maxLen) emit();
        if (bt.length > maxLen) { emit(); chunks.push(pre + bt.slice(0, 6000)); continue; }   // tablica NIKAD po sredini
        curC = curC ? (curC + '\n\n' + bt) : bt;
        if (curC.length > maxLen * 0.7) emit();
      } else {
        for (const para of bt.split(/\n\n+/)) {
          let pp = para.trim(); if (!pp) continue;
          if (curC && (curC.length + pp.length + 2) > maxLen) emit();
          while (pp.length > maxLen) {
            let cut = pp.lastIndexOf('. ', maxLen);
            if (cut < maxLen * 0.5) cut = pp.lastIndexOf(' ', maxLen);
            if (cut < maxLen * 0.5) cut = maxLen - 1;
            emit(); chunks.push(pre + pp.slice(0, cut + 1).trim()); pp = pp.slice(cut + 1).trim();
          }
          if (pp) curC = curC ? (curC + '\n\n' + pp) : pp;
        }
      }
    }
    emit();
  }
  return chunks.slice(0, 1500);
}
function _extractTextFromHtml(html) {
  let s = String(html || '');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ')
       .replace(/<script[\s\S]*?<\/script>/gi, ' ')
       .replace(/<style[\s\S]*?<\/style>/gi, ' ')
       .replace(/<head[\s\S]*?<\/head>/gi, ' ')
       .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');
  s = s.replace(/<\/(p|div|li|tr|table|h[1-6]|section|article|header|footer)>/gi, '\n')
       .replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<[^>]+>/g, ' ');
  const named = { 'nbsp':' ','amp':'&','lt':'<','gt':'>','quot':'"','apos':"'",'#39':"'",'scaron':'š','Scaron':'Š','ccaron':'č','Ccaron':'Č','cacute':'ć','Cacute':'Ć','dstrok':'đ','Dstrok':'Đ','zcaron':'ž','Zcaron':'Ž','laquo':'«','raquo':'»','ndash':'–','mdash':'—','hellip':'…','bdquo':'„','ldquo':'“','rdquo':'”' };
  s = s.replace(/&([a-zA-Z]+);/g, (m, n) => (named[n] !== undefined ? named[n] : ' '))
       .replace(/&#(\d+);/g, (_, n) => { try { return String.fromCodePoint(parseInt(n, 10)); } catch (_e) { return ' '; } })
       .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => { try { return String.fromCodePoint(parseInt(n, 16)); } catch (_e) { return ' '; } });
  s = s.replace(/[ \t\f\v]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return s;
}
// ⭐ v179: server-side dohvat URL-a (browser UA) → čitljiv tekst. Limit veličine + timeout.
async function _fetchUrlText(url, opts) {
  opts = opts || {};
  const fetch_ = (typeof fetch === 'function') ? fetch : require('node-fetch');
  const timeoutMs = opts.timeoutMs || 45000;
  const u = String(url || '').trim();
  if (!/^https?:\/\//i.test(u)) throw new Error('URL mora počinjati s http(s)://');
  const resp = await fetch_(u, {
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36', 'Accept': 'text/html,application/xhtml+xml' },
    signal: AbortSignal.timeout(timeoutMs)
  });
  if (!resp.ok) throw new Error('stranica vratila status ' + resp.status);
  const ct = (resp.headers.get('content-type') || '').toLowerCase();
  const raw = await resp.text();
  const _jeHtml = ct.includes('text/html') || /<html|<body|<div|<p[ >]/i.test(raw);
  let text = _jeHtml ? (opts.struct ? _extractStructFromHtml(raw) : _extractTextFromHtml(raw)) : raw;   // ⭐ v755: struct put za bazu znanja
  return String(text || '').slice(0, 700000);
}

async function _asistentResolveGradiliste(naziv) {
  if (!naziv) return [];
  const q = String(naziv).trim();
  // Prvo aktivna (najčešći slučaj)
  let r = await pool.query(
    "SELECT id, naziv FROM gradilista WHERE LOWER(naziv) LIKE LOWER('%'||$1||'%') AND aktivan=true ORDER BY naziv LIMIT 6",
    [q]
  );
  // ⭐ v135.7.502.20.162 (Ivan, 07.06.2026): ako nema aktivnog, padni na SVA (uklj. završena) —
  //   da asistent može dohvatiti i povijesne podatke (npr. završeno gradilište Samobor).
  if (!r.rows.length) {
    r = await pool.query(
      "SELECT id, naziv FROM gradilista WHERE LOWER(naziv) LIKE LOWER('%'||$1||'%') ORDER BY naziv LIMIT 6",
      [q]
    );
  }
  return r.rows || [];
}

