// Skoring: normaliziraj (mala slova, bez dijakritika) → presjek riječi pitanja s (k + txt) sekcije.
function _vodicNorm(s) {
  return String(s || '').toLowerCase()
    .replace(/š/g, 's').replace(/đ/g, 'd').replace(/č/g, 'c').replace(/ć/g, 'c').replace(/ž/g, 'z')
    .replace(/[^a-z0-9€%+± ]+/g, ' ');
}
function _vodicTrazi(pitanje, maxN) {
  const rijeci = _vodicNorm(pitanje).split(/\s+/).filter(w => w.length >= 3);
  if (!rijeci.length) return [];
  const sk = APP_VODIC.map(s => {
    const meta = _vodicNorm(s.tab + ' ' + s.k);
    const tijelo = _vodicNorm(s.txt);
    let sc = 0;
    for (const w of rijeci) {
      if (meta.includes(w)) sc += 3;        // pogodak u ključnim riječima vrijedi više
      else if (tijelo.includes(w)) sc += 1;
    }
    return { s, sc };
  }).filter(x => x.sc > 0).sort((a, b) => b.sc - a.sc);
  return sk.slice(0, maxN || 4).map(x => x.s);
}
