      let w = "d.gradiliste_id=$1";
      const AGG = "string_agg(DISTINCT NULLIF(TRIM(d.komentar),''), ' • ')";
      // ⭐ v698/v708 (Ivan): pretraga po ključnim riječima — SVAKA riječ mora biti u KOMBINIRANOM opisu tog dana,
      //   ali prikaže se CIJELI dan (svi opisi + ukupni radnici + sve fotke) → istinito, poklapa se s dnevnikom.
      let having = '';
