      return JSON.stringify({ gradiliste: g ? g.naziv : 'sva', razdoblje: { od: input.od || 'sve', do: input.do || 'sve' }, ukupno_eur: Math.round(tot), po_gradilistima: per.rows.map(x => ({ gradiliste: x.naziv || '(bez)', eur: Math.round(parseFloat(x.eur) || 0), unosa: parseInt(x.n) || 0 })) });
