      //   id + NAPUTAK; prazno → čista poruka.
      if (!spoj.length) return JSON.stringify({ nalaz: 'Nema rezultata u bazi znanja za taj pojam. Pokušaj drugim pojmom ili se osloni na opće znanje/ostale alate.' });
