function _asistentToolStatus(names) {
  const labels = [...new Set((names || []).map(n => _ASIST_TOOL_LABELS[n] || '🔎 tražim podatke'))];
  if (!labels.length) return 'tražim podatke…';
  return labels.slice(0, 2).join(' · ') + (labels.length > 2 ? ' …' : '');
}
// ⭐ v135.7.502.20.213 (Ivan, 08.06.2026): SANITY-CHECK za dokumente. Problem: model ponekad NE pozove alat
//   (generiraj_dopis/export_pdf/export_excel) nego samo napiše "spreman je" → korisnik nema gumb. Detektori
//   prepoznaju (a) traži li korisnik dokument, (b) tvrdi li asistent da je gotov, (c) pita li legitimno pojašnjenje
//   (tada NE guramo retry). Konzervativno: bolje propustiti nego lažno generirati.
function _asistentZadnjiUserText(messages) {
  for (let i = (messages || []).length - 1; i >= 0; i--) {
    const m = messages[i];
    if (m && m.role === 'user') {
      if (typeof m.content === 'string') return m.content;
      if (Array.isArray(m.content)) return m.content.filter(b => b && b.type === 'text').map(b => b.text || '').join(' ');
    }
  }
  return '';
}
function _userTraziDokument(text) {
  const t = (text || '').toLowerCase();
  if (/(napravi|generiraj|izradi|izrad|sastavi|složi|slozi|pošalji|posalji|izvezi|izvoz|kreiraj|pripremi|daj mi|trebam|treba mi|hoću|hocu|želim|zelim)\b[\s\S]{0,45}(dopis|dokument|pdf|excel|tablic|izvješt|izvjest|ponud|zapisnik|nalog|obrazac|ugovor|opomen|reklamacij|prigovor)/.test(t)) return true;
  if (/(dopis|izvješt|izvjest|ponud|tablic|zapisnik|nalog|opomen)[\s\S]{0,25}(u |kao )?(pdf|excel|word)/.test(t)) return true;
  if (/\b(u|kao)\s+(pdf|excel)\b/.test(t)) return true;
  return false;
}
function _asistentTvrdiSpreman(text) {
  const t = (text || '').toLowerCase();
  return /(spreman|spremn|preuzm|preuzimanj|u prilogu|prilož|prilozen|prilazem|poslao sam|šaljem|saljem|evo (ti )?(dopis|dokument|pdf|datotek|izvješt)|generirao sam|izradio sam|izvezao sam|kreirao sam|sastavio sam|gumb za preuzimanj|link za preuzimanj|možeš (ga )?preuzeti|mozes (ga )?preuzeti|naći ćeš|naci ces)/.test(t);
}
function _asistentPitaPojasnjenje(text) {
  const t = (text || '').toLowerCase();
  if (t.indexOf('?') === -1) return false;
  return /(koje|koji|koju|koliko|za koga|za koje|za koju|želiš li|zelis li|hoćeš li|hoces li|trebam li|trebaš li|trebas li|mogu li|navedi|reci mi|koji datum|koje gradili|koju adresu|kome|na koga|koju vrstu|koji format|daj mi (više |vise )?detalj)/.test(t);
}
// ⭐ v135.7.502.20.157 (Ivan, 06.06.2026): STREAMING verzija chata (SSE) — piše tekst uživo dok razmišlja.
//   Ista logika i sigurnost kao /chat (role-gating, alati, kvota, model-select), ali odgovor teče u komadima.
//   Stari /chat endpoint NAMJERNO ostaje (fallback). SSE eventi: {type:'delta',text} | {type:'status',msg} | {type:'error',msg} | {type:'done'}.
// ⭐ v695 (Ivan): pametni kontekstni prijedlozi — Haiku predloži 2-3 sljedeća koraka po SADRŽAJU odgovora.
//   Kratko + jeftino (Haiku, ~200 tok). Vraća [] na bilo kakav problem (feature nikad ne lomi chat).
async function _asistentPrijedlozi(userQuery, answer) {
  try {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) return [];
    const q = String(userQuery || '').slice(0, 400);
    const a = String(answer || '').replace(/\s+/g, ' ').trim();
    if (a.length < 40) return [];   // pretkratko/prazno → nema smisla
    const prompt = `Korisnik (izvođač na gradilištu, aplikacija ŽBUKA) pitao je: "${q}"\n\nAsistent je odgovorio: "${a.slice(0, 1500)}"\n\nPredloži 2-3 KRATKA (2-5 riječi) konkretna sljedeća koraka/pitanja koja bi korisnik logično poželio NAKON ovog odgovora. Na hrvatskom, praktično, bez ponavljanja onog što je već rečeno. Ako nema smislenih prijedloga, vrati prazan array. Vrati SAMO JSON array stringova i ništa drugo. Primjer: ["Napravi dopis o tome","Usporedi s prošlim mjesecom"]`;
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: ASISTENT_MODEL_BRZI, max_tokens: 200, messages: [{ role: 'user', content: prompt }] }),
    });
    if (!resp.ok) return [];
    const d = await resp.json();
    try { logAIUsage('asistent-prijedlozi', ASISTENT_MODEL_BRZI, d.usage, null, null).catch(() => {}); } catch (_) {}
    const txt = (d.content && d.content[0] && d.content[0].text) || '';
    const m = txt.match(/\[[\s\S]*\]/);
    if (!m) return [];
    const arr = JSON.parse(m[0]);
    if (!Array.isArray(arr)) return [];
    return arr.filter(x => typeof x === 'string' && x.trim()).map(x => x.trim().replace(/^["'\-\s]+|["'\s]+$/g, '').slice(0, 42)).filter(Boolean).slice(0, 3);
  } catch (_) { return []; }
}
// ⭐ v758 (Ivan, OI recept — prekid i nastavak): registar tko upravo piše + rute stanje/prekid.
//   Generiranje je posao SERVERA (send() već guši greške pisanja → nastavlja i kad klijent ode, v207
//   leave-safe finalize + push). Klijent se po povratku PRIKVAČI (GET stanje + interval) i može PREKINUTI.
const _AIUPogonu = new Map();   // korisnik_id -> { ctrl, prekid, razgovorId, ts }
// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v774 (Ivan): TAB PONUDE — Faza 0 / korak 0.1 (temelji).
//   Ovlast 'ponude' je DIREKTORSKA STVAR: podaci (cijene, marže, metodologija) su najosjetljiviji
//   u aplikaciji, pa direktor odlučuje tko ih vidi. Sve rute idu kroz _gateByPath ('ponude').
// ═══════════════════════════════════════════════════════════════════════════

// ⭐ v780 (Ivan): SAMOISCJELJENJE TABLICA. Nalaz s produkcije: `relation "ponude_profil" does not exist`
//   — init-db nije pokrenut (ili je pao), a onda pada SVE: upload slike, spremanje profila, pa i prikaz
//   sažetka jer survey_gotov nikad ne postane true. Umjesto da razvoj ovisi o tome je li netko otvorio
//   /api/init-db, tablice se stvaraju lijeno pri prvom dodiru. CREATE TABLE IF NOT EXISTS je jeftin,
//   a poziva se najviše jednom po procesu (osim ako padne, pa se pokuša ponovno).
// ⭐ v808 (Ivan): TEMELJI AI KALKULANTA — tri pravila koja se ne krše:
//   · tenant_id NIKAD kao literal u NOVOM kodu — uvijek _tid(req)
//   · skalarni ulazi (režijski sat) imaju POVIJEST — nikad UPDATE, uvijek novi redak s vrijedi_od
//   · nerazriješen ulaz vraća razlog, NIKAD tihu nulu
// ⭐ v1084 (revizija taba Ponude): TIHA DEGRADACIJA JE NAJSKUPLJA KLASA U OVOM PROJEKTU.
//   M4 s mrtvim izvor='auto', TDZ raspis koji se gubio cetiri verzije, harness bez konstante — sve
//   troje je kod koji NASTAVI raditi i vrati nesto razumno, samo krivo. `catch (_) {}` je tocno taj
//   obrazac: pad se dogodi, cijena izade niza, i nigdje ne pise zasto. Ovaj helper NE MIJENJA
//   ponasanje (i dalje se nastavlja dalje) nego ga cini vidljivim u Railway logu. Filtar: [tiho].
function _tiho(e, gdje) {
  try { console.warn('[tiho] ' + gdje + ': ' + ((e && e.message) || String(e)).slice(0, 160)); } catch (_) {}
}
function _tid(req) {
  const n = parseInt(req && req.user && req.user.tenant_id, 10);
  return (isFinite(n) && n > 0) ? n : 1;   // JWT danas ne nosi tenant_id → 1; kad ga ponese, radi samo od sebe
}
// Razriješi skalarni ulaz NA DATUM. Ključ 'struka.mjesto' pada na 'struka', pa na razlog — nikad na 0.
async function _kalUlaz(tenant, kljuc, naDan) {
  const dan = naDan || danasZagreb();
  const kandidati = [String(kljuc || '')];
  const t = kandidati[0].lastIndexOf('.');
  if (t > 0) kandidati.push(kandidati[0].slice(0, t));
  for (const k of kandidati) {
    try {
      const r = await pool.query(`SELECT vrijednost, jmj, vrijedi_od FROM kal_input
         WHERE tenant_id=$1 AND kljuc=$2 AND vrijedi_od <= $3::date
         ORDER BY vrijedi_od DESC, id DESC LIMIT 1`, [tenant, k, dan]);
      if (r.rows[0]) return { ok: true, vrijednost: parseFloat(r.rows[0].vrijednost),
        jmj: r.rows[0].jmj, kljuc: k, vrijedi_od: r.rows[0].vrijedi_od };
    } catch (e) { return { ok: false, razlog: 'čitanje palo: ' + String((e && e.message) || '').slice(0, 80) }; }
  }
  return { ok: false, razlog: 'nema vrijednosti za ' + kandidati.join(' ni za ') + ' na dan ' + dan };
}
// ⭐ v1054 (Ivan: „nakon AI ispune svih stavki nemam AI normu proračunato"): OVO JE UZROK Z1.
//   `_kalAutoJednuNorma` i četiri alata chata čitali su sat ovako:
//       SELECT rezijski_sat FROM pon_profil   (odnosno FROM pon_postavke)
//   NIJEDNA OD TE DVIJE TABLICE NE POSTOJI. U cijelom serveru: 5 upotreba, 0 `CREATE TABLE`.
//   Prava tablica se zove `ponude_profil` — ali ni ona nema kolonu `rezijski_sat`. Upit je zato
//   uvijek bacao `relation ... does not exist`, gutao ga je `catch (_) {}`, `sat` je ostajao 0 i
//   funkcija je odustajala na PRVOM retku — za svaku stavku, i poznatu i nepoznatu klasu.
//   Zato AI norme nije bilo ni jedanput, koliko god se popravljalo ono ispod (v1050, v1051, v1052).
//   Ivanov screenshot to i dokazuje: ista stavka pokazuje web + bilten + cjenik, a norme nema ni na
//   ETICS-u (poznata klasa) ni na ventiliranoj (nepoznata) — a to je moguće samo ako pada prije grananja.
//   ISTINA JE `kal_input` (tip='rezijski_sat'), i čita se kroz `_kalUlaz` — točno kako to već radi
//   ruta pojedinačne AI procjene (v856, `sat9`), jedina koja je cijelo vrijeme davala raspis.
//   ⚠ Ključ NE pogađamo. `_kalUlaz` pada samo na točku, ne na `|`, pa `rezijski_sat|firma` nema
//   rezervu; migracija v807 je ključeve mogla složiti i kao `rezijski_sat|opca`. Zato ovdje ide
//   izričit lanac, a na kraju najsvježiji zapis BILO KOJEG ključa tog tipa — i uvijek se kaže odakle
//   je brojka došla, da se sljedeći put ne pogađa nego čita.
async function _kalSatFirme(tenant) {
  const t9 = tenant || 1;
  for (const k of ['rezijski_sat|firma', 'rezijski_sat|opca']) {
    try {
      const r = await _kalUlaz(t9, k);
      const v = r && r.ok ? parseFloat(r.vrijednost) : NaN;
      if (isFinite(v) && v > 0) return { sat: v, kljuc: k };
    } catch (e) { _tiho(e, 'satnica firme: _kalUlaz'); }
  }
  try {
    const r = await pool.query(`SELECT kljuc, vrijednost FROM kal_input
       WHERE tenant_id=$1 AND tip='rezijski_sat' AND vrijednost > 0
       ORDER BY vrijedi_od DESC, id DESC LIMIT 1`, [t9]);
    if (r.rows[0]) {
      const v = parseFloat(r.rows[0].vrijednost);
      if (isFinite(v) && v > 0) return { sat: v, kljuc: r.rows[0].kljuc };
    }
  } catch (e) {
    console.warn('[sat-firme] čitanje kal_input palo: ' + String((e && e.message) || e).slice(0, 120));
  }
  return { sat: 0, kljuc: null };
}
