async function _kalRevizijaTroskovnika(t, pid) {
  const nalazi = [];
  try {
    const r = await pool.query(`SELECT id, oznaka, opis, kolicina, jmj, cijena_jed, obracun_json
      FROM pon_stavke WHERE ponuda_id=$1 AND tenant_id=$2 ORDER BY redoslijed, id LIMIT 700`, [pid, t]);
    const S = (r.rows || []).map(x => {
      const ob = (typeof x.obracun_json === 'string' ? JSON.parse(x.obracun_json || '{}') : (x.obracun_json || {}));
      return { id: x.id, oznaka: x.oznaka, opis: String(x.opis || ''), kol: parseFloat(x.kolicina) || 0,
        jmj: String(x.jmj || '').toLowerCase(), cij: parseFloat(x.cijena_jed) || 0, klasa: ob.klasa || null };
    });
    if (!S.length) return nalazi;
    // (1) raspršena količina: ista klasa + ista jedinica, ≥5 stavaka, sve sitne
    const po = {};
    S.forEach(s => { if (!s.klasa || !(s.kol > 0)) return; const k = s.klasa + '|' + s.jmj; (po[k] = po[k] || []).push(s); });
    Object.keys(po).forEach(k => {
      const g = po[k];
      if (g.length < 5) return;
      const zbroj = g.reduce((a, x) => a + x.kol, 0);
      const prosjek = zbroj / g.length;
      if (prosjek > 40 || zbroj < 50) return;
      nalazi.push({ tip: 'kolicina', tezina: 'visoka',
        poruka: g.length + ' stavaka iste vrste rada (' + k.split('|')[0] + ') od prosječno '
          + (Math.round(prosjek * 10) / 10) + ' ' + g[0].jmj + ' — ukupno '
          + (Math.round(zbroj * 10) / 10) + ' ' + g[0].jmj + '. To je JEDAN posao, ne deset sitnih: '
          + 'na toj količini cijena po jedinici pada, a organizacija se plaća jednom.',
        stavke: g.slice(0, 8).map(x => x.oznaka || ('#' + x.id)) });
    });
    // (2) skrivene obveze iz teksta
    const nadeno = {};
    S.forEach(s => {
      _KAL_KLAUZULE.forEach(([rx, txt]) => {
        if (!rx.test(s.opis)) return;
        if (!nadeno[txt]) nadeno[txt] = [];
        if (nadeno[txt].length < 6) nadeno[txt].push(s.oznaka || ('#' + s.id));
      });
    });
    Object.keys(nadeno).forEach(txt => {
      nalazi.push({ tip: 'klauzula', tezina: 'srednja', poruka: txt, stavke: nadeno[txt] });
    });
    // (3) odskakanja unutar iste struke
    const struke = {};
    S.forEach(s => { if (!s.klasa || !(s.cij > 0)) return; const st = s.klasa.split('.')[0]; (struke[st] = struke[st] || []).push(s); });
    Object.keys(struke).forEach(st => {
      const g = struke[st].filter(x => x.jmj === g0jmj(struke[st]));
      if (g.length < 4) return;
      const c = g.map(x => x.cij).sort((a, b) => a - b);
      const med = c[Math.floor(c.length / 2)];
      if (!(med > 0)) return;
      g.forEach(s => {
        if (s.cij > med * 4) nalazi.push({ tip: 'odskace', tezina: 'srednja',
          poruka: 'stavka ' + (s.oznaka || ('#' + s.id)) + ' je ' + (Math.round(s.cij / med * 10) / 10)
            + '× skuplja od sredine te struke (' + s.cij.toFixed(2) + ' naprama ' + med.toFixed(2) + ') — provjeri jedinicu i količinu.',
          stavke: [s.oznaka || ('#' + s.id)] });
      });
    });
  } catch (_) {}
  return nalazi.slice(0, 25);
}
function g0jmj(arr) {
  const c = {};
  (arr || []).forEach(x => { c[x.jmj] = (c[x.jmj] || 0) + 1; });
  return Object.keys(c).sort((a, b) => c[b] - c[a])[0] || '';
}
