// Prijedlozi opisa iz dosadašnjih stavki — BEZ cijene (namjerno, vidi zaglavlje bloka).
app.get('/api/pon/prijedlozi', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const q = String(req.query.q || '').trim();
    const par = [], uvj = ["tenant_id = 1", "opis <> ''"];
    if (q) { par.push('%' + q + '%'); uvj.push(`opis ILIKE $${par.length}`); }
    const r = await pool.query(
      `SELECT opis, MAX(jmj) AS jmj, COUNT(*)::int AS broj, MAX(updated_at) AS zadnji
         FROM pon_stavke WHERE ${uvj.join(' AND ')}
         GROUP BY opis ORDER BY COUNT(*) DESC, MAX(updated_at) DESC LIMIT 100`, par);
    const g = await pool.query(
      `SELECT grupa, COUNT(*)::int AS broj FROM pon_stavke WHERE tenant_id=1 AND grupa <> ''
         GROUP BY grupa ORDER BY COUNT(*) DESC LIMIT 40`);
    res.json({ ok: true, prijedlozi: r.rows, grupe: g.rows.map(x => x.grupa) });
  } catch (e) { console.error('[pon prijedlozi]', e && e.message); res.json({ ok: false, prijedlozi: [], grupe: [] }); }
});
