// ⭐ v793 (Ivan): RUČNA PROMJENA STATUSA. Dosad se status mijenjao samo kroz izradu memoranduma
//   (skica → spremna), pa se nije moglo evidentirati je li ponuda poslana ni je li prošla.
const PON_STATUSI = ['skica', 'spremna', 'poslana', 'prihvacena', 'odbijena', 'arhiva'];
app.post('/api/pon/ponuda/:id/status', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const id = parseInt(req.params.id, 10);
    const st = String((req.body && req.body.status) || '');
    if (!PON_STATUSI.includes(st)) return res.status(400).json({ error: 'Nepoznat status: ' + st });
    const nap = String((req.body && req.body.napomena) || '').slice(0, 500);
    const danas = danasZagreb();
    const polja = ['status = $1', 'ishod_napomena = $2', 'updated_at = NOW()'];
    const par = [st, nap];
    if (st === 'poslana') { polja.push('poslana_datum = COALESCE(poslana_datum, $' + (par.length + 1) + ')'); par.push(danas); }
    if (st === 'prihvacena' || st === 'odbijena') { polja.push('ishod_datum = $' + (par.length + 1)); par.push(danas); }
    if (st === 'skica' || st === 'spremna') polja.push('ishod_datum = NULL');
    par.push(id); par.push(_tid(req));   // ⭐ v873 #1: tenant iz tokena, ne literal (audit)
    const r = await pool.query(`UPDATE pon_ponude SET ${polja.join(', ')} WHERE id = $${par.length - 1} AND tenant_id = $${par.length}
      RETURNING id, status, poslana_datum, ishod_datum`, par);
    if (!r.rows.length) return res.status(404).json({ error: 'Ponuda nije pronađena' });
    res.json({ ok: true, ponuda: r.rows[0] });
  } catch (e) { console.error('[pon status]', e && e.message); res.status(500).json({ error: 'Promjena statusa nije uspjela: ' + String((e && e.message) || '').slice(0, 140) }); }
});
// ⭐ v804 (Ivan): BRISANJE VIŠE PONUDA ODJEDNOM — nakon testiranja se nakupi hrpa skica.
//   Zadano je meko brisanje (u koš); `trajno` briše dokument, ali STAVKE OSTAJU (gradivo cjenika).
app.post('/api/pon/ponude/obrisi', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const ids = (Array.isArray(req.body && req.body.ids) ? req.body.ids : []).map(x => parseInt(x, 10)).filter(Boolean).slice(0, 300);
    if (!ids.length) return res.status(400).json({ error: 'Nije odabrana nijedna ponuda' });
    const trajno = !!(req.body && req.body.trajno);
    let n = 0, zadrzanoStavki = 0;
    if (trajno) {
      const st = await pool.query('SELECT COUNT(*)::int AS n FROM pon_stavke WHERE ponuda_id = ANY($1::int[]) AND tenant_id=1', [ids]);
      zadrzanoStavki = st.rows[0].n;
      const r = await pool.query('DELETE FROM pon_ponude WHERE id = ANY($1::int[]) AND tenant_id=1', [ids]);
      n = r.rowCount;
    } else {
      const r = await pool.query(`UPDATE pon_ponude SET obrisano=true, obrisano_at=NOW(), updated_at=NOW()
        WHERE id = ANY($1::int[]) AND tenant_id=1 AND obrisano=false`, [ids]);
      n = r.rowCount;
    }
    res.json({ ok: true, obrisano: n, trajno, stavke_zadrzane: zadrzanoStavki });
  } catch (e) { console.error('[pon obrisi vise]', e && e.message); res.status(500).json({ error: 'Brisanje nije uspjelo: ' + String((e && e.message) || '').slice(0, 140) }); }
});
