// ── MEMORANDUM ────────────────────────────────────────────────────────────
// ⭐ v864 (Ivan: „nisam dobio popup koji lokacijski faktor da se primijeni“): JEDNOKRATNI množitelj
//   svih jediničnih cijena ponude (udaljenije gradilište / teži uvjeti). null = popup se pokazuje;
//   nakon odluke (i „bez faktora“ = 1.00) više se ne pita. Primjena je trajna i vidljiva u stavkama.
// ⭐ v1117 (Ivan): SATNICE PO STRUCI — citanje. Vraca SVE struke iz baze, s korisnikovom
//   vrijednoscu ondje gdje je upisana. Klijent tako u jednom pozivu ima cijeli popis i zna sto je
//   cije: `izvor: 'korisnik'` naprama `izvor: 'baza'`.
app.get('/api/pon/kal/satnice', auth, admin, async (req, res) => {
  try {
    const t = _tid(req);
    let moje = {};
    try {
      const q = await pool.query('SELECT struka, eur_h FROM pon_satnice WHERE tenant_id=$1', [t]);
      q.rows.forEach(r => { moje[String(r.struka)] = parseFloat(r.eur_h); });
    } catch (e) { _tiho(e, 'citanje satnica'); }
    const popis = KAL_SATNICE_BAZA.map(x => ({
      struka: x.s, baza_min: x.min, baza_max: x.max,
      eur_h: (moje[x.s] > 0) ? moje[x.s] : ((x.min + x.max) / 2),   // ⭐ v1119: ista sredina kao pri spremanju
      izvor: (moje[x.s] > 0) ? 'korisnik' : 'baza'
    }));
    res.json({ ok: true, satnice: popis, mojih: Object.keys(moje).length });
  } catch (e) { res.status(500).json({ error: String((e && e.message) || 'greška') }); }
});
// ⭐ v1117: spremanje — prima samo ono što je korisnik dirao. Vrijednost jednaka sredini baze
//   BRISE redak (vracanje na bazu), pa se ne gomilaju zapisi koji ne znace nista.
app.post('/api/pon/kal/satnice', auth, admin, async (req, res) => {
  try {
    const t = _tid(req);
    const ul = Array.isArray(req.body && req.body.satnice) ? req.body.satnice.slice(0, 120) : [];
    if (!ul.length) return res.status(400).json({ error: 'Nema što spremiti.' });
    let n = 0, obrisano = 0;
    for (const x of ul) {
      const st = String((x && x.struka) || '').trim().slice(0, 60);
      const v = parseFloat(String((x && x.eur_h) || '').toString().replace(',', '.'));
      if (!st || !KAL_SATNICE_BAZA.some(b => b.s === st)) continue;
      if (!(v >= 5 && v <= 200)) return res.status(400).json({ error: 'Satnica mora biti između 5 i 200 €/h (' + st + ').' });
      const b0 = KAL_SATNICE_BAZA.find(b => b.s === st);
      const sredina = (b0.min + b0.max) / 2;   // ⭐ v1119: TOCNA sredina — klijent racuna isto (35–40 → 37,5, ne 38)
      if (Math.abs(v - sredina) < 0.005) {
        await pool.query('DELETE FROM pon_satnice WHERE tenant_id=$1 AND struka=$2', [t, st]);
        obrisano++; continue;
      }
      await pool.query(`INSERT INTO pon_satnice (tenant_id, struka, eur_h, izvor, updated_at)
        VALUES ($1,$2,$3,'korisnik',NOW())
        ON CONFLICT (tenant_id, struka) DO UPDATE SET eur_h=$3, izvor='korisnik', updated_at=NOW()`, [t, st, v]);
      n++;
    }
    console.log('[satnice] spremljeno ' + n + ', vraceno na bazu ' + obrisano);
    res.json({ ok: true, spremljeno: n, na_bazu: obrisano });
  } catch (e) { _tiho(e, 'spremanje satnica'); res.status(500).json({ error: 'Nije spremljeno' }); }
});
app.post('/api/pon/ponuda/:id/lok-faktor', auth, admin, async (req, res) => {
  // ⭐ v1112: FAKTOR SE SMIJE MIJENJATI. Bio je jednokratan (409 na drugi pokusaj) jer se pitao
  //   jednom, pred izvoz. Ivan ga sada bira u samoj ponudi i ocekuje da cijene i rekapitulacija
  //   skoce odmah — pa mora ici koliko god puta zatreba. Racuna se UVIJEK iz `cijena_jed_baza`
  //   (cijena prije ikakvog faktora), nikad iz vec pomnozene — inace se lipe gube u zaokruzivanju.
  try {
    const t = _tid(req), pid = parseInt(req.params.id, 10);
    const f = parseFloat(String((req.body && req.body.f) || '').replace(',', '.'));
    if (!(f >= 0.5 && f <= 2.0)) return res.status(400).json({ error: 'Faktor mora biti između 0,50 i 2,00.' });
    const p0 = await pool.query('SELECT id FROM pon_ponude WHERE id=$1 AND tenant_id=$2', [pid, t]);
    if (!p0.rows[0]) return res.status(404).json({ error: 'Ponuda ne postoji' });
    // prvi put: zapamti cijene PRIJE faktora (samo gdje jos nisu zapamcene)
    // ⭐ v1115: baza se pamti za SVAKU stavku koja jos nema svoju — i za cijenu i za iznos. Time
    //   stavka koju je Ivan rucno upisao NAKON prvog faktora dobiva vlastito ishodiste i vise se ne
    //   moze nulirati ni pregaziti.
    await pool.query(`UPDATE pon_stavke SET cijena_jed_baza = cijena_jed
      WHERE ponuda_id=$1 AND tenant_id=$2 AND cijena_jed_baza IS NULL AND cijena_jed IS NOT NULL`, [pid, t]);
    await pool.query(`UPDATE pon_stavke SET iznos_baza = iznos
      WHERE ponuda_id=$1 AND tenant_id=$2 AND iznos_baza IS NULL AND iznos IS NOT NULL`, [pid, t]);
    // ⭐ v1114 (Ivan: „lokacijski faktor nije azuriran u ponudi“): IZNOS SE NIJE PRERACUNAVAO.
    //   v1112 je mijenjao samo `cijena_jed`, a `iznos` je zaseban stupac koji rekapitulacija ZBRAJA
    //   (`_ponPreracunaj` radi SUM(iznos)). Jedinicne cijene su se mijenjale, zbrojevi nisu — pa je
    //   izgledalo da faktor ne radi. Oba se sada racunaju u istom upitu, iz iste bazne cijene.
    // ⭐ v1115 (moja regresija iz v1114): `COALESCE(kolicina, 0)` je stavci BEZ kolicine davao
    //   iznos 0 — Ivanova rucno upisana cijena od 1.000 € pala je na 0,00 € cim je odabrao faktor.
    //   Iznos se sada skalira iz `iznos_baza`; kolicina se uopce ne dira jer je ona podatak iz
    //   troskovnika, ne racunica.
    await pool.query(`UPDATE pon_stavke SET cijena_jed = ROUND(cijena_jed_baza * $3, 2)
      WHERE ponuda_id=$1 AND tenant_id=$2 AND cijena_jed_baza IS NOT NULL`, [pid, t, f]);
    // ⭐ v1122 (revizija aritmetike): DVA NEOVISNA ZAOKRUZIVANJA DAVALA SU RAZLIKU OD LIPE.
    //   v1115 je iznos skalirao iz `iznos_baza`, neovisno o novoj cijeni: baza 36,75 x 3 = 110,25,
    //   faktor 1,10 → cijena 40,43 a iznos 121,28 — dok 40,43 x 3 = 121,29. U PDF-u bi stajala
    //   cijena, kolicina i iznos koji se NE MNOZE. Investitor to primijeti prvi.
    //   PRAVILO: gdje kolicina postoji, iznos se racuna IZ NOVE CIJENE (jedno zaokruzivanje na
    //   kraju). `iznos_baza` ostaje samo za stavke BEZ kolicine — pausal, koji se ne moze izvesti.
    await pool.query(`UPDATE pon_stavke SET iznos = ROUND(cijena_jed * kolicina, 2)
      WHERE ponuda_id=$1 AND tenant_id=$2 AND cijena_jed IS NOT NULL AND kolicina > 0`, [pid, t]);
    await pool.query(`UPDATE pon_stavke SET iznos = ROUND(iznos_baza * $3, 2)
      WHERE ponuda_id=$1 AND tenant_id=$2 AND iznos_baza IS NOT NULL
        AND (kolicina IS NULL OR kolicina <= 0)`, [pid, t, f]);
    await pool.query('UPDATE pon_ponude SET lok_faktor=$3, lok_regija=$4 WHERE id=$1 AND tenant_id=$2',
      [pid, t, f, String((req.body && req.body.regija) || '').slice(0, 40) || null]);
    try { await _ponPreracunaj(pid); } catch (_) {}
    console.log('[lok-faktor] ponuda=' + pid + ' ×' + f.toFixed(2) + ' (iz baznih cijena)');
    res.json({ ok: true, faktor: f });
  } catch (e) { res.status(500).json({ error: String((e && e.message) || 'greška') }); }
});
app.post('/api/pon/ponuda/:id/memorandum', auth, admin, async (req, res) => {
  // ⭐ v1069 (FAZA 7 revizije): TRI ZAKUCANA TENANTA NA IZLAZU (2 ovdje + 1 u docx ruti).
  //   Memorandum ide INVESTITORU — tudji korisnik s istim id-em ponude dobio bi Ivanovu ponudu u
  //   svom PDF-u. Ruta je ULAZ u izlazni lanac; zatvara se ovdje, pa 30 zakucanih unutar
  //   _ponPripremiPodatke (poseban krug v1070 — 157 kB funkcije, ne mijenja se naslijepo) postaje
  //   izvana nedohvatljivo za tudje ponude. Poznata granica bete, IZRECENA a ne skrivena:
  //   PDF za tenant≠1 jos vuce PROFIL tenanta 1 u zaglavlju.
  try {
    const id = parseInt(req.params.id, 10);
    const r = await pool.query('SELECT * FROM pon_ponude WHERE id=$1 AND tenant_id=$2', [id, _tid(req)]);
    if (!r.rows.length) return res.status(404).json({ error: 'Ponuda nije pronađena' });
    const P = await _ponPripremiPodatke(r.rows[0]);
    const greske = _ponProvjeriInvarijante(P);
    // ⭐ v896 (Ivan #4): bez vrste radova po stavci rekapitulacija ispadne besmislena (cijeli opis
    //   stavke kao naziv grupe). Memorandum se ne izdaje dok sve stavke nemaju grupu.
    const bezGrupe = await pool.query(
      `SELECT COUNT(*)::int n FROM pon_stavke WHERE ponuda_id=$1 AND tenant_id=$2
        AND COALESCE(NULLIF(TRIM(grupa), ''), NULL) IS NULL`, [id, _tid(req)]);
    if ((bezGrupe.rows[0] || {}).n > 0) {
      return res.status(400).json({ error: 'Memorandum nije generiran',
        bez_grupe: bezGrupe.rows[0].n,
        greske: [(bezGrupe.rows[0].n) + ' stavki nema određenu vrstu radova. Otvori ponudu i dodijeli vrstu radova (grupu) svakoj stavci — rekapitulacija se radi po grupama.'] });
    }
    if (greske.length) return res.status(400).json({ error: 'Memorandum nije generiran', greske });
    const pdf = await _ponMemorandumPDF(P);
    // snapshot uvjeta — kasnija promjena profila ne smije mijenjati poslanu ponudu
    await pool.query(
      `UPDATE pon_ponude SET ukupno_bez=$1, pdv_iznos=$2, ukupno_sa=$3, pdv_mode=$4, status=CASE WHEN status='skica' THEN 'spremna' ELSE status END,
         uvjeti_json=$5::jsonb, updated_at=NOW() WHERE id=$6`,
      [P.ukupnoBez, P.pdvIznos, P.ukupnoSa, P.pdvMode, JSON.stringify({
        rokDana: P.rokDana, opcijaDana: P.opcijaDana, opcijaDo: P.opcijaDo,
        txtGarancija: P.txtGarancija, txtPlacanje: P.txtPlacanje, txtObracun: P.txtObracun }), id]);
    res.json({ ok: true, pdf_base64: 'data:application/pdf;base64,' + pdf.toString('base64'),
      naziv: 'Ponuda_' + String(P.broj).replace(/[^\w-]/g, '') + '.pdf', bajtova: pdf.length,
      izracun: { ukupnoBez: P.ukupnoBez, pdvIznos: P.pdvIznos, ukupnoSa: P.ukupnoSa, rokDana: P.rokDana, opcijaDo: P.opcijaDo } });
  } catch (e) { console.error('[pon memo]', e && e.message); res.status(500).json({ error: 'Memorandum nije uspio: ' + String((e && e.message) || '').slice(0, 160) }); }
});

