    const t9 = _tcMalo(s.opis || '');
    let j9 = null;
    if (/\bkom\b|komad|prodor|okno|element|ugradnj\w*\s+vrat|prozor/.test(t9)) j9 = 'kom';
    else if (/rubnjak|lajsn|op\u0161av|opsav|oluk|\u017eljeb|zljeb|\u0161palet|spalet|profilacij|\bm1\b|du\u017eni/.test(t9)) j9 = 'm';
    else if (/iskop|nasip|zatrpavanj|beton\w*\s+ugradnj|ugradnj\w*\s+beton|betoniranj|volumen|\bm3\b/.test(t9)) j9 = 'm3';
    else if (/\u017ebuk|fasad|etics|ploh|zid|pod|strop|obloga|izolacij|krov|soboslikar/.test(t9)) j9 = 'm2';
    if (j9) { s.jmj = j9; s.jmj_pretpostavljena = true; }
