// GET — cjenik grupiran po vrstama radova; ?q= traži po opisu i šifri
app.get('/api/pon/cjenik', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const q = String(req.query.q || '').trim();
    const par = [], uvj = ['tenant_id = 1', 'aktivno = true'];
    if (q) {
      // ⭐ v796: više ključnih riječi → svaka mora biti negdje (kratki opis, puni opis, vrsta radova);
      //   čisti broj traži i po šifri. Semantičko traženje (vektori) dolazi s AI Sudcem.
      if (/^\d+$/.test(q)) { par.push(parseInt(q, 10)); uvj.push(`sifra = $${par.length}`); }
      else { const u = _ponTraziUvjet(q, par); if (u) uvj.push(u); }
    }
    const r = await pool.query(
      `SELECT id, sifra, grupa, opis, kratki_opis, jmj, cijena_std, cijena_std AS cijena, broj_koristenja, zadnji_put, izvor, updated_at
         FROM pon_cjenik WHERE ${uvj.join(' AND ')}
         ORDER BY grupa, sifra LIMIT 1000`, par);
    const grupe = [], mapa = new Map();
    r.rows.forEach(s => {
      const g = String(s.grupa || '').trim() || 'Bez vrste radova';
      if (!mapa.has(g)) { const o = { grupa: g, stavke: [] }; mapa.set(g, o); grupe.push(o); }
      mapa.get(g).stavke.push(s);
    });
    res.json({ ok: true, grupe, ukupno: r.rows.length, jmj: PON_JMJ });
  } catch (e) { console.error('[cjenik GET]', e && e.message); res.status(500).json({ error: 'Ne mogu učitati cjenik: ' + String((e && e.message) || '').slice(0, 140) }); }
});
