// ⭐ v899 (Ivan): BACKTEST NORMI — koliko su AI minute promašene u odnosu na tvoje ispravke.
//   Za svaki proces koji si ispravio (izvor 'ivan') usporedi se s onim što je AI predlagao;
//   iz omjera izlazi preporuka za faktor strogosti (danas 1.30) po struci i ukupno.
app.get('/api/pon/kal/backtest-norme', auth, admin, async (req, res) => {
  try {
    const t = _tid(req);
    const r = await pool.query(
      `SELECT kljuc, min_po_jmj, izvor, broj_upotreba, ai_min FROM (
         SELECT kljuc, min_po_jmj, izvor, broj_upotreba,
                (SELECT (vrijednost->>'ai_min')::numeric FROM kal_pravilo p
                  WHERE p.tenant_id = kal_proces.tenant_id AND p.oznaka = 'aimin|' || kal_proces.kljuc LIMIT 1) AS ai_min
         FROM kal_proces WHERE tenant_id = $1 AND aktivno = TRUE
       ) x ORDER BY broj_upotreba DESC NULLS LAST LIMIT 200`, [t]).catch(() => ({ rows: [] }));
    const redovi = (r.rows || []).map(x => ({
      kljuc: x.kljuc, tvoje: parseFloat(x.min_po_jmj) || 0, ai: x.ai_min != null ? parseFloat(x.ai_min) : null,
      izvor: x.izvor, upotreba: x.broj_upotreba || 0
    }));
    const sPar = redovi.filter(x => x.izvor === 'ivan' && x.ai != null && x.ai > 0);
    const omjeri = sPar.map(x => x.tvoje / x.ai).filter(x => isFinite(x) && x > 0).sort((a, b) => a - b);
    const med = omjeri.length ? (omjeri.length % 2 ? omjeri[(omjeri.length - 1) / 2] : (omjeri[omjeri.length / 2 - 1] + omjeri[omjeri.length / 2]) / 2) : null;
    res.json({ ok: true, procesa: redovi.length, tvojih: redovi.filter(x => x.izvor === 'ivan').length,
      usporedivih: sPar.length, medijan_omjer: med != null ? Math.round(med * 100) / 100 : null,
      faktor_danas: KAL_STROGOST,
      preporuka: med != null ? Math.round(med * KAL_STROGOST * 100) / 100 : null,
      redovi: redovi.slice(0, 60) });
  } catch (e) { res.status(500).json({ error: String((e && e.message) || 'greška') }); }
});
// ⭐ v1075 (F4, Ivan: „pouzdanost preko 100 % — zbunjujuće; prikazuj SAMO 90+; 60×60 ≠ 120×120“):
//   DIMENZIJSKI GUARD — ako OBJE strane nose dimenziju iste vrste a razlikuju se, to NISU iste stavke.
//   Vrste: format pločica/ploča (A×B, normaliziran redoslijed), debljina (mm, >10 % ili >1 mm razlike),
//   visina („do N m“ — skela/rad na visini). Vraća razlog radi vidljivosti, null = nema sukoba.
function _cjDimSukob(opisA, opisB) {
  try {
    const fmt = (t) => { const m = String(t || '').match(/(\d{1,3})\s*[x×]\s*(\d{1,3})/i);
      if (!m) return null; const a = +m[1], b2 = +m[2]; return (a <= b2 ? a + 'x' + b2 : b2 + 'x' + a); };
    const fA = fmt(opisA), fB = fmt(opisB);
    if (fA && fB && fA !== fB) return 'format ' + fA + ' ≠ ' + fB;
    let mA = null, mB = null;
    try { mA = _tcDebljinaMm(opisA); } catch (_) {}
    try { mB = _tcDebljinaMm(opisB); } catch (_) {}
    if (mA != null && mB != null) {
      const d = Math.abs(mA - mB);
      if (d > Math.max(1, 0.1 * Math.max(mA, mB))) return 'debljina ' + mA + ' mm ≠ ' + mB + ' mm';
    }
    const vis = (t) => { const m = String(t || '').match(/do\s*(\d{1,2})\s*m\b/i); return m ? +m[1] : null; };
    const vA = vis(opisA), vB = vis(opisB);
    if (vA != null && vB != null && vA !== vB) return 'visina do ' + vA + ' m ≠ do ' + vB + ' m';
    // ⭐ v1079 t.b (Ivan): slojevi VIŠE NISU dim-sukob. 2↔3 sloja NE ruši kandidata nego ide kao
    //   KAPA POUZDANOSTI 70 u /cjenik/slicne (ostaje vidljivo da korisnik presudi) i kao PRESKOK u
    //   auto-sidru _kalIzCjenika. Dim-sukob (format/debljina/visina) ostaje tvrd — to su
    //   kategorijalne razlike; broj slojeva je ISTA stavka s doplatom (kod Ivana treći sloj = +X €/m²,
    //   X živi u NJEGOVOM tenantu kroz survey sob_treci, ne u kodu).
    return null;
  } catch (_) { return null; }
}
