    const b64 = String(b.base64 || '').replace(/^data:[^;]+;base64,/, '');
    if (!b64) return res.status(400).json({ error: 'Nema datoteke' });
    const buf = Buffer.from(b64, 'base64');
    if (buf.length > 12 * 1024 * 1024) return res.status(400).json({ error: 'Datoteka je veća od 12 MB' });
    const jePDF = /\.pdf$/i.test(ime) || String(b.mime || '').includes('pdf');
    const traziReviziju = b.revizija !== false;   // ⭐ v800: LLM revizija je uključena po defaultu
    let uvozId = parseInt(b.uvoz_id, 10) || null;
