      const cisti = pdf.stavke.filter(s => s.kolicina != null && s.kolicina > 0 && !TC_UKUPNO.test(String(s.opis || '')));
      r = { listovi: [{ list: 'PDF', stavke: cisti, datum_ponude: null, datum_sigurno: false, datum_izvor: 'PDF' }],
            stavke: cisti, preskoceni: [], upozorenja: [] };
      if (cisti.length !== pdf.stavke.length) (kontrolaAI = pdf.kontrola || []).push({ vrsta: 'odbaceno',
        tekst: (pdf.stavke.length - cisti.length) + ' redaka iz AI izlaza odbačeno (zbrojevi / bez količine).' });
      izvorCitanja = 'ai'; kontrolaAI = pdf.kontrola || [];
