// naziv vrste radova iz profila („Krovopokrivački radovi") → struka (KROV)
function _tcStrukaIzNaziva(naziv) {
  const t9 = _tcMalo(String(naziv || ''));
  if (!t9) return null;
  // ⭐ v1075b (E2E: „A.1.Pripremni i zemljani“ → vraćalo ZEMLJANI): kad naziv nosi VIŠE struka,
  //   pobjeđuje ona koja se u tekstu pojavljuje NAJRANIJE, ne ona koja je prva u tablici.
  let naj = null, najI = Infinity;
  for (const [struka, rx] of _TC_LIST_STRUKA) {
    try { const m9 = t9.match(rx); if (m9 && m9.index < najI) { naj = struka; najI = m9.index; } } catch (_) {}
  }
  return naj;
}
// ⭐ v1075 (INTERNI USER, kritični nalaz): `_tcGrupaZaStavku` poziva `_tcListStruka` koji NIGDJE
//   NIJE POSTOJAO — ReferenceError je tiho gutao try/catch pa je kanon-put grupa bio MRTAV i u
//   produkciji (sve je padalo na staru MAPA-u iz v844). Nitko to ne bi vidio bez izvršnog E2E:
//   grupe su „radile", samo pogrešnim, siromašnijim putem. Alias na istu logiku (list = naziv).
const _tcListStruka = (t) => _tcStrukaIzNaziva(t);

function _tcNaseTudje(s, vrsteRadova) {
  // ⚠ u pravim troškovnicima je LIST često sama struka („10_Fas", „3_Zid", „8_Brav") — to je jači
  //   signal od pojedine riječi u opisu, pa se broji dvaput.
  // ⭐ v981 (SPEC v3 §8 · pravilo 4): sudi po _tcPredmet, NE po cijelom opisu. Ovo je funkcija iste
  //   uloge kao ona koja je na Palači izbacila 4.422 m² žbuke: gledala je svih 5.266 znakova
  //   zalijepljenog bloka, vidjela „armiranobetonskih ploča" na znaku 388 i presudila „tuđi obrt“ —
  //   dok je klasna brana gledala samo uvod i rekla „naše“. Obje su radile točno; tekst je bio kriv.
  //   Sada oba gledaju ISTI tekst, pa se ishod više ne može mijenjati s redoslijedom koraka.
  const list = _tcMalo(s.list || '');
  const txt = _tcMalo(_tcPredmet(s) + ' ' + (s.sekcija || '') + ' ' + list + ' ' + list);
  let bodova = 0, razlog = '';
  // ⭐ v1062: korisnikove struke se određuju PRIJE svakog bodovanja — i naši i tuđi uzorci ovise o njima.
  //   (Prva verzija je `mojeS` gradila tek pred provjeru lista, a koristila ga gore — TDZ bi srusio
  //   funkciju na prvoj stavci, i to tiho, jer je poziv u `try/catch` koji vraća „ostaje".)
  const mojeS = new Set();
  for (const v of (vrsteRadova || [])) { const k9 = _tcStrukaIzNaziva(v); if (k9) mojeS.add(k9); }
  // ⭐ v1063: PRESUDA SE VIŠE NE VUČE IZ FASADERSKOG POPISA NEGO IZ RJEČNIKA SVIH 28 STRUKA.
  //   `TC_NASI_POJMOVI` je popis riječi jedne struke; dok je alat bio Ivanov, to je bilo isto — sada
  //   nije. Krovopokrivaču je „prepoznat naš rad" značilo „prepoznata fasada", pa je za svoju stavku
  //   dobivao nula, a za tuđu fasadersku dva boda. Naopako u oba smjera.
  //   Sada se iz teksta izvuku SVE struke koje se spominju, pa se pita je li ijedna korisnikova.
  const spomenute = _tcStrukeIzTeksta(txt);
  const mojePog = spomenute.filter(x => mojeS.has(x));
  const tudjePog = spomenute.filter(x => !mojeS.has(x));
  if (mojeS.size) {
    if (mojePog.length) { bodova += 3; razlog = 'tvoja struka u opisu (' + mojePog.join(', ').toLowerCase() + ')'; }
    // ⚠ tuđa struka oduzima SAMO ako nijedna moja nije spomenuta. Posao koji dodiruje dvije struke
    //   („fasadna žbuka", „hidroizolacija kolnika vijadukta") ne smije ispasti zato što je i tuđi.
    else if (tudjePog.length) { bodova -= 3; razlog = 'tuđa struka (' + tudjePog[0].toLowerCase() + ')'; }
  } else {
    // profil prazan — prvi dan. Stari fasaderski popis ostaje kao rezerva, ali se KAŽE da je pretpostavka.
    for (const rx of TC_NASI_POJMOVI) if (rx.test(txt)) { bodova += 2; if (!razlog) razlog = 'prepoznat rad (pretpostavka: profil nije popunjen)'; }
  }
  // ⭐ v1062: uzorak tuđe struke se NE PRIMJENJUJE ako je ta struka korisnikova. Bez ovoga je
  //   krovopokrivaču riječ „crijep" oduzimala bodove na vlastitom poslu.
  // ⭐ v1063: stari popis tuđih struka radi još SAMO dok profil nije popunjen. Kad profil postoji,
  //   presudu donosi rječnik iznad — dva popisa koja sude istu stvar razilaze se prije ili kasnije.
  if (!mojeS.size) {
    for (const [struka9, rx] of TC_TUDJI_STRUKA) {
      if (rx.test(txt)) { bodova -= 3; if (bodova < 0) razlog = 'tuđa struka (' + struka9.toLowerCase() + ', pretpostavka: profil nije popunjen)'; }
    }
  }
  for (const v of (vrsteRadova || [])) {
    const k = _ponKljuc(v).slice(0, 5);
    if (k && txt.indexOf(k) !== -1) { bodova += 3; razlog = 'vrsta radova iz tvog profila'; }
  }
  // ⭐ v1062: pogodak VLASTITE STRUKE U TEKSTU, ne samo u imenu lista. Gornja provjera traži prvih pet
  //   slova naziva iz profila („podop" iz „Podopolagački radovi"), a troškovnik piše „parket" — pa
  //   parketaru vlastita stavka nije dobivala nijedan bod i ispadala je iz opsega. Isti popis uzoraka
  //   kojim se prepoznaje ime lista vrijedi i za tekst stavke: ako opis govori o mojoj struci, to je moj
  //   posao bez obzira zove li se list ikako.
  for (const [struka9, rx] of _TC_LIST_STRUKA) {
    if (!mojeS.has(struka9)) continue;
    try { if (rx.test(txt)) { bodova += 3; if (!razlog || bodova <= 3) razlog = 'opis govori o tvojoj struci'; break; } } catch (_) {}
  }
  // ⭐ v1062 (Ivan: „nemoj nužno gledati samo po pitanju fasaderskih radova — trebaš skuziti princip
  //   za SVE VRSTE RADOVA I SVE VRSTE STAVKI"): OVDJE JE ALAT BIO ZAKUCAN NA JEDNU STRUKU.
  //   Stara dva retka glasila su doslovno:
  //       ako list sadrži fas|zbuk|skel   → +3  („naša struka")
  //       ako list sadrži brav|stol|limar|kerami|elektr|vodo|stroj|KROV|geod → −4 („tuđa struka")
  //   Krovopokrivaču čiji se list zove „Krov" vlastiti je posao dobivao −4 i bio proglašen TUĐIM — a
  //   `_tcCijenaIzCjenika` (brana iz v927) takvoj stavci ODBIJA dati cijenu. Isto za bravara, stolara,
  //   limara, keramičara, električara, vodoinstalatera, strojara i geodeta: OSAM struka čiji je vlastiti
  //   troškovnik alat presuđivao kao tuđi posao. Za fasadera je radilo savršeno — i zato se nije vidjelo.
  //   Sada se „naše" i „tuđe" čitaju IZ KORISNIKOVA PROFILA: struke koje je izabrao su naše, ostale tuđe.
  //   Zakucani fasaderski popis ostaje samo kao rezerva dok profil još nije popunjen — prvi dan.
  if (mojeS.size) {
    let pogodio = null;
    for (const [struka, rx] of _TC_LIST_STRUKA) { if (rx.test(list)) { pogodio = struka; break; } }
    if (pogodio) {
      if (mojeS.has(pogodio)) { bodova += 3; razlog = 'list troškovnika je tvoja struka'; }
      else { bodova -= 4; razlog = 'list troškovnika je tuđa struka (' + pogodio.toLowerCase() + ')'; }
    }
  } else {
    // profil prazan — stara pretpostavka, ali se KAŽE da je pretpostavka
    if (/fas\b|fasad|zbuk|žbuk|skel/.test(list)) { bodova += 3; razlog = 'list troškovnika je naša struka (pretpostavka: profil nije popunjen)'; }
    if (/brav|stol|limar|kerami|elektr|vodo|stroj|krov|geod/.test(list)) { bodova -= 4; razlog = 'list troškovnika je tuđa struka (pretpostavka: profil nije popunjen)'; }
  }
  return { nase: bodova > 0, bodova, razlog: razlog || 'nije prepoznato', sigurno: Math.abs(bodova) >= 3 };
}
// Cijena iz cjenika za pročitanu stavku (isti kanonski ključ kao svugdje)
