    if (!ai.ok) return res.json({ ok: false, poruka: ai.errorType === 'rate_limit' ? 'AI zauzet — pokušaj za minutu.' : 'AI nije dostupan.' });
    let txt9 = '';
    try { txt9 = String(((ai.data || {}).content || [])[0] && ai.data.content[0].text || ''); } catch (_) {}
    let pj9 = null;
    try { const m9 = txt9.match(/\{[\s\S]*\}/); pj9 = m9 ? JSON.parse(m9[0]) : null; } catch (_) {}
    if (!pj9 || !Array.isArray(pj9.podstavke)) return res.json({ ok: false, poruka: 'AI odgovor nije razumljiv.' });
    const van9 = pj9.podstavke
      .map(p => ({ rk: parseInt(p.rk, 10), opis: String(p.opis || '').replace(/\s+/g, ' ').trim().slice(0, 560) }))
      .filter(p => kRed9.indexOf(p.rk) >= 0 && p.opis.length >= 8);
