function _kalNormaProvjera(klasa, jmj, minUkupno) {
  const m = parseFloat(minUkupno);
  if (!isFinite(m) || m <= 0) return null;
  const kl = String(klasa || ''), jm = String(jmj || '').toLowerCase();
  let s = null;
  for (const x of _KAL_NORMA_SIDRA) {   // najspecifičniji ključ prvi — popis je složen od užeg prema širem
    if (kl.indexOf(x.k) === 0 && x.jmj === jm) { s = x; break; }
  }
  if (!s) return null;
  const st = m < s.lo ? 'nisko' : (m > s.hi ? 'visoko' : 'ok');
  return { status: st, lo: s.lo, hi: s.hi, jmj: s.jmj, referenca: s.n, min: Math.round(m * 10) / 10,
    poruka: st === 'ok' ? ('norma je u referentnom rasponu ' + s.lo + '–' + s.hi + ' min/' + s.jmj)
      : (st === 'nisko'
        ? ('⚠ ' + (Math.round(m * 10) / 10) + ' min/' + s.jmj + ' je ISPOD referentnog raspona ' + s.lo + '–' + s.hi + ' (' + s.n + ') — vjerojatno fali proces (priprema, detalji ili transport).')
        : ('⚠ ' + (Math.round(m * 10) / 10) + ' min/' + s.jmj + ' je IZNAD referentnog raspona ' + s.lo + '–' + s.hi + ' (' + s.n + ') — provjeri je li neki proces dvaput ubrojen.')) };
}
