// ⭐ v958 (Ivan): NORMA OVISI O MATERIJALU, ne samo o klasi. Kamena vuna je teži rad od EPS-a:
//   ploče su teže i lomljivije pri lijepljenju, a armaturni sloj traži TRI ruke gletanja umjesto dvije.
//   Ivanova mjera s terena: ETICS MW = 1,9 h/m², ETICS EPS/XPS/grafitni = 1,6 h/m² (bilo 1,5 za oboje).
//   Faze ostaju iste — skaliraju se na ciljanu normu, pa se i dalje vidi ŠTO se radi.
//   Ciljane minute su GRADILIŠNE (s bufferom); skaliranje se radi na sirovi zbroj.
const _KAL_FAZE_MAT = {
  'fas.etics': [[/\bmw\b|kamen\w*\s+vun|mineraln\w*\s+vun/i, 114], [/\beps\b|\bxps\b|stiropor|grafitn/i, 96]],
  'fas.etics.bezzavrsne': [[/\bmw\b|kamen\w*\s+vun/i, 92], [/\beps\b|\bxps\b|stiropor|grafitn/i, 78]],
  'fas.sokl': [[/\bxps\b/i, 76], [/\beps\b/i, 70]],
  'izo.termo.fasadna': [[/\bmw\b|kamen\w*\s+vun/i, 62], [/\beps\b|\bxps\b|stiropor/i, 52]]
};
function _kalProcesiObavezni(klasa, opis) {
  const kl = String(klasa || '');
  if (!kl) return null;
  // ⭐ v951: VLASTITE faze klase imaju apsolutnu prednost nad obiteljskim skeletom.
  if (_KAL_FAZE_KLASA[kl]) {
    let p0 = _KAL_FAZE_KLASA[kl].map(x => ({ n: x[0], m: x[1] }));
    let sir0 = Math.round(p0.reduce((a, x) => a + x.m, 0) * 100) / 100;
    // ⭐ v958: materijal mijenja težinu rada — faze se skaliraju na ciljanu normu za taj materijal
    const mv = _KAL_FAZE_MAT[kl];
    let mat0 = null;
    if (mv && opis) {
      for (const [rx, cilj] of mv) {
        if (!rx.test(String(opis))) continue;
        const ciljSir = cilj / KAL_STROGOST;
        const f0 = ciljSir / sir0;
        p0 = p0.map(p => ({ n: p.n, m: Math.round(p.m * f0 * 100) / 100 }));
        sir0 = Math.round(ciljSir * 100) / 100;
        mat0 = cilj;
        break;
      }
    }
    return { kljuc: kl, vlastite: true, procesi: p0, min_ukupno: sir0, materijalna_varijanta: mat0 };
  }
  let naj = null;
  for (const k of Object.keys(_KAL_PROCESI_OBAVEZNI)) {
    if (kl.indexOf(k) === 0 && (!naj || k.length > naj.length)) naj = k;
  }
  if (!naj) return null;
  const p = _KAL_PROCESI_OBAVEZNI[naj].map(x => ({ n: x[0], m: x[1] }));
  return { kljuc: naj, procesi: p, min_ukupno: Math.round(p.reduce((a, x) => a + x.m, 0) * 100) / 100 };
}
// ⭐ v949: norma koja padne ISPOD referentnog raspona se PODIŽE na donju granicu, ne samo prijavi.
//   Razlog: prenizak broj minuta nije mišljenje nego propust — model nije nabrojao sve faze. Podizanje
//   je konzervativno (na donju granicu, ne na sredinu) i uvijek se OBRAZLAŽE, da korisnik vidi što se
//   dogodilo. Previsoku normu NE spuštamo automatski — tu je vjerojatnije da stavka nosi nešto što mi
//   ne vidimo (teži pristup, ručni rad), pa se samo javlja.
function _kalNormaDopuni(klasa, jmj, minUkupno, procesi, opis) {
  // ⭐ v950: NEDOSTAJUĆE FAZE SE DOPUNJUJU, norma se ne „podiže na granicu“. Ako je model nabrojao
  //   četiri od jedanaest faza, ne znači da je posao brži — znači da sedam faza nedostaje. Uzimamo
  //   njegove minute za ono što jest naveo i dodajemo VLASTITE minute za ono što je preskočio.
  //   Poklapanje faza je labavo (po ključnoj riječi), jer model iste radnje zove različito.
  const ob = _kalProcesiObavezni(klasa, opis || null);
  const P = procesi || [];
  // ⭐ v963 (Ivan: „opet 0,72 h za MW 15 cm“): DOPUNA SE PALILA SAMO KAD FALI BROJ FAZA.
  //   Model je naučio nabrojati svih jedanaest — ali im je dao po četiri minute, pa je zbroj ostao
  //   43 min umjesto 114. Brojač faza je bio zadovoljen i ništa se nije dogodilo. Sada se uspoređuje
  //   i ZBROJ: ako je AI ispod 75 % moje norme za tu klasu, uzima se MOJA — to više nije procjena
  //   nego previd. Iznad toga se ne dira; majstor smije biti brži od mene, ali ne dvostruko.
  if (ob) {
    const moja963 = (ob.korisnicka > 0) ? ob.korisnicka : Math.round(ob.min_ukupno * KAL_STROGOST * 10) / 10;
    if (moja963 > 0 && minUkupno > 0 && minUkupno < moja963 * 0.75) {
      return { min: moja963, podignuto: true, procesa: P.length, procesa_ocekivano: ob.procesi.length,
        // ⭐ v968 (Ivan): MIKRORADNJE SE SKALIRAJU ZAJEDNO S NORMOM. Vraćao sam ih sirove (zbroj 72)
        //   dok je naslov pisao 114 — pa se raspis nije zbrajao u ono što piše gore. Sada svaka faza
        //   nosi svoj udio u konačnoj normi: transport nije 4 nego 5 min, lijepljenje 16 pa 20, i tako
        //   redom. Zbroj raspisa = norma, uvijek.
        dodane_faze: [], faze_moje: (function () {
          const f968 = (ob.min_ukupno > 0) ? (moja963 / ob.min_ukupno) : 1;
          return ob.procesi.map(function (p) { return { naziv: p.n, min: _min2(Math.round(p.m * f968 * 10) / 10) }; });
        })(),
        vlastita_norma: ob.korisnicka > 0,
        provjera: _kalNormaProvjera(klasa, jmj, moja963),
        obrazlozenje: 'AI je razložio na ' + P.length + ' faza sa zbrojem ' + minUkupno + ' min/' + jmj
          + ', a ova vrsta rada traži ' + moja963 + ' min (' + (Math.round(moja963 / 60 * 100) / 100) + ' h)'
          + (ob.materijalna_varijanta ? ' za ovaj materijal' : '')
          + '. Uzeo sam svoju normu — razlika je prevelika da bi bila stvarna. Ispravi ako znaš točnije.' };
    }
  }
  // ⭐ v955: ako korisnik ima svoju normu za ovu klasu, ona presuđuje — postavlja se izvana
  //   (kroz o.korisnicka) jer je _kalNormaDopuni sinkrona, a norma dolazi iz baze.
  if (ob && ob.korisnicka > 0) {
    return { min: ob.korisnicka, provjera: null, podignuto: false, procesa: P.length,
      procesa_ocekivano: ob.procesi.length, dodane_faze: [], vlastita_norma: true,
      obrazlozenje: 'tvoja norma za ' + klasa + ': ' + ob.korisnicka + ' min/' + jmj + ' — moja procjena se ne primjenjuje.' };
  }
  const rez = { min: minUkupno, provjera: null, podignuto: false, obrazlozenje: null,
    procesa: P.length, procesa_ocekivano: ob ? ob.procesi.length : 0, dodane_faze: [] };
  if (ob && P.length < ob.procesi.length) {
    const tekst = P.map(p => _tcMalo(String(p.naziv || p.kljuc || ''))).join(' | ');
    const kljuc9 = (n) => _tcMalo(n).split(/[\s,\/]+/).filter(w => w.length >= 4).slice(0, 2);
    let dodano = 0;
    ob.procesi.forEach(f => {
      const k = kljuc9(f.n);
      const pokriveno = k.length ? k.some(w => tekst.indexOf(w.slice(0, 5)) >= 0) : false;
      if (pokriveno) return;
      rez.dodane_faze.push({ naziv: f.n, min: f.m });
      dodano += f.m;
    });
    if (dodano > 0) {
      rez.min = Math.round((minUkupno + dodano * KAL_STROGOST) * 10) / 10;   // dodane faze nose isti buffer (⭐ v1082: bilo 1.25)
      rez.podignuto = true;
      rez.obrazlozenje = 'razloženo je na ' + P.length + ' faza, a ova vrsta rada ih ima '
        + ob.procesi.length + '. Dodao sam što je falilo: '
        + rez.dodane_faze.map(x => x.naziv + ' ' + x.min + ' min').join(' · ')
        + ' — norma s ' + minUkupno + ' na ' + rez.min + ' min/' + jmj
        + ' (' + (Math.round(rez.min / 60 * 100) / 100) + ' h). Ispravi ako znaš točnije.';
    }
  }
  // referentni raspon je MREŽA ZA GRUBE PROMAŠAJE, ne odgovor — samo javlja, ne
  // presuđuje, jer je norma sastavljena iz stvarnih radnji specifičnija od svakog raspona.
  rez.provjera = _kalNormaProvjera(klasa, jmj, rez.min);
  if (!rez.obrazlozenje && rez.provjera && rez.provjera.status !== 'ok') rez.obrazlozenje = rez.provjera.poruka;
  return rez;
}
// ⭐ v971: jedno mjesto za čišćenje float repa kod minuta i iznosa.
function _min2(x) { const v = parseFloat(x); return isFinite(v) ? Math.round(v * 100) / 100 : 0; }
function _kalProcesiStrogi(procesi, f) {
  // ⭐ v924 (Ivan): buffer je 25 % — i mora BITI 25 %. Staro `Math.ceil(m × 1,30)` po procesu
  //   zaokruživalo je svaki proces na cijelu minutu prema gore, pa se buffer zbrajao: stavka s deset
  //   sitnih procesa od 2 min dobivala je +50 %, a ne +30 %. Što je stavka razloženija, to je bila skuplja —
  //   što je suprotno od namjere. Sada: ×1,25 i zaokruživanje na pola minute (gore i dolje).
  const fk = f || 1;
  return (procesi || []).map(p => {
    if (p.izvor === 'ivan') return p;   // korisnikove minute su izmjerene — ne diraj
    const m = parseFloat(p.min_po_jmj) || 0;
    // ⭐ v924: zaokruživanje se PRILAGOĐAVA veličini procesa. Fiksni prag od pola minute
    //   ubijao je rad po kg i m³ — armatura ima procese od 0,1–0,5 min/kg pa je pet takvih davalo
    //   2,5 min/kg (42 h/t) umjesto 1,7 (28 h/t). Sitno se zaokružuje sitno.
    const v9 = m * fk;
    const zaokr9 = v9 < 2 ? 0.05 : (v9 < 10 ? 0.5 : 1);
    // ⭐ v971 (Ivan): FLOAT REP. Math.round(v/0.05)*0.05 daje 1.9000000000000004 — binarni zapis,
    //   ne greška u računu, ali korisnik vidi smetlje u troškovniku. Svaki izračun minuta od sada ide
    //   kroz _min2 koji reže na dvije decimale. Pravilo: nijedna minuta ne izlazi iz sustava nezaštićena.
    return Object.assign({}, p, { min_po_jmj: m > 0 ? _min2(Math.round(v9 / zaokr9) * zaokr9) : m });
  });
}
