// Vrati raspon za struku; podnosi mnozinu, sufikse i djelomicno podudaranje („stolar-PVC“ → „stolar“).
function _kalSatnicaBaza(struka) {
  try {
    const t = String(struka || '').toLowerCase().replace(/[^a-z\u010d\u0107\u017e\u0161\u0111 \-\/]/g, ' ')
      .replace(/\s+/g, ' ').trim();
    if (!t) return null;
    let naj = null;
    for (const x of KAL_SATNICE_BAZA) {
      if (t === x.s) return x;
      if (t.indexOf(x.s) >= 0 || x.s.indexOf(t) >= 0) {
        if (!naj || x.s.length > naj.s.length) naj = x;   // dulje ime = precizniji pogodak
      }
    }
    return naj;
  } catch (_) { return null; }
}
