const KAL_MANIPULACIJA = 1.10;
// ⭐ v881: ZAJEDNIČKI spoj procesa — koriste ga i kalkulant-chat (_kalProcijeni) i kalibrirani prijedlog (_aiPrijedlogIzvedi).
//   Normalizira ključ; minute POTVRĐENIH procesa (izvor 'ivan') GAZE AI prijedlog; novi procesi se uče (upsert).
//   ⭐ v882 (Ivan): šihterica maknuta kao izvor — agregirani dnevni sati ne mogu se pripisati pojedinom procesu.
async function _kalProcesiSpoji(sirovi0, t) {
  const sirovi = (Array.isArray(sirovi0) ? sirovi0 : []).slice(0, 14);
  if (!sirovi.length) return [];
  let poznati = {};
  try {
    const pq = await pool.query(`SELECT kljuc, min_po_jmj, zastoj_h, izvor FROM kal_proces WHERE tenant_id = $1 AND aktivno = TRUE`, [t || 1]);
    pq.rows.forEach(r2 => { poznati[r2.kljuc] = r2; });
  } catch (e) { _tiho(e, 'kal_proces (tvoji procesi kao sidra)'); }
  const procesi = sirovi.map(pr => {
    const kljuc = String(pr.kljuc || pr.naziv || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60);
    const zn = poznati[kljuc];
    const gazi = !!(zn && zn.izvor === 'ivan');   // ⭐ v882 (Ivan): šihterica NIJE izvor procesa — dnevni agregat sati ne zna kojem procesu pripada
    const minAI = parseFloat(String(pr.min_po_jmj).replace(',', '.'));
    const min = gazi ? (parseFloat(zn.min_po_jmj) || 0) : (isFinite(minAI) ? minAI : 0);
    return { kljuc, naziv: String(pr.naziv || '').slice(0, 90), kategorija: String(pr.kategorija || '').slice(0, 20),
      min_po_jmj: Math.round(min * 10) / 10, br_ljudi: parseInt(pr.br_ljudi) || 1,
      zastoj_h: gazi ? (parseFloat(zn.zastoj_h) || 0) : (Math.round((parseFloat(pr.zastoj_h) || 0) * 10) / 10),
      izvor: gazi ? zn.izvor : 'ai', napomena: String(pr.napomena || '').slice(0, 120) };
  }).filter(x => x.kljuc && x.min_po_jmj > 0);
  procesi.forEach(x => {
    pool.query(`INSERT INTO kal_proces (tenant_id, kljuc, naziv, kategorija, min_po_jmj, zastoj_h, izvor, broj_upotreba)
      VALUES ($1,$2,$3,$4,$5,$6,'ai',1)
      ON CONFLICT (tenant_id, kljuc) DO UPDATE SET broj_upotreba = kal_proces.broj_upotreba + 1, updated_at = NOW()`,
      [t || 1, x.kljuc, x.naziv, x.kategorija, x.min_po_jmj, x.zastoj_h]).catch(() => {});
  });
  return procesi;
}
