// ── NADZOR NAD PONUDOM ────────────────────────────────────────────────────
//   Nakon spremanja ponude usporedi svaku stavku s cjenikom i vrati:
//     nove   → nema ih u cjeniku (predlaže se upis)
//     sukobi → ista stavka, DRUGA cijena (korisnik odlučuje koja vrijedi)
//   Ništa se ne mijenja bez korisnikove potvrde (/cjenik/primijeni).
app.post('/api/pon/ponuda/:id/nadzor', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const id = parseInt(req.params.id, 10);
    const st = (await pool.query('SELECT * FROM pon_stavke WHERE ponuda_id=$1 AND tenant_id=1 ORDER BY redoslijed, id', [id])).rows;
    const cj = (await pool.query('SELECT id, sifra, grupa, opis, kratki_opis, kljuc, jmj, cijena_std FROM pon_cjenik WHERE tenant_id=1 AND aktivno=true')).rows;
    const poKljucu = new Map(cj.map(c => [c.kljuc, c]));
    const nove = [], sukobi = [], povezane = [];
    for (const s of st) {
      const opis = String(s.opis || '').trim();
      if (!opis) continue;
      const k = _ponCjenikKljuc(opis, s.kratki_opis, s.jmj, s.debljina_mm != null ? s.debljina_mm : _ponDebljinaIzOpisa(opis), _tcMaterijal(opis));
      const c = poKljucu.get(k);
      const cij = Math.round((parseFloat(s.cijena_jed) || 0) * 100) / 100;
      if (!c) {
        // ⭐ v1082 (Ivan #5): DUPLIKAT-REVIZIJA. Kljuc je promasio, ali to jos ne znaci da stavka
        //   ne postoji — promasuje i na sitnu razliku u opisu. Zato ista presuda koju vec koristi
        //   /cjenik/slicne (guardovi netaknuti) trazi kandidata >=90; ako ga nade, kartica u popupu
        //   ide NARANCASTO s ODZNACENIM checkboxom — sutnja vise ne znaci „dodaj“.
        let sl82 = null;
        try {
          const k82 = _cjSlicniIz(opis, cij, s.jmj || 'm2', cj).filter(x => x.pouzdanost >= 90)[0];
          if (k82) sl82 = { id: k82.id, naziv: String(k82.opis || '').slice(0, 200), cijena: k82.cijena,
            jmj: k82.jmj || '', grupa: k82.grupa || '', pct: k82.pouzdanost,
            cijena_slaganje: !!k82.cijena_slaganje };
        } catch (e82) { console.warn('[nadzor slicna]', e82 && e82.message); }
        if (!nove.some(x => x.kljuc === k)) nove.push({ stavka_id: s.id, kljuc: k, opis, grupa: s.grupa || '',
          jmj: s.jmj || 'm2', cijena: cij, kratki_opis: String(s.kratki_opis || '').trim() || _ponKratkiOpis(opis, s.grupa),
          slicna: sl82 });
        continue;
      }
      if (s.cjenik_id !== c.id || !String(s.kratki_opis || '').trim())
        await pool.query('UPDATE pon_stavke SET cjenik_id=$1, kratki_opis=COALESCE(NULLIF($3,\'\'), kratki_opis) WHERE id=$2',
          [c.id, s.id, String(c.kratki_opis || '')]);
      const std = Math.round((parseFloat(c.cijena_std) || 0) * 100) / 100;
      if (Math.abs(std - cij) > 0.0001 && cij > 0) {
        sukobi.push({ stavka_id: s.id, cjenik_id: c.id, sifra: c.sifra, opis, jmj: c.jmj,
          kratki_opis: String(c.kratki_opis || '').trim() || _ponKratkiOpis(opis, c.grupa),
          cijena_cjenik: std, cijena_ponuda: cij, razlika_pct: std > 0 ? Math.round((cij - std) / std * 1000) / 10 : null });
      } else povezane.push({ stavka_id: s.id, cjenik_id: c.id, sifra: c.sifra });
    }
    res.json({ ok: true, nove, sukobi, povezane, ukupno_stavki: st.length });
  } catch (e) { console.error('[pon nadzor]', e && e.message); res.status(500).json({ error: 'Nadzor nije uspio: ' + String((e && e.message) || '').slice(0, 140) }); }
});
// Primjena korisnikovih odluka
app.post('/api/pon/cjenik/primijeni', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();
    const b = req.body || {};
    const ponudaId = parseInt(b.ponuda_id, 10) || null;
    const ponBroj = ponudaId ? String(((await pool.query('SELECT broj FROM pon_ponude WHERE id=$1 AND tenant_id=1', [ponudaId])).rows[0] || {}).broj || '') : '';
    let dodano = 0, azurirano = 0;
    for (const n of (Array.isArray(b.dodaj) ? b.dodaj : [])) {
      const opis = String(n.opis || '').trim().slice(0, 1200);
      if (!opis) continue;
      const kratkiN = String(n.kratki_opis || '').trim().slice(0, 80) || _ponKratkiOpis(opis, n.grupa);
      const kljuc = _ponCjenikKljuc(opis, kratkiN, n.jmj, _ponDebljinaIzOpisa(opis), _tcMaterijal(opis));
      const post = await pool.query('SELECT id FROM pon_cjenik WHERE tenant_id=1 AND kljuc=$1', [kljuc]);
      const cijena = Math.round((parseFloat(n.cijena) || 0) * 100) / 100;
      let cid;
      if (post.rows.length) { cid = post.rows[0].id; }
      else {
        // ⭐ v877: SEM-GUARD (ponuda→cjenik put) — isti princip
        const semU8 = _znSemKljuc((kratkiN || '') + ' ' + (opis || ''), n.jmj);
        const semK8 = await pool.query(`SELECT id, sem_kljuc FROM pon_cjenik WHERE tenant_id=1 AND aktivno=true AND sem_kljuc LIKE $1 LIMIT 30`, [_znJezgra(semU8).pre + '%']);
        const sp8 = semK8.rows.filter(r8 => r8.sem_kljuc === semU8 || _znSlicni(r8.sem_kljuc, semU8))[0];
        if (sp8) { cid = sp8.id; }
        else {
        const sifra = await _ponCjenikSifra();
        const ins = await pool.query(
          `INSERT INTO pon_cjenik (tenant_id, sifra, grupa, opis, kljuc, sem_kljuc, jmj, cijena_std, izvor, zadnji_put, broj_koristenja, kratki_opis)
           VALUES (1,$1,$2,$3,$4,$5,$6,$7,'ponuda',$8,0,$9) RETURNING id`,
          [sifra, String(n.grupa || '').slice(0, 120), opis, kljuc, semU8, PON_JMJ.includes(String(n.jmj)) ? n.jmj : 'm2', cijena, danasZagreb(), kratkiN]);
        cid = ins.rows[0].id; dodano++;
        await _ponCjenikPovijest(cid, cijena, ponBroj || 'ponuda', 'upisano iz ponude');
      }
        }
      if (n.stavka_id) await pool.query(`UPDATE pon_stavke SET cjenik_id=$1,
        kratki_opis=COALESCE(NULLIF(kratki_opis,''), $3) WHERE id=$2 AND tenant_id=1`,
        [cid, parseInt(n.stavka_id, 10), String(n.kratki_opis || '').slice(0, 80)]);
    }
    let ispravljeno = 0;
    for (const o of (Array.isArray(b.odluke) ? b.odluke : [])) {
      const cid = parseInt(o.cjenik_id, 10);
      const akcija = String(o.akcija || '');
      // ⭐ v796 (Ivan): samo dvije mogućnosti — cijena iz ponude postaje standardna, ILI se
      //   stavka u ponudi ispravlja na cijenu iz cjenika (kad je upis bio greška).
      if (akcija === 'ispravi_ponudu') {
        const sid = parseInt(o.stavka_id, 10);
        const cj = (await pool.query('SELECT cijena_std FROM pon_cjenik WHERE id=$1 AND tenant_id=1', [cid])).rows[0];
        const sv = sid ? (await pool.query('SELECT kolicina FROM pon_stavke WHERE id=$1 AND tenant_id=1', [sid])).rows[0] : null;
        if (cj && sv) {
          // iznos se računa u aplikaciji (ne u SQL-u) — ista aritmetika kao svugdje drugdje
          const nova = Math.round((parseFloat(cj.cijena_std) || 0) * 100) / 100;
          const izn = _ponIznos(sv.kolicina, nova);   // ⭐ v1248 B2
          await pool.query('UPDATE pon_stavke SET cijena_jed=$1, iznos=$2, cijena_jed_baza=NULL, iznos_baza=NULL, updated_at=NOW() WHERE id=$3 AND tenant_id=1', [nova, izn, sid]);   // ⭐ v1248 B1
          ispravljeno++;
        }
        continue;
      }
      if (akcija === 'nova_cijena') {
        const cijena = Math.round((parseFloat(o.cijena) || 0) * 100) / 100;
        const st = (await pool.query('SELECT cijena_std FROM pon_cjenik WHERE id=$1 AND tenant_id=1', [cid])).rows[0];
        await pool.query('UPDATE pon_cjenik SET cijena_std=$1, zadnji_put=$2, updated_at=NOW() WHERE id=$3 AND tenant_id=1',
          [cijena, danasZagreb(), cid]);
        await _ponCjenikPovijest(cid, cijena, ponBroj || 'ponuda', 'nova standardna cijena (bilo ' + _ponEur(st ? st.cijena_std : 0) + ' €)');
        azurirano++;
      }
    }
    // broj korištenja i datum za sve povezane stavke ove ponude
    if (ponudaId) {
      await pool.query(`UPDATE pon_cjenik c SET broj_koristenja = c.broj_koristenja + 1, zadnji_put = $1, updated_at = NOW()
        WHERE c.tenant_id = 1 AND c.id IN (SELECT DISTINCT cjenik_id FROM pon_stavke WHERE ponuda_id = $2 AND cjenik_id IS NOT NULL)`,
        [danasZagreb(), ponudaId]);
    }
    let ukupno = null;
    if (ponudaId && ispravljeno) { const pre = await _ponPreracunaj(ponudaId); ukupno = pre.ukupno; }
    res.json({ ok: true, dodano, azurirano, ispravljeno, ukupno_bez: ukupno });
  } catch (e) { console.error('[cjenik primijeni]', e && e.message); res.status(500).json({ error: 'Primjena nije uspjela: ' + String((e && e.message) || '').slice(0, 140) }); }
});

// ── LISTA PONUDA (kostur; puni se od Faze 1a) ─────────────────────────────
app.get('/api/pon/lista', auth, admin, async (req, res) => {
  try {
    await _ponudeOsiguraTablice();   // ⭐ v780: tablice se stvaraju same, init-db nije uvjet
    const kos = String(req.query.kos || '') === '1';
    const q = String(req.query.q || '').trim();
    const uvjeti = ['p.tenant_id = 1', kos ? 'p.obrisano = true' : 'p.obrisano = false'];
    const par = [];
    // ⭐ v797 (Ivan): PAMETNA TRAŽILICA po ponudama. Svaka upisana riječ mora se naći negdje —
    //   u broju, naručitelju, predmetu, lokaciji, regiji ILI u nekoj STAVCI te ponude (opis/kratki opis).
    //   Traži se po korijenu riječi (isto kao u cjeniku), pa „dombar fasada" nađe ponudu tom naručitelju
    //   u kojoj postoji fasaderska stavka. Semantičko traženje dolazi s vektorima u Fazi 1b.
    for (const r0 of _ponRijeciUpita(q)) {
      par.push('%' + _ponKorijen(r0) + '%');
      const i = par.length;
      uvjeti.push(`(p.broj ILIKE $${i} OR p.narucitelj ILIKE $${i} OR p.predmet ILIKE $${i}
        OR p.lokacija ILIKE $${i} OR p.regija ILIKE $${i} OR p.napomene ILIKE $${i}
        OR st.tekst ILIKE $${i})`);
    }
    // sadržaj stavki se spaja u jedan tekst po ponudi (jedan prolaz, bez koreliranih podupita)
    const r = await pool.query(
      `SELECT p.id, p.broj, p.godina, p.datum, p.status, p.narucitelj, p.predmet, p.lokacija, p.regija,
              p.ukupno_bez, p.memo_pdf_path, p.memo_docx_path, p.nacin_izrade,
              p.poslana_datum, p.ishod_datum, p.obrisano_at, p.pdv_mode,
              COALESCE(st.broj_stavki, 0) AS broj_stavki
         FROM pon_ponude p
         LEFT JOIN (SELECT ponuda_id, COUNT(*)::int AS broj_stavki,
                           string_agg(COALESCE(opis,'') || ' ' || COALESCE(kratki_opis,'') || ' ' || COALESCE(grupa,''), ' ') AS tekst
                      FROM pon_stavke WHERE tenant_id = 1 GROUP BY ponuda_id) st ON st.ponuda_id = p.id
         WHERE ${uvjeti.join(' AND ')}
         ORDER BY p.godina DESC, p.broj_redni DESC LIMIT 800`, par);
    res.json({ ponude: r.rows, trazeno: q || null });
  } catch (e) { console.error('[ponude lista]', e); res.status(500).json({ error: 'Greška' }); }
});

// ⭐ v768 (Ivan): RUČNI OVERRIDE blagdana — direktor ima ZADNJU RIJEČ (nadjačava i algoritam i online).
//   GET  /api/blagdani?godina=2026            → lista s izvorom svakog dana (algoritam/službeno/ručno)
//   POST /api/blagdani/override {godina, datum, naziv, akcija:'dodaj'|'ukloni'|'ponisti'}
//   POST /api/blagdani/sync {godina}          → ručno pokreni provjeru službene liste
app.get('/api/blagdani', async (req, res, next) => {
  // ⭐ v769 (Ivan): read-only provjera iz preglednika preko ?key= (adresna traka nema JWT header).
  //   Sve ostalo (override/sync) i dalje traži prijavu + direktora.
  if (req.query && req.query.key && req.query.key === process.env.INIT_SECRET) return _blagdaniGET(req, res);
  return auth(req, res, () => _blagdaniGET(req, res));
});
async function _blagdaniGET(req, res) {
  try {
    const godina = parseInt(req.query.godina, 10) || new Date().getFullYear();
    const zemlja = String(req.query.zemlja || process.env.ZEMLJA_BLAGDANI || 'HR').toUpperCase();
    await _blagdaniUcitajCache();
    const alg = praznikiDetalj(godina, zemlja, { bezOverride: true });
    const algSet = new Set(alg.map(p => p.datum));
    const c = (_blagdaniCache[zemlja] && _blagdaniCache[zemlja][godina]) || null;
    const rucnoDodaj = new Set(((c && c.rucno && c.rucno.dodaj) || []).map(x => x.datum));
    const rucnoUkloni = new Set((c && c.rucno && c.rucno.ukloni) || []);
    const finalna = praznikiDetalj(godina, zemlja);
    res.json({
      godina, zemlja,
      blagdani: finalna.map(p => ({
        datum: p.datum, naziv: p.naziv,
        izvor: rucnoDodaj.has(p.datum) ? 'ručno' : (algSet.has(p.datum) ? 'algoritam' : 'službena lista')
      })),
      uklonjeni_rucno: [...rucnoUkloni],
      zadnja_provjera: c && c.sync_ts ? new Date(c.sync_ts).toISOString().slice(0, 16).replace('T', ' ') : null,
      izvor_provjere: (c && c.izvor) || null
    });
  } catch (e) { console.error('[blagdani GET]', e); res.status(500).json({ error: 'Greška' }); }
}
app.post('/api/blagdani/override', auth, async (req, res) => {
  try {
    if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor' });
    const godina = parseInt(req.body && req.body.godina, 10);
    const datum = String((req.body && req.body.datum) || '');
    const akcija = String((req.body && req.body.akcija) || '');
    if (!Number.isFinite(godina) || !/^\d{4}-\d{2}-\d{2}$/.test(datum)) return res.status(400).json({ error: 'Neispravna godina/datum' });
    if (['dodaj', 'ukloni', 'ponisti'].indexOf(akcija) === -1) return res.status(400).json({ error: 'Neispravna akcija' });
    const zemlja = String((req.body && req.body.zemlja) || process.env.ZEMLJA_BLAGDANI || 'HR').toUpperCase();
    const cache = await _blagdaniUcitajCache();
    cache[zemlja] = cache[zemlja] || {};
    const rec = cache[zemlja][godina] = cache[zemlja][godina] || { dodaj: [], ukloni: [], rucno: { dodaj: [], ukloni: [] } };
    rec.rucno = rec.rucno || { dodaj: [], ukloni: [] };
    rec.rucno.dodaj = (rec.rucno.dodaj || []).filter(x => x.datum !== datum);
    rec.rucno.ukloni = (rec.rucno.ukloni || []).filter(d => d !== datum);
    if (akcija === 'dodaj') rec.rucno.dodaj.push({ datum, naziv: String((req.body && req.body.naziv) || 'Blagdan').slice(0, 80) });
    else if (akcija === 'ukloni') rec.rucno.ukloni.push(datum);
    await _blagdaniSpremiCache(cache);
    res.json({ ok: true, blagdani: praznikiDetalj(godina, zemlja) });
  } catch (e) { console.error('[blagdani override]', e); res.status(500).json({ error: 'Greška' }); }
});
app.post('/api/blagdani/sync', auth, async (req, res) => {
  try {
    if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor' });
    const godina = parseInt(req.body && req.body.godina, 10) || new Date().getFullYear();
    const zemlja = String((req.body && req.body.zemlja) || process.env.ZEMLJA_BLAGDANI || 'HR').toUpperCase();
    const r = await _blagdaniSync(godina, zemlja);
    res.json(r.ok ? { ok: true, dodano: r.dodaj.length, uklonjeno: r.ukloni.length, blagdani: praznikiDetalj(godina, zemlja) }
                  : { ok: false, error: 'Službena lista trenutno nedostupna — vrijedi izračun iz algoritma.' });
  } catch (e) { console.error('[blagdani sync]', e); res.status(500).json({ error: 'Greška' }); }
});

