// ⭐ v666 (Ivan): IZVOZ RAZGOVORA U PDF (arhiva/klijent). Streama PDF; klijent skine kao blob.
app.get('/api/asistent/razgovor/:id/pdf', auth, async (req, res) => {
  try {
    const rz = await pool.query('SELECT naslov, poruke FROM asistent_razgovori WHERE id=$1 AND korisnik_id=$2', [req.params.id, req.user.id]);
    if (!rz.rows.length) return res.status(404).json({ error: 'Razgovor nije pronađen.' });
    let poruke = rz.rows[0].poruke; if (typeof poruke === 'string') { try { poruke = JSON.parse(poruke); } catch (_) { poruke = []; } }
    if (!Array.isArray(poruke)) poruke = [];
    const naslov = String(rz.rows[0].naslov || 'Razgovor');
    const PDFDocument = require('pdfkit'); const path2 = require('path'); const fs2 = require('fs');
    const doc = new PDFDocument({ size: 'A4', margin: 50, bufferPages: true });
    const parts = []; doc.on('data', c => parts.push(c)); const done = new Promise(r => doc.on('end', r));
    try { const FR = path2.join(__dirname, 'DejaVuSans.ttf'), FB = path2.join(__dirname, 'DejaVuSans-Bold.ttf'); if (fs2.existsSync(FR)) doc.registerFont('Reg', FR); if (fs2.existsSync(FB)) doc.registerFont('Bold', FB); } catch (_) {}
    const F = (b) => { try { doc.font(b ? 'Bold' : 'Reg'); } catch (_) { doc.font(b ? 'Helvetica-Bold' : 'Helvetica'); } };
    F(true); doc.fontSize(16).fillColor('#0369a1').text('ŽBUKA Asistent — razgovor');
    F(false); doc.fontSize(11).fillColor('#334155').text(naslov); doc.moveDown(0.2);
    doc.fontSize(8.5).fillColor('#94a3b8').text('Izvezeno: ' + fmtDate(new Date(), { time: true })); doc.moveDown(0.7);
    doc.strokeColor('#e2e8f0').lineWidth(1).moveTo(50, doc.y).lineTo(545, doc.y).stroke(); doc.moveDown(0.7);
    for (const m of poruke) {
      const mine = m.role === 'user';
      if (doc.y > 740) doc.addPage();
      F(true); doc.fontSize(9.5).fillColor(mine ? '#0ea5e9' : '#7c3aed').text(mine ? 'TI' : 'ASISTENT');
      F(false); doc.fontSize(10.5).fillColor('#1e293b').text(String(m.content || '').slice(0, 6000), { lineGap: 1.5 });
      doc.moveDown(0.7);
    }
    const range = doc.bufferedPageRange();
    for (let i = 0; i < range.count; i++) { doc.switchToPage(range.start + i); F(false); doc.fontSize(7.5).fillColor('#94a3b8').text('ŽBUKA Čakarić d.o.o. · zbuka.hr · str. ' + (i + 1) + '/' + range.count, 50, 802, { align: 'center', width: 495, lineBreak: false }); }
    doc.end(); await done;
    const buf = Buffer.concat(parts);
    const fname = 'razgovor_' + naslov.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 40) + '.pdf';
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="' + fname + '"');
    res.send(buf);
  } catch (e) { console.error('[razgovor pdf]', e && e.message); res.status(500).json({ error: 'Greška pri izradi PDF-a.' }); }
});

// ⭐ v135.7.502.20.151 (Ivan, 06.06.2026): MEMORIJA — pregled/dodavanje/brisanje/toggle (kontrola učenja).
//   Poslovođa vidi zajedničko (struka) + svoje osobne; uređuje SAMO svoje osobne. Direktor kurira i zajedničko.
app.get('/api/asistent/memorija', auth, async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT id, korisnik_id, kategorija, sadrzaj, aktivan, status, created_at
       FROM asistent_memorija WHERE korisnik_id IS NULL OR korisnik_id = $1
       ORDER BY (korisnik_id IS NULL) DESC, created_at DESC`, [req.user.id]);
    const jeDirektor = req.user.role === 'direktor';
    const memorije = r.rows.map(x => ({
      id: x.id, kategorija: x.kategorija, sadrzaj: x.sadrzaj, aktivan: x.aktivan,
      status: x.status || 'aktivna',
      zajednicko: x.korisnik_id === null,
      uredivo: (x.korisnik_id === req.user.id) || (x.korisnik_id === null && jeDirektor)
    })).filter(m => !(m.status === 'prijedlog' && !m.uredivo)); // prijedloge vidi samo onaj tko ih može odobriti
    res.json({ memorije });
  } catch (e) { console.error('[memorija get]', e); res.status(500).json({ error: 'Greška' }); }
});
