// ═══ v135.7.502.20.208 (Ivan, 07.06.2026): FAZA 2 — AUTO-MEMORIJA (prijedlog → odobrenje) ═══
//   Jeftin model izvuče kandidate iz razgovora; spremaju se kao 'prijedlog' (aktivan=false → NE ulaze u prompt)
//   dok ih korisnik ne odobri. Tako asistent "uči iz razgovora" bez zatrpavanja memorije i bez auto-primjene.
async function _asistentIzluciPrijedloge(poruke) {
  const transkript = (poruke || [])
    .filter(m => m && (m.role === 'user' || m.role === 'assistant') && m.content)
    .slice(-30)
    .map(m => (m.role === 'user' ? 'KORISNIK: ' : 'ASISTENT: ') + (typeof m.content === 'string' ? m.content : ''))
    .join('\n').slice(0, 12000);
  if (!transkript.trim()) return [];
  const sys = [
    'Iz razgovora izvuci SAMO trajne, korisne činjenice vrijedne pamćenja za buduće razgovore',
    '(o korisniku, njegovoj firmi, projektima, načinu rada ili preferencijama).',
    'PRAVILA: Izvuci samo trajno korisno (npr. "Voli kratke, izravne odgovore", "Gradilište HBOR ima kulir fasadu", "Koristi Röfix ETICS sustav").',
    'NE izvlači: jednokratna pitanja, općepoznate činjenice, privremene stvari, ni očito.',
    'Kratko i konkretno (max ~120 znakova po stavci), najviše 6 stavki.',
    'Kategorija: "osobno" (preferencija/kontekst korisnika) ili "struka" (znanje o poslu/firmi/projektu).',
    'Ako nema ničeg vrijednog pamćenja, vrati prazan niz [].',
    'Vrati ISKLJUČIVO JSON niz: [{"sadrzaj":"...","kategorija":"osobno|struka"}] — bez ikakvog drugog teksta.'
  ].join(' ');
  const out = await _callClaudeStream(
    { model: ASISTENT_MODEL_BRZI, max_tokens: 800, system: sys,
      messages: [{ role: 'user', content: 'Razgovor:\n' + transkript + '\n\nPrijedlozi za pamćenje (JSON niz):' }] },
    () => {}, { timeoutMs: 60000 });
  if (!out.ok) return [];
  let txt = (out.blocks || []).filter(b => b && b.type === 'text').map(b => b.text).join('\n').trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  const a = txt.indexOf('['), b = txt.lastIndexOf(']');
  if (a === -1 || b === -1 || b <= a) return [];
  let arr; try { arr = JSON.parse(txt.slice(a, b + 1)); } catch (_) { return []; }
  if (!Array.isArray(arr)) return [];
  return arr
    .filter(x => x && typeof x.sadrzaj === 'string' && x.sadrzaj.trim())
    .map(x => ({ sadrzaj: x.sadrzaj.trim().slice(0, 200), kategorija: (x.kategorija === 'struka' ? 'struka' : 'osobno') }))
    .slice(0, 6);
}

// Analiziraj razgovor → spremi kandidate kao 'prijedlog' (čekaju odobrenje). Izvor: razgovor iz baze ILI poruke iz tijela.
app.post('/api/asistent/memorija/predlozi', auth, async (req, res) => {
  try {
    req.user.ovlasti = (await _loadOvlasti(req.user.id)).ovlasti;
    if (!hasPerm(req.user.role, req.user.ovlasti, 'asistent')) return res.status(403).json({ error: 'AI asistent nije omogućen.' });
    const daily = await _aiDailyCheck(req.user.id);
    if (!daily.ok) return res.status(429).json({ error: `Dosegnuta dnevna granica AI upita (${daily.used}/${daily.quota}).` });
    let poruke = [];
    const rid = (req.body && req.body.razgovor_id) ? (parseInt(req.body.razgovor_id, 10) || null) : null;
    if (rid) {
      const rr = await pool.query('SELECT poruke FROM asistent_razgovori WHERE id=$1 AND korisnik_id=$2', [rid, req.user.id]);
      if (rr.rows.length && Array.isArray(rr.rows[0].poruke)) poruke = rr.rows[0].poruke;
    }
    if (!poruke.length && req.body && Array.isArray(req.body.messages)) poruke = _asistentSlimPoruke(req.body.messages);
    if (poruke.length < 2) return res.json({ prijedlozi: [], poruka: 'Premalo razgovora za analizu.' });

    const kandidati = await _asistentIzluciPrijedloge(poruke);
    _aiDailyIncrement(req.user.id).catch(() => {});
    if (!kandidati.length) return res.json({ prijedlozi: [], poruka: 'Nisam našao ništa novo vrijedno pamćenja.' });

    const post = await pool.query('SELECT lower(sadrzaj) AS s FROM asistent_memorija WHERE korisnik_id IS NULL OR korisnik_id=$1', [req.user.id]);
    const postoje = new Set(post.rows.map(r => r.s));
    const jeDirektor = req.user.role === 'direktor';
    const dodani = [];
    for (const k of kandidati) {
      const norm = k.sadrzaj.toLowerCase();
      if (postoje.has(norm)) continue;
      if ([...postoje].some(p => p && (p.includes(norm) || norm.includes(p)))) continue;   // grubi dedupe (sadržano)
      const kategorija = jeDirektor ? k.kategorija : 'osobno';
      const korisnikId = (kategorija === 'struka' && jeDirektor) ? null : req.user.id;
      const ins = await pool.query(
        `INSERT INTO asistent_memorija(korisnik_id, kategorija, sadrzaj, izvor, aktivan, status)
         VALUES($1,$2,$3,'auto',false,'prijedlog') RETURNING id`, [korisnikId, kategorija, k.sadrzaj]);
      postoje.add(norm);
      dodani.push({ id: ins.rows[0].id, sadrzaj: k.sadrzaj, kategorija, zajednicko: korisnikId === null });
    }
    res.json({ prijedlozi: dodani, poruka: dodani.length ? '' : 'Sve što sam našao već je u memoriji.' });
  } catch (e) { console.error('[memorija predlozi]', e && e.message); res.status(500).json({ error: 'Greška pri analizi.' }); }
});

// Odobri prijedlog → postaje aktivna memorija (ulazi u prompt). Vlasništvo kao kod brisanja.
