// ═══ v135.7.502.20.209 (Ivan, 07.06.2026): FAZA 3 — "AI predloži znanje" (iz razgovora → baza znanja) ═══
//   Vraća kandidate (naslov+sadrzaj+kategorija), NE sprema ih — korisnik odobri u 📚 modalu (➕) pa idu kroz POST /api/znanje.
async function _asistentIzluciZnanje(poruke) {
  const transkript = (poruke || [])
    .filter(m => m && (m.role === 'user' || m.role === 'assistant') && m.content)
    .slice(-30)
    .map(m => (m.role === 'user' ? 'KORISNIK: ' : 'ASISTENT: ') + (typeof m.content === 'string' ? m.content : ''))
    .join('\n').slice(0, 14000);
  if (!transkript.trim()) return [];
  const sys = [
    'Iz razgovora izvuci do 4 KORISNA, TRAJNA znanja vrijedna dodavanja u internu bazu znanja tvrtke',
    '(tehnička uputa, specifikacija, postupak, pravilo, zakonska odredba, podaci o projektu/proizvodu).',
    'Svaka stavka: kratak jasan "naslov" + "sadrzaj" (može biti dulji, do ~700 znakova — sažmi bit, zadrži ključne brojke/uvjete).',
    'NE izvlači: jednokratna pitanja, chit-chat, općepoznato, ni povjerljive financijske brojke (plaće, marže).',
    'Ako nema ničeg vrijednog, vrati prazan niz [].',
    'Kategorija jedna od: "zakon","tehnika","postupak","proizvod","opce".',
    'Vrati ISKLJUČIVO JSON niz: [{"naslov":"...","sadrzaj":"...","kategorija":"..."}] — bez ikakvog drugog teksta.'
  ].join(' ');
  const out = await _callClaudeStream(
    { model: ASISTENT_MODEL_BRZI, max_tokens: 1500, system: sys,
      messages: [{ role: 'user', content: 'Razgovor:\n' + transkript + '\n\nPrijedlozi znanja (JSON niz):' }] },
    () => {}, { timeoutMs: 70000 });
  if (!out.ok) return [];
  let txt = (out.blocks || []).filter(b => b && b.type === 'text').map(b => b.text).join('\n').trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  const a = txt.indexOf('['), b = txt.lastIndexOf(']');
  if (a === -1 || b === -1 || b <= a) return [];
  let arr; try { arr = JSON.parse(txt.slice(a, b + 1)); } catch (_) { return []; }
  if (!Array.isArray(arr)) return [];
  const KAT = ['zakon', 'tehnika', 'postupak', 'proizvod', 'opce'];
  return arr
    .filter(x => x && typeof x.sadrzaj === 'string' && x.sadrzaj.trim().length >= 10)
    .map(x => ({
      naslov: String(x.naslov || '').trim().slice(0, 200),
      sadrzaj: x.sadrzaj.trim().slice(0, 1200),
      kategorija: KAT.indexOf(String(x.kategorija || '').toLowerCase()) !== -1 ? String(x.kategorija).toLowerCase() : 'opce'
    }))
    .slice(0, 4);
}
app.post('/api/asistent/znanje/predlozi', auth, async (req, res) => {
  try {
    req.user.ovlasti = (await _loadOvlasti(req.user.id)).ovlasti;
    if (!hasPerm(req.user.role, req.user.ovlasti, 'asistent')) return res.status(403).json({ error: 'AI asistent nije omogućen.' });
    const daily = await _aiDailyCheck(req.user.id);
    if (!daily.ok) return res.status(429).json({ error: `Dosegnuta dnevna granica AI upita (${daily.used}/${daily.quota}).` });
    let poruke = [];
    const rid = (req.body && req.body.razgovor_id) ? (parseInt(req.body.razgovor_id, 10) || null) : null;
    if (rid) {
      const rr = await pool.query('SELECT poruke FROM asistent_razgovori WHERE id=$1 AND korisnik_id=$2', [rid, req.user.id]);
      if (rr.rows.length && Array.isArray(rr.rows[0].poruke)) poruke = rr.rows[0].poruke;
    }
    if (!poruke.length && req.body && Array.isArray(req.body.messages)) poruke = _asistentSlimPoruke(req.body.messages);
    if (poruke.length < 2) return res.json({ prijedlozi: [], poruka: 'Premalo razgovora za analizu.' });
    const kandidati = await _asistentIzluciZnanje(poruke);
    _aiDailyIncrement(req.user.id).catch(() => {});
    if (!kandidati.length) return res.json({ prijedlozi: [], poruka: 'Nisam našao ništa novo za bazu znanja.' });
    const post = await pool.query("SELECT DISTINCT lower(naslov) AS n FROM znanje WHERE naslov <> ''");
    const naslovi = new Set(post.rows.map(r => r.n));
    const filt = kandidati.filter(k => !k.naslov || !naslovi.has(k.naslov.toLowerCase()));
    res.json({ prijedlozi: filt, poruka: filt.length ? '' : 'Sve što sam našao već je u bazi znanja.' });
  } catch (e) { console.error('[znanje predlozi]', e && e.message); res.status(500).json({ error: 'Greška pri analizi.' }); }
});

// ═══ v135.7.502.20.211 (Ivan, 08.06.2026): AI LOGOVI — direktor vidi razgovore i korištenje SVIH korisnika ═══
//   Strogo direktor-only (privatnost). Popis svih niti + sažetak po korisniku + uvid u pojedini razgovor.
app.get('/api/asistent/admin/razgovori', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const LIMIT = 100;
    const korisnikId = req.query.korisnik_id ? (parseInt(req.query.korisnik_id, 10) || null) : null;
    const before = req.query.before ? new Date(req.query.before) : null;
    const prviPut = !before;   // sažetak (GROUP BY svih) računamo samo na prvoj stranici
    const uvjeti = [], par = [];
    if (korisnikId) { par.push(korisnikId); uvjeti.push(`ar.korisnik_id = $${par.length}`); }
    if (before && !isNaN(before.getTime())) { par.push(before.toISOString()); uvjeti.push(`ar.updated_at < $${par.length}`); }
    const where = uvjeti.length ? ('WHERE ' + uvjeti.join(' AND ')) : '';
    par.push(LIMIT + 1);   // +1 da znamo ima li još (paginacija)
    const r = await pool.query(
      `SELECT ar.id, ar.korisnik_id, ar.naslov, ar.status, ar.updated_at, ar.created_at,
              jsonb_array_length(ar.poruke) AS broj,
              COALESCE(rd.ime,'') AS ime, COALESCE(rd.prezime,'') AS prezime, rd.role AS role
       FROM asistent_razgovori ar
       LEFT JOIN radnici rd ON rd.id = ar.korisnik_id
       ${where}
       ORDER BY ar.updated_at DESC LIMIT $${par.length}`, par);
    const ima_jos = r.rows.length > LIMIT;
    const rows = ima_jos ? r.rows.slice(0, LIMIT) : r.rows;
    const razgovori = rows.map(x => ({
      id: x.id, korisnik_id: x.korisnik_id,
      korisnik: ((x.ime || '') + ' ' + (x.prezime || '')).trim() || ('#' + x.korisnik_id),
      role: x.role || '', naslov: String(x.naslov || 'Razgovor'),
      status: x.status || 'idle', broj: Number(x.broj || 0),
      updated_at: x.updated_at, created_at: x.created_at
    }));
    let sazetak = null;
    if (prviPut) {
      // ⭐ v135.7.502.20.212: točan ukupni sažetak po korisniku (GROUP BY svih razgovora, ne samo učitanih).
      const s = await pool.query(
        `SELECT ar.korisnik_id, COALESCE(rd.ime,'') AS ime, COALESCE(rd.prezime,'') AS prezime, rd.role AS role,
                COUNT(*)::int AS razgovora, COALESCE(SUM(jsonb_array_length(ar.poruke)),0)::int AS poruka, MAX(ar.updated_at) AS zadnje
         FROM asistent_razgovori ar LEFT JOIN radnici rd ON rd.id=ar.korisnik_id
         GROUP BY ar.korisnik_id, rd.ime, rd.prezime, rd.role
         ORDER BY MAX(ar.updated_at) DESC`);
      sazetak = s.rows.map(x => ({
        korisnik_id: x.korisnik_id,
        korisnik: ((x.ime || '') + ' ' + (x.prezime || '')).trim() || ('#' + x.korisnik_id),
        role: x.role || '', razgovora: x.razgovora, poruka: x.poruka, zadnje: x.zadnje
      }));
    }
    res.json({ razgovori, sazetak, ima_jos });
  } catch (e) { console.error('[admin razgovori]', e && e.message); res.status(500).json({ error: 'Greška.' }); }
});
app.get('/api/asistent/admin/razgovor/:id', auth, async (req, res) => {
  if (req.user.role !== 'direktor') return res.status(403).json({ error: 'Samo direktor.' });
  try {
    const r = await pool.query(
      `SELECT ar.id, ar.naslov, ar.poruke, ar.status, ar.updated_at,
              COALESCE(rd.ime,'') AS ime, COALESCE(rd.prezime,'') AS prezime
       FROM asistent_razgovori ar LEFT JOIN radnici rd ON rd.id=ar.korisnik_id
       WHERE ar.id=$1`, [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ error: 'Razgovor nije pronađen.' });
    const x = r.rows[0];
    // ⭐ v135.7.502.20.212: privatnost — zabilježi da je direktor pregledao tuđi AI razgovor (GDPR/trag).
    auditLog(req, { action: 'ai_razgovor_pregledan', target_type: 'asistent_razgovor', details: { razgovor_id: x.id, korisnik: ((x.ime || '') + ' ' + (x.prezime || '')).trim() }, severity: 'info' }).catch(() => {});
    res.json({ id: x.id, naslov: String(x.naslov || 'Razgovor'),
      korisnik: ((x.ime || '') + ' ' + (x.prezime || '')).trim(),
      poruke: Array.isArray(x.poruke) ? x.poruke : [], status: x.status || 'idle', updated_at: x.updated_at });
  } catch (e) { console.error('[admin razgovor]', e && e.message); res.status(500).json({ error: 'Greška.' }); }
});

