// ⭐ v701/v703 (Ivan): BACKFILL embeddinga dnevnika (semantička pretraga). Radi U POZADINI — request se ODMAH vrati.
//   ?force=1 = obriši pa embeddaj sve iznova. Napredak: /api/asistent/embed-dnevnik-status. Resumable ako padne.
let _dnvEmbState = { running: false, done: 0, fail: 0, started: 0 };
app.get('/api/asistent/embed-dnevnik', async (req, res) => {
  if (!checkAndAuditInitSecret(req, res, '/api/asistent/embed-dnevnik')) return;
  if (!process.env.EMBED_API_KEY) return res.status(400).json({ error: 'EMBED_API_KEY nije postavljen u okolini (env).' });
  try { await pool.query('SELECT 1 FROM dnevnik_embed LIMIT 1'); }
  catch (e) { return res.status(400).json({ error: 'Tablica dnevnik_embed ne postoji — pokreni /api/init-db prvo.', detalj: e && e.message }); }
  if (_dnvEmbState.running) return res.json({ ok: true, vec_radi: true, poruka: 'Backfill vec radi u pozadini. Napredak: /api/asistent/embed-dnevnik-status?key=...' });
  const force = req.query.force === '1';
  _dnvEmbState = { running: true, done: 0, fail: 0, started: Date.now() };
  (async () => {
    try {
      if (force) { await pool.query('DELETE FROM dnevnik_embed').catch(() => {}); }
      while (true) {
        const rows = (await pool.query(`SELECT d.gradiliste_id, d.datum, string_agg(DISTINCT NULLIF(TRIM(d.komentar),''), ' \u2022 ') AS opis
          FROM dnevnik d WHERE NOT EXISTS (SELECT 1 FROM dnevnik_embed e WHERE e.gradiliste_id=d.gradiliste_id AND e.datum=d.datum)
          GROUP BY d.gradiliste_id, d.datum HAVING string_agg(DISTINCT NULLIF(TRIM(d.komentar),''), ' \u2022 ') IS NOT NULL
          ORDER BY d.datum DESC LIMIT 40`)).rows;
        if (!rows.length) break;
        const texts = rows.map(r => String(r.opis || '').slice(0, 2000));
        let vecs = await _embedTexts(texts);
        if (vecs.every(v => !v)) { await new Promise(r => setTimeout(r, 15000)); vecs = await _embedTexts(texts); }
        let anyUpsert = false;
        for (let k = 0; k < rows.length; k++) {
          if (vecs[k]) { try { await pool.query(`INSERT INTO dnevnik_embed(gradiliste_id, datum, opis, embedding, updated_at) VALUES($1,$2,$3,$4::vector,NOW()) ON CONFLICT (gradiliste_id, datum) DO UPDATE SET opis=EXCLUDED.opis, embedding=EXCLUDED.embedding, updated_at=NOW()`, [rows[k].gradiliste_id, rows[k].datum, texts[k], _vecLiteral(vecs[k])]); _dnvEmbState.done++; anyUpsert = true; } catch (_) { _dnvEmbState.fail++; } }
          else _dnvEmbState.fail++;
        }
        if (!anyUpsert) break;
        await new Promise(r => setTimeout(r, 1500));
      }
    } catch (e) { console.error('[embed-dnevnik bg]', e && e.message); }
    _dnvEmbState.running = false;
  })();
  res.json({ ok: true, pokrenuto: true, poruka: 'Backfill je POKRENUT u pozadini. Provjeri napredak (osvjezavaj stranicu): /api/asistent/embed-dnevnik-status?key=' + (req.query.key || '...') });
});
// ⭐ v703 (Ivan): STATUS backfilla dnevnika — koliko embeddano / preostalo / je li gotovo
app.get('/api/asistent/embed-dnevnik-status', async (req, res) => {
  if (!checkAndAuditInitSecret(req, res, '/api/asistent/embed-dnevnik-status')) return;
  try {
    let uk = 0, emb = 0;
    try { uk = parseInt((await pool.query(`SELECT COUNT(*) c FROM (SELECT gradiliste_id, datum FROM dnevnik GROUP BY gradiliste_id, datum HAVING string_agg(DISTINCT NULLIF(TRIM(komentar),''), ' \u2022 ') IS NOT NULL) t`)).rows[0].c) || 0; } catch (_) {}
    try { emb = parseInt((await pool.query(`SELECT COUNT(*) c FROM dnevnik_embed WHERE embedding IS NOT NULL`)).rows[0].c) || 0; } catch (e) { return res.status(400).json({ error: 'dnevnik_embed ne postoji — pokreni /api/init-db.', detalj: e && e.message }); }
    const preostalo = Math.max(0, uk - emb);
    const postotak = uk ? Math.round(emb / uk * 100) : 100;
    const gotovo = preostalo === 0 && uk > 0;
    res.json({ ukupno_dana_s_opisom: uk, embeddano: emb, preostalo, napredak: postotak + '%', radi_u_pozadini: _dnvEmbState.running, u_ovoj_sesiji: { uspjelo: _dnvEmbState.done, neuspjelo: _dnvEmbState.fail }, gotovo,
      poruka: gotovo ? '✅ GOTOVO - svi dani embeddani, semanticka pretraga je spremna.' : _dnvEmbState.running ? ('⏳ Radi u pozadini... ' + emb + '/' + uk + ' (' + postotak + '%). Osvjezi za koju minutu.') : (uk === 0 ? 'Nema dnevnika s opisom za embeddati.' : ('⏸ Stalo na ' + emb + '/' + uk + ' (' + postotak + '%). Pokreni /api/asistent/embed-dnevnik ponovno da nastavi.')) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// v708 (Ivan): BACKFILL VISION CAPTIONA - AI opise slike svakog dana s fotkama (pozadina, resumable). ?force=1 = sve iznova.
let _capState = { running: false, done: 0, fail: 0 };
