// ⭐ v135.7.502.20.219 (Ivan, 08.06.2026): RETENTION za asistent_dopisi (P0-2 iz audita).
//   Razlog: AI dopisi (PDF base64) rastu neograničeno → najveći operativni teret baze. Brišemo starije od
//   ASISTENT_DOPISI_RETENTION_DANA (default 90). 0/negativan = isključeno. Dnevni node-cron 03:30 Zagreb +
//   1×/24h setInterval sigurnosna mreža (Railway restart) + prvi run 10 min nakon starta. Idempotentno, nedestruktivno
//   za svježe dopise. (Razgovori se NE diraju — to je opt-in zaseban posao.)
async function asistentDopisiRetention() {
  const dana = parseInt(process.env.ASISTENT_DOPISI_RETENTION_DANA || '90', 10);
  if (!(dana > 0)) return;
  try {
    const r = await pool.query(`DELETE FROM asistent_dopisi WHERE created_at < NOW() - make_interval(days => $1)`, [dana]);
    if (r.rowCount > 0) console.log(`[retention] asistent_dopisi: obrisano ${r.rowCount} starijih od ${dana} dana`);
  } catch (e) { console.warn('[retention asistent_dopisi] fail:', e.message); _sentryCapture && _sentryCapture(e, { source: 'retention_asistent_dopisi' }); }
}
if (typeof _nodeCron !== 'undefined' && _nodeCron && _nodeCron.schedule) {
  _nodeCron.schedule('30 3 * * *', () => { asistentDopisiRetention(); }, { timezone: 'Europe/Zagreb' });
  console.log('[node-cron] asistent_dopisi retention scheduliran: 03:30 Europe/Zagreb');
}
setInterval(asistentDopisiRetention, 24 * 60 * 60 * 1000);
setTimeout(asistentDopisiRetention, 10 * 60 * 1000);

// ⭐ v661 (Ivan, FAZA 7): RETENCIJA RAZGOVORA — briši niti neaktivne dulje od ASISTENT_RAZGOVORI_RETENTION_DANA
//   (default 365; 0/negativan = isključeno). Po updated_at (aktivne niti ostaju). Prvo prilozi tih niti, pa niti,
//   pa počisti sve preostale orphan priloge (razgovor više ne postoji). Cron 03:40 (offset od dopisi 03:30).
async function asistentRazgovoriRetention() {
  const dana = parseInt(process.env.ASISTENT_RAZGOVORI_RETENTION_DANA || '365', 10);
  try {
    if (dana > 0) {
      await pool.query(`DELETE FROM asistent_prilozi WHERE razgovor_id IN (SELECT id FROM asistent_razgovori WHERE updated_at < NOW() - make_interval(days => $1))`, [dana]).catch(() => {});
      const r = await pool.query(`DELETE FROM asistent_razgovori WHERE updated_at < NOW() - make_interval(days => $1)`, [dana]);
      if (r.rowCount > 0) console.log(`[retention] asistent_razgovori: obrisano ${r.rowCount} niti starijih od ${dana} dana`);
    }
    // uvijek počisti orphan priloge (nit obrisana ručno/retencijom) — jeftino, drži bazu čistom
    await pool.query(`DELETE FROM asistent_prilozi WHERE razgovor_id NOT IN (SELECT id FROM asistent_razgovori)`).catch(() => {});
  } catch (e) { console.warn('[retention razgovori] fail:', e.message); _sentryCapture && _sentryCapture(e, { source: 'retention_asistent_razgovori' }); }
}
if (typeof _nodeCron !== 'undefined' && _nodeCron && _nodeCron.schedule) {
  _nodeCron.schedule('40 3 * * *', () => { asistentRazgovoriRetention(); }, { timezone: 'Europe/Zagreb' });
  console.log('[node-cron] asistent_razgovori retention scheduliran: 03:40 Europe/Zagreb');
}
setInterval(asistentRazgovoriRetention, 24 * 60 * 60 * 1000);
setTimeout(asistentRazgovoriRetention, 12 * 60 * 1000);

// ⭐ v666 (Ivan): AUTO-OSVJEŽAVANJE ZAKONA S POVEZNICE — zakoni se mijenjaju, pa jednom mjesečno (1. u 04:00)
//   ponovno povučemo sve znanje-stavke čiji je izvor URL, re-chunkamo i re-embeddamo. ZNANJE_REFRESH=0 gasi.
async function znanjeAutoRefresh() {
  if (process.env.ZNANJE_REFRESH === '0') return;
  try {
    const rows = (await pool.query("SELECT DISTINCT naslov, izvor, kategorija FROM znanje WHERE izvor LIKE 'http%'")).rows;
    let osv = 0;
    for (const r of rows) {
      try {
        const text = await _fetchUrlText(r.izvor, { timeoutMs: 45000 });
        if (!text || text.length < 200) continue;
        const chunks = _chunkText(text, 1500).slice(0, 1500);
        const _c = await pool.connect();
        try {
          await _c.query('BEGIN');
          await _c.query('DELETE FROM znanje WHERE naslov=$1', [r.naslov]);
          for (const c of chunks) await _c.query('INSERT INTO znanje(naslov, sadrzaj, kategorija, izvor) VALUES($1,$2,$3,$4)', [r.naslov, c, r.kategorija || 'zakon', r.izvor]);
          await _c.query('COMMIT'); osv++;
        } catch (e) { try { await _c.query('ROLLBACK'); } catch (_) {} } finally { _c.release(); }
        await new Promise(res => setTimeout(res, 1500));
      } catch (e) { console.warn('[znanje refresh]', r.naslov, e && e.message); }
    }
    if (osv && process.env.EMBED_API_KEY) {
      for (let pass = 0; pass < 40; pass++) {
        const un = (await pool.query('SELECT id, naslov, sadrzaj FROM znanje WHERE embedding IS NULL ORDER BY id LIMIT 40')).rows;
        if (!un.length) break;
        const vecs = await _embedTexts(un.map(x => (x.naslov ? x.naslov + '\n' : '') + (x.sadrzaj || '')));
        if (vecs.every(v => !v)) break;
        for (let i = 0; i < un.length; i++) if (vecs[i]) await pool.query('UPDATE znanje SET embedding=$1::vector WHERE id=$2', [_vecLiteral(vecs[i]), un[i].id]);
      }
    }
    if (osv) console.log('[znanje refresh] osvježeno URL zakona:', osv);
  } catch (e) { console.warn('[znanje refresh] fail:', e && e.message); }
}
if (typeof _nodeCron !== 'undefined' && _nodeCron && _nodeCron.schedule) {
  _nodeCron.schedule('0 4 1 * *', () => { znanjeAutoRefresh(); }, { timezone: 'Europe/Zagreb' });
  console.log('[node-cron] znanje auto-refresh scheduliran: 1. u mjesecu 04:00 Europe/Zagreb');
}

// ⭐ v135.7.219: Ručni test endpoint za Memsurov push reminder
//   Use case: Ivan želi testirati da Memsur stvarno dobiva push, bez čekanja 18h.
//   Šalje TEST push direktno Memsuru (ako on ima subscription).
//   Vraća detaljan dijagnostički ispis što je rezultat.
app.post('/api/test/mems-push', auth, direktor, async (req, res) => {
  try {
    // Pronađi Memsura (poslovođa)
    const memsR = await pool.query(`
      SELECT id, ime, prezime FROM radnici 
      WHERE je_admin = true AND (role IS NULL OR role != 'direktor') AND aktivan = true
      LIMIT 1
    `);
    
    if (!memsR.rows.length) {
      return res.json({
        ok: false,
        razlog: 'Memsur nije pronađen u bazi (poslovođa s aktivnim statusom)',
        savjet: 'Provjeri da Memsur ima role!=direktor i aktivan=true'
      });
    }
    
    const mems = memsR.rows[0];
    
    // Provjeri ima li subscription u bazi
    const subsR = await pool.query(
      'SELECT id, created_at FROM push_subscriptions WHERE radnik_id = $1',
      [mems.id]
    );
    
    if (subsR.rows.length === 0) {
      return res.json({
        ok: false,
        razlog: `Memsur (${mems.ime} ${mems.prezime}, id=${mems.id}) nema niti jednu push subscription u bazi`,
        savjet: 'Memsur treba: 1) otvoriti aplikaciju na svom mobitelu, 2) ići u postavke push notifikacija, 3) dati permission. Ako je već dao, možda treba ponovno klikom na "Aktiviraj push" gumb.',
        memsur: { id: mems.id, ime: mems.ime, prezime: mems.prezime }
      });
    }
    
    // Pošalji test push
    const result = await sendPushToUser(
      mems.id,
      '🧪 TEST: Push notifikacija radi',
      `Test poslan ${new Date().toLocaleString('hr-HR')}. Ako vidiš ovo, push sustav za tebe radi ispravno.`,
      '/?tab=sih'
    );
    
    res.json({
      ok: result.sent > 0,
      memsur: { id: mems.id, ime: mems.ime, prezime: mems.prezime },
      subscription_count: subsR.rows.length,
      subscription_dates: subsR.rows.map(s => s.created_at),
      push_result: result,
      poruka: result.sent > 0 
        ? `✓ Test push poslat na ${result.sent} Memsurov(a) uređaj(a). Provjeri njegov mobitel.`
        : `✗ Push NIJE dostavljen. Razlog: ${result.reason}. ${result.failed > 0 ? `Neuspjelo: ${result.failed}` : ''}`
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});


