// ⭐ v502.3 (Ivan, 24.05.2026): DIAGNOSTIKA pojedinog backup-a
//   Use case: Ivan dobiva notifikaciju "backup neuspješan" ali ZIP postoji na QNAP-u.
//   Ovaj endpoint vraća detaljnu sliku: što je uspjelo, što nije, gdje je problem.
//   Tipični uzroci "neuspješan" notifikacije iako ZIP postoji:
//     1. DB upload uspio, ali QNAP nedostupan u trenutku verifikacije
//     2. SHA256 mismatch (vrlo rijetko)
//     3. B2 upload tajmaut (zahtjev se cancela > 60s)
//     4. Background task se logirao kao "error" jer je DB connection prekinut
app.get('/api/backup/diagnostic/:id', auth, direktor, async (req, res) => {
  const id = parseInt(req.params.id);
  if (!id || isNaN(id)) return res.status(400).json({ error: 'Neispravan ID' });
  try {
    const r = await pool.query(
      `SELECT id, created_at, filename, status, size_kb, napomena, sha256,
              COALESCE(qnap_uploaded, false) AS qnap_uploaded,
              COALESCE(qnap_verified, false) AS qnap_verified,
              COALESCE(b2_ok, false) AS b2_ok,
              verified_at
       FROM backup_log WHERE id=$1`,
      [id]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Backup ne postoji' });
    const b = r.rows[0];
    
    // ⭐ v502.4 (Ivan, 24.05.2026): Dohvati audit_log evente vezane za ovaj backup
    //   (npr. backup_auto_verify_fail koji se generira kao critical event nakon 
    //   download-fail-a, što stvara push notifikaciju "backup neuspješan")
    let audit_eventi = [];
    try {
      const aud = await pool.query(
        `SELECT action, severity, details, created_at 
         FROM audit_log 
         WHERE target_type='backup' AND target_id=$1 
         ORDER BY created_at DESC LIMIT 5`,
        [id]
      );
      audit_eventi = aud.rows;
    } catch (_) {}
    
    // Procjena statusa
    // ⭐ v502.4: status enum fix — backend zapisuje 'ok' a ne 'success'
    const uspjesni_statusi = ['ok', 'ok_no_b2', 'ok_b2_only', 'ok_no_qnap'];
    const isOk = uspjesni_statusi.includes(b.status);
    
    const diagnostika = {
      backup: b,
      audit_eventi,
      analiza: {
        zip_uspjesno_kreiran: b.size_kb > 0 && b.sha256 != null,
        qnap_upload_uspio: b.qnap_uploaded === true,
        qnap_verified: b.qnap_verified === true,
        b2_upload_uspio: b.b2_ok === true,
        razlog_neuspjeha: null,
        savjet: null
      }
    };
    
    if (b.status === 'error') {
      diagnostika.analiza.razlog_neuspjeha = b.napomena || 'Nepoznata greška';
      if (b.qnap_uploaded) {
        diagnostika.analiza.savjet = 'ZIP je na QNAP-u (qnap_uploaded=TRUE), ali zapis je markiran kao error. Provjeri napomenu i SHA-256 verifikaciju.';
      } else if (b.size_kb > 0) {
        diagnostika.analiza.savjet = 'ZIP je kreiran (size_kb>0) ali upload na QNAP nije uspio. Provjeri QNAP dostupnost.';
      } else {
        diagnostika.analiza.savjet = 'ZIP nije ni kreiran. Provjeri DB connection ili memorijski limit.';
      }
    } else if (b.status === 'running') {
      diagnostika.analiza.razlog_neuspjeha = 'Backup je zaglavljen u "running" statusu (server crash?)';
      diagnostika.analiza.savjet = 'Pokreni /api/backup/cleanup-stuck za reset.';
    } else if (isOk) {
      // Provjera auto-verify fail-a
      const verifyFail = audit_eventi.find(e => e.action === 'backup_auto_verify_fail');
      if (verifyFail) {
        try {
          const det = typeof verifyFail.details === 'string' ? JSON.parse(verifyFail.details) : verifyFail.details;
          diagnostika.analiza.razlog_neuspjeha = `Auto-verifikacija pala: ${det.reason || 'nepoznato'}`;
          diagnostika.analiza.savjet = 'ZIP postoji na QNAP-u i status je OK. Auto-verifikacija je pokušala skinuti ZIP s QNAP-a i validirati SHA-256, ali download je neuspio (vjerojatno QNAP nedostupan u tom trenutku). Ručno možeš pokrenuti /api/backup/verify-latest da provjeriš sada.';
        } catch (_) {
          diagnostika.analiza.razlog_neuspjeha = 'Auto-verifikacija neuspješna (vidi audit log)';
        }
      } else if (!b.qnap_uploaded && !b.b2_ok) {
        diagnostika.analiza.savjet = 'Backup status=OK ali nije uploadan ni na QNAP ni B2. Provjeri konfiguraciju.';
      } else if (!b.qnap_verified && b.qnap_uploaded) {
        diagnostika.analiza.savjet = 'Backup na QNAP-u ali nije verificiran. Pokreni /api/backup/verify-latest.';
      } else {
        diagnostika.analiza.savjet = 'Sve OK!';
      }
    }
    
    res.json(diagnostika);
  } catch(e) {
    console.error('GET /api/backup/diagnostic/:id', e);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.230: Cleanup zaglavljenih "running" zapisa
//   Use case: Backup je krenuo, server crash-ao prije završetka, "running" zapis ostane zauvijek.
//   Pokazuje se kao "U tijeku..." u povijesti, zbunjujući.
//   Ovaj endpoint markira sve "running" zapise starije od 30 min kao 'aborted'.
app.post('/api/backup/cleanup-stuck', auth, direktor, async (req, res) => {
  try {
    const r = await pool.query(`
      UPDATE backup_log 
      SET status = 'aborted', 
          napomena = COALESCE(napomena, '') || ' [auto-cleaned: server restart]'
      WHERE status = 'running' 
        AND created_at < NOW() - INTERVAL '30 minutes'
      RETURNING id, created_at, napomena
    `);
    console.log(`[backup-cleanup] markirao ${r.rows.length} zaglavljenih backup-a kao 'aborted'`);
    res.json({ 
      ok: true, 
      cleaned: r.rows.length,
      records: r.rows
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.146: Diagnostički endpoint za auto-backup scheduler status
//   Pokazuje trenutno Zagreb vrijeme, je li u prozoru, datum zadnjeg backup-a,
//   i kada bi se sljedeći trebao pokrenuti.
app.get('/api/backup/scheduler-status', auth, direktor, async (req, res) => {
  try {
    const now = new Date();
    const zagrebFmt = new Intl.DateTimeFormat('en-GB', { 
      timeZone: 'Europe/Zagreb',
      weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit', hour12: false
    });
    const parts = zagrebFmt.formatToParts(now);
    const dayName = parts.find(p => p.type === 'weekday')?.value;
    const hour = parseInt(parts.find(p => p.type === 'hour')?.value || '0', 10);
    const minute = parseInt(parts.find(p => p.type === 'minute')?.value || '0', 10);
    
    // ⭐ v135.7.230: Sinkronizirano s autoBackupCheck cron-om (v229: 22h+)
    const isWindowSunday = dayName === 'Sun' && hour >= 22;
    const isWindowMondayMorning = dayName === 'Mon' && hour < 9;
    const inWindow = isWindowSunday || isWindowMondayMorning;
    
    // Zadnji uspješan auto backup
    const lastAuto = await pool.query(
      "SELECT created_at, filename, size_kb, napomena FROM backup_log WHERE status IN ('ok','ok_no_b2','ok_b2_only','ok_no_qnap') AND napomena LIKE '%utomatski%' ORDER BY created_at DESC LIMIT 1"
    ).catch(() => ({ rows: [] }));
    
    // Zadnji bilo koji backup
    const lastAny = await pool.query(
      "SELECT created_at, filename, status, napomena FROM backup_log ORDER BY created_at DESC LIMIT 1"
    ).catch(() => ({ rows: [] }));
    
    let danaOdZadnjeg = null;
    if (lastAny.rows.length) {
      danaOdZadnjeg = (now - new Date(lastAny.rows[0].created_at)) / (1000 * 60 * 60 * 24);
    }
    
    res.json({
      sada_zagreb: zagrebFmt.format(now),
      sada_dan: dayName,
      sada_sat: hour,
      u_prozoru: inWindow,
      prozor_opis: 'Nedjelja 22:00-23:59 ILI Ponedjeljak 0:00-9:00 (Europe/Zagreb)',
      zadnji_auto_backup: lastAuto.rows[0] || null,
      zadnji_bilo_koji: lastAny.rows[0] || null,
      dana_od_zadnjeg: danaOdZadnjeg !== null ? Number(danaOdZadnjeg.toFixed(2)) : null,
      bi_li_se_sad_aktivirao: inWindow && (danaOdZadnjeg === null || danaOdZadnjeg >= 5),
      // ⭐ v135.7.149: Server startup time + uptime diagnostics
      server_startup: global._serverStartupTime || 'n/a',
      server_uptime_h: global._serverStartupTime 
        ? Number(((now - new Date(global._serverStartupTime)) / (1000*60*60)).toFixed(1))
        : null,
      napomena: 'Scheduler proverava svakih 30 min. Server uptime mora pokrivati barem 1 prozor tjedno.'
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.149: Force-trigger auto backup endpoint
//   Razlog: ako se prozor propusti (Railway hibernacija, deploy nakon nedjelje, itd),
//   direktor može manualno pokrenuti "auto" backup koji se loguje kao automatski.
//   Razlikuje se od /api/backup (ručni) jer:
//   - Ne traje napredak (background)
//   - Loguje se s napomenom "Automatski tjedni backup (manual trigger)"
//   - Poštuje 5-day check (ne overwrite ako je bilo manje od 5 dana)
app.post('/api/backup/force-auto', auth, direktor, async (req, res) => {
  try {
    // Provjeri 5-day check (osim ako force=true)
    const force = req.body?.force === true;
    if (!force) {
      const lastR = await pool.query(
        "SELECT created_at FROM backup_log WHERE status IN ('ok','ok_no_b2','ok_b2_only','ok_no_qnap') ORDER BY created_at DESC LIMIT 1"
      ).catch(() => ({ rows: [] }));
      
      if (lastR.rows.length > 0) {
        const lastDate = new Date(lastR.rows[0].created_at);
        const daysSince = (Date.now() - lastDate.getTime()) / (1000 * 60 * 60 * 24);
        if (daysSince < 5) {
          return res.status(400).json({ 
            error: `Zadnji backup je bio prije ${daysSince.toFixed(1)} dana (< 5). Pošalji 'force: true' ako želiš svakako.` 
          });
        }
      }
    }
    
    // Pokreni auto backup logiku ručno (kao da je scheduler tick-ao)
    // Bypass window check tako da pozovemo internal helper koji radi backup direktno
    const logR = await pool.query(
      "INSERT INTO backup_log(status, napomena) VALUES('running', 'Automatski tjedni backup (manualno pokrenut)') RETURNING id"
    );
    const logId = logR.rows[0].id;
    
    // Vrati response odmah, backup ide u pozadini
    res.json({ ok: true, log_id: logId, message: 'Auto-backup pokrenut u pozadini. Pratite napredak preko povijesti.' });
    
    // Background backup
    setImmediate(async () => {
      try {
        const result = await doBackup();  // postojeća helper funkcija koja radi pravi backup
        await pool.query(
          "UPDATE backup_log SET status='ok', filename=$1, size_kb=$2, sha256=$3 WHERE id=$4",
          [result.filename || 'auto-backup.zip', result.size_kb || 0, result.sha256 || null, logId]
        );
        console.log('[AutoBackup-manual] Backup uspješan:', result.filename);
      } catch(eBackup) {
        await pool.query(
          "UPDATE backup_log SET status='fail', napomena=napomena || ' · Greška: ' || $1 WHERE id=$2",
          [eBackup.message.slice(0, 500), logId]
        ).catch(()=>{});
        console.error('[AutoBackup-manual] Backup pao:', eBackup.message);
      }
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ── AUTOMATSKO ČIŠĆENJE foto_base64 CACHE-a ──────────────────────────────────
// foto_base64 je samo cache za brži prikaz — pravi podaci su na QNAP-u
// ⭐ v135.7.200: Pojednostavljena politika — 730 dana (2 godine) UNIFORMNO za sve foto kolone
//    Razlog za 730 dana: 
//      - Aktivna gradilišta traju ~6-18 mjeseci, garancija 24 mjeseca
//      - Memsur i Ivan najčešće gledaju zadnja 1-2 mjeseca (live posao)
//      - Stariji podaci se rijetko otvaraju → QNAP lazy load je dovoljan
//      - 730 dana = backup pokriva regulatorne potrebe (HR poslovne knjige 5 god → originalni QNAP)
//    Bez qnap_path: NIKAD ne briše (fallback ako QNAP nije bio dostupan pri uploadu)
setTimeout(async () => {
  const cleanFotoCache = async () => {
    try {
      const queries = [
        // ⭐ Sve glavne foto tabele — 730 dana (2 godine)
        `UPDATE materijal SET foto_base64 = NULL
         WHERE foto_base64 IS NOT NULL AND qnap_path IS NOT NULL
           AND created_at < NOW() - INTERVAL '730 days'`,
        `UPDATE dnevnik SET foto_base64 = NULL
         WHERE foto_base64 IS NOT NULL AND qnap_path IS NOT NULL
           AND created_at < NOW() - INTERVAL '730 days'`,
        `UPDATE uredaji SET foto_base64 = NULL
         WHERE foto_base64 IS NOT NULL AND qnap_path IS NOT NULL
           AND created_at < NOW() - INTERVAL '730 days'`,
        `UPDATE izmjera SET foto_base64 = NULL
         WHERE foto_base64 IS NOT NULL AND qnap_path IS NOT NULL
           AND created_at < NOW() - INTERVAL '730 days'`,
        `UPDATE smece SET foto_base64 = NULL
         WHERE foto_base64 IS NOT NULL AND qnap_path IS NOT NULL
           AND created_at < NOW() - INTERVAL '730 days'`,
        // ⭐ Login attempts — drop redove starije od 30 dana (last_attempt je kolona, ne created_at)
        `DELETE FROM login_attempts
         WHERE last_attempt < NOW() - INTERVAL '30 days'`,
        // ⭐ AI override telemetry — stariji od 180 dana
        `DELETE FROM ai_overrides
         WHERE created_at < NOW() - INTERVAL '180 days'`,
        // ⭐ Backup log — stariji od 90 dana (sami backup file-ovi su u QNAP-u, ovo je samo metadata)
        `DELETE FROM backup_log
         WHERE created_at < NOW() - INTERVAL '90 days'`,
        // NAPOMENA: nalozi_foto NEMA qnap_path fallback — ne briše se base64
      ];
      let total = 0;
      const stats = {};
      for (const q of queries) {
        const tableMatch = q.match(/(?:UPDATE|DELETE FROM)\s+(\w+)/i);
        const table = tableMatch ? tableMatch[1] : '?';
        const r = await pool.query(q).catch(e => {
          console.warn(`[Cache cleanup] ${table} fail:`, e.message);
          return { rowCount: 0 };
        });
        const cnt = r.rowCount || 0;
        total += cnt;
        if (cnt > 0) stats[table] = (stats[table] || 0) + cnt;
      }
      if (total > 0) {
        console.log(`[Cache cleanup] Obrisano ${total} redaka:`, stats);
      }
    } catch(e) { console.error('[Cache cleanup]', e.message); }
  };
  cleanFotoCache();
  // Ponavljaj svakih 24 sata
  setInterval(cleanFotoCache, 24 * 60 * 60 * 1000);
}, 5 * 60 * 1000);

// ════════════════════════════════════════════════════════════════════════════
// ═══ NAV[BE]: B2 MIGRATION CRON (QNAP → B2 postupno) ═══
// ⭐ v135.7.202: B2 MIGRATION CRON — postupna migracija starih slika QNAP → B2
//   Pokreće se 1× dnevno, 30 minuta nakon starta servera.
//   Migrira maksimalno 100 slika dnevno (ograničavanje opterećenja).
//   Strategija:
//     1. SELECT id, qnap_path FROM <table> WHERE qnap_path IS NOT NULL AND b2_path IS NULL LIMIT 100
//     2. Za svaku: fetch s QNAP-a → upload na B2 → UPDATE b2_path
//     3. Ako B2 fail → log, ne mijenja DB, pokušat će sutra opet
//
//   ZAŠTO: novi unosi automatski idu paralelno na B2 (kroz qnapUploadImage wrapper).
//   Ali stare slike (od prije v202) imaju samo qnap_path. Migration cron ih postupno 
//   prebacuje, bez pritiska na sustav.
//
//   Aktivira se SAMO ako je B2 enabled (env vars postavljene).
// ════════════════════════════════════════════════════════════════════════════
setTimeout(() => {
  if (!b2Enabled()) {
    console.log('[B2 migration] B2 nije omogućen, cron se neće pokretati');
    return;
  }
  
  const migrateBatch = async () => {
    try {
      const tablesAndCols = [
        { table: 'materijal', limit: 30 },
        { table: 'dnevnik', limit: 30 },
        { table: 'uredaji', limit: 20 },
        { table: 'izmjera', limit: 10 },
        { table: 'smece', limit: 10 },
        // ⭐ v502.20.9 (Ivan, 27.05.2026): fasada_reference dodan u FORWARD sync
        //   Reference uploadane dok je samo QNAP radio (prije v502.20.9) dobivaju 
        //   B2 backup automatski. Limit 15.
        { table: 'fasada_reference', limit: 15 },
        // ⭐ v502.20.10 (Ivan, 27.05.2026): + nalozi_foto + radnici_dokumenti
        //   Nalozi_foto - stari nalozi pre-v502.20.10 dobivaju B2 backup
        //   Radnici_dokumenti - PDF dokumenti radnika (osobne, ugovori, sanitarne)
        { table: 'nalozi_foto', limit: 20 },
        { table: 'radnici_dokumenti', limit: 10 },
        // ⭐ v502.20.14 (Ivan, 27.05.2026): servisi PDF računi
        { table: 'servisi', limit: 10 }
      ];
      
      let totalMigrated = 0;
      const stats = {};
      
      for (const { table, limit } of tablesAndCols) {
        try {
          // Provjeri ima li tablica b2_path kolonu (defenzivno)
          const colCheck = await pool.query(`
            SELECT column_name FROM information_schema.columns 
            WHERE table_name = $1 AND column_name = 'b2_path'
          `, [table]);
          if (!colCheck.rows.length) {
            console.warn(`[B2 migration] ${table} nema b2_path kolonu — preskačem`);
            continue;
          }
          
          // Dohvati 100 redaka koji imaju qnap_path ali nemaju b2_path
          const rows = await pool.query(`
            SELECT id, qnap_path FROM ${table}
            WHERE qnap_path IS NOT NULL AND b2_path IS NULL
            ORDER BY id ASC
            LIMIT $1
          `, [limit]);
          
          if (!rows.rows.length) continue;
          
          let migrated = 0;
          let qnapMissing = 0;  // brojač za stare slike koje više ne postoje na QNAP-u
          for (const row of rows.rows) {
            try {
              // ⭐ v135.7.210: Koristi brzi fetch (8s timeout) umjesto 15s
              const buf = await _qnapFastFetch(row.qnap_path, 8000);
              if (!buf) {
                // QNAP fetch fail — može biti timeout ili 404 (slika obrisana s NAS-a izvan app-a)
                // Provjerit ćemo je li 404 (file ne postoji) — ako da, čistimo qnap_path da migration ne pokušava ponovo
                qnapMissing++;
                if (qnapMissing >= 5) {
                  // Ako 5 zaredom fail-a, znači QNAP je nedostupan — prekini batch
                  console.warn(`[B2 migration] ${table}: QNAP nedostupan (5 fail-ova zaredom) — prekidam`);
                  break;
                }
                continue;
              }
              qnapMissing = 0;  // reset counter ako uspije
              
              // Upload na B2 (isti path kao na QNAP-u)
              const b2Path = await b2Upload(buf, row.qnap_path, 'image/jpeg');
              if (!b2Path) continue;
              
              // Upiši u DB
              await pool.query(`UPDATE ${table} SET b2_path=$1 WHERE id=$2`, [b2Path, row.id]);
              migrated++;
            } catch(e) {
              console.warn(`[B2 migration] ${table}:${row.id} fail:`, e.message);
            }
            
            // Mali delay između migracija (ne preopterećuj QNAP/B2)
            await new Promise(r => setTimeout(r, 200));
          }
          
          if (migrated > 0) {
            stats[table] = migrated;
            totalMigrated += migrated;
          }
        } catch(e) {
          console.warn(`[B2 migration] ${table} table error:`, e.message);
        }
      }
      
      if (totalMigrated > 0) {
        console.log(`[B2 migration] migrirano ukupno ${totalMigrated} slika:`, stats);
      } else {
        console.log('[B2 migration] nema slika za migrirati (sve već imaju b2_path ili nema qnap_path)');
      }
    } catch(e) {
      console.error('[B2 migration] cron error:', e.message);
    }
  };
  
  // ⭐ v135.7.211: Smanjeno 30→5 min — brže se vidi da cron radi
  //   Plus, izloženo i na ručnom endpointu /api/b2/migrate-now (samo direktor)
  global._b2MigrateBatch = migrateBatch;
  
  // Pokreni odmah jednom (5 min nakon starta)
  migrateBatch();
  // Ponavljaj svakih 24 sata
  setInterval(migrateBatch, 24 * 60 * 60 * 1000);
  
  // ⭐ v135.7.228: REVERSE MIGRATION CRON (B2 → QNAP)
  //   Use case: ako QNAP padne, novi unosi idu samo na B2 (qnap_path=NULL, b2_path=postoji).
  //   Kad QNAP vratiš, ovaj cron postupno čita s B2 i piše na QNAP, da slike budu na oba mjesta.
  //   
  //   Zašto: aplikacija trenutno radi i bez ovog (čita s B2 fallback), ali korisno je da 
  //   nakon outage-a sve bude "uravnoteženo". Daje mir znajući da je QNAP 100% sinkroniziran.
  //   
  //   Pokretanje: svakih 24 sata, ali NE pokreće se ako QNAP nije dostupan
  //   (provjera prije pokretanja). Ručno pokretanje: POST /api/b2/sync-to-qnap-now
  const reverseMigrateBatch = async () => {
    if (!process.env.QNAP_WEBDAV_URL) {
      console.log('[B2→QNAP migration] QNAP nije konfiguriran — preskačem');
      return;
    }
    if (_qnapCircuitOpen()) {
      console.log('[B2→QNAP migration] QNAP circuit otvoren (nedostupan) — preskačem');
      return;
    }
    
    try {
      const tablesAndCols = [
        { table: 'materijal', limit: 30 },
        { table: 'dnevnik', limit: 30 },
        { table: 'uredaji', limit: 20 },
        { table: 'izmjera', limit: 10 },
        { table: 'smece', limit: 10 },
        // ⭐ v502.20.9 (Ivan, 27.05.2026): fasada_reference u REVERSE sync
        //   Kad QNAP online, reference uploadane tijekom outage-a (b2_path postoji,
        //   qnap_path NULL ili rezerviran bez stvarne slike) → povuci iz B2 na QNAP.
        { table: 'fasada_reference', limit: 15 },
        // ⭐ v502.20.10 (Ivan, 27.05.2026): + nalozi_foto + radnici_dokumenti
        { table: 'nalozi_foto', limit: 20 },
        { table: 'radnici_dokumenti', limit: 10 },
        // ⭐ v502.20.14 (Ivan, 27.05.2026): servisi PDF računi
        { table: 'servisi', limit: 10 }
      ];
      
      let totalSynced = 0;
      const stats = {};
      
      for (const { table, limit } of tablesAndCols) {
        try {
          // Provjeri ima li tablica b2_path kolonu (defenzivno)
          const colCheck = await pool.query(`
            SELECT column_name FROM information_schema.columns 
            WHERE table_name = $1 AND column_name = 'b2_path'
          `, [table]);
          if (!colCheck.rows.length) {
            continue;
          }
          
          // Dohvati zapise s b2_path ali bez qnap_path (uploadeni dok je QNAP bio DOWN)
          const rows = await pool.query(`
            SELECT id, b2_path FROM ${table}
            WHERE b2_path IS NOT NULL AND qnap_path IS NULL
            ORDER BY id ASC
            LIMIT $1
          `, [limit]);
          
          if (!rows.rows.length) continue;
          
          let synced = 0;
          let qnapFails = 0;
          for (const row of rows.rows) {
            try {
              // Fetch s B2
              const buf = await b2FetchBuffer(row.b2_path, 15000);
              if (!buf) {
                console.warn(`[B2→QNAP migration] B2 fetch fail za ${table}:${row.id}`);
                continue;
              }
              
              // Upload na QNAP s istim path-om
              const ext = (row.b2_path.split('.').pop() || 'jpg').toLowerCase();
              const ctype = ext === 'mp4' ? 'video/mp4' 
                          : ext === 'png' ? 'image/png' 
                          : ext === 'pdf' ? 'application/pdf' 
                          : 'image/jpeg';
              
              // Direktno preko WebDAV (zaobiđemo qnapUploadImage da ne radi B2 dvostruko)
              const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
              const base = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
              const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
              const hdrs = { Authorization: `Basic ${auth64}` };
              
              // MKCOL parent folders
              const parts = row.b2_path.split('/').filter(Boolean);
              let current = base;
              for (let i = 0; i < parts.length - 1; i++) {
                current += '/' + parts[i];
                await fetch(`${baseUrl}${current}/`, { 
                  method: 'MKCOL', 
                  headers: hdrs,
                  signal: AbortSignal.timeout(3000)
                }).catch(() => {});
              }
              
              const encoded = row.b2_path.replace(/^\//, '').split('/').filter(Boolean).map(encodeURIComponent).join('/');
              const putRes = await fetch(`${baseUrl}${base}/${encoded}`, {
                method: 'PUT',
                headers: { ...hdrs, 'Content-Type': ctype },
                body: buf,
                signal: AbortSignal.timeout(30000)
              });
              
              if (putRes.ok || putRes.status === 201 || putRes.status === 204) {
                // Upiši qnap_path u DB (isti kao b2_path)
                await pool.query(`UPDATE ${table} SET qnap_path=$1 WHERE id=$2`, [row.b2_path, row.id]);
                synced++;
                qnapFails = 0;
              } else {
                qnapFails++;
                console.warn(`[B2→QNAP migration] QNAP PUT fail ${table}:${row.id} status=${putRes.status}`);
                if (qnapFails >= 3) {
                  // Ako 3 zaredom fail-a, QNAP vjerojatno opet pao — prekini batch
                  console.warn(`[B2→QNAP migration] ${table}: 3 QNAP fail-ova zaredom — prekidam`);
                  break;
                }
              }
            } catch(e) {
              console.warn(`[B2→QNAP migration] ${table}:${row.id} fail:`, e.message);
            }
            
            // Mali delay između migracija (ne preopterećuj QNAP)
            await new Promise(r => setTimeout(r, 200));
          }
          
          if (synced > 0) {
            stats[table] = synced;
            totalSynced += synced;
          }
        } catch(e) {
          console.warn(`[B2→QNAP migration] ${table} table error:`, e.message);
        }
      }
      
      if (totalSynced > 0) {
        console.log(`[B2→QNAP migration] sinkronizirano ukupno ${totalSynced} slika natrag na QNAP:`, stats);
      } else {
        console.log('[B2→QNAP migration] nema zapisa za sinkronizirati (qnap_path postoji za sve)');
      }
    } catch(e) {
      console.error('[B2→QNAP migration] cron error:', e.message);
    }
  };
  
  global._b2ReverseSyncBatch = reverseMigrateBatch;
  
  // Pokreni 7 minuta nakon starta (kasnije od B2 forward migracije da ne sudaraju)
  setTimeout(reverseMigrateBatch, 7 * 60 * 1000);
  // Ponavljaj svakih 24 sata
  setInterval(reverseMigrateBatch, 24 * 60 * 60 * 1000);
}, 5 * 60 * 1000);

// ⭐ v135.7.228: Ručno pokretanje B2→QNAP sinka (samo direktor)
//   Use case: QNAP se vratio nakon outage-a, Ivan želi odmah sinkronizirati B2 na QNAP
//   bez čekanja 24h ciklusa.
app.post('/api/b2/sync-to-qnap-now', auth, direktor, async (req, res) => {
  if (!process.env.QNAP_WEBDAV_URL) {
    return res.json({ ok: false, error: 'QNAP nije konfiguriran' });
  }
  if (!global._b2ReverseSyncBatch) {
    return res.json({ ok: false, error: 'Cron još nije pokrenut (čeka 5 min od starta)' });
  }
  
  try {
    // Brojanje pending-a prije pokretanja
    // ⭐ v502.20.9: + fasada_reference
    const stats = await pool.query(`
      SELECT 
        (SELECT COUNT(*) FROM materijal WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS materijal,
        (SELECT COUNT(*) FROM dnevnik WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS dnevnik,
        (SELECT COUNT(*) FROM uredaji WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS uredaji,
        (SELECT COUNT(*) FROM izmjera WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS izmjera,
        (SELECT COUNT(*) FROM smece WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS smece,
        (SELECT COUNT(*) FROM fasada_reference WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS reference,
        (SELECT COUNT(*) FROM nalozi_foto WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS nalozi,
        (SELECT COUNT(*) FROM radnici_dokumenti WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS hr_dokumenti,
        (SELECT COUNT(*) FROM servisi WHERE b2_path IS NOT NULL AND qnap_path IS NULL) AS servisi
    `).catch(() => ({ rows: [{}] }));
    
    const pendingTotal = Object.values(stats.rows[0]).reduce((s, v) => s + parseInt(v || 0), 0);
    
    // Pokreni u pozadini
    console.log(`[B2→QNAP sync-now] direktor pokrenuo ručno. Pending: ${pendingTotal}`);
    global._b2ReverseSyncBatch().catch(e => console.error('[sync-to-qnap-now]', e.message));
    
    res.json({
      ok: true,
      message: 'B2→QNAP sync pokrenut u pozadini. Provjeri Railway logove za napredak.',
      pending: stats.rows[0],
      pending_total: pendingTotal
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

// Health check — Railway monitoring i uptime provjera






// ═══ NAV[BE]: FASADA AI ENDPOINTI — glavni blok (rute i drugdje → grep "'/api/fasada") ═══
