app.post('/api/fasada/validacija-tocaka', auth, staff, aiRateLimit, async (req, res) => {
  try {
    const { slika_base64, reference, plohe, exif_json } = req.body;

    if (!slika_base64) return res.status(400).json({ error: 'Nedostaje slika' });
    if (!reference || typeof reference !== 'object') {
      return res.status(400).json({ error: 'Nedostaju reference' });
    }

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      return res.status(500).json({ error: 'ANTHROPIC_API_KEY nije postavljen' });
    }

    // Strip data URL prefix
    let cleanBase64 = slika_base64;
    let mediaType = 'image/jpeg';
    const m = slika_base64.match(/^data:(image\/[a-z]+);base64,(.+)$/);
    if (m) { mediaType = m[1]; cleanBase64 = m[2]; }

    if (cleanBase64.length > 7000000) {
      return res.status(400).json({ error: 'Slika prevelika (max ~5MB)' });
    }

    const imgW = (exif_json && exif_json.image_width) || null;
    const imgH = (exif_json && exif_json.image_height) || null;

    // Sastavi listu svih tocaka za validaciju
    const tockeZaValidaciju = [];

    if (reference.x_os && Array.isArray(reference.x_os.tocke_px) && reference.x_os.tocke_px.length === 2) {
      tockeZaValidaciju.push({
        id: 'ref_x_0', tip: 'ref', ime: '1. mjera (X) - prva tocka',
        ocekivano: 'donji rub fasade ili krajnji ugao mjere',
        pos: reference.x_os.tocke_px[0]
      });
      tockeZaValidaciju.push({
        id: 'ref_x_1', tip: 'ref', ime: '1. mjera (X) - druga tocka',
        ocekivano: 'donji rub fasade ili krajnji ugao mjere',
        pos: reference.x_os.tocke_px[1]
      });
    }
    if (reference.y_os && Array.isArray(reference.y_os.tocke_px) && reference.y_os.tocke_px.length === 2) {
      tockeZaValidaciju.push({
        id: 'ref_y_0', tip: 'ref', ime: '2. mjera (Y) - prva tocka',
        ocekivano: 'vertikalni rub ili ugao zgrade',
        pos: reference.y_os.tocke_px[0]
      });
      tockeZaValidaciju.push({
        id: 'ref_y_1', tip: 'ref', ime: '2. mjera (Y) - druga tocka',
        ocekivano: 'vertikalni rub ili ugao zgrade',
        pos: reference.y_os.tocke_px[1]
      });
    }
    if (reference.z_os && Array.isArray(reference.z_os.tocke_px) && reference.z_os.tocke_px.length === 2) {
      tockeZaValidaciju.push({
        id: 'ref_z_0', tip: 'ref', ime: '3. mjera (Z) - prva tocka',
        ocekivano: 'donji rub bocnog procelja ili rub dubinske mjere',
        pos: reference.z_os.tocke_px[0]
      });
      tockeZaValidaciju.push({
        id: 'ref_z_1', tip: 'ref', ime: '3. mjera (Z) - druga tocka',
        ocekivano: 'donji rub bocnog procelja ili rub dubinske mjere',
        pos: reference.z_os.tocke_px[1]
      });
    }
    if (reference.x_os_paralela && Array.isArray(reference.x_os_paralela.tocke_px)) {
      reference.x_os_paralela.tocke_px.forEach((p, i) => {
        tockeZaValidaciju.push({
          id: 'ref_xp_' + i, tip: 'ref', ime: 'X-paralela - tocka ' + (i+1),
          ocekivano: 'gornji rub iste fasade (paralelan s 1. mjerom)',
          pos: p
        });
      });
    }
    if (reference.z_os_paralela && Array.isArray(reference.z_os_paralela.tocke_px)) {
      reference.z_os_paralela.tocke_px.forEach((p, i) => {
        tockeZaValidaciju.push({
          id: 'ref_zp_' + i, tip: 'ref', ime: 'Z-paralela - tocka ' + (i+1),
          ocekivano: 'gornji rub bocnog procelja (paralelan s 3. mjerom)',
          pos: p
        });
      });
    }

    if (Array.isArray(plohe)) {
      plohe.forEach((pl) => {
        if (Array.isArray(pl.tocke_px)) {
          pl.tocke_px.forEach((p, i) => {
            tockeZaValidaciju.push({
              id: pl.id + '_t' + i, tip: 'ploha', ime: pl.id + ' - tocka ' + (i+1),
              ocekivano: 'kut ili rub plohe (gdje se mijenja smjer fasade)',
              pos: p
            });
          });
        }
      });
    }

    if (tockeZaValidaciju.length === 0) {
      return res.status(400).json({ error: 'Nema tocaka za validaciju' });
    }

    // Pripremi JSON listu tocaka za AI
    const tockeJSON = JSON.stringify(tockeZaValidaciju.map(t => ({
      id: t.id,
      ime: t.ime,
      ocekivano: t.ocekivano,
      pos_px: t.pos
    })), null, 2);

    const sistemskiPrompt = `Ti si ekspert za fotogrametriju. Tvoj zadatak: provjeri da li su korisnikove tocke TOCNO na rubovima fasade ili otvora.

Vraca SAMO valjan JSON, bez markdown blokova.`;

    const userPrompt = `Slika je ${imgW || '?'} × ${imgH || '?'} px. Korisnik je oznacio sljedece tocke koje ti trebas validirati:

${tockeJSON}

ZADATAK za svaku tocku:
1. Provjeri je li tocka TOCNO na ocekivanom mjestu (na rubu fasade, kutu, itd.)
2. Ako nije, predlozi gdje BI TREBALA biti (u istim px koordinatama)
3. Tolerancija: ako je tocka unutar ~5px od ruba, smatraj je VALJANOM

ODGOVORI s JSON-om u tocno ovom formatu:
{
  "ukupna_tocnost_proc": broj_0_do_100 (knjiga ukupne preciznosti),
  "validacije": [
    {
      "id": "ref_x_0",  // isto kao u inputu
      "valjana": true | false,
      "razlog": "kratki opis ako nije valjana, npr. '8px od donjeg ruba'",
      "predlozeno": [x, y] | null  // ako se moze popraviti, inace null
    },
    ... (jedna stavka po tocki iz inputa)
  ],
  "preporuka": "kratki tekst za korisnika (max 200 znakova)"
}

VAZNO:
- Tocke "predlozeno" MORAJU biti u ORIGINAL koordinatama slike (ne 0-1 normirane)
- Ako je tocka jasno krivo (npr. usred fasade umjesto na rubu), valjana=false bez predlozeno
- Ako je tocka blizu (5-30px), predlozi popravak
- Budi konzervativan: bolje da kazes "valjana=true" za marginalne, nego nervirati korisnika`;

    // AI poziv
    // FUTURE-PROOF-2030: [ANTHROPIC-API] Anthropic Claude API integracija (FASADA AI module)
    //   PROVJERI 2× godišnje:
    //     1. docs.anthropic.com/en/docs/about-claude/models — koji modeli su deprecated
    //     2. anthropic-version header — trenutno '2023-06-01', mijenja se rijetko
    //     3. Pricing — na docs.anthropic.com/en/docs/about-claude/pricing
    //     4. API endpoint URL — vrlo stabilan, ali provjeri ako počnu greške
    //   FIX:
    //     - Migracija modela: grep -nE "model: 'claude-" server.js, zamijeni novom string
    //       Trenutno koristim claude-sonnet-4-5-20250929 (15 lokacija)
    //     - DEPRECATION_HISTORY:
    //       • claude-sonnet-4-20250514 deprecated 14.4.2026, gašen 15.6.2026 → migrirano u v135.7.47
    //   LAST_VERIFIED: 2026-05-01
    const fetch_ = (typeof fetch === 'function') ? fetch : require('node-fetch');
    const aiResp = await fetch_('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: AI_MODEL,
        max_tokens: 4000,
        system: sistemskiPrompt,
        messages: [{
          role: 'user',
          content: [
            { type: 'image', source: { type: 'base64', media_type: mediaType, data: cleanBase64 }},
            { type: 'text', text: userPrompt }
          ]
        }]
      }),
      signal: AbortSignal.timeout(120000)  // ⭐ v135.7.216: 120s timeout
    });

    if (!aiResp.ok) {
      const errBody = await aiResp.text();
      console.error('[fasada/validacija-tocaka] AI error:', aiResp.status, errBody);
      return res.status(500).json({ error: 'AI nije odgovorio (status ' + aiResp.status + ')' });
    }

    const aiData = await aiResp.json();
    const textBlocks = (aiData.content || []).filter(b => b.type === 'text');
    if (textBlocks.length === 0) {
      return res.status(500).json({ error: 'AI nije vratio tekst' });
    }

    let aiText = textBlocks[0].text.trim();
    aiText = aiText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

    let parsed;
    try {
      parsed = JSON.parse(aiText);
    } catch (e) {
      console.error('[fasada/validacija-tocaka] JSON parse error:', e.message);
      return res.status(500).json({ error: 'AI vratio nevaljan JSON' });
    }

    // Sanity check: validacije array
    if (!Array.isArray(parsed.validacije)) parsed.validacije = [];

    // Brojac problema
    const problemi = parsed.validacije.filter(v => !v.valjana).length;
    parsed.ukupno_problema = problemi;

    // Log AI usage
    try {
      await logAIUsage('fasada_validacija', AI_MODEL, aiData.usage, req.user?.id, null);
    } catch (e) { console.warn('logAIUsage failed:', e.message); }

    return res.json(parsed);

  } catch (err) {
    console.error('[fasada/validacija-tocaka] error:', err);
    return res.status(500).json({ error: err.message || 'Greska validacije' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// B6: AI Vision detekcija OTVORA u definiranim ravninama
// ═══════════════════════════════════════════════════════════════════════════
// Cilj: korisnik definira N ravnina. AI Vision automatski detektira sve
// otvore (prozore, vrata) i određuje kojoj ravnini pripadaju.
// ═══════════════════════════════════════════════════════════════════════════


// ═══════════════════════════════════════════════════════════════════════════
// EXIF parser (native, bez deps) — izvuče focal_35mm_eq, image dim, make/model
// Vraća { focal_35mm, focal_mm, width, height, make, model } ili null
// ═══════════════════════════════════════════════════════════════════════════
function parseExifFromJpeg(buf) {
  try {
    if (!buf || buf.length < 100) return null;
    // JPEG SOI marker check
    if (buf[0] !== 0xFF || buf[1] !== 0xD8) return null;
    
    // Pronađi APP1 marker (0xFFE1)
    let i = 2;
    let exifStart = -1;
    while (i < Math.min(buf.length - 4, 1048576)) {
      if (buf[i] !== 0xFF) { i++; continue; }
      const marker = buf[i+1];
      const segLen = (buf[i+2] << 8) | buf[i+3];
      if (marker === 0xE1 && segLen > 8) {
        // Provjeri "Exif\0\0" identifier
        if (buf[i+4] === 0x45 && buf[i+5] === 0x78 && buf[i+6] === 0x69 && 
            buf[i+7] === 0x66 && buf[i+8] === 0x00 && buf[i+9] === 0x00) {
          exifStart = i + 10;  // početak TIFF header-a
          break;
        }
      }
      // SOS (Start of Scan, 0xFFDA) = kraj metadata-a
      if (marker === 0xDA) break;
      if (segLen <= 0) break;
      i += 2 + segLen;
    }
    if (exifStart < 0) return null;
    
    // TIFF header: byte order (II=LE, MM=BE), magic (0x002A), IFD0 offset
    const tiffStart = exifStart;
    const isLE = buf[tiffStart] === 0x49 && buf[tiffStart+1] === 0x49;  // 'II'
    const isBE = buf[tiffStart] === 0x4D && buf[tiffStart+1] === 0x4D;  // 'MM'
    if (!isLE && !isBE) return null;
    
    const u16 = (off) => isLE 
      ? (buf[off] | (buf[off+1] << 8))
      : ((buf[off] << 8) | buf[off+1]);
    const u32 = (off) => isLE 
      ? (buf[off] | (buf[off+1] << 8) | (buf[off+2] << 16) | (buf[off+3] << 24)) >>> 0
      : ((buf[off] << 24) | (buf[off+1] << 16) | (buf[off+2] << 8) | buf[off+3]) >>> 0;
    
    if (u16(tiffStart + 2) !== 0x002A) return null;
    
    const ifd0Offset = u32(tiffStart + 4);
    if (ifd0Offset > buf.length - tiffStart) return null;
    
    const result = {};
    let exifSubIfdOffset = 0;
    
    // Helper: čitaj string (ASCII, null-terminated)
    const readString = (off, count) => {
      let s = '';
      for (let k = 0; k < count - 1; k++) {
        const c = buf[off + k];
        if (c === 0) break;
        if (c >= 32 && c < 127) s += String.fromCharCode(c);
      }
      return s.trim();
    };
    
    // Helper: čitaj rational (2× u32 = numerator/denominator)
    const readRational = (off) => {
      const num = u32(off);
      const den = u32(off + 4);
      return den > 0 ? num / den : 0;
    };
    
    // Parsiraj IFD entries
    const parseIFD = (ifdOff) => {
      if (ifdOff < 0 || ifdOff > buf.length - 2) return;
      const startAddr = tiffStart + ifdOff;
      if (startAddr < 0 || startAddr > buf.length - 2) return;
      const numEntries = u16(startAddr);
      if (numEntries > 200 || numEntries < 1) return;  // sanity check
      
      for (let e = 0; e < numEntries; e++) {
        const entryOff = startAddr + 2 + e * 12;
        if (entryOff + 12 > buf.length) break;
        const tag = u16(entryOff);
        const type = u16(entryOff + 2);
        const count = u32(entryOff + 4);
        const valueOff = entryOff + 8;  // ili dereference
        
        // Inline value (≤4 bytes) ili offset
        const inline = (
          (type === 1 && count <= 4) ||  // BYTE
          (type === 2 && count <= 4) ||  // ASCII
          (type === 3 && count <= 2) ||  // SHORT
          (type === 4 && count === 1) || // LONG
          (type === 7 && count <= 4)     // UNDEFINED
        );
        const dataOff = inline ? valueOff : (tiffStart + u32(valueOff));
        if (dataOff < 0 || dataOff > buf.length - 4) continue;
        
        switch(tag) {
          case 0x0100: result.width = u32(dataOff); break;       // ImageWidth
          case 0x0101: result.height = u32(dataOff); break;      // ImageHeight  
          case 0x010F: result.make = readString(dataOff, count); break;   // Make
          case 0x0110: result.model = readString(dataOff, count); break;  // Model
          case 0x8769: exifSubIfdOffset = u32(valueOff); break;  // ExifIFDPointer
          case 0x920A: result.focal_mm = readRational(dataOff); break;    // FocalLength (in Exif sub-IFD usually)
          case 0xA002: result.exif_width = u32(dataOff); break;  // PixelXDimension (Exif sub-IFD)
          case 0xA003: result.exif_height = u32(dataOff); break; // PixelYDimension
          case 0xA405: result.focal_35mm = u16(dataOff); break;  // FocalLengthIn35mmFilm (short)
        }
      }
    };
    
    parseIFD(ifd0Offset);
    if (exifSubIfdOffset > 0) parseIFD(exifSubIfdOffset);
    
    // Fallback: ako nemamo width/height iz IFD0, koristi exif_width/exif_height
    if (!result.width && result.exif_width) result.width = result.exif_width;
    if (!result.height && result.exif_height) result.height = result.exif_height;
    
    return result;
  } catch(e) {
    console.warn('[parseExifFromJpeg]', e.message);
    return null;
  }
}

// Helper: izračunaj GSD i kadar dimenzije iz EXIF + laser distance
function izracunajGSD(exif, laserDistanceM) {
  if (!exif || !exif.focal_35mm || !exif.width || !exif.height || !laserDistanceM) {
    return null;
  }
  // f_pixels = focal_35mm × diag_px / diag_35mm
  // diag_35mm = √(36² + 24²) = 43.27 mm
  const diagPx = Math.sqrt(exif.width ** 2 + exif.height ** 2);
  const diag35 = Math.sqrt(36 * 36 + 24 * 24);  // 43.267
  const fPixels = exif.focal_35mm * diagPx / diag35;
  
  const gsd = laserDistanceM / fPixels;  // m/px
  const kadarW = exif.width * gsd;        // m
  const kadarH = exif.height * gsd;       // m
  
  // FOV (informativno)
  const fovH = 2 * Math.atan(exif.width / (2 * fPixels)) * 180 / Math.PI;
  const fovV = 2 * Math.atan(exif.height / (2 * fPixels)) * 180 / Math.PI;
  
  return {
    f_pixels: Math.round(fPixels),
    gsd_mm_px: parseFloat((gsd * 1000).toFixed(2)),
    kadar_w_m: parseFloat(kadarW.toFixed(2)),
    kadar_h_m: parseFloat(kadarH.toFixed(2)),
    fov_h_deg: parseFloat(fovH.toFixed(1)),
    fov_v_deg: parseFloat(fovV.toFixed(1))
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// POST /api/fasada/ai-quick-estimate
// Brza AI procjena fasade za narudžbu materijala / planiranje dinamike
// Input: slika (base64) + tip objekta + napomena
// Output: { bruto_m2, neto_m2, broj_otvora, debljina, pouzdanost, napomene, raspon }
// ═══════════════════════════════════════════════════════════════════════════

// ⭐ v135.7.25: AI LEARNING — dohvati zadnja korigiranja iz ai_overrides
// Koristi se u system promptu kao "few-shot examples" da AI uči iz korekcija.
// Strategija: dohvaćamo zadnjih N korigiranja po pattern matching kontekstu (LIKE)
// i ekstrahujemo agregirane lekcije (npr. "AI često ne vidi male prozore").
//
// Klijent šalje kontekst kao 'manual_override_otvor', 'manual_override_ploha', itd.
// Server može dohvaćati po patternu npr. 'manual_override_%' ili specifičnom 'manual_override_otvor'.
async function _aiUcenjeIzKorigiranja(kontekstPattern = 'manual_override_%', limit = 20) {
  try {
    // Auto-detekcija: ako kontekst sadrži %, koristi LIKE; inače exact match
    const usesPattern = String(kontekstPattern).includes('%');
    const sqlOp = usesPattern ? 'LIKE' : '=';
    
    const r = await pool.query(`
      SELECT ai_verzija, rucna_verzija, diff, kontekst
      FROM ai_overrides
      WHERE kontekst ${sqlOp} $1
      ORDER BY created_at DESC
      LIMIT $2
    `, [kontekstPattern, limit]);
    
    if (r.rows.length === 0) return null;  // nema povijesti učenja još
    
    // Agregiraj lekcije iz korigiranja
    const lekcije = {
      ukupno_korigiranja: r.rows.length,
      tipovi_pogresaka: {},  // npr. { 'dodani_otvori': 5, 'obrisani_otvori': 1, 'promijenjena_velicina': 3 }
      avg_dodani_otvori: 0,
      avg_obrisani_otvori: 0,
      avg_promjena_bruto_pct: 0,  // u prosjeku koliko % bruto AI je krivo
      najcesce_dodani: 0   // ako > 0, AI češće propušta otvore (treba pažljivije tražiti)
    };
    
    let dodanihKom = 0, obrisanihKom = 0, brutoErrSum = 0, brutoErrN = 0;
    
    r.rows.forEach(row => {
      const d = row.diff || {};
      const ai = row.ai_verzija || {};
      const ru = row.rucna_verzija || {};
      
      // Tipovi izmjena
      if (Array.isArray(d.tipovi_izmjena)) {
        d.tipovi_izmjena.forEach(t => {
          lekcije.tipovi_pogresaka[t] = (lekcije.tipovi_pogresaka[t] || 0) + 1;
        });
      }
      
      // Otvori
      const razlikaOtv = parseInt(d.razlika_broj_otvora) || 0;
      if (razlikaOtv > 0) dodanihKom += razlikaOtv;
      else if (razlikaOtv < 0) obrisanihKom += Math.abs(razlikaOtv);
      
      // Bruto
      const brutoAi = parseFloat(d.bruto_m2_ai) || parseFloat(ai.bruto_m2) || 0;
      const brutoRu = parseFloat(d.bruto_m2_rucna) || parseFloat(ru.bruto_m2) || 0;
      if (brutoAi > 0 && brutoRu > 0) {
        const errPct = Math.abs((brutoRu - brutoAi) / brutoAi) * 100;
        brutoErrSum += errPct;
        brutoErrN++;
      }
    });
    
    lekcije.avg_dodani_otvori = r.rows.length > 0 ? (dodanihKom / r.rows.length) : 0;
    lekcije.avg_obrisani_otvori = r.rows.length > 0 ? (obrisanihKom / r.rows.length) : 0;
    lekcije.avg_promjena_bruto_pct = brutoErrN > 0 ? (brutoErrSum / brutoErrN) : 0;
    lekcije.najcesce_dodani = dodanihKom > obrisanihKom ? 1 : 0;
    
    return lekcije;
  } catch(e) {
    console.warn('[AI learning fetch fail]', e.message);
    return null;
  }
}

// ⭐ v135.7.25: Pretvori lekcije u prompt tekst (na hrvatskom, jasno)
function _aiLekcijeUPrompt(lekcije) {
  if (!lekcije || lekcije.ukupno_korigiranja === 0) return '';
  
  const parts = [];
  parts.push(`\n📚 NAUČENO IZ ${lekcije.ukupno_korigiranja} KORIGIRANJA NA TVOJIM PROŠLIM KNJIGAMA:`);
  
  if (lekcije.avg_dodani_otvori > 0.5) {
    parts.push(`⚠️ Korisnik je u ${(lekcije.avg_dodani_otvori).toFixed(1)} prosjeku DODAVAO otvora po knjizi — to znači da PROPUŠTAŠ otvore. Pažljivije pregledaj sliku za:
   - Mali prozori (npr. WC, kupaonica) — često 60×40 cm, lako ih je previdjeti
   - Balkonska vrata — ako vidiš balkon, ispod njega su vrata
   - Ventilacijski otvori — okrugli ili kvadratni
   - Prozori u sjeni / na rubu slike`);
  }
  
  if (lekcije.avg_obrisani_otvori > 0.5) {
    parts.push(`⚠️ Korisnik je u prosjeku BRISAO ${(lekcije.avg_obrisani_otvori).toFixed(1)} otvora — to znači da DETEKTIRAŠ FALSE POZITIVE. Provjeri:
   - Sjene na fasadi nisu prozori
   - Boja varijacije nisu otvori
   - Reljefni elementi (vučena žbuka) nisu otvori`);
  }
  
  if (lekcije.avg_promjena_bruto_pct > 5) {
    parts.push(`⚠️ Tvoja BRUTO knjiga u prosjeku odstupa ${lekcije.avg_promjena_bruto_pct.toFixed(1)}% od stvarne — budi pažljiviji s mjerenjima. Provjeri kalibraciju (referentne mjere, broj katova).`);
  }
  
  // Tipovi pogrešaka
  const topPogr = Object.entries(lekcije.tipovi_pogresaka)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3);
  if (topPogr.length > 0) {
    parts.push(`Najčešće korekcije: ${topPogr.map(([t, n]) => `${t} (${n}x)`).join(', ')}`);
  }
  
  return parts.join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// HOMOGRAFIJA helpers — port iz index.html za korištenje u AI brzoj procjeni
// ═══════════════════════════════════════════════════════════════════════════
function _srvH4tocke(px4, m4) {
  if (!Array.isArray(px4) || !Array.isArray(m4) || px4.length !== 4 || m4.length !== 4) return null;
  const A = []; const b = [];
  for (let i = 0; i < 4; i++) {
    const sx = px4[i].x, sy = px4[i].y;
    const dx = m4[i].x, dy = m4[i].y;
    A.push([sx, sy, 1, 0, 0, 0, -dx*sx, -dx*sy]);
    b.push(dx);
    A.push([0, 0, 0, sx, sy, 1, -dy*sx, -dy*sy]);
    b.push(dy);
  }
  const n = b.length;
  const M = A.map((row, i) => [...row, b[i]]);
  for (let i = 0; i < n; i++) {
    let maxRow = i;
    for (let k = i + 1; k < n; k++) {
      if (Math.abs(M[k][i]) > Math.abs(M[maxRow][i])) maxRow = k;
    }
    [M[i], M[maxRow]] = [M[maxRow], M[i]];
    if (Math.abs(M[i][i]) < 1e-10) return null;
    const piv = M[i][i];
    for (let j = 0; j < n + 1; j++) M[i][j] /= piv;
    for (let k = 0; k < n; k++) {
      if (k === i) continue;
      const f = M[k][i];
      for (let j = 0; j < n + 1; j++) M[k][j] -= f * M[i][j];
    }
  }
  const h = M.map(row => row[n]);
  return [
    [h[0], h[1], h[2]],
    [h[3], h[4], h[5]],
    [h[6], h[7], 1]
  ];
}

function _srvMNaRavnini(H, px) {
  if (!H || !px) return null;
  const x = px.x, y = px.y;
  const w = H[2][0]*x + H[2][1]*y + H[2][2];
  if (Math.abs(w) < 1e-10) return null;
  return {
    x: (H[0][0]*x + H[0][1]*y + H[0][2]) / w,
    y: (H[1][0]*x + H[1][1]*y + H[1][2]) / w
  };
}

