// AI Fine-position kutova ravnine (mikro-podesavanje na pravi rub procelja)
// ═══════════════════════════════════════════════════════════════════════════
// Korisnik je vec definirao ravninu (4 piksel-kuta priblizno). AI Vision
// fino podesi piksele tako da padaju TOCNO na rub procelja na slici.
// ═══════════════════════════════════════════════════════════════════════════


// ─── POST /api/fasada/ai-fine-kutovi (původně oko L10061) ───
app.post('/api/fasada/ai-fine-kutovi', auth, staff, aiRateLimit, async (req, res) => {
  try {
    const { slika_base64, ravnina } = req.body;

    if (!slika_base64) return res.status(400).json({ error: 'Nedostaje slika' });
    if (!ravnina || !ravnina.kutoviPx || ravnina.kutoviPx.length !== 4) {
      return res.status(400).json({ error: 'Nedostaje ravnina ili kutovi' });
    }

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY nije postavljen' });

    let cleanBase64 = slika_base64;
    let mediaType = 'image/jpeg';
    const m = slika_base64.match(/^data:(image\/[a-z]+);base64,(.+)$/);
    if (m) { mediaType = m[1]; cleanBase64 = m[2]; }
    if (cleanBase64.length > 7000000) {
      return res.status(400).json({ error: 'Slika prevelika (max ~5MB)' });
    }

    const sistemskiPrompt = `Ti si ekspert za PRECIZNU detekciju rubova procelja na fasadama.
Korisnik je priblizno oznacio 4 kuta procelja. Tvoj zadatak: PODESITI piksele tako da TOCNO padaju na vidljive rubove procelja.
Vraca SAMO valjan JSON.`;

    const userPrompt = `Korisnik je oznacio ravninu "${ravnina.opis || ''}" (${ravnina.sirina_m} m × ${ravnina.visina_m} m) sa 4 kuta:

BL (donji-lijevi): ${JSON.stringify(ravnina.kutoviPx[0])}
BR (donji-desni): ${JSON.stringify(ravnina.kutoviPx[1])}
TR (gornji-desni): ${JSON.stringify(ravnina.kutoviPx[2])}
TL (gornji-lijevi): ${JSON.stringify(ravnina.kutoviPx[3])}

ZADATAK: Provjeri svaki kut na slici i ako nije TOCNO na rubu procelja, predloži NOVI piksel.

Pogledaj rubove:
- Dolje: rub procelja gdje pocinje tlo/cesta (BL ↔ BR linija)
- Desno: rub procelja gdje zavrsava (BR ↔ TR linija)
- Gore: rub procelja gdje pocinje krov/atika (TR ↔ TL linija)
- Lijevo: rub procelja gdje zavrsava (TL ↔ BL linija)

Maksimalno odstupanje: 30 piksela od originalnog (ako je vise, ne mijenjaj - vjerojatno je u redu).

Vrati JSON:
{
  "kutoviPx": [
    {"x": ..., "y": ...},
    {"x": ..., "y": ...},
    {"x": ..., "y": ...},
    {"x": ..., "y": ...}
  ],
  "promjena_px": [5, 0, 12, 3],
  "obrazlozenje": "kratki tekst (max 150 znakova)"
}

PRAVILA:
- Reduce promjenu ako je rub jasno vidljiv vec na originalnom pikselu
- Vrati ISKLJUCIVO valjan JSON, bez markdown-a
- Promjena se mora vidjeti vizualno na slici (ne sumnjivo)`;

    const fetch_ = (typeof fetch === 'function') ? fetch : require('node-fetch');
    const aiResp = await fetch_('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: AI_MODEL,
        max_tokens: 2000,
        system: sistemskiPrompt,
        messages: [{
          role: 'user',
          content: [
            { type: 'image', source: { type: 'base64', media_type: mediaType, data: cleanBase64 }},
            { type: 'text', text: userPrompt }
          ]
        }]
      }),
      signal: AbortSignal.timeout(120000)  // ⭐ v135.7.216: 120s timeout
    });

    if (!aiResp.ok) {
      const errBody = await aiResp.text();
      console.error('[fasada/ai-fine-kutovi] AI error:', aiResp.status, errBody);
      return res.status(500).json({ error: 'AI nije odgovorio' });
    }

    const aiData = await aiResp.json();
    const textBlocks = (aiData.content || []).filter(b => b.type === 'text');
    if (textBlocks.length === 0) return res.status(500).json({ error: 'AI nije vratio tekst' });

    let aiText = textBlocks[0].text.trim();

    let parsed = null;
    try {
      parsed = JSON.parse(aiText);
    } catch (e1) {
      try {
        const cleaned = aiText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
        parsed = JSON.parse(cleaned);
      } catch (e2) {
        const startIdx = aiText.indexOf('{');
        const endIdx = aiText.lastIndexOf('}');
        if (startIdx !== -1 && endIdx > startIdx) {
          try { parsed = JSON.parse(aiText.substring(startIdx, endIdx + 1)); } catch(_){}
        }
      }
    }

    if (!parsed || !Array.isArray(parsed.kutoviPx) || parsed.kutoviPx.length !== 4) {
      return res.status(500).json({ error: 'AI vratio nevaljan format' });
    }

    // Validacija: max 30px odstupanja od originalnog
    let validni = true;
    parsed.kutoviPx.forEach((p, i) => {
      const orig = ravnina.kutoviPx[i];
      const dx = Math.abs(p.x - orig.x);
      const dy = Math.abs(p.y - orig.y);
      if (dx > 50 || dy > 50) {
        // Vrati originalni ako je predaleko
        parsed.kutoviPx[i] = orig;
      }
    });

    try {
      await logAIUsage('fasada_ai_fine_kutovi', AI_MODEL, aiData.usage, req.user?.id, null);
    } catch (e) { console.warn('logAIUsage failed:', e.message); }

    return res.json(parsed);

  } catch (err) {
    console.error('[fasada/ai-fine-kutovi] error:', err);
    return res.status(500).json({ error: err.message || 'Greska fine kutovi' });
  }
});

