// ⭐ v135.7.499 (Ivan, 19.05.2026): RECOVERY PROBE ENDPOINT
// GET /api/fasada/:id/probe-slike
// ═════════════════════════════════════════════════════════════════════════════
//   Cilj: pri load-u knjige u app-u, klijent zove ovaj endpoint da provjeri
//   ima li ijedna anotirana slika nestala s QNAP-a (npr. zbog starog bug-a
//   ili eksternog brisanja). Endpoint vraća listu idx-eva pročelja koja
//   trebaju regen pri sljedećem save-u.
//
//   Korak po korak:
//     1. Učitaj knjiga_procelja[] iz DB-a
//     2. Za svako pročelje s slika_hatch_qnap_path: HEAD na QNAP path
//     3. Ako 404 — provjeri B2 (možda treba restore-ati)
//     4. Označi { idx, oznaka, qnap_missing, b2_available }
//   
//   Klijent zatim pri save-u zna treba li regenerirati hatch ili samo
//   restore-ati s B2.
app.get('/api/fasada/:id/probe-slike', auth, staff, async (req, res) => {
  try {
    const procjenaId = parseInt(req.params.id);
    if (!Number.isFinite(procjenaId) || procjenaId <= 0) {
      return res.status(400).json({ error: 'Nevalidan knjiga ID' });
    }
    
    const r = await pool.query(
      'SELECT dimenzije_fasade FROM fasade_procjene WHERE id = $1',
      [procjenaId]
    );
    if (!r.rows.length) return res.status(404).json({ error: 'Knjiga ne postoji' });
    
    const dim = r.rows[0].dimenzije_fasade || {};
    const kp = Array.isArray(dim.knjiga_procelja) ? dim.knjiga_procelja : [];
    
    // ⭐ v500 (Ivan, 19.05.2026): probe SAMO QNAP, bez B2 check.
    //   Razlog: B2 dual-write je ukinut za Fasade-AI path-eve (v500), pa B2 status više 
    //   nije konzistentan informativan. Plus banner s "B2 backup postoji" je davao 
    //   korisniku iluziju sigurnosti koja može lagati (verzija conflict).
    const result = [];
    for (let i = 0; i < kp.length; i++) {
      const p = kp[i] || {};
      const entry = { 
        idx: i, 
        oznaka: p.oznaka || `Procelje-${i+1}`,
        slika_qnap_missing: false,
        hatch_qnap_missing: false,
        slika_qnap_path: p.slika_qnap_path || null,
        slika_hatch_qnap_path: p.slika_hatch_qnap_path || null
      };
      
      // Provjeri slika.jpg na QNAP-u
      if (p.slika_qnap_path && process.env.QNAP_WEBDAV_URL) {
        try {
          const exists = (typeof qnapFileExists === 'function')
            ? await qnapFileExists(p.slika_qnap_path)
            : true;
          entry.slika_qnap_missing = !exists;
        } catch(_) { entry.slika_qnap_missing = true; }
      }
      
      // Provjeri anotirana.jpg na QNAP-u
      if (p.slika_hatch_qnap_path && process.env.QNAP_WEBDAV_URL) {
        try {
          const exists = (typeof qnapFileExists === 'function')
            ? await qnapFileExists(p.slika_hatch_qnap_path)
            : true;
          entry.hatch_qnap_missing = !exists;
        } catch(_) { entry.hatch_qnap_missing = true; }
      }
      
      result.push(entry);
    }
    
    const anyMissing = result.some(e => e.slika_qnap_missing || e.hatch_qnap_missing);
    return res.json({
      procjena_id: procjenaId,
      procelja: result,
      any_missing: anyMissing,
      total_procelja: kp.length
    });
  } catch (err) {
    console.error('[probe-slike v500] error:', err);
    return res.status(500).json({ error: err.message || 'Greska probe-a' });
  }
});


