// ── FASADA EXCEL EXPORT — građevinska knjiga / obračun ────────────────────────

// Dohvati ANOTIRANU sliku (s plohama i otvorima) - koristi se u Excelu
// Fallback: ako nema anotirane, vrati originalnu
async function dohvatiAnotiranuSlikuProcjene(procjenaId) {
  try {
    const r = await pool.query(
      'SELECT ai_anotirana_slika FROM fasade_procjene WHERE id=$1',
      [procjenaId]
    );
    const anot = r.rows[0]?.ai_anotirana_slika;
    if (!anot) return null;

    // Ako je QNAP path (i nove Fasade-AI/{naziv}/ i legacy Fasada/{id}_{slug}/ strukture)
    if (typeof anot === 'string' &&
        (anot.startsWith('Fasade-AI/') || anot.startsWith('Fasada/')) &&
        process.env.QNAP_WEBDAV_URL) {
      try {
        const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
        const base    = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
        const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
        const cleanPath = anot.replace(/^\//, '');
        // FIX: koristi QNAP_BASE_PATH prefix (slike se uploadaju na /APLIKACIJA/Fasade-AI/...)
        const qr = await fetch(`${baseUrl}${base}/${cleanPath}`, {
          headers: { Authorization: `Basic ${auth64}` },
          signal: AbortSignal.timeout(15000)
        });
        console.log(`[dohvatiAnotiranuSliku] ${cleanPath}: status ${qr.status}`);
        if (qr.ok) return Buffer.from(await qr.arrayBuffer());
      } catch(e) { console.warn('[Anotirana QNAP fail]', e.message); }
    }

    // Ako je base64 string
    if (typeof anot === 'string' && anot.startsWith('data:image/')) {
      const m = anot.match(/^data:image\/[a-z]+;base64,(.+)$/);
      if (m) return Buffer.from(m[1], 'base64');
    }

    return null;
  } catch(e) {
    console.warn('[dohvatiAnotiranuSliku]', e.message);
    return null;
  }
}

// Dohvati sliku procjene (QNAP fallback DB)
async function dohvatiSlikuProcjene(procjenaId) {
  try {
    const r = await pool.query(
      'SELECT slika_base64, slika_qnap_path FROM fasade_procjene WHERE id=$1',
      [procjenaId]
    );
    const row = r.rows[0];
    if (!row) return null;

    // Prvo pokušaj QNAP
    if (row.slika_qnap_path && process.env.QNAP_WEBDAV_URL) {
      try {
        const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
        const base    = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
        const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
        const cleanPath = row.slika_qnap_path.replace(/^\//, '');
        // FIX: koristi QNAP_BASE_PATH prefix
        const fullUrl = `${baseUrl}${base}/${cleanPath}`;
        const qr = await fetch(fullUrl, {
          headers: { Authorization: `Basic ${auth64}` },
          signal: AbortSignal.timeout(15000)
        });
        console.log(`[dohvatiSliku] ${cleanPath}: status ${qr.status}`);
        if (qr.ok) {
          return Buffer.from(await qr.arrayBuffer());
        }
      } catch(e) { console.warn('[Fasada Excel] QNAP fail:', e.message); }
    }

    // Fallback: base64 u DB
    if (row.slika_base64) {
      const m = row.slika_base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
      const b64 = m ? m[1] : row.slika_base64;
      return Buffer.from(b64, 'base64');
    }
    return null;
  } catch(e) {
    console.error('[Fasada Excel] dohvatiSliku err:', e.message);
    return null;
  }
}

