// ⭐ v323 (Ivan): Robusna normalizacija opisa za grupiranje u Excel exportu.
//   v327 (Ivan, follow-up): dodano stripanje napomena u zagradama da "XPS 2cm (parapet)" 
//   i "XPS 2cm (parapet. Terasa = 4.28+0.61 = 14.58m')" idu u istu grupu.
//   
//   Cilj: "Xps 16cm", "XPS 16 cm", "xps16cm", "XPS-16cm", "XPS 16cm (detalji...)"
//         → svi jedan ključ "xps 16cm".
//   
//   Koristi se u 4 mjesta (rezime po podsekcijama + 2 sheet grupiranja + sitnice).
//
//   Algoritam:
//   1. lowercase + ukloni dijakritike (š→s, č→c, ć→c, ž→z, đ→d)
//   2. v327: ukloni SVE u zagradama (napomene/detalji/formule)
//   3. ukloni razmake oko brojeva: "16 cm" → "16cm"
//   4. squash multiple spaces, trim, normaliziraj cm sufiks
//   5. ukloni dashes/separator-e: "EPS-16cm" → "eps 16cm"
//
//   Posljedica: ova normalizacija je AGRESIVNA — koristi se SAMO za ključ grupiranja, 
//   NE za displayOpis (taj zadržava original sa napomenama, npr. "XPS 16cm (parapet)").
function _fasNormalizirajOpis(s) {
  if (!s) return '—';
  let t = String(s).toLowerCase().trim();
  // Hr dijakritike
  t = t.replace(/š/g, 's').replace(/č/g, 'c').replace(/ć/g, 'c')
       .replace(/ž/g, 'z').replace(/đ/g, 'd');
  // ⭐ v327 (Ivan): ukloni SVE u (zagradama) — to su napomene/detalji/formule, ne dio identiteta materijala.
  //   "XPS 2cm (parapet. Terasa = 4.28+0.61 = 14.58m')" → "XPS 2cm "
  //   "EPS 5cm (podgled)" → "EPS 5cm "
  //   Recursively za nested: "(a (b) c)" → ""
  let prev;
  do { prev = t; t = t.replace(/\([^()]*\)/g, ' '); } while (t !== prev);
  // Em/en dash → space
  t = t.replace(/[\u2013\u2014]/g, ' ');
  // Bilo koji dash, underscore, slash → space
  t = t.replace(/[-_\/]+/g, ' ');
  // Ukloni razmak između broja i jedinice: "16 cm" → "16cm", "16 mm" → "16mm"
  t = t.replace(/(\d+(?:[.,]\d+)?)\s*(cm|mm|m|kg|kom)\b/g, '$1$2');
  // Normaliziraj decimalni separator: zarez → točka (16,5cm → 16.5cm)
  t = t.replace(/(\d+),(\d+)(cm|mm|m)/g, '$1.$2$3');
  // Squash multiple spaces
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}

// Generiraj jedan A4 list u Excel sheet-u (jedna procjena = jedan blok s page break)
// Server-side helper: izracunaj bbox dimenzije iz tocaka poligona + ukupne m²
function _serverBboxIzTocaka(tocke_px, ukupna_m2) {
  if (!tocke_px || tocke_px.length < 3 || !ukupna_m2 || ukupna_m2 <= 0) return null;

  // Shoelace povrsina u px2
  let area_px2 = 0;
  for (let i = 0; i < tocke_px.length; i++) {
    const j = (i + 1) % tocke_px.length;
    area_px2 += tocke_px[i].x * tocke_px[j].y;
    area_px2 -= tocke_px[j].x * tocke_px[i].y;
  }
  area_px2 = Math.abs(area_px2 / 2);

  if (area_px2 <= 0) return null;

  const skala = Math.sqrt(ukupna_m2 / area_px2);

  let minX = tocke_px[0].x, maxX = tocke_px[0].x;
  let minY = tocke_px[0].y, maxY = tocke_px[0].y;
  tocke_px.forEach(p => {
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.y > maxY) maxY = p.y;
  });

  const bbox_sirina_m = (maxX - minX) * skala;
  const bbox_visina_m = (maxY - minY) * skala;
  const bbox_m2 = bbox_sirina_m * bbox_visina_m;
  // ⭐ v324 (audit 4 / L2): defenzivni guard — bbox_m2===0 (degenerate) ne dijeli
  const fillRatio = bbox_m2 > 0 ? (ukupna_m2 / bbox_m2) : 0;

  return {
    sirina_m: parseFloat(bbox_sirina_m.toFixed(2)),
    visina_m: parseFloat(bbox_visina_m.toFixed(2)),
    bbox_m2: parseFloat(bbox_m2.toFixed(2)),
    poligon_m2: parseFloat(ukupna_m2.toFixed(2)),
    pravokutan: fillRatio >= 0.92
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.378 (Ivan, 16.05.2026): Helper za detekciju aspect ratio slike iz PNG/JPG base64
//   Use case: per-pročelje sheet orijentacija (portrait/landscape) ovisi o orijentaciji
//   slike fasade. Ako je slika visoka (npr. zabatna fasada) → portrait, inače landscape.
//   
//   PNG format: bytes 16-23 sadrže Width (uint32 BE) i Height (uint32 BE).
//   JPEG format: traži SOF0/SOF2 marker (FFC0/FFC2), pa 5 bytes je [precision][H_hi H_lo][W_hi W_lo].
//   Vraća { width, height, ratio } gdje ratio = width/height.
//   Vraća null ako parsiranje fail-a (sigurno fallback na landscape).
function _detektirajAspectRatio(base64iliBuffer) {
  try {
    let buf;
    if (Buffer.isBuffer(base64iliBuffer)) {
      buf = base64iliBuffer;
    } else if (typeof base64iliBuffer === 'string') {
      // Skini "data:image/png;base64," prefix ako postoji
      const cleanB64 = base64iliBuffer.replace(/^data:image\/\w+;base64,/, '');
      buf = Buffer.from(cleanB64, 'base64');
    } else {
      return null;
    }
    
    if (buf.length < 24) return null;
    
    // PNG signature: 0x89 0x50 0x4E 0x47 0x0D 0x0A 0x1A 0x0A
    if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) {
      const width = buf.readUInt32BE(16);
      const height = buf.readUInt32BE(20);
      if (width > 0 && height > 0) {
        return { width, height, ratio: width / height };
      }
    }
    
    // JPEG signature: 0xFF 0xD8 0xFF
    if (buf[0] === 0xFF && buf[1] === 0xD8 && buf[2] === 0xFF) {
      let i = 2;
      while (i < buf.length - 9) {
        if (buf[i] !== 0xFF) { i++; continue; }
        const marker = buf[i + 1];
        // SOF0 (0xC0), SOF1 (0xC1), SOF2 (0xC2) — Start of Frame markers
        if (marker === 0xC0 || marker === 0xC1 || marker === 0xC2) {
          // Frame data: 2 bytes length, 1 byte precision, 2 bytes height, 2 bytes width
          const height = buf.readUInt16BE(i + 5);
          const width = buf.readUInt16BE(i + 7);
          if (width > 0 && height > 0) {
            return { width, height, ratio: width / height };
          }
          break;
        }
        // Skip segment: 2 bytes marker + 2 bytes length (sadrži length sebe)
        const segLen = buf.readUInt16BE(i + 2);
        i += 2 + segLen;
      }
    }
    
    return null;
  } catch(e) {
    return null;
  }
}

// ⭐ v135.7.385 (Ivan, 16.05.2026): AUTO-CROP bijelih rubova hatchirane slike + detekcija aspect
//   Use case: hatchirana slika u Excel exportu ima ~30% bijelog prostora gore i dolje 
//   (Ivan screenshot: slika "sjever" zauzima samo srednjih ~60% A4 lista).
//   
//   Što radi:
//     1. sharp.trim(threshold=18) — automatski briše uniformne bijele rubove sa svih 4 strane.
//        Threshold 18/255 = 7% tolerancije za JPEG kompresiju + sive nuance.
//     2. Vraća { buffer, width, height, ratio, cropped } — sve potrebno za:
//        • orientation odluka (portrait vs landscape A4)
//        • Excel embed dimensions (slika ide max do margine)
//     3. Fallback ako sharp ne dostupan / trim ne uspije → vraća null (caller koristi original)
//   
//   Performance: ~200-500ms per slika za tipičnu 2-5MB JPEG. Acceptable za on-demand export.
async function _cropBijeleRubove(buffer) {
  if (!buffer || !Buffer.isBuffer(buffer) || buffer.length < 200) return null;
  
  // ⭐ v386 (Ivan): koristi cached _getSharp() helper (jednom require, cache) umjesto 
  //   require('sharp') na svaki poziv — brže za multi-pročelje export (4-10 pročelja).
  const sharp = (typeof _getSharp === 'function') ? _getSharp() : null;
  if (!sharp) {
    console.warn('[_cropBijeleRubove] sharp nije dostupan, koristi original sliku');
    return null;
  }
  
  try {
    // sharp.trim() — auto detektira boju gornjeg-lijevog piksela i briše sve istih ±threshold.
    // Najčešće taj piksel je bijel (255,255,255) za hatchiranu sliku → savršeno za crop.
    // Threshold 18 = 18/255 = 7% tolerancije (kompenzira JPEG kompresiju).
    const result = await sharp(buffer)
      .trim({ threshold: 18 })
      .toBuffer({ resolveWithObject: true });
    
    if (!result.data || !result.info) return null;
    const { width, height } = result.info;
    if (width < 50 || height < 50) {
      console.warn('[_cropBijeleRubove] crop rezultat preuski, fallback na original');
      return null;
    }
    
    return {
      buffer: result.data,
      width,
      height,
      ratio: width / height,
      cropped: true,
      originalSize: buffer.length,
      croppedSize: result.data.length
    };
  } catch(e) {
    console.warn('[_cropBijeleRubove] trim fail:', e.message);
    return null;
  }
}

// FAZA A: Excel glavni sheet — koncept='ravnine'
// Koristi ravnine_json, otvori_json, pozarne_barijere_json, zone_debljine_json
// Respektira _manual_override mjere
// ═══════════════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════════════

// ⭐ v135.7.378 (Ivan, 16.05.2026): Helper za umetanje PEČATA + POTPISA u Ovjeru
//   Use case: na svakoj OVJERA IZVOĐAČA sekciji (3 mjesta — Ravnine generator, 
//   Klasični generator, Sažetak), potpis Ivana Čakarića preko pečata ŽBUKA d.o.o.
//   "Spontano" izgled: pečat malo offset, potpis preko pečata (gore lijevo offset).
//   Smjenjuje crtice "___________________________" linija u OVJERA IZVOĐAČA.
//   
//   Parametri:
//     ws — worksheet u koji se umeće slika
//     wb — workbook (potreban za addImage)
//     rowStart — red u kojem počinje OVJERA IZVOĐAČA naslov (potpis ide u sljedeća 2 reda)
//     colStart — početni stupac (1-based) — npr. 1 za lijevu polovicu
//     colSpan — koliko stupaca pokriva (npr. 4 za stupce 1-4)
//   
//   Vraća: broj redova koje je helper "potrošio" (caller mora preskočiti te redove)
function _knjigaUmetniPecatPotpis(ws, wb, rowStart, colStart, colSpan) {
  try {
    // Cache addImage rezultate na workbook level — da ne re-učitavamo iste slike za svaki sheet
    if (!wb._pecatImageId) {
      wb._pecatImageId = wb.addImage({
        base64: 'data:image/png;base64,' + ZBUKA_PECAT_B64,
        extension: 'png',
      });
    }
    if (!wb._potpisImageId) {
      wb._potpisImageId = wb.addImage({
        base64: 'data:image/png;base64,' + IVAN_POTPIS_B64,
        extension: 'png',
      });
    }
    
    // Pozicioniranje: pečat ide u centar/lijevo, potpis ide preko + malo desno + dolje
    // tl koordinate u exceljs: { col: X, row: Y } gdje col/row mogu biti decimale (0-indexed)
    // Pečat slika je 286×132 (ZBUKA_PECAT) → 130×60 px za Excel
    // Potpis slika je 500×173 (IVAN_POTPIS) → 130×45 px (preko pečata, blago desno)
    
    // Pečat — centar u colStart+0.3, otpočinje malo iznad rowStart (vizualno "spontano")
    ws.addImage(wb._pecatImageId, {
      tl: { col: (colStart - 1) + 0.7, row: (rowStart - 1) + 0.1 },
      ext: { width: 120, height: 55 }
    });
    
    // Potpis — preko pečata, malo desno + dolje (spontani efekt)
    ws.addImage(wb._potpisImageId, {
      tl: { col: (colStart - 1) + 1.4, row: (rowStart - 1) + 0.4 },
      ext: { width: 110, height: 38 }
    });
    
    return 0; // ne troši dodatne redove (slika je overlay)
  } catch(e) {
    console.warn(`[_knjigaUmetniPecatPotpis] Greška: ${e.message}`);
    return 0;
  }
}

// ⭐ MULTI-PROČELJE KNJIGA: 1 summary sheet + N per-pročelje sheets
// ═══════════════════════════════════════════════════════════════════════════
async function _generirajExcelKnjigaMulti(summaryWs, f, pocetniRed, gradilisteNaziv, gradilisteAdresa, procelja) {
  const RED = 'FFCC0000';
  const DARK = 'FF1a1a2e';
  const LBKG = 'FFf8f9fa';
  const BORD = 'FFdee2e6';
  const GREEN = 'FF10B981';
  const ORANGE = 'FFEA580C';
  const BLUE = 'FF0891B2';
  const PURPLE = 'FF7C3AED';
  
  let r = pocetniRed;
  
  // ═══ 1. HEADER (s logom) ═══
  // ⭐ v372 (Ivan, 16.05.2026): Logo veći — 100×50 → 130×65 → 150×75 px za vidljivost u 
  //   Ukupno listu (A4 portrait). Header row 75→85 da prostor odgovara većem logu.
  summaryWs.getRow(r).height = 85;
  try {
    if (!summaryWs._logoImageId) {
      const logoImageId = summaryWs.workbook.addImage({
        base64: 'data:image/png;base64,' + LOGO_B64,
        extension: 'png',
      });
      summaryWs._logoImageId = logoImageId;
    }
    summaryWs.addImage(summaryWs._logoImageId, {
      tl: { col: 0.15, row: r - 1 + 0.1 },
      ext: { width: 150, height: 75 }
    });
  } catch(e) {}
  
  summaryWs.mergeCells(r, 3, r, 8);
  const cT = summaryWs.getCell(r, 3);
  cT.value = 'GRAĐEVINSKA KNJIGA — SAŽETAK NACRTI';
  cT.font = { bold: true, size: 14, color: { argb: RED } };
  cT.alignment = { horizontal: 'right', vertical: 'middle' };
  r++;
  
  summaryWs.mergeCells(r, 3, r, 8);
  const cT2 = summaryWs.getCell(r, 3);
  cT2.value = `(${procelja.length} nacrt${procelja.length === 1 ? '' : 'a'} — fasaderski radovi)`;
  cT2.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
  cT2.alignment = { horizontal: 'right' };
  r++;
  
  summaryWs.mergeCells(r, 1, r, 8);
  summaryWs.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
  summaryWs.getRow(r).height = 4;
  r++;
  
  // ═══ 2. INFO BLOK ═══
  summaryWs.getRow(r).height = 5; r++;
  const datum = new Date(f.created_at);
  const dStr = fmtDate(datum) + ' ' + datum.toLocaleTimeString('hr-HR', {hour:'2-digit', minute:'2-digit'});
  
  const infoRows = [
    ['🏗 Gradilište:', gradilisteNaziv || '?', '📅 Datum:', dStr],
    ['📍 Adresa:', gradilisteAdresa || '-', '👤 Kreirao:', f.kreirao || '-'],
    // ⭐ Mjerni obračun napomena (po user request-u)
    ['📐 Metoda:', 'Referentne ravnine + perspektiva (±2% točnost)', '', '']
  ];
  infoRows.forEach(row => {
    summaryWs.getCell(r, 1).value = row[0];
    summaryWs.getCell(r, 1).font = { bold: true, size: 9, color: { argb: 'FF6b7280' } };
    summaryWs.mergeCells(r, 2, r, 4);
    summaryWs.getCell(r, 2).value = row[1];
    summaryWs.getCell(r, 2).font = { size: 10, color: { argb: DARK } };
    if (row[2]) {
      summaryWs.getCell(r, 5).value = row[2];
      summaryWs.getCell(r, 5).font = { bold: true, size: 9, color: { argb: 'FF6b7280' } };
      summaryWs.mergeCells(r, 6, r, 8);
      summaryWs.getCell(r, 6).value = row[3];
      summaryWs.getCell(r, 6).font = { size: 10, color: { argb: DARK } };
    }
    r++;
  });
  summaryWs.getRow(r).height = 8; r++;
  
  // ═══ 3. TABELA PROČELJA ═══
  summaryWs.mergeCells(r, 1, r, 8);
  const cap = summaryWs.getCell(r, 1);
  cap.value = '🏗 UKUPNO NACRTI';
  cap.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  cap.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: PURPLE } };
  cap.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  summaryWs.getRow(r).height = 22;
  r++;
  
  // Header reda — Status kolona uklonjena (po user request-u)
  // ⭐ v311 (Ivan, točka 5): dodan stupac "Otvori GN 421" desno od "Otvori m²"
  // ⭐ v447 (Ivan, 18.05.2026): UKLONJEN stupac "Otvori m²" (ukupna m² otvora — nebitno za fakture); 
  //   DODAN stupac "Špalete (+)" (m² dodatak od otvora >5 m²). Novi flow čitanja:
  //   Bruto → Otvori GN 421 (odbitak, neg.) → Špalete (+) (pozitivan) → Neto.
  const headers = ['#', 'Naziv nacrta', 'Bruto m²', 'Otvori GN 421', 'Špalete (+)', 'Neto m²', 'Ravnine', 'Plohe'];
  headers.forEach((h, i) => {
    const c = summaryWs.getCell(r, i + 1);
    c.value = h;
    c.font = { bold: true, size: 9.5, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i <= 1 ? 'left' : 'right', vertical: 'middle', indent: i <= 1 ? 1 : 0 };
    c.border = { top: { style: 'thin', color: { argb: BORD } }, bottom: { style: 'thin', color: { argb: BORD } } };
  });
  summaryWs.getRow(r).height = 18;
  r++;
  
  // Redovi pročelja
  // ⭐ v135.7.15 BUG #4 FIX: Sinkronizirana formula sa server-side multi-knjiga sumiranjem
  //    Bruto = Σ ploha (s backward compat _m2 || m2)
  //    Neto = Bruto - GN421 odbitak (otvori >3m²) + spalete - barijere - debljine + sitnice
  // ⭐ v447 (Ivan, 18.05.2026): dodan akumulator ukupnoSpalete za novu kolonu "Špalete (+)"
  let ukupnoBruto = 0, ukupnoOtvori = 0, ukupnoNeto = 0;
  let ukupnoOtvoriGN = 0;     // ⭐ v311: suma GN 421 odbitaka (samo odbitak, bez minus spalete)
  let ukupnoSpalete = 0;       // ⭐ v447: suma GN 421 špaleta (pozitivan dodatak)
  // ⭐ v501 (Ivan, 19.05.2026): defDebljinaM se sad čita PER PROČELJE unutar _knjigaOtvoriZaProcelje
  //   (helper čita p.debljina_izolacije_m). Outer var je fallback default za helper koji 
  //   nema p.* kontekst (sigurno bi to bilo nikad ali zadržavam za backward compat).
  const defDebljinaM_FALLBACK = 0.15;
  
  // ⭐ HELPERI (premjenuti na vrh u v339 da budu dostupni za UKUPNO PROČELJA tablicu I sekciju plohe):
  
  // Point-in-polygon (ray casting)
  const _ploheTockaUPoligonu = (x, y, points) => {
    if (!Array.isArray(points) || points.length < 3) return false;
    let inside = false;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
      const xi = points[i].x, yi = points[i].y;
      const xj = points[j].x, yj = points[j].y;
      const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  };
  
  // Je li stavka UNUTAR plohe (klasifikacija + centroid fallback)
  const _ploheStavkaUnutarPlohe = (stavka, plohaPts) => {
    if (!stavka || !Array.isArray(plohaPts) || plohaPts.length < 3) return false;
    if (stavka._pribraja_brutu === true) return false;
    if (stavka._pribraja_brutu === false) return true;
    const pts = Array.isArray(stavka.points) ? stavka.points 
              : Array.isArray(stavka.pointsPx) ? stavka.pointsPx : null;
    if (!pts || pts.length < 3) return false;
    const cx = pts.reduce((s, p) => s + p.x, 0) / pts.length;
    const cy = pts.reduce((s, p) => s + p.y, 0) / pts.length;
    return _ploheTockaUPoligonu(cx, cy, plohaPts);
  };
  
  // m² stavke (PB ili D) sa manual override
  const _ploheStavkaM2 = (stavka) => {
    const kol = parseInt(stavka.kolicina || 1) || 1;
    const m2 = (stavka._manual_override && stavka._manual_sirina && stavka._manual_visina)
      ? parseFloat(stavka._manual_sirina) * parseFloat(stavka._manual_visina)
      : (parseFloat(stavka._m2 || stavka.m2 || 0) || 0);
    return m2 * kol;
  };
  
  // ⭐ v339 KRITIČNI HELPER: izračunaj GN 421 otvore za pročelje
  //   IDENTIČNA logika per-pročelje sheet-a (generirajExcelProcjenuRavnine):
  //   1) otvorMjere: m2 = sirina×visina (manual) ili o.m2 || o._m2 || sirina×visina
  //      ⭐ KLJUČNO: m2 prije _m2! Inače stari _m2 (pre-manual-override) krivi rezultat.
  //   2) Per-otvor debljina iz plohe gdje je centroid otvora (debljina_cm/100)
  //   3) Klasifikacija: m² > 5 → veliki + špalete; m² > 3 → srednji
  //   
  //   Vraća: { otvoriUkupno, otvoriOdbitak, spaleteDodatak, otvoriDetalji }
  //   gdje je otvoriDetalji array s per-otvor detaljima za debug.
  const _knjigaOtvoriZaProcelje = (p) => {
    const otvori = Array.isArray(p.otvori) ? p.otvori : [];
    const ravnine = Array.isArray(p.ravnine) ? p.ravnine : [];
    
    // ⭐ v501 (Ivan, 19.05.2026): PER-PROČELJE default debljina izolacije.
    //   Ranije: outer scope `defDebljinaM` iz prvog pročelja se koristio za sva pročelja.
    //   Sad: čitamo iz tog konkretnog `p` objekta — sva pročelja u multi-knjizi 
    //   mogu imati različite debljine izolacije.
    const defDebljinaM = parseFloat(p?.debljina_izolacije_m) || defDebljinaM_FALLBACK;
    
    // Per-otvor debljina (centroid u plohi → debljina_cm × 0.01 → fallback defDebljinaM)
    // ⭐ v357 (Ivan, 16.05.2026): EKSPLICITAN OVERRIDE prvo (o.debljina_otvor_cm) — 
    //   korisnik može u app-u (edit otvor olovka) eksplicitno definirati debljinu za 
    //   GN 421 špalete ako otvor nije jasno unutar jedne plohe.
    const debljinaZaOtvor = (o) => {
      if (o && o.debljina_otvor_cm != null && o.debljina_otvor_cm !== '') {
        const v = parseFloat(o.debljina_otvor_cm);
        if (isFinite(v) && v > 0) return v / 100;
      }
      const pts = o.points || o.pointsPx || o.kutoviPx;
      if (!Array.isArray(pts) || pts.length < 3) return defDebljinaM;
      const cx = pts.reduce((s, pt) => s + pt.x, 0) / pts.length;
      const cy = pts.reduce((s, pt) => s + pt.y, 0) / pts.length;
      for (const rv of ravnine) {
        if (o._ravnina_id && rv.id && o._ravnina_id !== rv.id) continue;
        const plohe = Array.isArray(rv.plohe) ? rv.plohe : [];
        for (const pl of plohe) {
          const plohaPts = Array.isArray(pl.pointsPx) ? pl.pointsPx 
                         : Array.isArray(pl.points) ? pl.points : null;
          if (plohaPts && _ploheTockaUPoligonu(cx, cy, plohaPts)) {
            if (pl.debljina_cm != null) {
              const d = parseFloat(pl.debljina_cm) / 100;
              if (d > 0) return d;
            }
          }
        }
      }
      return defDebljinaM;
    };
    
    // otvorMjere — identičan per-pročelje (HYBRID: manual=stored prefer, canvas=Š×V prefer)
    // ⭐ v450 (Ivan, 18.05.2026): vidi detaljan komentar L31941.
    const otvorMjere = (o) => {
      const isManual = !!(o._manual_override && o._manual_sirina && o._manual_visina);
      const sirina = isManual ? parseFloat(o._manual_sirina) : parseFloat(o.sirina_m || 0);
      const visina = isManual ? parseFloat(o._manual_visina) : parseFloat(o.visina_m || 0);
      const sirinaXvisina = sirina * visina;
      const m2Stored = parseFloat(o.m2 || o._m2 || 0);
      const m2 = isManual
        ? (sirinaXvisina > 0 ? sirinaXvisina : m2Stored)
        : (sirinaXvisina > 0 ? sirinaXvisina : (m2Stored || 0));
      return { sirina, visina, m2 };
    };
    
    let otvoriUkupno = 0, otvoriOdbitak = 0, spaleteDodatak = 0;
    const otvoriDetalji = [];
    otvori.forEach((o) => {
      const { sirina, visina, m2 } = otvorMjere(o);
      const kol = parseInt(o.kolicina || 1) || 1;
      otvoriUkupno += m2 * kol;
      let odbitak = 0, spalete = 0;
      // ⭐ v446 (Ivan, 18.05.2026): sqrt fallback za Š/V kad su 0 ali m² > 0 (npr. Prozor 5 14.13m² 
      //   bez stored Š/V). PRIJE: špaleta = 0 (jer guard "if (s>0 && v>0)" odbio sve) → krivi NETO 
      //   u svim listovima. SAD: aproksimacija √m² (server-side limit; pravi Š/V bi trebao stići iz FE).
      let sFs = sirina, vFs = visina, fallbackUsed = false;
      if ((sFs <= 0 || vFs <= 0) && m2 > 0) {
        sFs = vFs = Math.sqrt(m2);
        fallbackUsed = true;
      }
      if (p.obracun_mod === 'spalete') {  // ⭐ v135.7.502.20.319 (Ivan): BUG E — špalete mod: cijeli otvor odbijen, špalete u m' (zaseban list)
        odbitak = m2 * kol;
      } else if (m2 > 5) {
        odbitak = (m2 - 3) * kol;
        const debM = debljinaZaOtvor(o);
        if (sFs > 0 && vFs > 0) {
          spalete = (2 * vFs + sFs) * debM * kol;
        }
      } else if (m2 > 3) {
        odbitak = (m2 - 3) * kol;
      }
      otvoriOdbitak += odbitak;
      spaleteDodatak += spalete;
      // ⭐ v446: dodajem _spalete_s/_spalete_v (effective za formula display) + _spalete_fallback flag
      otvoriDetalji.push({ 
        m2, kol, sirina, visina, odbitak, spalete,
        _spalete_s: sFs, _spalete_v: vFs, _spalete_fallback: fallbackUsed
      });
    });
    
    return { otvoriUkupno, otvoriOdbitak, spaleteDodatak, otvoriDetalji };
  };
  
  procelja.forEach((p, i) => {
    const ravnine = Array.isArray(p.ravnine) ? p.ravnine : [];
    let plohaSum = 0;  // ⭐ v448: razdvojen iz "bruto" radi jasnoće — Σ samih plohe (bez izvan stavki)
    ravnine.forEach(rv => {
      if (Array.isArray(rv.plohe) && rv.plohe.length > 0) {
        // ⭐ Backward compat: stari record-i imaju _m2, novi m2
        rv.plohe.forEach(pl => plohaSum += (parseFloat(pl._m2 || pl.m2) || 0) * (parseInt(pl.kolicina || 1) || 1));
      } else if (parseFloat(rv.ploha_m2 || 0) > 0) {
        plohaSum += parseFloat(rv.ploha_m2 || 0);
      }
      // NOTE: bez plohe → 0 (sinkronizirano s clientom + multi-knjiga sumiranjem, NIKAD bbox)
    });
    
    // ⭐ v339 (Ivan): GN 421 otvori koristi CENTRALNI helper (identično per-pročelje)
    //    Prije v339: inline blok je koristio o._m2 || o.m2 (krivi prioritet) — krivih brojeva
    //    za otvore s manual override (_m2 = stara vrijednost).
    //    Plus: Ivan traži da "Otvori GN 421" stupac uračuna i špalete (= neto odbitak).
    const { otvoriUkupno, otvoriOdbitak, spaleteDodatak } = _knjigaOtvoriZaProcelje(p);
    // Neto odbitak (= ono što stvarno smanjuje plohu) = odbitak − špalete
    const otvoriGN421Neto = Math.max(0, otvoriOdbitak - spaleteDodatak);
    
    // ⭐ v448 (Ivan, 18.05.2026): PB i D RAZDVOJENI na unutar/izvan plohe (kao u per-procelje sheet-u).
    //   PRIJE (v135.7.20): bruto = samo Σ plohe — IZVAN-plohe stavke (PB van plohe, D van plohe) NISU 
    //                       bile u bruto stupcu Ukupno tablice → krivih brojeva za pročelja s 
    //                       atika/cijevi/dodatka iznad/oko plohe.
    //   SAD (v448):         bruto = Σ plohe + barijere IZVAN + debljine IZVAN.
    //                       neto = bruto − barijere UNUTAR − debljine UNUTAR − otvoriOdbitak + spalete.
    //   Razvijene i sitnice (m²) NISU u brutu — Ivan: "samo PB i D crtane VAN plohe".
    let barijereUnutarSum_448 = 0, barijereIzvanSum_448 = 0;
    // ⭐ v457 (Ivan, 18.05.2026): dodatni akumulator za "izvan plohe" prema 3-razinskoj logici
    //   helpera _izracunajSumeProcjeneIzKnjige (L28261+). Razlikuje se od barijereIzvanSum_448 
    //   (koji koristi samo legacy `_unutar_plohe === false`).
    //   Razlika: pribraja_brutu može biti true zbog (1) eksplicitnog korisnikovog odabira 
    //   pop-upom (_pribraja_brutu), (2) auto 75% klasifikacije (_van_plohe_pribraja_bruto), 
    //   (3) legacy `_unutar_plohe === false`. Ovo se DODAJE u BRUTO stupac UKUPNO PROČELJA tablice.
    let barijereVanPloheSum_457 = 0;
    (p.barijere || []).forEach(b => {
      const kol = parseInt(b.kolicina || 1) || 1;
      // ⭐ v448: čitanje m² sinhronizirano s per-procelje sheet-om (prefer svježi Š×V, fallback cached)
      const isManual = !!(b._manual_override && b._manual_sirina && b._manual_visina);
      const sirina = isManual ? parseFloat(b._manual_sirina) : parseFloat(b.sirina_m || 0);
      const visina = isManual ? parseFloat(b._manual_visina) : parseFloat(b.visina_m || 0);
      const sXv = sirina * visina;
      const m2Cached = parseFloat(b._m2 || b.m2 || 0);
      let m2 = sXv > 0 ? sXv : m2Cached;
      // Backward-compat: ako ima m2_unutar/m2_izvan, koristi tu razdiobu direktno
      if (typeof b.m2_unutar === 'number' || typeof b.m2_izvan === 'number') {
        const mU = (parseFloat(b.m2_unutar) || 0) * kol;
        const mI = (parseFloat(b.m2_izvan) || 0) * kol;
        barijereUnutarSum_448 += mU;
        barijereIzvanSum_448 += mI;
        m2 = (parseFloat(b.m2_unutar) || 0) + (parseFloat(b.m2_izvan) || 0);
      } else {
        const m2Total = m2 * kol;
        if (b._unutar_plohe === false) barijereIzvanSum_448 += m2Total;
        else barijereUnutarSum_448 += m2Total;  // _unutar_plohe=true ILI undefined (legacy: pretpostavi unutar)
      }
      // ⭐ v457: 3-razinska prioritetna logika (sinkrono s _izracunajSumeProcjeneIzKnjige):
      //   1. _pribraja_brutu (eksplicitni korisnikov izbor)
      //   2. _van_plohe_pribraja_bruto (auto 75% klasifikacija)
      //   3. _unutar_plohe === false (legacy)
      let pribraja_457;
      if (b._pribraja_brutu !== undefined) pribraja_457 = !!b._pribraja_brutu;
      else if (b._van_plohe_pribraja_bruto !== undefined) pribraja_457 = !!b._van_plohe_pribraja_bruto;
      else pribraja_457 = (b._unutar_plohe === false);
      if (pribraja_457) barijereVanPloheSum_457 += m2 * kol;
    });
    let debljineUnutarSum_448 = 0, debljineIzvanSum_448 = 0;
    // ⭐ v457: isti pattern za debljine
    let debljineVanPloheSum_457 = 0;
    (p.debljine || []).forEach(d => {
      const kol = parseInt(d.kolicina || 1) || 1;
      const isManual = !!(d._manual_override && d._manual_sirina && d._manual_visina);
      const sirina = isManual ? parseFloat(d._manual_sirina) : parseFloat(d.sirina_m || 0);
      const visina = isManual ? parseFloat(d._manual_visina) : parseFloat(d.visina_m || 0);
      const sXv = sirina * visina;
      const m2Cached = parseFloat(d._m2 || d.m2 || 0);
      let m2 = sXv > 0 ? sXv : m2Cached;
      if (typeof d.m2_unutar === 'number' || typeof d.m2_izvan === 'number') {
        const mU = (parseFloat(d.m2_unutar) || 0) * kol;
        const mI = (parseFloat(d.m2_izvan) || 0) * kol;
        debljineUnutarSum_448 += mU;
        debljineIzvanSum_448 += mI;
        m2 = (parseFloat(d.m2_unutar) || 0) + (parseFloat(d.m2_izvan) || 0);
      } else {
        const m2Total = m2 * kol;
        if (d._unutar_plohe === false) debljineIzvanSum_448 += m2Total;
        else debljineUnutarSum_448 += m2Total;
      }
      let pribraja_457;
      if (d._pribraja_brutu !== undefined) pribraja_457 = !!d._pribraja_brutu;
      else if (d._van_plohe_pribraja_bruto !== undefined) pribraja_457 = !!d._van_plohe_pribraja_bruto;
      else pribraja_457 = (d._unutar_plohe === false);
      if (pribraja_457) debljineVanPloheSum_457 += m2 * kol;
    });
    // ⭐ v457 (Ivan, 18.05.2026): Razvijene i sitnice m² SADA idu u BRUTO (uskladujemo s 
    //   FE pregledom — DB polje `ukupna_fasada_m2` koje računa _izracunajSumeProcjeneIzKnjige 
    //   helper na L28289 uvijek je uključio razvijene + sitnice + van_plohe PB/D.
    //   Excel Ukupno tablica je do v456 bila inkonzistentna (samo plohe + PB/D izvan), 
    //   što je dovodilo do diferencije između FE pregleda (268.4 bruto) i Excel-a.
    //   Sad: Excel = FE = formula iz _izracunajSumeProcjeneIzKnjige.
    let razvijeneSum = 0, sitniceM2 = 0;
    (p.razvijene || []).forEach(rs => {
      const kol = parseInt(rs.kolicina || 1) || 1;
      const m2 = parseFloat(rs._m2 || rs.m2 || 0) || 0;
      razvijeneSum += m2 * kol;
    });
    (p.sitnice || []).forEach(s => {
      if (s.jedinica === 'm2' || s.jedinica === 'm²' || !s.jedinica) {
        const m2Jedan = parseFloat(s.kolicina || s.m2 || 0) || 0;
        const kol = parseInt(s.stavka_kolicina || 1) || 1;
        sitniceM2 += m2Jedan * kol;
      }
    });
    
    // ⭐ v457 (Ivan, 18.05.2026): BRUTO formula uskladena s FE pregledom (_izracunajSumeProcjeneIzKnjige L28289).
    //   PRIJE (v448): bruto = plohaSum + barijereIzvanSum_448 + debljineIzvanSum_448  
    //                  → izostavljeno razvijene + sitnice + 3-razinska logika za PB/D izvan
    //   SAD (v457):   bruto = plohaSum + razvijeneSum + sitniceM2 + barijereVanPloheSum_457 + debljineVanPloheSum_457
    //                  → identično FE pregledu (ukupna_fasada_m2 polje u DB)
    //   Razlog: Excel "UKUPNO PROČELJA" mora odgovarati onome što korisnik vidi u app pregledu.
    //   Ivan: "Bruto stupac uračuna i površine koje su izvan plohe (dodaju se bruto), svako za svoje pročelje"
    const bruto = plohaSum + razvijeneSum + sitniceM2 + barijereVanPloheSum_457 + debljineVanPloheSum_457;
    const neto = Math.max(0, bruto - otvoriOdbitak + spaleteDodatak);
    const brojPloha = ravnine.reduce((s, rv) => s + (Array.isArray(rv.plohe) ? rv.plohe.length : 0), 0);
    ukupnoBruto += bruto;
    ukupnoOtvori += otvoriUkupno;
    // ⭐ v447 (Ivan, 18.05.2026): "Otvori GN 421" stupac sad pokazuje SAMO odbitak (ne neto),
    //    a "Špalete (+)" stupac pokazuje špalete pozitivno. PRIJE v339: ukupnoOtvoriGN += otvoriGN421Neto.
    //    Razlog promjene: nadzor želi vidjeti odbitak i špalete RAZDVOJENE (jer su to dvije 
    //    različite stavke u GN 421 normi — odbitak otvora i kreditiranje špaleta).
    ukupnoOtvoriGN += otvoriOdbitak;
    ukupnoSpalete += spaleteDodatak;
    ukupnoNeto += neto;
    
    const isAlt = (i % 2 === 1);
    // ⭐ v447 (Ivan, 18.05.2026): novi layout — 8 kolona:
    //   # | Naziv | Bruto m² | Otvori GN 421 (negativno) | Špalete (+) (pozitivno) | Neto m² | Ravnine | Plohe
    //   "Otvori m²" stupac uklonjen (suvišan podatak, nadzor već vidi GN razdvojen na odbitak+špalete).
    const cells = [
      { v: i + 1, fmt: null, align: 'center' },
      { v: p.oznaka || `Nacrt ${i+1}`, fmt: null, align: 'left' },
      { v: bruto, fmt: '0.00', align: 'right', color: BLUE },
      { v: otvoriOdbitak > 0 ? -otvoriOdbitak : 0, fmt: '0.00', align: 'right', color: 'FFEAB308', italic: true },
      { v: spaleteDodatak > 0 ? spaleteDodatak : 0, fmt: '0.00', align: 'right', color: 'FF7C3AED', italic: true },
      { v: neto, fmt: '0.00', align: 'right', color: GREEN, bold: true },
      { v: ravnine.length, fmt: null, align: 'right' },
      { v: brojPloha, fmt: null, align: 'right' }
    ];
    cells.forEach((cell, j) => {
      const c = summaryWs.getCell(r, j + 1);
      c.value = cell.v;
      c.font = { size: 10, bold: !!cell.bold, italic: !!cell.italic, color: { argb: cell.color || DARK } };
      c.alignment = { horizontal: cell.align, vertical: 'middle', indent: cell.align === 'left' ? 1 : 0 };
      if (cell.fmt) c.numFmt = cell.fmt;
      if (isAlt) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
      c.border = { 
        top: { style: 'hair', color: { argb: BORD } }, 
        bottom: { style: 'hair', color: { argb: BORD } }
      };
    });
    summaryWs.getRow(r).height = 18;
    r++;
  });
  
  // UKUPNO red — 8 kolona
  // ⭐ v447 (Ivan, 18.05.2026): novi layout — Otvori m² uklonjen, Špalete (+) dodan.
  //   col 4 = GN 421 odbitak (negativno), col 5 = Špalete (pozitivno), col 6 = Neto.
  const totalCells = [
    { v: '', },
    { v: 'UKUPNO', align: 'left', bold: true },
    { v: ukupnoBruto, fmt: '0.00', align: 'right', color: BLUE, bold: true },
    { v: ukupnoOtvoriGN > 0 ? -ukupnoOtvoriGN : 0, fmt: '0.00', align: 'right', color: 'FFEAB308', bold: true },
    { v: ukupnoSpalete, fmt: '0.00', align: 'right', color: 'FF7C3AED', bold: true },
    { v: ukupnoNeto, fmt: '0.00', align: 'right', color: GREEN, bold: true },
    { v: '', },
    { v: '', },
  ];
  totalCells.forEach((cell, j) => {
    const c = summaryWs.getCell(r, j + 1);
    c.value = cell.v;
    c.font = { size: 11, bold: !!cell.bold, color: { argb: cell.color || DARK } };
    c.alignment = { horizontal: cell.align || 'right', vertical: 'middle', indent: cell.align === 'left' ? 1 : 0 };
    if (cell.fmt) c.numFmt = cell.fmt;
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
    c.border = { 
      top: { style: 'medium', color: { argb: DARK } }, 
      bottom: { style: 'double', color: { argb: DARK } }
    };
  });
  summaryWs.getRow(r).height = 24;
  r += 2;
  
  // ⭐ v369 (Ivan, 16.05.2026) Točka 3: Objašnjenje formule za nadzora — sistematski 
  //   redovi koji jasno pokazuju kako se došlo do BRUTO i NETO.
  //   IVAN: "U listu ukupno kod sekcije ukupno pročelja treba Nadzoru objasniti što 
  //   sve ulazi u izračun Bruto i Neto, dodaj dolje redove koji sistematski objasnjavaju."
  
  // Naslov sekcije objašnjenja
  summaryWs.mergeCells(r, 1, r, 8);
  const formulaNaslov = summaryWs.getCell(r, 1);
  formulaNaslov.value = '📐 OBJAŠNJENJE FORMULE — kako se izračunava BRUTO i NETO m²';
  formulaNaslov.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  formulaNaslov.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0EA5E9' } };  // sky-500
  formulaNaslov.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  summaryWs.getRow(r).height = 22;
  r++;
  
  // 4 strukturirana reda — svaki s naslovom + formulom
  const formulaRedovi = [
    {
      label: '① BRUTO m² (po nacrtu)',
      formula: '= Σ ploha svih ravnina  +  razvijene širine (atike, vijenci, sokli)  +  sitnice (m²)  +  Pož. barijere VAN plohe  +  Razl. debljine VAN plohe',
      napomena: 'Sve dodatne stavke izvan plohe (PB van plohe, D van plohe, atika, vijenac, sokl, sitnice m²) PRIBRAJAJU se BRUTO. Ne uključuje otvore — oni se prvo zbroje pa odbiju u koraku ②.'
    },
    {
      label: '② OTVORI GN 421 (m²)',
      formula: '= Σ otvora 3–5 m² × (m²−3) × kom  +  Σ otvora >5 m² × (m²−3) × kom',
      napomena: 'Otvori ≤ 3 m² PO KOMADU se NE odbijaju (uračunati u plohu po normi GN 421).'
    },
    {
      label: '③ ŠPALETE (m²) — DODATAK za otvore >5 m²',
      formula: '= Σ ((2 × visina + širina) × debljina_izolacije × kom)  za otvore > 5 m²',
      napomena: 'Špalete se DODAJU u Neto (kompenzacija za bočne plohe otvora >5 m²).'
    },
    {
      label: '④ NETO m² = Bruto − Otvori GN 421 + Špalete',
      formula: '= BRUTO − OTVORI GN 421 + ŠPALETE',
      napomena: 'NETO je konačna obračunska površina za fakturiranje fasaderskih radova po normi GN 421. Pož. barijere i Razl. debljine (unutar plohe) fakturiraju se POSEBNO (sekcije C i D u per-procelje listovima), ne smanjuju EPS NETO.'
    }
  ];
  
  formulaRedovi.forEach((red, idx) => {
    // Label red (lijevo) — naziv koraka, bold
    summaryWs.mergeCells(r, 1, r, 2);
    const lbl = summaryWs.getCell(r, 1);
    lbl.value = red.label;
    lbl.font = { bold: true, size: 10, color: { argb: 'FF1E40AF' } };  // blue-800
    lbl.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEFF6FF' } };  // blue-50
    lbl.alignment = { horizontal: 'left', vertical: 'top', indent: 1, wrapText: true };
    lbl.border = { top: { style: 'thin', color: { argb: 'FFCBD5E1' } }, bottom: { style: 'thin', color: { argb: 'FFCBD5E1' } } };
    
    // Formula red (desno, span 3-8) — formula + napomena
    summaryWs.mergeCells(r, 3, r, 8);
    const frm = summaryWs.getCell(r, 3);
    frm.value = { 
      richText: [
        { text: red.formula + '\n', font: { size: 10, color: { argb: 'FF0F172A' }, name: 'Consolas' } },
        { text: '   ' + red.napomena, font: { italic: true, size: 9, color: { argb: 'FF64748B' } } }
      ]
    };
    frm.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: idx % 2 === 0 ? 'FFFAFBFC' : 'FFF1F5F9' } };
    frm.alignment = { horizontal: 'left', vertical: 'top', indent: 1, wrapText: true };
    frm.border = { top: { style: 'thin', color: { argb: 'FFCBD5E1' } }, bottom: { style: 'thin', color: { argb: 'FFCBD5E1' } } };
    
    summaryWs.getRow(r).height = 36;
    r++;
  });
  
  // Vizualni sažetak na kraju — finalna formula u jednom redu, bold/highlighted
  // ⭐ v458 (Ivan, 18.05.2026): formula POPRAVLJENA — od v449 NETO ne oduzima PB/D unutar plohe
  //   (oni se fakturiraju POSEBNO u sekcijama C i D). Stari tekst je bio zastario.
  r++;
  summaryWs.mergeCells(r, 1, r, 8);
  const sazetak = summaryWs.getCell(r, 1);
  sazetak.value = '✓ FINALNI IZRAČUN:   NETO m² = BRUTO − OTVORI GN 421 + ŠPALETE';
  sazetak.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  sazetak.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF059669' } };  // emerald-600
  sazetak.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
  summaryWs.getRow(r).height = 26;
  r++;
  
  r++; // razmak
  
  // Napomena
  summaryWs.mergeCells(r, 1, r, 8);
  const note = summaryWs.getCell(r, 1);
  note.value = '💡 Detaljni pregled svakog nacrta je u zasebnom sheet-u (P1, P2, P3...).';
  note.font = { italic: true, size: 9.5, color: { argb: 'FF6b7280' } };
  note.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  r++;
  
  // ═══ 3b. PLOHE PO TIPU IZOLACIJE ═══
  // ⭐ v335 (Ivan): grupiranje plohe po MATERIJAL + DEBLJINA (npr. "EPS 16cm", "MW 15cm")
  //    Sekcija pokazuje POVRŠINU PROČELJA — TJ. EFEKTIVNU m² svake plohe nakon što 
  //    se odbiju drugi materijali UNUTAR plohe (požarne barijere PB, različite 
  //    debljine D koje su konceptualno U plohi).
  //    
  //    Formula (identična canvas prikazu): 
  //      efektivnoM2 = (ploha._m2 × kolicina) − Σ PB_unutar − Σ D_unutar
  //    
  //    "Unutar plohe" znači: ako stavka ima _pribraja_brutu===false → eksplicit U plohi;
  //      ako _pribraja_brutu===true → eksplicit IZVAN plohe → ne odbija;
  //      legacy (undefined) → centroid stavke u poligonu plohe.
  //    
  //    Primjer iz canvas-a (Zapadno pročelje, Ivan screenshot v334):
  //      Ploha "Zapad" (EPS 16cm): bruto 123.07 m², D1 unutar = 6.67 m² 
  //      → efektivnoM2 (EPS 16cm) = 123.07 − 6.67 = 116.40 m²
  //    
  //    Grupa "EPS 16cm" tako sumira sve takve efektivne površine kroz sva pročelja.
  r++; // praznina
  
  // Agregiraj plohe iz svih pročelja
  //   Ključ grupe: "MATERIJAL DEBLJINAcm" (npr. "EPS 16cm")
  //   Item: { proceljeOznaka, brutoM2, pbUnutar, dUnutar, otvoriGN, efektivnoM2 }
  //   ⭐ v339 (Ivan): GN 421 otvori sad koristi CENTRALNI helper _knjigaOtvoriZaProcelje 
  //      (definiran gore prije procelja.forEach loop-a) — identičan per-pročelje sheet-u.
  //      Prije v339: inline blok koristio o._m2 || o.m2 (krivi prioritet) — kriva razlika.
  const ploheGrupe = new Map();
  procelja.forEach((p, pi) => {
    const ravnine = Array.isArray(p.ravnine) ? p.ravnine : [];
    const barijere = Array.isArray(p.barijere) ? p.barijere : [];
    const debljine = Array.isArray(p.debljine) ? p.debljine : [];
    
    // ⭐ v339: Koristi centralni helper (identično per-pročelje sheet-u)
    const { otvoriOdbitak: proceljeOtvoriOdbitak, spaleteDodatak: proceljeSpalete } 
      = _knjigaOtvoriZaProcelje(p);
    // Neto otvori = odbitak − špalete (špalete su dodatni materijal koji se vraća brutu)
    const proceljeOtvoriNeto = Math.max(0, proceljeOtvoriOdbitak - proceljeSpalete);
    
    // Skupi sve plohe pročelja PRVO (da znamo totalBruto pa raspored otvora)
    const proceljePlohe = [];
    ravnine.forEach((rv) => {
      if (!Array.isArray(rv.plohe)) return;
      rv.plohe.forEach((ploha) => {
        const m2Jedan = (ploha._manual_override && ploha._manual_sirina && ploha._manual_visina)
          ? parseFloat(ploha._manual_sirina) * parseFloat(ploha._manual_visina)
          : (parseFloat(ploha._m2 || ploha.m2 || 0) || 0);
        const kol = parseInt(ploha.kolicina || 1) || 1;
        const brutoM2 = m2Jedan * kol;
        if (brutoM2 <= 0) return;
        
        // Polygon plohe za centroid checkove
        const plohaPts = Array.isArray(ploha.pointsPx) ? ploha.pointsPx 
                       : Array.isArray(ploha.points) ? ploha.points : null;
        
        // Suma PB unutar ove plohe
        let pbUnutar = 0;
        if (plohaPts && plohaPts.length >= 3) {
          barijere.forEach((b) => {
            if (_ploheStavkaUnutarPlohe(b, plohaPts)) {
              pbUnutar += _ploheStavkaM2(b);
            }
          });
        }
        
        // Suma D unutar ove plohe
        let dUnutar = 0;
        if (plohaPts && plohaPts.length >= 3) {
          debljine.forEach((d) => {
            if (_ploheStavkaUnutarPlohe(d, plohaPts)) {
              dUnutar += _ploheStavkaM2(d);
            }
          });
        }
        
        // Ključ grupe: materijal + debljina_cm
        let displayTip;
        if (ploha.materijal) {
          const debCm = (ploha.debljina_cm != null && ploha.debljina_cm !== '') 
            ? `${ploha.debljina_cm}cm` 
            : '';
          displayTip = debCm ? `${ploha.materijal} ${debCm}` : ploha.materijal;
        } else {
          displayTip = (ploha.opis || '— bez tipa').trim() || '— bez tipa';
        }
        
        proceljePlohe.push({
          proceljeOznaka: p.oznaka || `Nacrt ${pi+1}`,
          displayTip: displayTip,
          brutoM2: brutoM2,
          pbUnutar: pbUnutar,
          dUnutar: dUnutar
        });
      });
    });
    
    // Atribuiraj otvori_GN421 po plohi PROPORCIONALNO po bruto m²
    //   Ako pročelje ima samo 1 plohu → 100% otvora na nju
    //   Ako ima više → raspored po udjelu bruto m²
    // ⭐ v446 (Ivan, 18.05.2026): razdvojeni odbitak i špalete (opcija B). 
    //   Tablica sad ima zaseban "Špalete (+)" stupac (vidi header dolje).
    //   efektivnoM2 = bruto − PB − D − odbitak + špalete (opcija B: špalete kreditiraju natrag)
    const totalBruto = proceljePlohe.reduce((s, x) => s + x.brutoM2, 0);
    proceljePlohe.forEach((pd) => {
      const udio = totalBruto > 0 ? (pd.brutoM2 / totalBruto) : 0;
      pd.otvoriOdbitak = proceljeOtvoriOdbitak * udio;
      pd.otvoriSpalete = proceljeSpalete * udio;
      // Zadržavam stari field za backward-compat (drugi kod ga čita)
      pd.otvoriGN = pd.otvoriOdbitak - pd.otvoriSpalete;
      pd.efektivnoM2 = Math.max(0, pd.brutoM2 - pd.pbUnutar - pd.dUnutar - pd.otvoriOdbitak + pd.otvoriSpalete);
    });
    
    // Push u grupe (po displayTip)
    proceljePlohe.forEach((pd) => {
      if (pd.efektivnoM2 <= 0) return;
      const normKey = _fasNormalizirajOpis(pd.displayTip);
      if (!ploheGrupe.has(normKey)) {
        ploheGrupe.set(normKey, { displayTip: pd.displayTip, items: [], subtotal: 0 });
      }
      const g = ploheGrupe.get(normKey);
      g.items.push({
        proceljeOznaka: pd.proceljeOznaka,
        brutoM2: pd.brutoM2,
        pbUnutar: pd.pbUnutar,
        dUnutar: pd.dUnutar,
        otvoriOdbitak: pd.otvoriOdbitak,  // ⭐ v446
        otvoriSpalete: pd.otvoriSpalete,  // ⭐ v446
        otvoriGN: pd.otvoriGN,
        efektivnoM2: pd.efektivnoM2
      });
      g.subtotal += pd.efektivnoM2;
    });
  });
  
  if (ploheGrupe.size > 0) {
    // Naslov sekcije
    summaryWs.mergeCells(r, 1, r, 8);
    const ph = summaryWs.getCell(r, 1);
    ph.value = '📐 POVRŠINE NACRTI — PO TIPU IZOLACIJE';
    ph.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ph.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BLUE } };
    ph.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    summaryWs.getRow(r).height = 22;
    r++;
    
    // Header reda — 8 kolona:
    //   # | Pročelje | Bruto m² | Požarne barijere | Različite debljine | GN 421 otvori | Špalete (+) | = Površina
    // ⭐ v338 (Ivan): dodan stupac "GN 421 otvori"
    // ⭐ v446 (Ivan, 18.05.2026): dodan zaseban "Špalete (+)" stupac (prije bilo prazna rezerva).
    //   Stupac 6 "GN 421 otvori" sad ima SAMO odbitak (negativan), stupac 7 "Špalete (+)" ima 
    //   špalete (pozitivan dodatak), stupac 8 "= Površina" je rezultat (efektivnoM2).
    const ploheHeaders = ['#', 'Nacrt', 'Bruto m²', 'Požarne barijere', 'Različite debljine', 'GN 421 otvori', 'Špalete (+)', '= Površina'];
    ploheHeaders.forEach((h, j) => {
      const c = summaryWs.getCell(r, j + 1);
      c.value = h;
      c.font = { bold: true, size: 9.5, color: { argb: 'FFFFFFFF' } };
      c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
      c.alignment = { horizontal: j <= 1 ? 'left' : 'right', vertical: 'middle', indent: j <= 1 ? 1 : 0, wrapText: true };
      c.border = { top: { style: 'thin', color: { argb: BORD } }, bottom: { style: 'thin', color: { argb: BORD } } };
    });
    summaryWs.getRow(r).height = 26; // viši header za wrap tekstove
    r++;
    
    // Render: po grupama (sortirane silazno po subtotalu), unutar grupe stavke + subtotal
    const ploheGrupeArr = Array.from(ploheGrupe.values()).sort((a, b) => b.subtotal - a.subtotal);
    let totalPloheM2 = 0;
    let totalStavki = 0;
    let stavkaNum = 0;
    
    ploheGrupeArr.forEach((g) => {
      // Header grupe — naziv tipa izolacije (npr. "EPS 16cm")
      summaryWs.mergeCells(r, 1, r, 8);
      const gh = summaryWs.getCell(r, 1);
      gh.value = `▸ ${g.displayTip}  ·  ${g.items.length} nacrt${g.items.length === 1 ? '' : 'a'}`;
      gh.font = { bold: true, size: 10.5, color: { argb: 'FFFFFFFF' } };
      gh.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BLUE } };
      gh.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      summaryWs.getRow(r).height = 20;
      r++;
      
      // Stavke u grupi
      g.items.forEach((it) => {
        stavkaNum++;
        // ⭐ v338 (Ivan): dodan GN 421 otvori stupac (kolona 6, prije = Površina kolone 7)
        //   # | Pročelje | Bruto m² | Požarne barijere | Različite debljine | GN 421 otvori | Špalete (+) | = Površina
        // ⭐ v446 (Ivan): razdvojen špalete u zaseban stupac 7, = Površina shift 7→8
        const cells = [
          { v: stavkaNum, align: 'center' },
          { v: it.proceljeOznaka, align: 'left' },
          { v: it.brutoM2, fmt: '0.00', align: 'right' },
          { v: it.pbUnutar > 0 ? -it.pbUnutar : '', fmt: '0.00', align: 'right', color: 'FFEF4444' },
          { v: it.dUnutar > 0 ? -it.dUnutar : '', fmt: '0.00', align: 'right', color: 'FF06b6d4' },
          { v: it.otvoriOdbitak > 0 ? -it.otvoriOdbitak : '', fmt: '0.00', align: 'right', color: 'FFEAB308' },
          { v: it.otvoriSpalete > 0 ? it.otvoriSpalete : '', fmt: '0.00', align: 'right', color: 'FF7C3AED' },
          { v: it.efektivnoM2, fmt: '0.00', align: 'right', color: BLUE, bold: true }
        ];
        cells.forEach((cell, j) => {
          const c = summaryWs.getCell(r, j + 1);
          c.value = cell.v;
          c.font = { size: 10, bold: !!cell.bold, color: { argb: cell.color || DARK } };
          c.alignment = { horizontal: cell.align || 'right', vertical: 'middle', indent: (cell.align === 'left' || cell.align === 'center') ? 1 : 0 };
          if (cell.fmt && cell.v !== '') c.numFmt = cell.fmt;
          c.border = { bottom: { style: 'hair', color: { argb: 'FFE5E7EB' } } };
          if (r % 2 === 0) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
        });
        summaryWs.getRow(r).height = 17;
        r++;
      });
      
      // Subtotal grupe — Σ {tip izolacije}: efektivnaM2
      // ⭐ v446 (Ivan): label u kolonama 1-7, vrijednost u koloni 8 (prije bilo 1-6 / 7)
      summaryWs.mergeCells(r, 1, r, 7);
      const sc = summaryWs.getCell(r, 1);
      sc.value = `   Σ ${g.displayTip}:`;
      sc.font = { bold: true, italic: true, size: 10.5, color: { argb: BLUE } };
      sc.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
      sc.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF1F5F9' } };
      const scSum = summaryWs.getCell(r, 8);
      scSum.value = g.subtotal;
      scSum.numFmt = '0.00';
      scSum.font = { bold: true, italic: true, size: 11, color: { argb: BLUE } };
      scSum.alignment = { horizontal: 'right', vertical: 'middle' };
      scSum.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF1F5F9' } };
      for (let ci = 1; ci <= 8; ci++) {
        summaryWs.getCell(r, ci).border = { 
          top: { style: 'thin', color: { argb: BLUE } }, 
          bottom: { style: 'thin', color: { argb: BLUE } } 
        };
      }
      summaryWs.getRow(r).height = 19;
      r++;
      
      totalPloheM2 += g.subtotal;
      totalStavki += g.items.length;
    });
    
    // SVEUKUPNO POVRŠINE PROČELJA — naziv prema tipovima izolacije
    // ⭐ v446 (Ivan): label u kolonama 1-7, vrijednost u koloni 8 (prije bilo 1-6 / 7)
    const tipoviStr = ploheGrupeArr.length === 1
      ? ploheGrupeArr[0].displayTip
      : `(${ploheGrupeArr.map(g => g.displayTip).join(' + ')})`;
    
    summaryWs.mergeCells(r, 1, r, 7);
    const tot = summaryWs.getCell(r, 1);
    tot.value = `Ukupno ${tipoviStr}:`;
    tot.font = { bold: true, size: 11, color: { argb: DARK } };
    tot.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    tot.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
    const totSum = summaryWs.getCell(r, 8);
    totSum.value = totalPloheM2;
    totSum.numFmt = '0.00';
    totSum.font = { bold: true, size: 12, color: { argb: BLUE } };
    totSum.alignment = { horizontal: 'right', vertical: 'middle' };
    totSum.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
    for (let ci = 1; ci <= 8; ci++) {
      summaryWs.getCell(r, ci).border = { 
        top: { style: 'medium', color: { argb: DARK } }, 
        bottom: { style: 'double', color: { argb: DARK } } 
      };
    }
    summaryWs.getRow(r).height = 24;
    r++;
    
    // Napomena za sekciju plohe
    summaryWs.mergeCells(r, 1, r, 8);
    const noteP = summaryWs.getCell(r, 1);
    noteP.value = '💡 Površina nacrta = bruto plohe − požarne barijere unutar plohe − različite debljine unutar plohe − GN 421 otvori (sa špaletama). Tipovi izolacije (npr. EPS 16cm, MW 15cm) iz polja materijal + debljina_cm. Otvori su atribuirani proporcionalno po bruto m² ploha nacrta.';
    noteP.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
    noteP.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    summaryWs.getRow(r).height = 36;
    r++;
  }
  // (end PLOHE PO TIPU sekcija)
  
  // ═══ 4. PER-PROČELJE SHEET-OVI ═══
  // ⭐ v135.7.13 KRITIČNI FIX: sheet ime mora uključiti procjena ID + index pročelja
  //    Inače: za gradilište s više procjena (npr. #96 i #103, oba multi-pročelje s pročeljima
  //    "Pročelje 1, 2, 3"), sub-sheet imena kolidiraju (oba bi bila P1_Pročelje_1)
  //    → ExcelJS baca error → continue → PROČELJE NESTAJE iz Excela!
  //    Format: "P{procId}.{i+1}_{oznaka}" — npr. "P103.1_Pročelje_1" (jedinstveno per procjena)
  const procSuffix = `P${f.id || 'X'}`;
  for (let i = 0; i < procelja.length; i++) {
    const p = procelja[i];
    const oznakaSafe = (p.oznaka || `Nacrt ${i+1}`).replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 12);
    // ⭐ v135.7.389 (Ivan): 2 sheeta po pročelju — Slika + Obračun
    //   Sheet 1 (slika): "P102.1_Zapadno" — auto orientation (portrait ili landscape)
    //   Sheet 2 (obračun): "P102.1_Zapadno-O" — uvijek portrait
    //   Slika dobiva svoj papir (max prostor za prezentaciju), tablice idu zasebno.
    let baseSheetName = `${procSuffix}.${i+1}_${oznakaSafe}`.slice(0, 28);  // 28 chars + " -O" (3) = 31 limit
    let sheetNameSlika = baseSheetName;
    let sheetNameObracun = `${baseSheetName}-O`;
    
    // Sigurnosne provjere kolizije za oba sheeta
    let perWsSlika, perWsObracun;
    let pokusajCounter = 0;
    
    // ⭐ v135.7.385 (Ivan, 16.05.2026): AUTO-ORIJENTACIJA + CROP BIJELIH RUBOVA
    //   v381 logika: fetch slike → detect aspect → orientation
    //   v385 logika: fetch slike → CROP BIJELIH RUBOVA → detect aspect (na cropped!) → orientation
    //                + spremi cropped buffer u p._cropped_buffer za upotrebu pri Excel embed-u
    //   
    //   Zašto crop PRIJE detection: slika ima bijele rubove gore/dolje koji distort-aju 
    //   pravi aspect ratio. Npr. slika 1200×800 sa 200px bijele zone iznad+ispod = stvarna 
    //   slika 1200×400. PRIJE crop-a ratio = 1.5 (landscape), NAKON cropa ratio = 3.0 
    //   (širi landscape). Crop daje točan ratio za optimal A4 orientation.
    let proceljeOrientation = 'landscape';
    let proceljeCroppedBuffer = null;  // ⭐ v385: za reuse u image embed
    try {
      // 1. Prvi pokušaj: in-memory base64 (legacy single procjena)
      let slikaBuf = null;
      const slikaB64 = p.slika_hatch_base64 || p.slika_base64;
      if (slikaB64 && typeof slikaB64 === 'string' && slikaB64.length > 1000) {
        const cleanB64 = slikaB64.replace(/^data:image\/\w+;base64,/, '');
        slikaBuf = Buffer.from(cleanB64, 'base64');
      }
      
      // 2. Drugi pokušaj: fetch iz QNAP (hatch path prvo, pa originalna)
      if (!slikaBuf && typeof fetchImageWithFallback === 'function') {
        const hatchPath = p.slika_hatch_qnap_path || f.ai_anotirana_slika;
        const hatchB2 = p.slika_hatch_b2_path || f.slika_hatch_b2_path;
        if (hatchPath || hatchB2) {
          try {
            slikaBuf = await fetchImageWithFallback(hatchPath, hatchB2);
            if (slikaBuf && !Buffer.isBuffer(slikaBuf)) {
              if (slikaBuf.data) slikaBuf = Buffer.from(slikaBuf.data);
              else slikaBuf = null;
            }
          } catch(e) { /* tiho — možda hatch ne postoji još */ }
        }
        
        // 3. Treći pokušaj: originalna slika (ako nema hatch)
        if (!slikaBuf) {
          const origPath = p.slika_qnap_path || f.slika_qnap_path;
          const origB2 = p.slika_b2_path || f.slika_b2_path;
          if (origPath || origB2) {
            try {
              slikaBuf = await fetchImageWithFallback(origPath, origB2);
              if (slikaBuf && !Buffer.isBuffer(slikaBuf)) {
                if (slikaBuf.data) slikaBuf = Buffer.from(slikaBuf.data);
                else slikaBuf = null;
              }
            } catch(e) { /* tiho */ }
          }
        }
      }
      
      if (slikaBuf && Buffer.isBuffer(slikaBuf) && slikaBuf.length > 100) {
        // ⭐ v385: AUTO-CROP bijelih rubova PRIJE detection
        const cropped = await _cropBijeleRubove(slikaBuf);
        let aspectInfo;
        if (cropped && cropped.cropped) {
          // Crop uspješan — koristi cropped dimensions
          aspectInfo = { width: cropped.width, height: cropped.height, ratio: cropped.ratio };
          proceljeCroppedBuffer = cropped.buffer;  // spremi za embed
          // ⭐ v385: spremi i u p (per-pročelje objekt) — tako fProcelje gets it via spread
          p._cropped_hatch_buffer = cropped.buffer;
          const sizeOrig = (slikaBuf.length / 1024).toFixed(0);
          const sizeCrop = (cropped.buffer.length / 1024).toFixed(0);
          console.log(`[Excel/Knjiga] Nacrt "${p.oznaka}" CROP: ${cropped.width}×${cropped.height} (ratio ${cropped.ratio.toFixed(2)}), size ${sizeOrig}KB → ${sizeCrop}KB`);
        } else {
          // Crop fail (npr. sharp nije instaliran ili trim ne uspije) — fallback na original
          aspectInfo = _detektirajAspectRatio(slikaBuf);
        }
        
        if (aspectInfo && aspectInfo.ratio > 0) {
          // ⭐ v385: koristi 1.0 threshold za cropped sliku — stvarni aspekt fasade
          //   ratio < 1.0 → viša nego šira → PORTRAIT (slika max iskoristi A4 visinu)
          //   ratio >= 1.0 → šira nego viša → LANDSCAPE (Ivan: "aktiviraj layout mode")
          if (aspectInfo.ratio < 1.0) {
            proceljeOrientation = 'portrait';
            console.log(`[Excel/Knjiga] Nacrt "${p.oznaka}" → PORTRAIT (ratio ${aspectInfo.ratio.toFixed(2)})`);
          } else {
            proceljeOrientation = 'landscape';
            console.log(`[Excel/Knjiga] Nacrt "${p.oznaka}" → LANDSCAPE (ratio ${aspectInfo.ratio.toFixed(2)})`);
          }
        } else {
          console.log(`[Excel/Knjiga] Nacrt "${p.oznaka}" → LANDSCAPE (aspect parsing fail, fallback)`);
        }
      } else {
        console.log(`[Excel/Knjiga] Nacrt "${p.oznaka}" → LANDSCAPE (slika nedostupna, fallback)`);
      }
    } catch(e) {
      console.warn(`[Excel/Knjiga] _detektirajAspectRatio/_cropBijeleRubove fail: ${e.message}`);
    }
    
    // ⭐ v386: ranije v385 imao redundant setter `p._cropped_hatch_buffer = proceljeCroppedBuffer` 
    //   na kraju try-catch bloka — uklonjen, jer je već postavljen unutar if-bloka iznad (L28632).
    
    // ⭐ v135.7.389 (Ivan): Kreiranje 2 sheeta po pročelju
    //   Sheet 1 (Slika): orientation auto (portrait ako visoka slika, landscape ako široka)
    //   Sheet 2 (Obračun): uvijek portrait (tablice su prirodno čitljive u portretu)
    while (pokusajCounter < 10) {
      try {
        // SHEET 1: SLIKA (orientation auto po slici)
        perWsSlika = summaryWs.workbook.addWorksheet(sheetNameSlika, {
          pageSetup: {
            paperSize: 9,
            orientation: proceljeOrientation,  // auto: portrait/landscape po slici
            fitToPage: true,
            fitToWidth: 1, fitToHeight: 0,
            margins: { left: 0.25, right: 0.25, top: 0.3, bottom: 0.3, header: 0.15, footer: 0.15 }
          }
        });
        perWsSlika.columns = [
          { width: 7 }, { width: 26 }, { width: 17 }, { width: 17 },
          { width: 10 }, { width: 10 }, { width: 13 }, { width: 14 },
          { width: 16 },
        ];
        
        // SHEET 2: OBRAČUN (uvijek portrait — tablice se najbolje čitaju u portretu)
        perWsObracun = summaryWs.workbook.addWorksheet(sheetNameObracun, {
          pageSetup: {
            paperSize: 9,
            orientation: 'portrait',
            fitToPage: true,
            fitToWidth: 1, fitToHeight: 0,
            margins: { left: 0.25, right: 0.25, top: 0.3, bottom: 0.3, header: 0.15, footer: 0.15 }
          }
        });
        perWsObracun.columns = [
          { width: 7 }, { width: 26 }, { width: 17 }, { width: 17 },
          { width: 10 }, { width: 10 }, { width: 13 }, { width: 14 },
          { width: 16 },
        ];
        break;  // oba uspjela
      } catch(e) {
        pokusajCounter++;
        // Probaj sa sufixom za izbjegavanje kolizije
        const suffix = `_${pokusajCounter}`;
        sheetNameSlika = `${baseSheetName.slice(0, 28 - suffix.length)}${suffix}`;
        sheetNameObracun = `${baseSheetName.slice(0, 26 - suffix.length)}${suffix}-O`;
        console.warn(`[Excel/Knjiga] Sheet "${baseSheetName}" kolizija — pokušaj #${pokusajCounter}`);
        if (pokusajCounter >= 10) {
          console.error(`[Excel/Knjiga] Sub-sheet add fail za nacrt ${i+1} (P${f.id}) — preskočeno nakon 10 pokušaja:`, e.message);
        }
      }
    }
    if (!perWsSlika || !perWsObracun) continue;
    
    // Pripremi f-like objekt za 1 pročelje
    const fProcelje = {
      ...f,
      ravnine_json: Array.isArray(p.ravnine) ? p.ravnine : [],
      otvori_json: Array.isArray(p.otvori) ? p.otvori : [],
      pozarne_barijere_json: Array.isArray(p.barijere) ? p.barijere : [],
      zone_debljine_json: Array.isArray(p.debljine) ? p.debljine : [],
      sitnice_json: Array.isArray(p.sitnice) ? p.sitnice : [],
      napomena: p.napomena || '',
      // ⭐ v356 (Ivan, 15.05.2026): proslijedi naziv pročelja za naslov "NETO ZA FAKTURIRANJE"
      //   u per-pročelje view-u (zamjena prefiksa s nazivom pročelja umjesto "NETO ZA FAKTURIRANJE")
      _proceljeOznaka: p.oznaka || `Nacrt ${i+1}`,
      // ⭐ v357 (Ivan, 16.05.2026): globalni offset oznaka — broj otvora/PB/D u SVI PROČELJIMA 
      //   PRIJE ovog. Server replicira FE-ov `_fasMultiProceljeOffseti()` (index.html L17922). 
      //   Tako Excel oznake match hatch oznake (npr. ako "Južno" ima D4,D5,D6 na hatchu i 
      //   "Sjeverno"/"Zapadno"/"Istočno" prije njega imaju ukupno 3 D zone, lokalni idx 0,1,2 
      //   + offset 3 = D4,D5,D6 ✓).
      _proceljeOffset: (function() {
        let oO = 0, oB = 0, oD = 0;
        for (let pi = 0; pi < i; pi++) {
          const pp = procelja[pi];
          if (!pp) continue;
          oO += (Array.isArray(pp.otvori)   ? pp.otvori   : []).length;
          oB += (Array.isArray(pp.barijere) ? pp.barijere : []).length;
          oD += (Array.isArray(pp.debljine) ? pp.debljine : []).length;
        }
        return { otvori: oO, barijere: oB, debljine: oD };
      })()
    };
    
    // ⭐ v135.7.385 (Ivan, 16.05.2026): Ako je crop slike uspio (v385 aspect detection),
    //   koristi CROPPED HATCH buffer umjesto re-fetch sa QNAP-a. Sprječava dupli fetch +
    //   slika u Excel sheetu je TRIMMED (bez bijelih rubova) za max iskoristi A4 papira.
    if (p._cropped_hatch_buffer && Buffer.isBuffer(p._cropped_hatch_buffer)) {
      fProcelje._directSlikaBuffer = p._cropped_hatch_buffer;
      fProcelje._directSlikaIsAnotirana = true;
      console.log(`[multi-excel] P${i+1} koristi CROPPED HATCH buffer (auto-trim bijele rubove)`);
    }
    
    // ⭐ Pokušaj dohvatiti HATCH/ANOTIRANU sliku PRVO (s ravninama, plohama, otvorima, kotama)
    //    Tek fallback na original ako nema hatch-a.
    if (!fProcelje._directSlikaBuffer && p.slika_hatch_qnap_path) {
      try {
        const buf = await _qnapFetchBufferZaPath(p.slika_hatch_qnap_path);
        if (buf && Buffer.isBuffer(buf)) {
          fProcelje._directSlikaBuffer = buf;
          fProcelje._directSlikaIsAnotirana = true;
          console.log(`[multi-excel] P${i+1} koristi HATCH: ${p.slika_hatch_qnap_path}`);
        }
      } catch(e) { console.warn(`[multi-excel hatch fetch fail ${i+1}]`, e.message); }
    }
    
    // ⭐ Fallback Problem 1: ako pročelje nema svoj hatch ali procjena ima top-level ai_anotirana_slika,
    //    koristi to (single-pročelje knjiga ide kroz multi handler ali hatch je u top-level polju)
    if (!fProcelje._directSlikaBuffer && f.ai_anotirana_slika) {
      try {
        const buf = await _qnapFetchBufferZaPath(f.ai_anotirana_slika);
        if (buf && Buffer.isBuffer(buf)) {
          fProcelje._directSlikaBuffer = buf;
          fProcelje._directSlikaIsAnotirana = true;
          console.log(`[multi-excel] P${i+1} koristi TOP-LEVEL HATCH (single-knjiga fallback): ${f.ai_anotirana_slika}`);
        }
      } catch(e) { console.warn(`[multi-excel top-level hatch fail ${i+1}]`, e.message); }
    }
    
    // Fallback: original slika iz QNAP-a
    if (!fProcelje._directSlikaBuffer && p.slika_qnap_path) {
      try {
        const buf = await _qnapFetchBufferZaPath(p.slika_qnap_path);
        if (buf && Buffer.isBuffer(buf)) {
          fProcelje._directSlikaBuffer = buf;
          fProcelje._directSlikaIsAnotirana = false;
        }
      } catch(e) { console.warn(`[per-nacrt slika fetch fail ${i+1}]`, e.message); }
    }
    
    // ⭐ Fallback: top-level slika_qnap_path (single-knjiga koja nema per-pročelje upload)
    if (!fProcelje._directSlikaBuffer && f.slika_qnap_path) {
      try {
        const buf = await _qnapFetchBufferZaPath(f.slika_qnap_path);
        if (buf && Buffer.isBuffer(buf)) {
          fProcelje._directSlikaBuffer = buf;
          fProcelje._directSlikaIsAnotirana = false;
          console.log(`[multi-excel] P${i+1} koristi TOP-LEVEL ORIGINAL: ${f.slika_qnap_path}`);
        }
      } catch(e) { console.warn(`[per-nacrt top-level slika fail ${i+1}]`, e.message); }
    }
    
    // Fallback: ako nema slike u QNAP-u, ali ima base64 (manje efikasno, ali radi)
    if (!fProcelje._directSlikaBuffer && p.slika_base64) {
      try {
        const m = p.slika_base64.match(/^data:image\/[^;]+;base64,(.+)$/);
        const b64 = m ? m[1] : p.slika_base64;
        fProcelje._directSlikaBuffer = Buffer.from(b64, 'base64');
        fProcelje._directSlikaIsAnotirana = false;
      } catch(e) { console.warn(`[per-nacrt slika base64 fail ${i+1}]`, e.message); }
    }
    
    // Render detalja u per-sheet (re-zovi postojeću funkciju s _isPerProceljeView=true)
    const naslov = `${gradilisteNaziv || ''} — ${p.oznaka || `Nacrt ${i+1}`}`;
    
    // ⭐ v135.7.389 (Ivan): 2 sheeta po pročelju
    //   Sheet 1: Slika (full A4, optimalna orientation za sliku)
    //   Sheet 2: Obračun (portrait, sve tablice + ovjera)
    
    // Sheet 1: SLIKA
    try {
      await generirajExcelProcjenuRavnine(perWsSlika, fProcelje, 1, naslov, gradilisteAdresa, true, 'slika');
    } catch(e) {
      console.warn(`[Excel per-nacrt SLIKA render fail ${i+1}]`, e.message);
      perWsSlika.getCell(1, 1).value = `Greška renderiranja slike nacrta ${i+1}: ${e.message}`;
    }
    
    // Sheet 2: OBRAČUN
    try {
      await generirajExcelProcjenuRavnine(perWsObracun, fProcelje, 1, naslov, gradilisteAdresa, true, 'obracun');
    } catch(e) {
      console.warn(`[Excel per-nacrt OBRAČUN render fail ${i+1}]`, e.message);
      perWsObracun.getCell(1, 1).value = `Greška renderiranja obračuna nacrta ${i+1}: ${e.message}`;
    }
  }
  
  if (!summaryWs._pageBreaks) summaryWs._pageBreaks = [];
  summaryWs._pageBreaks.push(r);
  
  return r + 1;
}

// Helper za fetch slike iz QNAP-a po direktnom path-u (relative ka /APLIKACIJA/Fasade-AI/...)
async function _qnapFetchBufferZaPath(qnapPath) {
  if (!qnapPath || !process.env.QNAP_WEBDAV_URL) return null;
  try {
    const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
    const base = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
    const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
    const cleanPath = qnapPath.replace(/^\//, '');
    const encodedPath = cleanPath.split('/').filter(Boolean).map(encodeURIComponent).join('/');
    const fullUrl = `${baseUrl}${base}/${encodedPath}`;
    const r = await fetch(fullUrl, { 
      headers: { Authorization: `Basic ${auth64}` },
      signal: AbortSignal.timeout(15000)
    });
    if (!r.ok) return null;
    const ab = await r.arrayBuffer();
    return Buffer.from(ab);
  } catch(e) {
    console.warn('[_qnapFetchBufferZaPath]', e.message);
    return null;
  }
}

// ⭐ v135.7.252: Helper za PRAVO pozicioniranje slika u Excel sheet-u s
//   prilagođenim širinama stupaca (npr. knjiga sheet s A=8, B=32, C=18, ...).
//
//   ROOT CAUSE prethodnih fix-eva (v247-v251):
//     ExcelJS `tl: { col: X }` interpretira col=3.5 kao "3 + 50% kroz kolonu D",
//     NE kao "3.5 × default_col_width". Ako stupci imaju različite širine
//     (npr. knjiga A:H = 8,32,18,18,11,11,8,16 chars = 894 px total),
//     stari fix `tlCol = 8.0 - imgWidth/64` davao je tlCol ≈ 0.81 koji je
//     samo 50 px od lijevog ruba (kolona A je samo 61 px wide), pa je
//     slika ostajala daleko od desnog ruba.
//
//   PRAVI način: kumulativno preko stvarnih px-širina stupaca.
//
//   @param {Worksheet} ws - ExcelJS sheet (čita širine iz ws.getColumn(i))
//   @param {number} imgWidthPx - slika širina u px
//   @param {boolean} isHorizontal - ako je true, slika ide skroz desno
//                                   inače centrirana
//   @param {number} maxCol - zadnji stupac mjereni (default 8 = stupac H)
//   @returns {number} tlCol za ExcelJS `tl: { col: tlCol }`
function _excelSlikaPositioning(ws, imgWidthPx, isHorizontal, maxCol = 8) {
  const PX_PER_CHAR = 7;   // approx za Calibri 11 (Microsoft formula: chars*7+5)
  const PX_PADDING = 5;
  
  // Dinamički očitati stvarne širine stupaca
  const colWidthsPx = [];
  for (let i = 1; i <= maxCol; i++) {
    const col = ws.getColumn(i);
    const wChars = col.width || 8.43;  // ExcelJS default ako nije postavljen
    colWidthsPx.push(wChars * PX_PER_CHAR + PX_PADDING);
  }
  const totalPx = colWidthsPx.reduce((s, x) => s + x, 0);
  
  // Target lijevi rub slike u px-ima
  let targetLeftPx;
  if (isHorizontal) {
    // Slika skroz desno — desni rub slike = desni rub merged area
    targetLeftPx = Math.max(0, totalPx - imgWidthPx);
  } else {
    // Slika centrirana
    targetLeftPx = Math.max(0, (totalPx - imgWidthPx) / 2);
  }
  
  // Pretvori targetLeftPx → col fraction (kumulativno preko stvarnih širina)
  let cumPx = 0;
  for (let i = 0; i < colWidthsPx.length; i++) {
    const colW = colWidthsPx[i];
    if (targetLeftPx <= cumPx + colW) {
      const frac = colW > 0 ? (targetLeftPx - cumPx) / colW : 0;
      return Math.max(0, i + Math.max(0, Math.min(1, frac)));
    }
    cumPx += colW;
  }
  return Math.max(0.05, maxCol - 0.5);  // fallback ako je sve širje od target-a
}

// ⭐ v135.7.502.20.131 (Ivan, 04.06.2026): JEDINSTVENI IZVOR ISTINE za m² stavke
//   (ploha/barijera/debljina). _m2 (ručni unos + display ga pišu) je AUTORITATIVAN.
//   Fallback na _manual_sirina×_manual_visina SAMO ako _m2 nedostaje (legacy zapisi).
//   PRIJE: 9 export mjesta + 2 frontend re-množilo je _manual_sirina×_manual_visina kad
//   je override postavljen → gazilo ručno unesenu kvadraturu kad bi _m2 odstupio od dims
//   (npr. nakon drag-a kuta ravnine). Posljedica: bruto/neto u građevinskoj knjizi ≠ što
//   korisnik vidi i unese. SAD: _m2 prvi, dims samo kao legacy fallback. Iznos se mijenja
//   ISKLJUČIVO za već-divergentne (buggy) zapise; konzistentni ostaju identični.
function _fasAutoritativniM2(it) {
  if (!it) return 0;
  // ⭐ v354 (Ivan KRITIČAN): RUČNI override → dimenzije (š × v) su izvor istine, NE stari _m2
  //   (zna ostati poligonska vrijednost). Pravokutnik = š × v, kod ručnog unosa nepogrešivo.
  if (it._manual_override && parseFloat(it._manual_sirina) > 0 && parseFloat(it._manual_visina) > 0) {
    return (parseFloat(it._manual_sirina) || 0) * (parseFloat(it._manual_visina) || 0);
  }
  const m2 = parseFloat(it._m2 != null ? it._m2 : (it.m2 != null ? it.m2 : 0)) || 0;
  if (m2 > 0) return m2;
  return 0;
}

async function generirajExcelProcjenuRavnine(ws, f, pocetniRed, gradilisteNaziv, gradilisteAdresa, _isPerProceljeView = false, _renderMode = 'oba') {
  // ⭐ v135.7.389 (Ivan, 16.05.2026): _renderMode parametar za 2-sheet split po pročelju
  //   • 'oba' (default, backward compat): renderira sve (header + info + slika + tablice + ovjera)
  //   • 'slika': renderira samo header + info + slika (za "P1 Slika" sheet u optimal orientation)
  //   • 'obracun': renderira header + info + STRUKTURA + tablice + OVJERA (uvijek portrait)
  //   Ovaj split rješava Ivanov zahtjev: "bitno da je jedna stranica jedna slika pročelja"
  //   + tablice uvijek u portretu (najbolje za čitanje) bez kompromisa.
  
  // ⭐ MULTI-PROČELJE KNJIGA: ako f ima knjiga_procelja, generira 1 summary sheet + N per-pročelje sheets
  //    _isPerProceljeView = true znači da smo već unutar per-pročelje rendera (ne smije rekurzirati).
  if (!_isPerProceljeView) {
    const dim = f.dimenzije_fasade;
    let procelja = (dim && Array.isArray(dim.knjiga_procelja)) ? dim.knjiga_procelja : null;
    
    // ⭐ FALLBACK: ako procjena nema eksplicitan knjiga_procelja, sintetizira 1-pročelje knjigu
    //    iz top-level polja (ravnine_json, otvori_json, ...). Tako svaka procjena dobiva isti
    //    konzistentan layout: Sažetak + per-pročelje sheet sa anotiranom slikom.
    if ((!procelja || procelja.length === 0) && Array.isArray(f.ravnine_json) && f.ravnine_json.length > 0) {
      procelja = [{
        id: 'p_legacy_' + f.id,
        oznaka: f.naziv_objekta || `Nacrt 1`,
        slika_base64: null,
        slika_qnap_path: f.slika_qnap_path || null,
        slika_hatch_qnap_path: f.ai_anotirana_slika || null,  // legacy hatch path
        ravnine: f.ravnine_json,
        otvori: f.otvori_json || [],
        barijere: f.pozarne_barijere_json || [],
        debljine: f.zone_debljine_json || [],
        sitnice: f.sitnice_json || [],
        napomena: f.napomena || '',
        _zavrsen: true
      }];
    }
    
    if (procelja && procelja.length > 0) {
      return await _generirajExcelKnjigaMulti(ws, f, pocetniRed, gradilisteNaziv, gradilisteAdresa, procelja);
    }
  }
  
  const RED = 'FFCC0000';
  const DARK = 'FF1a1a2e';
  const LBKG = 'FFf8f9fa';
  const BORD = 'FFdee2e6';
  const GREEN = 'FF10B981';
  const ORANGE = 'FFEA580C';
  const BLUE = 'FF0891B2';
  
  let r = pocetniRed;

  // ═══ 1. HEADER + LOGO ═══
  // ⭐ v372 (Ivan, 16.05.2026): Logo veći — 85×40 → 115×55 → 140×70 px za vidljivost u 
  //   per-pročelje listu (A4 landscape — ima više širine, logo može biti veći).
  //   Header row 45→58→72 prostora za logo.
  ws.getRow(r).height = 72;
  try {
    if (!ws._logoImageId) {
      const logoImageId = ws.workbook.addImage({
        base64: 'data:image/png;base64,' + LOGO_B64,
        extension: 'png',
      });
      ws._logoImageId = logoImageId;
    }
    ws.addImage(ws._logoImageId, {
      tl: { col: 0.15, row: r - 1 + 0.1 },
      ext: { width: 140, height: 70 }
    });
  } catch(e) {}

  ws.mergeCells(r, 3, r, 8);
  const cT = ws.getCell(r, 3);
  cT.value = 'OBRAČUN GRAĐEVINSKIH RADOVA';
  cT.font = { bold: true, size: 13, color: { argb: RED } };  // ⭐ v251: 14 → 13
  cT.alignment = { horizontal: 'right', vertical: 'middle' };
  r++;
  ws.mergeCells(r, 3, r, 8);
  const cT2 = ws.getCell(r, 3);
  cT2.value = '(Građevinska knjiga · Fasaderski radovi)';
  cT2.font = { italic: true, size: 8, color: { argb: 'FF6b7280' } };  // ⭐ v251: 9 → 8
  cT2.alignment = { horizontal: 'right' };
  ws.getRow(r).height = 12;  // ⭐ v251: eksplicitno manji
  r++;
  
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
  ws.getRow(r).height = 3;  // ⭐ v251: 4 → 3 (tanja crta)
  r++;
  
  // ═══ 2. INFO BLOK ═══
  ws.getRow(r).height = 3; r++;  // ⭐ v251: 5 → 3 razmak
  const datum = new Date(f.created_at);
  const datumFormat = fmtDate(datum);
  
  const infoRows = [
    ['Gradilište:', gradilisteNaziv || '?', 'Datum knjige:', datumFormat],
    ['Adresa:',     gradilisteAdresa || '-', 'Metoda:', 'Ref. ravnine + perspektiva (±2%)'],
    ['Izvođač:',    'ŽBUKA Čakarić d.o.o.', 'Voditelj:', f.kreirao || 'Ivan Čakarić'],
    ['OIB:',        '46540647857',          'Tip objekta:', FAS_TIP_OBJEKTA_LABELS[f.tip_objekta] || '-'],
  ];
  infoRows.forEach(row => {
    ws.getCell(r, 1).value = row[0];
    ws.getCell(r, 1).font = { bold: true, size: 8, color: { argb: 'FF6b7280' } };  // ⭐ v251: 9 → 8
    ws.mergeCells(r, 2, r, 4);
    ws.getCell(r, 2).value = row[1];
    ws.getCell(r, 2).font = { size: 9, color: { argb: DARK } };  // ⭐ v251: 10 → 9
    ws.getCell(r, 2).alignment = { wrapText: true, vertical: 'middle' };  // ⭐ v251: wrap dugih nazivova
    ws.getCell(r, 5).value = row[2];
    ws.getCell(r, 5).font = { bold: true, size: 8, color: { argb: 'FF6b7280' } };
    ws.mergeCells(r, 6, r, 8);
    ws.getCell(r, 6).value = row[3];
    ws.getCell(r, 6).font = { size: 9, color: { argb: DARK } };
    ws.getCell(r, 6).alignment = { wrapText: true, vertical: 'middle' };
    ws.getRow(r).height = 14;  // ⭐ v251: eksplicitno (default je ~15, malo manje)
    r++;
  });
  ws.getRow(r).height = 3; r++;  // ⭐ v251: 5 → 3
  
  // ⭐ v135.7.389 (Ivan): Ako _renderMode === 'obracun', preskoči sliku (ide na zaseban sheet)
  if (_renderMode === 'obracun') {
    // Skip slika section — ide direktno na STRUKTURA + tablice + ovjera
  } else {
  // ═══ 3. SLIKA (hatch) ═══
  try {
    let slikaBuf = null;
    let isAnotirana = false;
    
    // ⭐ MULTI-PROČELJE: ako je proslijeđen buffer direktno (per-pročelje render),
    //    koristi ga umjesto fetcha iz QNAP-a (slika je iz procelje.slika_qnap_path)
    if (f._directSlikaBuffer && Buffer.isBuffer(f._directSlikaBuffer)) {
      slikaBuf = f._directSlikaBuffer;
      isAnotirana = !!f._directSlikaIsAnotirana;
    } else {
      slikaBuf = await dohvatiAnotiranuSlikuProcjene(f.id);
      isAnotirana = !!slikaBuf;
      console.log(`[Excel/Ravnine proc${f.id}] Anotirana: ${isAnotirana ? 'DA (' + (slikaBuf?.length || 0) + ' bytes)' : 'NE — fallback original'}`);
      if (!slikaBuf) {
        slikaBuf = await dohvatiSlikuProcjene(f.id);
      }
    }
    if (slikaBuf) {
      // ⭐ v310 (Ivan, točka 1): SLIKA NA ZASEBNU STRANICU.
      //   Ranije: header + info + SLIKA + ravnine + sve ostalo natiskano na jednoj stranici,
      //   slika premala da bi nadzor/investitor mogao pročitati anotaciju (P1, P2, otvori).
      //   Sada: 
      //     • Veće max dimenzije (730×660 vs 720×540) → cijela širina merged A:H + 80% A4 visine
      //     • PNG aspect detection (hatch slike su PNG, ranije padale na default 16:9 → krivo izduženo)
      //     • Page break NAKON slike → ostali sadržaj (mjere, plohe, ...) ide na novu stranicu
      //   Aspect ratio originala se čuva — slika nikad nije razvučena.
      let imgWidth = 720, imgHeight = 405;  // fallback ako ni JPEG ni PNG detection ne uspije
      try {
        // ⭐ v135.7.387 (Ivan, 16.05.2026): KONZERVATIVNE maxH dimenzije — slika MORA stati 
        //   u JEDNU A4 stranicu (ne preliv na 2 stranice kao u izrezak_1.png screenshot).
        //   
        //   Problem v385: maxH=970 (portrait) / 655 (landscape) NIJE uračunavao da header 
        //   (logo + info tablica) zauzima ~240 px PRIJE slike. Pa total visina = 
        //   header (240) + nacrt label (15) + slika (970) = 1225 px > 1075 useful portrait.
        //   → Excel prelivao na 2 stranice (Ivan: "ne da ju sijepa na dvije stranice").
        //   
        //   FIX v387: smanjit maxH na konzervativne brojeve koji garantiraju single-page:
        //     • Portrait useful 1075 px - header 240 - label 15 - buffer 20 = 800 px za sliku
        //     • Landscape useful 746 px - header 240 - label 15 - buffer 11 = 480 px za sliku
        //   
        //   Sheet orientation čitamo iz ws.pageSetup.orientation (postavljen u multi flow v381).
        //   ⭐ v135.7.389 (Ivan): U 'slika' mode (zasebnan sheet samo za sliku) — VEĆI maxH 
        //   jer slika ima cijelu stranicu za sebe (nema tablica iza). Portrait 800→950, 
        //   Landscape 480→580. Header (logo + info ~210 px) ostavi prostora za "puno disati".
        const wsOrientation = (ws.pageSetup && ws.pageSetup.orientation) || 'landscape';
        const isSlikaOnly = (_renderMode === 'slika');
        const maxW = (wsOrientation === 'portrait') ? 760 : 1065;
        const maxH = (wsOrientation === 'portrait') 
          ? (isSlikaOnly ? 950 : 800)   // portrait: slika-only=950, mixed=800
          : (isSlikaOnly ? 580 : 480);  // landscape: slika-only=580, mixed=480
        let foundDims = false;
        // JPEG: traži SOF marker (FFC0-FFCF, osim FFC4/FFC8/FFCC)
        if (slikaBuf[0] === 0xFF && slikaBuf[1] === 0xD8) {
          let i = 2;
          while (i < Math.min(slikaBuf.length - 8, 1048576)) {
            if (slikaBuf[i] !== 0xFF) { i++; continue; }
            const marker = slikaBuf[i+1];
            if (marker >= 0xD0 && marker <= 0xD9) { i += 2; continue; }
            if ((marker >= 0xC0 && marker <= 0xC3) || (marker >= 0xC5 && marker <= 0xC7) ||
                (marker >= 0xC9 && marker <= 0xCB) || (marker >= 0xCD && marker <= 0xCF)) {
              const h = (slikaBuf[i+5] << 8) | slikaBuf[i+6];
              const w = (slikaBuf[i+7] << 8) | slikaBuf[i+8];
              if (w > 0 && h > 0) {
                const ratio = Math.min(maxW / w, maxH / h);
                imgWidth = Math.round(w * ratio);
                imgHeight = Math.round(h * ratio);
                foundDims = true;
                break;
              }
            }
            const blockLen = (slikaBuf[i+2] << 8) | slikaBuf[i+3];
            if (blockLen <= 0) break;
            i += 2 + blockLen;
          }
        }
        // ⭐ v310: PNG aspect detection (signature 89 50 4E 47, IHDR na offset 16-23 big-endian)
        if (!foundDims && slikaBuf[0] === 0x89 && slikaBuf[1] === 0x50 && 
            slikaBuf[2] === 0x4E && slikaBuf[3] === 0x47) {
          const w = (slikaBuf[16] << 24) | (slikaBuf[17] << 16) | (slikaBuf[18] << 8) | slikaBuf[19];
          const h = (slikaBuf[20] << 24) | (slikaBuf[21] << 16) | (slikaBuf[22] << 8) | slikaBuf[23];
          if (w > 0 && h > 0 && w < 30000 && h < 30000) {
            const ratio = Math.min(maxW / w, maxH / h);
            imgWidth = Math.round(w * ratio);
            imgHeight = Math.round(h * ratio);
            foundDims = true;
          }
        }
        if (!foundDims) {
          console.warn(`[Excel/Ravnine slika proc${f.id}] dimenzije nisu detektirane (ni JPEG ni PNG marker), fallback 720×405`);
        } else {
          console.log(`[Excel/Ravnine slika proc${f.id}] sheet=${wsOrientation}, scale max=${maxW}×${maxH}, slika=${imgWidth}×${imgHeight}`);
        }
      } catch(e) {}
      
      // ⭐ v294 (Ivan): JPEG kompresija q=75 (vidi _compressJpegForExcel helper).
      //   Rezolucija ostaje IDENTIČNA — Ivan eksplicit: "neka bude ista rezolucija ali 
      //   kvaliteta slike smanji za 25%". Print na A4 (300 DPI) i PDF export za nadzor 
      //   ostaju čitljivi i lijepi. Očekivana ušteda 30-40% Excel file size.
      const compressedBuf = await _compressJpegForExcel(slikaBuf, 75);
      const imgId = ws.workbook.addImage({ buffer: compressedBuf, extension: 'jpeg' });
      ws.mergeCells(r, 1, r, 8);
      const lbl = ws.getCell(r, 1);
      lbl.value = isAnotirana ? '🎨 NACRT FASADE (anotirana slika s ravninama, plohama, otvorima, barijerama)' : '📷 NACRT FASADE (originalna fotografija)';
      lbl.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
      lbl.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
      lbl.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      ws.getRow(r).height = 15;
      r++;
      
      const slikaTopRow = r;
      // ⭐ v135.7.247: HORIZONTALNE slike (w>h) idu skroz desno (do kraja merged area-e A:H)
      //   VERTIKALNE slike (h>w) idu CENTRIRANE — estetski balansirano, ne smetaju
      //   čitanju desnih kolona jer su uske. Ivanov zahtjev (svibanj 2026):
      //   "horizontalne skroz desno, vertikalne pametno" → centrirane je najbolja prosudba.
      //   Pretvorba px → Excel column units: ~7.6 px po 1 column unit (default stupac
      //   8.43 ≈ 64 px). Ako stupac ima drugačiju širinu, ExcelJS rerendera ali aspekti
      //   ostaju OK jer koristimo ext (eksplicitne dimenzije px).
      const isHorizontal = imgWidth > imgHeight;
      // ⭐ v135.7.252: koristim _excelSlikaPositioning helper koji dinamički
      //   očitava STVARNE širine stupaca u sheet-u (knjiga A:H = 8,32,18,18,11,11,8,16
      //   chars = 894 px), umjesto pretpostavke o default 64px stupcu.
      //   Prethodni v251 fix `tlCol = 8.0 - imgWidth/64` davao je tlCol ≈ 0.81 koji je
      //   samo 50 px od lijevog ruba (kolona A je samo 61 px wide). Sad ide PRAVA px-bazirana
      //   kumulativna kalkulacija — slika u knjizi sad stiže do desnog ruba ~894 px.
      const tlCol = _excelSlikaPositioning(ws, imgWidth, isHorizontal, 8);
      ws.addImage(imgId, {
        tl: { col: tlCol, row: r - 1 + 0.2 },
        ext: { width: imgWidth, height: imgHeight },
        editAs: 'oneCell'
      });
      // Excel row.height je u POINTS (1pt ≈ 1.33px). 18pt ≈ 24px.
      // imgHeight u px → broj redaka = ceil(imgHeight / 24) za 18pt visinu.
      const rowHeightPt = 18;
      const rowHeightPx = rowHeightPt * 1.333;  // ≈ 24px
      const rowsForImg = Math.ceil(imgHeight / rowHeightPx);
      for (let kk = 0; kk < rowsForImg; kk++) ws.getRow(r + kk).height = rowHeightPt;
      r += rowsForImg;
      
      // ⭐ v310 (Ivan, točka 1): PAGE BREAK NAKON SLIKE.
      //   Forsira da sve sljedeće (referentne mjere, ravnine, plohe, otvori, sitnice, ...)
      //   ide na DRUGU stranicu A4. Tako je anotirana slika čitka i sama na prvoj stranici.
      //   ⭐ v135.7.389: u 'slika' mode sheetu ne treba page break jer ionako exit-amo (slika je 
      //   na zasebnom sheetu, tablice su na drugom sheet-u "P*-O").
      if (_renderMode !== 'slika') {
        try { ws.getRow(r - 1).addPageBreak(); } catch(_) {}
      }
    }
  } catch(e) { console.warn('[Excel/Ravnine slika]', e.message); }
  
  ws.getRow(r).height = 8; r++;
  
  // ⭐ v135.7.389 (Ivan): Ako _renderMode === 'slika', završi ovdje (nema tablica)
  if (_renderMode === 'slika') {
    return r + 1;
  }
  
  }  // ⭐ v389: kraj else bloka za 'obracun' mode (skip slika)
  
  // ═══ 4. RAVNINE + PLOHE (BRUTO) ═══
  const ravnine = Array.isArray(f.ravnine_json) ? f.ravnine_json : [];
  const barijerePre = Array.isArray(f.pozarne_barijere_json) ? f.pozarne_barijere_json : [];
  const debljinePre = Array.isArray(f.zone_debljine_json) ? f.zone_debljine_json : [];
  
  // ⭐ Pre-calc helper: razdvoji barijere/debljine na UNUTAR/IZVAN ploha
  // (potreban ovdje da znamo izvan-stavke uključiti u tablicu pročelja kao posebne retke)
  const xlsTockaUPoligonu = (x, y, points) => {
    if (!Array.isArray(points) || points.length < 3) return false;
    let inside = false;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
      const xi = points[i].x, yi = points[i].y;
      const xj = points[j].x, yj = points[j].y;
      const intersect = ((yi > y) !== (yj > y)) && 
        (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  };
  const xlsStavkaUnutarPlohe = (stavka, ravnina) => {
    if (!stavka || !ravnina) return false;
    const plohe = Array.isArray(ravnina.plohe) ? ravnina.plohe : [];
    if (plohe.length === 0) return false;
    const pts = Array.isArray(stavka.points) ? stavka.points 
              : Array.isArray(stavka.pointsPx) ? stavka.pointsPx : null;
    if (!pts || pts.length < 3) return false;
    const cx = pts.reduce((s, p) => s + p.x, 0) / pts.length;
    const cy = pts.reduce((s, p) => s + p.y, 0) / pts.length;
    for (const ploha of plohe) {
      const pp = Array.isArray(ploha.pointsPx) ? ploha.pointsPx 
               : Array.isArray(ploha.points) ? ploha.points : null;
      if (!pp || pp.length < 3) continue;
      if (xlsTockaUPoligonu(cx, cy, pp)) return true;
    }
    return false;
  };
  
  // ⭐ v135.7.260: Pre-flag barijere/debljine: PRVO poštuj frontend flag 
  //   (_van_plohe_pribraja_bruto postavljen iz _fasCalcRavnineSums koristeći 75% logiku),
  //   FALLBACK na centroid računanje (xlsStavkaUnutarPlohe) ako frontend nije postavio flag.
  //   Razlog: frontend i server moraju imati ISTU detekciju "van plohe" — inače u app-u 
  //   bruto pokazuje +D.m², a u Excelu drugačije. Frontend 75% logika je preciznija od
  //   server centroid (1 točka), zato joj dajemo prioritet.
  barijerePre.forEach(b => {
    if (typeof b._van_plohe_pribraja_bruto === 'boolean') {
      // Frontend je postavio flag — koristi ga (75% točaka logika)
      b._unutar_plohe = !b._van_plohe_pribraja_bruto;
    } else {
      // Legacy / brza procjena bez frontend kalkulacije → centroid fallback
      const ravnina = ravnine.find(rv => rv.id === b.ravnina_id || rv.id === b._ravnina_id);
      b._unutar_plohe = xlsStavkaUnutarPlohe(b, ravnina);
    }
  });
  debljinePre.forEach(d => {
    if (typeof d._van_plohe_pribraja_bruto === 'boolean') {
      d._unutar_plohe = !d._van_plohe_pribraja_bruto;
    } else {
      const ravnina = ravnine.find(rv => rv.id === d.ravnina_id || rv.id === d._ravnina_id);
      d._unutar_plohe = xlsStavkaUnutarPlohe(d, ravnina);
    }
  });
  
  // ═══════════════════════════════════════════════════════════════════════
  // ⭐ STRUKTURA PROČELJA PO RAVNINAMA — minimalan listing ravnina s kalibracijom
  //    ⭐ v451 (Ivan, 18.05.2026): POJEDNOSTAVLJENO — uklonjen preview stavki (plohe, otvori, PB, D, RŠ)
  //       ispod svake ravnine, Σ R subtotal redovi, i Σ PROČELJE (sve ravnine zbrojeno) red.
  //       Razlog: previše duplikata podataka — nadzor i investitor se zbune. Detaljan obračun 
  //       je DOLJE u sekciji "PLOHE PROČELJA" i "B) ODBITAK OTVORA", to je dovoljno.
  //       Ovaj listing sad služi samo kao evidencija KALIBRACIJE (R1 Š×V, R2 Š×V, ...).
  //       Uklonjen "(pregled za nadzor)" iz naslova jer više nije pregled, samo evidencija.
  // ═══════════════════════════════════════════════════════════════════════
  if (ravnine.length > 0) {
    // ⭐ v135.7.381 (Ivan, 16.05.2026): STRUKTURA naslov bio djelomično obrezan na vrh stranice
    //   nakon page break-a iza slike. Dodano: prazan buffer red (6pt) iznad naslova + height 22.
    ws.getRow(r).height = 6; r++;
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = '🗺️ STRUKTURA NACRTI PO RAVNINAMA';
    ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF5b21b6' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 22;
    r++;
    
    ravnine.forEach((rv, rIdx) => {
      const oznakaR = `R${rIdx + 1}`;
      // Samo ravnina header (kalibracijske dimenzije Š×V iz canvas-a)
      ws.mergeCells(r, 1, r, 9);
      const hCell = ws.getCell(r, 1);
      hCell.value = `${oznakaR} — ${rv.naziv || ('Ravnina ' + (rIdx+1))} (${parseFloat(rv.sirina_m||0).toFixed(2)}×${parseFloat(rv.visina_m||0).toFixed(2)} m kalibracija)`;
      hCell.font = { bold: true, size: 9.5, color: { argb: 'FF5b21b6' } };
      hCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFf3e8ff' } };
      hCell.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      ws.getRow(r).height = 16;
      r++;
    });
    
    // Spacing prije detaljnog obračuna
    ws.getRow(r).height = 10; r++;
  }
  
  // ⭐ v358 bugfix: full width naslov za landscape A4 (9 stupaca)
  ws.mergeCells(r, 1, r, 9);
  // ⭐ v311 (Ivan, točka 7): "POVRŠINE FASADE — REALNA PROČELJA" → "PLOHE PROČELJA"
  //    Ivan: "to nije bitno za izračun" (R1, R2 ravnine su kalibracija — info zbunjuje).
  //    Sad: prikazuju se samo plohe (s ploha opisom kojeg je Ivan stavio).
  ws.getCell(r, 1).value = 'PLOHE NACRTI  (Plohe + stavke izvan ploha = bruto)';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 16;
  r++;
  
  // Header tablice
  // ⭐ v369 (Ivan, 16.05.2026) Točka 4: tablica rastegnuta do A4 margine — dodan 9. 
  //   stupac "Napomena" da PLOHE PROČELJA tablica koristi sve raspoložive kolone 
  //   (1-9, kao i druge sekcije: Obračun GN 421, Razl. debljine itd.).
  const hdrPlo = ['Oznaka', 'Opis', 'Širina (m)', 'Visina (m)', 'Površina (m²)', 'Količina', 'Ukupno (m²)', 'Mode', 'Napomena'];
  hdrPlo.forEach((v, i) => {
    const c = ws.getCell(r, i+1);
    c.value = v;
    c.font = { bold: true, size: 9 };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
    c.border = { bottom: { style: 'thin', color: { argb: BORD } } };
    c.alignment = { horizontal: i >= 2 && i <= 6 ? 'right' : 'left', vertical: 'middle', indent: 1 };
  });
  r++;
  
  let bruto = 0;
  let plohaSum = 0;  // ⭐ v135.7.23: samo Σ plohe (bez razvijenih i izvan-plohe stavki) — za kontrolu Ivanovog koncepta
  ravnine.forEach((rv, rIdx) => {
    // ⭐ Ravnina = SAMO KALIBRACIJA. NE zbraja se u bruto.
    // Provjeri ima li ploha — ako ima, ravnina je samo geometrija (kalibracija)
    const sirinaRav = parseFloat(rv.sirina_m || 0);
    const visinaRav = parseFloat(rv.visina_m || 0);
    const bboxM2 = sirinaRav * visinaRav;
    const ravKol = parseInt(rv.kolicina || 1) || 1;
    const plohe = Array.isArray(rv.plohe) ? rv.plohe : [];
    // ⭐ v501.2 (Ivan): ploha mora imati m² > 0 da bi se ravnina tretirala kao "kalibracija" 
    //    (s realnim plohama). Prazne plohe (0×0) → ravnina je "BEZ PLOHE" → CRVENI ERROR 
    //    u Excelu i bruto se NE povećava. NIKAD bbox fallback — ravnina je samo kalibracija.
    const validnePlohe = plohe.filter(pl => parseFloat(pl._m2 || pl.m2 || 0) > 0);
    const imaPloha = validnePlohe.length > 0 || (Array.isArray(rv.ploha_pointsPx) && rv.ploha_pointsPx.length >= 3 && parseFloat(rv.ploha_m2 || 0) > 0);
    
    if (imaPloha) {
      // ⭐ v311 (Ivan, točka 7): NE renderira se R-red (kalibracija) — Ivan: "to nije bitno za izračun".
      //    Plohe ove ravnine same daju izračun pročelja. Ravnina je samo kalibracijski pomoć.
      //    Preskačemo direktno na plohe.forEach niže (bez r++).
    } else {
      // ⭐ v135.7.5: Ravnina BEZ PLOHE — Ivanov zahtjev: NE računati u bruto, prikazati CRVENI ERROR
      //    (prije: LEGACY grana je dodavala bbox ravnine kao bruto što je krivo)
      //    Ravnina = SAMO kalibracija (4 kuta + ref pravokutnik), ploha = realno pročelje
      //    Bez plohe → izračun se NE radi, korisnik mora definirati plohu
      ws.getCell(r, 1).value = 'R' + (rIdx + 1);
      ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFffffff' } };
      ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFdc2626' } };
      ws.getCell(r, 2).value = '⚠ ' + (rv.naziv || ('Ravnina ' + (rIdx+1))) + ' — NEMA PLOHE! Ravnina je samo za kalibraciju, definirajte plohu pa generirajte izvod ponovno.';
      ws.getCell(r, 2).font = { bold: true, size: 9, color: { argb: 'FFffffff' } };
      ws.getCell(r, 2).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFdc2626' } };
      ws.getCell(r, 2).alignment = { horizontal: 'left', vertical: 'middle', wrapText: true };
      ws.getCell(r, 3).value = sirinaRav; ws.getCell(r, 3).numFmt = '0.00';
      ws.getCell(r, 3).font = { color: { argb: 'FF6b7280' }, italic: true };
      ws.getCell(r, 4).value = visinaRav; ws.getCell(r, 4).numFmt = '0.00';
      ws.getCell(r, 4).font = { color: { argb: 'FF6b7280' }, italic: true };
      ws.getCell(r, 5).value = bboxM2; ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 5).font = { color: { argb: 'FF6b7280' }, italic: true, strike: true };  // precrtano
      ws.getCell(r, 6).value = '';
      ws.getCell(r, 7).value = '';  // ukupno = 0, ne ulazi u bruto
      ws.getCell(r, 8).value = 'GREŠKA — nedostaje ploha';
      ws.getCell(r, 8).font = { bold: true, size: 8, color: { argb: 'FFdc2626' }, italic: true };
      [3,4,5,6,7,8].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' });
      ws.getRow(r).height = 28;  // veći red da se vidi warning
      // Bruto se NE povećava (prije: bruto += ravUkupno) — ravnina bez plohe je nevaljana
      r++;  // ⭐ v311 (točka 7): r++ premješten u else granu (if/imaPloha više ne troši red)
    }
    
    // Plohe te ravnine
    plohe.forEach((p, pIdx) => {
      const isManual = !!p._manual_override;
      let sirinaP, visinaP, m2;
      
      if (isManual && p._manual_sirina && p._manual_visina) {
        // Ručno upisane mjere
        sirinaP = parseFloat(p._manual_sirina);
        visinaP = parseFloat(p._manual_visina);
        m2 = sirinaP * visinaP;
      } else {
        // Poligonska ploha — koristi sirina_m/visina_m iz klijenta (AABB iz pointsPx preko H matrice)
        // ⭐ FIX: parseFloat(_m2 || m2) jer FE payload za multi-pročelje knjigu šalje 'm2' (ne '_m2')
        m2 = parseFloat(p._m2 || p.m2 || 0) || 0;
        sirinaP = parseFloat(p.sirina_m || 0);
        visinaP = parseFloat(p.visina_m || 0);
        // Fallback: kvadrat √m² × √m² (samo orijentacijski, ako klijent nije poslao AABB)
        if (!isFinite(sirinaP) || sirinaP <= 0 || !isFinite(visinaP) || visinaP <= 0) {
          const sq = m2 > 0 ? Math.sqrt(m2) : 0;
          sirinaP = sq;
          visinaP = sq;
        }
      }
      const kolP = parseInt(p.kolicina || 1) || 1;
      const ukupnoP = m2 * kolP;
      
      ws.getCell(r, 1).value = '  ↳ P' + (pIdx + 1);
      ws.getCell(r, 1).font = { color: { argb: 'FF10b981' } };
      ws.getCell(r, 2).value = p._oznaka || p.opis || ('Ploha ' + (pIdx+1));
      ws.getCell(r, 2).font = { italic: true };
      ws.getCell(r, 3).value = sirinaP; ws.getCell(r, 3).numFmt = '0.00';
      ws.getCell(r, 4).value = visinaP; ws.getCell(r, 4).numFmt = '0.00';
      ws.getCell(r, 5).value = m2; ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 6).value = kolP;
      ws.getCell(r, 7).value = ukupnoP; ws.getCell(r, 7).numFmt = '0.00';
      ws.getCell(r, 7).font = { bold: true, color: { argb: 'FF10b981' } };
      ws.getCell(r, 8).value = isManual ? 'RUČNO ✏️' : 'auto';
      ws.getCell(r, 8).font = { size: 8, bold: isManual, color: { argb: isManual ? 'FFEAB308' : 'FF6b7280' } };
      // ⭐ v369 (Ivan, 16.05.2026) Točka 4: kolona 9 (Napomena) za plohe — popuni ako 
      //   ploha ima napomenu polje. Ovim tablica vizualno koristi sve 9 stupaca do A4 margine.
      if (p.napomena && String(p.napomena).trim()) {
        ws.getCell(r, 9).value = String(p.napomena).trim();
        ws.getCell(r, 9).font = { italic: true, size: 8.5, color: { argb: 'FF475569' } };
        ws.getCell(r, 9).alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
      }
      [3,4,5,6,7,8].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' });
      bruto += ukupnoP;
      plohaSum += ukupnoP;  // ⭐ v135.7.23: samo plohe (za Ivanov kontrolni broj)
      r++;
    });
    if (plohe.length === 0 && rIdx < ravnine.length - 1) {
      ws.getRow(r).height = 4; r++;
    }
  });
  
  // ⭐ Stavke IZVAN ploha (pribrajaju se u bruto) — barijere i debljine koje nisu u P1/P2/...
  //   ⭐ v135.7.260 fix: frontend koristi `_ravnina_id` (sa underscore), stari kod imao samo
  //   `ravnina_id` (bez underscore) — filter je uvijek bio false za nove stavke! Sad oba podržana.
  const barijereIzvanRow = barijerePre.filter(b => b._unutar_plohe === false && (b._ravnina_id || b.ravnina_id));
  const debljineIzvanRow = debljinePre.filter(d => d._unutar_plohe === false && (d._ravnina_id || d.ravnina_id));
  
  if (barijereIzvanRow.length > 0 || debljineIzvanRow.length > 0) {
    ws.getRow(r).height = 6; r++;
    // ⭐ v369 (Ivan): IZVAN PLOHA naslov rastegnut na 9 stupaca (tablica do A4 margine)
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = '➕ IZVAN PLOHA (pribraja se u bruto)';
    ws.getCell(r, 1).font = { bold: true, size: 9, color: { argb: 'FFb45309' }, italic: true };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 16;
    r++;
    
    barijereIzvanRow.forEach((b, bIdx) => {
      const m2 = _fasAutoritativniM2(b);
      const kol = parseInt(b.kolicina || 1) || 1;
      const ukupno = m2 * kol;
      ws.getCell(r, 1).value = '  + B' + (bIdx + 1);
      ws.getCell(r, 1).font = { color: { argb: 'FFEF4444' } };
      ws.getCell(r, 2).value = (b._oznaka || b.opis || 'Pož. barijera') + ' (izvan plohe)';
      ws.getCell(r, 2).font = { italic: true };
      if (m2 > 0) {
        const sq = Math.sqrt(m2);
        ws.getCell(r, 3).value = parseFloat(b._manual_sirina || sq); ws.getCell(r, 3).numFmt = '0.00';
        ws.getCell(r, 4).value = parseFloat(b._manual_visina || sq); ws.getCell(r, 4).numFmt = '0.00';
      }
      ws.getCell(r, 5).value = m2; ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 6).value = kol;
      ws.getCell(r, 7).value = ukupno; ws.getCell(r, 7).numFmt = '0.00';
      ws.getCell(r, 7).font = { bold: true, color: { argb: 'FFEF4444' } };
      ws.getCell(r, 8).value = 'izvan';
      ws.getCell(r, 8).font = { size: 8, color: { argb: 'FFb45309' }, italic: true };
      // ⭐ v369 (Ivan) Točka 4: kolona 9 — napomena (ako postoji)
      if (b.napomena && String(b.napomena).trim()) {
        ws.getCell(r, 9).value = String(b.napomena).trim();
        ws.getCell(r, 9).font = { italic: true, size: 8.5, color: { argb: 'FF475569' } };
        ws.getCell(r, 9).alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
      }
      [3,4,5,6,7,8].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' });
      bruto += ukupno;
      r++;
    });
    
    debljineIzvanRow.forEach((d, dIdx) => {
      const m2 = _fasAutoritativniM2(d);
      const kol = parseInt(d.kolicina || 1) || 1;
      const ukupno = m2 * kol;
      ws.getCell(r, 1).value = '  + D' + (dIdx + 1);
      ws.getCell(r, 1).font = { color: { argb: 'FF0891B2' } };
      // ⭐ v369 (Ivan) Točka 2 (PB/D napomena pokraj opisa) — opis bez napomene u zagradi,
      //   napomena ide u zasebnu kolonu 9 (kao u Σ PB/Σ D listovima)
      ws.getCell(r, 2).value = (d._oznaka || d.opis || 'Razl. debljina') + ' (izvan plohe)';
      ws.getCell(r, 2).font = { italic: true };
      if (m2 > 0) {
        const sq = Math.sqrt(m2);
        ws.getCell(r, 3).value = parseFloat(d._manual_sirina || sq); ws.getCell(r, 3).numFmt = '0.00';
        ws.getCell(r, 4).value = parseFloat(d._manual_visina || sq); ws.getCell(r, 4).numFmt = '0.00';
      }
      ws.getCell(r, 5).value = m2; ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 6).value = kol;
      ws.getCell(r, 7).value = ukupno; ws.getCell(r, 7).numFmt = '0.00';
      ws.getCell(r, 7).font = { bold: true, color: { argb: 'FF0891B2' } };
      ws.getCell(r, 8).value = 'izvan';
      ws.getCell(r, 8).font = { size: 8, color: { argb: 'FFb45309' }, italic: true };
      // ⭐ v369 (Ivan) Točka 4: kolona 9 — napomena (D često ima napomenu kao "atika", "jugozapadno"...)
      if (d.napomena && String(d.napomena).trim()) {
        ws.getCell(r, 9).value = String(d.napomena).trim();
        ws.getCell(r, 9).font = { italic: true, size: 8.5, color: { argb: 'FF475569' } };
        ws.getCell(r, 9).alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
      }
      [3,4,5,6,7,8].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' });
      bruto += ukupno;
      r++;
    });
  }
  
  // SUMA bruto
  // ⭐ v369 (Ivan, 16.05.2026) Točka 4: UKUPNO BRUTO red rastegnut na svih 9 stupaca 
  //   tako da tablica PLOHE PROČELJA dohvaća margine A4 (landscape). Vizualno čistija 
  //   zatvorenost tablice — bez "stepenice" gdje stupci 8-9 ostaju prazni izvan UKUPNO reda.
  ws.mergeCells(r, 1, r, 6);
  const sb = ws.getCell(r, 1);
  sb.value = 'UKUPNO BRUTO (Σ plohe):';
  sb.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  sb.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  sb.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getCell(r, 7).value = bruto;
  ws.getCell(r, 7).numFmt = '0.00';
  ws.getCell(r, 7).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 7).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 7).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  // ⭐ v369: kolona 8 i 9 popunjene da UKUPNO red dohvaća desni rub A4 (margina)
  ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getRow(r).height = 17;
  r++;
  
  // ═══ 5. SUMARNI BLOK (Otvori, Barijere, Debljine, Sitnice — pogledaj zasebne sheets za detalje) ═══
  ws.getRow(r).height = 8; r++;
  
  const otvori = Array.isArray(f.otvori_json) ? f.otvori_json : [];
  const barijere = Array.isArray(f.pozarne_barijere_json) ? f.pozarne_barijere_json : [];
  const debljine = Array.isArray(f.zone_debljine_json) ? f.zone_debljine_json : [];
  const sitnice = Array.isArray(f.sitnice_json) ? f.sitnice_json : [];
  
  // GN 421 PRAVILO ZA OTVORE:
  //   m² ≤ 3 → ne odbija se (špalete već uračunate)
  //   3 < m² ≤ 5 → odbija (m² - 3) m², špalete ne posebno
  //   m² > 5 → odbija (m² - 3) m² + dodatak špalete = (2v + š) × debljina × kom
  // Default debljina fasade za špalete: 15 cm = 0.15 m (može se override-ati u f.default_debljina_cm)
  const defDebljinaM = parseFloat(f.default_debljina_cm || 15) / 100;
  
  // ⭐ v135.7.251: Pretraga debljine iz opisa plohe ako je otvor unutar nje
  //   PRIJE: koristio uvijek defDebljinaM (15cm globalni) za sve otvore — netočno ako 
  //          plohe imaju različite debljine izolacije (npr. P1 = 15cm EPS, P2 = 20cm EPS)
  //   SAD: ekstrahiram debljinu iz opisa plohe (regex `\d+\s*cm`), fallback na default 15cm
  //   Logika: za svaki otvor, nađi plohu unutar koje se nalazi (centroid-in-polygon test)
  //          i koristi debljinu te plohe za izračun špaleta.
  const ravnine_json = Array.isArray(f.ravnine_json) ? f.ravnine_json : [];
  
  // Helper: ekstrahira debljinu (u metrima) iz opisa plohe
  //   "15cm EPS", "20 cm rock-wool", "EPS 25cm" → 0.15, 0.20, 0.25
  //   Bez "cm" → null (caller koristi default)
  const _debljinaIzOpisa = (opis) => {
    if (!opis) return null;
    const m = String(opis).match(/(\d{1,3}(?:[.,]\d+)?)\s*cm\b/i);
    if (!m) return null;
    const cm = parseFloat(m[1].replace(',', '.'));
    if (!isFinite(cm) || cm <= 0 || cm > 100) return null;  // sanity check
    return cm / 100;
  };
  
  // Helper: točka u poligonu (ray-casting algoritam)
  const _pointInPolygon = (x, y, poly) => {
    if (!Array.isArray(poly) || poly.length < 3) return false;
    let inside = false;
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const xi = poly[i].x, yi = poly[i].y;
      const xj = poly[j].x, yj = poly[j].y;
      const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  };
  
  // Helper: nađi plohu u kojoj se nalazi otvor (centroid otvora unutar plohe?)
  //   Vraća { ploha, ravnina } ili null ako otvor nije unutar nijedne plohe.
  const _nadiPlohuZaOtvor = (otvor) => {
    const pts = otvor.points || otvor.kutoviPx;
    if (!Array.isArray(pts) || pts.length < 3) return null;
    // Centroid otvora
    const cx = pts.reduce((s, p) => s + p.x, 0) / pts.length;
    const cy = pts.reduce((s, p) => s + p.y, 0) / pts.length;
    
    // Pretraga kroz sve ravnine i sve plohe
    for (const r of ravnine_json) {
      // Provjeri ako otvor ima _ravnina_id i poklapa s r.id (brzi case)
      if (otvor._ravnina_id && r.id && otvor._ravnina_id !== r.id) continue;
      const plohe = Array.isArray(r.plohe) ? r.plohe : [];
      for (const pl of plohe) {
        const plohaPts = pl.pointsPx;
        if (_pointInPolygon(cx, cy, plohaPts)) {
          return { ploha: pl, ravnina: r };
        }
      }
    }
    return null;
  };
  
  // Helper: debljina u metrima za otvor (kombinira sve gornje)
  //   Pretraga: opis plohe → opis ravnine → f.default_debljina_cm → 0.15
  const _debljinaZaOtvor = (otvor) => {
    // ⭐ v357 (Ivan, 16.05.2026): EKSPLICITAN OVERRIDE prvo (korisnik može u app-u za otvor 
    //   eksplicitno definirati debljinu plohe za GN 421 špalete, npr. ako je otvor na granici 
    //   ploha s različitim debljinama).
    if (otvor && otvor.debljina_otvor_cm != null && otvor.debljina_otvor_cm !== '') {
      const v = parseFloat(otvor.debljina_otvor_cm);
      if (isFinite(v) && v > 0) return v / 100;  // cm → m
    }
    const match = _nadiPlohuZaOtvor(otvor);
    if (match) {
      // ⭐ v357: ploha sad može imati eksplicitno polje `debljina_cm` (numeric) — to ima prioritet
      const plohaDebCm = match.ploha && match.ploha.debljina_cm;
      if (plohaDebCm != null && plohaDebCm !== '') {
        const v = parseFloat(plohaDebCm);
        if (isFinite(v) && v > 0) return v / 100;
      }
      const dFromPloha = _debljinaIzOpisa(match.ploha?.opis);
      if (dFromPloha !== null) return dFromPloha;
      const dFromRavnina = _debljinaIzOpisa(match.ravnina?.opis);
      if (dFromRavnina !== null) return dFromRavnina;
    }
    return defDebljinaM;
  };
  
  // Helper: vrati efektivni m², š, v za otvor (poštujući manual override)
  // ⭐ v450 (Ivan, 18.05.2026): HYBRID logika za m².
  //   - Manual override (korisnik ručno upisao Š/V/m² za nepravilan oblik kao lučni prozor): 
  //     prefer m2Stored (može biti drugačiji od Š×V bbox).
  //   - Canvas-crtani (najčešći slučaj, FE drag mijenja Š/V): prefer svježi Š×V > 0.
  //     m2Stored postaje fallback samo za legacy otvore bez Š/V.
  //   
  //   PRIJE (v360): uvijek prefer m2Stored — pretpostavka da FE sync-a m² nakon promjene Š/V.
  //                 U praksi FE ne osvježi `o.m2` pouzdano → Excel stale za canvas otvore.
  //   SAD (v450):   sinhroniziran s _knjigaOtvoriZaProcelje, calcStavku i agregated Σ Otvori sheet.
  const otvorMjere = (o) => {
    const isManual = !!(o._manual_override && o._manual_sirina && o._manual_visina);
    const sirina = isManual ? parseFloat(o._manual_sirina) : parseFloat(o.sirina_m || 0);
    const visina = isManual ? parseFloat(o._manual_visina) : parseFloat(o.visina_m || 0);
    const sirinaXvisina = sirina * visina;
    const m2Stored = parseFloat(o.m2 || o._m2 || 0);
    const m2 = isManual
      ? (sirinaXvisina > 0 ? sirinaXvisina : m2Stored)
      : (sirinaXvisina > 0 ? sirinaXvisina : (m2Stored || 0));
    return { sirina, visina, m2, isManual };
  };
  
  // ⭐ Problem 10: obracun_mod aware (FE per-pročelje setting + dimenzije_fasade)
  //    'gn421' (default): otvori >3m² djelomično, >5m² + špalete (GN 421 normativ)
  //    'spalete' alternativni: cijeli otvor odbijen, špalete (2v+š) idu u Σ Špalete sheet
  let obracunMod = 'gn421';
  try {
    const dim = f.dimenzije_fasade;
    if (dim && Array.isArray(dim.knjiga_procelja) && dim.knjiga_procelja.length > 0) {
      // Multi-pročelje: koristi obracun_mod prvog pročelja kao indikativan za list
      obracunMod = dim.knjiga_procelja[0].obracun_mod || 'gn421';
    } else if (dim && dim.obracun_mod) {
      obracunMod = dim.obracun_mod;
    }
  } catch(_) {}
  const isSpaleteMod = (obracunMod === 'spalete');
  
  // Klasificiraj svaki otvor po pravilu (mode-aware)
  const otvoriDetalji = otvori.map(o => {
    const { sirina, visina, m2, isManual } = otvorMjere(o);
    const kol = parseInt(o.kolicina || 1) || 1;
    let odbitak = 0;
    let spalete = 0;
    let spaleteMDuzni = 0;
    let kategorija = 'mali';  // ≤ 3
    
    // ⭐ v135.7.251: pronađi pravu debljinu za ovaj otvor (iz opisa plohe gdje se nalazi)
    const debljinaM = _debljinaZaOtvor(o);
    
    // ⭐ v446 (Ivan, 18.05.2026): sqrt fallback Š/V za špalete kad su Š=V=0 ali m²>0.
    //   Sinhroniziran s _knjigaOtvoriZaProcelje.
    let sFs = sirina, vFs = visina, fallbackUsed = false;
    if ((sFs <= 0 || vFs <= 0) && m2 > 0) {
      sFs = vFs = Math.sqrt(m2);
      fallbackUsed = true;
    }
    
    if (isSpaleteMod) {
      // ⭐ Špalete mod: cijeli otvor odbijen, špalete (2v+š) u m' (idu u Σ Špalete sheet)
      kategorija = 'cijeli';
      odbitak = m2 * kol;
      spaleteMDuzni = (sFs > 0 && vFs > 0) ? (2 * vFs + sFs) * kol : 0;
    } else if (m2 > 5) {
      kategorija = 'veliki';
      odbitak = (m2 - 3) * kol;
      if (sFs > 0 && vFs > 0) {
        spalete = (2 * vFs + sFs) * debljinaM * kol;  // ⭐ v251: debljinaM iz plohe + v446: sqrt fb
      }
    } else if (m2 > 3) {
      kategorija = 'srednji';
      odbitak = (m2 - 3) * kol;
    }
    return {
      o, sirina, visina, m2, kol, isManual,
      kategorija, odbitak, spalete, spaleteMDuzni,
      debljinaM,  // ⭐ v251: koristi se u Excel ispisu (formula s pravom debljinom, ne globalnom)
      // ⭐ v446: effective Š/V za formula display (sqrt fallback ako bilo Š/V = 0)
      _spalete_s: sFs, _spalete_v: vFs, _spalete_fallback: fallbackUsed,
      tipLabel: o.tip ? (FAS_TIP_LABELS[o.tip] || o.tip) : 'Otvor',
      opis: o._oznaka || o.opis || (o.tip ? (FAS_TIP_LABELS[o.tip] || o.tip) : 'Otvor')
    };
  }).filter(Boolean);
  
  const otvoriOdbitakSum = otvoriDetalji.reduce((s, x) => s + x.odbitak, 0);
  const spaleteDodatakSum = otvoriDetalji.reduce((s, x) => s + x.spalete, 0);
  
  // ⭐ Sume barijera/debljina (već su pre-flag-ane na _unutar_plohe gore u kodu)
  // ⭐ v448 (Ivan, 18.05.2026): m² čitanje pattern sinhroniziran s otvorima:
  //   prefer svježi Š×V > 0, fallback na cached _m2/m2.
  //   PRIJE: za canvas-crtane PB (ne manual override), uvijek koristio cached m² →
  //          ako FE ne ažurira cached field nakon promjene dimenzija, Excel pokazuje stari broj.
  //   SAD:   ako b.sirina_m > 0 i b.visina_m > 0 (uvijek slučaj kad FE ima geometriju), 
  //          koristi Š×V (svježe nakon canvas drag). Cached _m2 samo kao fallback za stavke
  //          bez Š/V (rijetko).
  let barijereUnutar = 0, barijereIzvan = 0;
  barijere.forEach(b => {
    const isManual = !!(b._manual_override && b._manual_sirina && b._manual_visina);
    const sirina = isManual ? parseFloat(b._manual_sirina) : parseFloat(b.sirina_m || 0);
    const visina = isManual ? parseFloat(b._manual_visina) : parseFloat(b.visina_m || 0);
    const sXv = sirina * visina;
    const m2Cached = parseFloat(b._m2 || b.m2 || 0);
    const m2 = sXv > 0 ? sXv : m2Cached;
    const m2Total = m2 * (parseInt(b.kolicina || 1) || 1);
    if (b._unutar_plohe) barijereUnutar += m2Total;
    else barijereIzvan += m2Total;
  });
  const barijereSum = barijereUnutar + barijereIzvan;
  
  let debljineUnutar = 0, debljineIzvan = 0;
  debljine.forEach(d => {
    const isManual = !!(d._manual_override && d._manual_sirina && d._manual_visina);
    const sirina = isManual ? parseFloat(d._manual_sirina) : parseFloat(d.sirina_m || 0);
    const visina = isManual ? parseFloat(d._manual_visina) : parseFloat(d.visina_m || 0);
    const sXv = sirina * visina;
    const m2Cached = parseFloat(d._m2 || d.m2 || 0);
    const m2 = sXv > 0 ? sXv : m2Cached;
    const m2Total = m2 * (parseInt(d.kolicina || 1) || 1);
    if (d._unutar_plohe) debljineUnutar += m2Total;
    else debljineIzvan += m2Total;
  });
  const debljineSum = debljineUnutar + debljineIzvan;
  
  let sitniceSum = 0;
  sitnice.forEach(s => {
    if (s.jedinica === 'm2' || !s.jedinica) {
      sitniceSum += parseFloat(s.m2 || s.kolicina || 0);
    }
  });
  
  // ═══════════════════════════════════════════════════════════════════════
  // OBRAČUN — Ivanov koncept (v135.7.23)
  //   A) GLAVNA PLOHA: ploha − PB − D = ČISTI EPS materijal (za fakturiranje)
  //   B) ODBITAK OTVORA + ŠPALETE (GN 421) → NETO ZA FAKTURIRANJE EPS-a
  //   C) Sekcija POŽARNE BARIJERE (lista + ukupno) — fakturira se posebno
  //   D) Sekcija RAZLIČITE DEBLJINE (lista + ukupno) — fakturira se posebno  
  //   E) SVEUKUPNO BRUTO (kontrola = Σ ploha = čisti EPS + PB + D)
  // ═══════════════════════════════════════════════════════════════════════
  
  // Pročitaj naziv pročelja + tip izolacije za naslov plohe
  const debljinaCm = Math.round(defDebljinaM * 100);
  const tipIzolacije = (f.tip_izolacije || f.materijal || 'EPS').toString();
  const proceljeNaziv = f.naziv_objekta || 'Nacrt';
  const plohaOpis = `${proceljeNaziv} — ${debljinaCm}cm ${tipIzolacije}`;
  
  // Helper kalkulacije — Ivanov koncept (v135.7.23, BUG FIX v337):
  //    Pločica EPS (čisti materijal) = Σ ploha − PB UNUTAR plohe − D UNUTAR plohe
  //    ⭐ v337 (Ivan): koristi SAMO _unutar_plohe stavke!
  //       PROBLEM (do v336): koristilo `barijereSum` i `debljineSum` (= unutar + izvan)
  //         → ako su PB/D klasificirane IZVAN plohe (pribraja se brutu, ne preklapaju s plohom),
  //           pogrešno su se oduzimale od cistiEps.
  //         Primjer (Ivan screenshot Istok): plohaSum=162.89, D1+D2 izvan plohe = 24.65 m²
  //           Pre v337: cistiEps = 162.89 − 24.65 = 138.24  ← KRIVO
  //           v337:     cistiEps = 162.89 − 0 = 162.89      ← TOČNO (D je izvan plohe)
  //    Izvan-plohe stavke (D izvan, PB izvan) NE oduzimaju se nigdje — one se 
  //    samostalno fakturiraju (sekcije C i D), a u kontrolnom redu E pribrajaju brutu.
  const cistiEps = Math.max(0, plohaSum - barijereUnutar - debljineUnutar);
  const netoEps = Math.max(0, cistiEps - otvoriOdbitakSum + spaleteDodatakSum);
  // Sveukupno bruto = plohe + ono što je izvan plohe (pribraja se brutu)
  //   Identično: plohaSum + barijereIzvan + debljineIzvan (= bruto pročelja kao u canvas)
  // ⭐ v354 (Ivan): + ZT (zid iz tlocrta) — van plohe, mora ulaziti u SVEUKUPNO BRUTO/NETO da se
  //   poklapa s naslovnicom (UKUPNO NETO) i PREGLED tablicom. Bez ovog je per-procjena list manji za ZT.
  const ztBrutoSheet_354 = (typeof _klasKnjigaZtBruto === 'function') ? _klasKnjigaZtBruto(f) : 0;
  const sveukupnoBruto = plohaSum + barijereIzvan + debljineIzvan + ztBrutoSheet_354;
  
  // ── Header sekcije OBRAČUN ──
  // ⭐ v358 bugfix: full width za landscape A4 (9 stupaca s Napomena)
  ws.mergeCells(r, 1, r, 9);
  ws.getCell(r, 1).value = isSpaleteMod
    ? 'OBRAČUN — špalete mod'
    : 'OBRAČUN — po GN 421';
  ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 16;
  r++;
  
  // Header tablice obračuna
  // ⭐ v357 (Ivan, 16.05.2026): dodan 9. stupac "Napomena" — korisnikov tekst iz app-a za PB, D, otvore.
  //   Stupci 5 ("š (m)") i 6 ("v (m)") sad imaju hibridni opis "š/Pov. (m/m²)" za stavke 
  //   bez stvarnih dimenzija (PB/D manualne) — u tom slučaju stupac 5 nosi POVRŠINU JEDINIČNU 
  //   (m²/kom) umjesto širine. Pravi A) GLAVNA PLOHA i dalje koristi š = širina, v = visina.
  const obrHdr = ['Br.', 'Stavka', 'Detalj / Formula', '', 'š / Pov. (m/m²)', 'v (m)', 'kom', 'Vrijednost (m²)', 'Napomena'];
  obrHdr.forEach((v, i) => {
    if (!v) return;
    const c = ws.getCell(r, i+1);
    c.value = v;
    c.font = { bold: true, size: 9, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF475569' } };
    c.alignment = { horizontal: i >= 4 && i < 8 ? 'right' : 'left', vertical: 'middle', indent: 1 };
  });
  ws.mergeCells(r, 3, r, 4);
  ws.getRow(r).height = 15;
  r++;
  
  // Helper za red obračuna
  // ⭐ v357 (Ivan, 16.05.2026): dodan 10. parametar `napomena` (stupac 9). Default null.
  //   Postojeći pozivi (8-9 argumenata) i dalje rade jer napomena ostaje undefined.
  const obrRed = (br, stavka, detalj, sirina, visina, kom, vrijednost, color, italic, napomena) => {
    ws.getCell(r, 1).value = br;
    ws.getCell(r, 2).value = stavka;
    ws.mergeCells(r, 3, r, 4);
    ws.getCell(r, 3).value = detalj;
    ws.getCell(r, 3).font = { size: 9, italic: !!italic, color: { argb: italic ? 'FF6b7280' : 'FF334155' } };
    ws.getCell(r, 3).alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    if (sirina != null) { ws.getCell(r, 5).value = sirina; ws.getCell(r, 5).numFmt = '0.00'; }
    if (visina != null) { ws.getCell(r, 6).value = visina; ws.getCell(r, 6).numFmt = '0.00'; }
    if (kom != null) ws.getCell(r, 7).value = kom;
    if (vrijednost != null) {
      ws.getCell(r, 8).value = vrijednost;
      ws.getCell(r, 8).numFmt = '0.00';
      ws.getCell(r, 8).font = { bold: true, color: { argb: color || 'FF334155' } };
    }
    // ⭐ v357: napomena stupac 9
    if (napomena != null && napomena !== '') {
      ws.getCell(r, 9).value = String(napomena);
      ws.getCell(r, 9).font = { size: 8.5, italic: true, color: { argb: 'FF475569' } };
      ws.getCell(r, 9).alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    }
    [1,2,5,6,7,8,9].forEach(ci => {
      const c = ws.getCell(r, ci);
      c.font = c.font || { size: 9 };
      c.alignment = c.alignment || { horizontal: ci >= 5 && ci < 9 ? 'right' : 'left', vertical: 'middle', indent: 1 };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
    });
    ws.getCell(r, 3).border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
    ws.getRow(r).height = 16;
    r++;
  };
  
  // ═══════════════════════════════════════════════════════════════
  // A) GLAVNA PLOHA: [pročelje] — [materijal] [debljina]cm
  // ⭐ v337 (Ivan): naslov koristi POPIS PLOHA (npr. "Istok — EPS 16cm") 
  //    konzistentan s finalnim "NETO ZA FAKTURIRANJE" naslovom dolje.
  //    Stupac "Detalj / Formula" ostaje prazan u A redovima (Ivan: nebitan).
  //    Subtotal "= ČISTI EPS" UKLONJEN — između A i B nema više duplicirajućeg subtotala,
  //    finalni "🟢 NETO ZA FAKTURIRANJE" pokriva sve.
  // ═══════════════════════════════════════════════════════════════
  
  // Skupi opis ploha (= naslov A i naslov NETO) — preuzeto iz logike NETO sekcije
  const ploheKomboA = new Set();
  ravnine.forEach(rv => {
    (Array.isArray(rv.plohe) ? rv.plohe : []).forEach(pl => {
      const op = (pl._oznaka || pl.opis || pl.naziv || '').toString().trim();
      const mat = (pl.materijal || tipIzolacije || 'EPS').toString().trim();
      const debCm = pl.debljina_cm || debljinaCm || 15;
      const kombo = op 
        ? `${op} — ${mat} ${debCm}cm`
        : `${mat} ${debCm}cm`;
      ploheKomboA.add(kombo);
    });
  });
  const plohaOpisListaA = ploheKomboA.size > 0 
    ? Array.from(ploheKomboA).join(' + ') 
    : `${tipIzolacije} ${debljinaCm}cm`;
  
  ws.mergeCells(r, 1, r, 9);
  ws.getCell(r, 1).value = `📐 A) GLAVNA PLOHA — ${plohaOpisListaA}`;
  ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };  // tamno zelena
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 16;
  r++;
  
  // ⭐ v337: prazan "Detalj" string + odbici koriste samo "unutar" sume
  obrRed(null, 'Σ plohe', '', null, null, null, plohaSum, 'FF1e40af');
  if (barijereUnutar > 0) {
    obrRed(null, '− Pož. barijere u plohi', '', null, null, null, -barijereUnutar, 'FFEF4444');
  }
  if (debljineUnutar > 0) {
    obrRed(null, '− Razl. debljine u plohi', '', null, null, null, -debljineUnutar, 'FF0891B2');
  }
  // ⭐ v337: UKLONJEN "= ČISTI EPS XXcm (za obračun EPS-a)" subtotal — 
  //    sad ide direktno na B sekciju (odbitak otvora) pa na finalni NETO ZA FAKTURIRANJE.
  
  // ═══════════════════════════════════════════════════════════════
  // B) ODBITAK OTVORA (GN 421) + ŠPALETE → NETO ZA FAKTURIRANJE
  // ═══════════════════════════════════════════════════════════════
  if (otvoriDetalji.length > 0) {
    ws.getRow(r).height = 6; r++;
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = `🪟 B) ODBITAK OTVORA ${isSpaleteMod ? '(otvori potpuno)' : '(po GN 421)'}`;
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEAB308' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 15;
    r++;
    
    otvoriDetalji.forEach((d, i) => {
      // ⭐ v357 (Ivan, 16.05.2026): globalna oznaka kroz sva pročelja (kao na hatchu)
      const _ofsOtv_357 = (f._proceljeOffset && f._proceljeOffset.otvori) || 0;
      const oznaka = 'O' + (_ofsOtv_357 + i + 1);
      const opisStavke = `${d.opis || d.tipLabel}`;
      let formulaTxt;
      if (isSpaleteMod) {
        formulaTxt = `${d.m2.toFixed(2)} × ${d.kol} = ${(d.m2 * d.kol).toFixed(2)} m² (cijeli odbitak)`;
      } else if (d.kategorija === 'mali') {
        formulaTxt = `${d.m2.toFixed(2)} m² ≤ 3 m² → ne odbija (GN 421)`;
      } else if (d.kategorija === 'srednji') {
        formulaTxt = `(${d.m2.toFixed(2)} − 3) × ${d.kol} = ${d.odbitak.toFixed(2)} m²`;
      } else {
        formulaTxt = `(${d.m2.toFixed(2)} − 3) × ${d.kol} = ${d.odbitak.toFixed(2)} m² + špalete`;
      }
      const odbitakPrikaz = d.odbitak > 0 ? -d.odbitak : 0;
      // ⭐ v357 (Ivan, 16.05.2026): napomena otvora u stupac 9 (d.o = original otvor objekt)
      obrRed(oznaka, opisStavke, formulaTxt, d.sirina, d.visina, d.kol, odbitakPrikaz, 'FFEAB308', false, d.o && d.o.napomena);
      // Špalete (samo ako kategorija veliki, GN 421 mod)
      if (!isSpaleteMod && d.kategorija === 'veliki' && d.spalete > 0) {
        // ⭐ v135.7.251: prikaži debljinu iz plohe (d.debljinaM × 100 = cm), ne globalnu
        const debCm = ((d.debljinaM || defDebljinaM) * 100).toFixed(0);
        // ⭐ v451 (Ivan, 18.05.2026): prefer svježi Š/V iz aplikacije (d.sirina/d.visina iz otvorMjere).
        //   PRIJE (v446): koristio d._spalete_s/d._spalete_v koji su mogli biti sqrt fallback (√m²).
        //                 To je prikazivalo krive brojeve ("(2×3.76 + 3.76) × 0.16m" umjesto realnih Š/V).
        //   SAD (v451):   ako d.sirina > 0 i d.visina > 0 (uvijek kad FE ima geometriju), koristi to.
        //                 sqrt fallback samo za otvore bez Š/V (legacy, rijetko).
        const _sShow = (d.sirina > 0 && d.visina > 0) ? d.sirina : (d._spalete_s != null ? d._spalete_s : 0);
        const _vShow = (d.sirina > 0 && d.visina > 0) ? d.visina : (d._spalete_v != null ? d._spalete_v : 0);
        const _isFallback = !(d.sirina > 0 && d.visina > 0) && !!d._spalete_fallback;
        const _fbHint = _isFallback ? ' (√ knjiga Š=V iz m²)' : '';
        obrRed(null, '  + špalete', `(2×${_vShow.toFixed(2)} + ${_sShow.toFixed(2)}) × ${(d.debljinaM || defDebljinaM).toFixed(2)}m (${debCm}cm) × ${d.kol} = ${d.spalete.toFixed(2)} m²${_fbHint}`, null, null, null, d.spalete, 'FF7C3AED', true);
      }
    });
    
    // Otvori subtotal
    if (otvoriOdbitakSum > 0 || spaleteDodatakSum > 0) {
      const podzbroj = -otvoriOdbitakSum + spaleteDodatakSum;
      ws.mergeCells(r, 1, r, 7);
      ws.getCell(r, 1).value = `Σ otvori i špalete: − ${otvoriOdbitakSum.toFixed(2)} + ${spaleteDodatakSum.toFixed(2)}`;
      ws.getCell(r, 1).font = { bold: true, italic: true, size: 9, color: { argb: 'FFEAB308' } };
      ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
      ws.getCell(r, 8).value = podzbroj;
      ws.getCell(r, 8).numFmt = '0.00';
      ws.getCell(r, 8).font = { bold: true, size: 10, color: { argb: 'FFEAB308' } };
      ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
      ws.getRow(r).height = 16;
      r++;
    }
  }
  
  // ── NETO ZA FAKTURIRANJE EPS-a (highlighted) ──
  ws.getRow(r).height = 6; r++;
  // ⭐ v314 (Ivan): NETO ZA FAKTURIRANJE koristi PER-PLOHA materijal/debljinu.
  //    Razlog: Ivan može imati različite materijale u različitim plohama (npr. zapadna 
  //    EPS 16cm, južna MW 12cm). v312 je koristio procjena-level tipIzolacije/debljinaCm 
  //    kao zajednički suffix → krivo prikazivao kad ploha ima vlastiti materijal.
  //    SAD: skupi (opis, materijal, debljina) trojke iz svake plohe, formiraj 
  //    unique kombinacije, spojiti s " + ".
  const ploheKombo = new Set();
  ravnine.forEach(rv => {
    (Array.isArray(rv.plohe) ? rv.plohe : []).forEach(pl => {
      const op = (pl._oznaka || pl.opis || pl.naziv || '').toString().trim();
      const mat = (pl.materijal || tipIzolacije || 'EPS').toString().trim();
      const debCm = pl.debljina_cm || debljinaCm || 15;
      const kombo = op 
        ? `${op} — ${mat} ${debCm}cm`
        : `${mat} ${debCm}cm`;
      ploheKombo.add(kombo);
    });
  });
  const plohaOpisLista = ploheKombo.size > 0 
    ? Array.from(ploheKombo).join(' + ') 
    : `${tipIzolacije} ${debljinaCm}cm`;
  
  ws.mergeCells(r, 1, r, 7);
  // ⭐ v356 (Ivan, 15.05.2026): u listu pročelja maknuti "NETO ZA FAKTURIRANJE" prefix —
  //   neka piše samo "Zapadno — EPS 16cm:" (naziv pročelja + opis materijala/debljine).
  //   Single-procjena view (legacy, _isPerProceljeView=false) ostaje s postojećim naslovom.
  // ⭐ v357 (Ivan, 16.05.2026): per-pročelje naslov pojednostavljen — bez materijala/opisa plohe,
  //   samo "Južno - 16cm" (oznaka pročelja + debljina). Skupljaju se UNIQUE debljine kroz sve plohe 
  //   pročelja; ako ih je više (npr. mix EPS 16cm + XPS 18cm) joinaju s " + " → "Južno - 16cm + 18cm".
  if (_isPerProceljeView && f._proceljeOznaka) {
    const debljineSet_357 = new Set();
    ravnine.forEach(rv => {
      (Array.isArray(rv.plohe) ? rv.plohe : []).forEach(pl => {
        const debCm = pl.debljina_cm || debljinaCm || 15;
        debljineSet_357.add(`${debCm}cm`);
      });
    });
    const debljinaSuffix_357 = debljineSet_357.size > 0 
      ? Array.from(debljineSet_357).join(' + ') 
      : `${debljinaCm}cm`;
    ws.getCell(r, 1).value = `${f._proceljeOznaka} - ${debljinaSuffix_357}`;
  } else {
    ws.getCell(r, 1).value = `🟢 NETO ZA FAKTURIRANJE ${plohaOpisLista}:`;
  }
  ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };  // ⭐ v381: 14→13
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };
  ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getCell(r, 8).value = netoEps;
  ws.getCell(r, 8).numFmt = '0.00 "m²"';
  ws.getCell(r, 8).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };  // ⭐ v381: 14→13
  ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };
  ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
  // ⭐ v357: napomena stupac 9 fill match (zelena) — vizualno čist red
  ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };
  ws.getRow(r).height = 22;  // ⭐ v381 (Ivan): 30→22 — preveliki red zauzima preveć prostora
  r++;
  
  // ═══════════════════════════════════════════════════════════════
  // C) POŽARNE BARIJERE — samostalna sekcija (fakturira se posebno)
  // ═══════════════════════════════════════════════════════════════
  if (barijere.length > 0 && barijereSum > 0) {
    ws.getRow(r).height = 8; r++;
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = '🔥 C) POŽARNE BARIJERE — drugi materijal, fakturira se posebno';
    ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEF4444' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 16;
    r++;
    
    barijere.forEach((b, i) => {
      // ⭐ v357 (Ivan, 16.05.2026): globalna oznaka kroz sva pročelja (kao na hatchu)
      const _ofsBar_357 = (f._proceljeOffset && f._proceljeOffset.barijere) || 0;
      const isManual = !!(b._manual_override && b._manual_sirina && b._manual_visina);
      const sirinaB = isManual ? parseFloat(b._manual_sirina) : parseFloat(b.sirina_m || 0);
      const visinaB = isManual ? parseFloat(b._manual_visina) : parseFloat(b.visina_m || 0);
      // ⭐ v448 (Ivan, 18.05.2026): prefer svježi Š×V > 0 (canvas dimenzije), fallback cached _m2
      const sXv_B = sirinaB * visinaB;
      const m2B_cached = parseFloat(b._m2 || b.m2 || 0);
      const m2B = sXv_B > 0 ? sXv_B : m2B_cached;
      const kolB = parseInt(b.kolicina || 1) || 1;
      const ukupnoB = m2B * kolB;
      const opisB = b.opis || `Pož. barijera ${_ofsBar_357 + i + 1}`;
      const formulaB = (sirinaB > 0 && visinaB > 0)
        ? `${sirinaB.toFixed(2)} × ${visinaB.toFixed(2)} × ${kolB} = ${ukupnoB.toFixed(2)} m²`
        : `${m2B.toFixed(2)} m² × ${kolB} = ${ukupnoB.toFixed(2)} m²`;
      // ⭐ v357 (Ivan, 16.05.2026): kad nema dimenzija → stupac 5 nosi POVRŠINU JEDINIČNU (m²),
      //   stupac 6 prazan. Napomena (b.napomena) ide u stupac 9.
      const sirinaPrikaz_357 = (sirinaB > 0 && visinaB > 0) ? sirinaB : m2B;
      const visinaPrikaz_357 = (sirinaB > 0 && visinaB > 0) ? visinaB : null;
      obrRed('PB' + (_ofsBar_357 + i + 1), opisB, formulaB, sirinaPrikaz_357, visinaPrikaz_357, kolB, ukupnoB, 'FFEF4444', false, b.napomena);
    });
    
    // Total PB
    ws.mergeCells(r, 1, r, 7);
    ws.getCell(r, 1).value = 'UKUPNO POŽARNE BARIJERE:';
    ws.getCell(r, 1).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEF4444' } };
    ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    ws.getCell(r, 8).value = barijereSum;
    ws.getCell(r, 8).numFmt = '0.00 "m²"';
    ws.getCell(r, 8).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEF4444' } };
    ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
    // ⭐ v357: napomena stupac 9 fill match (crveno) — vizualno čist red
    ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEF4444' } };
    ws.getRow(r).height = 18;
    r++;
  }
  
  // ═══════════════════════════════════════════════════════════════
  // D) RAZLIČITE DEBLJINE — samostalna sekcija (fakturira se posebno)
  // ═══════════════════════════════════════════════════════════════
  if (debljine.length > 0 && debljineSum > 0) {
    ws.getRow(r).height = 8; r++;
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = '🎨 D) RAZLIČITE DEBLJINE';
    ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0891B2' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 16;
    r++;
    
    debljine.forEach((d, i) => {
      // ⭐ v357 (Ivan, 16.05.2026): globalna oznaka kroz sva pročelja (kao na hatchu)
      const _ofsDeb_357 = (f._proceljeOffset && f._proceljeOffset.debljine) || 0;
      const isManual = !!(d._manual_override && d._manual_sirina && d._manual_visina);
      const sirinaD = isManual ? parseFloat(d._manual_sirina) : parseFloat(d.sirina_m || 0);
      const visinaD = isManual ? parseFloat(d._manual_visina) : parseFloat(d.visina_m || 0);
      // ⭐ v448 (Ivan, 18.05.2026): prefer svježi Š×V > 0 (canvas dimenzije), fallback cached _m2
      const sXv_D = sirinaD * visinaD;
      const m2D_cached = parseFloat(d._m2 || d.m2 || 0);
      const m2D = sXv_D > 0 ? sXv_D : m2D_cached;
      const kolD = parseInt(d.kolicina || 1) || 1;
      const ukupnoD = m2D * kolD;
      // ⭐ v357: napomena više NIJE u opisStavke (prelazi u zaseban stupac 9)
      const opisD = d.opis || `Razl. debljina ${_ofsDeb_357 + i + 1}`;
      const formulaD = (sirinaD > 0 && visinaD > 0)
        ? `${sirinaD.toFixed(2)} × ${visinaD.toFixed(2)} × ${kolD} = ${ukupnoD.toFixed(2)} m²`
        : `${m2D.toFixed(2)} m² × ${kolD} = ${ukupnoD.toFixed(2)} m²`;
      // ⭐ v357 (Ivan, 16.05.2026): kad nema dimenzija → stupac 5 nosi POVRŠINU JEDINIČNU (m²)
      const sirinaPrikaz_357 = (sirinaD > 0 && visinaD > 0) ? sirinaD : m2D;
      const visinaPrikaz_357 = (sirinaD > 0 && visinaD > 0) ? visinaD : null;
      obrRed('D' + (_ofsDeb_357 + i + 1), opisD, formulaD, sirinaPrikaz_357, visinaPrikaz_357, kolD, ukupnoD, 'FF0891B2', false, d.napomena);
    });
    
    // Total D
    ws.mergeCells(r, 1, r, 7);
    ws.getCell(r, 1).value = 'UKUPNO RAZLIČITE DEBLJINE:';
    ws.getCell(r, 1).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0891B2' } };
    ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    ws.getCell(r, 8).value = debljineSum;
    ws.getCell(r, 8).numFmt = '0.00 "m²"';
    ws.getCell(r, 8).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0891B2' } };
    ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
    // ⭐ v357: napomena stupac 9 fill match (cyan) — vizualno čist red
    ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0891B2' } };
    ws.getRow(r).height = 18;
    r++;
  }
  
  // ═══════════════════════════════════════════════════════════════
  // E) SVEUKUPNO BRUTO (KONTROLA)
  // ⭐ v337 (Ivan): preformulirano da prikazuje stvarni izračun bruta:
  //   Bruto pročelja = Σ plohe + PB izvan plohe + D izvan plohe
  //   (Stavke "u plohi" se NE pribrajaju — one su konceptualno DIO plohe.)
  // ═══════════════════════════════════════════════════════════════
  ws.getRow(r).height = 10; r++;
  ws.mergeCells(r, 1, r, 9);
  ws.getCell(r, 1).value = '✅ E) KONTROLA — SVEUKUPNO BRUTO';
  ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 16;
  r++;
  
  obrRed(null, 'Σ plohe (sve ravnine)', '', null, null, null, plohaSum, 'FF1e40af');
  if (barijereIzvan > 0) {
    obrRed(null, '+ Pož. barijere izvan plohe', '', null, null, null, barijereIzvan, 'FFEF4444');
  }
  if (debljineIzvan > 0) {
    obrRed(null, '+ Razl. debljine izvan plohe', '', null, null, null, debljineIzvan, 'FF0891B2');
  }
  // ⭐ v354 (Ivan): + ZID IZ TLOCRTA (ZT) — van plohe, prikaži kao zaseban red i uključi u kontrolu
  if (ztBrutoSheet_354 > 0) {
    obrRed(null, '+ Zid iz tlocrta (ZT)', '', null, null, null, ztBrutoSheet_354, 'FF7e22ce');
  }
  
  // Suma (= sveukupnoBruto po definiciji, kontrola je trivijalno OK matematički)
  const kontrolaSuma = plohaSum + barijereIzvan + debljineIzvan + ztBrutoSheet_354;  // ⭐ v354: + ZT
  const kontrolaOk = Math.abs(sveukupnoBruto - kontrolaSuma) < 0.05;
  ws.mergeCells(r, 1, r, 7);
  ws.getCell(r, 1).value = `= SVEUKUPNO BRUTO ${kontrolaOk ? '✓' : '⚠️'} (plohe + izvan plohe)`;
  ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: kontrolaOk ? 'FF1e40af' : 'FFDC2626' } };
  ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getCell(r, 8).value = sveukupnoBruto;
  ws.getCell(r, 8).numFmt = '0.00 "m²"';
  ws.getCell(r, 8).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };  // ⭐ v381: 14→13
  ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: kontrolaOk ? 'FF1e40af' : 'FFDC2626' } };
  ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
  // ⭐ v357: napomena stupac 9 fill match (plavo ili crveno) — vizualno čist red
  ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: kontrolaOk ? 'FF1e40af' : 'FFDC2626' } };
  ws.getRow(r).height = 22;  // ⭐ v381 (Ivan): 30→22 komprimirano
  r++;
  
  // ⭐ v449 (Ivan, 18.05.2026): dodan SVEUKUPNO NETO red ispod SVEUKUPNO BRUTO.
  //   Formula: NETO = BRUTO − GN 421 odbitak + GN 421 špalete
  //   Razlog: Ivan: "treba odgovarati na naslovnici ukupno neto površina fasade".
  //   Za jednostavnu fasadu (bez PB/D unutar/sitnice/razvijene), Σ per-procelje NETO 
  //   = naslovnica "UKUPNO NETO POVRŠINA FASADE". Za kompleksne fasade može se razlikovati 
  //   zbog dodatnih stavki na naslovnici (PB ukupno, D ukupno, sitnice, razvijene), 
  //   ali ovaj red služi kao "neto za fakturiranje EPS-a po pročelju" — najjednostavnija 
  //   slika za nadzor i investitora.
  const sveukupnoNeto_449 = Math.max(0, sveukupnoBruto - otvoriOdbitakSum + spaleteDodatakSum);
  ws.mergeCells(r, 1, r, 7);
  ws.getCell(r, 1).value = `= SVEUKUPNO NETO  (bruto − GN 421 odbitak + GN 421 špalete)`;
  ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };  // zelena (kao "Istočno - 16cm" red)
  ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getCell(r, 8).value = sveukupnoNeto_449;
  ws.getCell(r, 8).numFmt = '0.00 "m²"';
  ws.getCell(r, 8).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };
  ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle' };
  ws.getCell(r, 9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803D' } };
  ws.getRow(r).height = 22;
  r++;
  
  // Backward compat: stara `neto` varijabla za eventualne reference niže
  const neto = netoEps;
  
  // ⭐ DODATNE STAVKE (sitnice) — info, ako su u m² ide u BRUTO ali ne u sekciju D
  // Ostaje za backward compat, ne mijenjamo strukturu sekcija A–E
  
  // ═══ 6. NAPOMENA ═══
  if (f.napomena) {
    ws.getRow(r).height = 5; r++;
    ws.mergeCells(r, 1, r, 9);
    ws.getCell(r, 1).value = 'NAPOMENA';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 15;
    r++;
    ws.mergeCells(r, 1, r+2, 9);
    ws.getCell(r, 1).value = f.napomena;
    ws.getCell(r, 1).font = { size: 10 };
    ws.getCell(r, 1).alignment = { wrapText: true, vertical: 'top', horizontal: 'left', indent: 1 };
    r += 3;
  }
  
  // ═══ 7. OVJERA ═══
  ws.getRow(r).height = 8; r++;
  ws.mergeCells(r, 1, r, 9);
  ws.getCell(r, 1).value = 'OVJERA OBRAČUNA';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 15;
  r++;
  ws.getRow(r).height = 8; r++;
  // ⭐ v357: split 4+5 (stupci 1-4 + 5-9) umjesto 4+4 da pokrije i napomena stupac
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'Datum: ____________________';
  ws.mergeCells(r, 5, r, 9);
  ws.getCell(r, 5).value = 'Datum: ____________________';
  r++;
  ws.getRow(r).height = 8; r++;
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'OVJERA IZVOĐAČA:';
  ws.getCell(r, 1).font = { bold: true, size: 9 };
  ws.mergeCells(r, 5, r, 9);
  ws.getCell(r, 5).value = 'OVJERA NADZORA:';
  ws.getCell(r, 5).font = { bold: true, size: 9 };
  r++;
  // ⭐ v135.7.378 (Ivan): pečat + potpis preko crtica za izvođača (spontani izgled)
  //   Helper umeće slike kao overlay - ne pomiče redove. Pečat ide preko sljedećih 2-3 redaka.
  ws.getRow(r).height = 30;  // veći red za pečat
  _knjigaUmetniPecatPotpis(ws, ws.workbook, r, 1, 4);
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = '';  // prazna ćelija (pečat ide preko)
  ws.mergeCells(r, 5, r, 9);
  ws.getCell(r, 5).value = '___________________________';
  r++;
  ws.getRow(r).height = 16;  // dodatni prostor za pečat 
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'Ivan Čakarić · ŽBUKA Čakarić d.o.o.';
  ws.getCell(r, 1).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
  ws.mergeCells(r, 5, r, 9);
  ws.getCell(r, 5).value = '(ime, prezime, potpis)';
  ws.getCell(r, 5).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
  r++;
  
  if (!ws._pageBreaks) ws._pageBreaks = [];
  ws._pageBreaks.push(r);
  
  return r + 1;
}

async function generirajExcelProcjenu(ws, f, pocetniRed, gradilisteNaziv, gradilisteAdresa) {
  // FAZA A: ravnine koncept — drugačiji generator (manual mjere, plohe iz ravnine_json, otvori iz otvori_json)
  // Auto-promicija: ako procjena ima ravnine_json (Faza A flow), uvijek koristi ravnine generator
  // (čak i ako je koncept ostao 'klasicni' iz nekog razloga, npr. legacy update kroz drugi endpoint)
  const imaRavnine = Array.isArray(f.ravnine_json) && f.ravnine_json.length > 0;
  if (f.koncept === 'ravnine' || imaRavnine) {
    return generirajExcelProcjenuRavnine(ws, f, pocetniRed, gradilisteNaziv, gradilisteAdresa);
  }
  
  // LEGACY 'klasicni' koncept (originalna AI bbox detekcija — bez ravnina)
  const RED = 'FFCC0000';
  const DARK = 'FF1a1a2e';
  const LBKG = 'FFf8f9fa';
  const BORD = 'FFdee2e6';

  let r = pocetniRed;

  // 1. HEADER: ŽBUKA logo + naslov dokumenta
  // Spojeni redovi A:H za header
  const logoRow = r;
  // ⭐ v372 (Ivan, 16.05.2026): Logo veći — 100×50 → 130×65 px, header row 60→75
  ws.getRow(r).height = 75;

  // Ubaci logo (lijevo, A1:B header area)
  try {
    const ws_workbook = ws.workbook;
    if (!ws._logoImageId) {
      // Logo se dodaje JEDNOM u workbook, ne po sheetu
      // Koristim postojeći LOGO_B64 koji je gore u datoteci definiran
      const logoImageId = ws_workbook.addImage({
        base64: 'data:image/png;base64,' + LOGO_B64,
        extension: 'png',
      });
      ws._logoImageId = logoImageId;
    }
    ws.addImage(ws._logoImageId, {
      tl: { col: 0.15, row: r - 1 + 0.1 },
      ext: { width: 130, height: 65 }
    });
  } catch(e) { console.warn('[Excel logo]', e.message); }

  // Naslov dokumenta (desno)
  ws.mergeCells(r, 3, r, 8);
  const cT = ws.getCell(r, 3);
  cT.value = 'OBRAČUN GRAĐEVINSKIH RADOVA';
  cT.font = { bold: true, size: 14, color: { argb: RED } };
  cT.alignment = { horizontal: 'right', vertical: 'middle' };

  r++;
  ws.mergeCells(r, 3, r, 8);
  const cT2 = ws.getCell(r, 3);
  cT2.value = '(Građevinska knjiga · Fasaderski radovi)';
  cT2.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
  cT2.alignment = { horizontal: 'right' };

  r++;
  // Crvena crta
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
  ws.getRow(r).height = 4;
  r++;

  // 2. INFO BLOK: gradilište / datum / izvođač
  ws.getRow(r).height = 5; r++; // razmak

  const datum = new Date(f.created_at);
  const datumFormat = fmtDate(datum);

  const infoRows = [
    ['Gradilište:', gradilisteNaziv || '?', 'Datum knjige:', datumFormat],
    ['Adresa:',     gradilisteAdresa || '-', 'Metoda:', 'Ref. ravnine + perspektiva (±2%)'],
    ['Izvođač:',    'ŽBUKA Čakarić d.o.o.', 'Voditelj:', f.kreirao || 'Ivan Čakarić'],
    ['OIB:',        '46540647857',          'Tip objekta:', FAS_TIP_OBJEKTA_LABELS[f.tip_objekta] || '-'],
  ];

  infoRows.forEach(row => {
    ws.getCell(r, 1).value = row[0];
    ws.getCell(r, 1).font = { bold: true, size: 9, color: { argb: 'FF6b7280' } };
    ws.mergeCells(r, 2, r, 4);
    ws.getCell(r, 2).value = row[1];
    ws.getCell(r, 2).font = { size: 10, color: { argb: DARK } };

    ws.getCell(r, 5).value = row[2];
    ws.getCell(r, 5).font = { bold: true, size: 9, color: { argb: 'FF6b7280' } };
    ws.mergeCells(r, 6, r, 8);
    ws.getCell(r, 6).value = row[3];
    ws.getCell(r, 6).font = { size: 10, color: { argb: DARK } };
    r++;
  });

  ws.getRow(r).height = 5; r++; // razmak

  // 3. NACRT (slika anotirana s plohama i otvorima) — pokusaj umetnuti
  try {
    // Najprije pokusaj ANOTIRANU sliku (sa P1, P2 plohama + obojeni otvori)
    let slikaBuf = await dohvatiAnotiranuSlikuProcjene(f.id);
    let isAnotirana = !!slikaBuf;
    
    // Dijagnostika: log za debugging
    console.log(`[Excel slika proc${f.id}] Anotirana: ${isAnotirana ? 'DA (' + (slikaBuf?.length || 0) + ' bytes)' : 'NE — fallback original'}`);

    // Fallback: ako nema anotirane, koristi originalnu
    if (!slikaBuf) {
      slikaBuf = await dohvatiSlikuProcjene(f.id);
      if (slikaBuf) console.log(`[Excel slika proc${f.id}] Original: ${slikaBuf.length} bytes`);
    }

    if (slikaBuf) {
      // Procitaj originalne dimenzije slike (da odrzi aspect ratio)
      // Veće dimenzije za bolju čitljivost hatcha
      let imgWidth = 720, imgHeight = 405;  // veća za bolju iskorištenost A4  // 16:9 default
      try {
        let foundDims = false;
        if (slikaBuf[0] === 0xFF && slikaBuf[1] === 0xD8) {
          let i = 2;
          while (i < Math.min(slikaBuf.length - 8, 1048576)) {
            if (slikaBuf[i] !== 0xFF) { i++; continue; }
            const marker = slikaBuf[i+1];
            if (marker >= 0xD0 && marker <= 0xD9) { i += 2; continue; }
            if ((marker >= 0xC0 && marker <= 0xC3) ||
                (marker >= 0xC5 && marker <= 0xC7) ||
                (marker >= 0xC9 && marker <= 0xCB) ||
                (marker >= 0xCD && marker <= 0xCF)) {
              const h = (slikaBuf[i+5] << 8) | slikaBuf[i+6];
              const w = (slikaBuf[i+7] << 8) | slikaBuf[i+8];
              if (w > 0 && h > 0 && w < 30000 && h < 30000) {
                const maxW = 460, maxH = 400;  // ⭐ v250: 540→460 da slika stane unutar 8 kolona merged area-e
                const ratio = Math.min(maxW / w, maxH / h);
                imgWidth = Math.round(w * ratio);
                imgHeight = Math.round(h * ratio);
                foundDims = true;
                break;
              }
            }
            // Skip block by length (next 2 bytes after marker)
            const blockLen = (slikaBuf[i+2] << 8) | slikaBuf[i+3];
            if (blockLen <= 0) break;
            i += 2 + blockLen;
          }
        }
        // PNG signature: 89 50 4E 47 0D 0A 1A 0A → IHDR at offset 16
        if (!foundDims && slikaBuf[0] === 0x89 && slikaBuf[1] === 0x50 && 
            slikaBuf[2] === 0x4E && slikaBuf[3] === 0x47) {
          const w = (slikaBuf[16] << 24) | (slikaBuf[17] << 16) | (slikaBuf[18] << 8) | slikaBuf[19];
          const h = (slikaBuf[20] << 24) | (slikaBuf[21] << 16) | (slikaBuf[22] << 8) | slikaBuf[23];
          if (w > 0 && h > 0) {
            const maxW = 460, maxH = 400;  // ⭐ v250: 540→460 da slika stane unutar 8 kolona merged area-e
            const ratio = Math.min(maxW / w, maxH / h);
            imgWidth = Math.round(w * ratio);
            imgHeight = Math.round(h * ratio);
            foundDims = true;
          }
        }
        if (!foundDims) {
          console.warn('[Excel slika] dimenzije nisu detektirane, koristi 4:3 fallback');
        }
      } catch(de) { console.warn('[Excel parse dim]', de.message); }

      // Naslov bloka
      ws.mergeCells(r, 1, r, 8);
      const cN = ws.getCell(r, 1);
      cN.value = isAnotirana
        ? 'NACRT FASADE — anotirano (P1, P2... plohe · O1.. otvori · PB1.. barijere · D1.. debljine)'
        : 'NACRT FASADE (originalna fotografija s referentnim mjerama)';
      cN.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
      cN.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
      cN.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      ws.getRow(r).height = 18;
      r++;

      const ext = (slikaBuf[0] === 0x89 && slikaBuf[1] === 0x50) ? 'png' : 'jpeg';
      // ⭐ v294 (Ivan): JPEG kompresija q=75 (samo za JPEG; PNG ostaje lossless za hatch overlay)
      const slikaBufFinal = (ext === 'jpeg') 
        ? await _compressJpegForExcel(slikaBuf, 75) 
        : slikaBuf;
      const imgId = ws.workbook.addImage({
        buffer: slikaBufFinal,
        extension: ext
      });

      // ⭐ v135.7.252: koristim _excelSlikaPositioning helper (px-bazirano, robust na različite širine stupaca)
      const isHorizontal_2 = imgWidth > imgHeight;
      const tlCol_2 = _excelSlikaPositioning(ws, imgWidth, isHorizontal_2, 8);

      ws.addImage(imgId, {
        tl: { col: tlCol_2, row: r - 1 + 0.1 },
        ext: { width: imgWidth, height: imgHeight },
        editAs: 'oneCell'
      });

      // Rezerviraj redove prema visini slike
      const rezervRows = Math.ceil((imgHeight + 6) / 21);
      for (let i = 0; i < rezervRows; i++) {
        ws.getRow(r + i).height = 21;
      }
      r += rezervRows;
    }
  } catch(e) { console.warn('[Excel slika]', e.message); }

  ws.getRow(r).height = 5; r++; // razmak

  // 4. REFERENTNE MJERE (kako je dobiven izračun)
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = 'REFERENTNE MJERE (za skalu)';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 18;
  r++;

  // Header
  ['Linija', 'Mjera (m)', 'Što je izmjereno', '', '', '', '', ''].forEach((v, i) => {
    if (v) {
      ws.getCell(r, i+1).value = v;
      ws.getCell(r, i+1).font = { bold: true, size: 9 };
      ws.getCell(r, i+1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
      ws.getCell(r, i+1).border = { bottom: { style: 'thin', color: { argb: BORD } } };
    }
  });
  ws.mergeCells(r, 3, r, 8);
  r++;

  // Crvena referenca
  ws.getCell(r, 1).value = '🔴 Crvena (1.)';
  ws.getCell(r, 1).font = { color: { argb: RED }, bold: true, size: 9 };
  ws.getCell(r, 2).value = parseFloat(f.referentna_mjera_m || 0);
  ws.getCell(r, 2).numFmt = '0.00';
  ws.getCell(r, 2).font = { size: 9 };
  ws.mergeCells(r, 3, r, 8);
  ws.getCell(r, 3).value = f.referentni_opis || '-';
  ws.getCell(r, 3).font = { size: 9 };
  r++;

  // Zelena referenca (ako postoji)
  if (f.ref2_mjera_m) {
    ws.getCell(r, 1).value = '🟢 Zelena (2.)';
    ws.getCell(r, 1).font = { color: { argb: 'FF22c55e' }, bold: true, size: 9 };
    ws.getCell(r, 2).value = parseFloat(f.ref2_mjera_m || 0);
    ws.getCell(r, 2).numFmt = '0.00';
    ws.getCell(r, 2).font = { size: 9 };
    ws.mergeCells(r, 3, r, 8);
    ws.getCell(r, 3).value = f.ref2_opis || '-';
    ws.getCell(r, 3).font = { size: 9 };
    r++;
  }

  ws.getRow(r).height = 5; r++; // razmak

  // 5. POVRŠINE (plohe P1, P2, ...)
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = 'POVRŠINE FASADE (BRUTO)';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 18;
  r++;

  // Header tablice
  const povrHeaders = ['Oznaka', 'Opis', 'Širina (m)', 'Visina (m)', 'Površina (m²)', '', '', ''];
  povrHeaders.forEach((v, i) => {
    if (v) {
      ws.getCell(r, i+1).value = v;
      ws.getCell(r, i+1).font = { bold: true, size: 9 };
      ws.getCell(r, i+1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
      ws.getCell(r, i+1).border = { bottom: { style: 'thin', color: { argb: BORD } } };
      ws.getCell(r, i+1).alignment = { horizontal: i >= 2 ? 'right' : 'left', vertical: 'middle' };
    }
  });
  ws.mergeCells(r, 5, r, 8);
  r++;

  // Plohe iz dimenzije_fasade
  const dim = f.dimenzije_fasade || {};
  let bruto = 0;

  // P1 - glavna ploha
  if (dim.glavna_sirina_m && dim.glavna_visina_m) {
    const m2 = parseFloat(dim.glavna_m2 || (dim.glavna_sirina_m * dim.glavna_visina_m));
    ws.getCell(r, 1).value = 'P1';
    ws.getCell(r, 1).font = { bold: true, color: { argb: 'FF3b82f6' } };
    ws.getCell(r, 2).value = 'Glavna ploha';
    ws.getCell(r, 3).value = parseFloat(dim.glavna_sirina_m); ws.getCell(r, 3).numFmt = '0.00';
    ws.getCell(r, 4).value = parseFloat(dim.glavna_visina_m); ws.getCell(r, 4).numFmt = '0.00';
    ws.mergeCells(r, 5, r, 8);
    ws.getCell(r, 5).value = m2;
    ws.getCell(r, 5).numFmt = '0.00';
    ws.getCell(r, 5).font = { bold: true };
    ws.getCell(r, 5).alignment = { horizontal: 'right' };
    [3, 4, 5].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right' });
    bruto += m2;
    r++;
  }

  // Dodatne plohe P2, P3...
  if (Array.isArray(dim.dodatne_plohe)) {
    dim.dodatne_plohe.forEach((p, idx) => {
      const m2 = parseFloat(p.m2 || (p.sirina_m * p.visina_m) || 0);
      ws.getCell(r, 1).value = 'P' + (idx + 2);
      ws.getCell(r, 1).font = { bold: true, color: { argb: 'FFa855f7' } };
      ws.getCell(r, 2).value = p._oznaka || p.opis || 'Dodatna ploha';
      ws.getCell(r, 3).value = parseFloat(p.sirina_m || 0); ws.getCell(r, 3).numFmt = '0.00';
      ws.getCell(r, 4).value = parseFloat(p.visina_m || 0); ws.getCell(r, 4).numFmt = '0.00';
      ws.mergeCells(r, 5, r, 8);
      ws.getCell(r, 5).value = m2;
      ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 5).font = { bold: true };
      ws.getCell(r, 5).alignment = { horizontal: 'right' };
      [3, 4, 5].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right' });
      bruto += m2;
      r++;
    });
  }

  // Ako nema raščlanjenih dimenzija, samo ukupno
  if (!dim.glavna_sirina_m && !dim.dodatne_plohe?.length) {
    bruto = parseFloat(f.ukupna_fasada_m2 || 0);
    ws.getCell(r, 2).value = 'Ukupna fasada (bez raščlanjivanja)';
    ws.getCell(r, 2).font = { italic: true };
    ws.mergeCells(r, 5, r, 8);
    ws.getCell(r, 5).value = bruto;
    ws.getCell(r, 5).numFmt = '0.00';
    ws.getCell(r, 5).font = { bold: true };
    ws.getCell(r, 5).alignment = { horizontal: 'right' };
    r++;
  }

  // SUMA bruto
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'UKUPNO BRUTO (Σ ploha):';
  ws.getCell(r, 1).font = { bold: true, size: 10 };
  ws.getCell(r, 1).alignment = { horizontal: 'right' };
  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).value = parseFloat(f.ukupna_fasada_m2 || bruto);
  ws.getCell(r, 5).numFmt = '0.00 "m²"';
  ws.getCell(r, 5).font = { bold: true, size: 11, color: { argb: DARK } };
  ws.getCell(r, 5).alignment = { horizontal: 'right' };
  ws.getCell(r, 5).border = { top: { style: 'medium' } };
  r++;

  ws.getRow(r).height = 5; r++; // razmak

  // 6. OTVORI (odbitak)
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = 'OTVORI (odbitak od bruto)';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 18;
  r++;

  // Header
  ['Tip', 'Komada', 'Širina (m)', 'Visina (m)', 'm²/kom', 'Ukupno (m²)', '', ''].forEach((v, i) => {
    if (v) {
      ws.getCell(r, i+1).value = v;
      ws.getCell(r, i+1).font = { bold: true, size: 9 };
      ws.getCell(r, i+1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
      ws.getCell(r, i+1).border = { bottom: { style: 'thin', color: { argb: BORD } } };
      ws.getCell(r, i+1).alignment = { horizontal: i >= 1 ? 'right' : 'left', vertical: 'middle' };
    }
  });
  ws.mergeCells(r, 6, r, 8);
  r++;

  let otvoriUkupno = 0;
  const otvori = f.otvori_json || [];
  if (Array.isArray(otvori) && otvori.length) {
    otvori.forEach(o => {
      const kom = parseInt(o.kom || 0);
      const sir = parseFloat(o.sirina_m || 0);
      const vis = parseFloat(o.visina_m || 0);
      const m2k = sir * vis;
      const tot = m2k * kom;

      ws.getCell(r, 1).value = FAS_TIP_LABELS[o.tip] || o.tip;
      ws.getCell(r, 1).font = { size: 9 };
      ws.getCell(r, 2).value = kom;
      ws.getCell(r, 3).value = sir; ws.getCell(r, 3).numFmt = '0.00';
      ws.getCell(r, 4).value = vis; ws.getCell(r, 4).numFmt = '0.00';
      ws.getCell(r, 5).value = m2k; ws.getCell(r, 5).numFmt = '0.00';
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = tot;
      ws.getCell(r, 6).numFmt = '0.00';
      ws.getCell(r, 6).font = { bold: true };
      [2, 3, 4, 5, 6].forEach(c => ws.getCell(r, c).alignment = { horizontal: 'right' });

      otvoriUkupno += tot;
      r++;
    });
  } else {
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '(Nema otvora)';
    ws.getCell(r, 1).font = { italic: true, color: { argb: 'FF6b7280' } };
    r++;
  }

  // SUMA otvora
  ws.mergeCells(r, 1, r, 5);
  ws.getCell(r, 1).value = 'UKUPNO OTVORI:';
  ws.getCell(r, 1).font = { bold: true, size: 10 };
  ws.getCell(r, 1).alignment = { horizontal: 'right' };
  ws.mergeCells(r, 6, r, 8);
  ws.getCell(r, 6).value = otvoriUkupno;
  ws.getCell(r, 6).numFmt = '0.00 "m²"';
  ws.getCell(r, 6).font = { bold: true, size: 11, color: { argb: DARK } };
  ws.getCell(r, 6).alignment = { horizontal: 'right' };
  ws.getCell(r, 6).border = { top: { style: 'medium' } };
  r++;

  ws.getRow(r).height = 8; r++; // razmak

  // ── POŽARNE BARIJERE (ako postoje) ──
  let barijereJson = [];
  try {
    barijereJson = typeof f.pozarne_barijere_json === 'string'
      ? JSON.parse(f.pozarne_barijere_json)
      : (f.pozarne_barijere_json || []);
  } catch(e) { barijereJson = []; }

  const barijereM2 = parseFloat(f.pozarne_barijere_m2 || 0);

  if (barijereM2 > 0 && barijereJson.length > 0) {
    // Header
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '🟧 POŽARNE BARIJERE (poseban dio - drugi materijal):';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFc2410c' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEEFE6' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 16;
    r++;

    // Headers stupaca - dodano š × v za dokaz pred nadzorom
    ws.getCell(r, 1).value = 'Oznaka';
    ws.mergeCells(r, 2, r, 4);
    ws.getCell(r, 2).value = 'Širina × Visina (m)';
    ws.getCell(r, 5).value = 'm²';
    ws.mergeCells(r, 6, r, 8);
    ws.getCell(r, 6).value = 'Izvor / Napomena';
    [1,2,5,6].forEach(c => {
      ws.getCell(r, c).font = { bold: true, size: 9, color: { argb: 'FF92400e' } };
      ws.getCell(r, c).alignment = { horizontal: c === 5 ? 'right' : 'left' };
      ws.getCell(r, c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEEFE6' } };
    });
    r++;

    // Stavke barijera s dokazom š × v
    barijereJson.forEach((b, idx) => {
      const opis = b.opis || ('PB' + (idx + 1));
      const m2 = parseFloat(b.m2 || 0);
      const izvor = b.izvor === 'manualno' ? 'Označeno' : 'AI dopuna';

      // Izracunaj bbox dimenzije
      let dimText = '—';
      let napomena = izvor;
      if (b.tocke_px && b.tocke_px.length >= 3) {
        const dim = _serverBboxIzTocaka(b.tocke_px, m2);
        if (dim) {
          if (dim.pravokutan) {
            dimText = `${dim.sirina_m} × ${dim.visina_m}`;
            napomena = `${izvor} · pravokutan poligon`;
          } else {
            dimText = `bbox ${dim.sirina_m} × ${dim.visina_m}`;
            napomena = `${izvor} · ${b.tocke_px.length}-strani nepravilan poligon (bbox: ${dim.bbox_m2} m²)`;
          }
        }
      } else {
        napomena = izvor + ' · AI knjiga';
      }

      ws.getCell(r, 1).value = opis;
      ws.getCell(r, 1).font = { size: 9, bold: true };
      ws.mergeCells(r, 2, r, 4);
      ws.getCell(r, 2).value = dimText;
      ws.getCell(r, 2).font = { size: 9 };
      ws.getCell(r, 5).value = m2;
      ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 5).alignment = { horizontal: 'right' };
      ws.getCell(r, 5).font = { bold: true };
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = napomena;
      ws.getCell(r, 6).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
      ws.getCell(r, 6).alignment = { wrapText: true };
      r++;
    });

    // SUMA barijera
    ws.mergeCells(r, 1, r, 5);
    ws.getCell(r, 1).value = 'UKUPNO POŽARNE BARIJERE:';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFc2410c' } };
    ws.getCell(r, 1).alignment = { horizontal: 'right' };
    ws.mergeCells(r, 6, r, 8);
    ws.getCell(r, 6).value = barijereM2;
    ws.getCell(r, 6).numFmt = '0.00 "m²"';
    ws.getCell(r, 6).font = { bold: true, size: 11, color: { argb: 'FFc2410c' } };
    ws.getCell(r, 6).alignment = { horizontal: 'right' };
    ws.getCell(r, 6).border = { top: { style: 'medium', color: { argb: 'FFc2410c' } } };
    r++;

    ws.getRow(r).height = 8; r++;

    // ⭐ v135.7.22 (Ivanov koncept): bruto = sve plohe; PB i D ne odbijaju
    if (f.bruto_fasada_m2 && parseFloat(f.bruto_fasada_m2) > 0) {
      ws.mergeCells(r, 1, r, 5);
      ws.getCell(r, 1).value = 'BRUTO fasada (Σ ploha):';
      ws.getCell(r, 1).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
      ws.getCell(r, 1).alignment = { horizontal: 'right' };
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = parseFloat(f.bruto_fasada_m2);
      ws.getCell(r, 6).numFmt = '0.00 "m²"';
      ws.getCell(r, 6).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
      ws.getCell(r, 6).alignment = { horizontal: 'right' };
      r++;

      ws.getRow(r).height = 6; r++;
    }
  }

  // ── RAZLIČITE DEBLJINE ETICS-a (ako postoje) ──
  let zoneJson = [];
  try {
    zoneJson = typeof f.zone_debljine_json === 'string'
      ? JSON.parse(f.zone_debljine_json)
      : (f.zone_debljine_json || []);
  } catch(e) { zoneJson = []; }

  if (f.razlicite_debljine && zoneJson.length > 0) {
    const defD = parseFloat(f.default_debljina_cm || 10);

    // Header
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '🎨 RAZLIČITE DEBLJINE ETICS-a (zasebne stavke za obracun):';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FF0891b2' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0F2FE' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 16;
    r++;

    // SUBHEADER: Pojedinacne oznacene zone s dimenzijama (dokaz pred nadzorom)
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '📝 Označene zone (dokaz dimenzija):';
    ws.getCell(r, 1).font = { bold: true, size: 9, italic: true, color: { argb: 'FF0e7490' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', indent: 1 };
    r++;

    // Headers - per zona
    ws.getCell(r, 1).value = 'Oznaka';
    ws.getCell(r, 2).value = 'cm';
    ws.mergeCells(r, 3, r, 4);
    ws.getCell(r, 3).value = 'Širina × Visina (m)';
    ws.getCell(r, 5).value = 'm²';
    ws.mergeCells(r, 6, r, 8);
    ws.getCell(r, 6).value = 'Napomena';
    [1,2,3,5,6].forEach(c => {
      ws.getCell(r, c).font = { bold: true, size: 9, color: { argb: 'FF0e7490' } };
      ws.getCell(r, c).alignment = { horizontal: c === 5 ? 'right' : (c === 2 ? 'center' : 'left') };
      ws.getCell(r, c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0F2FE' } };
    });
    r++;

    // Pojedinacne zone s dokazom
    zoneJson.forEach((z, idx) => {
      const oznaka = z.opis || ('Z' + (idx + 1));
      const cm = parseFloat(z.debljina_cm);
      const m2 = parseFloat(z.m2 || 0);

      let dimText = '—';
      let napomena = z.izvor === 'manualno' ? 'Označeno' : 'AI dopuna';
      if (z.tocke_px && z.tocke_px.length >= 3) {
        const dim = _serverBboxIzTocaka(z.tocke_px, m2);
        if (dim) {
          if (dim.pravokutan) {
            dimText = `${dim.sirina_m} × ${dim.visina_m}`;
            napomena += ' · pravokutan';
          } else {
            dimText = `bbox ${dim.sirina_m} × ${dim.visina_m}`;
            napomena += ` · ${z.tocke_px.length}-strani nepravilan poligon (bbox: ${dim.bbox_m2} m²)`;
          }
        }
      }

      ws.getCell(r, 1).value = oznaka;
      ws.getCell(r, 1).font = { size: 9, bold: true };
      ws.getCell(r, 2).value = cm;
      ws.getCell(r, 2).font = { size: 9 };
      ws.getCell(r, 2).alignment = { horizontal: 'center' };
      ws.mergeCells(r, 3, r, 4);
      ws.getCell(r, 3).value = dimText;
      ws.getCell(r, 3).font = { size: 9 };
      ws.getCell(r, 5).value = m2;
      ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 5).alignment = { horizontal: 'right' };
      ws.getCell(r, 5).font = { bold: true };
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = napomena;
      ws.getCell(r, 6).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
      ws.getCell(r, 6).alignment = { wrapText: true };
      r++;
    });

    // Izracunaj raspodjelu (sumirana po debljinama)
    const raspodjela = {};
    zoneJson.forEach(z => {
      const k = parseInt(z.debljina_cm);
      raspodjela[k] = (raspodjela[k] || 0) + parseFloat(z.m2 || 0);
    });
    const zoneUkupno = zoneJson.reduce((s, z) => s + parseFloat(z.m2 || 0), 0);
    const ukupnaF = parseFloat(f.ukupna_fasada_m2 || 0);
    const ostatakDef = Math.max(0, ukupnaF - zoneUkupno);
    if (ostatakDef > 0) {
      raspodjela[defD] = (raspodjela[defD] || 0) + ostatakDef;
    }

    // Spacer
    ws.getRow(r).height = 4; r++;

    // SUBHEADER: Konacna raspodjela
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '📊 Konacna raspodjela po debljinama (za obracun):';
    ws.getCell(r, 1).font = { bold: true, size: 9, italic: true, color: { argb: 'FF0e7490' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', indent: 1 };
    r++;

    // Stavke u tablici (raspodjela)
    const sortedDebs = Object.keys(raspodjela).map(d => parseInt(d)).sort((a,b) => a - b);
    sortedDebs.forEach(cm => {
      const m2 = parseFloat(raspodjela[cm].toFixed(2));
      const isDef = cm === defD;

      ws.getCell(r, 1).value = `ETICS ${cm}cm`;
      ws.getCell(r, 1).font = { bold: true, size: 10 };
      ws.getCell(r, 5).value = m2;
      ws.getCell(r, 5).numFmt = '0.00';
      ws.getCell(r, 5).alignment = { horizontal: 'right' };
      ws.getCell(r, 5).font = { bold: true };
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = isDef ? 'default debljina (ostatak fasade)' : 'sumirano iz označenih zona';
      ws.getCell(r, 6).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
      r++;
    });

    // SUMA
    ws.mergeCells(r, 1, r, 4);
    ws.getCell(r, 1).value = 'UKUPNO (svi ETICS-i):';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FF0e7490' } };
    ws.getCell(r, 1).alignment = { horizontal: 'right' };
    ws.getCell(r, 5).value = ukupnaF;
    ws.getCell(r, 5).numFmt = '0.00 "m²"';
    ws.getCell(r, 5).font = { bold: true, size: 11, color: { argb: 'FF0e7490' } };
    ws.getCell(r, 5).alignment = { horizontal: 'right' };
    ws.getCell(r, 5).border = { top: { style: 'medium', color: { argb: 'FF0e7490' } } };
    ws.mergeCells(r, 6, r, 8);
    r++;

    ws.getRow(r).height = 8; r++;
  }

  // 7. NETO REZULTAT (highlight)
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'NETO POVRŠINA FASADE:';
  ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15803d' } };
  ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };

  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).value = parseFloat(f.neto_fasada_m2 || 0);
  ws.getCell(r, 5).numFmt = '0.00 "m²"';
  ws.getCell(r, 5).font = { bold: true, size: 14, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 5).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF22c55e' } };
  ws.getCell(r, 5).alignment = { horizontal: 'right', vertical: 'middle', indent: 1, shrinkToFit: true };
  ws.getRow(r).height = 24;
  r++;

  ws.getRow(r).height = 5; r++;

  // 7.5. DODATNI OBRAČUN (sitnice/dodatne stavke ručni unos: terase, balkoni, vijenci, ostalo)
  let sitniceJson = [];
  try {
    sitniceJson = typeof f.sitnice_json === 'string'
      ? JSON.parse(f.sitnice_json)
      : (f.sitnice_json || []);
  } catch(e) { sitniceJson = []; }

  if (Array.isArray(sitniceJson) && sitniceJson.length > 0) {
    // Header sekcije
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '📋 DODATNI OBRAČUN (terase, balkoni, vijenci, ostalo)';
    ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFa16207' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 18;
    r++;

    // Headers stupaca
    ws.mergeCells(r, 1, r, 3);
    ws.getCell(r, 1).value = 'Stavka';
    ws.mergeCells(r, 4, r, 6);
    ws.getCell(r, 4).value = 'Razlamba (š × v = m²)';
    ws.getCell(r, 7).value = 'Količina';
    ws.getCell(r, 8).value = 'Jed.';
    [1, 4, 7, 8].forEach(c => {
      ws.getCell(r, c).font = { bold: true, size: 9, color: { argb: 'FF92400e' } };
      ws.getCell(r, c).alignment = { horizontal: c === 7 ? 'right' : (c === 8 ? 'center' : 'left'), vertical: 'middle' };
      ws.getCell(r, c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
      ws.getCell(r, c).border = { bottom: { style: 'thin', color: { argb: 'FFa16207' } } };
    });
    r++;

    // Stavke
    let sitniceM2Ukupno = 0;
    for (const s of sitniceJson) {
      const opis = s.opis || '—';
      const napomena = s.napomena || '';
      const kolicina = parseFloat(s.kolicina || 0);
      const jedinica = s.jedinica || 'm2';
      const unosi = Array.isArray(s.unosi) ? s.unosi : [];

      if (jedinica === 'm2') sitniceM2Ukupno += kolicina;

      // Razlamba kao tekst (više unosa razdvojenih s newline za wrap)
      let razlambaText = '—';
      if (unosi.length > 0) {
        razlambaText = unosi.map(u => {
          const sw = _kuIzrazS(u.sirina) || 0;   // * v1179: raspis
          const sv = _kuIzrazS(u.visina) || 0;   // * v1179: raspis
          const m2 = sw * sv;
          // * v1179 (Ivan): ako je upisan RASPIS, u knjizi pise raspis PA rezultat - Nadzor vidi
          //   ODAKLE broj dolazi. Ako je obican broj, ispis ostaje kakav je i bio.
          const _sr = _kuJeRaspisS(u.sirina) ? String(u.sirina).trim() : null;
          const _vr = _kuJeRaspisS(u.visina) ? String(u.visina).trim() : null;
          if (_sr || _vr) {
            const _sL = _sr ? '(' + _sr + ') = ' + sw.toFixed(2) : sw.toFixed(2);
            const _vL = _vr ? '(' + _vr + ') = ' + sv.toFixed(2) : sv.toFixed(2);
            return `${_sL} × ${_vL} = ${m2.toFixed(2)}`;
          }
          return `${sw.toFixed(2)} × ${sv.toFixed(2)} = ${m2.toFixed(2)}`;
        }).join('\n');
      }

      // Visina retka prilagođena broju unosa + napomena
      const linijeTeksta = Math.max(1, unosi.length) + (napomena ? 1 : 0);
      const stavkaHeight = Math.min(80, 14 + linijeTeksta * 12);

      ws.mergeCells(r, 1, r, 3);
      ws.getCell(r, 1).value = opis + (napomena ? '\n   ↳ ' + napomena : '');
      ws.getCell(r, 1).font = { size: 10 };
      ws.getCell(r, 1).alignment = { vertical: 'top', wrapText: true, indent: 1 };

      ws.mergeCells(r, 4, r, 6);
      ws.getCell(r, 4).value = razlambaText;
      ws.getCell(r, 4).font = { size: 9, color: { argb: 'FF475569' } };
      ws.getCell(r, 4).alignment = { vertical: 'top', wrapText: true };

      ws.getCell(r, 7).value = kolicina;
      ws.getCell(r, 7).numFmt = '0.00';
      ws.getCell(r, 7).font = { bold: true, size: 10 };
      ws.getCell(r, 7).alignment = { horizontal: 'right', vertical: 'top' };

      ws.getCell(r, 8).value = jedinica === 'm2' ? 'm²' : (jedinica === 'm' ? "m'" : jedinica);
      ws.getCell(r, 8).font = { size: 9 };
      ws.getCell(r, 8).alignment = { horizontal: 'center', vertical: 'top' };

      // Tanki separator
      [1, 4, 7, 8].forEach(c => {
        ws.getCell(r, c).border = { bottom: { style: 'hair', color: { argb: 'FFcbd5e1' } } };
      });

      ws.getRow(r).height = stavkaHeight;
      r++;

      // SLIKA stavke (ako postoji foto_base64) - za Nadzornog inženjera
      if (s.foto_base64 && typeof s.foto_base64 === 'string' && s.foto_base64.startsWith('data:image')) {
        try {
          const m = s.foto_base64.match(/^data:image\/([\w+]+);base64,(.+)$/);
          if (m) {
            const ext = (m[1] === 'jpeg' ? 'jpeg' : (m[1] === 'png' ? 'png' : 'jpeg')).toLowerCase();
            const b64 = m[2];
            // ⭐ v294 (Ivan): JPEG kompresija q=75 za sitnice foto (samo JPEG, ne PNG)
            let imgId;
            if (ext === 'jpeg') {
              const compressed = await _compressJpegForExcel(Buffer.from(b64, 'base64'), 75);
              imgId = ws.workbook.addImage({ buffer: compressed, extension: 'jpeg' });
            } else {
              imgId = ws.workbook.addImage({ base64: b64, extension: ext });
            }
            // Slika u zasebnom redu, fiksna visina ~110px
            ws.getRow(r).height = 110;
            ws.addImage(imgId, {
              tl: { col: 1.0, row: r - 1 + 0.1 },
              ext: { width: 220, height: 105 }
            });
            ws.mergeCells(r, 1, r, 8);
            ws.getCell(r, 1).value = '📷 Foto: ' + opis;
            ws.getCell(r, 1).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
            ws.getCell(r, 1).alignment = { horizontal: 'right', vertical: 'top', indent: 1 };
            r++;
          }
        } catch(imgErr) {
          console.warn('[Excel sitnica foto]', imgErr.message);
        }
      }
    }

    // SUMA m² stavki (samo m² stavke, jer m, kom su druge jedinice)
    if (sitniceM2Ukupno > 0) {
      ws.mergeCells(r, 1, r, 6);
      ws.getCell(r, 1).value = 'UKUPNO Dodatni obračun (m² stavke):';
      ws.getCell(r, 1).font = { bold: true, size: 10 };
      ws.getCell(r, 1).alignment = { horizontal: 'right' };
      ws.mergeCells(r, 7, r, 8);
      ws.getCell(r, 7).value = sitniceM2Ukupno;
      ws.getCell(r, 7).numFmt = '0.00 "m²"';
      ws.getCell(r, 7).font = { bold: true, size: 11, color: { argb: 'FFa16207' } };
      ws.getCell(r, 7).alignment = { horizontal: 'right' };
      ws.getCell(r, 7).border = { top: { style: 'medium', color: { argb: 'FFa16207' } } };
      r++;
    }

    ws.getRow(r).height = 8; r++; // razmak
  }

  // 8. NAPOMENA AI / OBJAŠNJENJE
  if (dim.objasnjenje || f.napomena) {
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = 'NAPOMENA';
    ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 18;
    r++;

    const napText = [dim.objasnjenje, f.napomena].filter(Boolean).join(' · ');
    ws.mergeCells(r, 1, r + 2, 8);
    ws.getCell(r, 1).value = napText;
    ws.getCell(r, 1).font = { italic: true, size: 9, color: { argb: 'FF374151' } };
    ws.getCell(r, 1).alignment = { wrapText: true, vertical: 'top', horizontal: 'left' };
    r += 3;
  }

  ws.getRow(r).height = 8; r++;

  // 9. OVJERA / POTPISI
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = 'OVJERA OBRAČUNA';
  ws.getCell(r, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
  ws.getCell(r, 1).alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 18;
  r++;

  ws.getRow(r).height = 8; r++;

  // Datumi
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'Datum: ____________________';
  ws.getCell(r, 1).font = { size: 9 };
  ws.getCell(r, 1).alignment = { horizontal: 'left' };
  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).value = 'Datum: ____________________';
  ws.getCell(r, 5).font = { size: 9 };
  ws.getCell(r, 5).alignment = { horizontal: 'left' };
  r++;

  ws.getRow(r).height = 8; r++;

  // Potpisi labels
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'OVJERA IZVOĐAČA:';
  ws.getCell(r, 1).font = { bold: true, size: 9 };
  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).value = 'OVJERA NADZORA:';
  ws.getCell(r, 5).font = { bold: true, size: 9 };
  r++;

  // ⭐ v135.7.378 (Ivan): pečat + potpis preko crtica za izvođača
  ws.getRow(r).height = 35;
  _knjigaUmetniPecatPotpis(ws, ws.workbook, r, 1, 4);
  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).border = { bottom: { style: 'thin' } };
  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).border = { bottom: { style: 'thin' } };
  r++;

  ws.mergeCells(r, 1, r, 4);
  ws.getCell(r, 1).value = 'ŽBUKA Čakarić d.o.o. · Ivan Čakarić';
  ws.getCell(r, 1).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
  ws.mergeCells(r, 5, r, 8);
  ws.getCell(r, 5).value = '(ime, prezime, potpis)';
  ws.getCell(r, 5).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
  r++;

  ws.getRow(r).height = 5; r++;

  // Footer disclaimer
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = 'Knjiga izvedena AI analizom slike (Claude Vision). Mjere su raščlanjene i provjerene od strane voditelja radova. Dokument služi kao podloga za obračun izvedenih radova.';
  ws.getCell(r, 1).font = { size: 8, italic: true, color: { argb: 'FF6b7280' } };
  ws.getCell(r, 1).alignment = { wrapText: true, vertical: 'top', horizontal: 'center' };
  ws.getRow(r).height = 24;
  r++;

  // PAGE BREAK nakon ove procjene (osim ako je zadnja)
  ws.lastRow.addPageBreak = true;
  // Note: addPageBreak je metoda na sheet-u, ne na row. Postavljamo break:
  if (!ws._pageBreaks) ws._pageBreaks = [];
  ws._pageBreaks.push(r);

  return r + 1;
}

// ═══════════════════════════════════════════════════════════════════════════
// FAZA A: Excel sheet — OTVORI (prozori, vrata, sva otvor geometrija)
// ═══════════════════════════════════════════════════════════════════════════
async function generirajSheetOtvori(wb, f, gradNaziv, gradAdresa) {
  const otvori = Array.isArray(f.otvori_json) ? f.otvori_json : [];
  if (!otvori.length) return null;
  
  const DARK = 'FF1a1a2e';
  const ACCENT = 'FFEAB308'; // žuta - boja otvora
  const LIGHT = 'FFFEFCE8';
  
  const ws = wb.addWorksheet('Otvori', {
    pageSetup: {
      paperSize: 9, orientation: 'portrait', fitToPage: true,
      fitToWidth: 1, fitToHeight: 0,
      margins: { left: 0.4, right: 0.4, top: 0.4, bottom: 0.4 }
    }
  });
  ws.columns = [
    { width: 6 }, { width: 22 }, { width: 11 }, { width: 11 },
    { width: 12 }, { width: 9 }, { width: 13 }, { width: 12 }
  ];
  
  let r = 1;
  
  // Header
  ws.mergeCells(r, 1, r, 8);
  ws.getCell(r, 1).value = '🪟 OTVORI — ' + (gradNaziv || 'Bez naziva');
  ws.getCell(r, 1).font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 26;
  r++;
  
  if (gradAdresa) {
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = gradAdresa;
    ws.getCell(r, 1).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', indent: 1 };
    r++;
  }
  ws.getRow(r).height = 6; r++;
  
  // Tablica header
  const hdr = ['#', 'Opis', 'Tip', 'Š (m)', 'V (m)', 'Kom', 'Ukupno (m²)', 'Mode'];
  hdr.forEach((v, i) => {
    const c = ws.getCell(r, i+1);
    c.value = v;
    c.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i >= 3 ? 'right' : 'left', vertical: 'middle', indent: 1 };
    c.border = { bottom: { style: 'thin', color: { argb: 'FFD1D5DB' } } };
  });
  ws.getRow(r).height = 22;
  r++;
  
  let ukupnoSum = 0;
  otvori.forEach((o, idx) => {
    const isManual = !!o._manual_override;
    let s, v, m2;
    if (isManual && o._manual_sirina && o._manual_visina) {
      s = parseFloat(o._manual_sirina);
      v = parseFloat(o._manual_visina);
      m2 = s * v;
    } else {
      s = parseFloat(o.sirina_m || 0);
      v = parseFloat(o.visina_m || 0);
      // ⭐ v450 (Ivan, 18.05.2026): prefer svježi Š×V > 0, fallback cached m²
      const sXv = s * v;
      m2 = sXv > 0 ? sXv : parseFloat(o.m2 || o._m2 || 0) || 0;
    }
    const kol = parseInt(o.kolicina || 1) || 1;
    const ukupno = m2 * kol;
    ukupnoSum += ukupno;
    
    ws.getCell(r, 1).value = idx + 1;
    ws.getCell(r, 1).font = { bold: true, color: { argb: ACCENT } };
    ws.getCell(r, 2).value = o.opis || ('Otvor ' + (idx+1));
    ws.getCell(r, 3).value = o.tip || 'prozor';
    ws.getCell(r, 4).value = s; ws.getCell(r, 4).numFmt = '0.00';
    ws.getCell(r, 5).value = v; ws.getCell(r, 5).numFmt = '0.00';
    ws.getCell(r, 6).value = kol;
    ws.getCell(r, 7).value = ukupno; ws.getCell(r, 7).numFmt = '0.00';
    ws.getCell(r, 7).font = { bold: true, color: { argb: ACCENT } };
    ws.getCell(r, 8).value = isManual ? 'RUČNO ✏️' : 'auto';
    ws.getCell(r, 8).font = { size: 8, bold: isManual, color: { argb: isManual ? 'FFEAB308' : 'FF6b7280' } };
    
    for (let i2 = 1; i2 <= 8; i2++) {
      const c = ws.getCell(r, i2);
      c.alignment = { vertical: 'middle', horizontal: i2 >= 4 ? 'right' : 'left', indent: 1 };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      if (r % 2 === 0) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    }
    if (o.napomena) {
      r++;
      ws.mergeCells(r, 2, r, 8);
      ws.getCell(r, 2).value = '"' + o.napomena + '"';
      ws.getCell(r, 2).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
      ws.getCell(r, 2).alignment = { horizontal: 'left', indent: 2 };
    }
    ws.getRow(r).height = 18;
    r++;
  });
  
  // Suma
  r++;
  ws.mergeCells(r, 1, r, 6);
  const sc = ws.getCell(r, 1);
  sc.value = `UKUPNO OTVORI (${otvori.length} stavki):`;
  sc.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  sc.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  sc.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.mergeCells(r, 7, r, 8);
  ws.getCell(r, 7).value = ukupnoSum;
  ws.getCell(r, 7).numFmt = '0.00 "m²"';
  ws.getCell(r, 7).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 7).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  ws.getCell(r, 7).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 26;
  r++;
  
  // ═══════════════════════════════════════════════════════════════════════
  // ⭐ v340 (Ivan): GN 421 ODBITAK OTVORA PO POZICIJAMA
  //   Sekcija prikazuje GN 421 obračun za svaki otvor pojedinačno:
  //     • Mali (≤3 m²) → ne odbija se (špalete već u glavnoj plohi)
  //     • Srednji (3-5 m²) → odbija (m² − 3) × kom
  //     • Veliki (>5 m²) → odbija (m² − 3) × kom + dodatak špaleta
  //   Špalete = (2 × visina + sirina) × debljina_izolacije × kom
  //   Korisno za ispis svih otvora s individualnim odbicima — i one koji ispadaju 
  //   (≤3) Ivan eksplicit traži da budu prikazani s 0 m² odbitkom.
  // ═══════════════════════════════════════════════════════════════════════
  
  r++; // prazna linija
  
  // Naslov sekcije
  ws.mergeCells(r, 1, r, 8);
  const gnTit = ws.getCell(r, 1);
  gnTit.value = '🪟 GN 421 ODBITAK OTVORA PO POZICIJAMA';
  gnTit.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
  gnTit.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  gnTit.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 22;
  r++;
  
  // Napomena GN 421 norme
  ws.mergeCells(r, 1, r, 8);
  const gnNote = ws.getCell(r, 1);
  gnNote.value = '💡 GN 421: otvori ≤ 3 m² se NE odbijaju (špalete pokrivene u plohi). Otvori 3–5 m² odbijaju (m²−3) × kom. Otvori > 5 m² odbijaju (m²−3) × kom + dodatak špaleta (2v+š) × deb. izol. × kom.';
  gnNote.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
  gnNote.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
  ws.getRow(r).height = 32;
  r++;
  
  // Header tablice GN 421
  const gnHdr = ['#', 'Opis', 'm² (1×)', 'Kom', 'Klasifikacija', 'Odbitak m²', 'Špalete m²', 'Neto m²'];
  gnHdr.forEach((v, i) => {
    const c = ws.getCell(r, i+1);
    c.value = v;
    c.font = { bold: true, size: 9.5, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i >= 2 ? 'right' : 'left', vertical: 'middle', indent: 1 };
    c.border = { bottom: { style: 'thin', color: { argb: 'FFD1D5DB' } } };
  });
  ws.getRow(r).height = 20;
  r++;
  
  // Debljina izolacije (za špalete) — fallback top-level f.default_debljina_cm
  const gnDefDebljinaM = parseFloat(f.default_debljina_cm || 15) / 100;
  
  // ⭐ v359 (Ivan, 16.05.2026): per-otvor debljina helper za single-procjena Otvori list.
  //   Mora biti sinhroniziran s ostalim mjestima (recalcBruto, FE, Σ Otvori sheet).
  const _singleSheetTockaUPoligonu_359 = (x, y, points) => {
    if (!Array.isArray(points) || points.length < 3) return false;
    let inside = false;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
      const xi = points[i].x, yi = points[i].y;
      const xj = points[j].x, yj = points[j].y;
      const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  };
  const _ravnineSingle_359 = Array.isArray(f.ravnine_json) ? f.ravnine_json : [];
  const _singleSheetDebljinaZaOtvor_359 = (o) => {
    if (o && o.debljina_otvor_cm != null && o.debljina_otvor_cm !== '') {
      const v = parseFloat(o.debljina_otvor_cm);
      if (isFinite(v) && v > 0) return v / 100;
    }
    const pts = o.points || o.pointsPx || o.kutoviPx;
    if (!Array.isArray(pts) || pts.length < 3) return gnDefDebljinaM;
    const cx = pts.reduce((s, pt) => s + (pt.x || 0), 0) / pts.length;
    const cy = pts.reduce((s, pt) => s + (pt.y || 0), 0) / pts.length;
    for (const rv of _ravnineSingle_359) {
      if (o._ravnina_id && rv.id && o._ravnina_id !== rv.id) continue;
      const plohe = Array.isArray(rv.plohe) ? rv.plohe : [];
      for (const pl of plohe) {
        const plohaPts = Array.isArray(pl.pointsPx) ? pl.pointsPx 
                       : Array.isArray(pl.points) ? pl.points : null;
        if (plohaPts && _singleSheetTockaUPoligonu_359(cx, cy, plohaPts)) {
          if (pl.debljina_cm != null && pl.debljina_cm !== '') {
            const d = parseFloat(pl.debljina_cm) / 100;
            if (d > 0) return d;
          }
        }
      }
    }
    return gnDefDebljinaM;
  };
  
  let gnSumOdbitak = 0, gnSumSpalete = 0, gnSumNeto = 0;
  
  otvori.forEach((o, idx) => {
    // Identična otvorMjere logika kao u per-pročelje / centralnom helperu
    const isManual = !!(o._manual_override && o._manual_sirina && o._manual_visina);
    const s = isManual ? parseFloat(o._manual_sirina) : parseFloat(o.sirina_m || 0);
    const v = isManual ? parseFloat(o._manual_visina) : parseFloat(o.visina_m || 0);
    // ⭐ v450 (Ivan, 18.05.2026): HYBRID logika (manual=stored, canvas=Š×V). Vidi komentar L31941.
    const m2Stored = parseFloat(o.m2 || o._m2 || 0);
    const sXv = s * v;
    const m2 = isManual
      ? (sXv > 0 ? sXv : m2Stored)
      : (sXv > 0 ? sXv : (m2Stored || 0));
    const kol = parseInt(o.kolicina || 1) || 1;
    
    // ⭐ v359: per-otvor debljina (override → centroid plohe → default)
    const debM_perOtvor_359 = _singleSheetDebljinaZaOtvor_359(o);
    
    // ⭐ v446 (Ivan, 18.05.2026): sqrt fallback Š/V kad su 0 ali m²>0. Sinhroniziran s _knjigaOtvoriZaProcelje.
    let sFs = s, vFs = v;
    if ((sFs <= 0 || vFs <= 0) && m2 > 0) {
      sFs = vFs = Math.sqrt(m2);
    }
    
    // GN 421 klasifikacija
    let kategorija, odbitak = 0, spalete = 0;
    if (m2 > 5) {
      kategorija = '> 5 m² (veliki, sa špaletama)';
      odbitak = (m2 - 3) * kol;
      if (sFs > 0 && vFs > 0) {
        spalete = (2 * vFs + sFs) * debM_perOtvor_359 * kol;
      }
    } else if (m2 > 3) {
      kategorija = '3–5 m² (srednji)';
      odbitak = (m2 - 3) * kol;
    } else {
      kategorija = '≤ 3 m² (ne odbija)';
    }
    const neto = Math.max(0, odbitak - spalete);
    
    gnSumOdbitak += odbitak;
    gnSumSpalete += spalete;
    gnSumNeto += neto;
    
    // Boja klasifikacije
    const klasColor = (m2 > 5) ? 'FF7C3AED'      // ljubičasta (veliki)
                    : (m2 > 3) ? 'FFEAB308'      // žuta (srednji)
                    :            'FF10B981';     // zelena (mali, ne odbija)
    
    ws.getCell(r, 1).value = idx + 1;
    ws.getCell(r, 1).font = { bold: true, color: { argb: ACCENT } };
    ws.getCell(r, 2).value = o.opis || ('Otvor ' + (idx+1));
    ws.getCell(r, 3).value = m2; ws.getCell(r, 3).numFmt = '0.00';
    ws.getCell(r, 4).value = kol;
    ws.getCell(r, 5).value = kategorija;
    ws.getCell(r, 5).font = { size: 9, bold: true, color: { argb: klasColor } };
    // Odbitak — prikazati 0 ako je mali, inače sa minus predznakom radi vizualne jasnoće
    ws.getCell(r, 6).value = odbitak > 0 ? -odbitak : 0;
    ws.getCell(r, 6).numFmt = '0.00';
    ws.getCell(r, 6).font = { bold: odbitak > 0, color: { argb: odbitak > 0 ? 'FFDC2626' : 'FF6b7280' } };
    // Špalete — prikazati 0 ako nema, inače sa plus predznakom (dodatak na fakture)
    ws.getCell(r, 7).value = spalete > 0 ? spalete : 0;
    ws.getCell(r, 7).numFmt = '0.00';
    ws.getCell(r, 7).font = { bold: spalete > 0, color: { argb: spalete > 0 ? 'FF7C3AED' : 'FF6b7280' } };
    // Neto = odbitak - špalete (već s minus predznakom efektivno)
    ws.getCell(r, 8).value = neto > 0 ? -neto : 0;
    ws.getCell(r, 8).numFmt = '0.00';
    ws.getCell(r, 8).font = { bold: true, color: { argb: neto > 0 ? 'FFDC2626' : 'FF10B981' } };
    
    for (let i2 = 1; i2 <= 8; i2++) {
      const c = ws.getCell(r, i2);
      c.alignment = c.alignment || { vertical: 'middle', horizontal: i2 >= 3 ? 'right' : 'left', indent: 1 };
      if (i2 === 2 || i2 === 5) {
        c.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
      } else if (i2 >= 3) {
        c.alignment = { vertical: 'middle', horizontal: 'right', indent: 1 };
      }
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      if (r % 2 === 0) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    }
    ws.getRow(r).height = 17;
    r++;
  });
  
  // UKUPNO GN 421 red
  ws.mergeCells(r, 1, r, 5);
  const gnSc = ws.getCell(r, 1);
  gnSc.value = `UKUPNO GN 421 ODBITAK (${otvori.length} otvora):`;
  gnSc.font = { bold: true, size: 10.5, color: { argb: 'FFFFFFFF' } };
  gnSc.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  gnSc.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  
  ws.getCell(r, 6).value = gnSumOdbitak > 0 ? -gnSumOdbitak : 0;
  ws.getCell(r, 6).numFmt = '0.00';
  ws.getCell(r, 6).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 6).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDC2626' } };
  ws.getCell(r, 6).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  
  ws.getCell(r, 7).value = gnSumSpalete;
  ws.getCell(r, 7).numFmt = '0.00';
  ws.getCell(r, 7).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 7).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF7C3AED' } };
  ws.getCell(r, 7).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  
  ws.getCell(r, 8).value = gnSumNeto > 0 ? -gnSumNeto : 0;
  ws.getCell(r, 8).numFmt = '0.00 "m²"';
  ws.getCell(r, 8).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  ws.getCell(r, 8).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: gnSumNeto > 0 ? 'FFDC2626' : 'FF10B981' } };
  ws.getCell(r, 8).alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 24;
  r++;
  
  return ws;
}

// ═══════════════════════════════════════════════════════════════════════════
// FAZA A: Excel sheet 2 — POŽARNE BARIJERE
// ═══════════════════════════════════════════════════════════════════════════
async function generirajSheetBarijere(wb, f, gradNaziv, gradAdresa) {
  const barijere = Array.isArray(f.pozarne_barijere_json) ? f.pozarne_barijere_json : [];
  if (!barijere.length) return null;
  
  const ws = wb.addWorksheet('Pož. barijere', {
    pageSetup: {
      paperSize: 9, orientation: 'portrait', fitToPage: true,
      fitToWidth: 1, fitToHeight: 0,
      margins: { left: 0.5, right: 0.5, top: 0.5, bottom: 0.5, header: 0.2, footer: 0.2 }
    }
  });
  ws.columns = [
    { width: 5 },   // br
    { width: 16 },  // ravnina
    { width: 24 },  // opis
    { width: 10 },  // š
    { width: 10 },  // v
    { width: 10 },  // m²
    { width: 8 },   // kol
    { width: 12 }   // ukupno
  ];
  
  const DARK = 'FF0F172A', ACCENT = 'FFC2410C', LIGHT = 'FFFEF3F2';
  let r = 1;
  
  // Naslov
  ws.mergeCells(r, 1, r, 8);
  const c1 = ws.getCell(r, 1);
  c1.value = `POŽARNE BARIJERE — ${gradNaziv || 'Knjiga'} (proc #${f.id})`;
  c1.font = { bold: true, size: 14, color: { argb: 'FFFFFFFF' } };
  c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  c1.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 24;
  r++;
  
  if (gradAdresa) {
    ws.mergeCells(r, 1, r, 8);
    const c2 = ws.getCell(r, 1);
    c2.value = gradAdresa;
    c2.font = { italic: true, size: 10, color: { argb: 'FF64748B' } };
    c2.alignment = { horizontal: 'center' };
    r++;
  }
  r++;
  
  // Header tablice
  const headers = ['Br.', 'Ravnina', 'Opis', 'Širina (m)', 'Visina (m)', 'm² po kom', 'Kol.', 'Ukupno m²'];
  headers.forEach((h, i) => {
    const c = ws.getCell(r, i + 1);
    c.value = h;
    c.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i >= 3 ? 'right' : 'left', vertical: 'middle', indent: i < 3 ? 1 : 0 };
    c.border = { bottom: { style: 'thin', color: { argb: 'FF334155' } } };
  });
  ws.getRow(r).height = 18;
  r++;
  
  // Map ravnina_id -> opis
  const ravnine = Array.isArray(f.ravnine_json) ? f.ravnine_json : [];
  const ravinaNaziv = (id) => {
    const idx = ravnine.findIndex(rv => rv.id === id);
    if (idx < 0) return id ? '?' : '— van ravnine —';
    return `R${idx+1}: ${ravnine[idx].opis || ('Ravnina ' + (idx+1))}`;
  };
  
  // Stavke
  let ukupnoM2 = 0;
  barijere.forEach((b, i) => {
    const isManual = !!b._manual_override;
    let sirina, visina, m2;
    if (isManual && b._manual_sirina && b._manual_visina) {
      sirina = parseFloat(b._manual_sirina);
      visina = parseFloat(b._manual_visina);
      m2 = sirina * visina;
    } else {
      sirina = parseFloat(b.sirina_m || 0);
      visina = parseFloat(b.visina_m || 0);
      m2 = parseFloat(b.m2 || b._m2 || 0);
    }
    const kol = parseInt(b.kolicina || 1) || 1;
    const ukup = m2 * kol;
    ukupnoM2 += ukup;
    
    ws.getCell(r, 1).value = i + 1;
    ws.getCell(r, 2).value = ravinaNaziv(b.ravnina_id || b._ravnina_id);
    ws.getCell(r, 3).value = (b.opis || ('Pož. barijera ' + (i+1))) + (b.napomena ? ` (${b.napomena})` : '') + (isManual ? '  ✏️RUČNO' : '');
    ws.getCell(r, 4).value = sirina; ws.getCell(r, 4).numFmt = '0.00';
    ws.getCell(r, 5).value = visina; ws.getCell(r, 5).numFmt = '0.00';
    ws.getCell(r, 6).value = m2;     ws.getCell(r, 6).numFmt = '0.00';
    ws.getCell(r, 7).value = kol;
    ws.getCell(r, 8).value = ukup;   ws.getCell(r, 8).numFmt = '0.00';
    
    for (let i2 = 1; i2 <= 8; i2++) {
      const c = ws.getCell(r, i2);
      c.font = { name: 'Calibri', size: 10 };
      c.alignment = { vertical: 'middle', horizontal: i2 >= 4 ? 'right' : 'left', indent: i2 < 4 ? 1 : 0 };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      if (r % 2 === 0) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    }
    ws.getRow(r).height = 18;
    r++;
  });
  
  // Suma
  r++;
  ws.mergeCells(r, 1, r, 7);
  const cs = ws.getCell(r, 1);
  cs.value = `UKUPNO POŽARNE BARIJERE (${barijere.length} stavki):`;
  cs.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  cs.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  cs.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  const cs2 = ws.getCell(r, 8);
  cs2.value = ukupnoM2;
  cs2.numFmt = '0.00 "m²"';
  cs2.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
  cs2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  cs2.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 22;
  
  return ws;
}

// ═══════════════════════════════════════════════════════════════════════════
// FAZA A: Excel sheet 3 — RAZLIČITE DEBLJINE ETICS-a
// ═══════════════════════════════════════════════════════════════════════════
async function generirajSheetDebljine(wb, f, gradNaziv, gradAdresa) {
  const debljine = Array.isArray(f.zone_debljine_json) ? f.zone_debljine_json : [];
  if (!debljine.length) return null;
  
  const ws = wb.addWorksheet('Razl. debljine', {
    pageSetup: {
      paperSize: 9, orientation: 'portrait', fitToPage: true,
      fitToWidth: 1, fitToHeight: 0,
      margins: { left: 0.5, right: 0.5, top: 0.5, bottom: 0.5, header: 0.2, footer: 0.2 }
    }
  });
  ws.columns = [
    { width: 5 }, { width: 8 }, { width: 16 }, { width: 22 },
    { width: 10 }, { width: 10 }, { width: 10 }, { width: 8 }, { width: 12 }
  ];
  
  const DARK = 'FF0F172A', ACCENT = 'FF0E7490', LIGHT = 'FFE0F2FE';
  let r = 1;
  
  ws.mergeCells(r, 1, r, 9);
  const c1 = ws.getCell(r, 1);
  c1.value = `RAZLIČITE DEBLJINE ETICS-a — ${gradNaziv || 'Knjiga'} (proc #${f.id})`;
  c1.font = { bold: true, size: 14, color: { argb: 'FFFFFFFF' } };
  c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  c1.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 24;
  r++;
  
  if (gradAdresa) {
    ws.mergeCells(r, 1, r, 9);
    const c2 = ws.getCell(r, 1);
    c2.value = gradAdresa;
    c2.font = { italic: true, size: 10, color: { argb: 'FF64748B' } };
    c2.alignment = { horizontal: 'center' };
    r++;
  }
  r++;
  
  const headers = ['Br.', 'cm', 'Ravnina', 'Opis', 'Širina (m)', 'Visina (m)', 'm² po kom', 'Kol.', 'Ukupno m²'];
  headers.forEach((h, i) => {
    const c = ws.getCell(r, i + 1);
    c.value = h;
    c.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i >= 4 ? 'right' : 'left', vertical: 'middle', indent: i < 4 ? 1 : 0 };
  });
  ws.getRow(r).height = 18;
  r++;
  
  const ravnine = Array.isArray(f.ravnine_json) ? f.ravnine_json : [];
  const ravinaNaziv = (id) => {
    const idx = ravnine.findIndex(rv => rv.id === id);
    if (idx < 0) return id ? '?' : '— van ravnine —';
    return `R${idx+1}: ${ravnine[idx].opis || ('Ravnina ' + (idx+1))}`;
  };
  
  // Sortiraj po debljini
  const sorted = [...debljine].sort((a, b) => parseFloat(a.debljina_cm||0) - parseFloat(b.debljina_cm||0));
  
  let ukupnoM2 = 0;
  const sumaPoDebljini = {};
  sorted.forEach((d, i) => {
    const isManual = !!d._manual_override;
    let sirina, visina, m2;
    if (isManual && d._manual_sirina && d._manual_visina) {
      sirina = parseFloat(d._manual_sirina);
      visina = parseFloat(d._manual_visina);
      m2 = sirina * visina;
    } else {
      sirina = parseFloat(d.sirina_m || 0);
      visina = parseFloat(d.visina_m || 0);
      m2 = parseFloat(d.m2 || d._m2 || 0);
    }
    const kol = parseInt(d.kolicina || 1) || 1;
    const ukup = m2 * kol;
    const cm = parseFloat(d.debljina_cm || 0);
    ukupnoM2 += ukup;
    sumaPoDebljini[cm] = (sumaPoDebljini[cm] || 0) + ukup;
    
    ws.getCell(r, 1).value = i + 1;
    ws.getCell(r, 2).value = cm + ' cm';
    ws.getCell(r, 3).value = ravinaNaziv(d.ravnina_id || d._ravnina_id);
    ws.getCell(r, 4).value = (d.opis || (cm + 'cm zona')) + (d.napomena ? ` (${d.napomena})` : '') + (isManual ? '  ✏️RUČNO' : '');
    ws.getCell(r, 5).value = sirina; ws.getCell(r, 5).numFmt = '0.00';
    ws.getCell(r, 6).value = visina; ws.getCell(r, 6).numFmt = '0.00';
    ws.getCell(r, 7).value = m2;     ws.getCell(r, 7).numFmt = '0.00';
    ws.getCell(r, 8).value = kol;
    ws.getCell(r, 9).value = ukup;   ws.getCell(r, 9).numFmt = '0.00';
    
    for (let i2 = 1; i2 <= 9; i2++) {
      const c = ws.getCell(r, i2);
      c.font = { name: 'Calibri', size: 10 };
      c.alignment = { vertical: 'middle', horizontal: i2 >= 5 ? 'right' : 'left', indent: i2 < 5 ? 1 : 0 };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      if (r % 2 === 0) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    }
    ws.getRow(r).height = 18;
    r++;
  });
  
  // Sumarni po debljini
  r++;
  ws.mergeCells(r, 1, r, 9);
  const csH = ws.getCell(r, 1);
  csH.value = 'Suma po debljini:';
  csH.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  csH.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
  csH.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 18;
  r++;
  
  Object.keys(sumaPoDebljini).sort((a,b) => parseFloat(a) - parseFloat(b)).forEach(cm => {
    ws.mergeCells(r, 1, r, 4);
    const cl = ws.getCell(r, 1);
    cl.value = `${cm} cm:`;
    cl.font = { bold: true, size: 10 };
    cl.alignment = { horizontal: 'left', vertical: 'middle', indent: 2 };
    ws.mergeCells(r, 5, r, 9);
    const cv = ws.getCell(r, 5);
    cv.value = sumaPoDebljini[cm];
    cv.numFmt = '0.00 "m²"';
    cv.font = { bold: true, size: 10 };
    cv.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    r++;
  });
  
  // Total
  r++;
  ws.mergeCells(r, 1, r, 8);
  const cs = ws.getCell(r, 1);
  cs.value = `UKUPNO RAZL. DEBLJINE (${debljine.length} stavki):`;
  cs.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
  cs.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  cs.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  const cs2 = ws.getCell(r, 9);
  cs2.value = ukupnoM2;
  cs2.numFmt = '0.00 "m²"';
  cs2.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
  cs2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  cs2.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  ws.getRow(r).height = 22;
  
  return ws;
}

// ═══════════════════════════════════════════════════════════════════════════
// FAZA A: Excel sheet 4 — DODATNE STAVKE / SITNICE (sa slikama ako postoje)
// ═══════════════════════════════════════════════════════════════════════════
async function generirajSheetSitnice(wb, f, gradNaziv, gradAdresa) {
  const sitnice = Array.isArray(f.sitnice_json) ? f.sitnice_json : [];
  if (!sitnice.length) return null;
  
  const ws = wb.addWorksheet('Dodatni obračun', {
    pageSetup: {
      paperSize: 9, orientation: 'portrait', fitToPage: true,
      fitToWidth: 1, fitToHeight: 0,
      margins: { left: 0.5, right: 0.5, top: 0.5, bottom: 0.5, header: 0.2, footer: 0.2 }
    }
  });
  // ⭐ v135.7.37 (#9 Excel): dodana kolona "Hatch" (boja + oznaka S1/S2...)
  ws.columns = [
    { width: 5 }, { width: 28 }, { width: 12 }, { width: 8 }, { width: 12 }, { width: 12 }
  ];
  
  const DARK = 'FF0F172A', ACCENT = 'FF15803D', LIGHT = 'FFF0FDF4';
  let r = 1;
  
  ws.mergeCells(r, 1, r, 6);
  const c1 = ws.getCell(r, 1);
  c1.value = `DODATNI OBRAČUN — ${gradNaziv || 'Knjiga'} (proc #${f.id})`;
  c1.font = { bold: true, size: 14, color: { argb: 'FFFFFFFF' } };
  c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
  c1.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 24;
  r++;
  
  if (gradAdresa) {
    ws.mergeCells(r, 1, r, 6);
    const c2 = ws.getCell(r, 1);
    c2.value = gradAdresa;
    c2.font = { italic: true, size: 10, color: { argb: 'FF64748B' } };
    c2.alignment = { horizontal: 'center' };
    r++;
  }
  r++;
  
  // ⭐ v446 (Ivan, 18.05.2026): "m² ekvivalent" → "Ukupno" jer kolona sad prikazuje 
  //   vrijednost u jedinici stavke (m', kom, h, pausal — ne samo m²). UKUPNO red razdvojen po jedinici.
  const headers = ['Br.', 'Opis stavke', 'Količina', 'Jed.', 'Ukupno', 'Hatch'];
  headers.forEach((h, i) => {
    const c = ws.getCell(r, i + 1);
    c.value = h;
    c.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    c.alignment = { horizontal: i >= 2 ? 'right' : 'left', vertical: 'middle', indent: i < 2 ? 1 : 0 };
  });
  ws.getRow(r).height = 18;
  r++;
  
  let ukupnoM2 = 0;
  // ⭐ v446 (Ivan, 18.05.2026): per-unit akumulator za UKUPNO red (m', m², kom, h, pausal)
  const ukupnoByUnit = {};
  for (let i = 0; i < sitnice.length; i++) {
    const s = sitnice[i];
    const opis = s.opis || ('Stavka ' + (i+1));
    const kolJedna = parseFloat(s.kolicina || 0);
    const stavkaKol = parseInt(s.stavka_kolicina) || 1;
    const jed = s.jedinica || 'kom';
    const napomena = s.napomena ? ` — ${s.napomena}` : '';
    // ⭐ v306 (Ivan): stavka_kolicina multiplier (× N istih dimenzija)
    //   Prikaz u Excel-u: "5.68 × 0.76 = 4.32 × 3 = 12.96 m²" tip rastavljen.
    //   Kolona "Količina" prikazuje UKUPNU (kolJedna × stavkaKol), kolona "Mn" 
    //   pomoćno prikazuje × N ako je > 1.
    const kolUkupno = kolJedna * stavkaKol;
    // ⭐ v446 (Ivan): "Ukupno" kolona = vrijednost u jedinici stavke (NE samo m²).
    //   m' za m' stavke, kom za kom, itd. — sad pravilno zbraja.
    const valU = kolUkupno;  // već uključuje stavka_kolicina multiplier
    if (jed === 'm2') ukupnoM2 += valU;  // legacy za m² sumu
    ukupnoByUnit[jed] = (ukupnoByUnit[jed] || 0) + valU;
    
    // Opis: dodaj × N ako > 1 da nadzor jasno vidi multiplier
    const opisFinal = stavkaKol > 1 
      ? `${opis}${napomena}  (${kolJedna.toFixed(2)} ${jed === 'm' ? "m'" : (jed === 'm2' ? 'm²' : jed)} × ${stavkaKol})`
      : opis + napomena;
    
    ws.getCell(r, 1).value = i + 1;
    ws.getCell(r, 2).value = opisFinal;
    ws.getCell(r, 3).value = kolUkupno; ws.getCell(r, 3).numFmt = '0.00';
    ws.getCell(r, 4).value = jed;
    ws.getCell(r, 5).value = valU;  ws.getCell(r, 5).numFmt = '0.00';
    
    // ⭐ v135.7.37 (#9 Excel): Hatch kolona (boja + oznaka S1/S2...)
    if (s.hatch_aktivan) {
      const oznaka = `S${i+1}`;
      const polygonOk = Array.isArray(s.hatch_tocke_px) && s.hatch_tocke_px.length >= 3;
      const hatchTxt = polygonOk ? `■ ${oznaka}` : `□ ${oznaka} (bez poligona)`;
      const hatchCell = ws.getCell(r, 6);
      hatchCell.value = hatchTxt;
      // Pretvori HEX boju iz #RRGGBB u FFRRGGBB za ExcelJS
      let hexBoja = (s.hatch_boja || '#ec4899').replace('#', '').toUpperCase();
      if (hexBoja.length === 6) hexBoja = 'FF' + hexBoja;
      hatchCell.font = { 
        name: 'Calibri', size: 10, bold: true, 
        color: { argb: polygonOk ? hexBoja : 'FF94A3B8' } 
      };
      // Lagani background s tom bojom (alpha simuliran kroz tint)
      if (polygonOk) {
        hatchCell.fill = { 
          type: 'pattern', pattern: 'solid', 
          fgColor: { argb: hexBoja.replace(/^FF/, '20') }  // 20 alfa = 12.5% opacity
        };
      }
    } else {
      ws.getCell(r, 6).value = '—';
      ws.getCell(r, 6).font = { name: 'Calibri', size: 10, color: { argb: 'FF94A3B8' } };
    }
    
    for (let i2 = 1; i2 <= 6; i2++) {
      const c = ws.getCell(r, i2);
      if (!c.font) c.font = { name: 'Calibri', size: 10 };
      c.alignment = { vertical: 'middle', horizontal: i2 >= 3 ? 'right' : 'left', indent: i2 < 3 ? 1 : 0 };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      if (r % 2 === 0 && !c.fill) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    }
    ws.getRow(r).height = 18;
    r++;
    
    // Slike stavke — multi-image support
    // AUDIT FIX #9: prefer fotke_qnap (download s QNAP-a) → fallback fotke_base64 (legacy)
    const sveSlikeBuffers = [];
    
    // Helper: download slika s QNAP-a u Buffer
    const fetchQnapImg = async (qnapPath) => {
      if (!qnapPath || !process.env.QNAP_WEBDAV_URL) return null;
      try {
        const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
        const base = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
        const auth64 = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
        const cleanPath = qnapPath.replace(/^\//, '');
        const encoded = cleanPath.split('/').filter(Boolean).map(encodeURIComponent).join('/');
        const r = await fetch(`${baseUrl}${base}/${encoded}`, { 
          headers: { Authorization: `Basic ${auth64}` },
          signal: AbortSignal.timeout(10000)
        });
        if (!r.ok) {
          console.warn(`[Excel sitnica fetchQnapImg] ${qnapPath}: status ${r.status}`);
          return null;
        }
        const buf = Buffer.from(await r.arrayBuffer());
        const ext = qnapPath.toLowerCase().endsWith('.png') ? 'png' : 'jpeg';
        return { buf, ext };
      } catch(e) {
        console.warn(`[Excel sitnica fetchQnapImg] ${qnapPath}:`, e.message);
        return null;
      }
    };
    
    // ⭐ v310 BUG FIX (Ivan): jedna slika uploadana → prikazane dvije u Excelu.
    //    Vidi komentar u generirajAgregiraniSheetSitnice za detalje.
    //    FIX: prioritetni fallback (else if) — koristi prvi izvor koji ima slike.
    if (Array.isArray(s.fotke_qnap) && s.fotke_qnap.length > 0) {
      for (const qpath of s.fotke_qnap) {
        if (qpath && typeof qpath === 'string') {
          const fetched = await fetchQnapImg(qpath);
          if (fetched) sveSlikeBuffers.push(fetched);
        }
      }
    } else if (Array.isArray(s.fotke_base64) && s.fotke_base64.length > 0) {
      for (const b64 of s.fotke_base64) {
        if (typeof b64 === 'string' && b64.startsWith('data:image/')) {
          const mh = b64.match(/^data:image\/([a-z]+);base64,(.+)$/);
          if (mh) {
            sveSlikeBuffers.push({ buf: Buffer.from(mh[2], 'base64'), ext: mh[1] === 'png' ? 'png' : 'jpeg' });
          }
        }
      }
    } else if (Array.isArray(s.slike) && s.slike.length > 0) {
      for (const x of s.slike) {
        if (typeof x === 'string' && x.startsWith('data:image/')) {
          const mh = x.match(/^data:image\/([a-z]+);base64,(.+)$/);
          if (mh) sveSlikeBuffers.push({ buf: Buffer.from(mh[2], 'base64'), ext: mh[1] === 'png' ? 'png' : 'jpeg' });
        }
      }
    } else {
      [s.foto_base64, s.dodatna_slika, s.slika_base64].forEach(legacy => {
        if (legacy && typeof legacy === 'string' && legacy.startsWith('data:image/')) {
          const mh = legacy.match(/^data:image\/([a-z]+);base64,(.+)$/);
          if (mh) sveSlikeBuffers.push({ buf: Buffer.from(mh[2], 'base64'), ext: mh[1] === 'png' ? 'png' : 'jpeg' });
        }
      });
    }
    
    // Crtaj slike u 2 kolone, max 4 po stavki
    const limit = Math.min(sveSlikeBuffers.length, 4);
    for (let si = 0; si < limit; si++) {
      try {
        const { buf, ext } = sveSlikeBuffers[si];
        const imgId = wb.addImage({ buffer: buf, extension: ext });
        const colOffset = (si % 2 === 0) ? 1.2 : 3.5;
        const rowOffset = Math.floor(si / 2) * 8.5;
        ws.addImage(imgId, {
          tl: { col: colOffset, row: r - 1 + rowOffset + 0.1 },
          ext: { width: 200, height: 150 },
          editAs: 'oneCell'
        });
      } catch(de) { console.warn('[Excel sitnica slika ' + si + ']', de.message); }
    }
    
    if (limit > 0) {
      const rezerviranoRedova = Math.ceil(limit / 2) * 8;
      for (let kk = 0; kk < rezerviranoRedova; kk++) {
        ws.getRow(r + kk).height = 21;
      }
      r += rezerviranoRedova;
    }
  }
  
  // Suma
  // ⭐ v446 (Ivan, 18.05.2026): UKUPNO razdvojen po jedinici (jedan red po m²/m'/kom/h/pausal)
  r++;
  const ukUnits_p = Object.keys(ukupnoByUnit).filter(u => Math.abs(ukupnoByUnit[u]) > 0.001);
  const unitOrder_p = { 'm2': 0, 'm': 1, 'kom': 2, 'h': 3, 'pausal': 4 };
  ukUnits_p.sort((a, b) => (unitOrder_p[a] ?? 99) - (unitOrder_p[b] ?? 99));
  if (ukUnits_p.length === 0) {
    ws.mergeCells(r, 1, r, 5);
    const cs = ws.getCell(r, 1);
    cs.value = `UKUPNO (${sitnice.length} stavki):`;
    cs.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    cs.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
    cs.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    const cs2 = ws.getCell(r, 6);
    cs2.value = 0;
    cs2.numFmt = '0.00';
    cs2.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
    cs2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
    cs2.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 22;
    r++;
  } else {
    for (const u of ukUnits_p) {
      const uLabel = u === 'm' ? "m'" : (u === 'm2' ? 'm²' : u);
      const brStavki_u = sitnice.filter(s => (s.jedinica || 'kom') === u).length;
      ws.mergeCells(r, 1, r, 5);
      const cs = ws.getCell(r, 1);
      cs.value = `UKUPNO ${uLabel} (${brStavki_u} stavk${brStavki_u === 1 ? 'a' : 'i'}):`;
      cs.font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
      cs.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
      cs.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
      const cs2 = ws.getCell(r, 6);
      cs2.value = ukupnoByUnit[u];
      cs2.numFmt = `0.00 "${uLabel}"`;
      cs2.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };
      cs2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ACCENT } };
      cs2.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
      ws.getRow(r).height = 22;
      r++;
    }
  }
  
  // ⭐ v135.7.37 (#9 Excel): Hatch legend (ako ima sitnica s hatch)
  const hatchSitnice = sitnice.filter(s => s.hatch_aktivan);
  if (hatchSitnice.length > 0) {
    r += 2;
    ws.mergeCells(r, 1, r, 6);
    const lg = ws.getCell(r, 1);
    lg.value = `🎨 LEGENDA HATCH (osjenčani dodaci na slici):`;
    lg.font = { bold: true, size: 10, color: { argb: 'FF0F172A' } };
    lg.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 18;
    r++;
    
    hatchSitnice.forEach((s) => {
      const idxOriginal = sitnice.indexOf(s);
      const oznaka = `S${idxOriginal + 1}`;
      const polygonOk = Array.isArray(s.hatch_tocke_px) && s.hatch_tocke_px.length >= 3;
      let hexBoja = (s.hatch_boja || '#ec4899').replace('#', '').toUpperCase();
      if (hexBoja.length === 6) hexBoja = 'FF' + hexBoja;
      
      ws.mergeCells(r, 1, r, 6);
      const lc = ws.getCell(r, 1);
      lc.value = `   ${polygonOk ? '■' : '□'}  ${oznaka} — ${s.opis || ''} · ${(s.hatch_naziv || s.hatch_boja)} · ${(parseFloat(s.kolicina) || 0).toFixed(2)} ${s.jedinica === 'm' ? "m'" : (s.jedinica || 'm²')}${(parseInt(s.stavka_kolicina) || 1) > 1 ? ` × ${parseInt(s.stavka_kolicina)} = ${((parseFloat(s.kolicina) || 0) * (parseInt(s.stavka_kolicina) || 1)).toFixed(2)} ${s.jedinica === 'm' ? "m'" : (s.jedinica || 'm²')}` : ''}${polygonOk ? '' : '  (poligon nije nacrtan)'}`;
      lc.font = { 
        size: 9.5, 
        color: { argb: polygonOk ? hexBoja : 'FF94A3B8' }, 
        bold: polygonOk
      };
      lc.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      ws.getRow(r).height = 14;
      r++;
    });
  }
  
  return ws;
}


// LOGO_B64 reuse — uzimamo iz globalnog scope-a (vidi PDF dnevnika)
// Definiramo zaseban LOGO_B64 da ne ovisimo o PDF kontekstu
// ⭐ v135.7.502.20.233 (Ivan, 10.06.2026): službeni asseti knjige — novi logo + potpis + pečat
const ZBUKA_LOGO_NOVI_B64 = '';
const ZBUKA_LOGO_NASLOVNA_B64 = '';  // ⭐ v239: logo centriran UNUTAR slike pune širine sadržaja (842px) — centriranje više ne ovisi o rendereru
const KNJIGA_POTPIS_B64 = '';
const KNJIGA_PECAT_B64 = '';
const LOGO_B64 = ZBUKA_LOGO_NOVI_B64;  // ⭐ v233: normativ i knjiga koriste novi logo

// RAZVIJENA_SIRINA_IMG_B64 — slika za sekciju 1.1 "Što znači razvijena širina"
// Generirana matplotlib-om: presjek profila vijenca + razmotani razvojni dijagram
// Bordeaux paleta usklađena sa ŽBUKA brand-om
const RAZVIJENA_SIRINA_IMG_B64 = '';

// ═══════════════════════════════════════════════════════════════════════════
// v135.7.181: NORMATIVI SHEET — REDIZAJN (bordeaux paleta, logo, slika 1.1)
//             Stane u 2 A4 stranice. Logo lijevo gore, naslov desno.
//             Sekcije: 1, 2, 3, 4 (4.1-4.3), 5 (5.1-5.7), 6, 8 (8.1-8.2), 9 (9.1-9.4)
//             Maknute sekcije: 7 (demontaža), 9.5 (vizualna shema), 9.6 (primjer skele),
//                              10 (pojmovnik), 11 (ETICS), 12 (skela uvjeti),
//                              13 (žbuka i gips), 14 (VKV koeficijenti)
//             1.1 ima ugrađenu sliku (umjesto ASCII).
//             8.2 ima novi 3. red: "višak 5 cm → r.š. = 1 m¹ = 0,35 m² × duljina špalete"
// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v1213 (Ivan: „opet je prekinuo iz excela u pdf print kod normativa, stane i onda normativ
//   posebno isprinta"): NORMATIVI SU SE GRADILI IZVAN BUILDERA KNJIGE — i zato su promakli.
//   Sve dosadasnje provjere („nijedan list ne slaze svoj pageSetup") gledale su UNUTAR
//   `_kuGenerirajKnjiguWB`. Ovaj list nastaje u zasebnoj, starijoj funkciji koju knjiga samo
//   pozove — pa je zadrzao svoje margine (0,22/0,35/0,38) i svoje stupce (zbroj 142 → 1019 px
//   → skala 0,749), dok svi ostali listovi imaju 829,5 px → 0,9198.
//   ⚠ POUKA: „svi listovi" znaci SVI, ukljucujuci one koje gradi tudja funkcija. Provjera koja
//   gleda samo jedan blok koda ne dokazuje tvrdnju o cijeloj datoteci.
//   `opts.kuUskladi` — kad knjiga zove ovu funkciju, list se slaze po njezinoj mjeri. Ostala tri
//   pozivatelja (stari izvozi) ostaju netaknuta.
async function generirajSheetNormativi(wb, gradilisteInfo = null, opts = null) {
  // === NAVY/GOLD PALETA (usklađeno s dokaznicom/rekapitulacijom knjige) === ⭐ v542 (Ivan): redizajn bordeaux → navy/zlato
  const BORDEAUX = 'FF1A2A3F';        // NAVY — band naslova sekcija
  const BORDEAUX_DARK = 'FF1A2A3F';   // NAVY — subsection & bold tekst
  const BORDEAUX_DARKER = 'FF0E1825'; // NAVY2 — najtamniji naslov / highlight
  const BORDEAUX_LIGHT = 'FFEFE7D4';  // pale gold — subsection band
  const BORDEAUX_PALE = 'FFFAF8F2';   // IVORY — alternate rows
  const DARK_GRAY = 'FF334155';       // slate — body tekst
  const BORDER_GRAY = 'FFD8D0BE';     // topli gold-grey — granice tablica
  const WARN_BG = 'FFF6EED6';         // topli pijesak — callout pozadina
  const WARN_TEXT = 'FF7A5B28';       // gold-brown — callout tekst
  const EXAMPLE_BG = 'FFF3EEE2';      // ivory-gold — primjeri/highlight
  const EXAMPLE_TEXT = 'FF1A2A3F';    // NAVY — primjeri tekst
  const WHITE = 'FFFFFFFF';
  const GRAY_MED = 'FF6B6F76';        // SUBC — captions
  const GREY = 'FFF4F2EC';            // warm grey — table header fill (kao dokaznica) ⭐ v542
  const GOLD = 'FFB08A4F', GOLD2 = 'FF8C6D3C';  // antikni bronz/zlato akcent ⭐ v542
  const FSER = 'Georgia';             // serifni font naslova (kao knjiga) ⭐ v542
  
  const _kuU = !!(opts && opts.kuUskladi);   // * v1213: knjiga trazi svoju mjeru
  const ws = wb.addWorksheet('Normativi', _kuU ? { pageSetup: opts.kuPageSetup() } : {
    pageSetup: {
      paperSize: 9,                // A4
      orientation: 'portrait',
      fitToPage: true,
      fitToWidth: 1,
      fitToHeight: 0,              // ⭐ v542 (Ivan): BEZ vertikalne kompresije — tekst se ne gnječi/preklapa; teče prirodno preko stranica
      margins: { left: 0.22, right: 0.22, top: 0.35, bottom: 0.38,
                 header: 0.16, footer: 0.18 },
      horizontalCentered: true
    },
    views: [{ showGridLines: false }]
  });
  
  // ⭐ v542 (Ivan): široki stupci — sadržaj seže do ruba A4 (zbroj ~118 ≈ puna portrait širina, kao dokaznica)
  // * v1213: kad knjiga trazi uskladjenje, stupci se skaliraju tako da PIKSELNA sirina bude ista
  //   kao na ostalim listovima (829,5 px) — razdioba ostaje ista, mijenja se samo mjerilo.
  const _COLW0 = [7, 52, 29, 29, 25];
  const COLW = _kuU
    ? (() => { const cilj = (opts.kuCiljPx - _COLW0.length * 5) / 7;
               const f = cilj / _COLW0.reduce((a, b) => a + b, 0);
               return _COLW0.map(w => Math.round(w * f * 100) / 100); })()
    : _COLW0;   // ⭐ v545 (Ivan): šire (zbroj 142) → fitToWidth uniformno smanji na ~75% → normativ stane na 2 str (landscape testiran = 4 str, gore)   // A:numeracija · B:opis/naslov · C/D/E:tablica
  ws.columns = COLW.map(w => ({ width: w }));
  // ⭐ v543 (Ivan): print-footer s brojem stranice na svakoj stranici (Investitor/Nadzor lakše navigira ~3-str. prilog)
  ws.headerFooter = { differentFirst: false, differentOddEven: false,
    oddFooter: '&L&"Arial"&8&K8C6D3CNormativi obračuna · GN 421&R&"Arial"&8&K6B6F76str. &P / &N' };
  
  // ═══════════════════════════════════════════════════════════════════════
  // HELPERI
  // ═══════════════════════════════════════════════════════════════════════
  let r = 1;

  // ⭐ v542 (Ivan): adaptivne visine redova — procijeni broj redaka iz duljine teksta i širine merge-a
  //   → tekst se NIKAD ne reže ("ćelija ga ne jede"). Eksplicitna visina = MINIMUM, raste po potrebi.
  let _zebra = 0;   // ⭐ v543: brojač redova tablice za zebra-pruge (reset u addTblHeader)
  const _txt = (t) => (t && t.richText) ? t.richText.map(x => (x && x.text) || '').join('') : (t == null ? '' : String(t));   // ⭐ v543: richText → plain za procjenu retka
  const _wUnits = (c1, c2) => { let s = 0; for (let i = c1; i <= c2; i++) s += (COLW[i - 1] || 8.43); return s; };
  const _estLines = (text, wUnits, fs, indent) => {
    const t = _txt(text); if (!t) return 1;
    const usable = Math.max(4, wUnits - (indent || 0) * 1.1);
    const cpl = Math.max(6, usable * (11 / (fs || 9.5)) * 0.92);   // znakova po retku (proporcionalni font, 0.92 sigurnost)
    let lines = 0; for (const seg of t.split('\n')) lines += Math.max(1, Math.ceil(seg.length / cpl));
    return lines;
  };
  const _rowH = (lines, fs) => Math.ceil(lines * (fs || 9.5) * 1.35) + 4;
  const _autoH = (text, c1, c2, fs, indent, minH) => Math.max(minH || 0, _rowH(_estLines(text, _wUnits(c1, c2), fs, indent), fs));

  // Merge i upiši text
  const m = (text, opts = {}) => {
    const c1 = opts.c1 || 1;
    const c2 = opts.c2 || 5;
    if (c1 < c2) ws.mergeCells(r, c1, r, c2);
    const cell = ws.getCell(r, c1);
    cell.value = text;
    cell.font = opts.font || { name: 'Arial', size: 9, color: { argb: DARK_GRAY } };
    cell.alignment = opts.align || { horizontal: 'left', vertical: 'top', indent: 2, wrapText: true };
    if (opts.fill) {
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: opts.fill } };
    }
    // ⭐ v542: visina = max(zadana, procijenjena iz teksta) — wrap nikad ne ostane odrezan
    const _fs = (opts.font && opts.font.size) || 9.5;
    const _ind = (opts.align && typeof opts.align.indent === 'number') ? opts.align.indent : 2;
    ws.getRow(r).height = _autoH(text, c1, c2, _fs, _ind, opts.height || 0);
    r++;
  };
  
  // Empty row
  const empty = (h = 4) => { ws.getRow(r).height = h; r++; };
  
  // Section header (1, 2, 3...)
  const addSekcija = (broj, naslov) => {
    const _rr = r;
    m({ richText: [
      { text: `${broj}.`, font: { name: FSER, bold: true, size: 12, color: { argb: GOLD } } },        // ⭐ v543: broj sekcije u zlatu
      { text: `   ${naslov}`, font: { name: FSER, bold: true, size: 11, color: { argb: WHITE } } }
    ] }, {
      font: { name: FSER, bold: true, size: 11, color: { argb: WHITE } },   // ⭐ v542: serifni navy masthead
      fill: BORDEAUX,
      align: { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true },
      height: 21
    });
    ws.getCell(_rr, 1).border = { bottom: { style: 'medium', color: { argb: GOLD } } };   // ⭐ v542: zlatna akcentna linija (kao dokaznica)
  };
  
  // Subsection header (1.1, 1.2...)
  const addSub = (broj, naslov) => {
    const _rr = r;
    m(`${broj}  ${naslov}`, {
      font: { name: FSER, bold: true, size: 10, color: { argb: BORDEAUX_DARK } },   // ⭐ v542: serif, navy na pale-gold bandu
      fill: BORDEAUX_LIGHT,
      align: { horizontal: 'left', vertical: 'middle', indent: 2, wrapText: true },
      height: 17
    });
    ws.getCell(_rr, 1).border = { left: { style: 'medium', color: { argb: GOLD } } };   // ⭐ v543: zlatni lijevi akcent (kao oznaka odjeljka)
  };
  
  // Body paragraph
  const addPar = (tekst, h = 18) => {
    m(tekst, {
      font: { name: 'Arial', size: 9, color: { argb: DARK_GRAY } },
      align: { horizontal: 'left', vertical: 'top', indent: 2, wrapText: true },
      height: h
    });
  };
  
  // Important text (bold)
  const addImportant = (tekst, h = 18) => {
    m(tekst, {
      font: { name: 'Arial', bold: true, size: 9, color: { argb: BORDEAUX_DARKER } },
      align: { horizontal: 'left', vertical: 'top', indent: 2, wrapText: true },
      height: h
    });
  };
  
  // Bullet
  const addBullet = (tekst, h = 15) => {
    m(`•  ${tekst}`, {
      font: { name: 'Arial', size: 9, color: { argb: DARK_GRAY } },
      align: { horizontal: 'left', vertical: 'top', indent: 3, wrapText: true },
      height: h
    });
  };
  
  // Warning box
  const addWarning = (tekst, h = 18) => {
    const _rr = r;
    m(tekst, {
      font: { name: 'Arial', bold: true, size: 9, color: { argb: WARN_TEXT } },
      fill: WARN_BG,
      align: { horizontal: 'left', vertical: 'middle', indent: 2, wrapText: true },
      height: h
    });
    ws.getCell(_rr, 1).border = { left: { style: 'thick', color: { argb: GOLD2 } } };   // ⭐ v543: zlatna callout-traka (vizualno "važna napomena")
  };
  
  // Italic caption
  const addCaption = (tekst, h = 14) => {
    m(tekst, {
      font: { name: 'Arial', italic: true, size: 9, color: { argb: GRAY_MED } },
      align: { horizontal: 'left', vertical: 'top', indent: 2, wrapText: true },
      height: h
    });
  };
  
  // Cell borders helper
  const allBorders = {
    top: { style: 'thin', color: { argb: BORDER_GRAY } },
    bottom: { style: 'thin', color: { argb: BORDER_GRAY } },
    left: { style: 'thin', color: { argb: BORDER_GRAY } },
    right: { style: 'thin', color: { argb: BORDER_GRAY } }
  };
  
  // Table header row — cells = [{text, span}, ...]
  const addTblHeader = (cells, h = 19) => {
    _zebra = 0;   // ⭐ v543: reset zebra-pruga za novu tablicu
    let cur = 2; let maxLines = 1;
    for (const cell of cells) {
      const span = cell.span || 1;
      const end = cur + span - 1;
      if (span > 1) ws.mergeCells(r, cur, r, end);
      const c = ws.getCell(r, cur);
      c.value = cell.text;
      c.font = { name: 'Arial', bold: true, size: 9, color: { argb: BORDEAUX_DARKER } };   // ⭐ v542: NAVY2 tekst
      c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: GREY } };                // ⭐ v542: warm grey (kao dokaznica)
      c.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
      c.border = { top: { style: 'thin', color: { argb: BORDER_GRAY } }, left: { style: 'thin', color: { argb: BORDER_GRAY } }, right: { style: 'thin', color: { argb: BORDER_GRAY } }, bottom: { style: 'medium', color: { argb: GOLD } } };   // ⭐ v542: zlatni rub ispod headera
      maxLines = Math.max(maxLines, _estLines(cell.text, _wUnits(cur, end), 9.5, 0));
      cur = end + 1;
    }
    ws.getRow(r).height = Math.max(h, _rowH(maxLines, 9.5));
    r++;
  };
  
  // Table data row — cells = [{text, span, bold, center, fill}, ...]
  const addTblRow = (cells, h = 15) => {
    _zebra++; const _stripe = (_zebra % 2 === 0) ? BORDEAUX_PALE : null;   // ⭐ v543: naizmjenična ivory pruga (čitljivost)
    let cur = 2; let maxLines = 1;
    for (const cell of cells) {
      const span = cell.span || 1;
      const end = cur + span - 1;
      if (span > 1) ws.mergeCells(r, cur, r, end);
      const c = ws.getCell(r, cur);
      c.value = cell.text;
      c.font = {
        name: 'Arial', size: 9,
        color: { argb: cell.bold ? BORDEAUX_DARK : DARK_GRAY },
        bold: cell.bold || false,
        italic: cell.italic || false
      };
      if (cell.fill) {
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: cell.fill } };
      } else if (_stripe) {
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: _stripe } };   // ⭐ v543: zebra-pruga
      }
      c.alignment = {
        horizontal: cell.center ? 'center' : 'left',
        vertical: 'middle',
        indent: cell.center ? 0 : 1,
        wrapText: true
      };
      c.border = allBorders;
      maxLines = Math.max(maxLines, _estLines(cell.text, _wUnits(cur, end), 9.5, cell.center ? 0 : 1));   // ⭐ v542
      cur = end + 1;
    }
    ws.getRow(r).height = Math.max(h, _rowH(maxLines, 9.5));   // ⭐ v542: adaptivna visina — tekst se ne reže
    r++;
  };
  
  // ═══════════════════════════════════════════════════════════════════════
  // HEADER s LOGOM (lijevo) i NASLOVOM (desno)
  // ═══════════════════════════════════════════════════════════════════════
  
  // Logo - dodaj u workbook ako još nije
  let logoImageId;
  try {
    logoImageId = wb.addImage({
      base64: 'data:image/png;base64,' + LOGO_B64,
      extension: 'png'
    });
  } catch(e) { logoImageId = null; }
  
  // Postavi visine za 3 reda headera (logo zauzima ~3 reda)
  ws.getRow(r).height = 14;     // r1
  ws.getRow(r+1).height = 28;   // r2 (title)
  ws.getRow(r+2).height = 16;   // r3 (subtitle)
  
  // Logo na početku (red r, kolona 1)
  if (logoImageId !== null) {
    try {
      ws.addImage(logoImageId, {
        tl: { col: 0.1, row: r - 1 + 0.1 },
        ext: { width: 100, height: 43 }
      });
    } catch(e) {}
  }
  
  // r1 — empty space gore
  r++;
  
  // r2 — Naslov (desno)
  ws.mergeCells(r, 2, r, 5);
  const cTitle = ws.getCell(r, 2);
  cTitle.value = 'NORMATIVI OBRAČUNA';
  cTitle.font = { name: FSER, bold: true, size: 22, color: { argb: BORDEAUX_DARKER } };   // ⭐ v542: serifni navy naslov
  cTitle.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  r++;
  
  // r3 — Subtitle (desno)
  ws.mergeCells(r, 2, r, 5);
  const cSub = ws.getCell(r, 2);
  cSub.value = 'GN 421 · Tehnički uvjeti obračuna fasaderskih i žbukarskih radova';
  cSub.font = { name: 'Arial', size: 10, color: { argb: DARK_GRAY } };
  cSub.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
  r++;
  
  // ⭐ v542: zlatna divider linija ispod naslova (kao zlatni akcent dokaznice)
  ws.mergeCells(r, 1, r, 5);
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: GOLD } };
  ws.getRow(r).height = 3;
  r++;
  
  // Source caption
  m('Izvor: Prosječne norme u građevinarstvu, knjiga III  ·  Pripremio: ŽBUKA Čakarić d.o.o.', {
    font: { name: 'Arial', italic: true, size: 8.5, color: { argb: DARK_GRAY } },
    align: { horizontal: 'center', vertical: 'middle' },
    height: 14
  });
  
  empty(6);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 1. OPĆE NAČELO
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(1, 'Opće načelo obračuna');
  addPar(
    'Obračun se vrši razvijanjem svih istaka, tako da se dobije stvarno uređena površina. ' +
    'Svaka istaka, udubina, vijenac, prozorska klupčica i drugi 3D elementi obračunavaju se kao ' +
    'stvarno obrađena površina dobivena razmotavanjem svih ploha u ravninu.',
    36
  );
  empty(2);
  
  // 1.1 + slika
  addSub('1.1', 'Što znači "razvijena širina" — koncept');
  
  // Slika razvijene širine
  try {
    const imgId = wb.addImage({
      base64: 'data:image/png;base64,' + RAZVIJENA_SIRINA_IMG_B64,
      extension: 'png'
    });
    ws.addImage(imgId, {
      tl: { col: 0.2, row: r - 1 + 0.1 },
      ext: { width: 480, height: 165 }
    });
    // Rezerviraj 11 redova za sliku (165px / 15px = 11)
    for (let i = 0; i < 11; i++) {
      ws.getRow(r + i).height = 15;
    }
    r += 11;
  } catch(e) {
    console.warn('[Normativi] Slika 1.1 nije ubačena:', e.message);
    addCaption('Slika nije dostupna — vidi tablicu 4.1 za pretvaranje r.š. u m².');
  }
  
  empty(3);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 2. JEDINICA MJERE
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(2, 'Obračun fasadnih površina — jedinica mjere');
  addPar(
    'Fasadne površine — bez obzira na način obrade — obračunavaju se po m². ' +
    'Svi elementi: udubine, istake, trake, vijenci, klupčice, brisoleji, pilastri, utori — ' +
    'obračunavaju se u m¹ i potom pretvaraju u m² po normativnoj tablici (t. 4.1).',
    36
  );
  empty(2);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 3. MALE POVRŠINE
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(3, 'Normativ za male površine');
  addImportant('Površine zidova ispod 10 m²: norma vremena × 1,20 (+ 20 %).');
  addPar('Razlog: kod malih fragmentiranih površina raste udio pripreme i tehničkog gubitka.');
  empty(2);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 4. PRETVARANJE m¹ → m²
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(4, 'Pretvaranje m¹ → m² (ključna tablica)');
  addSub('4.1', 'Tablica koeficijenata pretvaranja');
  addCaption('Vrijedi za vijence, trake, klupčice, pilastre, utore i slične fasadne elemente.');
  
  addTblHeader([
    { text: 'Razvijena širina elementa', span: 2 },
    { text: 'Za 1,00 m¹ obračunava se', span: 2 }
  ], 20);
  
  for (const [sirina, koef] of [
    ['do 12 cm', '0,35 m²'],
    ['12 — 18 cm', '0,50 m²'],
    ['18 — 25 cm', '0,75 m²'],
    ['25 — 50 cm', '1,00 m²'],
    ['50 — 75 cm', '1,25 m²'],
    ['75 — 100 cm', '1,50 m²'],
    ['100 — 125 cm', '1,75 m²'],
    ['125 — 150 cm', '2,00 m²'],
    ['Utori razvijene širine do 5 cm', '0,25 m²']
  ]) {
    addTblRow([
      { text: sirina, span: 2 },
      { text: koef, span: 2, bold: true, center: true }
    ], 16);
  }
  empty(2);
  
  // 4.2
  addSub('4.2', 'Pravilo dodataka za rubove');
  addBullet('Tablica vrijedi za elemente do 4 ruba.');
  addBullet('Više od 4 ruba: + 20 % od gornjih vrijednosti za svaki dodatni rub.');
  addBullet('Maksimalni dodatak: + 40 %.  ·  Svaka oblina računa se kao i rub.');
  empty(2);
  
  // 4.3 — primjeri
  addSub('4.3', 'Praktični primjeri primjene');
  for (const [oz, opis, racun] of [
    ['Primjer A', 'Vijenac r.š. 30 cm × 12 m¹, 4 ruba',
     '1,00 m²/m¹  →  12 × 1,00 = 12,00 m²'],
    ['Primjer B', 'Vijenac r.š. 30 cm × 12 m¹, 6 rubova',
     '12 × 1,00 = 12,00 m² → +40 % (max) = 16,80 m²'],
    ['Primjer C', 'Klupčica r.š. 16 cm × 1,80 m¹',
     '0,50 m²/m¹  →  1,80 × 0,50 = 0,90 m²']
  ]) {
    const c1 = ws.getCell(r, 2);
    c1.value = oz;
    c1.font = { name: 'Arial', bold: true, size: 9, color: { argb: EXAMPLE_TEXT } };
    c1.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: EXAMPLE_BG } };
    
    const c2 = ws.getCell(r, 3);
    c2.value = opis;
    c2.font = { name: 'Arial', size: 9, color: { argb: DARK_GRAY } };
    c2.alignment = { horizontal: 'left', vertical: 'middle', wrapText: true };
    c2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: EXAMPLE_BG } };
    
    ws.mergeCells(r, 4, r, 5);
    const c3 = ws.getCell(r, 4);
    c3.value = racun;
    c3.font = { name: 'Arial', italic: true, size: 9, color: { argb: EXAMPLE_TEXT } };
    c3.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c3.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: EXAMPLE_BG } };
    
    ws.getRow(r).height = 22;
    r++;
  }
  empty(3);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 5. VUČENE PROFILACIJE
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(5, 'Vučene profilacije (venci, šembrane, lučni profili)');
  addWarning('⚠  Drugačiji obračunski sustav od t. 4. Odnosi se na vučene profilacije šablonom.');
  empty(3);
  
  // 5.1
  addSub('5.1', 'Razvijena širina venca — dodaci');
  addTblHeader([
    { text: 'Razvijena širina' },
    { text: 'Dodatak na vrijeme' },
    { text: 'Dodatak na materijal', span: 2 }
  ], 20);
  
  for (const [sirina, vrijeme, materijal] of [
    ['do 50 cm', '+ 20 %', '+ 100 %'],
    ['do 75 cm', '+ 70 %', '+ 150 %'],
    ['do 100 cm', '+ 200 %', '+ 200 %']
  ]) {
    addTblRow([
      { text: sirina },
      { text: vrijeme, bold: true, center: true },
      { text: materijal, span: 2, bold: true, center: true }
    ], 16);
  }
  empty(2);
  
  // 5.2 - 5.5 — kompaktni single-row
  for (const [tag, naslov, opis] of [
    ['5.2', 'Sučeljavanje kod venaca', '1 kom = 1 m¹ odgovarajuće razvijene širine venca.'],
    ['5.3', 'Vučeni profili (šembrana, podnoprozornik...)', 'Norma vremena: + 20 % uz odgovarajuće r.š. venca.'],
    ['5.4', 'Lučni profili', 'Norma vremena: + 15 % od odgovarajuće r.š. venca.'],
    ['5.5', 'Sučeljavanje kod vučenih profila', '1 kom = 1 m¹ odgovarajuće r.š. vučenog/lučnog profila.']
  ]) {
    const c1 = ws.getCell(r, 1);
    c1.value = tag;
    c1.font = { name: 'Arial', bold: true, size: 9, color: { argb: BORDEAUX_DARK } };
    c1.alignment = { horizontal: 'center', vertical: 'middle' };
    c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    const c2 = ws.getCell(r, 2);
    c2.value = naslov;
    c2.font = { name: 'Arial', bold: true, size: 9, color: { argb: DARK_GRAY } };
    c2.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    ws.mergeCells(r, 3, r, 5);
    const c3 = ws.getCell(r, 3);
    c3.value = opis;
    c3.font = { name: 'Arial', size: 9, color: { argb: DARK_GRAY } };
    c3.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c3.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    ws.getRow(r).height = 17;
    r++;
  }
  empty(2);
  
  // 5.6
  addSub('5.6', 'Dodatak za broj ivica (samo za vučene profile)');
  addBullet('Vrijedi za profile do 4 ivice.');
  addBullet('Za svaku ivicu preko 4: + 5 %, maksimalno + 60 %.  ·  Svaka krivina računa se kao ivica.');
  empty(3);
  
  // 5.7
  addSub('5.7', 'Razlika između t. 4.2 i t. 5.6 — RAZJAŠNJENJE');
  addCaption('Obavezno navesti u građevinskoj knjizi koji se obračunski sustav primjenjuje:');
  
  addTblHeader([
    { text: 'Kontekst', span: 2 },
    { text: 'Po ivici / rubu' },
    { text: 'Maksimum' }
  ], 20);
  
  for (const [kontekst, ivica, maks] of [
    ['Tablica m¹→m² (t. 4.1) — fasadni elementi', '+ 20 %', '+ 40 %'],
    ['Vučene profilacije (t. 5) — venci, šembrane', '+ 5 %', '+ 60 %']
  ]) {
    addTblRow([
      { text: kontekst, span: 2 },
      { text: ivica, bold: true, center: true },
      { text: maks, bold: true, center: true }
    ], 20);
  }
  empty(3);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 6. SPOJNICE (NITNE)
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(6, 'Spojnice (nitne)');
  addPar('Kod spojnica izrađenih vučenjem šablonom ili na bilo koji drugi način:', 15);
  
  addTblHeader([
    { text: 'Tip detalja' },
    { text: 'Opis', span: 2 },
    { text: 'Obračunski dodatak' }
  ], 22);
  
  for (const [tip, opis, dodatak] of [
    ['A) UKRŠTANJE',
     'Križanje dviju spojnica pod 90° (npr. horizontalna siječe vertikalnu).',
     '+ 1,00 m¹'],
    ['B) UVLAČENJE',
     'Spojnica završava uz istaku, štok ili nišu (jedan kraj se uvlači).',
     '+ 0,50 m¹'],
    ['C) ZAVRŠAVANJE',
     'Spojnica se završava u vertikalnom uglu fasade.',
     '+ 0,50 m¹']
  ]) {
    const c1 = ws.getCell(r, 2);
    c1.value = tip;
    c1.font = { name: 'Arial', bold: true, size: 9, color: { argb: BORDEAUX_DARK } };
    c1.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    c1.border = allBorders;
    
    ws.mergeCells(r, 3, r, 4);
    const c2 = ws.getCell(r, 3);
    c2.value = opis;
    c2.font = { name: 'Arial', size: 9, color: { argb: DARK_GRAY } };
    c2.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c2.border = allBorders;
    
    const c3 = ws.getCell(r, 5);
    c3.value = dodatak;
    c3.font = { name: 'Arial', bold: true, size: 9, color: { argb: EXAMPLE_TEXT } };
    c3.alignment = { horizontal: 'center', vertical: 'middle' };
    c3.border = allBorders;
    
    ws.getRow(r).height = 22;
    r++;
  }
  empty(3);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 8. OBRAČUN OTVORA I ULOŽINA (ŠPALETA) — sekcija 7 PRESKOČENA
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(8, 'Obračun otvora i uložina (špaleta)');
  addPar(
    'Pravilo se primjenjuje na otvore (prozori, vrata, niše) kod kojih postoje uložine ' +
    '(špalete) do 20 cm širine:',
    24
  );
  
  addTblHeader([
    { text: 'Veličina otvora' },
    { text: 'Postupak odbijanja', span: 2 },
    { text: 'Obračun uložina' }
  ], 20);
  
  for (const [vel, odbija, ulo] of [
    ['do 3,00 m²', 'NE odbija se', 'NE obračunava se'],
    ['3,00 — 5,00 m²', 'samo višak preko 3,00 m²', 'NE obračunava se'],
    ['preko 5,00 m²', 'samo višak preko 3,00 m²', 'POSEBNO po m²']
  ]) {
    addTblRow([
      { text: vel, bold: true, center: true },
      { text: odbija, span: 2 },
      { text: ulo, center: true }
    ], 18);
  }
  empty(2);
  
  // 8.1
  addSub('8.1', 'Posebno pravilo za uložine šire od 20 cm');
  addImportant('Ako su uložine šire od 20 cm, višak preko 20 cm obračunava se posebno po m².', 15);
  addCaption('Formula:  višak (m¹) × koeficijent iz t. 4.1 (prema širini viška)');
  empty(2);
  
  // 8.2
  addSub('8.2', 'Praktični primjeri');
  
  addTblHeader([
    { text: 'Otvor' },
    { text: 'Uložina · odbija se', span: 2 },
    { text: 'Dodatni obračun' }
  ], 20);
  
  // Standard primjeri (siva)
  addTblRow([
    { text: '2,5 m²', bold: true, center: true },
    { text: '18 cm · NE odbija', span: 2 },
    { text: '—', center: true }
  ], 17);
  addTblRow([
    { text: '4,2 m²', bold: true, center: true },
    { text: '15 cm · 1,2 m² (= 4,2 − 3,0)', span: 2 },
    { text: '—', center: true }
  ], 17);
  
  // NOVI 3. red s highlightom (zelena pozadina)
  addTblRow([
    { text: '7,0 m²', bold: true, center: true, fill: EXAMPLE_BG },
    { text: '25 cm · 4,0 m² (= 7,0 − 3,0)', span: 2, fill: EXAMPLE_BG },
    { text: 'višak 5 cm  →  r.š. = 1 m¹ = 0,35 m² × duljina špalete',
      bold: true, fill: EXAMPLE_BG }
  ], 32);
  empty(2);
  
  addWarning(
    'ℹ  Napomena: višak preko 20 cm = linijski element (m¹) × koeficijent t. 4.1.  ' +
    'Za 5 cm viška  →  kategorija "do 12 cm"  →  0,35 m²/m¹ × duljina špalete.',
    28
  );
  empty(2);

  // ⭐ v135.7.502.20.233 (Ivan, 10.06.2026): 8.3 — kako se pravilo ZAPISUJE u građevinskoj knjizi
  addSub('8.3', 'Zapis u građevinskoj knjizi');
  addBullet('• do 3,00 m² — otvor se NE odbija (nema retka odbitka u raspisu).', 15);
  addBullet('• 3,00 – 5,00 m² — pun odbitak otvora + povratni redak „+3,00 m²/otvoru" (ekvivalent: odbija se samo višak preko 3,00 m²). Špalete se NE obračunavaju.', 26);
  addBullet('• preko 5,00 m² — pun odbitak + „+3,00 m²/otvoru" + ŠPALETE posebno: (2 × visina + širina) × debljina izolacije; npr. (2×2,51+2,55) × 0,18 = 1,36 m².', 26);
  empty(3);
  
  // ═══════════════════════════════════════════════════════════════════════
  // 9. SKELA (BEZ 9.5 i 9.6)
  // ═══════════════════════════════════════════════════════════════════════
  addSekcija(9, 'Izrada fasadne skele');
  
  // Sve 9.x kompaktno - svaka u jednom retku
  for (const [tag, naslov, opis] of [
    ['9.1', 'Što normativ obuhvaća',
     'Pomoćne radnje · prijenos elemenata do 40 m horizontalno · prosječno 20 m vertikalno.'],
    ['9.2', 'Horizontalno (uzdužne strane)',
     'L_objekta + 1,20 m¹ na svakom kraju  =  L_objekta + 2,40 m¹.'],
    ['9.2', 'Horizontalno (bočne strane)',
     'Čisti razmak između unutrašnjih vertikalnih stupova skele.'],
    ['9.3', 'Vertikalno',
     'Od kote terena do zadnje platforme + 1,00 m¹ (do visine zadnjeg gelendera).'],
    ['9.4', 'Dodatak za istake (balkoni)',
     'Osnovnoj dužini objekta dodaju se bočne stranice balkona.']
  ]) {
    const c1 = ws.getCell(r, 1);
    c1.value = tag;
    c1.font = { name: 'Arial', bold: true, size: 9, color: { argb: BORDEAUX_DARK } };
    c1.alignment = { horizontal: 'center', vertical: 'middle' };
    c1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    const c2 = ws.getCell(r, 2);
    c2.value = naslov;
    c2.font = { name: 'Arial', bold: true, size: 9, color: { argb: DARK_GRAY } };
    c2.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    ws.mergeCells(r, 3, r, 5);
    const c3 = ws.getCell(r, 3);
    c3.value = opis;
    c3.font = { name: 'Arial', size: 9, color: { argb: DARK_GRAY } };
    c3.alignment = { horizontal: 'left', vertical: 'middle', indent: 1, wrapText: true };
    c3.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BORDEAUX_PALE } };
    
    ws.getRow(r).height = 19;
    r++;
  }
  empty(4);
  
  // ═══════════════════════════════════════════════════════════════════════
  // FOOTER
  // ═══════════════════════════════════════════════════════════════════════
  ws.mergeCells(r, 1, r, 5);
  ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: GOLD } };   // ⭐ v542: zlatni footer divider (simetrija s naslovom)
  ws.getRow(r).height = 3;
  r++;
  
  m('Izvor: GN 421 — Tehnički uslovi obračuna fasaderskih i žbukarskih radova ' +
    '(Prosječne norme u građevinarstvu, knjiga III)', {
    font: { name: 'Arial', italic: true, size: 8.5, color: { argb: DARK_GRAY } },
    align: { horizontal: 'center', vertical: 'middle' },
    height: 14
  });
  m('ŽBUKA Čakarić d.o.o.  ·  OIB: 46540647857  ·  Zagreb', {
    font: { name: 'Arial', bold: true, size: 8.5, color: { argb: BORDEAUX_DARK } },
    align: { horizontal: 'center', vertical: 'middle' },
    height: 14
  });
  
  return ws;
}

// ─── HELPER: grupiranje otvora po sličnim dimenzijama (5cm tolerancija) ───
// Input: [{tip, sirina_m, visina_m, m2 (opt)}, ...]
// Output: [{tip, broj, sirina, visina, ukupnoM2}, ...]
function _grupiranjePoDimenziji(otvori) {
  if (!Array.isArray(otvori) || otvori.length === 0) return [];

  const TOL = 0.05; // 5cm tolerancija
  const round = (v) => Math.round((parseFloat(v) || 0) / TOL) * TOL;

  const grupe = new Map();
  for (const o of otvori) {
    const tip = o.tip || 'prozor';
    let sirina = parseFloat(o.sirina_m || 0);
    let visina = parseFloat(o.visina_m || 0);
    let m2 = parseFloat(o.m2 || o._m2 || (sirina * visina)) || 0;
    
    // ⭐ v135.7.32 (#5): NIKAD ne izbacuj otvor — građevinska knjiga MORA sadržavati sve.
    //    Ako manuali override (_manual_sirina/_manual_visina), koristi to.
    if (o._manual_override && o._manual_sirina && o._manual_visina) {
      sirina = parseFloat(o._manual_sirina) || sirina;
      visina = parseFloat(o._manual_visina) || visina;
      m2 = sirina * visina;
    }
    // Ako nedostaju dimenzije ali ima m², napravi aproksimaciju (kvadratni korijen)
    if ((sirina <= 0 || visina <= 0) && m2 > 0) {
      const dim = Math.sqrt(m2);
      if (sirina <= 0) sirina = dim;
      if (visina <= 0) visina = dim;
    }
    // Ako uopće nema dimenzija ni m² (totalno prazno), preskoči
    if (sirina <= 0 && visina <= 0 && m2 <= 0) continue;

    const key = `${tip}|${round(sirina).toFixed(2)}|${round(visina).toFixed(2)}`;

    if (grupe.has(key)) {
      const g = grupe.get(key);
      g.broj += 1;
      g.ukupnoM2 += m2;
      g._sumSirina += sirina;
      g._sumVisina += visina;
      g.sirina = g._sumSirina / g.broj;
      g.visina = g._sumVisina / g.broj;
    } else {
      grupe.set(key, {
        tip,
        broj: 1,
        sirina,
        visina,
        ukupnoM2: m2,
        _sumSirina: sirina,
        _sumVisina: visina
      });
    }
  }

  // Sortiraj: vrata prvo, pa po ukupnoM2 silazno
  const lista = Array.from(grupe.values());
  lista.sort((a, b) => {
    if (a.tip === 'vrata' && b.tip !== 'vrata') return -1;
    if (a.tip !== 'vrata' && b.tip === 'vrata') return 1;
    return b.ukupnoM2 - a.ukupnoM2;
  });

  return lista.map(g => ({
    tip: g.tip,
    broj: g.broj,
    sirina: g.sirina,
    visina: g.visina,
    ukupnoM2: g.ukupnoM2
  }));
}

app.post('/api/fasada/export-ravnine', auth, staff, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');
    const { ravnine, sitnice, slika_base64, gradiliste_naziv, gradiliste_adresa, napomena, otvori } = req.body;

    if (!Array.isArray(ravnine) && !Array.isArray(sitnice)) {
      return res.status(400).json({ error: 'Nema podataka za export' });
    }

    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Gradiliste';
    wb.created = new Date();

    const wsName = (gradiliste_naziv || 'Fasada').substring(0, 28).replace(/[^a-zA-Z0-9 _-]/g, '');
    const ws = wb.addWorksheet(wsName, {
      pageSetup: {
        paperSize: 9,           // A4
        orientation: 'portrait',
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,
        margins: {
          left: 0.5, right: 0.5,
          top: 0.5, bottom: 0.5,
          header: 0.3, footer: 0.3
        }
      }
    });

    // Kolone (A-H, ukupno 8) - po referenca file-u
    ws.columns = [
      { width: 12.0 },  // A
      { width: 18.0 },  // B
      { width: 12.0 },  // C
      { width: 13.0 },  // D
      { width: 13.0 },  // E
      { width: 14.0 },  // F
      { width: 6.0 },   // G
      { width: 16.0 }   // H — povećano s 13 na 16 da broj NETO POVRŠINA stane
    ];

    // Doaj logo u header (sve stranice)
    try {
      const logoBuffer = Buffer.from(LOGO_B64, 'base64');
      const logoImgId = wb.addImage({ buffer: logoBuffer, extension: 'png' });
      ws.headerFooter.oddHeader = '&L&G';
      // Logo u rasponu A1:B4 (gornji-lijevi kut)
      ws.addImage(logoImgId, {
        tl: { col: 0.1, row: 0.1 },
        ext: { width: 110, height: 50 },
        editAs: 'absolute'
      });
    } catch (e) {
      console.warn('[export-ravnine] logo fail:', e.message);
    }

    let row = 1;

    // ═══ R1: Naslov "OBRAČUN GRAĐEVINSKIH RADOVA" (crveno, bold, 14pt) ═══
    ws.mergeCells('C1:H1');
    const c1 = ws.getCell('C1');
    c1.value = 'OBRAČUN GRAĐEVINSKIH RADOVA';
    c1.font = { name: 'Calibri', size: 14, bold: true, color: { argb: 'FFCC0000' } };
    c1.alignment = { vertical: 'middle', horizontal: 'center' };
    ws.getRow(1).height = 22;

    // ═══ R2: Podnaslov ═══
    ws.mergeCells('C2:H2');
    const c2 = ws.getCell('C2');
    c2.value = '(Građevinska knjiga · Fasaderski radovi)';
    c2.font = { name: 'Calibri', size: 9, color: { argb: 'FF6B7280' } };
    c2.alignment = { vertical: 'middle', horizontal: 'center' };

    row = 5;

    // ═══ R5-R8: Info zaglavlje (4 reda × 2 kolone) ═══
    const danas = fmtDate(new Date());
    const procjenaId = req.body.procjena_id || ('-' + Date.now().toString().slice(-4));
    const labelStyle = { name: 'Calibri', size: 9, bold: true, color: { argb: 'FF6B7280' } };
    const valueStyle = { name: 'Calibri', size: 10, color: { argb: 'FF1A1A2E' } };

    const info = [
      ['Gradilište:', gradiliste_naziv || '-', 'Datum knjige:', danas],
      ['Adresa:', gradiliste_adresa || '-', 'Metoda:', 'Ref. ravnine + perspektiva (±2%)'],
      ['Izvođač:', 'ŽBUKA Čakarić d.o.o.', 'Voditelj:', req.user?.ime ? (req.user.ime + ' ' + (req.user.prezime || '')).trim() : 'Ivan Čakarić'],
      ['OIB:', '46540647857', 'Tip objekta:', req.body.tip_objekta || '-']
    ];

    info.forEach((line, i) => {
      const r = 5 + i;
      ws.getCell('A' + r).value = line[0];
      ws.getCell('A' + r).font = labelStyle;
      ws.getCell('A' + r).alignment = { vertical: 'middle', horizontal: 'left' };

      ws.mergeCells(`B${r}:D${r}`);
      ws.getCell('B' + r).value = line[1];
      ws.getCell('B' + r).font = valueStyle;
      ws.getCell('B' + r).alignment = { vertical: 'middle', horizontal: 'left' };

      ws.getCell('E' + r).value = line[2];
      ws.getCell('E' + r).font = labelStyle;
      ws.getCell('E' + r).alignment = { vertical: 'middle', horizontal: 'left' };

      ws.mergeCells(`F${r}:H${r}`);
      ws.getCell('F' + r).value = line[3];
      ws.getCell('F' + r).font = valueStyle;
      ws.getCell('F' + r).alignment = { vertical: 'middle', horizontal: 'left' };
    });

    row = 10;

    // ═══ R10: Naslov "NACRT FASADE..." (bijeli na tamnoplavoj) ═══
    ws.mergeCells('A10:H10');
    const c10 = ws.getCell('A10');
    c10.value = 'NACRT FASADE (originalna fotografija s referentnim ravninama)';
    c10.font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FFFFFFFF' } };
    c10.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
    c10.alignment = { vertical: 'middle', horizontal: 'center', indent: 1 };
    ws.getRow(10).height = 18;

    // ═══ R11-R26: Slika fasade (NE rastegnuta) ═══
    if (slika_base64 && slika_base64.startsWith('data:image')) {
      try {
        const m = slika_base64.match(/^data:image\/(\w+);base64,(.+)$/);
        if (m) {
          const ext = m[1] === 'jpeg' ? 'jpeg' : m[1];
          const imgBuf = Buffer.from(m[2], 'base64');
          const imgId = wb.addImage({ buffer: imgBuf, extension: ext });
          // Drzi aspect ratio - ne rastezati. Maksimalno 660px sirine, 250px visine.
          // ExcelJS positions image absolutely
          ws.addImage(imgId, {
            tl: { col: 0.1, row: 10.5 },
            ext: { width: 660, height: 320 },
            editAs: 'oneCell'
          });
        }
      } catch (e) {
        console.warn('[export-ravnine] slika fail:', e.message);
      }
    }
    // Reserve 16 redova za sliku (11-26)
    for (let i = 11; i <= 26; i++) ws.getRow(i).height = 22;

    row = 27;

    // ═══ R27: REFERENTNE MJERE (za skalu) — koristimo dimenzije ravnine R1 ═══
    if (Array.isArray(ravnine) && ravnine.length > 0) {
      ws.mergeCells('A27:H27');
      const c27 = ws.getCell('A27');
      c27.value = 'REFERENTNE MJERE (za skalu)';
      c27.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
      c27.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
      c27.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
      ws.getRow(27).height = 18;

      ['Linija', 'Mjera (m)', 'Što je izmjereno'].forEach((h, i) => {
        const c = ws.getCell(28, i + 1);
        c.value = h;
        c.font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF6B7280' } };
        c.alignment = { vertical: 'middle', horizontal: i === 1 ? 'right' : 'left' };
        c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      });

      // Uzmi prvu ravninu kao referentnu
      const r0 = ravnine[0];
      ws.getCell('A29').value = '🔴 Crvena (1.)';
      ws.getCell('B29').value = parseFloat(r0.sirina_m || 0);
      ws.getCell('B29').numFmt = '0.00';
      ws.mergeCells('C29:H29');
      ws.getCell('C29').value = 'sirina ravnine R1 "' + (r0.opis || '-') + '"';

      ws.getCell('A30').value = '🟢 Zelena (2.)';
      ws.getCell('B30').value = parseFloat(r0.visina_m || 0);
      ws.getCell('B30').numFmt = '0.00';
      ws.mergeCells('C30:H30');
      ws.getCell('C30').value = 'visina ravnine R1';

      [29, 30].forEach(rr => {
        for (let i = 1; i <= 8; i++) {
          const c = ws.getCell(rr, i);
          c.font = { name: 'Calibri', size: 10 };
          c.alignment = { vertical: 'middle', horizontal: i === 2 ? 'right' : 'left' };
        }
      });
    }

    row = 32;

    // ═══ R32: POVRŠINE FASADE (BRUTO) ═══
    ws.mergeCells('A32:H32');
    const c32 = ws.getCell('A32');
    c32.value = 'POVRŠINE FASADE (BRUTO)';
    c32.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    c32.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
    c32.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(32).height = 18;

    // Zaglavlje tablice
    ['Oznaka', 'Opis', 'Širina (m)', 'Visina (m)', 'Površina (m²)', '', '', ''].forEach((h, i) => {
      if (!h) return;
      const c = ws.getCell(33, i + 1);
      c.value = h;
      c.font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF6B7280' } };
      c.alignment = { vertical: 'middle', horizontal: i >= 2 ? 'right' : 'left' };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
    });

    let plohaRow = 34;
    let ukupnoBruto = 0;

    if (Array.isArray(ravnine)) {
      ravnine.forEach((r, idx) => {
        const sirina = parseFloat(r.sirina_m || 0);
        const visina = parseFloat(r.visina_m || 0);
        const bbox = sirina * visina;
        const plohaM2 = parseFloat(r.ploha_m2 || 0);
        const plohaDef = (Array.isArray(r.ploha_pointsPx) && r.ploha_pointsPx.length >= 3 && plohaM2 > 0);
        // ADITIVNO: bruto = bbox (š × v) + dodatna ploha (npr. zabat)
        const dodatnaM2 = plohaDef ? plohaM2 : 0;
        const bruto = bbox + dodatnaM2;
        ukupnoBruto += bruto;

        ws.getCell('A' + plohaRow).value = 'P' + (idx + 1);
        ws.getCell('B' + plohaRow).value = r.opis || ('Ravnina ' + (idx + 1));
        ws.getCell('C' + plohaRow).value = sirina;
        ws.getCell('C' + plohaRow).numFmt = '0.00';
        ws.getCell('D' + plohaRow).value = visina;
        ws.getCell('D' + plohaRow).numFmt = '0.00';
        ws.getCell('E' + plohaRow).value = bruto;
        ws.getCell('E' + plohaRow).numFmt = '0.00';

        for (let i = 1; i <= 8; i++) {
          const c = ws.getCell(plohaRow, i);
          c.font = { name: 'Calibri', size: 10 };
          c.alignment = { vertical: 'middle', horizontal: i >= 3 ? 'right' : 'left' };
          c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
        }
        plohaRow++;

        // Ako ima dodatnu plohu (zabat itd.) — dodaj poseban red s objašnjenjem
        if (plohaDef) {
          const opisP = r.ploha_opis || 'Dodatna ploha';
          ws.getCell('A' + plohaRow).value = '';
          ws.getCell('B' + plohaRow).value = '   ↳ od toga: bbox ' + bbox.toFixed(2) + ' m² + ' + opisP + ' ' + dodatnaM2.toFixed(2) + ' m²';
          ws.getCell('B' + plohaRow).font = { name: 'Calibri', size: 9, italic: true, color: { argb: 'FF10B981' } };
          ws.getCell('B' + plohaRow).alignment = { vertical: 'middle', horizontal: 'left' };
          for (let i = 1; i <= 8; i++) {
            ws.getCell(plohaRow, i).border = { bottom: { style: 'hair', color: { argb: 'FFE5E7EB' } } };
          }
          plohaRow++;
        }
      });
    }

    // UKUPNO BRUTO
    plohaRow++;
    ws.mergeCells(`A${plohaRow}:D${plohaRow}`);
    ws.getCell('A' + plohaRow).value = 'UKUPNO BRUTO (Σ ploha):';
    ws.getCell('A' + plohaRow).font = { name: 'Calibri', size: 11, bold: true };
    ws.getCell('E' + plohaRow).value = ukupnoBruto;
    ws.getCell('E' + plohaRow).numFmt = '0.00';
    ws.getCell('E' + plohaRow).font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FF7C3AED' } };
    ws.getCell('E' + plohaRow).alignment = { vertical: 'middle', horizontal: 'right' };
    ws.getCell('A' + plohaRow).alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(plohaRow).height = 22;

    row = plohaRow + 2;

    // ═══ OTVORI (odbitak od bruto) ═══
    ws.mergeCells(`A${row}:H${row}`);
    const cOtvOk = ws.getCell('A' + row);
    cOtvOk.value = 'OTVORI (odbitak od bruto)';
    cOtvOk.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cOtvOk.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD97706' } };
    cOtvOk.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(row).height = 18;
    row++;

    // Zaglavlje tablice otvora
    ['Tip', 'Komada', 'Širina (m)', 'Visina (m)', 'm²/kom', 'Ukupno (m²)', '', ''].forEach((h, i) => {
      if (!h) return;
      const c = ws.getCell(row, i + 1);
      c.value = h;
      c.font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF6B7280' } };
      c.alignment = { vertical: 'middle', horizontal: i >= 1 ? 'right' : 'left' };
      c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
    });
    row++;

    let ukupnoOtvori = 0;

    // Grupiraj otvore po dimenzijama (5cm tolerancija) preko svih ravnina
    if (Array.isArray(otvori) && otvori.length > 0) {
      const grupe = _grupiranjePoDimenziji(otvori);
      grupe.forEach(g => {
        ws.getCell('A' + row).value = g.tip === 'vrata' ? 'Ulazna vrata' : 'Prozor';
        ws.getCell('B' + row).value = g.broj;
        ws.getCell('C' + row).value = g.sirina;
        ws.getCell('C' + row).numFmt = '0.00';
        ws.getCell('D' + row).value = g.visina;
        ws.getCell('D' + row).numFmt = '0.00';
        ws.getCell('E' + row).value = g.sirina * g.visina;
        ws.getCell('E' + row).numFmt = '0.0000';
        ws.getCell('F' + row).value = g.ukupnoM2;
        ws.getCell('F' + row).numFmt = '0.0000';
        ukupnoOtvori += g.ukupnoM2;

        for (let i = 1; i <= 8; i++) {
          const c = ws.getCell(row, i);
          c.font = { name: 'Calibri', size: 10 };
          c.alignment = { vertical: 'middle', horizontal: i >= 2 ? 'right' : 'left' };
          c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
        }
        row++;
      });
    }

    // UKUPNO OTVORI
    ws.mergeCells(`A${row}:E${row}`);
    ws.getCell('A' + row).value = 'UKUPNO OTVORI:';
    ws.getCell('A' + row).font = { name: 'Calibri', size: 11, bold: true };
    ws.getCell('A' + row).alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getCell('F' + row).value = ukupnoOtvori;
    ws.getCell('F' + row).numFmt = '0.0000';
    ws.getCell('F' + row).font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFD97706' } };
    ws.getCell('F' + row).alignment = { vertical: 'middle', horizontal: 'right' };
    ws.getRow(row).height = 22;
    row += 2;

    // ═══ NETO POVRŠINA FASADE ═══
    const ukupnoNeto = Math.max(0, ukupnoBruto - ukupnoOtvori);
    ws.mergeCells(`A${row}:D${row}`);
    ws.getCell('A' + row).value = 'NETO POVRŠINA FASADE:';
    ws.getCell('A' + row).font = { name: 'Calibri', size: 13, bold: true, color: { argb: 'FF16A34A' } };
    ws.getCell('A' + row).alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getCell('E' + row).value = ukupnoNeto;
    ws.getCell('E' + row).numFmt = '0.00';
    ws.getCell('E' + row).font = { name: 'Calibri', size: 13, bold: true, color: { argb: 'FF16A34A' } };
    ws.getCell('E' + row).alignment = { vertical: 'middle', horizontal: 'right', shrinkToFit: true };
    for (let i = 1; i <= 8; i++) {
      ws.getCell(row, i).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDCFCE7' } };
      ws.getCell(row, i).border = {
        top: { style: 'medium', color: { argb: 'FF16A34A' } },
        bottom: { style: 'medium', color: { argb: 'FF16A34A' } }
      };
    }
    ws.getRow(row).height = 26;
    row += 2;

    // ═══ SITNICE (ako ima) ═══
    if (Array.isArray(sitnice) && sitnice.length > 0) {
      ws.mergeCells(`A${row}:H${row}`);
      const cSit = ws.getCell('A' + row);
      cSit.value = 'DODATNI OBRAČUNI (terasa, balkon, vijenac...)';
      cSit.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
      cSit.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF7C3AED' } };
      cSit.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
      ws.getRow(row).height = 18;
      row++;

      ['#', 'Opis', 'Količina', 'Jed.', 'Napomena', '', '', ''].forEach((h, i) => {
        if (!h) return;
        const c = ws.getCell(row, i + 1);
        c.value = h;
        c.font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF6B7280' } };
        c.alignment = { vertical: 'middle', horizontal: i === 2 ? 'right' : 'left' };
        c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
      });
      row++;

      sitnice.forEach((s, idx) => {
        ws.getCell('A' + row).value = idx + 1;
        ws.getCell('B' + row).value = s.opis || '';
        ws.getCell('C' + row).value = parseFloat(s.kolicina || 0);
        ws.getCell('C' + row).numFmt = '0.00';
        ws.getCell('D' + row).value = s.jedinica === 'm' ? "m'" : (s.jedinica || 'm²');
        ws.mergeCells(`E${row}:H${row}`);
        ws.getCell('E' + row).value = s.napomena || '';
        for (let i = 1; i <= 8; i++) {
          const c = ws.getCell(row, i);
          c.font = { name: 'Calibri', size: 10 };
          c.alignment = { vertical: 'middle', horizontal: (i === 1 || i === 3) ? 'center' : 'left', wrapText: true };
          c.border = { bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
        }
        row++;
      });
      row++;
    }

    // ═══ NAPOMENA ═══
    ws.mergeCells(`A${row}:H${row}`);
    const cNap = ws.getCell('A' + row);
    cNap.value = 'NAPOMENA';
    cNap.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cNap.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
    cNap.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(row).height = 18;
    row++;

    ws.mergeCells(`A${row}:H${row + 2}`);
    const napText = (napomena && napomena.trim()) || ('Knjiga izradjena AI Vision detekcijom + ravnine homografijom. Ukupno bruto: ' + ukupnoBruto.toFixed(2) + ' m². Otvori: ' + ukupnoOtvori.toFixed(2) + ' m². Neto: ' + ukupnoNeto.toFixed(2) + ' m².');
    const napCell = ws.getCell('A' + row);
    napCell.value = napText;
    napCell.font = { name: 'Calibri', size: 10, italic: true, color: { argb: 'FF1A1A2E' } };
    napCell.alignment = { vertical: 'top', horizontal: 'left', wrapText: true, indent: 1 };
    ws.getRow(row).height = 60;
    row += 4;

    // ═══ OVJERA OBRAČUNA ═══
    ws.mergeCells(`A${row}:H${row}`);
    const cOvj = ws.getCell('A' + row);
    cOvj.value = 'OVJERA OBRAČUNA';
    cOvj.font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cOvj.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
    cOvj.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(row).height = 18;
    row += 2;

    // Datumi
    ws.mergeCells(`A${row}:D${row}`);
    ws.getCell('A' + row).value = 'Datum: ____________________';
    ws.getCell('A' + row).font = { name: 'Calibri', size: 10 };
    ws.mergeCells(`E${row}:H${row}`);
    ws.getCell('E' + row).value = 'Datum: ____________________';
    ws.getCell('E' + row).font = { name: 'Calibri', size: 10 };
    row += 2;

    // OVJERA IZVOĐAČA / NADZOR
    ws.mergeCells(`A${row}:D${row}`);
    ws.getCell('A' + row).value = 'OVJERA IZVOĐAČA:';
    ws.getCell('A' + row).font = { name: 'Calibri', size: 10, bold: true };
    ws.mergeCells(`E${row}:H${row}`);
    ws.getCell('E' + row).value = 'OVJERA NADZORA:';
    ws.getCell('E' + row).font = { name: 'Calibri', size: 10, bold: true };
    row += 4;

    ws.mergeCells(`A${row}:D${row}`);
    ws.getCell('A' + row).value = '___________________________';
    ws.getCell('A' + row).font = { name: 'Calibri', size: 10 };
    ws.mergeCells(`E${row}:H${row}`);
    ws.getCell('E' + row).value = '___________________________';
    ws.getCell('E' + row).font = { name: 'Calibri', size: 10 };

    // ═══ Generiraj fajl ═══
    const filename = `Fasada_${(gradiliste_naziv || 'knjiga').replace(/[^a-zA-Z0-9_-]/g, '_')}_${new Date().toISOString().split('T')[0]}.xlsx`;
    const buffer = await _xlsxFixBuffer(await wb.xlsx.writeBuffer());   // ⭐ v546: sanacija OOXML quirkova (rFont-first + spPr ext) — ima slike

    // Spremi kopiju na QNAP - Fasade-AI/{naziv_gradilista}/{filename}
    if (process.env.QNAP_WEBDAV_URL && req.body.gradiliste_id) {
      try {
        // Uvijek dohvati naziv iz DB-a (klijentski može ne biti dostupan)
        let gradNazivDB = req.body.gradiliste_naziv;
        if (!gradNazivDB) {
          const gr = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [req.body.gradiliste_id]);
          gradNazivDB = gr.rows[0]?.naziv;
        }
        if (!gradNazivDB) {
          console.warn('[export-ravnine] Gradilište ' + req.body.gradiliste_id + ' nema naziv — QNAP upload preskočen');
        } else {
          const folder = fasadaQnapFolder(gradNazivDB);
          const qnapFile = `${folder}/${filename}`;
          await qnapUploadExcel(Buffer.from(buffer), qnapFile);
        }
      } catch (e) {
        console.warn('[export-ravnine] QNAP save failed:', e.message);
      }
    }

    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.end(buffer);

  } catch (err) {
    console.error('[fasada/export-ravnine] error:', err);
    return res.status(500).json({ error: err.message || 'Greska export' });
  }
});

// GET /api/fasada/export/excel/gradiliste/:id — sve procjene jednog gradilišta
// GET /api/fasada/export/all — SVI procjene fasade (sva gradilista) u jedan Excel za backup


// ─── GET /api/fasada/export/all (původně oko L12778) ───
app.get('/api/fasada/export/all', auth, staff, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');
    const procR = await pool.query(`
      SELECT f.*, rad.ime || ' ' || rad.prezime AS kreirao,
             g.naziv AS grad_naziv, g.adresa AS grad_adresa, g.aktivan AS grad_aktivan
      FROM fasade_procjene f
      LEFT JOIN radnici rad ON rad.id = f.kreirao_id
      JOIN gradilista g ON g.id = f.gradiliste_id
      ORDER BY g.aktivan DESC, g.naziv ASC, f.created_at DESC
    `);

    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Čakarić d.o.o.';
    wb.created = new Date();

    const ws = wb.addWorksheet('Sve knjige fasada');

    // Headers
    ws.columns = [
      { header: 'Gradilište', key: 'grad', width: 28 },
      { header: 'Status', key: 'status', width: 10 },
      { header: 'Datum', key: 'datum', width: 12 },
      { header: 'Bruto m²', key: 'bruto', width: 11 },
      { header: 'Pož. bar. m²', key: 'barijere', width: 12 },
      { header: 'Ukupna m²', key: 'ukupna', width: 11 },
      { header: 'Otvori m²', key: 'otvori', width: 11 },
      { header: 'Neto m²', key: 'neto', width: 11 },
      { header: 'Razl. debljine', key: 'razlicite', width: 13 },
      { header: 'AI conf', key: 'conf', width: 9 },
      { header: 'Korekcija', key: 'kor', width: 11 },
      { header: 'Tip objekta', key: 'tip', width: 16 },
      { header: 'Kreirao', key: 'kreirao', width: 18 },
      { header: 'Adresa', key: 'adresa', width: 30 },
    ];

    ws.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } };
    ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1f2937' } };
    ws.getRow(1).height = 24;
    ws.getRow(1).alignment = { vertical: 'middle' };

    procR.rows.forEach(f => {
      const datum = fmtDate(new Date(f.created_at));
      let otvoriM2 = 0;
      try {
        const otv = typeof f.otvori_json === 'string' ? JSON.parse(f.otvori_json) : (f.otvori_json || []);
        otvoriM2 = (otv || []).reduce((s, o) => s + parseFloat(o.ukupno_m2 || 0), 0);
      } catch(e) {}

      ws.addRow({
        grad: safeExcelCell(f.grad_naziv || '?'),
        status: f.grad_aktivan ? 'Aktivno' : 'Arhivirano',
        datum: datum,
        bruto: parseFloat(f.bruto_fasada_m2 || f.ukupna_fasada_m2 || 0),
        barijere: parseFloat(f.pozarne_barijere_m2 || 0),
        ukupna: parseFloat(f.ukupna_fasada_m2 || 0),
        otvori: parseFloat(otvoriM2.toFixed(2)),
        neto: parseFloat(f.neto_fasada_m2 || 0),
        razlicite: f.razlicite_debljine ? 'DA' : '',
        conf: parseInt(f.ai_confidence || 0) + '%',
        kor: f.korekcija_ratio ? parseFloat(f.korekcija_ratio).toFixed(3) : '',
        tip: safeExcelCell(f.tip_objekta || ''),
        kreirao: safeExcelCell(f.kreirao || ''),
        adresa: safeExcelCell(f.grad_adresa || '')
      });
    });

    // Format number columns
    ['bruto','barijere','ukupna','otvori','neto'].forEach(key => {
      ws.getColumn(key).numFmt = '0.00';
    });

    // Status fill (arhivirano = sivi)
    ws.eachRow((row, rowNum) => {
      if (rowNum === 1) return;
      if (row.getCell('status').value === 'Arhivirano') {
        row.eachCell(c => {
          c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF3F4F6' } };
          c.font = { color: { argb: 'FF6b7280' } };
        });
      }
    });

    // Auto filter
    ws.autoFilter = { from: 'A1', to: 'N1' };
    ws.views = [{ state: 'frozen', ySplit: 1 }];

    const buf = await wb.xlsx.writeBuffer();
    // Bez datuma - idempotent (svaki backup overwrite-a)
    const fname = `Sve_fasade.xlsx`;
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', `attachment; filename="${fname}"`);
    res.send(Buffer.from(buf));

    // QNAP upload - idempotent
    setImmediate(() => qnapUploadExcel(Buffer.from(buf), `Fasade-AI/${fname}`));
  } catch(e) {
    console.error('[Fasada export all]', e);
    res.status(500).json({ error: e.message });
  }
});



// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v124: PDF PREVIEW — HTML A4 print-ready stranica za brzu procjenu
// GET /api/fasada/preview/procjena/:id?token=...
// Klijent otvori u novom tabu, koristi browser "Ispiši → Spremi kao PDF"
// (token kroz query za <a target="_blank"> jer browser ne propušta auth headere)
// ═══════════════════════════════════════════════════════════════════════════
app.get('/api/fasada/preview/knjiga/:id', async (req, res) => {
  try {
    // Auth kroz query token (jer <a target="_blank"> ne nosi headere)
    let user = null;
    const _hdrTok = req.headers.authorization?.replace('Bearer ', '');
    if (_hdrTok) { try { user = jwt.verify(_hdrTok, JWT_SECRET); } catch(_) {} }
    if (!user) user = await _userFromMediaToken(req.query.mt || req.query.token);  // ⭐ v219: URL nosi media token, ne JWT
    if (!user) return res.status(401).send('<h1>401 — Token nevažeći</h1>');
    
    const procjenaId = parseInt(req.params.id);
    if (!Number.isFinite(procjenaId)) return res.status(400).send('<h1>400 — Nevažeći ID</h1>');
    
    const procR = await pool.query(`
      SELECT f.*, rad.ime || ' ' || rad.prezime AS kreirao,
             g.naziv AS grad_naziv, g.adresa AS grad_adresa
      FROM fasade_procjene f
      LEFT JOIN radnici rad ON rad.id = f.kreirao_id
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1
    `, [procjenaId]);
    
    if (!procR.rows.length) return res.status(404).send('<h1>404 — Knjiga ne postoji</h1>');
    
    const f = procR.rows[0];
    const datum = fmtDate(new Date(f.created_at));
    const datumKreiran = fmtDate(f.created_at, { time: true });
    
    // Otvori list (ako ima)
    let otvori = f.otvori_json;
    if (typeof otvori === 'string') { try { otvori = JSON.parse(otvori); } catch(_) { otvori = []; } }
    if (!Array.isArray(otvori)) otvori = [];
    
    // ⭐ v135.7: Anotirana (HATCHIRANA) slika — prioritet pred originalnom
    //    Bug prije: PDF iz Ukupno (klik 📄) je pokazivao GOLU sliku bez hatch-a
    //    Razlog: server je čitao samo f.slika_base64/slika_qnap_path (original)
    //    Fix: za multi (homografija_multi) iteriramo dimenzije_fasade.procelja[],
    //         za single uzmemo f.ai_anotirana_slika; fallback na originalu samo ako anotirane nema
    //    QNAP slike fetchamo server-side (kao data URL) jer <img src=qnap-proxy> bi vraćao JSON
    let slikeProcelja = [];   // niz {oznaka, src} za multi prikaz
    let slikaSrc = '';        // prvi/glavni za prikaz (legacy fallback)
    
    const isMulti = f.koncept === 'homografija_multi';
    
    // Helper za odabir najbolje slike (prioritet: anotirana > original) i pretvorbu u data URL
    const _odabirSlike = async (anotiranaB64, anotiranaQnapPath, hatchQnapPath, originalB64, originalQnapPath) => {
      // 1. Anotirana base64 (najbrže)
      if (anotiranaB64 && String(anotiranaB64).length > 100) {
        return String(anotiranaB64).startsWith('data:') 
          ? anotiranaB64 
          : `data:image/jpeg;base64,${anotiranaB64}`;
      }
      // 2. Anotirana QNAP — fetch server-side
      const anotPath = anotiranaQnapPath || hatchQnapPath;
      if (anotPath && typeof _qnapFetchSlikaAsDataUrl === 'function') {
        try {
          const url = await _qnapFetchSlikaAsDataUrl(anotPath);
          if (url) return url;
        } catch(e) { console.warn('[preview] QNAP anotirana fetch fail:', e.message); }
      }
      // 3. Original base64
      if (originalB64 && String(originalB64).length > 100) {
        return String(originalB64).startsWith('data:') 
          ? originalB64 
          : `data:image/jpeg;base64,${originalB64}`;
      }
      // 4. Original QNAP
      if (originalQnapPath && typeof _qnapFetchSlikaAsDataUrl === 'function') {
        try {
          const url = await _qnapFetchSlikaAsDataUrl(originalQnapPath);
          if (url) return url;
        } catch(e) { console.warn('[preview] QNAP original fetch fail:', e.message); }
      }
      return '';
    };
    
    if (isMulti) {
      // Multi pročelje: dimenzije_fasade.procelja[] sadrži po-pročelje slike
      let dim = f.dimenzije_fasade;
      if (typeof dim === 'string') { try { dim = JSON.parse(dim); } catch(_) { dim = null; } }
      const procelja = (dim && Array.isArray(dim.procelja)) ? dim.procelja : [];
      
      // ⭐ v135.7.3 DIAGNOSTIC: log koja polja u DB-u imaju anotiranu sliku
      //    Ivan kaže da i dalje vidi original (bez hatcha) — provjerava se da li
      //    ima ikakva referenca u DB ili ne (Memsur možda nije spremio anotiranu)
      console.log(`[PDF preview] proc#${procjenaId} multi · ${procelja.length} nacrta:`);
      procelja.forEach((p, i) => {
        console.log(`  [${i}] oznaka="${p.oznaka || '?'}" · slika_anotirana=${!!p.slika_anotirana} (${p.slika_anotirana ? String(p.slika_anotirana).length : 0} chars) · slika_anotirana_qnap_path=${p.slika_anotirana_qnap_path || 'NULL'} · slika_hatch_qnap_path=${p.slika_hatch_qnap_path || 'NULL'} · slika_base64=${!!p.slika_base64} · slika_qnap_path=${p.slika_qnap_path || 'NULL'}`);
      });
      
      // Paralelno fetch-amo sve slike (najbrže)
      const fetched = await Promise.all(procelja.map(async (p, i) => {
        const oznaka = p.oznaka || 'Nacrt';
        const src = await _odabirSlike(
          p.slika_anotirana, p.slika_anotirana_qnap_path, p.slika_hatch_qnap_path,
          p.slika_base64, p.slika_qnap_path
        );
        const tip = p.slika_anotirana ? 'anotirana_b64' 
                  : p.slika_anotirana_qnap_path ? 'anotirana_qnap'
                  : p.slika_hatch_qnap_path ? 'hatch_qnap'
                  : p.slika_base64 ? 'original_b64'
                  : p.slika_qnap_path ? 'original_qnap'
                  : 'NEMA';
        console.log(`  [${i}] ${oznaka} → ${src ? `LOADED (${tip}, ${src.length} chars)` : 'EMPTY'}`);
        return src ? { oznaka, src } : null;
      }));
      slikeProcelja = fetched.filter(Boolean);
      // Glavna (legacy) — prva pročelje slika
      if (slikeProcelja.length > 0) slikaSrc = slikeProcelja[0].src;
    } else {
      // Single brza/detaljna: prioritet anotirana > original
      console.log(`[PDF preview] proc#${procjenaId} single · ai_anotirana_slika=${!!f.ai_anotirana_slika} (${f.ai_anotirana_slika ? String(f.ai_anotirana_slika).length : 0} chars) · slika_base64=${!!f.slika_base64} · slika_qnap_path=${f.slika_qnap_path || 'NULL'}`);
      slikaSrc = await _odabirSlike(
        f.ai_anotirana_slika, null, null,
        f.slika_base64, f.slika_qnap_path
      );
      // Fallback na klijent proxy ako server fetch fail
      if (!slikaSrc && f.slika_qnap_path) {
        slikaSrc = `/api/fasada/${procjenaId}/slika?token=${encodeURIComponent(token)}`;
      }
    }
    
    const escapeHtml = (s) => String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const fmtBr = (n) => n != null ? Number(n).toLocaleString('hr-HR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '–';
    
    const tipLabel = f.tip_procjene === 'brza' ? 'Brza AI knjiga' : 'Detaljna knjiga';
    const pouzdanost = f.ai_confidence ? Math.round(f.ai_confidence * 100) : null;
    
    const html = `<!DOCTYPE html>
<html lang="hr">
<head>
  <meta charset="UTF-8">
  <title>Knjiga #${procjenaId} — ${escapeHtml(f.grad_naziv || f.naziv_objekta || 'Bez gradilišta')}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    @page { size: A4 portrait; margin: 12mm 14mm; }
    @media print {
      .no-print { display: none !important; }
      body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    }
    * { box-sizing: border-box; }
    body {
      font-family: -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      color: #1a1a2e;
      line-height: 1.5;
      max-width: 800px;
      margin: 0 auto;
      padding: 20px;
      background: #fff;
    }
    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-bottom: 3px solid #cc0000;
      padding-bottom: 14px;
      margin-bottom: 18px;
    }
    .firma { font-weight: 800; font-size: 18px; color: #cc0000; }
    .firma-sub { font-size: 11px; color: #6b7280; margin-top: 2px; }
    .doc-title {
      text-align: right;
      font-weight: 800;
      font-size: 16px;
      color: #cc0000;
      text-transform: uppercase;
    }
    .doc-sub { font-size: 10px; color: #6b7280; font-style: italic; margin-top: 2px; }
    
    h2 {
      font-size: 14px;
      color: #1e3a8a;
      border-left: 4px solid #1e40af;
      padding-left: 10px;
      margin: 18px 0 10px;
    }
    .info-table { width: 100%; border-collapse: collapse; margin-bottom: 14px; font-size: 11.5px; }
    .info-table td { padding: 4px 8px; vertical-align: top; }
    .info-table td:first-child { font-weight: 700; color: #6b7280; width: 30%; }
    
    .slika-wrap {
      margin: 12px 0;
      text-align: center;
      page-break-inside: avoid;
    }
    .slika-wrap img {
      max-width: 100%;
      max-height: 350px;
      border: 1px solid #e5e7eb;
      border-radius: 6px;
    }
    
    /* ⭐ v135.7: Multi pročelje galerija anotiranih (hatch) slika */
    .slika-galerija {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 10px;
      margin: 12px 0;
    }
    .slika-procelje {
      page-break-inside: avoid;
      border: 1px solid #e5e7eb;
      border-radius: 6px;
      padding: 6px;
      background: #fafafa;
    }
    .slika-procelje .procelje-oznaka {
      font-size: 11px;
      font-weight: 700;
      color: #1e40af;
      margin-bottom: 4px;
      text-align: center;
      letter-spacing: 0.3px;
    }
    .slika-procelje img {
      width: 100%;
      max-height: 220px;
      object-fit: contain;
      border-radius: 4px;
    }
    
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 8px;
      margin: 14px 0;
    }
    .stat-card {
      background: #f8f9fa;
      border: 1px solid #e5e7eb;
      border-radius: 6px;
      padding: 10px;
      text-align: center;
    }
    .stat-card .label {
      font-size: 9px;
      color: #6b7280;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .stat-card .value {
      font-size: 18px;
      font-weight: 800;
      color: #1a1a2e;
      margin-top: 2px;
    }
    .stat-card.highlight {
      background: #dcfce7;
      border-color: #22c55e;
    }
    .stat-card.highlight .value { color: #15803d; }
    
    table.dt {
      width: 100%;
      border-collapse: collapse;
      margin: 8px 0;
      font-size: 11px;
    }
    table.dt th {
      background: #1e3a8a;
      color: #fff;
      padding: 6px 8px;
      text-align: left;
      font-weight: 700;
    }
    table.dt td {
      padding: 5px 8px;
      border-bottom: 1px solid #e5e7eb;
    }
    table.dt tr:nth-child(even) td { background: #f9fafb; }
    
    .footer {
      margin-top: 24px;
      padding-top: 12px;
      border-top: 1px solid #e5e7eb;
      font-size: 10px;
      color: #6b7280;
      display: flex;
      justify-content: space-between;
    }
    
    .print-btn {
      position: fixed;
      top: 16px;
      right: 16px;
      background: linear-gradient(135deg, #16a34a, #15803d);
      color: #fff;
      border: none;
      padding: 10px 18px;
      border-radius: 8px;
      font-size: 14px;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
      z-index: 9999;
    }
    .print-btn:hover { background: linear-gradient(135deg, #15803d, #166534); }
    
    .badge {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
    }
    .badge-purple { background: #ede9fe; color: #6d28d9; }
    .badge-blue { background: #dbeafe; color: #1e40af; }
    .badge-green { background: #dcfce7; color: #15803d; }
    .badge-red { background: #fee2e2; color: #991b1b; }
    .badge-yellow { background: #fef3c7; color: #92400e; }
  </style>
</head>
<body>
  <button class="print-btn no-print" onclick="window.print()">🖨️ Ispiši / Spremi kao PDF</button>
  
  <div class="header">
    <div>
      <div class="firma">ŽBUKA Čakarić d.o.o.</div>
      <div class="firma-sub">Plastering · Facade construction · Zagreb</div>
    </div>
    <div>
      <div class="doc-title">${tipLabel}</div>
      <div class="doc-sub">Knjiga #${procjenaId} · ${datum}</div>
    </div>
  </div>
  
  <h2>📋 Osnovni podaci</h2>
  <table class="info-table">
    <tr><td>Gradilište:</td><td>${escapeHtml(f.grad_naziv || '(bez gradilišta — vanjska knjiga)')}</td></tr>
    ${f.grad_adresa ? `<tr><td>Adresa:</td><td>${escapeHtml(f.grad_adresa)}</td></tr>` : ''}
    ${f.naziv_objekta ? `<tr><td>Objekt:</td><td>${escapeHtml(f.naziv_objekta)}</td></tr>` : ''}
    ${f.tip_objekta ? `<tr><td>Tip objekta:</td><td>${escapeHtml(f.tip_objekta)}</td></tr>` : ''}
    <tr><td>Tip knjige:</td><td><span class="badge ${f.tip_procjene === 'brza' ? 'badge-purple' : 'badge-blue'}">${tipLabel}</span></td></tr>
    ${pouzdanost != null ? `<tr><td>AI pouzdanost:</td><td><span class="badge ${pouzdanost >= 70 ? 'badge-green' : (pouzdanost >= 50 ? 'badge-yellow' : 'badge-red')}">${pouzdanost}%</span></td></tr>` : ''}
    <tr><td>Datum:</td><td>${datumKreiran}</td></tr>
    ${f.kreirao ? `<tr><td>Kreirao:</td><td>${escapeHtml(f.kreirao)}</td></tr>` : ''}
    ${f.referentna_mjera_m ? `<tr><td>Referenca:</td><td>${escapeHtml(f.referentni_opis || '')} ${f.referentna_mjera_m} m</td></tr>` : ''}
  </table>
  
  ${slikeProcelja.length > 1 ? `
    <!-- Multi nacrt: galerija anotiranih slika po nacrtu -->
    <h2>🖼️ Anotirane slike nacrta (${slikeProcelja.length})</h2>
    <div class="slika-galerija">
      ${slikeProcelja.map(p => `
        <div class="slika-procelje">
          <div class="procelje-oznaka">${escapeHtml(p.oznaka)}</div>
          <img src="${p.src}" alt="${escapeHtml(p.oznaka)}" onerror="this.style.display='none'">
        </div>
      `).join('')}
    </div>
  ` : (slikaSrc ? `
    <div class="slika-wrap">
      <img src="${slikaSrc}" alt="Nacrt" onerror="this.style.display='none'">
    </div>
  ` : '')}
  
  <h2>📊 Površine</h2>
  <div class="stats-grid">
    <div class="stat-card">
      <div class="label">Bruto</div>
      <div class="value">${fmtBr(f.bruto_fasada_m2 || f.ukupna_fasada_m2)} m²</div>
    </div>
    <div class="stat-card highlight">
      <div class="label">Neto</div>
      <div class="value">${fmtBr(f.neto_fasada_m2)} m²</div>
    </div>
    <div class="stat-card">
      <div class="label">Otvori</div>
      <div class="value">${otvori.length}</div>
    </div>
  </div>
  
  ${otvori.length > 0 ? `
    <h2>🪟 Otvori (${otvori.length})</h2>
    <table class="dt">
      <thead>
        <tr>
          <th>#</th>
          <th>Tip</th>
          <th>Opis</th>
          <th>Š × V</th>
          <th>m²</th>
          <th>Kom</th>
        </tr>
      </thead>
      <tbody>
        ${otvori.map((o, i) => {
          const sirina = parseFloat(o._manual_sirina || o.sirina_m || 0);
          const visina = parseFloat(o._manual_visina || o.visina_m || 0);
          const m2 = parseFloat(o._m2 || o.m2 || (sirina * visina) || 0);
          const kol = parseInt(o.kolicina || o.kom || 1);
          return `<tr>
            <td>${i+1}</td>
            <td>${escapeHtml(o.tip || '–')}</td>
            <td>${escapeHtml(o.opis || '')}</td>
            <td>${sirina ? fmtBr(sirina) : '?'} × ${visina ? fmtBr(visina) : '?'} m</td>
            <td>${fmtBr(m2)}</td>
            <td>${kol}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  ` : ''}
  
  ${f.napomena ? `
    <h2>📝 Napomena</h2>
    <div style="background:#fef3c7;border:1px solid #fbbf24;padding:10px 12px;border-radius:6px;font-size:11.5px;color:#78350f;line-height:1.55">
      ${escapeHtml(f.napomena)}
    </div>
  ` : ''}
  
  <div class="footer">
    <div>ŽBUKA Čakarić d.o.o. · Zagreb</div>
    <div>Generirano: ${new Date().toLocaleString('hr-HR')}</div>
  </div>
  
  <script>
    // Auto-trigger print dialog ako je query auto=1 (npr. iz brza pregleda direktno)
    if (new URLSearchParams(location.search).get('auto') === '1') {
      setTimeout(() => window.print(), 500);
    }
  <\/script>
</body>
</html>`;
    
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  } catch(e) {
    console.error('[fasada/preview]', e);
    res.status(500).send(`<h1>500 — ${e.message}</h1>`);
  }
});

// ⭐ v135.7.34 (#3): POST /api/fasada/procjena/:id/pdf-qnap
//    Generira jednostavan PDF rezime procjene (pdfkit) + upload na QNAP
//    Path: Fasade-AI/<naziv>/PDF/Procjena_<id>_<datum>.pdf
//    DB: ažurira pdf_qnap_path
//    Pri DELETE procjene → QNAP folder cleanup (već postoji) automatski briše PDF.
app.post('/api/fasada/knjiga/:id/pdf-qnap', auth, staff, async (req, res) => {
  try {
    const procjenaId = parseInt(req.params.id);
    if (!Number.isFinite(procjenaId)) return res.status(400).json({ error: 'Nevažeći ID' });
    
    const procR = await pool.query(`
      SELECT f.*, g.naziv AS grad_naziv, g.adresa AS grad_adresa
      FROM fasade_procjene f
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1
    `, [procjenaId]);
    if (!procR.rows.length) return res.status(404).json({ error: 'Knjiga ne postoji' });
    
    const f = procR.rows[0];
    const PDFDocument = require('pdfkit');
    
    // Helper: dohvati sliku kao Buffer (anotirana > original)
    const _slikaBuffer = async () => {
      // Priorita 1: ai_anotirana_slika (base64)
      if (f.ai_anotirana_slika && String(f.ai_anotirana_slika).length > 100) {
        const b64 = String(f.ai_anotirana_slika).replace(/^data:image\/\w+;base64,/, '');
        try { return Buffer.from(b64, 'base64'); } catch(_) {}
      }
      // Priorita 2: slika_base64
      if (f.slika_base64 && String(f.slika_base64).length > 100) {
        const b64 = String(f.slika_base64).replace(/^data:image\/\w+;base64,/, '');
        try { return Buffer.from(b64, 'base64'); } catch(_) {}
      }
      // Priorita 3: QNAP path
      if (f.slika_qnap_path && typeof _qnapFetchSlikaAsDataUrl === 'function') {
        try {
          const dataUrl = await _qnapFetchSlikaAsDataUrl(f.slika_qnap_path);
          if (dataUrl) {
            const b64 = String(dataUrl).replace(/^data:image\/\w+;base64,/, '');
            return Buffer.from(b64, 'base64');
          }
        } catch(_) {}
      }
      return null;
    };
    
    const imgBuf = await _slikaBuffer();
    
    // Generiraj PDF u memory buffer
    const chunks = [];
    const doc = new PDFDocument({ size: 'A4', margin: 30 });
    doc.on('data', chunk => chunks.push(chunk));
    
    const pdfDone = new Promise((resolve, reject) => {
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      doc.on('error', reject);
    });
    
    // Header
    doc.fontSize(18).fillColor('#1f2937').font('Helvetica-Bold').text('FASADA AI — KNJIGA', { align: 'center' });
    doc.fontSize(11).fillColor('#6b7280').font('Helvetica').text(`#${procjenaId} · ${f.tip_objekta || 'Brza knjiga'}`, { align: 'center' });
    doc.moveDown(0.5);
    
    // Gradilište + datum
    doc.fontSize(10).fillColor('#000');
    doc.text(`Gradilište: ${f.grad_naziv || '—'}`);
    if (f.grad_adresa) doc.text(`Adresa: ${f.grad_adresa}`);
    doc.text(`Datum: ${fmtDate(new Date(f.created_at))}`);
    doc.moveDown(0.5);
    
    // Slika (ako ima) - prilagodi širini
    if (imgBuf) {
      try {
        const startY = doc.y;
        doc.image(imgBuf, { fit: [535, 350], align: 'center' });
        // Ako se ne kreira space, pomakni dolje (pdfkit bug recovery)
        if (doc.y < startY + 50) doc.y = startY + 350;
        doc.moveDown(0.5);
      } catch(e) {
        doc.fontSize(9).fillColor('#dc2626').text(`⚠ Slika nije dostupna: ${e.message}`);
        doc.moveDown(0.5);
      }
    }
    
    // Sažetak (bruto/neto/otvori)
    doc.fontSize(13).fillColor('#1f2937').font('Helvetica-Bold').text('Rezime');
    doc.moveDown(0.2);
    doc.fontSize(11).font('Helvetica').fillColor('#000');
    
    const bruto = parseFloat(f.bruto_fasada_m2 || 0);
    const neto = parseFloat(f.neto_fasada_m2 || 0);
    const otvoriSum = parseFloat(f.otvori_ukupno_m2 || 0);
    
    doc.text(`Bruto: ${bruto.toFixed(2)} m²`);
    doc.text(`Otvori: -${otvoriSum.toFixed(2)} m²`);
    doc.fillColor('#15803d').font('Helvetica-Bold').text(`NETO: ${neto.toFixed(2)} m²`);
    doc.font('Helvetica').fillColor('#000');
    doc.moveDown(0.5);
    
    // Otvori detalji (ako ima)
    let otvori = f.otvori_json;
    if (typeof otvori === 'string') { try { otvori = JSON.parse(otvori); } catch(_) { otvori = []; } }
    if (Array.isArray(otvori) && otvori.length > 0) {
      doc.fontSize(11).font('Helvetica-Bold').text(`Otvori (${otvori.length}):`);
      doc.fontSize(9).font('Helvetica');
      otvori.slice(0, 20).forEach((o, i) => {
        const sirina = parseFloat(o._manual_sirina || o.sirina_m || 0);
        const visina = parseFloat(o._manual_visina || o.visina_m || 0);
        const m2 = parseFloat(o._m2 || o.m2 || (sirina * visina) || 0);
        const kol = parseInt(o.kolicina || 1) || 1;
        doc.text(`${i+1}. ${o.tip || 'prozor'} · ${sirina.toFixed(2)}×${visina.toFixed(2)} m = ${m2.toFixed(2)} m²${kol > 1 ? ' × ' + kol : ''}`);
      });
      if (otvori.length > 20) doc.text(`... i još ${otvori.length - 20}`);
    }
    
    // Footer
    doc.moveDown(1);
    doc.fontSize(8).fillColor('#6b7280').text(`Generirano: ${new Date().toLocaleString('hr-HR')} · ŽBUKA Čakarić d.o.o.`, { align: 'center' });
    
    doc.end();
    const pdfBuffer = await pdfDone;
    
    // Upload na QNAP
    const datum = _ymd(new Date(f.created_at));
    const safeNaziv = (f.grad_naziv || 'gradiliste').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
    const remotePath = `Fasade-AI/${safeNaziv}/PDF/Procjena_${procjenaId}_${datum}.pdf`;
    
    if (typeof qnapUploadExcel === 'function') {
      // qnapUploadExcel detects .pdf extension i postavlja Content-Type
      await qnapUploadExcel(pdfBuffer, remotePath);
    }
    
    // DB update
    await pool.query('UPDATE fasade_procjene SET pdf_qnap_path=$1 WHERE id=$2', [remotePath, procjenaId]);
    
    console.log(`[PDF QNAP] Knjiga #${procjenaId} → ${remotePath} (${(pdfBuffer.length/1024).toFixed(0)}KB)`);
    res.json({ ok: true, qnap_path: remotePath, size_kb: Math.round(pdfBuffer.length / 1024) });
  } catch(e) {
    console.error('[fasada/pdf-qnap]', e);
    res.status(500).json({ error: e.message });
  }
});

// GET /api/fasada/export/excel/procjena/:id — jedna procjena (jedan A4 list)


// ─── GET /api/fasada/export/excel/procjena/:id (původně oko L12958) ───
app.get('/api/fasada/export/excel/knjiga/:id', auth, staff, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');

    const procR = await pool.query(`
      SELECT f.*, rad.ime || ' ' || rad.prezime AS kreirao,
             g.naziv AS grad_naziv, g.adresa AS grad_adresa
      FROM fasade_procjene f
      LEFT JOIN radnici rad ON rad.id = f.kreirao_id
      JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1
    `, [req.params.id]);

    if (!procR.rows.length) return res.status(404).json({ error: 'Knjiga ne postoji' });

    const f = procR.rows[0];

    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Čakarić d.o.o.';
    wb.created = new Date();

    const sheetName = (f.grad_naziv || 'Knjiga').slice(0, 30);
    const ws = wb.addWorksheet(sheetName, {
      pageSetup: {
        paperSize: 9,
        orientation: 'portrait',
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,
        margins: { left: 0.4, right: 0.4, top: 0.4, bottom: 0.4, header: 0.2, footer: 0.2 }
      }
    });

    ws.columns = [
      { width: 13 }, { width: 22 }, { width: 11 }, { width: 11 },
      { width: 13 }, { width: 11 }, { width: 13 }, { width: 9 },
    ];

    await generirajExcelProcjenu(ws, f, 1, f.grad_naziv, f.grad_adresa);
    
    // FAZA A: dodatni sheet-ovi (otvori, barijere, debljine, sitnice) ako postoje
    if (f.koncept === 'ravnine') {
      try { await generirajSheetOtvori(wb, f, f.grad_naziv, f.grad_adresa); } catch(e) { console.warn('[Sheet otvori]', e.message); }
      try { await generirajSheetBarijere(wb, f, f.grad_naziv, f.grad_adresa); } catch(e) { console.warn('[Sheet barijere]', e.message); }
      try { await generirajSheetDebljine(wb, f, f.grad_naziv, f.grad_adresa); } catch(e) { console.warn('[Sheet debljine]', e.message); }
      try { await generirajSheetSitnice(wb, f, f.grad_naziv, f.grad_adresa); } catch(e) { console.warn('[Sheet sitnice]', e.message); }
    }
    
    // ⭐ v127: Normativi sheet (GN 421) — ZADNJI list u svakom exportu građ. knjige
    try { await generirajSheetNormativi(wb, { naziv: f.grad_naziv, adresa: f.grad_adresa }); } catch(e) { console.warn('[Sheet Normativi]', e.message); }

    const buffer = await wb.xlsx.writeBuffer();

    const safeName = (f.grad_naziv || 'knjiga').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
    // Bez datuma u nazivu - isti naziv = overwrite (idempotent)
    const fname = `Obracun_fasada_${safeName}_proc${f.id}.xlsx`;
    const fnameAscii = safeAsciiFilename(fname);

    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', `attachment; filename="${fnameAscii}"; filename*=UTF-8''${encodeURIComponent(fname)}`);
    res.send(Buffer.from(buffer));

    // ⭐ QNAP upload + clear dirty flag (lazy regen)
    //    Brze procjene idu u Brze-procjene/ subfolder
    let folder;
    if (f.tip_procjene === 'brza') {
      if (f.gradiliste_id) {
        folder = `${fasadaQnapFolder(f.grad_naziv || 'gradiliste')}/Brze-procjene`;
      } else {
        folder = fasadaQnapFolder('_BrzeProcjene/' + (f.naziv_objekta || 'objekt').replace(/[/\\:*?"<>|]/g, '_').slice(0, 80));
      }
    } else {
      folder = fasadaQnapFolder(f.grad_naziv || 'gradiliste');
    }
    setImmediate(async () => {
      try {
        const qnapPath = `${folder}/${fname}`;
        await qnapUploadExcel(Buffer.from(buffer), qnapPath);
        // Clear dirty — Excel je sad svjež
        await pool.query(`UPDATE fasade_procjene SET excel_dirty = false WHERE id = $1`, [f.id]);
        
        // ⭐ AUDIT #58: Snimi u history za verzioniranje
        try {
          // Dohvati ime kreatora (ako je req.user dostupan u closure-u)
          const kreaIme = req.user?.ime ? `${req.user.ime} ${req.user.prezime || ''}`.trim() 
                                         : (f.kreirao || 'sustav');
          await pool.query(`
            INSERT INTO fasade_excel_history 
              (procjena_id, gradiliste_id, excel_qnap_path, opis_promjene, 
               ukupno_m2_neto, ukupno_m2_bruto, kreirao_id, kreirao_ime, created_at)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW())
          `, [
            f.id,
            f.gradiliste_id,
            qnapPath,
            'Excel regen',
            parseFloat(f.neto_fasada_m2 || 0) || null,
            parseFloat(f.bruto_fasada_m2 || 0) || null,
            req.user?.id || null,
            kreaIme.slice(0, 100)
          ]);
        } catch(histErr) {
          console.warn('[Excel history INSERT]', histErr.message);
        }
      } catch(e) { console.warn('[Excel export] clear dirty fail:', e.message); }
    });
  } catch(e) {
    console.error('[Fasada Excel knjiga]', e);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// HELPER: generiraj građevinsku knjigu jednog gradilišta (poziva se iz endpoint + move/delete/arhiv)
// Vraća { buffer, fname, broj_procjena }
// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v544 (Ivan): SANACIJA ExcelJS↔Excel shema-quirkova koji su tjerali Excel da "popravlja" knjigu na otvaranju.
//   (1) richText <rPr>: ExcelJS piše <rFont> ZADNJI; OOXML CT_RPrElt traži <rFont> PRVI → premjesti ga na početak.
//   (2) slike <xdr:spPr><a:xfrm>: ExcelJS piše <a:ext cx="0" cy="0"/> (nulta veličina shape-a); postavi na stvarnu veličinu iz anchora (<xdr:ext>).
//   Radi na gotovom xlsx bufferu (zip) preko JSZip; ciljani string-replace unutar 2 dijela, ostalo netaknuto. Fallback: original buffer (knjiga radi i bez sanacije).
async function _xlsxFixBuffer(buf) {
  try {
    const JSZip = require('jszip');
    const zip = await JSZip.loadAsync(buf);
    const ssPath = 'xl/sharedStrings.xml';
    if (zip.file(ssPath)) {
      let ss = await zip.file(ssPath).async('string');
      ss = ss.replace(/<rPr>([\s\S]*?)<\/rPr>/g, (mm, inner) => {
        const rf = inner.match(/<rFont\b[^>]*\/>/);
        if (!rf) return mm;
        return '<rPr>' + rf[0] + inner.replace(rf[0], '') + '</rPr>';
      });
      zip.file(ssPath, ss);
    }
    const drFiles = Object.keys(zip.files).filter(pp => /^xl\/drawings\/drawing\d+\.xml$/.test(pp));
    for (const pp of drFiles) {
      let dx = await zip.file(pp).async('string');
      // ⭐ v552 (Ivan): editAs NIJE valjan atribut na <xdr:oneCellAnchor> (samo na twoCellAnchor) → Excel je zbog toga
      //   isao u "repair mode" (vidi se kao "Repaired Records: Drawing..."), a usput je STRPAO richText fontove iz sharedStrings
      //   (pa su opisi u rekapitulaciji ispadali razlicitih velicina). Makni editAs → OOXML valjan → nema repair-a → fontovi ostaju.
      dx = dx.replace(/<xdr:oneCellAnchor editAs="[^"]*">/g, '<xdr:oneCellAnchor>');
      dx = dx.replace(/<xdr:(oneCellAnchor|twoCellAnchor|absoluteAnchor)\b([\s\S]*?)<\/xdr:\1>/g, (whole) => {
        const ext = whole.match(/<xdr:ext cx="(\d+)" cy="(\d+)"\/>/);
        if (!ext) return whole;
        return whole.replace(/<a:ext cx="0" cy="0"\/>/, '<a:ext cx="' + ext[1] + '" cy="' + ext[2] + '"/>');
      });
      zip.file(pp, dx);
    }
    return await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  } catch (e) { console.warn('[xlsx-fix v544]', e && e.message); return buf; }
}

// ⭐ v553 (Ivan): XLSX → PDF preko LibreOffice headless. Za "📄 PDF" gumb (CIJELA knjiga — svi listovi + crtezi).
//   Zahtjeva LibreOffice na serveru (nixpacks.toml: aptPkgs ["libreoffice-calc"]). Ako nije instaliran /
//   padne / timeout — BACA gresku (ruta vrati jasan 503), NIKAD ne rusi proces. Excel preuzimanje radi neovisno.
//   Konvertira ISTI XLSX buffer koji generira 📥 Preuzmi → PDF je vjerna kopija Excela (svi listovi).
async function _xlsxToPdfBuffer(xlsxBuf, baseName) {
  const { execFile } = require('child_process');
  const fs = require('fs');
  const os = require('os'), path = require('path'), fsp = require('fs').promises;
  // ⭐ v554 (Ivan): robusno nalaženje LibreOffice binarke (apt -> /usr/bin/soffice; ali ovisno o slici
  //   može biti i drugdje) + DETALJNA greška da se na klijentu vidi STVARNI razlog (prije: generičko 503).
  const _absCands = ['/usr/bin/soffice', '/usr/bin/libreoffice', '/usr/lib/libreoffice/program/soffice',
    '/opt/libreoffice/program/soffice', '/snap/bin/libreoffice'];
  let _bin = null;
  for (const c of _absCands) { try { if (fs.existsSync(c)) { _bin = c; break; } } catch (_) {} }
  if (!_bin) _bin = 'soffice';   // zadnji fallback: PATH lookup (baca ENOENT ako ni to nije instalirano)
  console.log('[xlsx->pdf] LibreOffice binarka:', _bin);
  const safe = String(baseName || 'knjiga').replace(/[^a-z0-9_]+/gi, '_').slice(0, 60) || 'knjiga';
  const dir = await fsp.mkdtemp(path.join(os.tmpdir(), 'zbuka_pdf_'));
  const xlsxPath = path.join(dir, safe + '.xlsx');
  const pdfPath = path.join(dir, safe + '.pdf');
  try {
    await fsp.writeFile(xlsxPath, xlsxBuf);
    await new Promise((resolve, reject) => {
      execFile(_bin, [
        '--headless', '--nologo', '--nofirststartwizard', '--norestore',
        '--convert-to', 'pdf',
        '--outdir', dir,
        '-env:UserInstallation=file://' + path.join(dir, 'lo_profile'),
        xlsxPath
      ], { timeout: 120000, maxBuffer: 1024 * 1024 * 16 }, (err, stdout, stderr) => {
        if (!err) return resolve();
        if (err.code === 'ENOENT') return reject(new Error('LibreOffice nije instaliran/pronaden (binarka "' + _bin + '"). Provjeri da je nixpacks.toml u rootu i da je Railway rebuildao s libreoffice-calc.'));
        if (err.killed) return reject(new Error('Konverzija prekinuta (timeout 120s ili memorija/OOM).'));
        return reject(new Error('soffice greska (' + (err.code != null ? 'exit ' + err.code : err.message) + ')' + (stderr ? ': ' + String(stderr).replace(/\s+/g, ' ').slice(0, 180) : '')));
      });
    });
    if (!fs.existsSync(pdfPath)) throw new Error('soffice nije proizveo PDF izlaz.');
    return await fsp.readFile(pdfPath);
  } finally {
    fsp.rm(dir, { recursive: true, force: true }).catch(() => {});
  }
}

async function generirajGradevinskuKnjiguBuffer(gradiliste_id) {
  const gradR = await pool.query('SELECT * FROM gradilista WHERE id=$1', [gradiliste_id]);
  if (!gradR.rows.length) throw new Error('Gradilište ne postoji');
  const grad = gradR.rows[0];
  
  // ⭐ v135.7.15 BUG #3 FIX: Filter SAMO detaljne procjene (građevinska knjiga)
  //    Prije: WHERE gradiliste_id - dohvaćao SVE procjene (i brze, i AI multi-pročelje)
  //    Sada: samo procjene koje su detaljne ravnine (građevinska knjiga koncept)
  //    Brze i AI multi-pročelje su u drugom listu pod "Ukupno" — ne pripadaju u knjigu.
  // 
  // ⭐ v135.7.52 (Ivan): SAMO AKTIVNA procjena
  //    Prije: knjiga je agregirala SVE procjene gradilišta (P1 #111, P2 #112, P3 #113...)
  //           što je rezultiralo višestrukim sažetcima istih pročelja u Excelu
  //    Sada: AND aktivna = TRUE → knjiga sadrži SAMO najnoviju verziju.
  //          Stare verzije su snapshot-ane na QNAP (aktivna=FALSE + arhiva_qnap_path).
  //          UI gumb "📚 Stare verzije knjige" daje pristup arhivi.
  const procR = await pool.query(`
    SELECT f.*, rad.ime || ' ' || rad.prezime AS kreirao
    FROM fasade_procjene f
    LEFT JOIN radnici rad ON rad.id = f.kreirao_id
    WHERE f.gradiliste_id = $1
      AND (f.tip_procjene IS NULL OR f.tip_procjene = 'detaljna')
      AND (f.koncept IS NULL OR f.koncept != 'homografija_multi')
      AND f.aktivna = TRUE
    ORDER BY f.created_at ASC
  `, [gradiliste_id]);
  const knjige = procR.rows;
  
  // Pozovi postojeći knjigu generator (pristup preko req-a) - ali ovdje radimo embed verziju
  // Najlakše: pozovemo postojeći endpoint kao internal request? Ne — bolje da knjiga endpoint sam koristi ovaj buffer.
  
  const ExcelJS = require('exceljs');
  const wb = new ExcelJS.Workbook();
  wb.creator = 'ŽBUKA Čakarić d.o.o.';
  wb.created = new Date();
  
  // Pozivamo helper inline (kompletna logika dolje u endpointu)
  // Ali mi sad ovdje moramo replicate-ati. Zato delegate na zajednički helper buildKnjiga(wb, grad, procjene).
  await buildKnjigaWorkbook(wb, grad, knjige);
  
  const buffer = await _xlsxFixBuffer(await wb.xlsx.writeBuffer());   // ⭐ v544: sanacija OOXML quirkova (rFont-first + spPr ext)
  const safeName = (grad.naziv || 'gradiliste').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
  const fname = `Gradevinska_knjiga_${safeName}.xlsx`;
  
  return { buffer: Buffer.from(buffer), fname, broj_procjena: knjige.length, grad };
}

// ═══════════════════════════════════════════════════════════════════════════
// KOMPAKTNA 3-STRANICA VERZIJA NORMATIVA — v135.4
// Stari sheet je bio ~30+ stranica (preopsežan). Ova verzija stane na 3 A4.
// Stranica 1: Header + uvod + ključna GN 421 pravila
// Stranica 2: Tablica normativa (sve točke 1-10 sažeto)
// Stranica 3: Reference + napomene + potpis blok
// ═══════════════════════════════════════════════════════════════════════════
async function generirajSheetNormativiKompaktno(wb, gradilisteInfo = null) {
  const NAVY = 'FF0f172a';
  const AMBER = 'FFd97706';
  const AMBER_LIGHT = 'FFfef3c7';
  const GRAY_DARK = 'FF374151';
  const GRAY_MED = 'FF6b7280';
  const GRAY_BORDER = 'FFd1d5db';
  const GRAY_LIGHT = 'FFf3f4f6';
  const WHITE = 'FFFFFFFF';
  
  const ws = wb.addWorksheet('Normativi', {
    pageSetup: {
      paperSize: 9, orientation: 'portrait', fitToPage: true,
      fitToWidth: 1, fitToHeight: 0,
      margins: { left: 0.4, right: 0.4, top: 0.5, bottom: 0.4, header: 0.2, footer: 0.2 }
    },
    views: [{ showGridLines: false }]
  });
  
  // 6 kolona, kompaktna širina (zajedno ~18cm = A4 width minus margins)
  ws.columns = [
    { width: 3 },   // A: lijevi gutter
    { width: 6 },   // B: broj/oznaka
    { width: 28 },  // C: naziv normativa
    { width: 14 },  // D: jedinica
    { width: 18 },  // E: vrijednost/formula
    { width: 8 }    // F: napomena
  ];
  
  let r = 1;
  const setBorder = (cell) => { cell.border = {
    top:    { style: 'thin', color: { argb: GRAY_BORDER } },
    bottom: { style: 'thin', color: { argb: GRAY_BORDER } },
    left:   { style: 'thin', color: { argb: GRAY_BORDER } },
    right:  { style: 'thin', color: { argb: GRAY_BORDER } }
  };};
  
  // ════════ STRANICA 1: HEADER + UVOD ════════
  
  // Logo bar (visok, navy)
  ws.mergeCells(`A${r}:F${r}`);
  const cellLogo = ws.getCell(`A${r}`);
  cellLogo.value = '🏗 ŽBUKA Čakarić d.o.o. — REFERENTNI NORMATIVI GN 421';
  cellLogo.font = { name: 'Calibri', size: 14, bold: true, color: { argb: WHITE } };
  cellLogo.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY } };
  cellLogo.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 32;
  r++;
  
  // Subtitle (amber)
  ws.mergeCells(`A${r}:F${r}`);
  const cellSub = ws.getCell(`A${r}`);
  cellSub.value = 'Sažetak za izradu građevinske knjige fasaderskih radova';
  cellSub.font = { name: 'Calibri', size: 10, italic: true, color: { argb: AMBER } };
  cellSub.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: AMBER_LIGHT } };
  cellSub.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(r).height = 20;
  r++;
  
  // Praznina
  ws.getRow(r).height = 6; r++;
  
  // Info redak (gradilište + datum)
  if (gradilisteInfo && gradilisteInfo.naziv) {
    ws.mergeCells(`A${r}:C${r}`);
    const cellG = ws.getCell(`A${r}`);
    cellG.value = `Gradilište: ${gradilisteInfo.naziv}${gradilisteInfo.adresa ? ' · ' + gradilisteInfo.adresa : ''}`;
    cellG.font = { name: 'Calibri', size: 9, color: { argb: GRAY_DARK } };
    cellG.alignment = { horizontal: 'left' };
    
    ws.mergeCells(`D${r}:F${r}`);
    const cellD = ws.getCell(`D${r}`);
    cellD.value = `Datum: ${fmtDate(new Date())}`;
    cellD.font = { name: 'Calibri', size: 9, color: { argb: GRAY_DARK } };
    cellD.alignment = { horizontal: 'right' };
    r++;
  }
  
  ws.getRow(r).height = 8; r++;
  
  // Uvod naslov
  ws.mergeCells(`A${r}:F${r}`);
  const cellUvod = ws.getCell(`A${r}`);
  cellUvod.value = '1. ŠTO JE GN 421';
  cellUvod.font = { name: 'Calibri', size: 11, bold: true, color: { argb: NAVY } };
  cellUvod.alignment = { horizontal: 'left', vertical: 'middle' };
  cellUvod.border = { bottom: { style: 'medium', color: { argb: AMBER } } };
  ws.getRow(r).height = 18;
  r++;
  ws.getRow(r).height = 4; r++;
  
  // Uvod tekst (pažljivo dimenzioniran)
  const uvodText = 'GN 421 ("Prosječne norme u građevinarstvu, knjiga III") je referentni normativ za obračun fasaderskih i žbukarskih radova u Republici Hrvatskoj. Definira pravila za izračun bruto i neto površine nacrta, način obračuna otvora, špaleta, vijenaca, brisoleja i drugih elemenata fasade.';
  ws.mergeCells(`A${r}:F${r}`);
  const cellUT = ws.getCell(`A${r}`);
  cellUT.value = uvodText;
  cellUT.font = { name: 'Calibri', size: 9, color: { argb: GRAY_DARK } };
  cellUT.alignment = { horizontal: 'justify', vertical: 'top', wrapText: true };
  ws.getRow(r).height = 50;
  r++;
  ws.getRow(r).height = 8; r++;
  
  // KLJUČNO PRAVILO box (amber light)
  ws.mergeCells(`A${r}:F${r}`);
  const cellKP = ws.getCell(`A${r}`);
  cellKP.value = '⚡ KLJUČNO: Otvori MANJI od 3 m² uključuju se u obračun bruto površine. Otvori VEĆI od 3 m² oduzimaju se (samo višak iznad 3 m²).';
  cellKP.font = { name: 'Calibri', size: 9.5, bold: true, color: { argb: NAVY } };
  cellKP.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: AMBER_LIGHT } };
  cellKP.alignment = { horizontal: 'left', vertical: 'middle', wrapText: true, indent: 1 };
  cellKP.border = { left: { style: 'thick', color: { argb: AMBER } } };
  ws.getRow(r).height = 30;
  r++;
  ws.getRow(r).height = 10; r++;
  
  // Naslov sekcija 2
  ws.mergeCells(`A${r}:F${r}`);
  const cellS2 = ws.getCell(`A${r}`);
  cellS2.value = '2. PROCEDURA OBRAČUNA';
  cellS2.font = { name: 'Calibri', size: 11, bold: true, color: { argb: NAVY } };
  cellS2.alignment = { horizontal: 'left', vertical: 'middle' };
  cellS2.border = { bottom: { style: 'medium', color: { argb: AMBER } } };
  ws.getRow(r).height = 18;
  r++;
  ws.getRow(r).height = 4; r++;
  
  // Procedura (5 koraka u tablici)
  const koraci = [
    ['1.', 'BRUTO POLIGON', 'Izmjeri vanjski rub nacrta (širina × visina ili poligon).'],
    ['2.', 'OTVORI', 'Označi sve otvore (prozore, vrata, garažna vrata) s pravom dimenzijom.'],
    ['3.', 'KLASIFIKACIJA', 'Otvor < 3m²: ne odbija se. Otvor > 3m²: odbija se samo (Površina − 3m²).'],
    ['4.', 'NETO POVRŠINA', 'Neto = Bruto − Σ (otvori po pravilu 3.).'],
    ['5.', 'DODACI', 'Špalete, vijenci, brisoleji se dodaju po t. 4.1 normativa (ako primjenjivo).']
  ];
  for (const [k, naslov, opis] of koraci) {
    const cellK = ws.getCell(`B${r}`);
    cellK.value = k;
    cellK.font = { name: 'Calibri', size: 10, bold: true, color: { argb: AMBER } };
    cellK.alignment = { horizontal: 'center' };
    
    const cellN = ws.getCell(`C${r}`);
    cellN.value = naslov;
    cellN.font = { name: 'Calibri', size: 9, bold: true, color: { argb: NAVY } };
    
    ws.mergeCells(`D${r}:F${r}`);
    const cellO = ws.getCell(`D${r}`);
    cellO.value = opis;
    cellO.font = { name: 'Calibri', size: 9, color: { argb: GRAY_DARK } };
    cellO.alignment = { horizontal: 'left', wrapText: true };
    
    ws.getRow(r).height = 18;
    r++;
  }
  
  // Page break — kraj stranice 1
  ws.getRow(r).addPageBreak();
  r++;
  
  // ════════ STRANICA 2: TABLICA NORMATIVA ════════
  
  // Header
  ws.mergeCells(`A${r}:F${r}`);
  const cellH2 = ws.getCell(`A${r}`);
  cellH2.value = '3. TABLICA NORMATIVA — GN 421 točke 1-10';
  cellH2.font = { name: 'Calibri', size: 11, bold: true, color: { argb: NAVY } };
  cellH2.alignment = { horizontal: 'left', vertical: 'middle' };
  cellH2.border = { bottom: { style: 'medium', color: { argb: AMBER } } };
  ws.getRow(r).height = 22;
  r++;
  ws.getRow(r).height = 6; r++;
  
  // Tablica zaglavlje
  const headerCells = [
    { col: 'B', val: 'GN' },
    { col: 'C', val: 'NORMATIV' },
    { col: 'D', val: 'JEDINICA' },
    { col: 'E', val: 'OBRAČUN' },
    { col: 'F', val: 'ref.' }
  ];
  for (const h of headerCells) {
    const c = ws.getCell(`${h.col}${r}`);
    c.value = h.val;
    c.font = { name: 'Calibri', size: 9, bold: true, color: { argb: WHITE } };
    c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY } };
    c.alignment = { horizontal: 'center', vertical: 'middle' };
    setBorder(c);
  }
  ws.getRow(r).height = 18;
  r++;
  
  // Tablica redovi (kompaktni)
  const normativi = [
    ['1.1', 'Bruto površina nacrta', 'm²', 'Š × V (poligon ili pravokutnik)', 't.1'],
    ['1.2', 'Neto površina nacrta', 'm²', 'Bruto − Σ otvori (po pravilu 3.)', 't.1'],
    ['2.1', 'Otvori < 3 m²', 'm²', 'NE odbijaju se od bruto', 't.2'],
    ['2.2', 'Otvori 3-5 m²', 'm²', 'Odbija se (P − 3) m²', 't.2'],
    ['2.3', 'Otvori > 5 m²', 'm²', 'Odbija se (P − 3) + špalete', 't.2'],
    ['3.1', 'Žbuka grubo (sirov beton)', 'm²', 'Bruto nacrta', 't.3'],
    ['3.2', 'Žbuka fino (završno)', 'm²', 'Neto nacrta', 't.3'],
    ['3.3', 'ETICS (fasadni sustav)', 'm²', 'Neto + 5% (rezovi)', 't.3'],
    ['4.1', 'Vijenci, klupčice u m¹', 'm¹→m²', 'Duljina × visina (cm)/100', 't.4.1'],
    ['4.2', 'Pilastri, stupci', 'kom', 'Po komadu (kataloški)', 't.4.2'],
    ['4.3', 'Brisoleji, lamele', 'm²', 'Vanjska + unutarnja površina', 't.4.3'],
    ['5.1', 'Izrada skele radne', 'm²', 'Bruto nacrta × 1.05', 't.5'],
    ['5.2', 'Izrada skele zaštitne', 'm²', 'Bruto + nadogradnja krova', 't.5'],
    ['6.1', 'Demontaža skele', 'm²', '70% od izrade', 't.6'],
    ['7.1', 'Penetracija (priprema)', 'm²', 'Neto nacrta', 't.7'],
    ['7.2', 'Boja (završni sloj)', 'm²', 'Neto nacrta × 2 (slojevi)', 't.7'],
    ['8.1', 'Sokl (visina < 50cm)', 'm¹→m²', 'Duljina × 0.5 m', 't.8'],
    ['9.1', 'Špalete prozora < 30cm', 'm', 'Obračunate u otvoru', 't.9'],
    ['9.2', 'Špalete > 30cm', 'm²', 'Posebno (š × duljina)', 't.9'],
    ['10.1', 'Mreža armirajuća', 'm²', 'ETICS sloj × 1.10 (preklopi)', 't.10']
  ];
  
  for (const [gn, naziv, jed, obracun, ref] of normativi) {
    const isAlt = (r % 2 === 0);
    const fillColor = isAlt ? GRAY_LIGHT : WHITE;
    
    const cells = [
      { col: 'B', val: gn, align: 'center', bold: true, color: AMBER },
      { col: 'C', val: naziv, align: 'left', bold: false, color: GRAY_DARK },
      { col: 'D', val: jed, align: 'center', bold: false, color: GRAY_DARK },
      { col: 'E', val: obracun, align: 'left', bold: false, color: GRAY_DARK },
      { col: 'F', val: ref, align: 'center', bold: false, color: GRAY_MED }
    ];
    for (const c of cells) {
      const cell = ws.getCell(`${c.col}${r}`);
      cell.value = c.val;
      cell.font = { name: 'Calibri', size: 8.5, bold: c.bold, color: { argb: c.color } };
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: fillColor } };
      cell.alignment = { horizontal: c.align, vertical: 'middle', wrapText: true };
      setBorder(cell);
    }
    ws.getRow(r).height = 14;
    r++;
  }
  
  // Page break — kraj stranice 2
  r++;
  ws.getRow(r).addPageBreak();
  r++;
  
  // ════════ STRANICA 3: REFERENCE + NAPOMENE ════════
  
  // Header
  ws.mergeCells(`A${r}:F${r}`);
  const cellH3 = ws.getCell(`A${r}`);
  cellH3.value = '4. PRAKTIČNE NAPOMENE';
  cellH3.font = { name: 'Calibri', size: 11, bold: true, color: { argb: NAVY } };
  cellH3.alignment = { horizontal: 'left', vertical: 'middle' };
  cellH3.border = { bottom: { style: 'medium', color: { argb: AMBER } } };
  ws.getRow(r).height = 22;
  r++;
  ws.getRow(r).height = 6; r++;
  
  const napomene = [
    ['•', 'Mjeri se uvijek u metrima i m², ne u centimetrima.'],
    ['•', 'Otvor (prozor/vrata) u procesu se mjeri sa svjetlim otvorom — bez okvira/štoka.'],
    ['•', 'Špalete < 30 cm tretiraju se kao dio otvora (nema posebnog obračuna).'],
    ['•', 'Vijenci, klupčice, trake u m¹ pretvaraju se u m² množenjem s visinom u cm / 100.'],
    ['•', 'ETICS sustav: dodaj 5% za rezove i preklope mreže.'],
    ['•', 'Skela radna: minimum 5% više od neto nacrta zbog tlocrta.'],
    ['•', 'Penetracija + 2 sloja boje = osnovni paket završne obrade.'],
    ['•', 'Različite debljine ETICS-a (npr. 8cm/10cm/14cm) tretiraju se kao zasebne stavke.'],
    ['•', 'Požarne barijere (mineralna vuna trake oko otvora) obračunavaju se u m¹.'],
    ['•', 'Reljefni elementi (rustika, štukatura) imaju posebne pozicije po dogovoru s investitorom.']
  ];
  
  for (const [bullet, text] of napomene) {
    const cellB = ws.getCell(`B${r}`);
    cellB.value = bullet;
    cellB.font = { name: 'Calibri', size: 10, bold: true, color: { argb: AMBER } };
    cellB.alignment = { horizontal: 'center', vertical: 'top' };
    
    ws.mergeCells(`C${r}:F${r}`);
    const cellT = ws.getCell(`C${r}`);
    cellT.value = text;
    cellT.font = { name: 'Calibri', size: 9, color: { argb: GRAY_DARK } };
    cellT.alignment = { horizontal: 'left', vertical: 'top', wrapText: true };
    ws.getRow(r).height = 16;
    r++;
  }
  
  ws.getRow(r).height = 12; r++;
  
  // Reference box
  ws.mergeCells(`A${r}:F${r}`);
  const cellRef = ws.getCell(`A${r}`);
  cellRef.value = '5. IZVOR I REFERENCE';
  cellRef.font = { name: 'Calibri', size: 11, bold: true, color: { argb: NAVY } };
  cellRef.alignment = { horizontal: 'left', vertical: 'middle' };
  cellRef.border = { bottom: { style: 'medium', color: { argb: AMBER } } };
  ws.getRow(r).height = 22;
  r++;
  ws.getRow(r).height = 6; r++;
  
  const refs = [
    ['1.', 'Primarni izvor', 'Prosječne norme u građevinarstvu, knjiga III (GN 421)'],
    ['2.', 'Pravilnik', 'Pravilnik o jednostavnim i drugim građevinama (NN 112/17)'],
    ['3.', 'Tehnička norma', 'HRN EN 13914 (Žbuka i gips za zidove)'],
    ['4.', 'ETICS standard', 'ETAG 004 + EAD 040083 (vanjski toplinski izolacijski sustavi)'],
    ['5.', 'Sigurnost na radu', 'Zakon o zaštiti na radu (NN 71/14, 118/14)']
  ];
  
  for (const [n, naslov, opis] of refs) {
    const cellN = ws.getCell(`B${r}`);
    cellN.value = n;
    cellN.font = { name: 'Calibri', size: 9, bold: true, color: { argb: AMBER } };
    cellN.alignment = { horizontal: 'center' };
    
    const cellNa = ws.getCell(`C${r}`);
    cellNa.value = naslov;
    cellNa.font = { name: 'Calibri', size: 9, bold: true, color: { argb: NAVY } };
    
    ws.mergeCells(`D${r}:F${r}`);
    const cellO = ws.getCell(`D${r}`);
    cellO.value = opis;
    cellO.font = { name: 'Calibri', size: 8.5, color: { argb: GRAY_DARK }, italic: true };
    cellO.alignment = { horizontal: 'left', wrapText: true };
    
    ws.getRow(r).height = 14;
    r++;
  }
  
  ws.getRow(r).height = 12; r++;
  
  // Footer s potpisima
  ws.mergeCells(`A${r}:F${r}`);
  const cellFt = ws.getCell(`A${r}`);
  cellFt.value = `Dokument generiran: ${fmtDate(new Date())} u ${new Date().toLocaleTimeString('hr-HR', {hour:'2-digit', minute:'2-digit'})} · ŽBUKA Čakarić d.o.o.`;
  cellFt.font = { name: 'Calibri', size: 8, italic: true, color: { argb: GRAY_MED } };
  cellFt.alignment = { horizontal: 'center', vertical: 'middle' };
  cellFt.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: GRAY_LIGHT } };
  ws.getRow(r).height = 18;
  r++;
  
  return ws;
}

// HELPER: regen + upload knjige na QNAP (overwrite). Briše ako 0 procjena.
async function regenGradevinskaKnjiga(gradiliste_id) {
  try {
    const gradR = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id]);
    if (!gradR.rows.length) return null;
    const grad = gradR.rows[0];
    const folder = fasadaQnapFolder(grad.naziv || 'gradiliste');
    
    const procCntR = await pool.query(
      'SELECT COUNT(*) AS cnt FROM fasade_procjene WHERE gradiliste_id=$1',
      [gradiliste_id]
    );
    const cnt = parseInt(procCntR.rows[0]?.cnt || 0);
    
    if (cnt === 0) {
      // Nema procjena → obriši knjigu s QNAP-a (ako postoji)
      const safeName = (grad.naziv || 'gradiliste').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
      const fname = `Gradevinska_knjiga_${safeName}.xlsx`;
      try {
        if (typeof qnapDeleteFile === 'function') {
          await qnapDeleteFile(`${folder}/${fname}`);
          console.log(`[regenKnjiga] 0 knjiga → obrisana knjiga ${fname}`);
        }
      } catch(_) {}
      return { broj_procjena: 0, obrisano: true };
    }
    
    const { buffer, fname, broj_procjena } = await generirajGradevinskuKnjiguBuffer(gradiliste_id);
    await qnapUploadExcel(buffer, `${folder}/${fname}`);
    
    // ⭐ Clear dirty + zabilježi vrijeme
    try {
      await pool.query(
        `UPDATE gradilista SET knjiga_dirty = false, knjiga_last_gen = NOW() WHERE id = $1`,
        [gradiliste_id]
      );
    } catch(_) {}
    
    console.log(`[regenKnjiga] ${grad.naziv}: ${broj_procjena} knjiga, upload ${fname}`);
    return { broj_procjena, fname };
  } catch(e) {
    console.warn('[regenKnjiga]', e.message);
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// MULTI-PROČELJE: SAVE/LOAD endpoints
// Spremanje multi-pročelje (homografija_multi koncept) u DB i čitanje natrag.
// Prije ovoga, multi-pročelje detaljna se gubila pri refresh-u (samo browser memorija).
// ═══════════════════════════════════════════════════════════════════════════

// ── HELPER: Upload multi-pročelje slika u folder gradilišta ──
// Pattern: Fasade-AI/{naziv_gradilista}/multi{multiId}_p{idx}.jpg + multi{multiId}_p{idx}_anot.jpg
// Cleanup naracrt: pri delete-u koristimo qnapDeleteByPattern(`multi${id}_`)
async function _qnapUploadMultiProceljaSlike(multiId, gradNaziv, procelja) {
  if (!process.env.QNAP_WEBDAV_URL || !gradNaziv) return procelja;
  
  const folder = fasadaQnapFolder(gradNaziv);
  
  for (let idx = 0; idx < procelja.length; idx++) {
    const p = procelja[idx];
    
    // Originalna slika
    if (p.slika_base64 && typeof p.slika_base64 === 'string') {
      try {
        const filename = `${folder}/multi${multiId}_p${idx}.jpg`;
        let cleanB64 = p.slika_base64;
        const m = p.slika_base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
        if (m) cleanB64 = m[1];
        const buf = Buffer.from(cleanB64, 'base64');
        const upPath = await qnapUploadImage(buf, filename);
        if (upPath) {
          p.slika_qnap_path = upPath;
          // Sliku iz DB jsonb sad možemo nullificirati jer je na QNAP-u (manji JSONB → brži queryi)
          p.slika_base64 = null;
          console.log(`[multi-procelje QNAP] slika p${idx} → ${upPath}`);
        }
      } catch(e) {
        console.warn(`[multi-procelje QNAP] upload slike p${idx} fail:`, e.message);
      }
    }
    
    // Anotirana slika (s polygon + ref + otvori) — ako postoji
    if (p.slika_anotirana && typeof p.slika_anotirana === 'string') {
      try {
        const fnameAnot = `${folder}/multi${multiId}_p${idx}_anot.jpg`;
        let cleanA = p.slika_anotirana;
        const ma = p.slika_anotirana.match(/^data:image\/[a-z]+;base64,(.+)$/);
        if (ma) cleanA = ma[1];
        const bufA = Buffer.from(cleanA, 'base64');
        const upPathA = await qnapUploadImage(bufA, fnameAnot);
        if (upPathA) {
          p.slika_anotirana_qnap_path = upPathA;
          p.slika_anotirana = null;  // ne čuvamo u JSONB nakon uploada
          console.log(`[multi-procelje QNAP] anotirana p${idx} → ${upPathA}`);
        }
      } catch(e) {
        console.warn(`[multi-procelje QNAP] upload anotirane p${idx} fail:`, e.message);
      }
    }
  }
  
  return procelja;
}

// POST /api/fasada/multi-procelje/spremi — spremi (insert ili update) multi-pročelje proceju
app.post('/api/fasada/multi-procelje/spremi', auth, staff, async (req, res) => {
  try {
    const { 
      id,                  // ako postoji → update, inače insert
      gradiliste_id, 
      naziv_objekta, 
      tip_objekta, 
      napomena,
      procelja             // niz: [{ oznaka, slika_base64, slika_anotirana, pravokutnik, rezultat (s otvori_detaljno), napomena }]
    } = req.body || {};
    
    if (!Array.isArray(procelja) || procelja.length === 0) {
      return res.status(400).json({ error: 'Nema nacrta za spremiti' });
    }
    if (!gradiliste_id) {
      return res.status(400).json({ error: 'Gradilište je obavezno' });
    }
    
    // ⭐ v135.7.22 (Ivanov koncept): Sumarni podaci iz svih pročelja
    //    BRUTO = Σ bruto_m2 svih pročelja
    //    NETO (GN 421) = Σ neto_gn421_m2 — ovo se pohranjuje kao neto_fasada_m2
    //    NETTO ODBITAK = Σ neto_cisti_m2 (za narudžbu materijala — info)
    let bruto = 0, otvoriM2 = 0, brojOtvora = 0, netoCisti = 0, netoGn421 = 0;
    procelja.forEach(p => {
      const r = p.rezultat || {};
      bruto += parseFloat(r.bruto_m2) || 0;
      otvoriM2 += parseFloat(r.otvori_m2) || 0;
      brojOtvora += parseInt(r.broj_otvora) || 0;
      netoCisti += parseFloat(r.neto_cisti_m2) || 0;  // = NETTO ODBITAK
      netoGn421 += parseFloat(r.neto_gn421_m2) || 0;  // = NETO GN 421 (Ivanov koncept)
    });
    
    // ── Dohvati naziv gradilišta za QNAP folder ──
    let gradNaziv = null;
    try {
      const gradR = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [gradiliste_id]);
      gradNaziv = gradR.rows[0]?.naziv || null;
    } catch(_) {}
    
    let result;
    let multiId = id;
    
    // ── 1) FIRST: INSERT ili UPDATE u DB sa SLIKAMA u JSONB (čekamo ID) ──
    //    Razlog: za INSERT trebamo dobiti ID prije nego što uploadamo slike na QNAP
    //    (jer pattern je multi{id}_p{idx}.jpg)
    
    // Proširena pročelje struktura — uključi i slika_anotirana i postojeći qnap path-ove
    const proceljaPrep = procelja.map(p => ({
      oznaka: p.oznaka || '',
      napomena: p.napomena || '',
      slika_base64: (p.slika_base64 && p.slika_base64.length < 4_000_000) ? p.slika_base64 : null,
      slika_anotirana: (p.slika_anotirana && p.slika_anotirana.length < 4_000_000) ? p.slika_anotirana : null,
      slika_qnap_path: p.slika_qnap_path || null,        // ako je već uploadana
      slika_anotirana_qnap_path: p.slika_anotirana_qnap_path || null,
      slika_velikost_kb: p.slika_base64 ? Math.round(p.slika_base64.length / 1024) : 0,
      pravokutnik: p.pravokutnik || null,
      rezultat: p.rezultat || null,
      tip_objekta: p.tip_objekta || null
    }));
    
    const dimenzijeInicial = {
      koncept: 'homografija_multi',
      tip_objekta: tip_objekta || 'stambena_zgrada',
      napomena_glavna: napomena || '',
      procelja: proceljaPrep
    };
    
    if (id) {
      // UPDATE: prvo dohvati postojeću proceju za potencijalni cleanup starih slika
      const stari = await pool.query(`SELECT dimenzije_fasade FROM fasade_procjene WHERE id=$1`, [id]);
      const r = await pool.query(`
        UPDATE fasade_procjene
        SET gradiliste_id = $1,
            naziv_objekta = $2,
            tip_procjene = 'brza',
            koncept = 'homografija_multi',
            tip_objekta = $3,
            dimenzije_fasade = $4,
            bruto_fasada_m2 = $5,
            ukupna_fasada_m2 = $5,
            neto_fasada_m2 = $6,
            updated_at = NOW()
        WHERE id = $7
        RETURNING *
      `, [gradiliste_id, naziv_objekta || '', tip_objekta || null, JSON.stringify(dimenzijeInicial), 
          bruto, netoGn421, id]);  // v135.7.22: NETO = GN 421 (Ivanov koncept)
      
      if (!r.rows.length) {
        // ⭐ v135.4: Fallback na INSERT — procjena s tim ID-om ne postoji (možda obrisana ili krivi ID)
        //    Klijent pamti zastarjeli ID (npr. nakon brisanja iz baze) → UPDATE ne pogodi nikoga
        //    Umjesto da fail-amo, kreiramo novu procjenu i vratimo novi ID
        console.log(`[multi-procelje/spremi] UPDATE id=${id} ne pogodi nikoga → fallback na INSERT (nova knjiga)`);
        const r2 = await pool.query(`
          INSERT INTO fasade_procjene (
            gradiliste_id, naziv_objekta, tip_procjene, koncept, tip_objekta,
            dimenzije_fasade, bruto_fasada_m2, ukupna_fasada_m2, neto_fasada_m2,
            ai_confidence, kreirao_id, created_at
          ) VALUES ($1, $2, 'brza', 'homografija_multi', $3, $4, $5, $5, $6, $7, $8, NOW())
          RETURNING *
        `, [gradiliste_id, naziv_objekta || '', tip_objekta || null, JSON.stringify(dimenzijeInicial),
            bruto, netoGn421, 85, req.user.id]);  // v135.7.22
        result = r2.rows[0];
        multiId = result.id;
      } else {
        result = r.rows[0];
      }
    } else {
      const r = await pool.query(`
        INSERT INTO fasade_procjene (
          gradiliste_id, naziv_objekta, tip_procjene, koncept, tip_objekta,
          dimenzije_fasade, bruto_fasada_m2, ukupna_fasada_m2, neto_fasada_m2,
          ai_confidence, kreirao_id, created_at
        ) VALUES ($1, $2, 'brza', 'homografija_multi', $3, $4, $5, $5, $6, $7, $8, NOW())
        RETURNING *
      `, [gradiliste_id, naziv_objekta || '', tip_objekta || null, JSON.stringify(dimenzijeInicial),
          bruto, netoGn421, 85, req.user.id]);  // v135.7.22
      result = r.rows[0];
      multiId = result.id;
    }
    
    // ── 2) UPLOAD slike na QNAP (folder gradilišta, pattern multi{id}_p{idx}) ──
    //    Async ali blokira odgovor jer trebamo update DB s path-ovima
    if (process.env.QNAP_WEBDAV_URL && gradNaziv) {
      try {
        const proceljaPosUpload = await _qnapUploadMultiProceljaSlike(multiId, gradNaziv, proceljaPrep);
        
        // Update DB s novim path-ovima (slike_base64 sada null)
        const dimenzijeNakonUpload = {
          ...dimenzijeInicial,
          procelja: proceljaPosUpload
        };
        await pool.query(
          `UPDATE fasade_procjene SET dimenzije_fasade = $1 WHERE id = $2`,
          [JSON.stringify(dimenzijeNakonUpload), multiId]
        );
        result.dimenzije_fasade = dimenzijeNakonUpload;
      } catch(e) {
        console.warn(`[multi-procelje QNAP upload]`, e.message);
        // Ne fail-aj, slike ostaju u JSONB ako je QNAP nedostupan
      }
    }
    
    // ⭐ Multi je tip='brza' — postavi excel_dirty (ne knjiga, jer multi NE ulazi u knjigu)
    try {
      await pool.query(`UPDATE fasade_procjene SET excel_dirty = true WHERE id = $1`, [multiId]);
    } catch(_) {}
    
    // ⭐ v132: Activity log + push notifikacija (Memsur kreirao → Ivan dobiva push)
    //    Bilo je propušteno u multi-procelje endpoint-u — Ivan nije dobivao notifikacije!
    logFasActivity(
      req.user,
      id ? 'azurirana' : 'kreirana',  // id postoji = update
      'multi-procelje',
      multiId,
      gradiliste_id || null,
      naziv_objekta || gradNaziv || null,
      { 
        broj_procelja: procelja.length,
        bruto_m2: parseFloat(bruto.toFixed(2)),
        neto_cisti_m2: parseFloat(netoCisti.toFixed(2))
      }
    ).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
    
    res.json({
      ok: true,
      id: multiId,
      sumarno: {
        bruto_m2: parseFloat(bruto.toFixed(2)),
        otvori_m2: parseFloat(otvoriM2.toFixed(2)),
        broj_otvora: brojOtvora,
        neto_cisti_m2: parseFloat(netoCisti.toFixed(2)),
        neto_gn421_m2: parseFloat(netoGn421.toFixed(2)),
        broj_procelja: procelja.length
      }
    });
  } catch(e) {
    console.error('[multi-procelje spremi]', e);
    res.status(500).json({ error: e.message });
  }
});

// ── HELPER: dohvati sliku sa QNAP-a kao data: URL (base64) ──
async function _qnapFetchSlikaAsDataUrl(qnapPath) {
  if (!qnapPath) return null;
  
  // ⭐ v135.7.227: B2 fallback za fasade slike (reference, procjene, sitnice, nacrti)
  //   Razlog: qnapUploadImage automatski uploada na B2 s istim path-om (od v202),
  //   ali ova funkcija nije znala B2 fallback → ako QNAP padne, slike nedostupne.
  //   SAD: pokušaj QNAP first → fallback B2 (isti path) ako QNAP fail-a.
  //   
  //   Circuit breaker: ako QNAP DOWN, idi direktno na B2 (instant).
  
  const cleanPath = qnapPath.replace(/^\//, '');
  const isPng = qnapPath.toLowerCase().endsWith('.png');
  const isPdf = qnapPath.toLowerCase().endsWith('.pdf');
  const mimeType = isPng ? 'image/png' : isPdf ? 'application/pdf' : 'image/jpeg';
  
  // Pokušaj 1: QNAP (osim ako circuit breaker je open)
  // ⭐ v259 (Ivan): Fasade-AI UVIJEK pokuša QNAP — circuit se otvara i na štucaje myqnapcloud
  //   relaya (Ivanovi lažni 'QNAP pao' pushevi dok LAN radi); bez B2 izlaza, preskakanje QNAP-a
  //   bi značilo trenutni 'slika ne postoji' za sve Fasade slike.
  if (process.env.QNAP_WEBDAV_URL && (!_qnapCircuitOpen() || cleanPath.startsWith('Fasade-AI/'))) {
    try {
      const baseUrl = process.env.QNAP_WEBDAV_URL.replace(/\/$/, '');
      const base    = (process.env.QNAP_BASE_PATH || '/APLIKACIJA').replace(/\/$/, '');
      const auth64  = Buffer.from(`${process.env.QNAP_USER}:${process.env.QNAP_PASSWORD}`).toString('base64');
      const encodedPath = cleanPath.split('/').filter(Boolean).map(encodeURIComponent).join('/');
      const fullUrl = `${baseUrl}${base}/${encodedPath}`;
      const qr = await fetch(fullUrl, {
        headers: { Authorization: `Basic ${auth64}` },
        signal: AbortSignal.timeout(10000)
      });
      if (qr.ok) {
        _qnapCircuitRecord(true);
        const buf = Buffer.from(await qr.arrayBuffer());
        return `data:${mimeType};base64,` + buf.toString('base64');
      }
      _qnapCircuitRecord(false);
      console.warn(`[fasada-slika QNAP fail] ${qnapPath}: HTTP ${qr.status} → B2 fallback`);
    } catch(e) {
      _qnapCircuitRecord(false);
      console.warn(`[fasada-slika QNAP exception] ${qnapPath}:`, e.message);
    }
  }
  
  // ⭐ v258 (Ivan): Fasade-AI = SAMO QNAP i pri ČITANJU (v500 je ukinuo B2 upload za Fasade →
  
  //   B2 nema svježe Fasade slike; fallback bi servirao STARE verzije bez upozorenja ili null).
  
  if (cleanPath.startsWith('Fasade-AI/')) return null;

  
  // Pokušaj 2: B2 fallback
  if (b2Enabled()) {
    try {
      const buf = await b2FetchBuffer(cleanPath, 15000);
      if (buf) {
        console.log(`[fasada-slika B2 fallback OK] ${qnapPath}`);
        return `data:${mimeType};base64,` + buf.toString('base64');
      }
    } catch(e) {
      console.warn(`[fasada-slika B2 exception] ${qnapPath}:`, e.message);
    }
  }
  
  console.error(`[fasada-slika] OBA fail-ala: ${qnapPath}`);
  return null;
}

// GET /api/fasada/multi-procelje/:id — učitaj spremljenu multi-procjenu (s slikama iz QNAP-a)
app.get('/api/fasada/multi-procelje/:id', auth, staff, async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT id, gradiliste_id, naziv_objekta, tip_procjene, koncept, tip_objekta,
             dimenzije_fasade, bruto_fasada_m2, neto_fasada_m2, created_at, updated_at
      FROM fasade_procjene
      WHERE id = $1 AND koncept = 'homografija_multi'
    `, [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ error: 'Multi-knjiga ne postoji' });
    
    const proc = r.rows[0];
    
    // ── Hidriraj slike iz QNAP-a (ako su tamo) ──
    if (proc.dimenzije_fasade && Array.isArray(proc.dimenzije_fasade.procelja)) {
      const procelja = proc.dimenzije_fasade.procelja;
      
      // Paralelno dohvati sve slike (ne sekvencijalno — multiple QNAP-fetcheve odjednom)
      await Promise.all(procelja.map(async (p) => {
        // Originalna slika: ako nemamo base64 ali imamo qnap path → fetch
        if (!p.slika_base64 && p.slika_qnap_path) {
          const dataUrl = await _qnapFetchSlikaAsDataUrl(p.slika_qnap_path);
          if (dataUrl) p.slika_base64 = dataUrl;
        }
        // ⭐ v135.4: Hidriraj i hatch sliku (anotirana) iz QNAP-a
        //    Razlog: prije se dohvaćala samo originalna → hatch verzija nedostupna pri load-u
        if (!p.slika_anotirana && (p.slika_anotirana_qnap_path || p.slika_hatch_qnap_path)) {
          const hatchPath = p.slika_anotirana_qnap_path || p.slika_hatch_qnap_path;
          const dataUrl = await _qnapFetchSlikaAsDataUrl(hatchPath);
          if (dataUrl) p.slika_anotirana = dataUrl;
        }
      }));
      
      proc.dimenzije_fasade = { ...proc.dimenzije_fasade, procelja };
    }
    
    res.json(proc);
  } catch(e) {
    console.error('[multi-procelje load]', e);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// DELETE /api/fasada/multi-procelje/:id
// Briše multi-pročelje proceju iz DB + slike sa QNAP-a (folder gradilišta)
// ═══════════════════════════════════════════════════════════════════════════
app.delete('/api/fasada/multi-procelje/:id', auth, staff, async (req, res) => {
  try {
    const procjenaId = parseInt(req.params.id);
    
    // Dohvati paths + naziv gradilišta
    // ⭐ v135.7.255: proširen SELECT s B2 paths (orphan files fix)
    const r = await pool.query(`
      SELECT f.dimenzije_fasade, f.gradiliste_id, f.naziv_objekta,
             f.slika_b2_path, f.slika_hatch_b2_path, f.ai_anotirana_b2_path,
             f.pdf_b2_path, f.nacrt_pdf_b2_path, f.nacrt_folder,
             g.naziv AS grad_naziv
      FROM fasade_procjene f
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1 AND f.koncept = 'homografija_multi'
    `, [procjenaId]);
    
    if (!r.rows.length) return res.status(404).json({ error: 'Multi-knjiga ne postoji' });
    
    const dim = r.rows[0].dimenzije_fasade || {};
    const procelja = Array.isArray(dim.procelja) ? dim.procelja : [];
    const gradId = r.rows[0].gradiliste_id;
    const gradNaziv = r.rows[0].grad_naziv || '';
    const nacrtFolder = r.rows[0].nacrt_folder;
    
    // ⭐ v135.7.255: skupi B2 paths za cleanup
    const b2Paths = [];
    if (r.rows[0].slika_b2_path) b2Paths.push(r.rows[0].slika_b2_path);
    if (r.rows[0].slika_hatch_b2_path) b2Paths.push(r.rows[0].slika_hatch_b2_path);
    if (r.rows[0].ai_anotirana_b2_path) b2Paths.push(r.rows[0].ai_anotirana_b2_path);
    if (r.rows[0].pdf_b2_path) b2Paths.push(r.rows[0].pdf_b2_path);
    if (r.rows[0].nacrt_pdf_b2_path) b2Paths.push(r.rows[0].nacrt_pdf_b2_path);
    
    // Skupi sve QNAP path-eve + B2 paths iz pročelja
    const qnapPaths = [];
    procelja.forEach(p => {
      if (p.slika_qnap_path) qnapPaths.push(p.slika_qnap_path);
      if (p.slika_anotirana_qnap_path) qnapPaths.push(p.slika_anotirana_qnap_path);
      // ⭐ v135.7.255: B2 paths iz svakog pročelja
      if (p.slika_b2_path) b2Paths.push(p.slika_b2_path);
      if (p.slika_anotirana_b2_path) b2Paths.push(p.slika_anotirana_b2_path);
      if (p.slika_hatch_b2_path) b2Paths.push(p.slika_hatch_b2_path);
    });
    
    // ⭐ v295 (Ivan): Audit log NULL-uj procjena_id PRIJE brisanja procjene.
    //   Čuva povijest "tko je radio nešto" ali eliminira orphan retke (Backup test F3).
    try {
      await pool.query(
        `UPDATE fasada_aktivnost SET procjena_id = NULL 
         WHERE procjena_id = $1 
           AND akcija NOT IN ('obrisana', 'bulk_obrisano', 'obrisana_naknadno')`,
        [procjenaId]
      );
    } catch(_) { /* swallow — best effort */ }
    
    // Obriši iz DB
    await pool.query('DELETE FROM fasade_procjene WHERE id=$1', [procjenaId]);
    
    // Obriši sa QNAP-a + B2 (best-effort, ne blokira odgovor)
    if (process.env.QNAP_WEBDAV_URL || b2Enabled()) {
      setImmediate(async () => {
        try {
          // 1) QNAP: poznati path-eve iz DB - PARALELNO za brzinu
          if (process.env.QNAP_WEBDAV_URL) {
            await Promise.all(qnapPaths.map(async qpath => {
              try {
                const ok = await qnapDeleteFile(qpath);
                console.log(`[multi-procelje DELETE ${procjenaId}] QNAP ${qpath} → ${ok ? 'OBRISAN' : 'FAIL'}`);
              } catch(e) { console.warn('[multi-procelje DELETE QNAP]', qpath, e.message); }
            }));
            
            // 2) QNAP: Pattern-cleanup za orphan-e (multi{id}_*)
            if (gradNaziv) {
              const folder = fasadaQnapFolder(gradNaziv);
              const obrisanih = await qnapDeleteByPattern(folder, `multi${procjenaId}_`);
              console.log(`[multi-procelje DELETE ${procjenaId}] pattern multi${procjenaId}_: ${obrisanih} u ${folder}`);
            }
            
            // 2b) QNAP nacrt folder (ako ima)
            if (nacrtFolder && typeof nacrtFolder === 'string' && nacrtFolder.startsWith('Fasade-AI/')) {
              try {
                await qnapDeleteFolder(nacrtFolder);
                console.log(`[multi-procelje DELETE ${procjenaId}] QNAP nacrt folder: ${nacrtFolder} → OBRISAN`);
              } catch (e) {
                console.warn(`[multi-procelje DELETE ${procjenaId}] QNAP nacrt folder fail:`, e.message);
              }
            }
            
            // 3) QNAP: Provjeri ima li još procjena za to gradilište
            if (gradId) {
              const ostatakR = await pool.query(
                `SELECT COUNT(*) AS cnt FROM fasade_procjene WHERE gradiliste_id=$1`,
                [gradId]
              );
              const cnt = parseInt(ostatakR.rows[0]?.cnt || 0);
              if (cnt === 0 && gradNaziv) {
                const folder = fasadaQnapFolder(gradNaziv);
                await qnapDeleteFolder(folder);
                console.log(`[multi-procelje DELETE ${procjenaId}] QNAP folder ${folder} obrisan (zadnja knjiga)`);
              }
            }
          }
          
          // ⭐ v135.7.255: B2 CLOUD CLEANUP
          if (b2Enabled()) {
            // Individual B2 paths
            if (b2Paths.length > 0) {
              const results = await Promise.all(b2Paths.map(async (p) => {
                try {
                  const ok = await b2Delete(p);
                  return ok;
                } catch (e) {
                  console.warn(`[multi-procelje DELETE ${procjenaId}] B2 ${p}:`, e.message);
                  return false;
                }
              }));
              const ok = results.filter(Boolean).length;
              console.log(`[multi-procelje DELETE ${procjenaId}] B2 individual: ${ok}/${b2Paths.length} obrisano`);
            }
            
            // B2 nacrt folder (sve PNG stranice + original PDF)
            if (nacrtFolder && typeof nacrtFolder === 'string' && nacrtFolder.startsWith('Fasade-AI/')) {
              try {
                const stats = await b2DeleteByPrefix(nacrtFolder + '/');
                console.log(`[multi-procelje DELETE ${procjenaId}] B2 nacrt folder "${nacrtFolder}": ${stats.deleted} obrisano, ${stats.errors} grešaka`);
              } catch (eNacrt) {
                console.warn(`[multi-procelje DELETE ${procjenaId}] B2 nacrt folder fail:`, eNacrt.message);
              }
            }
          }
        } catch(e) {
          console.error('[multi-procelje DELETE cleanup]', e);
        }
      });
    }
    
    res.json({ ok: true, deleted_id: procjenaId, qnap_paths_count: qnapPaths.length, b2_paths_count: b2Paths.length });
    
    // ⭐ v132: Push notifikacija - Ivan vidi kad netko obriše multi procjenu
    logFasActivity(
      req.user,
      'obrisana',
      'multi-procelje',
      procjenaId,
      gradId || null,
      r.rows[0].naziv_objekta || gradNaziv || null,
      { broj_procelja: procelja.length }
    ).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
  } catch(e) {
    console.error('[multi-procelje DELETE]', e);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// POST /api/fasada/multi-procelje/:id/move
// Premjesti multi-pročelje proceju u drugo gradilište
// Filozofija: 1) upload na novi folder, 2) update DB, 3) delete sa starog
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/fasada/multi-procelje/:id/move', auth, staff, async (req, res) => {
  try {
    const procjenaId = parseInt(req.params.id);
    const noviGradId = parseInt(req.body?.gradiliste_id || 0);
    
    if (!noviGradId) return res.status(400).json({ error: 'Novi gradiliste_id obavezan' });
    
    // Dohvati postojeću proceju
    const r = await pool.query(`
      SELECT f.dimenzije_fasade, f.gradiliste_id, f.naziv_objekta,
             g.naziv AS stari_grad_naziv
      FROM fasade_procjene f
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1 AND f.koncept = 'homografija_multi'
    `, [procjenaId]);
    
    if (!r.rows.length) return res.status(404).json({ error: 'Multi-knjiga ne postoji' });
    
    const dim = r.rows[0].dimenzije_fasade || {};
    const procelja = Array.isArray(dim.procelja) ? dim.procelja : [];
    const stariGradId = r.rows[0].gradiliste_id;
    const stariGradNaziv = r.rows[0].stari_grad_naziv || '';
    
    if (stariGradId === noviGradId) {
      return res.json({ ok: true, message: 'Već je u tom gradilištu', moved: false });
    }
    
    // Dohvati naziv novog gradilišta
    const noviGradR = await pool.query('SELECT naziv FROM gradilista WHERE id=$1', [noviGradId]);
    const noviGradNaziv = noviGradR.rows[0]?.naziv;
    if (!noviGradNaziv) {
      return res.status(404).json({ error: 'Novo gradilište ne postoji' });
    }
    
    const noviFolder = fasadaQnapFolder(noviGradNaziv);
    const stariPaths = [];  // spremamo da kasnije obrišemo
    
    // ── 1) UPLOAD slika u NOVI folder gradilišta (ako QNAP dostupan) ──
    if (process.env.QNAP_WEBDAV_URL) {
      for (let idx = 0; idx < procelja.length; idx++) {
        const p = procelja[idx];
        
        // Original slika: dohvati sa starog QNAP-a, upload na novi
        if (p.slika_qnap_path) {
          stariPaths.push(p.slika_qnap_path);
          try {
            const dataUrl = await _qnapFetchSlikaAsDataUrl(p.slika_qnap_path);
            if (dataUrl) {
              const cleanB64 = dataUrl.replace(/^data:image\/[a-z]+;base64,/, '');
              const buf = Buffer.from(cleanB64, 'base64');
              const noviPath = `${noviFolder}/multi${procjenaId}_p${idx}.jpg`;
              const upPath = await qnapUploadImage(buf, noviPath);
              if (upPath) {
                p.slika_qnap_path = upPath;
                console.log(`[multi-procelje MOVE] p${idx}: ${stariPaths[stariPaths.length-1]} → ${upPath}`);
              }
            }
          } catch(e) {
            console.warn(`[multi-procelje MOVE p${idx} original]`, e.message);
          }
        }
        
        // Anotirana slika
        if (p.slika_anotirana_qnap_path) {
          stariPaths.push(p.slika_anotirana_qnap_path);
          try {
            const dataUrl = await _qnapFetchSlikaAsDataUrl(p.slika_anotirana_qnap_path);
            if (dataUrl) {
              const cleanB64 = dataUrl.replace(/^data:image\/[a-z]+;base64,/, '');
              const buf = Buffer.from(cleanB64, 'base64');
              const noviPath = `${noviFolder}/multi${procjenaId}_p${idx}_anot.jpg`;
              const upPath = await qnapUploadImage(buf, noviPath);
              if (upPath) {
                p.slika_anotirana_qnap_path = upPath;
              }
            }
          } catch(e) {
            console.warn(`[multi-procelje MOVE p${idx} anot]`, e.message);
          }
        }
      }
    }
    
    // ── 2) UPDATE DB: novi gradiliste_id + nove path-ove u dimenzijama ──
    const novaDim = { ...dim, procelja };
    await pool.query(`
      UPDATE fasade_procjene
      SET gradiliste_id = $1,
          naziv_objekta = $2,
          dimenzije_fasade = $3,
          updated_at = NOW()
      WHERE id = $4
    `, [noviGradId, noviGradNaziv, JSON.stringify(novaDim), procjenaId]);
    
    // ── 3) DELETE stare path-ove sa QNAP-a (best-effort, async) ──
    if (process.env.QNAP_WEBDAV_URL && stariPaths.length > 0) {
      setImmediate(async () => {
        for (const qpath of stariPaths) {
          try {
            const ok = await qnapDeleteFile(qpath);
            console.log(`[multi-procelje MOVE delete] ${qpath} → ${ok ? 'OBRISAN' : 'FAIL'}`);
          } catch(_) {}
        }
        
        // Ako stari gradilište više nema procjena → obriši folder
        if (stariGradId && stariGradNaziv) {
          try {
            const ostatakR = await pool.query(
              `SELECT COUNT(*) AS cnt FROM fasade_procjene WHERE gradiliste_id=$1`,
              [stariGradId]
            );
            const cnt = parseInt(ostatakR.rows[0]?.cnt || 0);
            if (cnt === 0) {
              const stariFolder = fasadaQnapFolder(stariGradNaziv);
              await qnapDeleteFolder(stariFolder);
              console.log(`[multi-procelje MOVE] obrisan stari folder ${stariFolder} (prazno)`);
            }
          } catch(_) {}
        }
      });
    }
    
    res.json({
      ok: true,
      moved: true,
      from_gradiliste_id: stariGradId,
      to_gradiliste_id: noviGradId,
      to_gradiliste_naziv: noviGradNaziv,
      qnap_paths_moved: stariPaths.length
    });
    
    // ⭐ v132: Push notifikacija - Ivan vidi kad netko premjesti procjenu
    logFasActivity(
      req.user,
      'azurirana',
      'multi-procelje',
      procjenaId,
      noviGradId,
      `${r.rows[0].naziv_objekta || ''} → ${noviGradNaziv}`,
      { premjesteno_iz: stariGradNaziv, premjesteno_u: noviGradNaziv }
    ).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));
  } catch(e) {
    console.error('[multi-procelje MOVE]', e);
    res.status(500).json({ error: e.message });
  }
});

// GET /api/fasada/multi-procelje/gradiliste/:gid — sve multi-procjene za gradilište
app.get('/api/fasada/multi-procelje/gradiliste/:gid', auth, staff, async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT id, naziv_objekta, bruto_fasada_m2, neto_fasada_m2,
             jsonb_array_length(COALESCE(dimenzije_fasade->'procelja', '[]'::jsonb)) AS broj_procelja,
             created_at, updated_at
      FROM fasade_procjene
      WHERE gradiliste_id = $1 AND koncept = 'homografija_multi'
      ORDER BY created_at DESC
    `, [req.params.gid]);
    res.json(r.rows);
  } catch(e) {
    console.error('[multi-procelje gradiliste]', e);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// MULTI-PROČELJE: GET /api/fasada/multi-procelje/preview/:id?token=...
// Generira HTML preview za PDF print (A4 portrait, multi-pročelje).
// Klijent otvori u novom tabu, browser "Ispiši → Spremi kao PDF" daje finalni PDF.
// ═══════════════════════════════════════════════════════════════════════════
app.get('/api/fasada/multi-procelje/preview/:id', async (req, res) => {
  try {
    let user = null;
    const _hdrTok = req.headers.authorization?.replace('Bearer ', '');
    if (_hdrTok) { try { user = jwt.verify(_hdrTok, JWT_SECRET); } catch(_) {} }
    if (!user) user = await _userFromMediaToken(req.query.mt || req.query.token);  // ⭐ v219: URL nosi media token, ne JWT
    if (!user) return res.status(401).send('<h1>401 — Token nevažeći</h1>');
    
    const procjenaId = parseInt(req.params.id);
    if (!Number.isFinite(procjenaId)) return res.status(400).send('<h1>400 — Nevažeći ID</h1>');
    
    const procR = await pool.query(`
      SELECT f.*, rad.ime || ' ' || rad.prezime AS kreirao,
             g.naziv AS grad_naziv, g.adresa AS grad_adresa
      FROM fasade_procjene f
      LEFT JOIN radnici rad ON rad.id = f.kreirao_id
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1 AND f.koncept = 'homografija_multi'
    `, [procjenaId]);
    
    if (!procR.rows.length) return res.status(404).send('<h1>404 — Multi-knjiga ne postoji</h1>');
    
    const f = procR.rows[0];
    const dim = typeof f.dimenzije_fasade === 'string' 
      ? JSON.parse(f.dimenzije_fasade) 
      : (f.dimenzije_fasade || {});
    const procelja = Array.isArray(dim.procelja) ? dim.procelja : [];
    
    if (procelja.length === 0) {
      return res.status(404).send('<h1>404 — Knjiga ne sadrži nacrta</h1>');
    }
    
    const datum = fmtDate(new Date(f.created_at));
    const datumKreiran = fmtDate(f.created_at, { time: true });
    
    const escapeHtml = (s) => String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const fmtBr = (n) => n != null && Number.isFinite(parseFloat(n)) 
      ? parseFloat(n).toLocaleString('hr-HR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '–';
    
    // Tip mapping
    const tipObjektaLabel = {
      'stambena_zgrada': 'Stambena zgrada',
      'obiteljska_kuca': 'Obiteljska kuća',
      'poslovni_prostor': 'Poslovni prostor',
      'industrijski_objekt': 'Industrijski objekt',
      'ostalo': 'Ostalo'
    }[dim.tip_objekta || ''] || dim.tip_objekta || '–';
    
    // Sumarno
    let sumBruto = 0, sumNetoCisti = 0, sumNetoGN421 = 0, sumOtvori = 0;
    procelja.forEach(p => {
      const r = p.rezultat || {};
      sumBruto += parseFloat(r.bruto_m2 || 0);
      sumNetoCisti += parseFloat(r.neto_cisti_m2 || 0);
      sumNetoGN421 += parseFloat(r.neto_gn421_m2 || 0);
      sumOtvori += parseInt(r.broj_otvora || 0);
    });
    
    // Generiraj HTML za svako pročelje
    const proceljaHtml = procelja.map((p, idx) => {
      const r = p.rezultat || {};
      const pravo = p.pravokutnik || {};
      const otvori = Array.isArray(r.otvori_detaljno) ? r.otvori_detaljno : [];
      
      // ⭐ v132: Slika src - uvijek koristi ORIGINAL pa klijent JS crta overlay
      //    (radi i za stare procjene bez anotirana_qnap_path)
      let slikaSrc = '';
      if (p.slika_qnap_path) {
        slikaSrc = `/api/fasada/multi-procelje/${procjenaId}/slika/${idx}?token=${encodeURIComponent(token)}`;
      } else if (p.slika_anotirana_qnap_path) {
        // Fallback ako original ne postoji
        slikaSrc = `/api/fasada/multi-procelje/${procjenaId}/slika/${idx}/anotirana?token=${encodeURIComponent(token)}`;
      } else if (p.slika_base64 && p.slika_base64.length > 100) {
        slikaSrc = p.slika_base64.startsWith('data:') ? p.slika_base64 : `data:image/jpeg;base64,${p.slika_base64}`;
      }
      
      // ⭐ v132: Embed overlay data za klijent JS render
      const overlayData = JSON.stringify({
        konture: r.konture_facade_px || null,
        pravokutnik: (pravo.kutovi_px && pravo.sirina_m && pravo.visina_m) ? {
          kutovi_px: pravo.kutovi_px,
          sirina_m: pravo.sirina_m,
          visina_m: pravo.visina_m
        } : null,
        otvori: otvori.filter(o => o.kutovi_px && o.kutovi_px.length === 4 && o.izvor !== 'referentni_pravokutnik'),
        bruto_m2: parseFloat(r.bruto_m2) || 0
      }).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
      
      const otvoriRows = otvori.map((ot, oi) => `
        <tr>
          <td>P${oi+1}</td>
          <td>${escapeHtml(ot.tip || 'otvor')}</td>
          <td style="text-align:right">${fmtBr(ot.sirina_m)} × ${fmtBr(ot.visina_m)} m</td>
          <td style="text-align:right">${fmtBr(ot.povrsina_m2)} m²</td>
        </tr>`).join('');
      
      return `
        <div class="page-break"></div>
        <section class="procelje">
          <div class="proc-header">
            <div class="proc-naslov">Nacrt ${idx + 1} · ${escapeHtml(p.oznaka || '–')}</div>
            <div class="proc-meta">${otvori.length} otvora · bruto ${fmtBr(r.bruto_m2)} m²</div>
          </div>
          
          ${slikaSrc ? `<div class="slika-wrap"><canvas class="slika-canvas" data-src="${slikaSrc}" data-overlay="${overlayData}" data-idx="${idx+1}"></canvas></div>` : '<div class="bez-slike">Nema slike</div>'}
          
          <div class="kalibracija-blok">
            <div class="kalibracija-naslov">📐 Kalibracija (referentni pravokutnik)</div>
            <table class="kalib-tbl">
              <tr><td>Tip</td><td><b>${escapeHtml(pravo.tip || '–')}</b></td></tr>
              <tr><td>Dimenzije</td><td><b>${fmtBr(pravo.sirina_m)} × ${fmtBr(pravo.visina_m)} m</b></td></tr>
            </table>
          </div>
          
          <div class="rezultat-blok">
            <div class="rezultat-naslov">📊 Rezultat AI knjige</div>
            <table class="rezultat-tbl">
              <tr><td>Bruto površina</td><td class="num">${fmtBr(r.bruto_m2)} m²</td></tr>
              <tr><td>Površina otvora (${r.broj_otvora || 0})</td><td class="num">${fmtBr(r.otvori_m2 || 0)} m²</td></tr>
              <tr class="hl"><td>Neto čisti</td><td class="num">${fmtBr(r.neto_cisti_m2)} m²</td></tr>
              <tr class="hl-gn"><td>Neto GN 421</td><td class="num">${fmtBr(r.neto_gn421_m2)} m²</td></tr>
            </table>
          </div>
          
          ${otvoriRows ? `
          <div class="otvori-blok">
            <div class="otvori-naslov">🪟 Detektirani otvori (${otvori.length})</div>
            <table class="otvori-tbl">
              <thead>
                <tr><th>#</th><th>Tip</th><th>Dimenzije</th><th>Površina</th></tr>
              </thead>
              <tbody>${otvoriRows}</tbody>
            </table>
          </div>` : ''}
          
          ${p.napomena ? `<div class="napomena">📝 ${escapeHtml(p.napomena)}</div>` : ''}
        </section>`;
    }).join('');
    
    const objektNaziv = f.naziv_objekta || f.grad_naziv || 'Knjiga fasade';
    
    const html = `<!DOCTYPE html>
<html lang="hr">
<head>
  <meta charset="UTF-8">
  <title>Knjiga #${procjenaId} — ${escapeHtml(objektNaziv)}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    @page { size: A4 portrait; margin: 12mm 14mm; }
    @media print {
      body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
      .no-print { display: none !important; }
      .page-break { page-break-before: always; break-before: page; }
      .procelje { page-break-inside: avoid; break-inside: avoid; }
    }
    * { box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; color: #0f172a; margin: 0; padding: 0; line-height: 1.4; font-size: 11px; }
    .container { max-width: 800px; margin: 0 auto; padding: 16px; }
    .no-print { background: linear-gradient(135deg, #0f172a, #1e293b); color: #fff; padding: 14px 18px; border-radius: 10px; margin-bottom: 18px; display: flex; justify-content: space-between; align-items: center; gap: 14px; }
    .no-print button { padding: 9px 18px; background: linear-gradient(135deg, #d97706, #b45309); border: none; color: #fff; border-radius: 6px; cursor: pointer; font-weight: 700; font-size: 13px; box-shadow: 0 2px 8px rgba(0,0,0,0.2); }
    .no-print button:hover { transform: translateY(-1px); }
    .header { background: linear-gradient(135deg, #0f172a, #1e3a8a); color: #fff; padding: 18px 22px; border-radius: 8px; margin-bottom: 14px; }
    .header h1 { margin: 0 0 6px; font-size: 22px; font-weight: 800; letter-spacing: 0.3px; }
    .header .meta-row { display: flex; gap: 16px; flex-wrap: wrap; font-size: 11px; opacity: 0.9; margin-top: 8px; }
    .header .meta-row span { white-space: nowrap; }
    .header .meta-row b { color: #fcd34d; }
    
    .info-blok { background: #f3f4f6; border: 1px solid #d1d5db; border-radius: 6px; padding: 10px 14px; margin-bottom: 14px; font-size: 11px; }
    .info-row { display: flex; justify-content: space-between; padding: 3px 0; border-bottom: 1px dashed #d1d5db; }
    .info-row:last-child { border-bottom: none; }
    .info-row span:first-child { color: #6b7280; }
    .info-row span:last-child { font-weight: 700; color: #0f172a; }
    
    .sumarno-blok { background: linear-gradient(135deg, #d97706, #b45309); color: #fff; border-radius: 8px; padding: 12px 16px; margin-bottom: 18px; }
    .sumarno-naslov { font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; opacity: 0.9; margin-bottom: 8px; font-weight: 700; }
    .sumarno-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
    .sumarno-cell { text-align: center; }
    .sumarno-cell .label { font-size: 9px; text-transform: uppercase; opacity: 0.85; }
    .sumarno-cell .val { font-size: 16px; font-weight: 800; margin-top: 2px; }
    
    .procelje { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 14px 16px; margin-bottom: 16px; }
    .proc-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 2px solid #d97706; }
    .proc-naslov { font-size: 14px; font-weight: 800; color: #0f172a; }
    .proc-meta { font-size: 10px; color: #6b7280; }
    .slika-wrap { text-align: center; margin: 10px 0; background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 6px; padding: 6px; }
    .slika-wrap img { max-width: 100%; max-height: 280px; border-radius: 4px; }
    .slika-wrap canvas { max-width: 100%; max-height: 280px; border-radius: 4px; height: auto; }
    .bez-slike { text-align: center; padding: 30px; background: #f9fafb; border: 2px dashed #d1d5db; border-radius: 6px; color: #9ca3af; font-style: italic; margin: 10px 0; }
    
    .kalibracija-blok, .rezultat-blok, .otvori-blok { margin: 10px 0; }
    .kalibracija-naslov, .rezultat-naslov, .otvori-naslov { font-size: 10.5px; text-transform: uppercase; font-weight: 700; color: #0f172a; margin-bottom: 6px; letter-spacing: 0.3px; }
    
    table { width: 100%; border-collapse: collapse; font-size: 10.5px; }
    .kalib-tbl td, .rezultat-tbl td { padding: 5px 8px; border-bottom: 1px solid #e5e7eb; }
    .kalib-tbl td:first-child, .rezultat-tbl td:first-child { color: #6b7280; }
    .rezultat-tbl .num { text-align: right; font-weight: 700; }
    .rezultat-tbl tr.hl td { background: rgba(34,197,94,0.10); color: #15803d; font-weight: 700; }
    .rezultat-tbl tr.hl-gn td { background: rgba(59,130,246,0.10); color: #1e40af; font-weight: 700; }
    
    .otvori-tbl thead th { background: #0f172a; color: #fff; padding: 6px 8px; text-align: left; font-size: 10px; text-transform: uppercase; }
    .otvori-tbl thead th:nth-child(3), .otvori-tbl thead th:nth-child(4) { text-align: right; }
    .otvori-tbl tbody tr:nth-child(even) { background: #f9fafb; }
    .otvori-tbl tbody td { padding: 5px 8px; border-bottom: 1px solid #e5e7eb; }
    
    .napomena { background: #fef3c7; border-left: 3px solid #d97706; padding: 8px 12px; margin-top: 10px; font-size: 10.5px; color: #78350f; border-radius: 0 4px 4px 0; }
    
    .footer { text-align: center; margin-top: 24px; padding: 14px; border-top: 2px solid #0f172a; font-size: 10px; color: #6b7280; }
    .footer b { color: #0f172a; }
  </style>
</head>
<body>
  <div class="container">
    <div class="no-print">
      <div>
        <div style="font-weight:700;font-size:14px">📄 Pregled knjige #${procjenaId}</div>
        <div style="font-size:11px;opacity:0.7;margin-top:3px">Klikni "Ispiši PDF" → u dialogu odaberi "Spremi kao PDF"</div>
      </div>
      <button onclick="window.print()">🖨️ Ispiši PDF</button>
    </div>
    
    <div class="header">
      <h1>${escapeHtml(objektNaziv)}</h1>
      <div class="meta-row">
        <span>Knjiga <b>#${procjenaId}</b></span>
        <span>Tip: <b>${tipObjektaLabel}</b></span>
        <span>Nacrti: <b>${procelja.length}</b></span>
        <span>Datum: <b>${datum}</b></span>
      </div>
    </div>
    
    <div class="info-blok">
      ${f.grad_naziv ? `<div class="info-row"><span>Gradilište</span><span>${escapeHtml(f.grad_naziv)}</span></div>` : ''}
      ${f.grad_adresa ? `<div class="info-row"><span>Adresa</span><span>${escapeHtml(f.grad_adresa)}</span></div>` : ''}
      ${f.kreirao ? `<div class="info-row"><span>Kreirao</span><span>${escapeHtml(f.kreirao)}</span></div>` : ''}
      <div class="info-row"><span>Vrijeme kreiranja</span><span>${datumKreiran}</span></div>
      ${dim.napomena_glavna ? `<div class="info-row"><span>Napomena</span><span>${escapeHtml(dim.napomena_glavna)}</span></div>` : ''}
    </div>
    
    <div class="sumarno-blok">
      <div class="sumarno-naslov">📊 Sumarno · sva nacrta</div>
      <div class="sumarno-grid">
        <div class="sumarno-cell">
          <div class="label">Bruto fasada</div>
          <div class="val">${fmtBr(sumBruto)} m²</div>
        </div>
        <div class="sumarno-cell">
          <div class="label">Otvori (broj)</div>
          <div class="val">${sumOtvori}</div>
        </div>
        <div class="sumarno-cell">
          <div class="label">Neto čisti</div>
          <div class="val">${fmtBr(sumNetoCisti)} m²</div>
        </div>
        <div class="sumarno-cell">
          <div class="label">Neto GN 421</div>
          <div class="val">${fmtBr(sumNetoGN421)} m²</div>
        </div>
      </div>
    </div>
    
    ${proceljaHtml}
    
    <div class="footer">
      <b>ŽBUKA Čakarić d.o.o.</b> · Fasaderski i žbukarski radovi, Zagreb<br>
      Multi-nacrt AI knjiga · Generirano automatski · ${datumKreiran}
    </div>
  </div>
  
  <!-- ⭐ v132: Klijent JS - render canvas overlay (polygon hatch + ref + otvori s mjerama + numeracija) -->
  <script>
    function drawHatch(ctx, kutovi, color, lineWidth, gap) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(kutovi[0].x, kutovi[0].y);
      for (let i = 1; i < kutovi.length; i++) ctx.lineTo(kutovi[i].x, kutovi[i].y);
      ctx.closePath();
      ctx.clip();
      const xs = kutovi.map(k => k.x), ys = kutovi.map(k => k.y);
      const minX = Math.min(...xs), maxX = Math.max(...xs);
      const minY = Math.min(...ys), maxY = Math.max(...ys);
      ctx.strokeStyle = color;
      ctx.lineWidth = lineWidth;
      const range = (maxX - minX) + (maxY - minY);
      for (let off = -range; off <= range; off += gap) {
        ctx.beginPath();
        ctx.moveTo(minX + off, minY);
        ctx.lineTo(minX + off + (maxY - minY), maxY);
        ctx.stroke();
      }
      ctx.restore();
    }
    
    function renderCanvasOverlay(canvas) {
      const src = canvas.dataset.src;
      const overlayStr = canvas.dataset.overlay;
      if (!src || !overlayStr) return;
      
      let overlay;
      try { overlay = JSON.parse(overlayStr.replace(/&quot;/g, '"').replace(/&#39;/g, "'")); } catch(e) { return; }
      
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        
        // 1. Polygon konture (zeleni hatch + outline)
        if (Array.isArray(overlay.konture) && overlay.konture.length >= 3) {
          const poly = overlay.konture;
          const polyXs = poly.map(p => p.x), polyYs = poly.map(p => p.y);
          const polyMinX = Math.min.apply(null, polyXs);
          const polyMaxX = Math.max.apply(null, polyXs);
          const polyMinY = Math.min.apply(null, polyYs);
          const polyMaxY = Math.max.apply(null, polyYs);
          
          // Hatch unutar
          const polyGap = Math.max(14, canvas.width / 80);
          const polyLW = Math.max(1.5, canvas.width / 600);
          drawHatch(ctx, poly, 'rgba(34,197,94,0.45)', polyLW, polyGap);
          
          // Outline
          ctx.strokeStyle = '#22c55e';
          ctx.lineWidth = Math.max(3, canvas.width / 250);
          ctx.setLineDash([12, 8]);
          ctx.fillStyle = 'rgba(34,197,94,0.10)';
          ctx.beginPath();
          ctx.moveTo(poly[0].x, poly[0].y);
          for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i].x, poly[i].y);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();
          ctx.setLineDash([]);
          
          // Label "PROČELJE: X m²"
          if (overlay.bruto_m2) {
            const cx = (polyMinX + polyMaxX) / 2;
            const cy = polyMinY + Math.max(20, canvas.height / 50);
            const polyFs = Math.max(13, canvas.width / 75);
            ctx.font = 'bold ' + polyFs + 'px sans-serif';
            const polyLabel = 'NACRT · ' + overlay.bruto_m2.toFixed(1) + ' m² bruto';
            const polyW = ctx.measureText(polyLabel).width + 16;
            ctx.fillStyle = 'rgba(34,197,94,0.95)';
            ctx.fillRect(cx - polyW/2, cy - polyFs/2 - 4, polyW, polyFs + 8);
            ctx.fillStyle = '#fff';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(polyLabel, cx, cy);
          }
        }
        
        // 2. Ref pravokutnik (ljubičasti)
        if (overlay.pravokutnik && overlay.pravokutnik.kutovi_px) {
          const k = overlay.pravokutnik.kutovi_px;
          if (k.every(p => p && Number.isFinite(p.x) && Number.isFinite(p.y))) {
            ctx.strokeStyle = '#a855f7';
            ctx.lineWidth = Math.max(3, canvas.width / 300);
            ctx.fillStyle = 'rgba(168,85,247,0.20)';
            ctx.beginPath();
            ctx.moveTo(k[0].x, k[0].y);
            ctx.lineTo(k[1].x, k[1].y);
            ctx.lineTo(k[2].x, k[2].y);
            ctx.lineTo(k[3].x, k[3].y);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
            
            const cx = (k[0].x + k[1].x + k[2].x + k[3].x) / 4;
            const cy = (k[0].y + k[1].y + k[2].y + k[3].y) / 4;
            const refLabel = 'REF · ' + overlay.pravokutnik.sirina_m + '×' + overlay.pravokutnik.visina_m + 'm';
            const refFs = Math.max(11, canvas.width / 90);
            ctx.font = 'bold ' + refFs + 'px sans-serif';
            const refW = ctx.measureText(refLabel).width + 14;
            ctx.fillStyle = '#a855f7';
            ctx.fillRect(cx - refW/2, cy - refFs/2 - 4, refW, refFs + 8);
            ctx.fillStyle = '#fff';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(refLabel, cx, cy);
          }
        }
        
        // 3. Otvori s hatchom + numeracija + kotirane mjere
        if (Array.isArray(overlay.otvori) && overlay.otvori.length > 0) {
          const otvFs = Math.max(13, canvas.width / 80);
          const kotaFs = Math.max(10, canvas.width / 100);
          
          overlay.otvori.forEach((ot, i) => {
            const ok = ot.kutovi_px;
            
            // Outline + fill
            ctx.strokeStyle = '#dc2626';
            ctx.lineWidth = Math.max(3, canvas.width / 350);
            ctx.fillStyle = 'rgba(239,68,68,0.10)';
            ctx.beginPath();
            ctx.moveTo(ok[0].x, ok[0].y);
            ctx.lineTo(ok[1].x, ok[1].y);
            ctx.lineTo(ok[2].x, ok[2].y);
            ctx.lineTo(ok[3].x, ok[3].y);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
            
            // Hatch
            const hatchGap = Math.max(6, canvas.width / 250);
            const hatchLW = Math.max(1.2, canvas.width / 700);
            drawHatch(ctx, ok, 'rgba(220,38,38,0.65)', hatchLW, hatchGap);
            
            // Kotirane mjere
            const xs = ok.map(p => p.x), ys = ok.map(p => p.y);
            const otMinX = Math.min.apply(null, xs);
            const otMaxX = Math.max.apply(null, xs);
            const otMinY = Math.min.apply(null, ys);
            const otMaxY = Math.max.apply(null, ys);
            const cx = (otMinX + otMaxX) / 2;
            const cy = (otMinY + otMaxY) / 2;
            const sirina = parseFloat(ot.sirina_m) || 0;
            const visina = parseFloat(ot.visina_m) || 0;
            
            ctx.font = 'bold ' + kotaFs + 'px sans-serif';
            
            // Širina iznad
            if (sirina > 0) {
              const sirText = sirina.toFixed(2) + 'm';
              const sirW = ctx.measureText(sirText).width + 8;
              const sirX = cx - sirW/2;
              const sirY = otMinY - kotaFs - 6;
              ctx.fillStyle = 'rgba(220,38,38,0.92)';
              ctx.fillRect(sirX, sirY, sirW, kotaFs + 4);
              ctx.fillStyle = '#fff';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              ctx.fillText(sirText, cx, sirY + kotaFs/2 + 2);
            }
            
            // Visina lijevo
            if (visina > 0) {
              const visText = visina.toFixed(2) + 'm';
              const visW = ctx.measureText(visText).width + 8;
              const visX = otMinX - visW - 6;
              const visY = cy - kotaFs/2 - 2;
              if (visX > 0) {
                ctx.fillStyle = 'rgba(220,38,38,0.92)';
                ctx.fillRect(visX, visY, visW, kotaFs + 4);
                ctx.fillStyle = '#fff';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(visText, visX + visW/2, cy);
              }
            }
            
            // Numeracija (P1, P2... velik krug)
            ctx.font = 'bold ' + otvFs + 'px sans-serif';
            const otCircleR = Math.max(20, canvas.width / 70);
            ctx.beginPath();
            ctx.arc(cx, cy, otCircleR, 0, 2 * Math.PI);
            ctx.fillStyle = 'rgba(220,38,38,0.95)';
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = Math.max(2, canvas.width / 600);
            ctx.stroke();
            ctx.fillStyle = '#fff';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('P' + (i+1), cx, cy);
          });
        }
      };
      img.onerror = () => {
        // Fallback: pokušaj bez crossOrigin
        const fallbackImg = new Image();
        fallbackImg.onload = function() {
          canvas.width = fallbackImg.naturalWidth;
          canvas.height = fallbackImg.naturalHeight;
          canvas.getContext('2d').drawImage(fallbackImg, 0, 0);
        };
        fallbackImg.src = src;
      };
      img.src = src;
    }
    
    // Render sve canvas-e nakon load
    document.addEventListener('DOMContentLoaded', function() {
      const canvases = document.querySelectorAll('canvas.slika-canvas');
      canvases.forEach(renderCanvasOverlay);
    });
    if (document.readyState !== 'loading') {
      document.querySelectorAll('canvas.slika-canvas').forEach(renderCanvasOverlay);
    }
  </script>
</body>
</html>`;
    
    res.set('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  } catch(e) {
    console.error('[multi-procelje preview]', e);
    res.status(500).send(`<h1>500 — ${e.message}</h1>`);
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// MULTI-PROČELJE: GET /api/fasada/multi-procelje/:id/slika/:idx[/anotirana]
// Servira sliku pročelja (iz QNAP-a) za <img> tag u PDF preview-u.
// ═══════════════════════════════════════════════════════════════════════════
app.get('/api/fasada/multi-procelje/:id/slika/:idx/:tip?', async (req, res) => {
  try {
    let _ok = false;
    const _hdrTok = req.headers.authorization?.replace('Bearer ', '');
    if (_hdrTok) { try { jwt.verify(_hdrTok, JWT_SECRET); _ok = true; } catch(_) {} }
    if (!_ok && await _userFromMediaToken(req.query.mt || req.query.token)) _ok = true;  // ⭐ v219: media token
    if (!_ok) return res.status(401).send('401');
    
    const procjenaId = parseInt(req.params.id);
    const idx = parseInt(req.params.idx);
    const tip = req.params.tip || 'original';
    
    const procR = await pool.query(`SELECT dimenzije_fasade FROM fasade_procjene WHERE id = $1`, [procjenaId]);
    if (!procR.rows.length) return res.status(404).send('404');
    
    const dim = typeof procR.rows[0].dimenzije_fasade === 'string'
      ? JSON.parse(procR.rows[0].dimenzije_fasade)
      : procR.rows[0].dimenzije_fasade;
    const procelja = Array.isArray(dim?.procelja) ? dim.procelja : [];
    const p = procelja[idx];
    if (!p) return res.status(404).send('404');
    
    const qnapPath = tip === 'anotirana' ? p.slika_anotirana_qnap_path : p.slika_qnap_path;
    
    // Pokušaj iz base64 ako je u JSON-u (fallback)
    if (!qnapPath && p.slika_base64) {
      // ⭐ v135.7.502.20.64: zadrži stvarni MIME iz data-URI prefiksa (jpg/webp/png)
      const mimeMatch = String(p.slika_base64).match(/^data:(image\/[a-z]+);base64,/);
      const b64 = p.slika_base64.replace(/^data:image\/[a-z]+;base64,/, '');
      const buf = Buffer.from(b64, 'base64');
      res.set('Content-Type', mimeMatch ? mimeMatch[1] : 'image/jpeg');
      return res.send(buf);
    }
    
    if (!qnapPath) return res.status(404).send('404');
    
    // Skini sa QNAP-a
    try {
      const fileBuf = await _qnapFetchBufferZaPath(qnapPath);
      res.set('Content-Type', extToContentType(qnapPath)); // ⭐ v135.7.502.20.64: format iz ekstenzije
      res.set('Cache-Control', 'private, max-age=300');
      return res.send(fileBuf);
    } catch(e) {
      return res.status(500).send('QNAP fail: ' + e.message);
    }
  } catch(e) {
    console.error('[multi-procelje slika]', e);
    res.status(500).send(e.message);
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// MULTI-PROČELJE: POST /api/fasada/export/excel/multi-procelje
// Frontend-driven export — prima detaljnu multi-procjenu (još ne spremljenu u DB)
// Vraća Excel s 1 sumarni sheet + N pročelje sheet-ova.
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/fasada/export/excel/multi-procelje', auth, staff, async (req, res) => {
  try {
    const ExcelJS = require('exceljs');
    const { id: multiId, naziv_objekta, tip_objekta, napomena, procelja, gradiliste_id } = req.body || {};
    
    if (!Array.isArray(procelja) || procelja.length === 0) {
      return res.status(400).json({ error: 'Nema nacrta za export' });
    }
    
    // Dohvati naziv + adresu gradilišta za QNAP folder + branded header
    let gradNaziv = null, gradAdresa = null, kreirao = req.user?.ime || 'Ivan Čakarić';
    if (gradiliste_id) {
      try {
        const gr = await pool.query(`SELECT naziv, adresa FROM gradilista WHERE id=$1`, [gradiliste_id]);
        gradNaziv = gr.rows[0]?.naziv || null;
        gradAdresa = gr.rows[0]?.adresa || null;
      } catch(_) {}
    }
    
    // ─── BOJE (kao u single brzi Excel-u) ───
    const RED = 'FFCC0000';
    const DARK = 'FF1a1a2e';
    const LBKG = 'FFf8f9fa';
    const BORD = 'FFdee2e6';
    const GREEN = 'FF10B981';
    const ORANGE = 'FFEA580C';
    const BLUE = 'FF0891B2';
    
    const datum = new Date();
    const datumFormat = fmtDate(datum);
    
    const wb = new ExcelJS.Workbook();
    wb.creator = 'ŽBUKA Čakarić d.o.o.';
    wb.created = datum;
    
    // Logo (jednom u workbook-u, koristi se u svim sheetovima)
    let logoImageId = null;
    try {
      logoImageId = wb.addImage({
        base64: 'data:image/png;base64,' + LOGO_B64,
        extension: 'png',
      });
    } catch(_) {}
    
    // ═════════════════════════════════════════════════════════════════
    // SHEET 1: SUMARNA — branded header + tablica pročelja + ukupno
    // ═════════════════════════════════════════════════════════════════
    const ws = wb.addWorksheet('Sumarna knjiga', {
      pageSetup: {
        paperSize: 9, orientation: 'landscape', fitToPage: true,
        fitToWidth: 1, fitToHeight: 0,
        margins: { left: 0.5, right: 0.5, top: 0.6, bottom: 0.5, header: 0.25, footer: 0.25 }
      }
    });
    // Šire stupce da brojevi ne prikazuju #### (m² s decimalama trebaju ~14 znakova)
    ws.columns = [
      { width: 14 }, { width: 24 }, { width: 14 }, { width: 14 },
      { width: 14 }, { width: 16 }, { width: 17 }, { width: 12 },
    ];
    
    let r = 1;
    
    // ── HEADER: logo + naslov ──
    ws.getRow(r).height = 60;
    if (logoImageId !== null) {
      try {
        ws.addImage(logoImageId, {
          tl: { col: 0.1, row: r - 1 + 0.1 },
          ext: { width: 100, height: 50 }
        });
      } catch(_) {}
    }
    ws.mergeCells(r, 3, r, 8);
    const cT = ws.getCell(r, 3);
    cT.value = 'OBRAČUN GRAĐEVINSKIH RADOVA';
    cT.font = { bold: true, size: 14, color: { argb: RED } };
    cT.alignment = { horizontal: 'right', vertical: 'middle' };
    r++;
    ws.mergeCells(r, 3, r, 8);
    const cT2 = ws.getCell(r, 3);
    cT2.value = '(AI knjiga · Multi-nacrt · Sumarna)';
    cT2.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
    cT2.alignment = { horizontal: 'right' };
    r++;
    
    // Crveni separator
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
    ws.getRow(r).height = 4;
    r++;
    
    // Razmak
    ws.getRow(r).height = 5; r++;
    
    // ── INFO BLOK ──
    const infoRows = [
      ['Gradilište:', gradNaziv || naziv_objekta || '?', 'Datum knjige:', datumFormat],
      ['Adresa:',     gradAdresa || '-', 'Broj nacrta:', String(procelja.length)],
      ['Izvođač:',    'ŽBUKA Čakarić d.o.o.', 'Voditelj:', kreirao],
      ['OIB:',        '46540647857', 'Tip objekta:', FAS_TIP_OBJEKTA_LABELS[tip_objekta] || '-'],
    ];
    infoRows.forEach(row => {
      ws.getCell(r, 1).value = row[0];
      ws.getCell(r, 1).font = { bold: true, size: 10 };
      ws.mergeCells(r, 2, r, 4);
      ws.getCell(r, 2).value = row[1];
      ws.getCell(r, 2).font = { size: 10 };
      ws.getCell(r, 5).value = row[2];
      ws.getCell(r, 5).font = { bold: true, size: 10 };
      ws.mergeCells(r, 6, r, 8);
      ws.getCell(r, 6).value = row[3];
      ws.getCell(r, 6).font = { size: 10 };
      ws.getRow(r).height = 16;
      r++;
    });
    
    if (napomena) {
      ws.getRow(r).height = 5; r++;
      ws.getCell(r, 1).value = 'Napomena:';
      ws.getCell(r, 1).font = { bold: true, size: 10 };
      ws.mergeCells(r, 2, r, 8);
      ws.getCell(r, 2).value = napomena;
      ws.getCell(r, 2).font = { size: 10, italic: true };
      ws.getCell(r, 2).alignment = { wrapText: true, vertical: 'middle' };
      ws.getRow(r).height = 30;
      r++;
    }
    
    ws.getRow(r).height = 8; r++;
    
    // ── TABLICA PROČELJA ──
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = 'PREGLED NACRTI';
    ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 20;
    r++;
    
    // ⭐ v135.7.22 (Ivanov koncept): NETO GN 421 prikazan prvi (formalna obračun), Netto odbitak (narudžba) ispod
    const tblHeaders = ['#', 'Oznaka', 'Bruto m²', 'Otvori m²', 'Otvori kom', 'NETO GN 421 m²', 'Netto odbitak m²', ''];
    tblHeaders.forEach((h, i) => {
      if (h) {
        const cell = ws.getCell(r, i + 1);
        cell.value = h;
        cell.font = { bold: true, size: 10 };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
        cell.border = { bottom: { style: 'thin', color: { argb: BORD } } };
        cell.alignment = { horizontal: i >= 2 ? 'right' : (i === 0 ? 'center' : 'left'), vertical: 'middle', wrapText: true };
      }
    });
    ws.getRow(r).height = 22;
    r++;
    
    let totBruto = 0, totOtvori = 0, totBroj = 0, totNetoCisti = 0, totNetoGn421 = 0;
    procelja.forEach((p, i) => {
      const bruto = parseFloat(p.bruto_m2 || 0);
      const otvori = parseFloat(p.otvori_m2 || 0);
      const broj = parseInt(p.broj_otvora || 0);
      const netoC = parseFloat(p.neto_cisti_m2 || 0);
      const netoG = parseFloat(p.neto_gn421_m2 || 0);
      
      ws.getCell(r, 1).value = i + 1;
      ws.getCell(r, 1).alignment = { horizontal: 'center', vertical: 'middle' };
      ws.getCell(r, 2).value = p.oznaka || `Nacrt ${i+1}`;
      ws.getCell(r, 2).font = { bold: true, color: { argb: BLUE }, size: 10 };
      ws.getCell(r, 3).value = bruto;
      ws.getCell(r, 4).value = otvori;
      ws.getCell(r, 5).value = broj;
      ws.getCell(r, 6).value = netoG;  // ⭐ v135.7.22: NETO GN 421 (formalna obračun)
      ws.getCell(r, 7).value = netoC;  // ⭐ v135.7.22: Netto odbitak (za narudžbu)
      
      [3, 4, 6, 7].forEach(c => { ws.getCell(r, c).numFmt = '0.00'; });
      [3, 4, 5, 6, 7].forEach(c => { ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' }; });
      [1, 2, 3, 4, 5, 6, 7].forEach(c => {
        if (c !== 2) ws.getCell(r, c).font = { ...(ws.getCell(r, c).font || {}), size: 10 };
        ws.getCell(r, c).border = { bottom: { style: 'thin', color: { argb: BORD } } };
      });
      ws.getRow(r).height = 18;
      
      totBruto += bruto;
      totOtvori += otvori;
      totBroj += broj;
      totNetoCisti += netoC;
      totNetoGn421 += netoG;
      r++;
    });
    
    // ⭐ v135.7.22 (Ivanov koncept): NETO GN 421 prvi (formalna), Netto odbitak drugi
    ws.getCell(r, 1).value = '';
    ws.getCell(r, 2).value = 'UKUPNO';
    ws.getCell(r, 3).value = parseFloat(totBruto.toFixed(2));
    ws.getCell(r, 4).value = parseFloat(totOtvori.toFixed(2));
    ws.getCell(r, 5).value = totBroj;
    ws.getCell(r, 6).value = parseFloat(totNetoGn421.toFixed(2));  // NETO GN 421
    ws.getCell(r, 7).value = parseFloat(totNetoCisti.toFixed(2));  // Netto odbitak
    for (let c = 1; c <= 7; c++) {
      const cell = ws.getCell(r, c);
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: GREEN } };
      cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 12 };
      cell.border = { top: { style: 'medium' }, bottom: { style: 'medium' } };
      if (c >= 3) cell.alignment = { horizontal: 'right', vertical: 'middle' };
      if (c === 3 || c === 4 || c === 6 || c === 7) cell.numFmt = '0.00';
    }
    ws.getRow(r).height = 26;
    r++;
    
    // ⭐ v135.7.178 (Prijedlog E): BREAKDOWN SAŽETAK — iz čega se sastoji Bruto
    //   Razlog: klijent vidi 254m² Bruto ali ne razumije: koliko je ploha, koliko atike/sokla?
    //   Sad: zaseban tablica koji pokazuje sumirani Plohe / Razvijene (m + m²) / Sitnice po pročelju.
    ws.getRow(r).height = 12; r++;
    
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = 'STRUKTURA BRUTO POVRŠINE (iz čega se sastoji)';
    ws.getCell(r, 1).font = { bold: true, size: 11, color: { argb: 'FFFFFFFF' } };
    ws.getCell(r, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
    ws.getCell(r, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
    ws.getRow(r).height = 20;
    r++;
    
    // Header: # | Oznaka | Plohe m² | RŠ duljina (m') | RŠ m² | Dodatni obračuni m² | Bruto m² (kontrola)
    const brkHeaders = ['#', 'Oznaka', 'Plohe m²', 'Razvijene (m\')', 'Razvijene m²', 'Dodatni obračuni m²', 'Bruto m²', ''];
    brkHeaders.forEach((h, i) => {
      if (h) {
        const cell = ws.getCell(r, i + 1);
        cell.value = h;
        cell.font = { bold: true, size: 10 };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
        cell.border = { bottom: { style: 'thin', color: { argb: BORD } } };
        cell.alignment = { horizontal: i >= 2 ? 'right' : (i === 0 ? 'center' : 'left'), vertical: 'middle', wrapText: true };
      }
    });
    ws.getRow(r).height = 22;
    r++;
    
    let totPlohe = 0, totRsDuljina = 0, totRsM2 = 0, totSitnice = 0, totBrkBruto = 0;
    procelja.forEach((p, i) => {
      // Plohe — iz p.plohe_m2 ako server ga šalje, inače sumiraj iz ravnine
      let plohaM2 = parseFloat(p.plohe_m2 || 0);
      if (!plohaM2 && Array.isArray(p.ravnine)) {
        p.ravnine.forEach(r => {
          (r.plohe || []).forEach(pl => {
            const m2 = _fasAutoritativniM2(pl);
            plohaM2 += m2 * (parseInt(pl.kolicina || 1) || 1);
          });
        });
      }
      
      // Razvijene — duljina (m') i m² zasebno
      let rsDuljina = 0, rsM2 = 0;
      (p.razvijene || []).forEach(rs => {
        if (!rs._zavrsen) return;
        const kol = parseInt(rs.kolicina || 1) || 1;
        rsDuljina += (parseFloat(rs._m_duzni || 0) || 0) * kol;
        rsM2 += (parseFloat(rs._m2 || rs.m2 || 0) || 0) * kol;
      });
      
      // Sitnice m² (samo m² jedinica — komadi nisu m²)
      let sitniceM2 = 0;
      (p.sitnice || []).forEach(s => {
        if (s.jedinica === 'm²' || s.jedinica === 'm2' || !s.jedinica) {
          sitniceM2 += parseFloat(s.kolicina || s.m2 || 0) || 0;
        }
      });
      
      // Bruto kontrola = Plohe + RŠ m² + Sitnice
      const brkBruto = plohaM2 + rsM2 + sitniceM2;
      
      ws.getCell(r, 1).value = i + 1;
      ws.getCell(r, 1).alignment = { horizontal: 'center', vertical: 'middle' };
      ws.getCell(r, 2).value = p.oznaka || `Nacrt ${i+1}`;
      ws.getCell(r, 2).font = { bold: true, color: { argb: BLUE }, size: 10 };
      ws.getCell(r, 3).value = parseFloat(plohaM2.toFixed(2));
      ws.getCell(r, 4).value = parseFloat(rsDuljina.toFixed(2));
      ws.getCell(r, 5).value = parseFloat(rsM2.toFixed(2));
      ws.getCell(r, 6).value = parseFloat(sitniceM2.toFixed(2));
      ws.getCell(r, 7).value = parseFloat(brkBruto.toFixed(2));
      
      [3, 4, 5, 6, 7].forEach(c => { ws.getCell(r, c).numFmt = '0.00'; });
      [3, 4, 5, 6, 7].forEach(c => { ws.getCell(r, c).alignment = { horizontal: 'right', vertical: 'middle' }; });
      [1, 2, 3, 4, 5, 6, 7].forEach(c => {
        if (c !== 2) ws.getCell(r, c).font = { ...(ws.getCell(r, c).font || {}), size: 10 };
        ws.getCell(r, c).border = { bottom: { style: 'thin', color: { argb: BORD } } };
      });
      ws.getRow(r).height = 18;
      
      totPlohe += plohaM2;
      totRsDuljina += rsDuljina;
      totRsM2 += rsM2;
      totSitnice += sitniceM2;
      totBrkBruto += brkBruto;
      r++;
    });
    
    // Suma row za breakdown
    ws.getCell(r, 1).value = '';
    ws.getCell(r, 2).value = 'UKUPNO';
    ws.getCell(r, 3).value = parseFloat(totPlohe.toFixed(2));
    ws.getCell(r, 4).value = parseFloat(totRsDuljina.toFixed(2));
    ws.getCell(r, 5).value = parseFloat(totRsM2.toFixed(2));
    ws.getCell(r, 6).value = parseFloat(totSitnice.toFixed(2));
    ws.getCell(r, 7).value = parseFloat(totBrkBruto.toFixed(2));
    for (let c = 1; c <= 7; c++) {
      const cell = ws.getCell(r, c);
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BLUE } };
      cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
      cell.border = { top: { style: 'medium' }, bottom: { style: 'medium' } };
      if (c >= 3) cell.alignment = { horizontal: 'right', vertical: 'middle' };
      if (c >= 3 && c <= 7) cell.numFmt = '0.00';
    }
    ws.getRow(r).height = 24;
    r++;
    
    // Mini-legenda (objašnjenje za klijenta)
    ws.getRow(r).height = 4; r++;
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '💡 Plohe = ravne fasadne plohe · Razvijene = atike/vijenci/sokli (linija razvijena na m²) · Dodatni obračuni = ostali detalji izvan ravnina (špalete su m\' u zasebnom listu)';
    ws.getCell(r, 1).font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
    ws.getCell(r, 1).alignment = { horizontal: 'center', wrapText: true, vertical: 'top' };
    ws.getRow(r).height = 28;
    r++;
    
    // Footer napomena
    ws.getRow(r).height = 8; r++;
    ws.mergeCells(r, 1, r, 8);
    ws.getCell(r, 1).value = '📋 Detalji svakog nacrta: pogledajte zasebne sheet-ove (slika + mjere + otvori detaljno)';
    ws.getCell(r, 1).font = { italic: true, size: 10, color: { argb: 'FF6b7280' } };
    ws.getCell(r, 1).alignment = { horizontal: 'center', wrapText: true };
    r++;
    
    // ═════════════════════════════════════════════════════════════════
    // SHEET-ovi PER PROČELJE — branded format kao single brzi
    // ═════════════════════════════════════════════════════════════════
    // ⭐ v135.7.10: for...of umjesto forEach jer trebamo await za QNAP slike
    for (let idx = 0; idx < procelja.length; idx++) {
      const p = procelja[idx];
      const sheetName = (p.oznaka || `Procelje ${idx+1}`).replace(/[\\/?*\[\]:]/g, '_').slice(0, 31);
      const sw = wb.addWorksheet(sheetName, {
        pageSetup: {
          paperSize: 9, orientation: 'portrait', fitToPage: true,
          fitToWidth: 1, fitToHeight: 0,
          margins: { left: 0.5, right: 0.5, top: 0.6, bottom: 0.5, header: 0.25, footer: 0.25 }
        }
      });
      // Šire stupce da brojevi ne prikazuju #### + bolji prostor za naslove
      sw.columns = [
        { width: 16 }, { width: 24 }, { width: 14 }, { width: 14 },
        { width: 16 }, { width: 14 }, { width: 16 }, { width: 12 },
      ];
      
      let pr = 1;
      
      // ── HEADER s logom + naslovom ──
      sw.getRow(pr).height = 60;
      if (logoImageId !== null) {
        try {
          sw.addImage(logoImageId, {
            tl: { col: 0.1, row: pr - 1 + 0.1 },
            ext: { width: 100, height: 50 }
          });
        } catch(_) {}
      }
      sw.mergeCells(pr, 3, pr, 8);
      const ph = sw.getCell(pr, 3);
      ph.value = `NACRT ${idx + 1} OD ${procelja.length}`;
      ph.font = { bold: true, size: 14, color: { argb: RED } };
      ph.alignment = { horizontal: 'right', vertical: 'middle' };
      pr++;
      sw.mergeCells(pr, 3, pr, 8);
      const ph2 = sw.getCell(pr, 3);
      ph2.value = `${p.oznaka || ('Nacrt ' + (idx + 1))} · AI knjiga`;
      ph2.font = { italic: true, size: 9, color: { argb: 'FF6b7280' } };
      ph2.alignment = { horizontal: 'right' };
      pr++;
      
      // Crveni separator
      sw.mergeCells(pr, 1, pr, 8);
      sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
      sw.getRow(pr).height = 4;
      pr++;
      sw.getRow(pr).height = 5; pr++;
      
      // ── INFO BLOK ──
      const pInfoRows = [
        ['Gradilište:', gradNaziv || naziv_objekta || '?', 'Datum:', datumFormat],
        ['Adresa:',     gradAdresa || '-', 'Nacrt:', `${idx + 1} / ${procelja.length}`],
        ['Izvođač:',    'ŽBUKA Čakarić d.o.o.', 'Pouzdanost:', `${(p.pouzdanost_postotak || 85).toFixed(0)}%`],
      ];
      pInfoRows.forEach(row => {
        sw.getCell(pr, 1).value = row[0];
        sw.getCell(pr, 1).font = { bold: true, size: 10 };
        sw.mergeCells(pr, 2, pr, 4);
        sw.getCell(pr, 2).value = row[1];
        sw.getCell(pr, 2).font = { size: 10 };
        sw.getCell(pr, 5).value = row[2];
        sw.getCell(pr, 5).font = { bold: true, size: 10 };
        sw.mergeCells(pr, 6, pr, 8);
        sw.getCell(pr, 6).value = row[3];
        sw.getCell(pr, 6).font = { size: 10 };
        sw.getRow(pr).height = 16;
        pr++;
      });
      
      sw.getRow(pr).height = 5; pr++;
      
      // ── SLIKA pročelja (anotirana ima prednost) ──
      // ⭐ v135.7.10 fix: nakon save-a server briše slika_anotirana base64 i ostavlja QNAP path
      // (vidi multi-procelje/spremi → p.slika_anotirana = null; p.slika_anotirana_qnap_path = upPathA)
      // → trebamo prvo pokušati dohvatiti iz QNAP-a, pa fallback na base64
      let slikaB64 = null;
      let imgBuffer = null;
      
      // 1) Pokušaj QNAP anotirana (najnovije, prioritet)
      if (!imgBuffer && p.slika_anotirana_qnap_path && typeof _qnapFetchBufferZaPath === 'function') {
        try {
          imgBuffer = await _qnapFetchBufferZaPath(p.slika_anotirana_qnap_path);
          if (imgBuffer) console.log(`[Excel multi-p${idx}] Anotirana QNAP: ${imgBuffer.length}b`);
        } catch(e) { console.warn(`[Excel multi-p${idx} QNAP anot] ${e.message}`); }
      }
      // 2) Pokušaj QNAP hatch (alternativni naziv)
      if (!imgBuffer && p.slika_hatch_qnap_path && typeof _qnapFetchBufferZaPath === 'function') {
        try {
          imgBuffer = await _qnapFetchBufferZaPath(p.slika_hatch_qnap_path);
          if (imgBuffer) console.log(`[Excel multi-p${idx}] Hatch QNAP: ${imgBuffer.length}b`);
        } catch(e) { console.warn(`[Excel multi-p${idx} QNAP hatch] ${e.message}`); }
      }
      // 3) Fallback: anotirana base64 (svježi save prije QNAP uploada)
      if (!imgBuffer && p.slika_anotirana && typeof p.slika_anotirana === 'string') {
        slikaB64 = p.slika_anotirana;
      }
      // 4) Fallback: original QNAP slika
      if (!imgBuffer && !slikaB64 && p.slika_qnap_path && typeof _qnapFetchBufferZaPath === 'function') {
        try {
          imgBuffer = await _qnapFetchBufferZaPath(p.slika_qnap_path);
          if (imgBuffer) console.log(`[Excel multi-p${idx}] Original QNAP: ${imgBuffer.length}b`);
        } catch(e) { console.warn(`[Excel multi-p${idx} QNAP orig] ${e.message}`); }
      }
      // 5) Final fallback: original base64
      if (!imgBuffer && !slikaB64 && p.slika_base64) {
        slikaB64 = p.slika_base64;
      }
      
      if (slikaB64 && typeof slikaB64 === 'string') {
        try {
          let cleanB64 = slikaB64;
          let ext = 'jpeg';
          const m = cleanB64.match(/^data:image\/(\w+);base64,(.+)$/);
          if (m) { ext = m[1]; cleanB64 = m[2]; }
          imgBuffer = Buffer.from(cleanB64, 'base64');
        } catch(e) { console.warn(`[Excel multi-p${idx} base64 parse] ${e.message}`); }
      }
      
      if (imgBuffer) {
        try {
          const buf = imgBuffer;
          const ext = (buf[0] === 0x89 && buf[1] === 0x50) ? 'png' : 'jpeg';
          
          // Detect dimensions for aspect ratio (veće za bolju čitljivost — 720×480 max)
          let imgWidth = 720, imgHeight = 480;
          try {
            if (buf[0] === 0xFF && buf[1] === 0xD8) {
              let i = 2;
              while (i < Math.min(buf.length - 8, 1048576)) {
                if (buf[i] !== 0xFF) { i++; continue; }
                const marker = buf[i+1];
                if (marker >= 0xD0 && marker <= 0xD9) { i += 2; continue; }
                if ((marker >= 0xC0 && marker <= 0xC3) ||
                    (marker >= 0xC5 && marker <= 0xC7)) {
                  const h = (buf[i+5] << 8) | buf[i+6];
                  const w = (buf[i+7] << 8) | buf[i+8];
                  if (w > 0 && h > 0 && w < 30000 && h < 30000) {
                    const ratio = Math.min(720 / w, 480 / h);
                    imgWidth = Math.round(w * ratio);
                    imgHeight = Math.round(h * ratio);
                    break;
                  }
                }
                const blockLen = (buf[i+2] << 8) | buf[i+3];
                if (blockLen <= 0) break;
                i += 2 + blockLen;
              }
            } else if (buf[0] === 0x89 && buf[1] === 0x50) {
              const w = (buf[16] << 24) | (buf[17] << 16) | (buf[18] << 8) | buf[19];
              const h = (buf[20] << 24) | (buf[21] << 16) | (buf[22] << 8) | buf[23];
              if (w > 0 && h > 0) {
                const ratio = Math.min(720 / w, 480 / h);
                imgWidth = Math.round(w * ratio);
                imgHeight = Math.round(h * ratio);
              }
            }
          } catch(_) {}
          
          // Naslov bloka (uvijek "anotirano" jer FE uvijek šalje anotiranu)
          sw.mergeCells(pr, 1, pr, 8);
          sw.getCell(pr, 1).value = 'NACRT FASADE — anotirano (🟢 referentni pravokutnik · 🔴 otvori)';
          sw.getCell(pr, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
          sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
          sw.getCell(pr, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
          sw.getRow(pr).height = 18;
          pr++;
          
          const imgId = wb.addImage({ buffer: buf, extension: ext });
          
          // ⭐ v135.7.252: koristim _excelSlikaPositioning helper (px-bazirano, robust na različite širine stupaca)
          //   NAPOMENA: ovdje je `sw` (multi-procelje sheet), ne `ws`. Helper čita iz sw.
          const isHorizontal_3 = imgWidth > imgHeight;
          const centerCol = _excelSlikaPositioning(sw, imgWidth, isHorizontal_3, 8);
          
          sw.addImage(imgId, {
            tl: { col: centerCol, row: pr - 1 + 0.1 },
            ext: { width: imgWidth, height: imgHeight },
            editAs: 'oneCell'
          });
          
          // Rezerviraj redove prema visini slike (1 row ≈ 21px)
          const rezervRows = Math.ceil((imgHeight + 8) / 21);
          for (let i = 0; i < rezervRows; i++) {
            sw.getRow(pr + i).height = 21;
          }
          pr += rezervRows;
        } catch(e) { console.warn('[multi sheet slika]', p.oznaka, e.message); }
      }
      
      sw.getRow(pr).height = 5; pr++;
      
      // ── REFERENTNI PRAVOKUTNIK ──
      if (p.pravokutnik) {
        sw.mergeCells(pr, 1, pr, 8);
        sw.getCell(pr, 1).value = 'REFERENTNI PRAVOKUTNIK (za skalu)';
        sw.getCell(pr, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
        sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
        sw.getCell(pr, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
        sw.getRow(pr).height = 18;
        pr++;
        
        const refRows = [
          ['Tip reference:', p.pravokutnik.tip || 'pravokutnik', null],
          ['Širina (m):', parseFloat(p.pravokutnik.sirina_m || 0), '0.00'],
          ['Visina (m):', parseFloat(p.pravokutnik.visina_m || 0), '0.00'],
        ];
        refRows.forEach(row => {
          sw.getCell(pr, 1).value = row[0];
          sw.getCell(pr, 1).font = { bold: true, size: 10 };
          sw.mergeCells(pr, 2, pr, 8);
          sw.getCell(pr, 2).value = row[1];
          sw.getCell(pr, 2).font = { size: 10 };
          if (row[2]) sw.getCell(pr, 2).numFmt = row[2];
          sw.getRow(pr).height = 16;
          pr++;
        });
        sw.getRow(pr).height = 5; pr++;
      }
      
      // ── GLAVNE MJERE ──
      sw.mergeCells(pr, 1, pr, 8);
      sw.getCell(pr, 1).value = 'GLAVNE MJERE NACRTI';
      sw.getCell(pr, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
      sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
      sw.getCell(pr, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      sw.getRow(pr).height = 18;
      pr++;
      
      const mjereRows = [
        ['Širina (m):', parseFloat(p.sirina_m || 0), null, '0.00'],
        ['Visina (m):', parseFloat(p.visina_m || 0), null, '0.00'],
        ['BRUTO fasada (m²):', parseFloat(p.bruto_m2 || 0), BLUE, '0.00'],
        ['Površina otvora (m²):', parseFloat(p.otvori_m2 || 0), ORANGE, '0.00'],
        ['Broj otvora:', parseInt(p.broj_otvora || 0), null, '0'],
        ['NETO GN 421 (formalna obračun, m²):', parseFloat(p.neto_gn421_m2 || 0), GREEN, '0.00'],
        ['📦 Netto odbitak (za narudžbu materijala, m²):', parseFloat(p.neto_cisti_m2 || 0), null, '0.00'],
      ];
      mjereRows.forEach(row => {
        sw.getCell(pr, 1).value = row[0];
        sw.getCell(pr, 1).font = { bold: row[2] != null, size: 10 };
        sw.mergeCells(pr, 2, pr, 4);
        sw.getCell(pr, 2).value = row[1];  // Number, ne string — numFmt radi
        sw.getCell(pr, 2).numFmt = row[3];
        sw.getCell(pr, 2).alignment = { horizontal: 'right', vertical: 'middle' };
        if (row[2]) {
          sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: row[2] } };
          sw.getCell(pr, 1).font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 10 };
          sw.getCell(pr, 2).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: row[2] } };
          sw.getCell(pr, 2).font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
        } else {
          sw.getCell(pr, 1).font = { ...(sw.getCell(pr, 1).font || {}), size: 10 };
          sw.getCell(pr, 2).font = { size: 10 };
        }
        sw.getCell(pr, 1).border = { bottom: { style: 'thin', color: { argb: BORD } } };
        sw.getCell(pr, 2).border = { bottom: { style: 'thin', color: { argb: BORD } } };
        sw.getRow(pr).height = 18;
        pr++;
      });
      
      sw.getRow(pr).height = 5; pr++;
      
      // ── OTVORI DETALJNO ──
      if (Array.isArray(p.otvori_detaljno) && p.otvori_detaljno.length > 0) {
        // Ukupno kom (zbroj svih kom polja, default 1)
        const ukupnoKom = p.otvori_detaljno.reduce((s, o) => s + (parseInt(o.kom) || 1), 0);
        sw.mergeCells(pr, 1, pr, 8);
        sw.getCell(pr, 1).value = `OTVORI DETALJNO (${p.otvori_detaljno.length} tip${p.otvori_detaljno.length === 1 ? '' : 'a'} · ${ukupnoKom} kom ukupno)`;
        sw.getCell(pr, 1).font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
        sw.getCell(pr, 1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: DARK } };
        sw.getCell(pr, 1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
        sw.getRow(pr).height = 18;
        pr++;
        
        // Header tablice otvora — sad s "Kom" + "Ukupno (m²)"
        const oh = ['#', 'Tip otvora', 'Širina (m)', 'Visina (m)', 'Po kom (m²)', 'Kom', 'Ukupno (m²)', ''];
        oh.forEach((h, i) => {
          if (h) {
            const cell = sw.getCell(pr, i + 1);
            cell.value = h;
            cell.font = { bold: true, size: 10 };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LBKG } };
            cell.border = { bottom: { style: 'thin', color: { argb: BORD } } };
            cell.alignment = { horizontal: i >= 2 ? 'right' : (i === 0 ? 'center' : 'left'), vertical: 'middle', wrapText: true };
          }
        });
        sw.getRow(pr).height = 22;
        pr++;
        
        let sumOtv = 0;
        p.otvori_detaljno.forEach((o, i) => {
          const sirina = parseFloat(o.sirina_m || 0);
          const visina = parseFloat(o.visina_m || 0);
          const povrs = parseFloat(o.povrsina_m2 || 0);
          const kom = parseInt(o.kom) || 1;
          const ukupno = povrs * kom;
          
          sw.getCell(pr, 1).value = i + 1;
          sw.getCell(pr, 1).alignment = { horizontal: 'center', vertical: 'middle' };
          sw.getCell(pr, 2).value = o.tip || 'prozor';
          sw.getCell(pr, 3).value = sirina;
          sw.getCell(pr, 3).numFmt = '0.00';
          sw.getCell(pr, 4).value = visina;
          sw.getCell(pr, 4).numFmt = '0.00';
          sw.getCell(pr, 5).value = povrs;
          sw.getCell(pr, 5).numFmt = '0.00';
          sw.getCell(pr, 6).value = kom;
          sw.getCell(pr, 6).numFmt = '0';
          // Ukupno (m²) merge stupce 7-8
          sw.mergeCells(pr, 7, pr, 8);
          sw.getCell(pr, 7).value = ukupno;
          sw.getCell(pr, 7).numFmt = '0.00';
          sw.getCell(pr, 7).font = { bold: true, size: 10, color: kom > 1 ? { argb: ORANGE } : null };
          [3, 4, 5, 6, 7].forEach(c => sw.getCell(pr, c).alignment = { horizontal: 'right', vertical: 'middle' });
          [1, 2, 3, 4, 5, 6, 7].forEach(c => {
            if (c !== 7) sw.getCell(pr, c).font = { ...(sw.getCell(pr, c).font || {}), size: 10 };
            sw.getCell(pr, c).border = { bottom: { style: 'thin', color: { argb: BORD } } };
          });
          // Highlight kolicina ako > 1
          if (kom > 1) {
            sw.getCell(pr, 6).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0F2FE' } };
            sw.getCell(pr, 6).font = { bold: true, size: 10, color: { argb: BLUE } };
          }
          sw.getRow(pr).height = 16;
          
          sumOtv += ukupno;
          pr++;
        });
        
        // Suma otvora
        sw.getCell(pr, 1).value = '';
        sw.getCell(pr, 2).value = 'UKUPNO OTVORI';
        sw.getCell(pr, 6).value = ukupnoKom;
        sw.getCell(pr, 6).numFmt = '0';
        sw.mergeCells(pr, 7, pr, 8);
        sw.getCell(pr, 7).value = parseFloat(sumOtv.toFixed(2));
        sw.getCell(pr, 7).numFmt = '0.00';
        for (let c = 1; c <= 7; c++) {
          const cell = sw.getCell(pr, c);
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: ORANGE } };
          cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
          cell.border = { top: { style: 'medium' }, bottom: { style: 'medium' } };
          if (c >= 3) cell.alignment = { horizontal: 'right', vertical: 'middle' };
        }
        sw.getRow(pr).height = 22;
        pr++;
      }
      
      // ── NAPOMENA / OBRAZLOŽENJE ──
      if (p.napomena) {
        sw.getRow(pr).height = 5; pr++;
        sw.getCell(pr, 1).value = 'Napomena:';
        sw.getCell(pr, 1).font = { bold: true, size: 9 };
        sw.mergeCells(pr, 2, pr, 8);
        sw.getCell(pr, 2).value = p.napomena;
        sw.getCell(pr, 2).font = { size: 9, italic: true };
        sw.getCell(pr, 2).alignment = { wrapText: true };
        pr++;
      }
      if (p.obrazlozenje) {
        sw.getCell(pr, 1).value = 'Obrazloženje:';
        sw.getCell(pr, 1).font = { bold: true, size: 9 };
        sw.mergeCells(pr, 2, pr, 8);
        sw.getCell(pr, 2).value = p.obrazlozenje;
        sw.getCell(pr, 2).font = { size: 9, color: { argb: 'FF6b7280' } };
        sw.getCell(pr, 2).alignment = { wrapText: true, vertical: 'top' };
        sw.getRow(pr).height = 50;
        pr++;
      }
    } // end for (let idx ...) — multi-procelje sheets
    
    // ─────────────────────────────────────────────────────────────────
    // SAVE + UPLOAD
    // ─────────────────────────────────────────────────────────────────
    const buffer = await _xlsxFixBuffer(await wb.xlsx.writeBuffer());   // ⭐ v546: sanacija OOXML quirkova — ima slike
    const dateStr = _ymd(datum);
    const safeName = (gradNaziv || naziv_objekta || 'objekt').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
    const fname = `Obracun_fasada_${safeName}_multi_${procelja.length}p_${dateStr}.xlsx`;
    
    // Auto-upload na QNAP — Brze-procjene podfolder + clear dirty
    if (process.env.QNAP_WEBDAV_URL) {
      let qnapPath;
      if (gradNaziv) {
        // S gradilištem: Fasade-AI/{gradilište}/Brze-procjene/{fname}
        qnapPath = `Fasade-AI/${sanitizeFolderName(gradNaziv)}/Brze-procjene/${fname}`;
      } else {
        // Bez gradilišta: Fasade-AI/_BrzeProcjene/{naziv_objekta}/{fname}
        const sn = sanitizeFolderName(naziv_objekta || 'objekt');
        qnapPath = `Fasade-AI/_BrzeProcjene/${sn}/${fname}`;
      }
      setImmediate(async () => {
        try {
          await qnapUploadExcel(Buffer.from(buffer), qnapPath);
          if (multiId) {
            await pool.query(`UPDATE fasade_procjene SET excel_dirty = false WHERE id = $1`, [multiId]);
          }
          console.log(`[multi excel] uploaded: ${qnapPath}`);
        } catch(e) { console.warn('[multi excel] upload fail:', e.message); }
      });
    }
    
    const fnameAscii = safeAsciiFilename(fname);
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', `attachment; filename="${fnameAscii}"; filename*=UTF-8''${encodeURIComponent(fname)}`);
    res.setHeader('Content-Length', buffer.length);
    res.send(Buffer.from(buffer));
  } catch(e) {
    console.error('[export multi-procelje]', e);
    if (!res.headersSent) res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// GRADEVINSKA KNJIGA: GET /api/fasada/export/excel/gradiliste/:gid
// Generira kompletnu građevinsku knjigu fasaderskih radova za jedno gradilište:
// - Naslovnica + sažetak svega
// - Pregled svih procjena (tablica)
// - Sažetak fasade po procjenama
// - Svi otvori, sve barijere, sve debljine, sve dodatne stavke (agregirano)
// - Po jedan list za svaku procjenu (kao individualni Excel)
// Auto-upload na QNAP: Fasade-AI/{naziv}/Gradevinska_knjiga_{naziv}.xlsx (overwrite)
// ═══════════════════════════════════════════════════════════════════════════
app.get('/api/fasada/export/excel/gradiliste/:gid', auth, staff, async (req, res) => {
  try {
    const gid = parseInt(req.params.gid);
    if (!gid) return res.status(400).json({ error: 'Nedostaje ID gradilišta' });
    
    // ⭐ THROTTLE + CACHE: ako je knjiga svježa (regen <5min) i nije dirty,
    //    koristi cached version iz QNAP-a (vraća direktan link)
    //    Ako je dirty ili stara, regeniraj.
    const gradR = await pool.query(
      'SELECT id, naziv, knjiga_dirty, knjiga_last_gen FROM gradilista WHERE id=$1', [gid]
    );
    if (!gradR.rows.length) return res.status(404).json({ error: 'Gradilište ne postoji' });
    const grad = gradR.rows[0];
    
    const procCntR = await pool.query(
      'SELECT COUNT(*) AS cnt FROM fasade_procjene WHERE gradiliste_id=$1', [gid]
    );
    if (parseInt(procCntR.rows[0]?.cnt || 0) === 0) {
      return res.status(400).json({ error: 'Gradilište nema knjiga za export' });
    }
    
    // Throttle: ako se generirala u <5min i nije dirty, ne regen-iraj
    const minutaOdGen = grad.knjiga_last_gen 
      ? (Date.now() - new Date(grad.knjiga_last_gen).getTime()) / 60000 
      : 9999;
    const treba_regen = grad.knjiga_dirty || minutaOdGen > 5;
    
    if (!treba_regen) {
      console.log(`[Knjiga] cached (${minutaOdGen.toFixed(1)}min stara, ne dirty) — preskočen regen`);
      // Pokušaj poslati cached file iz QNAP-a (ako postoji)
      // Fallback: regen ipak
    }
    
    const result = await generirajGradevinskuKnjiguBuffer(gid);
    
    // ⭐ v135.7.57: Streaming + gzip kompresija za velike Excele
    sendExcelResponse(req, res, result.buffer, result.fname);
    
    // QNAP upload + clear dirty + update last_gen
    const folder = fasadaQnapFolder(result.grad.naziv || 'gradiliste');
    setImmediate(async () => {
      try {
        await qnapUploadExcel(result.buffer, `${folder}/${result.fname}`);
        await pool.query(
          `UPDATE gradilista SET knjiga_dirty = false, knjiga_last_gen = NOW() WHERE id = $1`,
          [gid]
        );
      } catch(e) { console.warn('[Knjiga] clear dirty fail:', e.message); }
    });
    console.log(`[Knjiga] ${result.fname} (${(result.buffer.length / 1024).toFixed(0)} KB, ${result.broj_procjena} knjiga, regen=${treba_regen})`);
  } catch(e) {
    console.error('[Gradevinska knjiga endpoint]', e);
    if (!res.headersSent) res.status(500).json({ error: e.message });
  }
});

