      // ⭐ v372: dugi tekst (metoda izračuna) → wrapText + font 9 (umjesto 8) + visina 80
      const jeDugiText_358 = typeof row[3] === 'string' && row[3].length > 60;
      wsNas.getCell(r, 6).font = { size: jeDugiText_358 ? 9 : 10, color: { argb: 'FF0F172A' } };
      wsNas.getCell(r, 6).alignment = jeDugiText_358 
        ? { wrapText: true, vertical: 'middle', horizontal: 'left', indent: 1 }
        : { vertical: 'middle', horizontal: 'left', indent: 1 };
      // Subtle alternating row background
