// ─── DELETE /api/fasada/:id (původně oko L13055) ───
// ── DIJAGNOSTIKA: GET /api/fasada/audit (samo direktor) ──────────────────
// Vraća audit izvještaj o stanju Fasada AI flow-a:
// - broj procjena u DB
// - broj fajlova u QNAP folder-ima po gradilištu
// - inconsistencies (orphan slike, missing fajlovi)
app.get('/api/fasada/audit', auth, direktor, async (req, res) => {
  try {
    const startTs = Date.now();
    
    // 1) Procjene u DB
    const dbR = await pool.query(`
      SELECT f.id, f.gradiliste_id, f.slika_qnap_path, f.ai_anotirana_slika, f.koncept,
             f.bruto_fasada_m2, f.neto_fasada_m2, f.created_at, f.updated_at,
             length(coalesce(f.slika_base64,'')) AS slika_b64_size,
             length(coalesce(f.ravnine_json::text,'')) AS ravnine_size,
             length(coalesce(f.sitnice_json::text,'')) AS sitnice_size,
             length(coalesce(f.otvori_json::text,'')) AS otvori_size,
             length(coalesce(f.pozarne_barijere_json::text,'')) AS bar_size,
             length(coalesce(f.zone_debljine_json::text,'')) AS deb_size,
             g.naziv AS grad_naziv, g.aktivan AS grad_aktivan
      FROM fasade_procjene f
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      ORDER BY f.gradiliste_id, f.id
    `);
    
    // 2) Group by gradilište
    const procjeneByGrad = {};
    let totalDbSize = 0;
    let legacySlikaB64 = 0;
    
    for (const r of dbR.rows) {
      const k = r.grad_naziv || 'BEZ_NAZIVA_grad' + r.gradiliste_id;
      if (!procjeneByGrad[k]) procjeneByGrad[k] = { aktivan: r.grad_aktivan, knjige: [] };
      procjeneByGrad[k].procjene.push({
        id: r.id,
        koncept: r.koncept,
        bruto: parseFloat(r.bruto_fasada_m2 || 0).toFixed(2),
        neto: parseFloat(r.neto_fasada_m2 || 0).toFixed(2),
        ima_qnap_sliku: !!r.slika_qnap_path,
        ima_anotiranu: !!r.ai_anotirana_slika,
        created: r.created_at,
        updated: r.updated_at,
        size_kb: Math.round((parseInt(r.slika_b64_size) + parseInt(r.ravnine_size) + parseInt(r.sitnice_size) +
                  parseInt(r.otvori_size) + parseInt(r.bar_size) + parseInt(r.deb_size)) / 1024)
      });
      totalDbSize += parseInt(r.slika_b64_size) + parseInt(r.ravnine_size) + parseInt(r.sitnice_size) +
                     parseInt(r.otvori_size) + parseInt(r.bar_size) + parseInt(r.deb_size);
      if (parseInt(r.slika_b64_size) > 1000) legacySlikaB64++;
    }
    
    // 3) QNAP file count po folderu (samo ako je QNAP konfigurisan)
    const qnapStats = {};
    if (process.env.QNAP_WEBDAV_URL) {
      for (const grad of Object.keys(procjeneByGrad)) {
        const folder = fasadaQnapFolder(grad);
        const files = await qnapListFolder(folder);
        const dbProcjene = procjeneByGrad[grad].procjene;
        const fileNames = files || [];
        const slike = fileNames.filter(f => f.startsWith('slika_'));
        const anotirane = fileNames.filter(f => f.startsWith('anotirana_'));
        const excels = fileNames.filter(f => f.endsWith('.xlsx'));
        const knjiga = fileNames.find(f => f.startsWith('Gradevinska_knjiga_'));
        const orphans = fileNames.filter(f => {
          const procMatch = f.match(/proc(\d+)/);
          if (procMatch) {
            return !dbProcjene.find(p => p.id == procMatch[1]);
          }
          return false;
        });
        qnapStats[grad] = {
          folder: folder,
          ukupno_fajlova: fileNames.length,
          slike: slike.length,
          anotirane: anotirane.length,
          excels: excels.length,
          knjiga: knjiga || null,
          orphans_count: orphans.length,
          orphans: orphans,
          // Anomalije
          previse_slika: slike.length > dbProcjene.length,  // 1:1 očekivano
          fali_slika: slike.length < dbProcjene.filter(p => p.ima_qnap_sliku).length
        };
      }
    }
    
    // 4) DB size statistika (PostgreSQL specific)
    let dbSizeInfo = null;
    try {
      const sizeR = await pool.query(`
        SELECT pg_size_pretty(pg_total_relation_size('fasade_procjene')) AS table_size,
               pg_size_pretty(pg_indexes_size('fasade_procjene')) AS index_size,
               (SELECT COUNT(*) FROM fasade_procjene) AS row_count
      `);
      dbSizeInfo = sizeR.rows[0];
    } catch(_) {}
    
    // 5) AI potrošnja (tokens, cost)
    let aiPotrosnja = null;
    try {
      const aiR = await pool.query(`
        SELECT 
          endpoint,
          COUNT(*) AS broj_poziva,
          SUM(input_tokens) AS sum_input,
          SUM(output_tokens) AS sum_output,
          ROUND(SUM(cijena_usd)::numeric, 4) AS uk_usd,
          MAX(created_at) AS zadnji_poziv
        FROM ai_potrosnja
        WHERE created_at > NOW() - INTERVAL '90 days'
        GROUP BY endpoint
        ORDER BY uk_usd DESC NULLS LAST
      `);
      aiPotrosnja = aiR.rows;
    } catch(_) {}
    
    // 6) Sažeci + scaling preporuke
    const totalProcjene = dbR.rows.length;
    const procjeneNoQnap = dbR.rows.filter(r => !r.slika_qnap_path && !r.ai_anotirana_slika).length;
    const procjeneNoHatch = dbR.rows.filter(r => r.slika_qnap_path && !r.ai_anotirana_slika).length;
    const aktivnaGradilista = Object.values(procjeneByGrad).filter(g => g.aktivan).length;
    const arhiviranaGradilista = Object.values(procjeneByGrad).filter(g => !g.aktivan).length;
    
    const scalingUpozorenja = [];
    if (totalProcjene > 1000) scalingUpozorenja.push('🔴 1000+ knjiga u DB-u - razmotri archive partitioning');
    else if (totalProcjene > 500) scalingUpozorenja.push('🟡 500+ knjiga - dobro stanje, pratiti rast');
    if (legacySlikaB64 > 0) scalingUpozorenja.push(`🟡 ${legacySlikaB64} starih knjiga ima slika_base64 u DB - run init-db ponovo (briše ih)`);
    if (totalDbSize > 1024 * 1024 * 500) scalingUpozorenja.push(`🟡 DB tablica fasade_procjene > 500MB (trenutno ${(totalDbSize/1024/1024).toFixed(0)}MB) - JSONB GIN index?`);
    
    const orphan_files_total = Object.values(qnapStats).reduce((s, q) => s + (q.orphans_count || 0), 0);
    if (orphan_files_total > 0) scalingUpozorenja.push(`🟡 ${orphan_files_total} orphan fajlova na QNAP-u - pokreni cleanup`);
    
    const trajanjeMs = Date.now() - startTs;
    
    res.json({
      timestamp: new Date().toISOString(),
      trajanje_ms: trajanjeMs,
      qnap_konfigurisan: !!process.env.QNAP_WEBDAV_URL,
      sumar: {
        ukupno_procjena_db: totalProcjene,
        procjene_bez_qnap_slike: procjeneNoQnap,
        procjene_bez_anotirane: procjeneNoHatch,
        gradilista_aktivna: aktivnaGradilista,
        gradilista_arhivirana: arhiviranaGradilista,
        legacy_slika_base64_count: legacySlikaB64,
        ukupno_jsonb_size_kb: Math.round(totalDbSize / 1024),
        orphan_files_qnap: orphan_files_total
      },
      db_size: dbSizeInfo,
      ai_potrosnja_90_dana: aiPotrosnja,
      scaling_upozorenja: scalingUpozorenja,
      procjene_po_gradilistu: procjeneByGrad,
      qnap_stats: qnapStats
    });
  } catch (e) {
    console.error('[Fasada audit]', e);
    res.status(500).json({ error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ⭐ v135.7.281 (Ivan svibanj 2026): CROSS-TAB ORPHAN AUDIT
//   "Ako nema u aplikaciji, nema što biti orphan na cloudu" (Ivan).
//   
//   Cilj: skenirati QNAP i B2 paralelno za svih 5 tab-ova s slikama, naći
//   fileove koji NISU referencirani u nijednoj DB tablici (orphan) ILI 
//   DB qnap_path-eve čiji file ne postoji u oblaku (reverse — broken link).
//   
//   Tabovi (path prefiks → DB tablica + relevantni stupci):
//     Materijali/{grad}/   → materijal      (qnap_path, b2_path)
//     Smece/              → smece          (qnap_path, b2_path)
//     Dnevnik/{grad}/      → dnevnik        (qnap_path, qnap_path_original, b2_path)
//     Uredaji/            → uredaji        (qnap_path, b2_path)
//     Izmjera/{grad}/      → izmjera        (qnap_path, b2_path)
//     Fasade-AI/{grad}/    → fasade_procjene (slika_qnap_path, ai_anotirana_slika, 
//                                              nacrt_folder, nacrt_pdf_qnap_path,
//                                              + slika_b2_path, slika_hatch_b2_path,
//                                              + ai_anotirana_b2_path, pdf_b2_path,
//                                              + nacrt_pdf_b2_path,
//                                              + dimenzije_fasade.knjiga_procelja[].slika_qnap_path,
//                                              + dimenzije_fasade.knjiga_procelja[].slika_hatch_qnap_path,
//                                              + dimenzije_fasade.knjiga_procelja[].slika_b2_path,
//                                              + dimenzije_fasade.knjiga_procelja[].slika_hatch_b2_path,
//                                              + dimenzije_fasade.knjiga_procelja[].slika_anotirana_b2_path)
//   
//   Whitelist root-ova: BLOCK Sihterica, Rezijski-sati, Zaduznice, Gorivo, Backup,
//   Analitika, Diagnostic, Reference, Fasada (Excel exports - nemaju 1:1 mapping).
//   
//   Endpoint-i (svi DIREKTOR ONLY):
//     GET  /api/orphan-audit/full         — dry-run scan svih tabova (vraća listu)
//     POST /api/orphan-audit/cleanup      — briše po listi path-eva (s re-verifikacijom)
//   
//   + tjedni cron (nedjelja 03:00) automatski radi dry-run i šalje push direktoru
//   ako pronađe orphan-e.

const ORPHAN_AUDIT_CONFIG = {
  // Whitelist root foldera koje skeniramo (key = root prefix, value = config)
  roots: {
    'Materijali': { table: 'materijal', cols: ['qnap_path', 'b2_path'] },
    'Smece': { table: 'smece', cols: ['qnap_path', 'b2_path'] },
    'Dnevnik': { table: 'dnevnik', cols: ['qnap_path', 'qnap_path_original', 'b2_path'] },
    'Uredaji': { table: 'uredaji', cols: ['qnap_path', 'b2_path'] },
    'Izmjera': { table: 'izmjera', cols: ['qnap_path', 'b2_path'] },
    'Fasade-AI': { table: 'fasade_procjene', cols: 'fasada_special' }  // specijalna logika
  },
  // Excel exports koji su valjani — ne smatraj orphan-ima čak i bez DB refa
  excelPatterns: [
    /Gradevinska_knjiga.*\.xlsx$/i,
    /Obracun_fasada.*\.xlsx$/i,
    /\.xlsx$/i  // sva .xlsx u dozvoljenim folderima su safe (export-i)
  ],
  // Sigurnosni limit
  maxFilesScan: 10000,
  // Max paralelnih QNAP delete-ova
  deleteBatchSize: 10
};

// Helper: dohvati sve aktivne path-eve iz DB-a, grupirano po root folderu
async function _buildActivePathsByRoot() {
  const result = {};
  // Inicijaliziraj root-ove sa Set-ovima za QNAP i B2
  for (const root of Object.keys(ORPHAN_AUDIT_CONFIG.roots)) {
    result[root] = { qnap: new Set(), b2: new Set() };
  }
  
  // 1) Standardne tablice (materijal, smece, dnevnik, uredaji, izmjera)
  for (const [root, conf] of Object.entries(ORPHAN_AUDIT_CONFIG.roots)) {
    if (conf.cols === 'fasada_special') continue;  // posebna logika niže
    
    const cols = conf.cols.join(', ');
    try {
      const r = await pool.query(`SELECT ${cols} FROM ${conf.table}`);
      for (const row of r.rows) {
        for (const col of conf.cols) {
          const val = row[col];
          if (!val || typeof val !== 'string') continue;
          // qnap_path / qnap_path_original idu u qnap, b2_path ide u b2
          if (col.includes('b2')) {
            result[root].b2.add(val);
          } else {
            result[root].qnap.add(val);
          }
        }
      }
    } catch (e) {
      console.warn(`[orphan-audit] _buildActivePathsByRoot ${conf.table}:`, e.message);
    }
  }
  
  // 2) Fasade-AI: pokupi sve path-eve iz fasade_procjene + dimenzije_fasade.knjiga_procelja
  try {
    const fR = await pool.query(`
      SELECT slika_qnap_path, ai_anotirana_slika, nacrt_folder, nacrt_pdf_qnap_path,
             slika_b2_path, slika_hatch_b2_path, ai_anotirana_b2_path, 
             pdf_b2_path, nacrt_pdf_b2_path,
             dimenzije_fasade
      FROM fasade_procjene
    `);
    for (const row of fR.rows) {
      // Direktni stupci QNAP
      ['slika_qnap_path', 'ai_anotirana_slika', 'nacrt_pdf_qnap_path'].forEach(c => {
        if (row[c] && typeof row[c] === 'string') result['Fasade-AI'].qnap.add(row[c]);
      });
      // Direktni stupci B2
      ['slika_b2_path', 'slika_hatch_b2_path', 'ai_anotirana_b2_path', 'pdf_b2_path', 'nacrt_pdf_b2_path'].forEach(c => {
        if (row[c] && typeof row[c] === 'string') result['Fasade-AI'].b2.add(row[c]);
      });
      // nacrt_folder — to je folder, ne file → svi file-ovi pod njim su valjani
      if (row.nacrt_folder && typeof row.nacrt_folder === 'string') {
        result['Fasade-AI'].qnap.add(row.nacrt_folder);  // prefix marker
      }
      // dimenzije_fasade.knjiga_procelja[]
      if (row.dimenzije_fasade) {
        try {
          const dim = typeof row.dimenzije_fasade === 'string' 
            ? JSON.parse(row.dimenzije_fasade) 
            : row.dimenzije_fasade;
          if (dim && Array.isArray(dim.knjiga_procelja)) {
            for (const proc of dim.knjiga_procelja) {
              if (!proc) continue;
              ['slika_qnap_path', 'slika_hatch_qnap_path'].forEach(c => {
                if (proc[c] && typeof proc[c] === 'string') result['Fasade-AI'].qnap.add(proc[c]);
              });
              ['slika_b2_path', 'slika_hatch_b2_path', 'slika_anotirana_b2_path'].forEach(c => {
                if (proc[c] && typeof proc[c] === 'string') result['Fasade-AI'].b2.add(proc[c]);
              });
            }
          }
        } catch(_) {}
      }
    }
  } catch (e) {
    console.warn('[orphan-audit] _buildActivePathsByRoot fasade_procjene:', e.message);
  }
  
  return result;
}

// Helper: provjeri je li file ispod jednog od poznatih nacrt_folder-a iz Fasade-AI
//   (file unutar nacrt_folder/ je valjan ako je folder referenciran u DB-u)
function _isUnderNacrtFolder(filePath, fasadeAiQnap) {
  if (!filePath.startsWith('Fasade-AI/')) return false;
  for (const p of fasadeAiQnap) {
    if (!p) continue;
    // Heuristika: ako referenca u DB-u izgleda kao folder (bez ekstenzije), 
    // smatraj sve unutar njega valjanim. Više od običnog "startsWith" je 
    // potrebno jer je p direktno dodano kao referenca foldera (nacrt_folder stupac).
    if (!p.includes('.') && filePath.startsWith(p + '/')) return true;
  }
  return false;
}

// Helper: skeniraj QNAP rekurzivno za sve root-ove
async function _scanQnapForOrphans(activeByRoot) {
  const orphans = [];  // { root, path, size, location: 'qnap' }
  const totals = {};   // { root: count }
  const broken = [];   // reverse: DB ima path, file ne postoji
  
  for (const root of Object.keys(ORPHAN_AUDIT_CONFIG.roots)) {
    totals[root] = 0;
    const active = activeByRoot[root]?.qnap || new Set();
    
    let scan;
    try {
      scan = await qnapListRecursive(root, { maxFiles: ORPHAN_AUDIT_CONFIG.maxFilesScan, maxDepth: 8 });
    } catch (e) {
      console.warn(`[orphan-audit] qnapListRecursive ${root} fail:`, e.message);
      continue;
    }
    if (!scan || !Array.isArray(scan.files)) continue;
    
    const filesOnDisk = new Set();
    
    for (const f of scan.files) {
      filesOnDisk.add(f.path);
      totals[root]++;
      
      // Da li je file orphan?
      if (active.has(f.path)) continue;  // u DB-u → valjan
      
      // Excel export u dozvoljenom folderu — preskoči
      if (ORPHAN_AUDIT_CONFIG.excelPatterns.some(p => p.test(f.path))) continue;
      
      // Fasade-AI: provjeri je li ispod nacrt_folder-a
      if (root === 'Fasade-AI' && _isUnderNacrtFolder(f.path, active)) continue;
      
      orphans.push({ root, path: f.path, size: f.size || 0, location: 'qnap' });
    }
    
    // Reverse audit: DB path-evi koji nisu na disku
    for (const dbPath of active) {
      if (!dbPath || dbPath.includes('.') === false) continue;  // skip folder markeri
      // Skip B2-only situations (path može biti referenca ali file je u B2)
      if (!filesOnDisk.has(dbPath)) {
        broken.push({ root, path: dbPath, location: 'qnap_missing' });
      }
    }
  }
  
  return { orphans, totals, broken };
}

// Helper: skeniraj B2 za sve root-ove
async function _scanB2ForOrphans(activeByRoot) {
  if (!b2Enabled() || typeof b2ListByPrefix !== 'function') {
    return { orphans: [], totals: {}, broken: [], skipped: 'b2-disabled' };
  }
  
  const orphans = [];
  const totals = {};
  const broken = [];
  
  for (const root of Object.keys(ORPHAN_AUDIT_CONFIG.roots)) {
    totals[root] = 0;
    const active = activeByRoot[root]?.b2 || new Set();
    
    let list;
    try {
      list = await b2ListByPrefix(root + '/');
    } catch (e) {
      console.warn(`[orphan-audit] b2ListByPrefix ${root} fail:`, e.message);
      continue;
    }
    if (!list || !Array.isArray(list)) continue;
    
    const filesInB2 = new Set();
    
    for (const f of list) {
      const fileName = f.fileName;
      filesInB2.add(fileName);
      totals[root]++;
      
      if (active.has(fileName)) continue;
      
      // Excel — preskoči
      if (ORPHAN_AUDIT_CONFIG.excelPatterns.some(p => p.test(fileName))) continue;
      
      // Fasade-AI: ispod nacrt_folder-a?
      if (root === 'Fasade-AI' && _isUnderNacrtFolder(fileName, activeByRoot['Fasade-AI']?.qnap || new Set())) continue;
      
      orphans.push({ 
        root, 
        path: fileName, 
        size: f.contentLength || 0, 
        location: 'b2' 
      });
    }
    
    // Reverse za B2
    for (const dbPath of active) {
      if (!dbPath || !filesInB2.has(dbPath)) {
        broken.push({ root, path: dbPath, location: 'b2_missing' });
      }
    }
  }
  
  return { orphans, totals, broken };
}

// ──────────────────────────────────────────────────────────────────────────
// GET /api/orphan-audit/full — DIREKTOR ONLY — dry-run scan
// ──────────────────────────────────────────────────────────────────────────
app.get('/api/orphan-audit/full', auth, direktor, async (req, res) => {
  try {
    const startTs = Date.now();
    
    // 1) Pokupi sve aktivne paths iz DB-a
    const activeByRoot = await _buildActivePathsByRoot();
    
    // 2) Paralelno skeniraj QNAP + B2
    const [qnapScan, b2Scan] = await Promise.all([
      _scanQnapForOrphans(activeByRoot),
      _scanB2ForOrphans(activeByRoot)
    ]);
    
    // 3) Spoji orphan listu (QNAP + B2)
    const allOrphans = [...qnapScan.orphans, ...b2Scan.orphans];
    const allBroken = [...qnapScan.broken, ...(b2Scan.broken || [])];
    
    // 4) Statistika po root-u
    const perRoot = {};
    for (const root of Object.keys(ORPHAN_AUDIT_CONFIG.roots)) {
      perRoot[root] = {
        qnap_files_scanned: qnapScan.totals[root] || 0,
        b2_files_scanned: b2Scan.totals?.[root] || 0,
        active_in_db: (activeByRoot[root]?.qnap.size || 0) + (activeByRoot[root]?.b2.size || 0),
        orphans_qnap: qnapScan.orphans.filter(o => o.root === root).length,
        orphans_b2: b2Scan.orphans.filter(o => o.root === root).length,
        broken_qnap: qnapScan.broken.filter(b => b.root === root).length,
        broken_b2: (b2Scan.broken || []).filter(b => b.root === root).length,
        total_orphan_size_kb: Math.round(
          allOrphans.filter(o => o.root === root).reduce((s, o) => s + (o.size || 0), 0) / 1024
        )
      };
    }
    
    const elapsedMs = Date.now() - startTs;
    
    console.log(`[orphan-audit/full] direktor=${req.user.id} ${allOrphans.length} orphan, ${allBroken.length} broken, ${elapsedMs}ms`);
    
    res.json({
      ok: true,
      orphans_count: allOrphans.length,
      orphans: allOrphans,           // [{ root, path, size, location }]
      broken_count: allBroken.length,
      broken: allBroken,             // [{ root, path, location }]
      per_root: perRoot,
      b2_enabled: b2Enabled(),
      elapsed_ms: elapsedMs,
      ts: new Date().toISOString()
    });
  } catch (e) {
    console.error('[orphan-audit/full]', e);
    res.status(500).json({ error: e.message });
  }
});

// ──────────────────────────────────────────────────────────────────────────
// POST /api/orphan-audit/cleanup — DIREKTOR ONLY — briše po listi
//   Body: { paths: [{ root, path, location: 'qnap'|'b2' }], dry_run?: bool }
// ──────────────────────────────────────────────────────────────────────────
app.post('/api/orphan-audit/cleanup', auth, direktor, async (req, res) => {
  try {
    const { paths, dry_run } = req.body || {};
    if (!Array.isArray(paths) || paths.length === 0) {
      return res.status(400).json({ error: 'Treba poslati array `paths` s objektima { root, path, location }' });
    }
    if (paths.length > 5000) {
      return res.status(400).json({ error: 'Maximalno 5000 path-eva po pozivu' });
    }
    
    // RE-VERIFIKACIJA: pokupi DB paths ponovo da hvatamo race condition 
    // (file je u međuvremenu dobio DB referencu — npr. korisnik je istovremeno upload-ao novu sliku)
    const activeByRoot = await _buildActivePathsByRoot();
    
    const obrisani = [];
    const odbijeni = [];
    const greski = [];
    
    // Safety check za svaku stavku
    const _validate = (item) => {
      if (!item || typeof item !== 'object') return 'invalid item';
      const { root, path: p, location } = item;
      if (!root || typeof root !== 'string') return 'missing root';
      if (!p || typeof p !== 'string') return 'missing path';
      if (!location || (location !== 'qnap' && location !== 'b2')) return 'invalid location';
      if (!ORPHAN_AUDIT_CONFIG.roots[root]) return 'root not in whitelist';
      if (!p.startsWith(root + '/')) return 'path ne počinje s root prefix';
      if (p.includes('..') || p.includes('//') || p.includes('\\') || p.includes('\0')) return 'sumnjivi karakteri u path-u';
      // Re-check da je još uvijek orphan (race protection)
      const active = activeByRoot[root];
      if (location === 'qnap' && active.qnap.has(p)) return 'path je u međuvremenu postao aktivan u DB-u (QNAP)';
      if (location === 'b2' && active.b2.has(p)) return 'path je u međuvremenu postao aktivan u DB-u (B2)';
      // Excel safe
      if (ORPHAN_AUDIT_CONFIG.excelPatterns.some(re => re.test(p))) return 'Excel export — sigurnosni skip';
      // Fasade-AI nacrt folder safe
      if (root === 'Fasade-AI' && _isUnderNacrtFolder(p, active.qnap)) return 'ispod nacrt_folder-a iz DB-a';
      return null;
    };
    
    if (dry_run) {
      // Samo validacija, ne briše
      for (const item of paths) {
        const err = _validate(item);
        if (err) odbijeni.push({ item, razlog: err });
        else obrisani.push(item);  // u dry_run modu, "obrisani" = "would-be deleted"
      }
      return res.json({
        ok: true,
        dry_run: true,
        would_delete: obrisani.length,
        rejected: odbijeni.length,
        odbijeni
      });
    }
    
    // Stvarno brisanje — batch paralelno
    for (let i = 0; i < paths.length; i += ORPHAN_AUDIT_CONFIG.deleteBatchSize) {
      const chunk = paths.slice(i, i + ORPHAN_AUDIT_CONFIG.deleteBatchSize);
      await Promise.all(chunk.map(async (item) => {
        const err = _validate(item);
        if (err) {
          odbijeni.push({ item, razlog: err });
          return;
        }
        try {
          let ok = false;
          if (item.location === 'qnap') {
            ok = await qnapDeleteFile(item.path);
          } else if (item.location === 'b2') {
            ok = await b2Delete(item.path);
          }
          if (ok) {
            obrisani.push(item);
          } else {
            greski.push({ item, error: 'delete returned false' });
          }
        } catch (e) {
          greski.push({ item, error: e.message });
        }
      }));
    }
    
    console.log(`[orphan-audit/cleanup] direktor=${req.user.id}: ${obrisani.length} obrisano, ${odbijeni.length} odbijeno, ${greski.length} grešaka`);
    
    res.json({
      ok: true,
      obrisano: obrisani.length,
      odbijeno: odbijeni.length,
      greske: greski.length,
      odbijeni: odbijeni.slice(0, 50),
      greski_detalji: greski.slice(0, 50)
    });
  } catch (e) {
    console.error('[orphan-audit/cleanup]', e);
    res.status(500).json({ error: e.message });
  }
});

// ──────────────────────────────────────────────────────────────────────────
// CRON: tjedni auto dry-run (nedjelja ~03:00 UTC) → push direktoru ako ima orphan-a
// ──────────────────────────────────────────────────────────────────────────
async function _orphanAuditWeeklyCron() {
  try {
    const now = new Date();
    // Trigger samo nedjeljom (0) između 03:00-03:59 UTC
    if (now.getUTCDay() !== 0) return;
    if (now.getUTCHours() !== 3) return;
    
    // Throttle: jednom tjedno (provjeri zadnji run kroz postavke tablicu)
    const lastR = await pool.query(
      `SELECT vrijednost FROM postavke WHERE kljuc='orphan_audit_last_run'`
    ).catch(() => ({ rows: [] }));
    const last = lastR.rows[0]?.vrijednost;
    if (last) {
      const lastTs = new Date(last);
      const hoursAgo = (now - lastTs) / (1000 * 60 * 60);
      if (hoursAgo < 24 * 6) {  // <6 dana — preskoči
        return;
      }
    }
    
    console.log('[orphan-audit cron] Pokrećem tjedni audit...');
    
    const activeByRoot = await _buildActivePathsByRoot();
    const [qnapScan, b2Scan] = await Promise.all([
      _scanQnapForOrphans(activeByRoot),
      _scanB2ForOrphans(activeByRoot)
    ]);
    
    const totalOrphans = qnapScan.orphans.length + b2Scan.orphans.length;
    const totalSizeKb = Math.round(
      [...qnapScan.orphans, ...b2Scan.orphans].reduce((s, o) => s + (o.size || 0), 0) / 1024
    );
    
    // Spremi last_run
    await pool.query(
      `INSERT INTO postavke (kljuc, vrijednost) VALUES ('orphan_audit_last_run', $1)
       ON CONFLICT (kljuc) DO UPDATE SET vrijednost = $1`,
      [now.toISOString()]
    ).catch(() => {});
    
    if (totalOrphans === 0) {
      console.log('[orphan-audit cron] ✓ Cloud je čist — 0 orphan-a');
      return;
    }
    
    // Pošalji push direktoru
    const dirR = await pool.query(
      `SELECT id FROM radnici WHERE role='direktor' AND aktivan=true LIMIT 1`
    );
    if (dirR.rows.length === 0) {
      console.warn('[orphan-audit cron] Nema aktivnog direktora — preskačem push');
      return;
    }
    const dirId = dirR.rows[0].id;
    
    const sizeMb = (totalSizeKb / 1024).toFixed(1);
    await sendPushToUser(
      dirId,
      '🧹 Cloud cleanup — pronađeni orphan fileovi',
      `${totalOrphans} fajlova (${sizeMb} MB) ne pripada nijednom DB zapisu. Otvori Backup tab za pregled i brisanje.`,
      '/?tab=backup'
    );
    
    console.log(`[orphan-audit cron] ✓ Push poslat direktoru: ${totalOrphans} orphan, ${sizeMb} MB`);
  } catch (e) {
    console.error('[orphan-audit cron]:', e.message);
  }
}

// Pokreni svakih 30 min (sličan pattern kao autoBackupCheck) — funkcija sama provjerava 
// dan u tjednu i sat. Plus throttle preko postavke tablice.
setInterval(_orphanAuditWeeklyCron, 30 * 60 * 1000);
// Prvi check 10 min nakon starta (Railway restart zaštita)
setTimeout(_orphanAuditWeeklyCron, 10 * 60 * 1000);


app.delete('/api/fasada/:id', auth, staff, async (req, res) => {
  try {
    const procjenaId = parseInt(req.params.id);
    // ⭐ v1147 (Ivan): BRISANJE IZ AI KNJIGA = ARHIVIRANJE, NE UNIŠTENJE.
    //   Arhiva je ISTI red u `fasade_procjene` (`aktivna = FALSE` + `arhivirana_at`) — pa je
    //   `DELETE FROM fasade_procjene` briše ZAJEDNO s knjigom, a uz nju i slike s QNAP-a.
    //   Građevinska knjiga je dokaz izvedenog rada; ona se ne uništava klikom na koš. Knjiga
    //   nestaje iz AI knjiga, ostaje u Arhivi, slike se NE diraju.
    //   Trajno brisanje i dalje postoji, ali se mora izričito zatražiti: `?trajno=1`.
    if (String((req.query && req.query.trajno) || '') !== '1') {
      const ar = await pool.query(
        `UPDATE fasade_procjene
            SET aktivna = FALSE,
                arhivirana_at = COALESCE(arhivirana_at, NOW())
          WHERE id = $1 AND COALESCE(aktivna, TRUE) = TRUE
          RETURNING id, naziv_objekta`, [procjenaId]);
      if (!ar.rows.length) {
        const post = await pool.query('SELECT id FROM fasade_procjene WHERE id=$1', [procjenaId]);
        if (!post.rows.length) return res.status(404).json({ error: 'Knjiga ne postoji' });
        return res.json({ ok: true, arhivirano: true, vec_arhivirano: true,
          poruka: 'Knjiga je već u arhivi.' });
      }
      console.log('[Fasada v1147] knjiga ' + procjenaId + ' ARHIVIRANA (ne obrisana) — slike netaknute');
      return res.json({ ok: true, arhivirano: true,
        poruka: 'Maknuto iz AI knjiga — ostaje u Arhivi.' });
    }
    // Dohvati sve QNAP path-eve + B2 path-eve + naziv gradilišta + naziv objekta
    // ⭐ v135.7.255: proširen SELECT s B2 path stupcima (orphan files fix)
    const r = await pool.query(`
      SELECT f.slika_qnap_path, f.ai_anotirana_slika, f.gradiliste_id, 
             f.naziv_objekta, f.tip_procjene, f.dimenzije_fasade,
             f.nacrt_folder, f.nacrt_pdf_qnap_path,
             f.slika_b2_path, f.slika_hatch_b2_path, f.ai_anotirana_b2_path,
             f.pdf_b2_path, f.nacrt_pdf_b2_path,
             g.naziv AS grad_naziv
      FROM fasade_procjene f
      LEFT JOIN gradilista g ON g.id = f.gradiliste_id
      WHERE f.id = $1
    `, [procjenaId]);
    
    if (!r.rows.length) return res.status(404).json({ error: 'Knjiga ne postoji' });
    
    const qnapPath = r.rows[0]?.slika_qnap_path;
    const anotPath = r.rows[0]?.ai_anotirana_slika;
    const gradId = r.rows[0]?.gradiliste_id;
    const gradNaziv = r.rows[0]?.grad_naziv || '';
    const nazivObjekta = r.rows[0]?.naziv_objekta;
    const dimFasade = r.rows[0]?.dimenzije_fasade;
    const nacrtFolder = r.rows[0]?.nacrt_folder;  // ⭐ v135.7.186
    const isBrzaBezGradilista = r.rows[0]?.tip_procjene === 'brza' && !gradId && nazivObjekta;
    const tipProc = r.rows[0]?.tip_procjene;
    
    // ⭐ v135.7.255: B2 paths (orphan files fix)
    const slikaB2 = r.rows[0]?.slika_b2_path;
    const slikaHatchB2 = r.rows[0]?.slika_hatch_b2_path;
    const aiAnotiranaB2 = r.rows[0]?.ai_anotirana_b2_path;
    const pdfB2 = r.rows[0]?.pdf_b2_path;
    const nacrtPdfB2 = r.rows[0]?.nacrt_pdf_b2_path;

    // ⭐ v135.7.265 (Ivanovo pravilo: "1 knjiga = 1 gradilište = 1 folder"):
    //   Pri brisanju DETALJNE procjene briše se cijela knjiga gradilišta:
    //   - Sve aktivne + arhivirane procjene tog gradilišta iz DB-a
    //   - Cijeli QNAP folder Fasade-AI/{gradiliste}/ (rekurzivno)
    //   - Cijeli B2 prefix Fasade-AI/{gradiliste}/
    //   Razlog: u ovom modelu jedno gradilište ima jednu knjigu — pri brisanju
    //   se sve odlazi. Nema "ostatka", nema "arhive", nema dvosmislenosti.
    //   
    //   Brze procjene zadržavaju staru logiku (folder se briše samo ako je zadnja).
    // ⭐ v135.7.265 → v501 REFACTOR (Ivan, 19.05.2026):
    //   PRIJE v501: "Ivanovo pravilo 1 knjiga = 1 gradilište = 1 folder" je DELETE detaljne knjige 
    //   brisao SVE procjene gradilišta (uključujući brze procjene radnih sati, materijala, 
    //   arhivirane). Brisanje samo JEDNE detaljne knjige je tiho brisalo i sve ostale 
    //   povezane procjene bez upozorenja.
    //   
    //   SAD v501: konzervativno — briše SAMO ovu procjenu (procjenaId). QNAP folder gradilišta 
    //   se briše SAMO ako je ovo bila ZADNJA detaljna procjena za to gradilište (npr. korisnik 
    //   ima 1 detaljnu + 2 brze → briše detaljnu → folder ostaje (brze ne koriste folder, 
    //   ali za sigurnost zadržavamo)). Ako bi ostala 0 detaljnih, folder briše.
    //   
    //   Ako Ivan zaista želi "obriši SVE procjene gradilišta", to je sad poseban flow 
    //   kroz brisanje gradilišta u Gradilišta tabu (postojeći permanent delete).
    const isDetaljnaKnjiga = !isBrzaBezGradilista && gradId && (tipProc === 'detaljna' || !tipProc);
    let folderCleanupTreba = false;
    
    if (isDetaljnaKnjiga) {
      // ⭐ v295 (Ivan): NULL audit log procjena_id PRIJE brisanja
      try {
        await pool.query(
          `UPDATE fasada_aktivnost SET procjena_id = NULL 
           WHERE procjena_id = $1 
             AND akcija NOT IN ('obrisana', 'bulk_obrisano', 'obrisana_naknadno')`,
          [procjenaId]
        );
      } catch(_) { /* swallow */ }
      
      // ⭐ v501: Briši SAMO ovu procjenu
      await pool.query('DELETE FROM fasade_procjene WHERE id=$1', [procjenaId]);
      console.log(`[Fasada DELETE detaljna v501] knjiga ${procjenaId} obrisana iz DB-a (SAMO ta, ostale za gradilište ${gradId} ostaju)`);
      
      // Provjeri ima li još detaljnih procjena za gradilište — ako NE, folder treba cleanup
      try {
        const ostatak = await pool.query(
          `SELECT COUNT(*) AS cnt FROM fasade_procjene 
           WHERE gradiliste_id = $1 AND (tip_procjene = 'detaljna' OR tip_procjene IS NULL)`,
          [gradId]
        );
        const ostaloDet = parseInt(ostatak.rows[0]?.cnt) || 0;
        folderCleanupTreba = (ostaloDet === 0);
        console.log(`[Fasada DELETE detaljna v501] preostalih detaljnih za gradilište ${gradId}: ${ostaloDet} → folder cleanup ${folderCleanupTreba ? 'TREBA' : 'preskačem'}`);
      } catch(eCnt) {
        console.warn('[Fasada DELETE detaljna v501] count check fail:', eCnt.message);
      }
    } else {
      // ⭐ v295 (Ivan): NULL audit log procjena_id PRIJE brisanja
      try {
        await pool.query(
          `UPDATE fasada_aktivnost SET procjena_id = NULL 
           WHERE procjena_id = $1 
             AND akcija NOT IN ('obrisana', 'bulk_obrisano', 'obrisana_naknadno')`,
          [procjenaId]
        );
      } catch(_) { /* swallow */ }
      
      // Brza procjena (ili neki edge case) — obriši samo ovu procjenu
      await pool.query('DELETE FROM fasade_procjene WHERE id=$1', [procjenaId]);
    }
    
    // ⭐ v124: Activity log za brisanje
    logFasActivity(
      req.user,
      'obrisana',
      tipProc === 'brza' ? 'brza' : 'knjiga',
      procjenaId,
      gradId,
      nazivObjekta || gradNaziv || `#${procjenaId}`
    ).catch(e => console.warn('[caught]', e?.message || String(e), e?.position ? 'poz=' + e.position : ''));

    // Obriši i s QNAP-a (best-effort, ne blokira odgovor)
    if (process.env.QNAP_WEBDAV_URL) {
      setImmediate(async () => {
        try {
          const folderNew = isBrzaBezGradilista 
            ? fasadaQnapFolder('_BrzeProcjene/' + nazivObjekta)
            : fasadaQnapFolder(gradNaziv || 'gradiliste');
          
          // ═══════════════════════════════════════════════════════════════════
          // ⭐ DETALJNA KNJIGA: briše QNAP folder gradilišta SAMO ako je ovo bila ZADNJA detaljna
          //   (v501 fix — Ivan: ne briši cijelo gradilište ako imam još procjena za njega)
          // ═══════════════════════════════════════════════════════════════════
          if (isDetaljnaKnjiga && folderCleanupTreba) {
            console.log(`[Fasada DELETE detaljna v501] zadnja detaljna knjiga za gradilište → briše folder: ${folderNew}`);
            try {
              await qnapDeleteFolder(folderNew);
              console.log(`[Fasada DELETE detaljna v501] QNAP folder OBRISAN: ${folderNew}`);
            } catch (e) {
              console.warn(`[Fasada DELETE detaljna v501] QNAP folder delete fail (best-effort):`, e.message);
            }
            
            // ⭐ v282 (Ivan #3+#6): BACKWARD COMPAT — pokušaj obrisati i stari format
            //   foldera s razmacima i č/š/đ (pre-v282 nacrt upload je koristio 
            //   `_sanitNazivZaQnap` koji NIJE transliterirao). Best-effort: ako ne 
            //   postoji, qnapDeleteFolder vraća false bez exception-a.
            //   Primjer: gradNaziv="Gornje Vrapče" 
            //     folderNew = "Fasade-AI/Gornje_Vrapce" (već obrisan gore)
            //     folderLegacy = "Fasade-AI/Gornje Vrapče" (ovaj sad brišemo)
            const folderLegacy = `Fasade-AI/${(gradNaziv || '').replace(/[^a-zA-Z0-9čćžšđČĆŽŠĐ\-_ ]/g, '').trim()}`;
            if (folderLegacy !== folderNew) {
              try {
                await qnapDeleteFolder(folderLegacy);
                console.log(`[Fasada DELETE detaljna] LEGACY QNAP folder OBRISAN: ${folderLegacy}`);
              } catch (e) {
                console.warn(`[Fasada DELETE detaljna] legacy folder delete fail (best-effort):`, e.message);
              }
            }
            
            // B2 cloud cleanup — briše SVE pod prefix-om Fasade-AI/{gradiliste}/
            if (b2Enabled()) {
              try {
                const stats = await b2DeleteByPrefix(folderNew + '/');
                console.log(`[Fasada DELETE detaljna] B2 prefix "${folderNew}/": ${stats.deleted} obrisano, ${stats.errors} grešaka`);
              } catch (eB2) {
                console.error(`[Fasada DELETE detaljna] B2 prefix cleanup greška:`, eB2.message);
              }
              // ⭐ v282: B2 cleanup za legacy folder format
              if (folderLegacy !== folderNew) {
                try {
                  const statsL = await b2DeleteByPrefix(folderLegacy + '/');
                  if (statsL.deleted > 0) console.log(`[Fasada DELETE detaljna] B2 legacy prefix "${folderLegacy}/": ${statsL.deleted} obrisano`);
                } catch (eB2L) {
                  console.warn(`[Fasada DELETE detaljna] B2 legacy prefix cleanup greška:`, eB2L.message);
                }
              }
            }
            
            // Legacy: collective Excel-i u Fasade-AI rootu (stara struktura)
            const safeName = (gradNaziv || '').replace(/[^\w\u00c0-\u017f]/g, '_').slice(0, 50);
            try { await qnapDeleteFile(`Fasade-AI/Obracun_fasada_${safeName}_sve.xlsx`); } catch(_) {}
            try { await qnapDeleteFile(`Fasade-AI/Obracun_fasada_${safeName}_grad${gradId}.xlsx`); } catch(_) {}
            
            // Skip stari file-po-file flow — sve je već obrisano s folder-om
            return;
          }
          
          // ═══════════════════════════════════════════════════════════════════
          // BRZA PROCJENA ili edge case: stari file-po-file flow
          // ═══════════════════════════════════════════════════════════════════
          
          // 1) Obriši ORIGINALNU sliku (poznati path)
          if (qnapPath) {
            const ok = await qnapDeleteFile(qnapPath);
            console.log(`[Fasada DELETE proc${procjenaId}] originalna slika: ${qnapPath} → ${ok ? 'OBRISANA' : 'NIJE OBRISANA'}`);
          }
          
          // 2) Obriši ANOTIRANU sliku (poznati path)
          if (anotPath && typeof anotPath === 'string' &&
              (anotPath.startsWith('Fasade-AI/') || anotPath.startsWith('Fasada/'))) {
            const ok = await qnapDeleteFile(anotPath);
            console.log(`[Fasada DELETE proc${procjenaId}] anotirana: ${anotPath} → ${ok ? 'OBRISANA' : 'NIJE OBRISANA'}`);
          }
          
          // 2b) MULTI-PROČELJE KNJIGA: cleanup per-pročelje slika i foldera
          //     Inače: orphan slike u Procelje-{i}-{oznaka} subfolderima ostaju zauvijek.
          if (dimFasade && Array.isArray(dimFasade.knjiga_procelja)) {
            for (let i = 0; i < dimFasade.knjiga_procelja.length; i++) {
              const p = dimFasade.knjiga_procelja[i];
              if (!p) continue;
              
              // 2b-i) Obriši pojedinu sliku po path-u
              if (p.slika_qnap_path && typeof p.slika_qnap_path === 'string') {
                try {
                  await qnapDeleteFile(p.slika_qnap_path);
                  console.log(`[Fasada DELETE proc${procjenaId}] P${i+1} slika: ${p.slika_qnap_path}`);
                } catch(_) {}
              }
              
              // 2b-i.5) Obriši hatch sliku po path-u
              if (p.slika_hatch_qnap_path && typeof p.slika_hatch_qnap_path === 'string') {
                try {
                  await qnapDeleteFile(p.slika_hatch_qnap_path);
                  console.log(`[Fasada DELETE proc${procjenaId}] P${i+1} hatch: ${p.slika_hatch_qnap_path}`);
                } catch(_) {}
              }
              
              // 2b-ii) Obriši cijeli Procelje-{oznakaSafe} subfolder
              //   ⭐ v280 (Ivan #1): briše OBA formata — novi (bez indeksa, v280+) 
              //   i stari (s indeksom, v275-v279) za backward compat. Best-effort 
              //   — ako format ne postoji, qnapDeleteFolder vraća false bez exception-a.
              try {
                const oznakaSafe = (p.oznaka || `Procelje-${i+1}`).replace(/[/\\:*?"<>|]/g, '_').slice(0, 40);
                const procFolderNew = `${folderNew}/Procelje-${oznakaSafe}`;
                const procFolderOld = `${folderNew}/Procelje-${i+1}-${oznakaSafe}`;
                if (typeof qnapDeleteFolder === 'function') {
                  await qnapDeleteFolder(procFolderNew).catch(() => {});
                  await qnapDeleteFolder(procFolderOld).catch(() => {});
                  console.log(`[Fasada DELETE proc${procjenaId}] P${i+1} folders cleanup: ${procFolderNew} + ${procFolderOld}`);
                }
              } catch(eFolder) {
                console.warn(`[Fasada DELETE proc${procjenaId}] P${i+1} folder cleanup fail:`, eFolder.message);
              }
            }
          }
          
          // ⭐ v135.7.186: PDF AI knjiga — obriši nacrt folder (PDF + sve rasterizirane stranice)
          if (nacrtFolder && typeof nacrtFolder === 'string' && nacrtFolder.startsWith('Fasade-AI/')) {
            try {
              await qnapDeleteFolder(nacrtFolder);
              console.log(`[Fasada DELETE proc${procjenaId}] nacrt folder: ${nacrtFolder} → OBRISAN`);
            } catch (e) {
              console.warn(`[Fasada DELETE proc${procjenaId}] nacrt folder cleanup fail:`, e.message);
            }
          }
          
          // 3) PATTERN BRISANJE: listaj folder + obriši SVE fajlove koji sadrže "proc{id}"
          //    To hvata Excel + slike + sve drugo što nije u DB-u (orphan fajlove)
          console.log(`[Fasada DELETE proc${procjenaId}] folder: ${folderNew}, isBrzaBezGradilista=${isBrzaBezGradilista}, naziv_objekta="${nazivObjekta}"`);
          const procPattern = `proc${procjenaId}`;
          const obrisanihNova = await qnapDeleteByPattern(folderNew, procPattern);
          const obrisanihRoot = await qnapDeleteByPattern('Fasade-AI', procPattern);
          console.log(`[Fasada DELETE proc${procjenaId}] pattern: ${obrisanihNova} u folderu, ${obrisanihRoot} u Fasade-AI rootu`);
          
          // ⭐ v135.7.255: B2 CLOUD CLEANUP za brze procjene (legacy)
          if (b2Enabled()) {
            try {
              const b2Paths = [];
              if (slikaB2) b2Paths.push(slikaB2);
              if (slikaHatchB2) b2Paths.push(slikaHatchB2);
              if (aiAnotiranaB2) b2Paths.push(aiAnotiranaB2);
              if (pdfB2) b2Paths.push(pdfB2);
              if (nacrtPdfB2) b2Paths.push(nacrtPdfB2);
              
              // Per-procelje B2 paths
              if (dimFasade && Array.isArray(dimFasade.knjiga_procelja)) {
                dimFasade.knjiga_procelja.forEach(p => {
                  if (p?.slika_b2_path) b2Paths.push(p.slika_b2_path);
                  if (p?.slika_hatch_b2_path) b2Paths.push(p.slika_hatch_b2_path);
                  if (p?.slika_anotirana_b2_path) b2Paths.push(p.slika_anotirana_b2_path);
                });
              }
              
              if (b2Paths.length > 0) {
                const results = await Promise.all(b2Paths.map(async (p) => {
                  try { return { path: p, ok: await b2Delete(p) }; }
                  catch (e) { return { path: p, ok: false }; }
                }));
                const ok = results.filter(r => r.ok).length;
                console.log(`[Fasada DELETE proc${procjenaId}] B2 individual: ${ok}/${b2Paths.length} obrisano`);
              }
              
              if (nacrtFolder && typeof nacrtFolder === 'string' && nacrtFolder.startsWith('Fasade-AI/')) {
                try {
                  const stats = await b2DeleteByPrefix(nacrtFolder + '/');
                  console.log(`[Fasada DELETE proc${procjenaId}] B2 nacrt folder "${nacrtFolder}": ${stats.deleted} obrisano`);
                } catch (eNacrt) {
                  console.warn(`[Fasada DELETE proc${procjenaId}] B2 nacrt folder fail:`, eNacrt.message);
                }
              }
            } catch (eB2) {
              console.error(`[Fasada DELETE proc${procjenaId}] B2 cleanup section greška:`, eB2.message);
            }
          }
          
          // 4) Brza procjena: provjeri preostale i obriši folder ako je zadnja
          if (isBrzaBezGradilista) {
            const ostatakR = await pool.query(
              `SELECT COUNT(*) AS cnt FROM fasade_procjene WHERE naziv_objekta=$1 AND tip_procjene='brza' AND gradiliste_id IS NULL`,
              [nazivObjekta]
            );
            const ostatakCnt = parseInt(ostatakR.rows[0]?.cnt || 0);
            if (ostatakCnt === 0) {
              await qnapDeleteFolder(folderNew);
              console.log(`[Fasada DELETE brza] obrisan folder _BrzeProcjene/${nazivObjekta} (zadnja knjiga)`);
            }
          }
        } catch(e) { console.error('[Fasada DELETE] QNAP greška:', e.message); }
      });
    }

    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

