// ⭐ v135.7.6: REFERENCE + PORTFOLIO endpoints — MORAJU BITI PRIJE 404 catch-all
//    Bug fix: prije su bile POSLIJE app.get('*'), pa ih je 404 handler hvatao
// ═══════════════════════════════════════════════════════════════════════════

// Helper: sanitize naziv gradilišta za file system path
function _refSanitizeGradName(naziv) {
  return String(naziv || 'Bez-gradilista')
    .replace(/[/\\:*?"<>|]/g, '_')
    .replace(/\s+/g, '-')
    .slice(0, 60);
}

// ⭐ v135.7.127 (BUG FIX REF-01): Lightweight image dimension parser
//   Bez sharp/image-size dependency-a — parse JPEG/PNG header manually.
//   JPEG: traži SOF marker (0xFFC0-0xFFC3, 0xFFC5-0xFFC7, 0xFFC9-0xFFCB, 0xFFCD-0xFFCF)
//   PNG:  prvi IHDR chunk (na offsetu 16, big-endian uint32 width/height)
function _getImageDimensions(buf) {
  if (!buf || buf.length < 24) return null;
  
  // PNG: 89 50 4E 47 0D 0A 1A 0A → IHDR @ 16
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) {
    const width = buf.readUInt32BE(16);
    const height = buf.readUInt32BE(20);
    return { width, height };
  }
  
  // JPEG: FF D8
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    let offset = 2;
    while (offset < buf.length - 8) {
      // Marker mora biti 0xFF
      if (buf[offset] !== 0xFF) return null;
      const marker = buf[offset + 1];
      offset += 2;
      // SOF markers (Start of Frame)
      if ((marker >= 0xC0 && marker <= 0xC3) || 
          (marker >= 0xC5 && marker <= 0xC7) || 
          (marker >= 0xC9 && marker <= 0xCB) || 
          (marker >= 0xCD && marker <= 0xCF)) {
        // Length (2) + Precision (1) + Height (2) + Width (2)
        const height = buf.readUInt16BE(offset + 3);
        const width = buf.readUInt16BE(offset + 5);
        return { width, height };
      }
      // Skip ovaj segment
      const segLen = buf.readUInt16BE(offset);
      offset += segLen;
    }
    return null;
  }
  
  return null;
}

// POST /api/reference/upload — primi sliku (base64), uploadaj na QNAP, zapiši u DB
app.post('/api/reference/upload', auth, staff, async (req, res) => {
  try {
    const { gradiliste_id, slika_base64, opis, zanimljivi_detalj, thumb_base64 } = req.body || {};
    if (!gradiliste_id) return res.status(400).json({ error: 'Gradilište je obavezno' });
    if (!slika_base64 || typeof slika_base64 !== 'string') {
      return res.status(400).json({ error: 'Slika nedostaje' });
    }
    const gr = await pool.query('SELECT naziv, qnap_folder FROM gradilista WHERE id = $1', [gradiliste_id]);
    if (!gr.rows.length) return res.status(404).json({ error: 'Gradilište ne postoji' });
    
    // ⭐ v135.7.127 (BUG FIX REF-02): immutable qnap_folder
    //   Ako gradilište nema qnap_folder → generiraj iz trenutnog naziva + spremi PERMANENTNO.
    //   Sve buduće reference idu u taj isti folder, čak i ako se naziv kasnije mijenja.
    let folderSafe = gr.rows[0].qnap_folder;
    if (!folderSafe) {
      folderSafe = _refSanitizeGradName(gr.rows[0].naziv || `gradilište-${gradiliste_id}`);
      // Spremi za sve buduće upload-e (best-effort)
      await pool.query('UPDATE gradilista SET qnap_folder = $1 WHERE id = $2 AND qnap_folder IS NULL', 
        [folderSafe, gradiliste_id]).catch(() => {});
    }
    let cleanB64 = slika_base64;
    const m = slika_base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
    if (m) cleanB64 = m[1];
    const buf = Buffer.from(cleanB64, 'base64');
    if (buf.length < 100) return res.status(400).json({ error: 'Slika premala' });
    if (buf.length > 8_000_000) return res.status(400).json({ error: 'Slika prevelika (>8 MB)' });
    
    // ⭐ v135.7.127 (BUG FIX REF-01): Validacija dimenzija slike (width × height)
    //   Razlog: prije je samo veličina (8MB) bila kontrolirana. User mogao uploadat
    //   50000×50000 piksel sliku koja je 7MB ali browser-i je ne mogu otvoriti.
    //   Sad: parse JPEG/PNG header → reject ako > 6000px na bilo kojoj strani.
    const dim = _getImageDimensions(buf);
    if (dim && (dim.width > 6000 || dim.height > 6000)) {
      return res.status(400).json({ 
        error: `Slika ima nerazumne dimenzije (${dim.width}×${dim.height}px). Maksimum 6000×6000 px.` 
      });
    }
    if (dim && (dim.width < 100 || dim.height < 100)) {
      return res.status(400).json({ 
        error: `Slika premalih dimenzija (${dim.width}×${dim.height}px). Minimum 100×100 px.` 
      });
    }
    
    // ⭐ v135.7.65 (Ivan): SANITY CHECK - upozorenje ako slika prevelika (logo + kompresija nije dobro radio)
    //    700 KB = target. >1000 KB = klijent nije pravilno komprimirao.
    if (buf.length > 1024 * 1024) {
      console.warn(`[reference upload] WARN: slika ${(buf.length/1024).toFixed(0)} KB > 1 MB - klijent nije pravilno komprimirao`);
    }
    
    const fname = `Reference/${folderSafe}/ref_${Date.now()}.${imgExtFromB64(slika_base64)}`; // ⭐ v...65: webp/jpg po stvarnom formatu
    
    // ⭐ v502.20.9 (Ivan, 27.05.2026): PARALELNI QNAP + B2 upload (PRIJE: samo QNAP)
    //   PROBLEM: Ivan-ov QNAP pao 27.05., reference upload fail-a jer čeka QNAP.
    //   Materijal/dnevnik/uredaji/nalozi su već imali B2 fallback (Promise.allSettled),
    //   ALI reference je bio zaboravljen — koristio je qnapUploadImage() direktno.
    //   FIX: paralelni upload kao u materijal flow-u. Ako QNAP fail-a, B2 spašava upload.
    const [qnapRes, b2Res] = await Promise.allSettled([
      qnapUploadImage(buf, fname),                                              // QNAP (postojeći)
      b2Enabled() ? b2Upload(buf, fname, extToContentType(fname)) : Promise.resolve(null)  // B2 fallback ⭐ v...65: format iz ekstenzije
    ]);
    const qnapPath = qnapRes.status === 'fulfilled' ? qnapRes.value : null;
    const b2Path   = b2Res.status === 'fulfilled' ? b2Res.value : null;
    
    if (!qnapPath && !b2Path) {
      console.error('[reference upload] QNAP+B2 OBA fail-ala za', fname);
      return res.status(500).json({ 
        error: 'Upload neuspješan — ni QNAP ni B2 ne odgovaraju. Pokušaj ponovo za par sekundi.' 
      });
    }
    console.log(`[reference upload] QNAP=${qnapPath?'OK':'FAIL'} B2=${b2Path?'OK':'FAIL'}`);
    
    // ⭐ v502.20.9: KRITIČAN — ako QNAP fail-a, qnap_path mora biti NULL (NE rezervirani path)
    //   inače reverse sync (B2 → QNAP) nikad ne uhvati ovu sliku jer čeka 
    //   `WHERE qnap_path IS NULL`. Kad QNAP dođe online, reverseMigrateBatch pokupi 
    //   sve b2_path s qnap_path=NULL i sinkronizira ih natrag na QNAP.
    const uploaded = qnapPath || null;
    
    // ⭐ v135.7.127 (BUG FIX REF-04): Validacija thumb_base64 (mora biti valid base64 ako je poslan)
    let cleanThumb = null;
    if (thumb_base64 && typeof thumb_base64 === 'string') {
      const tm = thumb_base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
      cleanThumb = tm ? thumb_base64 : 'data:image/jpeg;base64,' + thumb_base64;
      // Sanity check — thumb mora biti razumno mali (<50KB)
      const thumbBytes = Buffer.from(cleanThumb.split(',')[1] || '', 'base64').length;
      if (thumbBytes > 50_000) {
        console.warn(`[reference upload] thumb_base64 too large (${thumbBytes} B) → ignoring`);
        cleanThumb = null;
      }
    }
    
    // ⭐ v135.7.65 (Ivan): UPLOAD pretpostavljamo PROŠAO logo proces (frontend _refKompresirajSWatermark uvijek dodaje logo)
    //    Označavamo watermark_validated=true odmah — slika ne prolazi auto-fix re-check.
    // ⭐ v502.20.9: spremamo i b2_path uz qnap_path
    let ins;
    try {
      ins = await pool.query(`
        INSERT INTO fasada_reference (gradiliste_id, qnap_path, b2_path, veličina_kb, watermark, watermark_validated, validated_at, opis, zanimljivi_detalj, kreirao_id, thumb_base64)
        VALUES ($1, $2, $3, $4, true, true, NOW(), $5, $6, $7, $8) RETURNING id, qnap_path, b2_path, created_at
      `, [gradiliste_id, uploaded, b2Path, Math.round(buf.length / 1024), opis || null, !!zanimljivi_detalj, req.user?.id || null, cleanThumb]);
    } catch(e) {
      // Fallback: stara baza bez thumb_base64 ili b2_path kolone
      console.warn('[reference upload] INSERT fallback (stara shema):', e.message);
      ins = await pool.query(`
        INSERT INTO fasada_reference (gradiliste_id, qnap_path, veličina_kb, watermark, watermark_validated, validated_at, opis, zanimljivi_detalj, kreirao_id)
        VALUES ($1, $2, $3, true, true, NOW(), $4, $5, $6) RETURNING id, qnap_path, created_at
      `, [gradiliste_id, uploaded, Math.round(buf.length / 1024), opis || null, !!zanimljivi_detalj, req.user?.id || null]);
    }
    res.json({ ok: true, ...ins.rows[0] });
  } catch (e) {
    console.error('[reference upload]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v770 (Ivan): SKRIVANJE GRADILIŠTA IZ REFERENCI — čisto "izbaci iz portfelja", NIKAD ne dira
//   gradilište ni njegove slike/podatke. Lista skrivenih ID-eva živi u postojećoj key-value tablici
//   `postavke` (ključ 'ref_skrivena_gradilista') → BEZ init-db, i reverzibilno jednim klikom.
const _REF_SKRIVENA_KLJUC = 'ref_skrivena_gradilista';
async function _refSkrivenaUcitaj() {
  try {
    const r = await pool.query('SELECT vrijednost FROM postavke WHERE kljuc = $1', [_REF_SKRIVENA_KLJUC]);
    if (!r.rows.length) return [];
    const a = JSON.parse(r.rows[0].vrijednost);
    return Array.isArray(a) ? a.map(x => parseInt(x, 10)).filter(Number.isFinite) : [];
  } catch (_) { return []; }
}
async function _refSkrivenaSpremi(arr) {
  const cist = [...new Set((arr || []).map(x => parseInt(x, 10)).filter(Number.isFinite))];
  await pool.query(`INSERT INTO postavke(kljuc, vrijednost, updated_at) VALUES($1,$2,NOW())
                    ON CONFLICT (kljuc) DO UPDATE SET vrijednost = $2, updated_at = NOW()`,
    [_REF_SKRIVENA_KLJUC, JSON.stringify(cist)]);
  return cist;
}
app.get('/api/reference/skrivena', auth, staff, async (req, res) => {
  try { res.json({ ok: true, skrivena: await _refSkrivenaUcitaj() }); }
  catch (e) { console.error('[ref skrivena GET]', e); res.status(500).json({ error: 'Greška' }); }
});
app.post('/api/reference/skrivena', auth, staff, async (req, res) => {
  try {
    const gid = parseInt(req.body && req.body.gradiliste_id, 10);
    const skrij = !!(req.body && req.body.skrij);
    if (!Number.isFinite(gid)) return res.status(400).json({ error: 'Neispravan gradiliste_id' });
    // SIGURNOSNA POTVRDA: gradilište i njegove slike ostaju netaknuti — mijenja se SAMO ova lista.
    let lista = await _refSkrivenaUcitaj();
    lista = skrij ? lista.concat([gid]) : lista.filter(x => x !== gid);
    const nova = await _refSkrivenaSpremi(lista);
    res.json({ ok: true, skrivena: nova, napomena: 'Gradilište i slike su netaknuti — promijenjen je samo prikaz u referencama.' });
  } catch (e) { console.error('[ref skrivena POST]', e); res.status(500).json({ error: 'Greška' }); }
});

// GET /api/reference/lista — vrati sve reference (opt. po gradilištu)
app.get('/api/reference/lista', auth, staff, async (req, res) => {
  try {
    const gid = req.query.gradiliste_id ? parseInt(req.query.gradiliste_id) : null;
    const where = gid ? 'WHERE r.gradiliste_id = $1' : '';
    const params = gid ? [gid] : [];
    
    // ⭐ v135.7.58 (Ivan): Self-healing migracija ako startup nije prošao
    //    Stari serveri (prije v135.7.55) nemaju watermark_validated/validated_at kolone.
    //    Ako migracija fail-a (race condition, deploy timing), ovaj try-catch osigurava
    //    da endpoint radi bez crash-a — defenzivni dodatak.
    try {
      await pool.query(`
        ALTER TABLE fasada_reference ADD COLUMN IF NOT EXISTS watermark_validated BOOLEAN DEFAULT NULL;
        ALTER TABLE fasada_reference ADD COLUMN IF NOT EXISTS validated_at TIMESTAMP;
      `);
    } catch(_) {}  // best-effort, ako fail-a query niže će svejedno raditi (COALESCE)
    
    // ⭐ v135.7.127 (BUG FIX REF-04): vraćaj thumb_base64 (mobile data ušteda)
    //   has_thumb flag → frontend zna koristiti thumb umjesto pun fetch.
    let q;
    try {
      q = await pool.query(`
        SELECT r.id, r.gradiliste_id, r.qnap_path, r.veličina_kb, r.watermark, r.opis,
               COALESCE(r.zanimljivi_detalj, false) AS zanimljivi_detalj, r.created_at,
               r.watermark_validated, r.validated_at,
               r.sirina_px, r.visina_px,
               r.thumb_base64,
               (r.thumb_base64 IS NOT NULL) AS has_thumb,
               g.naziv AS grad_naziv,
               COALESCE(rad.ime || ' ' || rad.prezime, 'Sustav') AS kreirao
        FROM fasada_reference r
        LEFT JOIN gradilista g ON g.id = r.gradiliste_id
        LEFT JOIN radnici rad ON rad.id = r.kreirao_id
        ${where}
        ORDER BY COALESCE(r.zanimljivi_detalj, false) DESC, r.created_at DESC
      `, params);
    } catch(e) {
      // Fallback bez thumb_base64 kolone
      console.warn('[reference lista] thumb fallback:', e.message);
      q = await pool.query(`
        SELECT r.id, r.gradiliste_id, r.qnap_path, r.veličina_kb, r.watermark, r.opis,
               COALESCE(r.zanimljivi_detalj, false) AS zanimljivi_detalj, r.created_at,
               r.watermark_validated, r.validated_at,
               r.sirina_px, r.visina_px,
               g.naziv AS grad_naziv,
               COALESCE(rad.ime || ' ' || rad.prezime, 'Sustav') AS kreirao
        FROM fasada_reference r
        LEFT JOIN gradilista g ON g.id = r.gradiliste_id
        LEFT JOIN radnici rad ON rad.id = r.kreirao_id
        ${where}
        ORDER BY COALESCE(r.zanimljivi_detalj, false) DESC, r.created_at DESC
      `, params);
    }
    res.json({ ok: true, reference: q.rows });
  } catch (e) {
    console.error('[reference lista]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// GET /api/reference/:id/slika — stream slike s QNAP-a kao base64 (s B2 fallback)
app.get('/api/reference/:id/slika', auth, staff, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    // ⭐ v502.20.9 (Ivan, 27.05.2026): čitaj b2_path uz qnap_path za fallback
    // ⭐ v502.20.21 (Ivan, 27.05.2026): + thumb_base64 za zadnji fallback (DB cache)
    // ⭐ v502.20.24 (Ivan, 27.05.2026): defensive SELECT — fallback ako kolone ne postoje
    //   (do prvog restart-a s v502.20.24 migracijama kolone možda još ne postoje)
    let r;
    try {
      r = await pool.query(
        'SELECT qnap_path, b2_path, thumb_base64 FROM fasada_reference WHERE id = $1', 
        [id]
      );
    } catch(colErr) {
      console.warn(`[ref-slika ${id}] DB kolone nedostaju, fallback na qnap_path only:`, colErr.message);
      r = await pool.query(
        'SELECT qnap_path FROM fasada_reference WHERE id = $1', 
        [id]
      );
      // Defensive: stvori prazne null polja da kod dalje radi
      if (r.rows.length) {
        r.rows[0].b2_path = null;
        r.rows[0].thumb_base64 = null;
      }
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Referenca ne postoji' });
    
    const row = r.rows[0];
    
    // ⭐ v502.20.24 (Ivan, 27.05.2026): QNAP-FIRST + b2_path try/catch
    //   Ivan EKSPLICITNO traži: "trebao bi fetchat sa qnapa". QNAP je primarni izvor.
    //   B2 služi SAMO kao fallback ako QNAP fail-a. Plus: SELECT b2_path u try/catch 
    //   jer kolona možda još ne postoji u DB-u (migracije se sad stavljaju u startup).
    const t0 = Date.now();
    let buf = null;
    let source = null;
    
    // 1. QNAP RAW first (Ivan eksplicitno traži) — preskoči circuit breaker
    if (row.qnap_path) {
      try {
        const qBuf = await _qnapFastFetch(row.qnap_path, 5000);
        if (qBuf) {
          buf = qBuf;
          source = 'qnap';
          _qnapCircuitRecord(true);  // ako je circuit bio otvoren, zatvori
        } else {
          console.warn(`[ref-slika ${id}] QNAP raw fetch returned null (path=${row.qnap_path})`);
          _qnapCircuitRecord(false);
        }
      } catch(e) {
        console.warn(`[ref-slika ${id}] QNAP raw fetch error:`, e.message);
        _qnapCircuitRecord(false);
      }
    }
    
    // 2. B2 fallback ako QNAP fail-a (samo ako kolona postoji)
    if (!buf && row.b2_path) {
      try {
        const b2Buf = await b2FetchBuffer(row.b2_path, 5000);
        if (b2Buf) {
          buf = b2Buf;
          source = 'b2';
        } else {
          console.warn(`[ref-slika ${id}] B2 fetch returned null (path=${row.b2_path})`);
        }
      } catch(e) {
        console.warn(`[ref-slika ${id}] B2 fetch error:`, e.message);
      }
    }
    
    if (buf) {
      const b64 = buf.toString('base64');
      console.log(`[ref-slika ${id}] OK from=${source} size=${Math.round(buf.length/1024)}KB time=${Date.now()-t0}ms`);
      // ⭐ v135.7.502.20.64: prefiks slijedi stvarni format (jpg→image/jpeg, webp→image/webp).
      //   Faza 1: svi pathovi su .jpg → image/jpeg (bez promjene). Spremno za .webp.
      const mime = extToContentType(row.qnap_path || row.b2_path);
      return res.json({ ok: true, slika_base64: `data:${mime};base64,` + b64 });
    }
    
    // 3. ZADNJI FALLBACK - thumb_base64 (postoji u DB-u kao 200×200, ~10-15 KB)
    if (row.thumb_base64) {
      console.warn(`[ref-slika ${id}] vraćam thumb_base64 (QNAP+B2 oba fail; time=${Date.now()-t0}ms)`);
      return res.json({ ok: true, slika_base64: row.thumb_base64, from_thumb: true });
    }
    
    console.error(`[ref-slika ${id}] SVE FAIL: qnap_path=${row.qnap_path}, b2_path=${row.b2_path}, no thumb; time=${Date.now()-t0}ms`);
    return res.status(404).json({ 
      error: 'Slika nije dostupna (QNAP, B2 i thumb cache svi ne odgovaraju)' 
    });
  } catch (e) {
    console.error('[reference slika]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ⭐ v135.7.55 (Ivan): PUT /api/reference/:id/slika
//    Overwrite QNAP slike s novom (već watermark-iranom + komprimiranom) verzijom.
//    Klijent (Reference tab) auto-detektira slike bez logoa, primijeni
//    _refKompresirajSWatermark, pošalje natrag ovdje. Ovaj endpoint:
//    1) Spremi novu sliku na QNAP (overwrite postojeće na istom path-u)
//    2) Update DB: veličina_kb, watermark=true, watermark_validated=true, validated_at=NOW()
app.put('/api/reference/:id/slika', auth, staff, async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    const { slika_base64 } = req.body || {};
    if (!slika_base64 || typeof slika_base64 !== 'string') {
      return res.status(400).json({ error: 'Slika nedostaje' });
    }
    
    // ⭐ v502.20.25 (Ivan, 27.05.2026): + b2_path za paralelni overwrite
    let r;
    try {
      r = await pool.query('SELECT qnap_path, b2_path FROM fasada_reference WHERE id = $1', [id]);
    } catch(colErr) {
      console.warn('[reference update slika] b2_path fallback:', colErr.message);
      r = await pool.query('SELECT qnap_path FROM fasada_reference WHERE id = $1', [id]);
      if (r.rows.length) r.rows[0].b2_path = null;
    }
    if (!r.rows.length) return res.status(404).json({ error: 'Referenca ne postoji' });
    const qnapPath = r.rows[0].qnap_path;
    const oldB2Path = r.rows[0].b2_path;
    if (!qnapPath) return res.status(400).json({ error: 'Slika nema QNAP path' });
    
    let cleanB64 = slika_base64;
    const m = slika_base64.match(/^data:image\/[a-z]+;base64,(.+)$/);
    if (m) cleanB64 = m[1];
    const buf = Buffer.from(cleanB64, 'base64');
    if (buf.length < 100) return res.status(400).json({ error: 'Slika premala' });
    if (buf.length > 8_000_000) return res.status(400).json({ error: 'Slika prevelika (>8 MB)' });
    
    // ⭐ v502.20.25 (Ivan, 27.05.2026): paralelni overwrite QNAP + B2 (consistency)
    //   PRIJE: samo QNAP overwrite, B2 zadržava staru verziju → kada QNAP fail-a, 
    //   frontend dobije staru sliku bez logoa.
    //   FIX: paralelni upload na istom putu (QNAP) i na novom B2 putu (jer 
    //   _refSanitizeGradName može vraćati različite path-ove kroz vrijeme).
    const newFname = qnapPath;  // istog imena za QNAP
    const newB2Fname = qnapPath;  // koristi isti path key za B2
    
    const [qnapRes, b2Res] = await Promise.allSettled([
      qnapUploadImage(buf, newFname),
      b2Enabled() ? b2Upload(buf, newB2Fname, 'image/jpeg') : Promise.resolve(null)
    ]);
    const uploaded = qnapRes.status === 'fulfilled' ? qnapRes.value : null;
    const newB2Path = b2Res.status === 'fulfilled' ? b2Res.value : null;
    
    if (!uploaded) return res.status(500).json({ error: 'QNAP overwrite neuspješan' });
    
    // Update DB — b2_path se može pomijenjati ako je stari path drugačiji
    try {
      await pool.query(`
        UPDATE fasada_reference 
        SET veličina_kb = $1, b2_path = $2, watermark = true, watermark_validated = true, validated_at = NOW()
        WHERE id = $3
      `, [Math.round(buf.length / 1024), newB2Path || oldB2Path, id]);
    } catch(e) {
      // Fallback ako b2_path kolona ne postoji (predmigracija)
      console.warn('[reference update slika] UPDATE b2_path fallback:', e.message);
      await pool.query(`
        UPDATE fasada_reference 
        SET veličina_kb = $1, watermark = true, watermark_validated = true, validated_at = NOW()
        WHERE id = $2
      `, [Math.round(buf.length / 1024), id]);
    }
    
    res.json({ ok: true, id, veličina_kb: Math.round(buf.length / 1024), b2_updated: !!newB2Path });
  } catch (e) {
    console.error('[reference update slika]', e.message);
    res.status(500).json({ error: e.message });
  }
});

