      if (!dodano && Array.isArray(r.ploha_pointsPx) && r.ploha_pointsPx.length >= 3) polys.push({ pts: r.ploha_pointsPx, rgb: [22, 163, 74], fillA: 66, edgeA: 220 });   // legacy single-ploha
