      if (!v.foto_b64) {  // ⭐ v275 (Ivan #2): jedan retry + glasna dijagnoza (tiho null = nevidljiv uzrok)
        try { v.foto_b64 = await _qnapFetchSlikaAsDataUrl(v.foto_qnap); } catch (_) {}
        if (!v.foto_b64) console.warn('[vtr foto v275] NEDOSTUPNA nakon retrya:', v.foto_qnap);
      }
