  const _kuPrijevod = _kuPrijevodKljuceva(f);
  const mapKeys = (st) => {
    if (!st || !st.mapiranje || st.mapiranje === '_rucni') return [];
    const sirovi = Array.isArray(st.mapiranje) ? st.mapiranje.filter(Boolean) : [st.mapiranje];
    // prijevod + uklanjanje duplikata (stari i novi kljuc iste geometrije mogu biti oba u popisu)
    const vid = {}, out = [];
    sirovi.forEach(k => { const t = _kuPrijevod[k] || k; if (!vid[t]) { vid[t] = 1; out.push(t); } });
    return out;
  };
  // ⭐ v237: skup svih eksplicitno mapiranih 'R|' ključeva — razvijena dodijeljena jednoj stavci
