  const globalRSet = new Set();
  ukljucene.forEach(st => mapKeys(st).forEach(k => { if (k && k.indexOf('R|') === 0) globalRSet.add(k); }));
  const _normP = (k) => (_kuLegKey(k) ? ('P|' + k) : k);

  const prev = opts.prevSnapshot || null;
  const prevEl = {}; ((prev && prev.elementi) || []).forEach(e => { prevEl[e.fp] = e; });
  // ⭐ v237/v239: normalizacija STARIH snapshot ključeva na nove prefiksirane — i za PREV i za
  //   OVERRIDE elemente (Preuzmi stare situacije inače radi lažni storno+novo na svakom elementu)
  const _kuNormElKljuc = (pe) => {
    const k = pe.kljuc;
    if (!k || k === '_otvor' || /^(P\||D\||PB\||R\||S\|)/.test(k)) {
      if (k === '_bazni' && pe.tip === 'R') { pe.kljuc = 'R|' + (pe.opis || 'razvijena širina'); pe.vrsta = null; }
      return;
    }
    if (pe.tip === 'P') pe.kljuc = 'P|' + k;
    else if (pe.tip === 'D') pe.kljuc = 'D|' + k;
    else if (pe.tip === 'PB') pe.kljuc = 'PB|' + k;
    else if (pe.tip === 'R') { pe.vrsta = k; pe.kljuc = 'R|' + (pe.opis || 'razvijena širina'); }
  };
  Object.values(prevEl).forEach(_kuNormElKljuc);
  const prevStavke = (prev && prev.stavke) || {};
  const sitN = opts.situacija_n || 1;
  // ⭐ v1208 (Ivan: „treba biti gumb za okoncana situacija (to je zadnja) jer ovako mozemo ici do
  //   n... privremenih i necemo nikada moci zakljuciti gradiliste i izdavanje racuna sa okoncano"):
  //   OKONCANA SITUACIJA JE PRAVNI POJAM, NE NAZIV.
  //   Privremena situacija je medjuobracun — placa se, ali ne zatvara posao. OKONCANA je zadnja:
  //   njome se gradiliste zatvara, oslobadja retencija i izdaje zavrsni racun. Dok toga nema,
  //   knjiga moze rasti u beskonacnost i Nadzor nema sto potpisati kao KONACNO.
  //   Zato `okoncana` nije samo drukciji tekst nego stanje koje se sprema uz situaciju.
  const jeOkoncana = !!(opts && opts.okoncana);
  const sitLabel = opts.situacija_label || (sitN + (jeOkoncana ? '. okončana situacija' : '. privremena situacija'));

  // ⭐ v612 (Ivan, ispravak v610 #2): oznaka situacije na crtezu/prilogu za SPREMLJENE + ZAKLJUCANE situacije (NE
  //   samo ovjerene — Ivan: spremljena I situacija mora oznaciti crteze i bez ovjere, "to smo prije definirali").
  //   Tekuca RADNA (nacrt, jos nespremljena) se NE broji jer nije u bazi kao spremljena -> upit prirodno iskljucuje.
  const _zakljPrvaSit = {};
  try {
    if (f && f.id != null) {
      const _zq = await pool.query("SELECT verzija_n, snapshot->'mapiranje' AS mapiranje, snapshot->'elementi' AS elementi FROM fasade_knjiga_verzije WHERE procjena_id = $1 AND status IN ('spremljena','zakljucana') ORDER BY verzija_n ASC", [f.id]);
      _zq.rows.forEach(row => {
        const map = row.mapiranje;
        if (map && typeof map === 'object' && !Array.isArray(map) && Object.keys(map).length) {
          Object.keys(map).forEach(sk => { const arr = map[sk]; if (Array.isArray(arr)) arr.forEach(k => { if (k && _zakljPrvaSit[k] == null) _zakljPrvaSit[k] = row.verzija_n; }); });
        } else {
          (Array.isArray(row.elementi) ? row.elementi : []).forEach(el => { if (el && el.kljuc && _zakljPrvaSit[el.kljuc] == null) _zakljPrvaSit[el.kljuc] = row.verzija_n; });
        }
      });
    }
  } catch (eZ) { console.warn('[v610 zakljPrvaSit]', eZ && eZ.message); }

  // ⭐ v235: elementiOverride → povijesno vjerna reprodukcija situacije iz snapshota (Preuzmi)
  const E = Array.isArray(opts.elementiOverride) ? opts.elementiOverride : _kuElementiProcjene(f);
  if (Array.isArray(opts.elementiOverride)) E.forEach(_kuNormElKljuc);  // ⭐ v239
  // * v1169 (nelogicnost 1): GEOMETRIJA SE PROMIJENILA NAKON SPREMANJA - nigdje nije pisalo.
