      if (!e2) { _geomPromjene.push({ opis: String(pe.opis || fp).slice(0, 40), sto: 'uklonjeno iz nacrta' }); return; }
      const raz = [];
      // * v1187 (Ivan: „stisnuo sam spremi situaciju i izbacio mi je napomenu da se geometrija
      //   promijenila — nije se nista promijenilo, nisam nakon spremanja nista mijenjao").
