      if (Math.abs(_m2r(pe.m2) - _m2r(e2.m2)) > 0.004) raz.push('m2 ' + _kuBrojHr(_m2r(pe.m2)) + ' -> ' + _kuBrojHr(_m2r(e2.m2)));
      const _g = (g, k) => (g && isFinite(parseFloat(g[k]))) ? Math.round(parseFloat(g[k]) * 100) / 100 : 0;
      ['odbij', 'povrat', 'spalete'].forEach(k => {
        if (Math.abs(_g(pe.gn, k) - _g(e2.gn, k)) > 0.004) raz.push(k + ' ' + _kuBrojHr(_g(pe.gn, k)) + ' -> ' + _kuBrojHr(_g(e2.gn, k)));
      });
      if ((pe._plohaKljuc || '') !== (e2._plohaKljuc || '')) raz.push('promijenjen vlasnik odbitka');
      // * v1187 POJAS ZA UBUDUCE: nijedna prijava ne smije glasiti „X -> X". Ako se prije i
      //   poslije ispisuju jednako, korisnik ne moze provjeriti ni ispraviti nista — a poruka
