  let _prevBilledKeys = null;
  if (prev && prev.mapiranje && typeof prev.mapiranje === 'object') {
    _prevBilledKeys = new Set();
    Object.values(prev.mapiranje).forEach(arr => { (Array.isArray(arr) ? arr : []).forEach(k2 => { if (k2 && k2 !== '_rucni') _prevBilledKeys.add(k2); }); });
  }

  // ⭐ v238: AUTO-BAZNI — ako bazni nije spremljen u Koraku 2, izvedi ga iz najvećeg plohe-sustava
  //   (bez ovoga: otvori i tuđi odbitci se NE pojavljuju → 'gola' P lista kao na Samoboru).
  let bazniAuto = null;
  if (!bazniKljuc) {
    const pSum = {};
    E.forEach(e => { if (e.tip === 'P' && e.kljuc) pSum[e.kljuc] = (pSum[e.kljuc] || 0) + (e.m2 || 0); });
    let top = Object.keys(pSum).sort((a, b) => pSum[b] - pSum[a])[0];
    // ⭐ v336 (Ivan): NEMA plohe P → ZT je glavna mjera; od ZT računskog raspisa oduzimaju se otvori
    //   (GN 421 / špalete mod) jednako kao da je P bazni — jeBazniList + _kuPripadaListi su tip-agnostični.
    if (!top) {
      const ztSum = {};
      E.forEach(e => { if (e.tip === 'ZT' && e.kljuc) ztSum[e.kljuc] = (ztSum[e.kljuc] || 0) + (e.m2 || 0); });
      top = Object.keys(ztSum).sort((a, b) => ztSum[b] - ztSum[a])[0];
    }
    if (top) { bazniKljuc = top; bazniAuto = top; console.warn('[knjiga] bazni nije postavljen → AUTO:', top); }
  }

  const wb = new ExcelJS.Workbook(); wb.creator = 'ŽBUKA Gradilište';
  // ⭐ v334 (Ivan): PREMIUM paleta "Ink & Bronze" — duboki ink, antikni bronz akcent, topli ivory.
