    const jeRucni = (st.mapiranje === '_rucni');
    const jeBazniList = !!(bazniKljuc && keys.map(_normP).indexOf(_normP(bazniKljuc)) !== -1);
    // ⭐ v235 (P1.1): donos se nastavlja na OVJERENU vrijednost nadzora ako postoji
    // ⭐ v476 (Ivan #2): pozicijski rezervni ključ — kad stavka dobije redni broj (Auto-broj), ključ se
    //   mijenja (npr. „idx0" → „1") pa donos PRETHODNE (već službene) situacije, snimljen pod „idx0",
    //   inače pukne (krivi kumulativ). 'idx'+sIdx je isti POLOŽAJ → donos se nastavlja bez prekida.
    //   (vrijedi dok se redoslijed/uključenost stavki ne mijenja — što je normalan slučaj kroz situacije)
    const ps = prevStavke[stKey] || prevStavke['idx' + sIdx] || null;
    const prevUkRaw = ps ? (parseFloat(ps.ukupno) || 0) : 0;
    const prevOvj = (ps && ps.ukupno_ovjereno != null && isFinite(parseFloat(ps.ukupno_ovjereno))) ? parseFloat(ps.ukupno_ovjereno) : null;
    const prevUk = (prevOvj != null) ? prevOvj : prevUkRaw;
    const prevOvjeren = (prevOvj != null) && Math.abs(prevOvj - prevUkRaw) > 0.004;
    // prinos elementa na OVOJ listi (koriste novi + izmjene + storno)
    const prinosNaListi = (e) => {
      if (!_kuPripadaListi(e, keys, jeBazniList, globalRSet)) return 0;
      if (e.tip === 'O') { const g = e.gn; if (!g || g.prag === '<=3') return 0; return -g.odbij + g.povrat + (g.spalete || 0); }
      if (e.tip === 'P' || e.tip === 'R' || e.tip === 'S' || e.tip === 'ZT') return e.m2;  // ⭐ v255: + ZT
      if (e.tip === 'D' || e.tip === 'PB') {
        // ⭐ v569 (Ivan): PER-GEOMETRIJA. Pozitivno = eksplicitno mapiran vlastiti ključ. ODBITAK (tuđi materijal
        //   unutar plohe) = na stavci PLOHE u kojoj zona leži (e._plohaKljuc), da se površina ne broji dvaput.
        if (keys.indexOf(e.kljuc) !== -1) return e.m2;  // vlastita stavka
        if (!e.izvan && e._plohaKljuc && keys.indexOf(e._plohaKljuc) !== -1) return -((e.m2u != null) ? e.m2u : e.m2);  // odbitak na stavci svoje plohe (samo dio u plohi)
      }
      return 0;
    };

    // ⭐ v616 (Ivan, screenshot): geo-VTR "Ukupna kol. prema troš." je pokazivao 0,00 (v.kolicina se za VTR vezan
    //   na geometriju ne upisuje — geometrija je izvor, v611). Header sada pokazuje PUNU mjeru geometrije (isti
    //   broj kao Korak 3/4). Samo prikaz u zaglavlju lista; NE dira mjes/kumulativ/donos.
    if (st._vtr && !jeRucni && !(parseFloat(st.kolicina) > 0.004)) {
      st.kolicina = Math.round(E.filter(e => _kuPripadaListi(e, keys, jeBazniList, globalRSet)).reduce((a, e) => a + prinosNaListi(e), 0) * 100) / 100;
    }

    let mjes = 0;
    const linije = []; // {grupaProcelje, redovi:[{...redRaspis opts}]}
    const dodajElemRedove = (e, storno) => {
      const sgn = storno ? -1 : 1;
      const pref = storno ? 'STORNO · ' : '';
      // ⭐ v255: ZT s promjenjivim visinama — glavni red + dionice (nadzor vidi svaki trapez)
      if (e.tip === 'ZT' && Array.isArray(e.zt_segmenti) && e.zt_segmenti.length >= 1) {  // ⭐ v291 (Ivan #3): i jedna dionica se raspisuje
        const redovi = [{ ozn: 'ZT' + (e.br || '') + (storno ? '·st' : '') + (e.kom > 1 ? ' ×' + e.kom : ''),
          izraz: pref + e.opis, v: e.izraz, m2: (sgn >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(e.m2)) }];
        e.zt_segmenti.forEach((sg, si) => {
          const _istaH = Math.abs((sg.h1 || 0) - (sg.h2 || 0)) <= 0.005;  // ⭐ v291: jednake visine → čisti 'L × h'
          const _frm = _istaH ? (_kuBrojHr(sg.L) + ' × ' + _kuBrojHr(sg.h1)) : (_kuBrojHr(sg.L) + ' × (' + _kuBrojHr(sg.h1) + '+' + _kuBrojHr(sg.h2) + ')/2');
          redovi.push({ izraz: '— dionica ' + (si + 1) + ': ' + _frm + ' = ' + _kuBrojHr(sg.a), note: true, m2: null });
        });
        linije.push({ p: e.procelje, redovi });
        mjes += sgn * e.m2;  // ⭐ v255: multi-red put MORA pribrojiti (kao O-blok)
        return;
      }
      if (e.tip === 'O') {  // ⭐ v569: pozivatelj već filtrira _kuPripadaListi (otvor slijedi svoju plohu) — note se crta na stavci te plohe, ne na baznom
        const g = e.gn || {}; if (!g.prag) return;
        // ⭐ v135.7.502.20.312 (Ivan): ŠPALETE MOD — otvor cijeli odbijen (š×v), bez GN 421.
        //   Špalete m' su informativna nota ovdje; stavka s cijenom je na zasebnom listu "Špalete".
        if (g.spaleteMod) {
          const rspl = [];
          rspl.push({ ozn: 'O' + (e.br || '') + (storno ? '·st' : '') + (e.kom > 1 ? ' ×' + e.kom : ''), oznBoja: REDC, izraz: pref + e.opis + ' — otvor CIJELI odbijen (špalete mod)', v: e.izraz, m2: (sgn * -g.odbij >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(g.odbij)) });
          if (g.spaleteMduzni > 0) rspl.push({ ozn: 'šp. O' + (e.br || ''), oznBoja: GRN, izraz: 'špalete (2v+š) = ' + _kuBrojHr(g.spaleteMduzni) + ' m¹ → vlastiti troškovnički list (mapiranje stavki)', v: '', m2: null, note: true });
          linije.push({ p: e.procelje, redovi: rspl });
          mjes += sgn * (-g.odbij);   // špalete m' NE ulaze u m² neto (zaseban list)
          return;
        }
        if (g.prag === '<=3') {
          linije.push({ p: e.procelje, redovi: [{ ozn: 'O' + (e.br || ''), oznBoja: REDC, izraz: pref + e.opis + ' — ≤ 3 m²: NE odbija se (GN 421)', v: e.izraz, m2: null, note: true }] });
          return;
        }
        const redovi = [];
        redovi.push({ ozn: 'O' + (e.br || '') + (storno ? '·st' : '') + (e.kom > 1 ? ' ×' + e.kom : ''), oznBoja: REDC, izraz: pref + e.opis, v: e.izraz, m2: (sgn * -g.odbij >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(g.odbij)) });
        redovi.push({ izraz: 'GN 421 — otvor ' + (g.prag === '>5' ? '> 5 m²' : '3–5 m²') + ': +3,00 m²/otvoru' + (g.prag === '>5' ? ' + špalete' : ' (bez špaleta)'), note: true, m2: (sgn * g.povrat >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(g.povrat)) });
        if (g.spalete > 0) redovi.push({ ozn: 'šp. O' + (e.br || '') + (e.kom > 1 ? ' ×' + e.kom : ''), oznBoja: GRN, izraz: 'špalete (2v+š) × d', v: '', m2: (sgn * g.spalete >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(g.spalete)) });
        linije.push({ p: e.procelje, redovi });
        mjes += sgn * (-g.odbij + g.povrat + (g.spalete || 0));
        return;
      }
      // ⭐ v234 (audit): D/PB čiji je VLASTITI ključ eksplicitno mapiran u OVU stavku (npr. „završna
      //   žbuka" = [EPS|18, XPS|8, MW|18]) se PRIZNAJE (+m2) — odbitak (−) je samo kad bazni list
      //   isključuje tuđi sustav. Time i bazni IZVAN dijelovi (atika svoje vrste) dolaze s +.
      // ⭐ v237: jedinstveni izvor istine — prinosNaListi (pokriva nove i legacy ključeve)
      const prinos = prinosNaListi(e);
      const odbitakNaBaznom = (e.tip === 'D' || e.tip === 'PB') && prinos < 0;
      if (!prinos) return;
      const val = sgn * prinos;
      // ⭐ v564 (Ivan): RŠ raspis u POSEBAN pod-red (note) — pun racun ("30+50+30 = 110 cm -> normativ (...) =
      //   1,75 m2/m' x ... = 36,34 m2") ne stane u uski stupac Izracun pa je bio ODREZAN ("... ->"). Sad: glavni
      //   red = oznaka + naziv (kao ZT/ostali), a puni racun ide u wrap-ani note pod-red ispod (kao ZT dionice).
      if (e.tip === 'R') {
        const _oznR = 'R' + (e.br || '') + (storno ? '·st' : '') + (e.kom > 1 ? ' ×' + e.kom : '');
        const _redoviR = [{ ozn: _oznR, oznBoja: LJUB, izraz: pref + e.opis, v: '', m2: (val >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(val)) }];
        if (e.izraz) _redoviR.push({ izraz: e.izraz, note: true, m2: null });
        linije.push({ p: e.procelje, redovi: _redoviR });
        mjes += val;
        return;
      }
      const ozn = e.tip + (e.br || '') + (storno ? '·st' : '') + (e.kom > 1 ? ' ×' + e.kom : '');
      const boja = e.tip === 'P' ? GRN : (e.tip === 'R' || e.tip === 'ZT' ? LJUB : (e.tip === 'S' ? NAVY2 : AMB));  // ⭐ v255
      // ⭐ v562 (Ivan): "oznaka - opis" u stupcu B (npr. "ZT5 - krovna kucica zapad") — Ivan zeli oznaku UZ
      //   opis u istom retku, ne samo cistu oznaku (v504 ih je razdvojio; sad spojeno na zahtjev). Stupac A
      //   ostaje kratka oznaka u boji. pref (STORNO) ostaje na pocetku. Vrijedi za SVE tipove (P/O/D/PB/R/ZT/S).
      const opis = pref + e.opis + (odbitakNaBaznom
        ? (((e.m2u != null) && Math.abs(e.m2u - e.m2) > 0.004) ? ' (u plohi ' + _kuBrojHr(e.m2u) + ' od ' + _kuBrojHr(e.m2) + ') — odbitak (zaseban list)' : ' — odbitak (zaseban list)')
        : '');  // ⭐ v247
      linije.push({ p: e.procelje, redovi: [{ ozn, oznBoja: boja, izraz: opis, v: e.izraz, m2: (val >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(val)) + (e.tip === 'S' && e.jedinica && e.jedinica !== 'm²' ? ' ' + e.jedinica : '') }] });
      mjes += val;
    };

    if (!jeRucni) {
      novi.filter(e => _kuPripadaListi(e, keys, jeBazniList, globalRSet)).forEach(e => dodajElemRedove(e, false));
      // ⭐ v616 (Ivan): PRVI PUT NAPLAĆENO — element koji postoji otprije (nije fp-"nov"; nacrtan prije spremanja
      //   prošle situacije) ali ga u njoj NIJE naplatila nijedna stavka, a OVA ga stavka sada naplaćuje (tipično:
      //   nova VTR iz Koraka 3 vezana na postojeću geometriju). Dodaje se PUNOM mjerom: kumulativ = donos(0) +
      //   puna mjera = točno ono što Korak 4 pokazuje. Element IZMIJENJEN u međuvremenu (isti _id, nova mjera)
      //   koji prije NIJE bio naplaćen ide također punom SADAŠNJOM mjerom → preskače se u ±Δ bloku niže
      //   (_v616IzmSkip) da se ne broji dvaput. Bez prev.mapiranje (_prevBilledKeys=null) sve ostaje kao prije.
      const _v616IzmSkip = new Set();
      if (_prevBilledKeys) {
        const _v616NoviFp = new Set(novi.map(e2 => e2 && e2.fp).filter(Boolean));
        const _v616IzmFp = new Set(izmjene.map(x => x && x.sada && x.sada.fp).filter(Boolean));
        E.forEach(e => {
          if (!e || _v616NoviFp.has(e.fp)) return;                              // fp-nov je već raspisan gore
          if (!_kuPripadaListi(e, keys, jeBazniList, globalRSet)) return;       // ne pripada ovoj stavci
          const _viaOwn = keys.indexOf(e.kljuc) !== -1;                          // match vlastitim ključem ILI preko plohe (O / D-PB odbitak)
          const _naplPrije = _viaOwn ? _prevBilledKeys.has(e.kljuc) : !!(e._plohaKljuc && _prevBilledKeys.has(e._plohaKljuc));
          if (_naplPrije) return;                                                // već naplaćeno ranije → u donosu je
          if (_v616IzmFp.has(e.fp)) _v616IzmSkip.add(e.fp);
          dodajElemRedove(e, false);
        });
      }
      // ⭐ v235 (P3.7): IZMIJENJENI elementi (isti _id) → jedan ±Δ redak umjesto storno+novo
      const izmListe = izmjene.map(par => ({ par, d: prinosNaListi(par.sada) - prinosNaListi(par.prije) }))
                              .filter(x => Math.abs(x.d) > 0.004 && !_v616IzmSkip.has(x.sada && x.sada.fp));
      if (izmListe.length) {
        linije.push({ p: '± IZMJENE PRETHODNIH IZMJERA', redovi: [] });
        izmListe.forEach(x => {
          const e = x.par.sada;
          linije.push({ p: '± IZMJENE PRETHODNIH IZMJERA', redovi: [{ ozn: '± ' + e.tip + (e.br || ''), oznBoja: AMB,
            izraz: 'IZMJENA: ' + e.opis + '  (prije ' + _kuBrojHr(prinosNaListi(x.par.prije)) + ' → sada ' + _kuBrojHr(prinosNaListi(e)) + ')',
            v: e.izraz, m2: (x.d >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(x.d)) }] });
          mjes += x.d;
        });
      }
      const korekcije = uklonjeni.filter(e => _kuPripadaListi(e, keys, jeBazniList, globalRSet));
      // ⭐ v615 (Ivan): guard protiv LAZNOG STORNA. Ako je geometrija stavke/VTR-a POTPUNO uklonjena u ovoj
      //   situaciji (_geomSada ~ 0) a stavka je BILA obracunata ranije (prevUk > 0), diferencijal bi uklonjene
      //   plohe stavio u KOREKCIJE (STORNO) -> mjes = -donos -> stavka pada u MINUS iako je rijesena u prethodnoj
      //   situaciji ("nema novog rada" krivo protumaceno kao ponistenje obracuna). Zadrzi donos (bez storna,
      //   mjes ostaje 0, kumulativ = donos). Isti princip kao v596 (%) i v608 (rucna grana) koji su pokrivali te
      //   putove ali NE geometrijski diferencijal STORNO. Legitimno DJELOMICNO smanjenje i dalje radi: kad
      //   _geomSada > 0 geometrija POSTOJI -> STORNO dozvoljen (naplaceni kumulativ < donos je stvaran storno).
      const _geomSada = Math.round(E.filter(e => _kuPripadaListi(e, keys, jeBazniList, globalRSet)).reduce((a, e) => a + prinosNaListi(e), 0) * 100) / 100;
      if (korekcije.length && !(_geomSada < 0.005 && prevUk > 0.005)) {
        linije.push({ p: '⚠ KOREKCIJE PRETHODNIH IZMJERA', redovi: [] });
        korekcije.forEach(e => dodajElemRedove(e, true));
      }
    } else {
      // ⭐ v135.7.502.20.246: RASPIS RUČNIH UNOSA / VTR-a — red po unosu (opis · š×v · ±), kumulativni
      //   diff po _id (novi '+', izmjena '±', uklonjen 'STORNO'); Σ unosa = izvršena količina stavke.
      const unosiRaw = Array.isArray(st.rucni_unosi) ? st.rucni_unosi : [];
      const unosi = unosiRaw.map((u, ui) => {
        // * v1180: i ovaj oblik (`u && u.sirina`) mora racunati raspis - promakao mi je u v1179
        const su = _kuIzrazS(u && u.sirina) || 0, vu = _kuIzrazS(u && u.visina) || 0;
        const kq = (su > 0 && vu > 0) ? su * vu : (parseFloat(u && u.kolicina) || 0);
        return { _id: ((u && u._id) || ('ru' + ui)).toString(),
                 opis: ((u && u.opis) || '').toString().slice(0, 70),
                 // ⭐ v1181 (Ivan): u stupcu „Izračun" mora pisati RASPIS, ne samo rezultat - Nadzor
                 //   vidi odakle broj dolazi. Ako je upisan običan broj, ispis ostaje kakav je bio.
                 // ⭐ v1182 (Ivan): SAMO RASPIS, bez „= 10,20". Rezultat već stoji u stupcu
                 //   „Ukupna kol.", pa je ponavljanje iza svakog raspisa suvišno i guši ćeliju.
                 //   Nadzoru treba raspis; broj koji iz njega izlazi vidi desno.
                 izr: (su > 0 && vu > 0)
                   ? ((_kuJeRaspisS(u && u.sirina) ? '(' + String(u.sirina).trim() + ')' : _kuBrojHr(su))
                      + ' × ' + (_kuJeRaspisS(u && u.visina) ? '(' + String(u.visina).trim() + ')' : _kuBrojHr(vu)))
                   : '',
                 m2: Math.round(kq * 100) / 100 };
      }).filter(u => u.m2 > 0.0049);
      if (unosi.length) {
        const prevUn = (ps && Array.isArray(ps.unosi)) ? ps.unosi : [];
        const prevMap = {}; prevUn.forEach(u => { if (u && u._id) prevMap[u._id] = u; });
        const curIds = {}; unosi.forEach(u => { curIds[u._id] = 1; });
        const redovi = []; let zbroj = 0;
        unosi.forEach((u, ui) => {
          const pu = prevMap[u._id];
          if (!pu) { redovi.push({ ozn: 'RU' + (ui + 1), izraz: u.opis || (st._vtr ? 'VTR unos' : 'ručni unos'), v: u.izr, m2: '+' + _kuBrojHr(u.m2) }); zbroj += u.m2; }
          else {
            const pm = Math.round((parseFloat(pu.m2) || 0) * 100) / 100;
            if (Math.abs(pm - u.m2) > 0.0049) {
              const d = u.m2 - pm;
              redovi.push({ ozn: '± RU' + (ui + 1), izraz: (u.opis || 'unos') + ' — IZMJENA (prije ' + _kuBrojHr(pm) + ' → sada ' + _kuBrojHr(u.m2) + ')', v: u.izr, m2: (d >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(d)) });
              zbroj += d;
            }
          }
        });
        prevUn.forEach(pu => {
          if (!pu || !pu._id || curIds[pu._id]) return;
          const pm = Math.round((parseFloat(pu.m2) || 0) * 100) / 100; if (pm <= 0.0049) return;
          redovi.push({ ozn: 'RU·st', izraz: 'STORNO — uklonjen unos: ' + ((pu.opis || '').toString().slice(0, 60)), v: '', m2: '−' + _kuBrojHr(pm) });
          zbroj -= pm;
        });
        const kolSada = Math.round(unosi.reduce((a, u) => a + u.m2, 0) * 100) / 100;
        mjes = kolSada - prevUk;
        const korr = mjes - zbroj;
        if (Math.abs(korr) > 0.0049) redovi.push({ izraz: '± korekcija donosa (ovjera nadzora / raniji agregatni upis)', note: true, m2: (korr >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(korr)) });
        if (redovi.length) linije.push({ p: '', redovi });
        st._unosiSnap = unosi.map(u => ({ _id: u._id, opis: u.opis, m2: u.m2 }));
      } else {
        const kol = parseFloat(st.kolicina) || 0;
        // ⭐ v608 (Ivan): guard kao v596. VTR/rucna stavka BEZ kolicine u OVOJ situaciji (kol ~ 0) ali obracunata
        //   ranije (prevUk > 0): kol - prevUk = -donos -> stavka pada u MINUS iako je rijesena u prethodnoj
        //   situaciji. To NIJE storno nego "nema novog rada u ovoj situaciji" -> zadrzi donos (mjes = 0, kumulativ
        //   = donos). Namjerno smanjenje (storno) se radi preko rucni_unosi (STORNO red s negativnim diffom), ne
        //   postavljanjem kolicine na 0. Bez ovog guarda VTR obracunat u I. je u II. pokazivao -kolicina (Ivanov slucaj).
        if (kol < 0.005 && prevUk > 0.005) {
          mjes = 0;
        } else {
          mjes = kol - prevUk;
          if (Math.abs(mjes) > 0.005) linije.push({ p: '', redovi: [{ izraz: st._vtr ? 'Izvanugovorni rad (VTR) — količina po upisu (Korak 4)' : 'Ručni unos — ugovorna količina (bez geometrije Fasade)', note: true, m2: (mjes >= 0 ? '+' : '−') + _kuBrojHr(Math.abs(mjes)) }] });
        }
      }
    }

    // ⭐ v603 (Ivan #3): zapamti RASPISANE RETKE ove stavke (kompletan raspis PRIJE renderiranja) za vjernu
    //   reprodukciju u povijesti buducih situacija. Deep-copy (bez internih _num koji se dodaju tek pri renderu).
    _snapRaspis[stKey] = JSON.parse(JSON.stringify(linije));
    const ukupno = prevUk + mjes;
    const _cij = parseFloat(st.jed_cijena) || 0;  // ⭐ v240 (FAZA 5): € po stavci
    // ⭐ v333 (Ivan): snapshot + totali se postavljaju NAKON renderiranja lista, iz sumE (= prikazani UKUPNO
    //   lista), a NE iz mjes (puna preciznost). Tako donos sljedeće situacije i totali TOČNO odgovaraju onome
    //   što list pokazuje — nema centa razlike u lancu situacija. (vidi kraj ove iteracije)

    // ── render lista (s paginacijom) ──
    const bazaIme = (st.redni_broj || ('Stavka ' + (sIdx + 1))).toString().replace(/\.+$/, '');
    // * v1188: `PAGE_H` (fiksnih 54 redaka po stranici) je NAPUSTEN — stranica sada zavrsava ondje
    //   gdje zavrsi sadrzaj + podnozje. Zadrzan samo kao zapis staroga modela; ne koristi se.
    const PAGE_H = 54;  // (povijesno) fiksna visina stranice u redovima
    let base = 0, ws = noviList(bazaIme), raspisNaStr = 0, kumNaList = prevUk;
    // ⭐ v492 (Ivan): list stavke 7 stupaca — umetnut široki „Izračun" (izraz po geometriji); Ukupna kol = rezultat, Jed. cijena prazna u raspisu
    // ⭐ v1181 (Ivan): širi stupac „Izračun" (raspis „(1,2+3*2+1) = 8,20 × …" mora stati), uži „Opis".
