      // ⭐ v493 (Ivan): C(3)=Ugovorena kol., D(4)=Jed. cijena, E(5)=Mjes.kol (link F lista), F(6)=Mjesečno €(=E*cij), G(7)=Kum.kol (link G lista), H(8)=Kumulativ €(=G*cij), I(9)=Napredak (bar)
      const refE = _xref(info, 'F'), refF = _xref(info, 'G');   // ⭐ v492: list stavke pomaknut +1 (Izračun) → UKUPNO mjesečno=F, kumulativ=G
      // ⭐ v581 (Ivan): STUPAC JM (C=3) izmedu opisa i kolicine. Numericki pomaknuti +1: ugK=D(4), cij=E(5), mjesV=F(6), mjesecno EUR=G(7), kumV=H(8), kumulativ EUR=I(9). Formule prate: mjesecno=F*cij, kumulativ=H*cij.
      const Cjm = wsR.getCell(rr, 3); Cjm.value = (st2.jm || '').toString() || '—'; Cjm.font = { size: 8, color: { argb: st2.jm ? 'FF0F172A' : SUBC } }; Cjm.alignment = { horizontal: 'center', vertical: 'top' }; Cjm.border = { bottom: { style: 'hair', color: { argb: 'FFE2E8F0' } } };
      const Cug = wsR.getCell(rr, 4); Cug.value = ugK > 0 ? Math.round(ugK * 1000) / 1000 : '—'; if (ugK > 0) Cug.numFmt = '#,##0.00';   // ⭐ v493: ugovorena količina
