      const Hk = wsR.getCell(rr, 9); if (cij > 0) { Hk.value = { formula: 'H' + rr + '*' + _fnum(cij), result: Math.round(kumV * cij * 100) / 100 }; Hk.numFmt = eurFmt; } else Hk.value = '—';
      [Cug, Dcij, E, Fm, G, Hk].forEach((c, i) => { c.font = { size: 8, bold: i === 5, color: { argb: i === 5 ? GRN : (i === 3 ? NAVY2 : 'FF0F172A') } };   // ⭐ v545: manji font brojeva (portrait)
        c.alignment = { horizontal: 'right', vertical: 'top' }; c.border = { bottom: { style: 'hair', color: { argb: 'FFE2E8F0' } } }; });
