// Detektira proizvođača iz naziva. Vraća catalog entry ili null.
function detectInsulationBrand(naziv) {
  const n = (naziv || '').toLowerCase();
  if (!n) return null;
  for (const [key, info] of Object.entries(INSULATION_CATALOG)) {
    if (info.aliases.some(a => n.includes(a))) return { key, ...info };
  }
  return null;
}

